INSERT INTO public.teachings (arabic, english, source, domain)
VALUES
  ('بِرُّ الوالِدَيْنِ أكْبَرُ فَريضَة.', 'Being good to parents is the greatest [and most important] duty.', 'Ghurar al-Hikam, Parents §1', 'family'),
  ('بِرُّوا آباءَكُمْ يَبـََرَّكُمْ أبْناؤُكُمْ.', 'Be good to your parents and your children will be good to you.', 'Ghurar al-Hikam, Parents §2', 'family'),
  ('مَنْ بَرَّ والِدَيْهِ بَرَّهُ وَلَدُهُ.', 'Whoever is good to his parents, his child will be good to him.', 'Ghurar al-Hikam, Parents §3', 'family'),
  ('مَوْتُ الوالِدِ قاصِمَةُ الظَّهْرِ.', 'The death of a father breaks one’s back.', 'Ghurar al-Hikam, Parents §4', 'family'),
  ('مَنِ اسْتَنْكَفَ مِنْ أبَوَيهِ فَقَدْ خالَفَ الرُّشْدَ.', 'One who scorns his parents has diverged from the right path.', 'Ghurar al-Hikam, Parents §5', 'family'),
  ('مَوَدَّةُ الآباءِ نَسَبٌ بَيْنَ الأبناءِ.', 'The affection of parents is [the basis of] the relationship between siblings.', 'Ghurar al-Hikam, Parents §6', 'family'),
  ('مِسْكينٌ اِبْنُ آدَمَ، مَكْتُومُ الأجَلِ، مَكْنُونُ العِلَلِ، مَحفُوظُ العَمَلِ، تُؤْلِمُهُ البَقَّةُ، وتُنْتِنُهُ العَرَقَةُ، وتَقْتُلُهُ الشَّرْقَةُ.', 'How wretched the son of Adam is! His death is hidden, his ailments concealed, his every action recorded, harmed by the bite of a mosquito, made malodorous by perspiration and caused to die by [something as simple as] choking.', 'Ghurar al-Hikam, The Son Of Adam (The Human Being) §1', 'mortality'),
  ('وَيْحَ ابْنِ آدَمَ ما أغْفَلَهُ، وَعَنْ رُشدِهِ ما أذْهَلَهُ.', 'Woe to the son of Adam! How heedless and negligent of his salvation he is!', 'Ghurar al-Hikam, The Son Of Adam (The Human Being) §2', 'mortality'),
  ('وَيْحَ ابْنِ آدَمَ، أسيرُ الجُوعِ، صَريعُ الشَّبَعِ، غَرَضُ الآفاتِ، خَليفَةُ', 'Woe to the son of Adam! A prisoner of hunger, prone to overeating, a target of calamities and a successor of the dead.', 'Ghurar al-Hikam, The Son Of Adam (The Human Being) §3', 'mortality'),
  ('رُبَّ ذي اُبَّهـَة أحْقَرُ مِنْ كُلِّ حَقير.', 'It is possible that a person who possesses [apparent] grandeur is actually the lowliest of the low.', 'Ghurar al-Hikam, Grandeur §1', 'wisdom'),
  ('اَلإيثارُ فَضيلَةٌ، اَلإحْتِكارُ رَذيلَةٌ.', 'Self-sacrifice is a virtue, hoarding [wealth] is a vice.', 'Ghurar al-Hikam, Self-Sacrifice §1', 'generosity'),
  ('الإيثارُ أشرَفُ الإحْسانِ.', 'Self-sacrifice is the noblest benevolence.', 'Ghurar al-Hikam, Self-Sacrifice §2', 'generosity'),
  ('الإيثارُ شيمَةُ الأبْرارِ.', 'Self-sacrifice is a trait of the virtuous.', 'Ghurar al-Hikam, Self-Sacrifice §3', 'generosity'),
  ('الإيثارُ غايَةُ الإحْسانِ.', 'Self-sacrifice is the highest degree of benevolence.', 'Ghurar al-Hikam, Self-Sacrifice §4', 'generosity'),
  ('الإيثارُ أشرَفُ الكَرَمِ.', 'Self-sacrifice is the noblest munificence.', 'Ghurar al-Hikam, Self-Sacrifice §5', 'generosity'),
  ('الإيثارُ أعلَى الإحْسانِ.', 'Self-sacrifice is the highest form of benevolence.', 'Ghurar al-Hikam, Self-Sacrifice §6', 'generosity'),
  ('الإيثارُ أعلَى المَكارِمِ.', 'Self-sacrifice is the loftiest of noble traits.', 'Ghurar al-Hikam, Self-Sacrifice §7', 'generosity'),
  ('الإيثارُ أفضَلُ عِبادَة، وأجَلُّ(أحْسَنُ) سيادَة.', 'Self-sacrifice is the greatest worship and the most sublime eminence.', 'Ghurar al-Hikam, Self-Sacrifice §8', 'generosity'),
  ('الإيثارُ أعْلى مَراتِبِ الكَرَمِ، وأفْضَلُ الشِّيَمِ.', 'Self-sacrifice is the highest level of munificence and the most excellent quality.', 'Ghurar al-Hikam, Self-Sacrifice §9', 'generosity'),
  ('الإيثارُ أحْسَنُ الإحْسانِ وأعْلى مَراتِبِ الإيمانِ.', 'Self-sacrifice is the best [form of] benevolence and the highest stage of faith.', 'Ghurar al-Hikam, Self-Sacrifice §10', 'generosity'),
  ('اَلأجلُ مَحْتُومٌ، والرِّزْقُ مَقْسُومٌ، فلا يَغُمَّنَّ أحَدَكُمْ إبطاؤُهُ، فإنَّ الحِرْصَ لايُقَدِّمُهُ، والعَفافُ لا يُؤَخِّرُهُ، والمُؤمِنُ بالتَّحَمُّلِ(بِالتَّجَمُّلِ (خَليقٌ.', 'The appointed time of death is [already] determined and sustenance is [already] apportioned, so let not any of you grieve its reduction; for verily greed does not expedite it and self-restraint does not delay it, and it behoves a believer to be patient.', 'Ghurar al-Hikam, The Appointed Time Of Death §1', 'mortality'),
  ('أصْدَقُ شَيْ ء اَلأجَلُ.', 'The truest thing is death.', 'Ghurar al-Hikam, The Appointed Time Of Death §2', 'mortality'),
  ('أقْرَبُ شَيْ ء الأجَلُ.', 'The nearest thing is death.', 'Ghurar al-Hikam, The Appointed Time Of Death §3', 'mortality'),
  ('صِدقُ الأجلِ يُفْصِحُ (يَفْضَحُ) كِذْبَ الأمَلِ.', 'The reality of death exposes the lie of [false] aspiration.', 'Ghurar al-Hikam, The Appointed Time Of Death §4', 'mortality'),
  ('في كُلِّ لَحْظَة أجَلٌ.', 'At every moment there is death.', 'Ghurar al-Hikam, The Appointed Time Of Death §5', 'mortality'),
  ('قَدْ غابَ عَنْ قُلُوبِكُمْ ذِكرُ الآجالِ، وَحَضَرَتْكُمْ كَواذِبُ الآمالِ.', 'The remembrance of [the times of] death has disappeared from your hearts and has been replaced by false hopes and aspirations.', 'Ghurar al-Hikam, The Appointed Time Of Death §6', 'mortality'),
  ('قَدْ ذَهبَ عَنْ قُلُوبِكُمْ صِدْقُ الأجَلِ، وغَلَبَكُم غُرُورُ الأملِ.', 'Your hearts have forgotten the reality of death and you have been overcome by deception of [false] hope.', 'Ghurar al-Hikam, The Appointed Time Of Death §7', 'mortality'),
  ('مَنْ راقَبَ أجَلَهُ إغْتَنَمَ مَهَلَهُ.', 'The one who takes death into consideration values his time.', 'Ghurar al-Hikam, The Appointed Time Of Death §8', 'mortality'),
  ('مَنْ دَنى مِنْهُ أجَلُهُ لَمْ تُعِنْهُ (لم تُغْنِهِ) حِيَلُهُ.', 'One whose death draws near to him cannot be saved [from it] by his efforts.', 'Ghurar al-Hikam, The Appointed Time Of Death §9', 'mortality'),
  ('مِنَ الآجالِ إنْقِضاءُ السَّاعاتِ.', 'The passing of time draws one towards death.', 'Ghurar al-Hikam, The Appointed Time Of Death §10', 'mortality'),
  ('اَلآخِرةُ فَوزُ السُّعَداءِ.', 'The Hereafter is the victory of the felicitous.', 'Ghurar al-Hikam, The Hereafter §1', 'mortality'),
  ('اِشتِغالُكَ بإصْلاحِ مَعادِكَ يُنْجيكَ مِنْ عَذابِ النَّارِ.', 'Occupying yourself with improving your Hereafter will save you from the chastisement of hellfire.', 'Ghurar al-Hikam, The Hereafter §2', 'mortality'),
  ('الرَّابِحُ مَنْ باعَ العاجِلَةَ بِالآجِلَةِ.', 'The [true] winner is one who has sold this transitory life for the [eternal] Hereafter.', 'Ghurar al-Hikam, The Hereafter §3', 'mortality'),
  ('اَلمالُ وَالْبَنُونَ زينَةُ الحَيوةِ الدُّنيا، والعَمَلُ الصَّالِحُ حَرْثُ الآخِرَةِ.', 'Wealth and children are the adornment of the life of this world whereas good deeds are the tillage of the Hereafter.', 'Ghurar al-Hikam, The Hereafter §4', 'mortality'),
  ('أحْوالُ الدُّنيا تَتْبَعُ الإتِّفاقَ وأحْوالُ الآخرةِ تَتْبَعُ الاِسْتِحْقاقَ.', 'The conditions in this world are based on convention whereas the conditions in the Hereafter are based on merit.', 'Ghurar al-Hikam, The Hereafter §5', 'mortality'),
  ('إنّ أمامَكَ عَقَبَةً كَؤُوداً، اَلمُخِفُّ فيها أحْسَنُ حالاً مِنَ المُثْقِلِ، والمُبْطِئُ عَلَيها أقْبَحُ أمْراً مِنَ المُسـْرِعِ، إنّ مَهْبِطَها بِكَ لامُحالَةَ على جَنَّة أوْ نار.', 'Surely in front of you is a difficult place of ascension in which one whose weight is lighter is in a better position than the one whose weight is heavier, and the one who moves slowly is worse off than the one who moves swiftly. Verily its landing will lead you to either Paradise or hell.', 'Ghurar al-Hikam, The Hereafter §6', 'mortality'),
  ('إنَّ الغايَةَ القيامَةُ، وكَفى بِذلِكَ واعِظاً لِـمَنْ عَقَلَ، ومُعْتَبَراً لِمَنْ جَهِلَ، وبَعدَ ذلك ما تَعْلَمُونَ مِنْ هَوْلِ الْمُطَّلَعِ، وَرَوْعاتِ الفَزَعِ، واسْتِكاكِ الأسماعِ، وَاخْتِلافِ الأضلاعِ، وضيقِ الأرماسِ، وَشِدَّةِ الأبلاسِ.', 'Verily the final destination is al-Qiyāmah and this is enough of an admonition for the one who reasons, and [enough of] a warning for the one who is unaware; and after that - what you know of the torment of the Day of Judgment and the frightening terror, and the deafening of the ears, and the turning of the ribs, and the narrowness of the grave, and the intensity of sadness and heavy-heartedness.', 'Ghurar al-Hikam, The Hereafter §7', 'mortality'),
  ('إنْ رَغِبْتُم في الفَوزِ وكَرامَةِ الآخِرَةِ فَخُذُوا في الفَناءِ لِلْبَقاءِ.', 'If you desire success and honor in the Hereafter, then take from the perishing [life of this world] for the everlasting [life of the Hereafter].', 'Ghurar al-Hikam, The Hereafter §8', 'mortality'),
  ('إنَّكَ في سَبيلِ مَنْ كانَ قَبْلَكَ، فَاجْعَلْ جِدَّكَ لآخرَتِكَ، ولا تَكْتَـرِثْ بِعَمَلِ الدُّنيا.', 'Verily you are following the path of those who came before you, so put your efforts in [working for] your Hereafter and do not care for worldly gain.', 'Ghurar al-Hikam, The Hereafter §9', 'mortality'),
  ('إنّك مَخْلُوقٌ لِلآخِرَةِ فَاعْمَل لَها.', 'Verily you have been created for the Hereafter, so work for it!', 'Ghurar al-Hikam, The Hereafter §10', 'mortality'),
  ('نالَ المُنى مَنْ عَمِلَ لِدارِ البَقاءِ.', 'He who works for his Eternal Abode obtains what he desires.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §47', 'mortality'),
  ('لاتبيعُوا الآخرَةَ بالدُّنيا، ولاتَسْتَبْدِلُوا الفَناءَ بِالبَقاءِ.', 'Do not sell the Hereafter for this world and do not exchange the everlasting for the evanescent.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §48', 'mortality'),
  ('لايَشْغَلَنَّكَ عَنِ العَمَلِ لِلآخِرَةِ شُغلٌ فإنَّ المُدَّةَ قَصيرَةٌ.', 'Never let anything occupy you from working for the Hereafter for indeed the time is short.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §49', 'mortality'),
  ('لاتَجْتَمِعُ الآخِرَةُ وَالدُّنيا.', 'The Hereafter and this world do not come together.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §50', 'mortality'),
  ('لاتَجتَمِعُ الفَناءُ والبَقاءُ.', 'The perishing and the permanent do not go together.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §51', 'mortality'),
  ('لايُدْرِكُ أحَدٌ ما يُريدُ مِنَ الآخِرَةِ إلاّ بِتَرْكِ ما يَشتَهي مِنَ الدُّنيا.', 'No one attains what he wishes for in the Hereafter except by abstaining from that which he desires in this world.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §52', 'mortality'),
  ('يَنبَغي لِمَنْ أيْقَنَ بِبَقاءِ الآخِرَةِ ودَوامِها أنْ يَعْمَلَ لَها.', 'It behoves one who is certain about the everlastingness and permanence of the Hereafter to work for it.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §53', 'mortality'),
  ('لايَتْرُكُ النَّاسُ شَيْئاً مِنْ دُنياهُمْ لإصلاحِ آخِرَتِهِمْ إلاّ عَوَّضَهُمُ اللّهُ سُبْحانَهُ خَيْراً مِنْهُ.', 'People do not abstain from anything of their worldly life for the sake of improving their Hereafter but that Allah, the Glorified, recompenses them with what is better than it.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §54', 'mortality'),
  ('إرْغَبُوا فيما وَعَدَاللّهُ المُتَّقينَ، فإنّ أصْدَقَ الوَعْدِ ميعادُهُ.', 'Aspire for what Allah has promised the God-wary, for surely the truest promises are His promises.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §55', 'mortality'),
  ('إنَّ غَداً مِنَ اليَوْمِ قَريبٌ، يَذْهَبُ اليَومُ بِما فيهِ، ويَأتي الْغَدُ لاحِقاً بِهِ.', 'Verily tomorrow is close to today. This day will pass with what is in it and tomorrow will come [soon] following it.', 'Ghurar al-Hikam, of] the Hereafter by exerting his greatest effort. §56', 'mortality'),
  ('اَلإخْوانُ أفْضَلُ العُدَدِ.', 'Brothers are the best of assets [in times of hardship].', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §1', 'wisdom'),
  ('اَلمُعينُ عَلَى الطَّاعَةِ خَيرُ الأصحابِ.', 'The one who assists [you] in obeying [Allah] is the best companion.', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §2', 'wisdom'),
  ('اَلصَّديقُ مَنْ صَدَقَ غَيبُهُ(غَيْبَتُهُ).', 'A Friend is one whose friendship is true [even] in absence.', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §3', 'wisdom'),
  ('اَلفَقْدُ المُمْرِضُ (المُرْمِضُ) فَقْدُ الأحبابِ.', 'The loss that causes illness (or burns [the heart]) is the loss of loved ones.', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §4', 'wisdom'),
  ('اَلصَّاحِبُ كالرُّقعَةِ فَاتَّخِذْهُ مُشاكِلاً.', 'A companion is like a patch [of cloth], so take one that matches [yours].', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §5', 'wisdom'),
  ('الرَّفيقُ كالصَّديقِ فَاخْتَرَهُ مُوافِقاً.', 'An associate is like a friend, so choose one who is suitable.', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §6', 'wisdom'),
  ('اَلْغَريبُ مَنْ لَيْسَ لَهُ حَبيبٌ.', 'A stranger is one who does not have a [close] friend.', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §7', 'wisdom'),
  ('إخْوانُ الدّين أبْقى مَوَدَّةً.', 'Brothers in faith have lasting affection [for each other].', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §8', 'wisdom'),
  ('أخٌ تَسْتَفيدُهُ خَيْرٌ مِنْ أخ تَسْتَزيدُهُ.', 'The brother whom you benefit from is better than the brother [for] whom you increase [benefit].', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §9', 'wisdom'),
  ('اِسْتِفْسادُ الصَّديقِ مِنْ عَدَمِ التَّوفيقِ.', 'Seeking the destruction of a friend stems from lack of conciliation.', 'Ghurar al-Hikam, The Brother, The Friend, The Associate And The Companion §10', 'wisdom'),
  ('خَيرُ الإخْوانِ مَنْ لَمْ تَكُنْ على الدُّنيا اُخُوَّتُهُ.', 'The best brother is one whose brotherhood is not based on worldly gain.', 'Ghurar al-Hikam, Deceitful. §15', 'wisdom'),
  ('خَيرُ الإخوانِ مَنْ كانَتْ في اللّهِ مَوَّدَتُه.', 'The best brother is one whose affection is for the sake of Allah.', 'Ghurar al-Hikam, Deceitful. §16', 'wisdom'),
  ('خَيرُ الإخوانِ مَنْ إذا فَقَدْتَهُ لَـمْ تُحِبَّ البَقاءَ بَعدَهُ.', 'The best brother is one after whose loss you would not like to remain [alive].', 'Ghurar al-Hikam, Deceitful. §17', 'wisdom'),
  ('خيرُ إخوانِكَ مَنْ سارَعَ إلَى الخَيرِ وجَذَبَكَ إليه، وأمَرَكَ بِالبِرِّ وَأعانَكَ علَيْهِ.', 'The best of your brothers is one who rushes towards good and pulls you towards it, and enjoins you to righteousness and assists you in it.', 'Ghurar al-Hikam, Deceitful. §18', 'wisdom'),
  ('خَيرُ إخوانِكَ مَنْ دَعاكَ إلى صِدْقِ المَقالِ بِصِدقِ مَقالِهِ ونَدَبَكَ إلى أفْضلِ الأعمالِ بِحُسنِ أعمالهِ.', 'The best of your brothers is the one who exhorts you to speak the truth by his own veracity and compels you to perform the best deeds by his own good actions.', 'Ghurar al-Hikam, Deceitful. §19', 'wisdom'),
  ('خَيرُ إخوانِكَ مَنْ دَلَّكَ على هُدىً، وألبَسَكَ(أكْسَبَكَ) تُقىً، وَصَدَّكَ عَنْ إتّباعِ هَوىً.', 'The best of your brothers is the one who shows you the path of guidance, makes you acquire piety and prevents you from following your lowly desires.', 'Ghurar al-Hikam, Deceitful. §20', 'wisdom'),
  ('خَيرُ إخوانِكَ مَنْ واساكَ.', 'The best of your brothers is the one who assists you financially [in your time of need].', 'Ghurar al-Hikam, Deceitful. §21', 'wisdom'),
  ('رُبَّ أخ لَمْ يَلِدْهُ اُمُّكَ.', 'Many a brother has not been born to your mother.', 'Ghurar al-Hikam, Deceitful. §22', 'wisdom'),
  ('صَديقُ الجاهلِ مَتْعُوبٌ مَنكُوبٌ.', 'The friend of an ignorant person is troubled and afflicted.', 'Ghurar al-Hikam, Deceitful. §23', 'wisdom'),
  ('صاحِبِ الإخوانَ بالإحسانِ، وتَغَمَّدْ ذُنُوبَهُم بالغُفْرانِ.', 'Accompany your brothers with kindness and cover their offences with forgiveness.', 'Ghurar al-Hikam, Deceitful. §24', 'wisdom'),
  ('صُحبَةُ الأشرارِ تُوجبُ سُوءَ الظَّنِّ الأخيارِ.', 'Association with the wicked leads one to have negative thoughts about the righteous.', 'Ghurar al-Hikam, Perform evil]. §34', 'wisdom'),
  ('عَلَيكَ بِمُقارَنَةِ ذِي العَقلِ والدِّينِ فإنَّهُ خَيرُ الأصحابِ.', 'You should accompany the one who is intelligent and devout, for surely he is the best of companions.', 'Ghurar al-Hikam, Perform evil]. §35', 'wisdom'),
  ('عَليكَ بإخْوانِ الصَّفا فإنّهُمْ زينَةٌ فِي الرَّخاءِ وعَونٌ فِي البلاءِ.', 'You should keep ties with brethren of purity, for they are an embellishment in times of ease and a support in [times of] tribulation.', 'Ghurar al-Hikam, Perform evil]. §36', 'wisdom'),
  ('عَلَيكَ بِمُواخاةِ مَنْ حَذَّرَكَ وَنهاكَ فإنّهُ يُنجِدُكَ ويُرشِدُكَ.', 'You should build a bond of brotherhood with the one who cautions and forbids you [from doing evil] for verily he is aiding and guiding you.', 'Ghurar al-Hikam, Perform evil]. §37', 'wisdom'),
  ('مَنّ تَألّفَ النَّاسَ أحَبُّوهُ.', 'One who is amiable towards people is loved by them.', 'Ghurar al-Hikam, Perform evil]. §38', 'wisdom'),
  ('الإصْطِحابُ قليلٌ.', 'The companionship [in this world] is short.', 'Ghurar al-Hikam, Perform evil]. §39', 'wisdom'),
  ('الصَّديقُ أقْرَبُ الأقارِبِ.', 'A friend is the closest of relations.', 'Ghurar al-Hikam, Perform evil]. §40', 'wisdom'),
  ('إنّما سُمِّيَ الصَّديقُ صديقاً لأنّه يَصْدُقُكَ في نَفْسِكَ ومَعائبِكَ، فَمَنْ فَعَلَ ذلك فاستَنِمْ إليْهِ فإنَّهُ الصَّديقُ.', 'The friend has been named ṣ adīq because he is truthful to you about your nature and faults, so have confidence in one who does this for he is your [true] friend.', 'Ghurar al-Hikam, Perform evil]. §41', 'wisdom'),
  ('إنَّما سُمِّىَ الرَّفيقُ رَفيقاً لأنَّه يَرفَقُكَ على إصلاحِ دينكَ فَمنْ أعانَكَ على صَلاحِ دينكَ فَهُوَ الرَّفيقُ الشَّفيقُ.', 'The comrade has been named rafīq because he encourages you to improve your religion; so whoever assists you to improve your faith, then he is a concerned comrade.', 'Ghurar al-Hikam, Perform evil]. §42', 'wisdom'),
  ('إذا طالَّتِ الصُّحْبَةُ تأكَّدَتِ الحُرمَةُ.', 'As the companionship prolongs, the [mutual] respect is affirmed.', 'Ghurar al-Hikam, Perform evil]. §43', 'wisdom'),
  ('تَحَبَّبْ إلى خَليلِكَ يُحْبِبْكَ، وأكرِمْهُ يُكْرِمْكَ وآثِرْهُ على نَفْسِكَ يُؤثِرْكَ على نَفسِهِ وأهْلِهِ.', 'Be warm-hearted to your friend and he will be warm-hearted towards you, honour him and he will honour you, give him preference over yourself and he will give you preference over himself and his family.', 'Ghurar al-Hikam, in times of distress). §55', 'purpose'),
  ('جَليسُ الخَيرِ نِعْمَةٌ.', 'A good companion is a blessing.', 'Ghurar al-Hikam, in times of distress). §56', 'purpose'),
  ('جَليسُ الشّرِّ نِقْمَةٌ.', 'An evil companion is a curse.', 'Ghurar al-Hikam, in times of distress). §57', 'purpose'),
  ('جالِسْ أهْلَ الوَرَعِ والحِكْمَةِ، وأكثِرْ مُناقَشَتَهُمْ، فإنَّكَ إنْ كُنتَ جاهلاً عَلَّمُوكَ، وإنْ كُنْتَ عالِماً إزدَدْتَ عِلماً.', 'Sit in the company of the people of piety and wisdom and increase your discourse with them, for if you are ignorant they will enlighten you and if you are knowledgeable, you will increase your knowledge.', 'Ghurar al-Hikam, in times of distress). §58', 'purpose'),
  ('حُسنُ الصُّحْبَةِ يَزيدُ في مَحَبَّةِ القُلُوبِ.', 'Good companionship increases the affection of the hearts.', 'Ghurar al-Hikam, in times of distress). §59', 'purpose'),
  ('حَسَدُ الصَّديقِ مِنْ سُقْمِ المَوَدَّةِ.', 'The jealousy of a friend is an ailment of [his] friendship.', 'Ghurar al-Hikam, in times of distress). §60', 'purpose'),
  ('خَيْرُ الاِختيارِ صُحبَةُ الأخيارِ.', 'The best choice is accompanying the righteous.', 'Ghurar al-Hikam, in times of distress). §61', 'purpose'),
  ('خيرُ مَنْ صاحَبْتَ ذَوُوا العِلْمِ والحِلمِ.', 'The best of those whom you can accompany are the people of knowledge and insight.', 'Ghurar al-Hikam, in times of distress). §62', 'purpose'),
  ('خَيْرُ مَنْ صَحِبْتَهُ مَنْ لايُحوِجُكَ إلى حاكِم بَينَكَ وبيْنَهُ.', 'The best person you can accompany is the one who does not compel you to seek adjudication between yourself and him.', 'Ghurar al-Hikam, in times of distress). §63', 'purpose'),
  ('خَيرُ مَنْ صَحِبْتَ مَنْ وَلَّهَكَ بالاُخرى، وزَهَّدَكَ في الدُّنيا، وأعانَكَ على طاعةِ المَولى.', 'The best companion is one who makes you infatuated with the Hereafter, urges you to renounce worldly pleasures and assists you in obeying your Lord.', 'Ghurar al-Hikam, in times of distress). §64', 'purpose'),
  ('اَلإخْوانُ في اللّه تعالى تَدُومُ مَوَّدَتُهُمْ لِدَوامِ سَبَبِها.', 'One who takes a brother without evaluation will be forced by necessity to associate with the wicked.', 'Ghurar al-Hikam, the depraved. §234', 'wisdom'),
  ('إخوانُ الصِّدقِ زينَةٌ في السَّرّاءِ وعُدَّةٌ في الضَّرّاءِ.', 'The amity between those who are brothers for the sake of Allah endures because of its firm foundation.', 'Ghurar al-Hikam, the depraved. §235', 'wisdom'),
  ('اَلأخُ المُكْتَسَبُ في اللّهِ أقْرَبُ الأقْرِباءِ وأحَمُّ مِنَ الأُمَّهاتِ والآباءِ.', 'True brotherhood is an embellishment in times of ease and a provision in times of difficulty.', 'Ghurar al-Hikam, the depraved. §236', 'wisdom'),
  ('أخُوكَ في اللّهِ مَنْ هَداكَ إلى رَشاد، ونَهاكَ عَنْ فَساد، وأعانَكَ إلى إصلاحِ معاد.', 'The brother acquired for the sake of Allah is the nearest of relations – even closer than mothers and fathers.', 'Ghurar al-Hikam, the depraved. §237', 'wisdom'),
  ('أخُوكَ الصَّديقُ مَنْ وَقاكَ بِنَفْسِهِ، وآثَرَكَ على مالِهِ ووَلدِهِ، وَعِرْسِهِ.', 'Your brother for the sake of Allah is one who guides you towards rectitude, forbids you from corruption and assists you to improve your Hereafter.', 'Ghurar al-Hikam, the depraved. §238', 'wisdom'),
  ('قَليلٌمِنَ الإخْوانِ مَنْ يُنْصِفُ.', 'Your true friend and brother is the one who protects you with his life, and prefers you over his wealth, his children and his spouse.', 'Ghurar al-Hikam, the depraved. §239', 'wisdom'),
  ('قَرينُ السُّوءِ شَـرُّ قَرين وداءُ اللُّؤْمِ داءٌ دفينٌ.', 'It is only a few of the brothers who are fair.', 'Ghurar al-Hikam, the depraved. §240', 'wisdom'),
  ('قارِنْ أهلَ الخَيرِ تَكُنْ مِنْهُمْ، وبايِنْ أهْلَ الشَّـرِّ تَبِنْ عَنْهُمْ.', 'An evil companion is the worst of companions; and the disease of ignobility is a concealed disease.', 'Ghurar al-Hikam, the depraved. §241', 'wisdom'),
  ('قَدِّمِ الاختبارَ فِي اتِّخاذِ الإخوانِ، فإنَّ الاختِبارَ مِعيارٌ يَفْرُقُ بَيْنَ الأخيارِ والأشرارِ.', 'Accompany the virtuous and you will become one of them; separate yourself from the evil people and you will be dissociated from them.', 'Ghurar al-Hikam, the depraved. §242', 'wisdom'),
  ('مَنْ رَفِقَ بِمُصاحِبِهِ وافَقَهُ، ومَنْ أعنَفَ بِهِ أخْرَجَهُ وفارَقَهُ.', 'Be sure to investigate before taking anyone as your brother, for assessment is the gauge that distinguishes the virtuous from the wicked.', 'Ghurar al-Hikam, the depraved. §243', 'wisdom'),
  ('اَلأدَبُ أحَدُ الْحَسَبَيْنِ.', 'Good etiquette is one of the two distinguishing merits.', 'Ghurar al-Hikam, Good Etiquette §1', 'character'),
  ('اَلأدبُ في الإنْسانِ كَشَجَرَة أصْلُها العَقلُ.', 'Good etiquette in a person is like a tree whose roots are the intellect.', 'Ghurar al-Hikam, Good Etiquette §2', 'character'),
  ('أشرفُ حَسَب حُسْنُ الأدبِ.', 'The noblest of personal merits is good etiquette.', 'Ghurar al-Hikam, Good Etiquette §3', 'character'),
  ('أفْضلُ الأدبِ حِفْظُ المُرُوءَةِ.', 'The best etiquette is preserving one’s magnanimity.', 'Ghurar al-Hikam, Good Etiquette §4', 'character'),
  ('أفضلُ الأدبِ ما بَدَأْتَ بِهِ نَفْسَكَ.', 'The best etiquette is that [in] which you start with yourself.', 'Ghurar al-Hikam, Good Etiquette §5', 'character'),
  ('أفضلُ الأدبِ أنْ يَقِفَ الإنسانُ عِندَ حَدِّهِ ولايَتَعدَّى قَدْرَهُ.', 'The best etiquette is for a person to stay within his limits and not go beyond his rank.', 'Ghurar al-Hikam, Good Etiquette §6', 'character'),
  ('أحسنُ الآدابِ ما كَفَّكَ عَنِ المَحارِمِ.', 'The best of etiquettes is that which stops you from what is forbidden.', 'Ghurar al-Hikam, Good Etiquette §7', 'character'),
  ('أكرَمُ حَسَب حُسْنُ الأدبِ.', 'The noblest merit is good etiquette.', 'Ghurar al-Hikam, Good Etiquette §8', 'character'),
  ('إنَّ بِذَوي العُقُولِ مِنَ الحاجَةِ إلى الأدبِ، كَما يَظْمَأُ الزَّرْعُ إلَى المَطَرِ.', 'The people of intellect are in need of good etiquette just as the plants thirst for rain.', 'Ghurar al-Hikam, Good Etiquette §9', 'character'),
  ('إنَّ النَّاس إلى صالحِ الأدبِ أحْوَجُ مِنْهُمْ إلى الفِضَّةِ والذَّهبِ.', 'People are more in need of good etiquette than of silver and gold.', 'Ghurar al-Hikam, Good Etiquette §10', 'character'),
  ('اَلأذى يَجْلِبُ القِلى.', 'Harm breeds hatred.', 'Ghurar al-Hikam, Harm And Preventing Harm §1', 'wisdom'),
  ('مَنْ كَفَّ أذاهُ لَمْ يُعانِدْهُ أحدٌ.', 'One who prevents himself from harming [others] will not be opposed [or hated] by anyone.', 'Ghurar al-Hikam, Harm And Preventing Harm §2', 'wisdom'),
  ('مَنْعُ أذاكَ يُصلِحُ لَكَ قُلُوبُ عِداكَ.', 'Preventing yourself from harming [others] reforms the hearts of your enemies towards you.', 'Ghurar al-Hikam, Harm And Preventing Harm §3', 'wisdom'),
  ('خَرَقَ عِلْمُ اللّهِ سُبْحانَهُ باطِنَ غَيْبِ السُّتََراتِ، وأحاطَ بِغُمُوضِ عَقائدِ السَّريراتِ.', 'The knowledge of Allah, the Glorified, tore through the veils of the unseen and encompassed the darkness of inner-beliefs.', 'Ghurar al-Hikam, Allah and His Attributes §1', 'wisdom'),
  ('كُلُّ مُسَمًّى بِالوَحْدَةِ غَيرُ اللّهِ سُبْحانَهُ قَليلٌ، وكُلُّ عزيز غَيرُهُ ذَليلٌ، وَكُلُّ قَويّ غَيرُهُ ضعيفٌ، وَكُلُّ مالِك غَيرُهُ مَمْلُوكٌ، وكُلُّ عالِم غَيرُهُ مُتَعَلِّمٌ، وَكُلُّ قادِر غيرُهُ يَقْدِرُ ويَعْجِزُ.', 'Everyone who is called ‘one’ other than Allah, the Glorified, is little; and every honoured one other than Him is inferior; and every strong one other than Him is weak; and every master other than Him is a slave; and every knower other than Him is a learner; and every capable one other than Him is sometimes able and other times unable.', 'Ghurar al-Hikam, Allah and His Attributes §2', 'wisdom'),
  ('كُلُّ باطِن عندَ اللّه جَلّتْ آلاؤُهُ ظاهرٌ.', 'Every hidden thing is apparent for Allah, exalted are His bounties.', 'Ghurar al-Hikam, Allah and His Attributes §3', 'wisdom'),
  ('كُلُّ سِرّ عندَ اللّهِ عَلانِيَةٌ.', 'Every secret is manifest for Allah.', 'Ghurar al-Hikam, Allah and His Attributes §4', 'wisdom'),
  ('مَنْ تَفَكَّرَ في ذاتِ اللّهِ اَلْحَدَ(تَزَنْدَقَ)', 'Whoever contemplates about the essence of Allah, apostatizes.', 'Ghurar al-Hikam, Allah and His Attributes §5', 'wisdom'),
  ('ماكانَ اللّهُ سُبْحانَهُ لِيُضِلَّ أحَداً ولَيسَ اللّهُ بِظلاّّم لِلْعَبيدِ.', 'Allah, the Glorified, does not misguide anyone and Allah is not unjust to the servants.', 'Ghurar al-Hikam, Allah and His Attributes §6', 'wisdom'),
  ('ما أعظَمَ حِلْمَ اللّهِ سُبْحانَهُ عَنْ أهْلِ العِنادِ، وما أكْثَرَ عَفْوَهُ عَنْ مُسرِفي العِبادِ.', 'How great is the clemency of Allah, the Glorified, upon the recalcitrant, and how great is His forgiveness to the extravagant servants.', 'Ghurar al-Hikam, Allah and His Attributes §7', 'wisdom'),
  ('ما أعْظَمَ ألّلهُمَّ ما نَرى مِنْ خَلْقِكَ، وما أصغَرَ عَظيمَهُ في جَنْبِ ما غابَ عنَّا مِنْ قُدْرَتِكَ.', 'Allah, how great is that which we see of your creation, yet how small its greatness is next to what is hidden from us of your might!', 'Ghurar al-Hikam, Allah and His Attributes §8', 'wisdom'),
  ('ما أهْولَ ألّلهُمَّ ما نُشاهِدُهُ مِنْ مَلَكُوتِكَ، وما أحقَرَ ذلِكَ فيما غابَ عنَّا مِنْ عظيمِ سُلْطانِكَ.', 'Allah! How awesome is that which we witness of Your kingdom, yet how negligible is that compared to what is hidden from us of Your grand sovereignty!', 'Ghurar al-Hikam, Allah and His Attributes §9', 'wisdom'),
  ('هُوَ اللّهُ الَّذي تَشْهَدُ لَهُ أعْلامُ الوُجودِ على قَلْبِ ذي الجُحُودِ.', 'He is Allah, the One for whom all signs of existence stand witness over the denying heart.', 'Ghurar al-Hikam, Allah and His Attributes §10', 'wisdom'),
  ('اَلاُُمُورُ بالتَّقديرِ لابِالتَّدبيرِ.', 'Matters come to pass by divine decree, not by [the] planning [of human beings].', 'Ghurar al-Hikam, Matters §1', 'wisdom'),
  ('اِستَدِلَّ على ما لَمْ يَكنْ بِما كانَ فإنَّ الاُمُورَ أشباهٌ.', 'Deduce that which has not happened from that which has transpired, for matters are similar.', 'Ghurar al-Hikam, Matters §2', 'wisdom'),
  ('أنجَحُ الأُمُورِما أحاطَ بِهِ الكِتْمانُ.', 'The most successful matters are those that have been shrouded in secrecy.', 'Ghurar al-Hikam, Matters §3', 'wisdom'),
  ('إنَّ الأُمورَ إذا تَشابَهَتْ اُعْتُبِرَ آخِرُها بِأوَّلِها.', 'Indeed when matters are similar, the latter is judged by the former.', 'Ghurar al-Hikam, Matters §4', 'wisdom'),
  ('الأُمُورُ بِالتَّجرِبَةِ.', 'Matters are [perfected] through experience [and trial].', 'Ghurar al-Hikam, Matters §5', 'wisdom'),
  ('الأُمُورُ أشباهٌ.', 'Matters are similar [to one another].', 'Ghurar al-Hikam, Matters §6', 'wisdom'),
  ('تَذِلُّ الأُمُورُ لِلْمَقاديرِ حتّى يَكُونََ الحَتْفُ (الحِيْفُ) في التَّدبيرِِ.', 'Matters are subservient to destiny until death (or injustice) enters the plan.', 'Ghurar al-Hikam, Matters §7', 'wisdom'),
  ('تَحَرَّ مِنْ أمْرِكَ مايَقُومُ بِهِ عُذرُكَ، وتَثْبُتُ بِِهِ حُجَّتُكَ ويَفيءُ إلَيْكَ بِرُشْدِكَ.', 'Seek in your work the course by which your excuse may be credible, your evidence may be established and your integrity may be restored.', 'Ghurar al-Hikam, Matters §8', 'wisdom'),
  ('خَيْرُ الأُمُورِ ما أسْفَرَ عنِ اليَقينِ.', 'The best matters are those which give rise to certitude.', 'Ghurar al-Hikam, Matters §9', 'wisdom'),
  ('خَيْرُ الأُمُورِ ما أدّى إلَى الخَلاصِ.', 'The best matters are those which lead to deliverance [from hellfire].', 'Ghurar al-Hikam, Matters §10', 'wisdom'),
  ('اَلأمرُ بِالمَعْرُوفِ أفْضلُ أعْمالِ الخَلقِ.', 'Enjoining good and forbidding evil are the best actions of the creation.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §1', 'character'),
  ('اُومُرْ بِالمَعْروفِ تَكُنْ مِنْ أهْلِهِ، وأنْكِرِ المُنْكَرَ بِيَدِكَ ولِسانِكَ، وبايِنْ مِنْ فِعْلِهِ بِجَهْدِكَ.', 'Enjoin good and you will be among the virtuous. Forbid evil with your hand and tongue, and make an effort to disassociate yourself from the one who commits it.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §2', 'character'),
  ('إئتَمِرُوا بِالمَعرُوفِ، وَأْمُرُوا بهِ، وتَناهَوا عَنِ المُنكَرِ وانْهَوا عنهُ.', 'Submit yourselves to good and enjoin it; keep away from evil and forbid it.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §3', 'character'),
  ('إنَّ الأمْرَ بالمَعروفِ والنَّهيَ عنِ المُنْكَرِ لا يُقَرِّبانِ مِنْ أجَل، وَلا يَنْقُصانِ مِنْ رِزق، لكنْ يُضاعِفانِ الثَّوابَ ويُعْظِمانِ الأجْرَ، وأفْضَلُ مِنْهُما كَلِمَةُ عَدْل عِندَ إمام جائر.', 'Verily enjoining good and forbidding evil neither brings death near nor decreases sustenance, rather it multiplies reward and magnifies recompense; and a just word in the presence of an oppressive ruler is [even] better than this.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §4', 'character'),
  ('إنَّ مَنْ رَأى عُدْواناً يُعمَلُ بهِ، ومُنْكَراً يُدعى إلَيهِ، فَأنْكَرَهُ بِقَلْبِهِ فَقَدْ سَلِمَ وبَرِئَ، ومَنْ أنْكَرَهُ بِلِسانِهِ فَقَد اُجِرَ، وهُوَ أفْضَلُ مِنْ صاحِبِهِ، وَمَنْ أنْكَرَهُ بِسَيفِهِ لِتَكُونَ حُجَّةُ اللّهِ العُلْيا، وكَلِمَةُ الظَّالِمينَ السُّفلى، فَذلكَ الَّذي أصابَ سَبيلَ الهُدى، وَقامَ عَلَى الطَّريْقِ، ونَوَّرَ في قَلْبِهِ اليَقينُ.', 'Whoever observes excesses being committed and people being called towards evil, and disapproves of it with his heart, is safe and free [from responsibility for it], and whoever disapproves of it with his tongue will be rewarded for it, and he is in a higher position than the former. But whoever disapproves of it with his sword in order that the proof of Allah may remain superior and the word of the oppressors may remain inferior, has found the path of guidance and stands on the right way while his heart is illuminated with conviction.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §5', 'character'),
  ('إذا رَأى أحَدُكُمْ المُنْكَرَ، وَلَمْ يَسْتَطِعْ أنْ يُنْكِرَهُ بِيَدِهِ ولِسانِهِ، وأنْكَرَهُ بِقَلْبِهِ، وعَلِمَ اللّهُ صِدقَ ذلِك مِنْهُ فَقَد أنكَرَهُ.', 'If one of you sees an evil being committed and is unable to forbid it with his hand or tongue and forbids it with his heart, while Allah knows the truth of his intention, then [it is as if] he has forbidden it.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §6', 'character'),
  ('إذا لَمْ تَنْفَعِ الكَرامَةُ فَالإهانَةُ أحْزَمُ، وَإذا لَمْ يَنجَحِ السَّوْطُ فَالسَّيفُ أحْسَمُ.', 'When [showing] respect is of no benefit then humiliation is firmer; when the whip is not successful then the sword is sharper.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §7', 'character'),
  ('والأمرَ بِالمَعرُوفِ مَصْلَحةً لِلْعَوامِّ، والنَّهيَ عَنِ المُنْكَرِ رَدْعاً لِلسُّفَهاءِ.', 'Enjoining good [was prescribed] as a reformation for the common people, and forbidding evil as a restriction for the insolent.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §9', 'character'),
  ('كُنْ بِالمعرُوفِ آمِراً، وعَنِ المُنْكَرِ ناهِياً، ولِمَنْ قَطَعَكَ واصِلاً، وَلِمَنْ حَرَمَكَ مُعطِياً.', 'Be one who invites towards good, dissuades from evil, builds ties with those who cut him off and gives to those who deprive him.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §10', 'character'),
  ('كُنْ آمِراً بالمَعْروفِ عاملاً بهِ، ولا تَكُنْ مِمَّنْ يَأمُرُ بِِهِ ويَنْأى عَنْهُ فَيَبُوءُ بإثمهِ، ويَتَعَرَّضُ مَقَتَ رَبِّهِ.', 'Be one who invites towards good while acting upon it, and don’t be one who enjoins it while being distant from it [himself], thereby committing a sin and earning the displeasure of his Lord.', 'Ghurar al-Hikam, Enjoining Good And Forbidding Evil §12', 'character'),
  ('كَمْ مِنْ آمِل خائِب وغائِب غَيْرِ آئِب.', 'Many [of those] who hope get disappointed, and many a traveller fails to return.', 'Ghurar al-Hikam, Hopes And Aspirations §1', 'hope'),
  ('كَمْ مِنْ مُؤَمِّل ما لا يُدْرِكُهُ.', 'Many a person hopes for what he never achieves.', 'Ghurar al-Hikam, Hopes And Aspirations §2', 'hope'),
  ('اَلأمَلُ يُقَرِّبُ المَنِيَّةَ، ويُباعِدُ الاُمنِيَّةَ.', 'Hope brings death closer and takes aspiration further away.', 'Ghurar al-Hikam, Hopes And Aspirations §3', 'hope'),
  ('اَلأملُ سُلطانُ الشَّياطينِ على قُلُوبِ الغافِلينَ.', 'Hope is the dominion of devils over hearts of the negligent.', 'Ghurar al-Hikam, Hopes And Aspirations §4', 'hope'),
  ('اَلأملُ كالسَّرابِ، يُغِرُّ مَنْ رَاهُ، ويُخْلِفُ مَنْ رَجاهُ.', 'Hope is like a mirage, it deceives the one who sees it and disheartens the one who looks forward to it.', 'Ghurar al-Hikam, Hopes And Aspirations §5', 'hope'),
  ('اَلأملُ أبَداً في تَكْذِيب، وطُولُ الحَياةِ لِلْمَرْءِ تَعذيبٌ.', 'Hope is always in denial; and long life is an affliction for man.', 'Ghurar al-Hikam, Hopes And Aspirations §6', 'hope'),
  ('أكذِبِ الأمَلَ، وَلا تَثِقْ بِهِ، فَإنَّهُ غُرُورٌ، وصاحِبُهُ مَغْرُورٌ.', 'Belie hope and do not trust it, for it is a deception and he who possesses it is deceived.', 'Ghurar al-Hikam, Hopes And Aspirations §7', 'hope'),
  ('أكذِبُوا آمالَكُمْ، واغْتَنِمُوا آجالَكُمْ بِأحسَنِ أعْمالِكُمْ، وبادِرُوا مُبادَرَةَ اُولِي النُّهى والألبابِ.', 'Belie your hopes and take advantage of your lifetimes to perform your best deeds, and hasten with the hastening of the wise and those endowed with understanding.', 'Ghurar al-Hikam, Hopes And Aspirations §8', 'hope'),
  ('إتَّقُوا خِداعَ الآمالِ، فَكَمْ مِنْ مُؤَمِّلِ يَوْم لَمْ يُدْرِكْهُ، وَباني بِناء لَمْيَسكُنْهُ، وجامِعِ مال لَمْ يَأكُلْهُ، وَلَعَلَّهُ مِنْ باطِل جَمَعَهُ وَمِنْ حَقّ مَنَعَهُ، أصابَهُ حَراماً، واحْتَمَلَ بِهِ أثاماً.', 'Be wary of the deceit of hopes, for many a person has hoped for a day that never came and built a house that he never occupied and amassed wealth that he never used, and it may be that he amassed it unlawfully by depriving others of their rights, thereby acquiring what is forbidden and carrying the burden of sin.', 'Ghurar al-Hikam, Hopes And Aspirations §9', 'hope'),
  ('إتَّقُوا باطلَ الأمَلِ، فَرُبَّ مُسْتَقْبِلِ يَوم لَيْسَ بِمُسْتَدْبِرِه، ومَغْبُوط في أوّلِ لَيْلَة قامَتْ بَواكيهِ في آخِرِهِ.', 'Be wary of vain hopes, as it is possible for one who starts a day not to end it and for one who is deemed fortunate at dusk to be mourned at dawn.', 'Ghurar al-Hikam, Hopes And Aspirations §10', 'hope'),
  ('إمامٌ عادِلٌ خَيْرٌ مِنْ مَطَر وابِل.', 'A just leader is better [and more beneficial] than heavy rainfall.', 'Ghurar al-Hikam, The Leader §1', 'wisdom'),
  ('مَنْ أطاعَ إمامَهُ فَقَدْ أطاعَ رَبَّهُ.', 'One who obeys his Imām has obeyed his Lord.', 'Ghurar al-Hikam, The Leader §2', 'wisdom'),
  ('يَحتاجُ الإمامُ إلى قَلْب عَقُول، ولِسان قَؤُول، وجَنان على إقامَةِ الحَقِّ صَؤُول.', 'A leader needs a wise mind, an eloquent tongue and a heart that is steadfast in the establishment of truth.', 'Ghurar al-Hikam, The Leader §3', 'wisdom'),
  ('اَلإمامَةُ نِظامُ الاُمَّةِ.', 'Leadership ( imāmah ) is a social order.', 'Ghurar al-Hikam, Leadership §1', 'leadership'),
  ('والإمامَةَ نِظاماً لِلاُْمَّةِ.', 'Leadership is an organizational structure for the society', 'Ghurar al-Hikam, Leadership §2', 'leadership'),
  ('مَنْ أجارَ المُسْتَغيثَ، أجارَهُ اللّهُ سُبْحانَه مِنْ عذابِهِ.', 'Whoever gives refuge to the one who seeks his help, Allah will grant him refuge from His punishment.', 'Ghurar al-Hikam, Granting Refuge To The Fearful §1', 'wisdom'),
  ('مَنْ امَنَ خائفاً مِنْ مَخوفَة، آمَنَهُ اللّهُ سُبْحانَهُ مِنْ عِقابِهِ.', 'One who protects a fearful person from what he fears, Allah, the Glorified, will protect him from His chastisement.', 'Ghurar al-Hikam, Granting Refuge To The Fearful §2', 'wisdom'),
  ('رُبَّ آمِن وَجِل.', 'Many a person who is secure gets frightened.', 'Ghurar al-Hikam, The Secure §1', 'wisdom'),
  ('ما مِنْ شَيْء يَحصُلُ بِهِ الأمانُ أبْلَغَ مِنْ ايمان وإحسان.', 'Nothing brings greater security than [having] faith and [performing] good deeds.', 'Ghurar al-Hikam, Security §1', 'wisdom'),
  ('واللّهِ ما مَنَعَ الأمْنَ أهْلَهُ، وأزاحَ الحقَّ عَنْ مُسْتَحِقِّهِ إلاّ كُلُّ كافِر جاحِد، ومُنافِق مُلْحِد.', 'By Allah, no one hinders the security of the peaceful or takes away the rights of the people except the disbelieving infidel and the duplicitous apostate.', 'Ghurar al-Hikam, Security §2', 'wisdom'),
  ('لا تَغْتَرَّنَّ بِالأمْنِ، فَإنَّكَ مَأخُوذٌ مِنْ مَأمَنِكَ.', 'Do not be deceived by [a false sense of] security, for you will surely be taken from your sanctuary.', 'Ghurar al-Hikam, Security §3', 'wisdom'),
  ('لايَنْبَغي لِلْعاقِلِ أنْ يُقيمَ عَلَى الخَوفِ إذا وَجَدَ إلىَ الأمْنِ سَبيلاً.', 'It is not appropriate for an intelligent person to live in fear when he has found a way to [attain] security.', 'Ghurar al-Hikam, Security §4', 'wisdom'),
  ('لا نِعْمَةَ أهْنَأُ مِنَ الأمْنِ.', 'There is no blessing better than security.', 'Ghurar al-Hikam, Security §5', 'wisdom'),
  ('اَلأمْنُ إغْتِرارٌ، اَلخَوْفُ إسْتِظْهارٌ.', 'Security is [a cause of] deception; fear is [a means of] precaution.', 'Ghurar al-Hikam, Security §6', 'wisdom'),
  ('حَلاوَةُ الأمْنِ، تُنَكِّدُها مَرارَةُ الخَوفِ والحَذَرِ.', 'The sweetness of security is spoilt by the bitterness of fear and panic.', 'Ghurar al-Hikam, Security §7', 'wisdom'),
  ('رُبَّ أمْن إنْقَلَبَ خَوْفاً.', 'Many a security turns into fear.', 'Ghurar al-Hikam, Security §8', 'wisdom'),
  ('رِفاهِيَّةُ العَيْشِ فيِ الأمْنِ.', 'The comfort of life is in security.', 'Ghurar al-Hikam, Security §9', 'wisdom'),
  ('مَنْ أمِنَ مَكْرَ اللّهِ بَطَلَ أمانُهُ (ايمانه).', 'One who feels secure from the scheme of Allah, his sense of security is futile (or his faith is nullified).', 'Ghurar al-Hikam, Feeling Secure From Allah’s Scheme §1', 'wisdom'),
  ('ما أمِنَ عَذابَ اللّهِ مَنْ لَمْ يَأمَنِ النَّاسُ شَـرَّهُ.', 'He from whose evil people are not safe, is not secure from the punishment of Allah.', 'Ghurar al-Hikam, Feeling Secure From Allah’s Scheme §2', 'wisdom'),
  ('ما أقَلَّ الثِّقَة َالمُؤتَمَنَ، وأكْثَرَ الخَوَّانَ.', 'How few are the reliable, trustworthy people, and how many are the treacherous!', 'Ghurar al-Hikam, The Trustworthy §1', 'wisdom'),
  ('اَلأمانَةُ تُؤَدّي إلى الصِّدْقِ.', 'Trustworthiness leads to truthfulness.', 'Ghurar al-Hikam, Trustworthiness §1', 'justice'),
  ('اَلأمانةُ والوَفاءُ صِدْقُ الأفعالِ، والكِذْبُ والإفتِراءُ خيانَةُ الأقوالِ.', 'Trustworthiness and loyalty are sincere actions, lying and fabrication are perfidious utterances.', 'Ghurar al-Hikam, Trustworthiness §2', 'justice'),
  ('أدِّ الأمانَةَ إلى مَنِ ائْتَمَنَكَ، ولا تَخُنْ مَنْ خانَكَ.', 'Return the trust to the one who has entrusted it to you, and do not act treacherously with the one who betrayed your trust.', 'Ghurar al-Hikam, Trustworthiness §3', 'justice'),
  ('أدِّ الأمانَةَ إذَا ائْتُمِنْتَ، ولا تَتَّهِمْ غَيرَكَ إذَا ائْتَمَنْتَهُ، فَإنَّهُ لا إيمانَ لِمَنْ لا أمانَةَ لَهُ.', 'Return the trust when it is entrusted to you, and do not accuse anyone when you entrust something to him, for surely one who is not trustworthy has no faith.', 'Ghurar al-Hikam, Trustworthiness §4', 'justice'),
  ('أفضلُ الأمانَةِ الوَفاءُ بِالعَهدِ.', 'The best [form of] trustworthiness is keeping one’s promise.', 'Ghurar al-Hikam, Trustworthiness §5', 'justice'),
  ('اَلأمانةُ إيمانٌ، البَشاشَةُ إحسانٌ.', 'Trustworthiness is [a sign of] faith; cheerfulness is [a form of] kindness.', 'Ghurar al-Hikam, Trustworthiness §6', 'justice'),
  ('اَلأمانَةُ صِيانةٌ.', 'Trustworthiness is preservation [and safeguarding of what has been entrusted].', 'Ghurar al-Hikam, Trustworthiness §7', 'justice'),
  ('الأمانَةُ فَوْزٌ لِمَنْ رَعاها(وَعاها).', 'Trustworthiness is a success for the one who observes it.', 'Ghurar al-Hikam, Trustworthiness §8', 'justice'),
  ('اَلأمانَةُ فَضيلَةٌ لِمَنْ أدَّاها.', 'Trustworthiness is a merit for the one who executes it.', 'Ghurar al-Hikam, Trustworthiness §9', 'justice'),
  ('آفَةُ الأمانَةِ الخِيانَةُ.', 'The bane of trustworthiness is treachery.', 'Ghurar al-Hikam, Trustworthiness §10', 'justice'),
  ('اَلإيمانُ أفْضَلُ الأمانَتَيْنِ(الأمانَيِْن).', 'Faith is the better of the two trusts (or securities).', 'Ghurar al-Hikam, Faith §1', 'faith'),
  ('اَلإيمانُ قَوْلٌ بِاللِّسانِ، وعَمَلٌ بِالأركانِ.', 'Faith is acknowledging with the tongue and acting with the limbs.', 'Ghurar al-Hikam, Faith §2', 'faith'),
  ('اَلإيمانُ والحَياءُ مَقْرُونانِ في قَرَن، ولا يَفْتَـرِقانِ.', 'Faith and modesty are linked in one linkage and they do not separate.', 'Ghurar al-Hikam, Faith §3', 'faith'),
  ('اَلإيمانُ والعِلْمُ (وَ العمَلُ) أخَوانِ تَوْأمانِ، ورَفيقانِ لا يَفْتَرِقانِ.', 'Faith and knowledge (or action) are twin brothers and companions who do not part ways.', 'Ghurar al-Hikam, Faith §4', 'faith'),
  ('الإيمانُ شَجَرَةٌ، أصْلُهَا الْيَقينُ، وفَرْعُهَا التُّقى، ونُورُهَا الْحَياءُ، وَثَمَرُهَا السَّخاءُ.', 'Faith is a tree, its root is certitude, its branch is piety, its sunlight is modesty and its fruit is generosity.', 'Ghurar al-Hikam, Faith §5', 'faith'),
  ('الإيمانُ، والإخْلاصُ، واليَقينُ، والوَرَعُ، اَلصَّبْرُ والرِّضا بما يَأتي بِهِ القَدَرُ.', 'Faith, sincerity, certitude and piety are [encapsulated in] patience and acceptance of what has been decreed [by Allah].', 'Ghurar al-Hikam, Faith §6', 'faith'),
  ('اَلإيمانُ والعَمَلُ أخَوانِ تَوْأمانِ، ورَفيقانِ لايَفْترِقانِ، لا يَقْبَلُ اللّهُ أحَدَهُما إلاّ بِصاحِبِهِ.', 'Faith and action are twin brothers and companions who do not part ways; Allah does not accept one without its counterpart.', 'Ghurar al-Hikam, Faith §7', 'faith'),
  ('أفضلُ الإيمانِ، الأمانَةُ.', 'The best [sign of] faith is trustworthiness.', 'Ghurar al-Hikam, Faith §8', 'faith'),
  ('أفْضَلُ الإيمانِ، حُسْنُ الإيقانِ.', 'The best faith is [based on] complete certitude.', 'Ghurar al-Hikam, Faith §9', 'faith'),
  ('أقْوىَ النَّاسِ إيمانَاً أكثَرُهُمْ تَوَكُّلاً عَلَى اللّهِ سُبْحانَهُ.', 'The people who are strongest in faith are those who rely the most on Allah, the Glorified.', 'Ghurar al-Hikam, Faith §10', 'faith'),
  ('اَلمُؤْمِنُ صَدُوقُ اللِّسانِ، بَذُولُ الإحسانِ.', 'A believer is very truthful in [his] speech and generous in [his] benevolence.', 'Ghurar al-Hikam, The Believer §1', 'wisdom'),
  ('اَلمُؤْمِِنُ يَقْظانٌ يَنْتَظِرُ إحْدَى الحَسَنَتَينِ.', 'A believer is [always] alert, waiting for one of the two boons [of this world or the Hereafter].', 'Ghurar al-Hikam, The Believer §2', 'wisdom'),
  ('اَلمُؤْمِنُ عَفِيفٌ، مُقْتَنِعٌ، مُتَنَزِّهٌ، مُتَوَرِِّعٌ.', 'A believer is chaste, contented, free from sin and pious.', 'Ghurar al-Hikam, The Believer §3', 'wisdom'),
  ('اَلمُؤْمِنُ مَنْ كانَ حُبُّهلِلّهِ، وبُغْضُهلِلّهِ، وأخذُهلِلّهِ، وتَرْكُهُ لِلّهِ.', 'A believer is one whose love is for [the sake of] Allah, whose hate is for Allah, whose taking is for Allah and whose leaving is for Allah.', 'Ghurar al-Hikam, The Believer §4', 'wisdom'),
  ('اَلمُؤْمِنُ شاكِرٌ فيِ السَّـرّاءِ، صابِرٌ فِي البَلاءِ، خائفٌ فِي الرَّخاءِ.', 'A believer is thankful in [times of] comfort, patient in tribulation and fearful in affluence.', 'Ghurar al-Hikam, The Believer §5', 'wisdom'),
  ('اَلمُؤْمِنُ عَفيفٌ فِي الغِنى، مُتَنَزَّهٌ عَنِ الدُّنيا.', 'A believer is moderate in [times of] affluence, [and] keeps away from the [pleasures of this] world.', 'Ghurar al-Hikam, The Believer §6', 'wisdom'),
  ('اَلمُؤْمِنُ بَيْنَ نِعْمَة وخَطيئَة لا يُصلِحُهُما إلاّ الشُّكرُ وَالإسْتِغْفارُ.', 'A believer is [always] between blessing and wrongdoing, [and] nothing reforms these two except thankfulness and repentance.', 'Ghurar al-Hikam, The Believer §7', 'wisdom'),
  ('اَلمُؤْمِِنُ عِزٌّ كَريمٌ، مَأمُونٌ على نَفْسِهِ، حَذِرٌ مَحْزُونٌ.', 'A believer is dignified, honourable, self-reliant, cautious and sorrowful.', 'Ghurar al-Hikam, The Believer §8', 'wisdom'),
  ('المُؤْمِنُ دائِمُ الذِّكرِ، كَثيرُ الفِكرِ، عَلَى النَّعماءِ شاكِرٌ، وَفِي البَلاءِ صابِرٌ.', 'A believer constantly remembers [Allah], frequently contemplates, is thankful for blessings and patient in the face of tribulation.', 'Ghurar al-Hikam, The Believer §9', 'wisdom'),
  ('اَلمُؤْمِنُ حَييٌّ، غَنيٌّ، مُوقِنٌ، تَقِيٌّ.', 'A believer is modest, independent, certain and pious.', 'Ghurar al-Hikam, The Believer §10', 'wisdom'),
  ('اَلإنسانُ بِعَقْلِهِ.', 'The human being is [distinguished] by his intellect.', 'Ghurar al-Hikam, The Human Being §1', 'wisdom'),
  ('صَلاحُ الإنسانِ في حَبْسِ اللِّسانِ وبَذْلِ الإحسانِ.', 'The uprightness of a human being is in controlling the tongue and doing good deeds.', 'Ghurar al-Hikam, The Human Being §2', 'wisdom'),
  ('وَقالَ ـ عليه السّلام ـ في وَصفِ مَنْ ذَمَّهُ: لايَحْسِبُ رَزِيَّةً، ولا يَخْشَعُ تَقِيَّةً، لا يَعْرِفُ بابَ الهُدى، فَيَتَّبِعَهُ ولا بابَ الرَّدى فَيَصُدَّ عَنْهُ.', 'He (‘a) said about the one whom he censured: He does not anticipate any misfortune and does not humble himself in piety. He does not know the door of guidance so as to go towards it, nor [does he know] the door of perdition so as to turn away from it.', 'Ghurar al-Hikam, The Human Being §3', 'wisdom'),
  ('ثَمَرةُ الأُنسِ بِاللّهِ الاسْتيحاشُ مِنَ النَّاسِ.', 'The fruit of intimacy with Allah is keeping aloof from the people.', 'Ghurar al-Hikam, Intimacy With Allah §1', 'wisdom'),
  ('كَيفَ يَأنَسُ بِاللّهِ مَنْ لا يَسْتَوْحِشُ مِنَ الخَلْقِ؟', 'How can one become intimate with Allah when he has not separated himself from the creation?', 'Ghurar al-Hikam, Intimacy With Allah §2', 'wisdom'),
  ('مَنْ اَنِسَ باللّهِ اِسْتَوحَشَ مِنَ النَّاسِ.', 'One who is intimate with Allah keeps aloof from the people.', 'Ghurar al-Hikam, Intimacy With Allah §3', 'wisdom'),
  ('مَنِ اسْتَوحَشَ عَنِ النَّاسِ أَنِسَ بِاللّهِ سُبْحانَهُ.', 'One who keeps aloof from the people, becomes intimate with Allah, the Glorified.', 'Ghurar al-Hikam, Intimacy With Allah §4', 'wisdom'),
  ('اُنسُ الأمْنِ تُذْهِبُهُ وَحْشَةُ الوَحْدَةِ، وأُنْسُ الجَماعَةِ يُنَكِّدُهُ وَحْشَةُ المَخافَةِ.', 'The comfort of security is removed by the anxiety of loneliness and the apprehension of fear disturbs the familiarity of society.', 'Ghurar al-Hikam, Intimacy §1', 'wisdom'),
  ('اَلأُنسُ في ثَلاثَة: اَلزَّوجَةِ المُوافِقَةِ، والوَلَدِ الصَّالِحِ، والأخِ المُوافِقِ.', 'Intimacy is in three [people]: A compatible wife, a righteous child and an agreeable brother.', 'Ghurar al-Hikam, Intimacy §2', 'wisdom'),
  ('أحقُّ النَّاسِ أنْ يُونَسَ بِهِ، اَلوَدُودُ، اَلمألُوفُ.', 'The most deserving of intimacy among the people is the close friend.', 'Ghurar al-Hikam, Intimacy §3', 'wisdom'),
  ('اَلتُّؤَدَةُ مَمْدُوحَةٌ في كُلِّ شَيْء إلاّ في فُرَصِ الخَيْرِ.', 'Acting slowly is praiseworthy in everything except in opportunities for [doing] good.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §1', 'wisdom'),
  ('اَلتَّثَبُّتُ خَيْرٌ مِنَ العَجَلَةِ إلاّ في فُرَصِ الخَيْرِ(البِرِّ).', 'Taking time [to ascertain] is better than making haste, except in opportunities for [doing] good.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §2', 'wisdom'),
  ('اَلتَّأنّي حَزْمٌ.', 'Deliberateness is judiciousness.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §3', 'wisdom'),
  ('التَّأنّي يُوجِبُ الإستِظهارَ.', 'Deliberateness brings about assurance.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §4', 'wisdom'),
  ('اَلتَّأنّيُ فيِ الفِعْلِ يُؤمِنُ الخَطَلَ.', 'Deliberateness in action protects against errancy.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §5', 'wisdom'),
  ('بِالتَّأنّي تَسْهُلُ المَطالِبُ.', 'Through deliberateness, matters become easy.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §6', 'wisdom'),
  ('التَثَبُّتُ في القَوْلِ يُؤمِنُ العِثارَ والزَّلَلَ.', 'Confidence in speech protects from slips and mistakes.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §7', 'wisdom'),
  ('بِالتَّأنّي تَسْهَلُ الأسْبابُ.', 'Through deliberateness, means become easy.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §8', 'wisdom'),
  ('رُوَيْداً يُسْفِرُ الظَّلامُ، كَأنْ قَدْ وَرَدَتِ الأظْعانُ يُوشِكُ مَنْ أسْـَرعَ أنْ يَلْحَقَ.', 'Slowly! Darkness is disappearing; as though those who had departed have arrived [at their final destination] and those who hasten will soon join.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §9', 'wisdom'),
  ('صِلْ عَجَلَتَكَ بِتَأنّيكَ، وسَطْوَتَكَ بِرِفْقِكَ، وشَرَّكَ بِخَيْرِكَ، وانْصُرِ العَقْلَ عَلَى الهَوى تَمْلِكِ النُّهى.', 'Bind your haste with your deliberateness, your domination with your friendliness and your evil [traits] with your good [ones]. Help the intellect overcome vain desires and you will possess understanding.', 'Ghurar al-Hikam, Deliberateness And Acting Unhurriedly §10', 'wisdom'),
  ('اَلمُتَأَنّي حَرِيٌّ بِالإصابَةِ.', 'One who acts unhurriedly is deserving of success.', 'Ghurar al-Hikam, One Who Acts With Deliberateness §1', 'wisdom'),
  ('اَلمُتَأَنّي مُصيبٌ وإنْ هَلَكَ.', 'The one who acts with deliberateness is successful even if he perishes.', 'Ghurar al-Hikam, One Who Acts With Deliberateness §2', 'wisdom'),
  ('أصابَ مُتَأَنّ أوْ كادَ.', 'The one who acts without haste is either successful or close to success.', 'Ghurar al-Hikam, One Who Acts With Deliberateness §3', 'wisdom'),
  ('اَلتَّأيُّدُ حَزْمٌ.', 'Strengthening oneself is [a sign of] judiciousness.', 'Ghurar al-Hikam, Strengthening Oneself §1', 'wisdom'),
  ('ما أقْرَبَ البُؤسُ مِنَ النَّعيمِ، والمَوْتُ مِنَ الحَياةِ.', 'How close is misery to felicity, and death to life.', 'Ghurar al-Hikam, Misery §1', 'wisdom'),
  ('البُخْلُ أحَدُ الفَقْرَينِ.', 'Stinginess is one of the two forms of poverty.', 'Ghurar al-Hikam, Stinginess And Avarice §1', 'wisdom'),
  ('اَلبُخْلُ يَكْسِبُ العارَ، ويُدْخِلُ النَّارَ.', 'Stinginess earns dishonor and makes one enter hellfire.', 'Ghurar al-Hikam, Stinginess And Avarice §2', 'wisdom'),
  ('البُخْلُ بِإخْراجِ مَاافتَرَضَهُ اللّهُ سُبْحانَهُ مِنَ الأمْوالِ أقْبَحُ البُخلِ.', 'Stinginess in spending from one’s wealth that which Allah, the Glorified, has made obligatory, is the worst type of stinginess.', 'Ghurar al-Hikam, Stinginess And Avarice §3', 'wisdom'),
  ('اِحْتَِرسُوا مِنْ سَوْرَةِ الجِمْدِ(الحَمد)، والحِقْدِ، والغَضَبِ، والحَسَدِ، وَأعِدُّوا لِكُلِّ شَيْء مِنْ ذلِكَ عُدَّةً تُجاهِدونَهُ بِها مِنَ الفِكْرِ فيِ العاقِبَةِ، ومَنْعِ الرَّذيلَةِ، وطَلَبِ الفَضيلَةِ، وصَلاحِ الآخِرَةِ، ولُزومِ الحِلْمِ.', 'Protect yourselves from vehement miserliness, malice, anger and jealousy and prepare for each of these things a contrivance which you can fight it with, like thinking about the consequence, refraining [from] vice, seeking virtue, improving your Hereafter and espousing forbearance.', 'Ghurar al-Hikam, Stinginess And Avarice §4', 'wisdom'),
  ('اِحْذَرُوا البُخْلَ فَإنَّهُ لُؤْمٌ ومَسَبَّةٌ.', 'Be wary of stinginess, for it is ignobility and [leads to] vilification.', 'Ghurar al-Hikam, Stinginess And Avarice §5', 'wisdom'),
  ('اِحْذَرُوا الشُّحَّ، فَإنَّهُ يُكْسِبُ المَقْتَ، ويَشِينُ المَحاسِنَ، ويُشيعُ العُيوبَ.', 'Be wary of avarice, for verily it brings hate, tarnishes [one’s] good qualities and exposes [one’s] faults.', 'Ghurar al-Hikam, Stinginess And Avarice §6', 'wisdom'),
  ('إيّاكَ والتَّحَلِّيَ بِالبُخْلِ، فَإنَّهُ يُزري بِكَ عِندَ القَريبِ (الغَريبِ)، وَيُمَقِّتُكَ إلَى النَّسيبِ.', 'I bid you not to adorn yourself with stinginess, for it will disparage you near those who are close to you and will make your hated by your relatives.', 'Ghurar al-Hikam, Stinginess And Avarice §7', 'wisdom'),
  ('إيّاك والشُّحَّ فَإنَّهُ جِلبابُ المَسْكَنَةِ، وزِمامٌ يُقادُ بِهِ إلى كُلِّ دِناءَة.', 'I bid you to refrain from avarice, for it is the garment of indigence and the bridle that is used to drive one towards every [type of] vileness.', 'Ghurar al-Hikam, Stinginess And Avarice §8', 'wisdom'),
  ('إيّاكُمْ والبُخلَ، فَإنَّ البَخيلَ يَمْقَتُهُ الغَريبُ، ويَنْفُرُ مِنْهُ القَريبُ.', 'I bid you to refrain from stinginess, for the miser is hated by strangers and shunned by those who are close to him.', 'Ghurar al-Hikam, Stinginess And Avarice §9', 'wisdom'),
  ('أقْبَحُ البُخْلِ مَنْعُ الأمْوالِ مِنْ مُسْتَحِقِّها.', 'The worst stinginess is withholding money from those who deserve it.', 'Ghurar al-Hikam, Stinginess And Avarice §10', 'wisdom'),
  ('البَخيلُ يَبْخَلُ على نَفْسِهِ بِاليَسيرِ مِنْ دُنياهُ، ويَسْمَحُ لِوُرَّاثهِ بِكُلِّها.', 'A miser is stingy towards himself with little of his worldly possessions and leaves all the rest for his heirs.', 'Ghurar al-Hikam, The Miser And The Avaricious §1', 'wisdom'),
  ('اَلبَخيلُ يَسْمَحُ مِنْ عِرْضِهِ بِأكثَرَ مِمّا أمْسَكَ مِنْ عَرَضِهِ، ويُضَيِّعُ مِنْ دينِهِ أضعافَ ما حَفِظَ مِنْ نَشَبِهِ.', 'A miser gives up of more of his honour than what he holds of his possessions and loses multiple times more of his religion than what he saves of his property.', 'Ghurar al-Hikam, The Miser And The Avaricious §2', 'wisdom'),
  ('أبْعَدُ الخلائِقِ مِنَ اللّهِ تعالى اَلبَخيلُ الغَنِيُّ.', 'The farthest of creatures from Allah, the Exalted, is the wealthy miser.', 'Ghurar al-Hikam, The Miser And The Avaricious §3', 'wisdom'),
  ('أبْخَلُ النَّاسِ بِعَرَضِهِ أسْخاهُمْ بِعِرْضِهِ.', 'The most miserly with his possessions is the most generous with his honour.', 'Ghurar al-Hikam, The Miser And The Avaricious §4', 'wisdom'),
  ('أبْخَلُ النَّاسِ مَنْ بَخِلَ على نَفْسِهِ بِمالِهِ، وخَلَّفَهُ لِوُرّاثهِِ.', 'The most miserly of all people is the one who is stingy to himself with his wealth, and [eventually] leaves it behind for his heirs.', 'Ghurar al-Hikam, The Miser And The Avaricious §5', 'wisdom'),
  ('البَخيلُ مَذْمُومٌ، اَلْحَسُودُ مَغْمُومٌ.', 'The miser is dispraised, the envious is disheartened.', 'Ghurar al-Hikam, The Miser And The Avaricious §6', 'wisdom'),
  ('اَلبَخيلُ خازِنٌ لِوَرَثَتِهِ.', 'The miser is a treasurer for his heirs.', 'Ghurar al-Hikam, The Miser And The Avaricious §7', 'wisdom'),
  ('البَخيلُ مُتَعَجِّلُ الفَقْرِ.', 'A miser hastens poverty.', 'Ghurar al-Hikam, The Miser And The Avaricious §8', 'wisdom'),
  ('اَلبَخيلُ أبَداً ذَليلٌ.', 'A miser is always disgraced.', 'Ghurar al-Hikam, The Miser And The Avaricious §9', 'wisdom'),
  ('اَلبَخيلُ مُتَحَجِّجٌ (مُتَبََجِّجٌ) بِالمعاذيرِ والتَّعالِيلِ.', 'A miser always comes up with excuses and pretexts.', 'Ghurar al-Hikam, The Miser And The Avaricious §10', 'wisdom'),
  ('بادِرُوا العَمَلَ، وأكْذِبُوا الأمَلَ، ولاحِظُوا الأجَلَ.', 'Take the initiative to act, belie [false] hope and recall death.', 'Ghurar al-Hikam, Taking The Initiative §1', 'wisdom'),
  ('بادِرُوا العَمَلَ(الأمَل)، وخَافُوا بَغْتَةَ الأجَلِ، تُدْرِكُوا أفْضَلَ الأمَلِ.', 'Take the initiative to act and fear the suddenness of death, [then] you will realize the greatest hope.', 'Ghurar al-Hikam, Taking The Initiative §2', 'wisdom'),
  ('بادِرُوا بِالعَمَلِ عُمْراً ناكِساً.', 'Hasten towards [virtuous] actions before old age disables you.', 'Ghurar al-Hikam, Taking The Initiative §3', 'wisdom'),
  ('بادِروا بِالعَمَلِ مَرَضاً حابِساً، وَمَوْتاً خالِساً.', 'Hasten towards [virtuous] actions before debilitating illness or sudden death [overtakes you].', 'Ghurar al-Hikam, Taking The Initiative §4', 'wisdom'),
  ('بادِرِ البِرَّ فَإنَّ أعْمالَ البِرِّ فُرْصَةٌ.', 'Hasten towards virtue, for verily virtuous deeds are an opportunity [to secure your Hereafter].', 'Ghurar al-Hikam, Taking The Initiative §5', 'wisdom'),
  ('بادِرُوا صالِحَ الأعْمالِ والخَناقُ مُهْمَلٌ والرُّوحُ مُرْسَلٌ.', 'Take the initiative to perform good deeds [now] while the neck is free from the noose and the spirit is unfettered.', 'Ghurar al-Hikam, Taking The Initiative §6', 'wisdom'),
  ('بادِرْ شَبابَكَ قَبْلَ هَرَمِكَ، وصِحَّتَكَ قَبْلَ سُقْمِكَ.', 'Take the initiative in your youth before your old age and in your health before your illness.', 'Ghurar al-Hikam, Taking The Initiative §7', 'wisdom'),
  ('بادِرْ غِناكَ قَبْلَ فَقْرِكَ، وحَيوتَكَ قَبْلَ مَوْتِكَ.', 'Take the initiative in your affluence before your poverty and while you are alive before your death.', 'Ghurar al-Hikam, Taking The Initiative §8', 'wisdom'),
  ('بادِرُوا في مَهَلِ البَقِيَّةِ، وأنْفِ المَشيَّةِ، وانْتِظارِ التَّوبَةِ، وانْفِساخِ الحَوبَةِ.', 'Take the initiative while the rest of your life is before you, and you have the ability to act by volition 1 , and have the opportunity of repentance, and the possibility of abrogating your misdeeds.', 'Ghurar al-Hikam, Taking The Initiative §9', 'wisdom'),
  ('بادِرُوا والأبْدانُ صَحيحَةٌ، والألْسُنُ مُطْلَقَةٌ، والتَّوبَةُ مَسْمُوعَةٌ، وَالأعْمالُ مَقْبُولَةٌ.', 'Hasten to act while the bodies are healthy, the tongues are untied, the [cry of] repentance is heard and the deeds are accepted.', 'Ghurar al-Hikam, Taking The Initiative §10', 'wisdom'),
  ('تَوَقُّو البَرْدَ في أوَّلِهِ، وتَلَقَّوْهُ في آخِرهِ، فَإنَّهُ يَفْعَلُ بِالأبْدانِ كَما يَفْعَلُ فِي الأغصانِ، أوَّلُهُ يُحْرِقُ، وآخِرُهُ يُورِقُ.', 'Be cautious of the cold [of winter] at its onset and embrace it towards its ending, for it acts upon the bodies as it acts upon the branches its beginning scorches and its end causes leaves to grow.', 'Ghurar al-Hikam, Cold Weather §1', 'wisdom'),
  ('اَلبِرُّ عَمَلٌ مُصْلِحٌ.', 'The righteous act is an action that reforms.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §1', 'wisdom'),
  ('اَلبِرُّ عَمَلٌ صالِحٌ.', 'The righteous act is a good deed.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §2', 'wisdom'),
  ('اَلْبِرُّ غَنيمَةُ الحازِمِ.', 'Righteousness is the prize of the judicious.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §3', 'wisdom'),
  ('اَلبِـرُّ أعْجَلُ شَيْء مَثُوبَةً.', 'Righteousness is the quickest in acquiring reward.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §4', 'wisdom'),
  ('بِالبُـِرِّ يُمْلَكُ الحُرُّ.', 'Through righteousness the free man is owned.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §5', 'wisdom'),
  ('تَعجِيلُ البِرِّ زيادَةٌ فِي البِرِّ.', 'Hastening to perform righteous acts increases [one’s] righteousness.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §6', 'wisdom'),
  ('خَيْرُ البِرِّ ما وَصَلَ إلَى الأحْرارِ.', 'The best benefaction is that which reaches the free.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §7', 'wisdom'),
  ('خَيْرُ البِرِّ ما وَصَلَ إلَى المُحْتاجِ.', 'The best righteous act is that which reaches the needy.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §8', 'wisdom'),
  ('في كُلِّ بِرّ شُكْرٌ.', 'In every righteous act there is gratitude.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §9', 'wisdom'),
  ('مَنْ مَنَعَ بِرّاً مُنِعَ شُكْراً.', 'One who prevents righteousness is deprived of gratitude.', 'Ghurar al-Hikam, Righteousness And Those Who Prevent It §10', 'wisdom'),
  ('مَنْ أبْرَمَ سُئِمَ.', 'One who insists [too much] makes others fed up of him.', 'Ghurar al-Hikam, Insistence §1', 'wisdom'),
  ('اَلبَريءُ صَحيحٌ، وَالمُريبُ عَليلٌ.', 'The innocent one is healthy, the suspicious one is sick.', 'Ghurar al-Hikam, The Innocent §1', 'wisdom'),
  ('البَريءُ جَريءٌ.', 'The innocent one is fearless.', 'Ghurar al-Hikam, The Innocent §2', 'wisdom'),
  ('ما أشْجَعَ البَريءُ وأجْبَنَ المُريبُ.', 'How courageous the innocent one is and how timid is the suspicious one!', 'Ghurar al-Hikam, The Innocent §3', 'wisdom'),
  ('لا أشْجَعَ مِنْ بَريء.', 'No one is more courageous than an innocent person.', 'Ghurar al-Hikam, The Innocent §4', 'wisdom'),
  ('كُلُّ بَريء صَحيحٌ.', 'Every innocent one is well.', 'Ghurar al-Hikam, The Innocent §5', 'wisdom'),
  ('البَشاشَةُ أحَدُ القَرائَيْنِ.', 'Cheerfulness is one of the two forms of hospitality.', 'Ghurar al-Hikam, Being Cheerful And Smiling §1', 'wisdom'),
  ('اَلبَشاشَةُ إحْسانٌ.', 'Cheerfulness is [a form of] kindness.', 'Ghurar al-Hikam, Being Cheerful And Smiling §2', 'wisdom'),
  ('اَلبَشاشَةُ حِبالَةُ المَوَدَّةِ.', 'Cheerfulness is a trap for [ensnaring] affection.', 'Ghurar al-Hikam, Being Cheerful And Smiling §3', 'wisdom'),
  ('عَلَيكَ بِالبَشاشَةِ فَإنَّهُ حِبالَةُ المَوَدَّةِ.', 'Adopt cheerfulness for it is indeed a trap for [ensnaring] affection.', 'Ghurar al-Hikam, Being Cheerful And Smiling §4', 'wisdom'),
  ('لابَشاشَةَ مَعَ إبْرام.', 'There is no cheerfulness with annoyance.', 'Ghurar al-Hikam, Being Cheerful And Smiling §5', 'wisdom'),
  ('اَلبِشْرُ يُطْفِئُ نارَ المُعانَدَةِ.', 'Cheerfulness cools down the fire of opposition.', 'Ghurar al-Hikam, Being Cheerful And Smiling §6', 'wisdom'),
  ('اَلبِشْرُ أوَّلُ النَّوالِ.', 'Cheerfulness is the first gift [that can be given].', 'Ghurar al-Hikam, Being Cheerful And Smiling §7', 'wisdom'),
  ('اَلبِشْرُ شيمَةُ الحُرِّ.', 'Cheerfulness is the trait of the free.', 'Ghurar al-Hikam, Being Cheerful And Smiling §8', 'wisdom'),
  ('اَلبِشْرُ يُوْنِسُ الرِّفاقَ.', 'Cheerfulness makes companions affable.', 'Ghurar al-Hikam, Being Cheerful And Smiling §9', 'wisdom'),
  ('اَلبِشْرُ إسْداءُ الصَّنيعَةِ بِغَيْرِ مَؤُنَة.', 'Cheerfulness renders goodness without any expense.', 'Ghurar al-Hikam, Being Cheerful And Smiling §10', 'wisdom'),
  ('أيْنَ الأبصارُ اللامِحَةُ مَنارَ التَّقْوى؟', 'Where are the eyes that glance at the [illuminated] signposts of piety?', 'Ghurar al-Hikam, Sight, Observation And Insight §1', 'wisdom'),
  ('أبْصَرُ النَّاسِ مَنْ أبْصَرَ عُيُوبَهُ، وأقْلَعَ عَنْ ذُنُوبِهِ.', 'The most observant person is one who sees his own faults and refrains from his sins.', 'Ghurar al-Hikam, Sight, Observation And Insight §2', 'wisdom'),
  ('إنَّ أبصارَ هذِهِ الفُحُولِ طوامِحُ، وهُوَ سَبَبُ هَبابِها، فإذا نَظَرَ أحَدُكُمْ إلَى امْرَأة فَأعْجَبَتْهُ، فَلْيَمُسَّ أهْلَهُ. فَإنَّما هيَ امْرأةٌ بِامْرَأة.', '[It is narrated that at one time some people looked at a passing woman with lust, at which point the Imam (‘a) said:] Verily the eyes of these virile males are covetous and this glancing is the cause of their lust. Whenever any of you sees a woman whom he finds attractive, he should go to his wife, because she [too] is a woman like her.', 'Ghurar al-Hikam, Sight, Observation And Insight §3', 'wisdom'),
  ('إنَّما البَصيرُ مَنْ سَمِعَ فَفَكَّرَ، ونظَرَ فَأبْصَرَ، وانْتَفَعَ بِالعِبرِ.', 'Indeed the perceptive person is one who listens and then ponders, sees then reflects, and derives benefit from examples.', 'Ghurar al-Hikam, Sight, Observation And Insight §4', 'wisdom'),
  ('بِالإسْتِبْصارِ يَحصُلُ الإعتِبارُ.', 'It is through observation [and reflection] that lessons are learned.', 'Ghurar al-Hikam, Sight, Observation And Insight §5', 'wisdom'),
  ('ذَهابُ البَصَرِ خَيْـرٌ مِنْ عَمَى البَصيرَةِ.', 'The loss of eyesight is better than the blinding of insight.', 'Ghurar al-Hikam, Sight, Observation And Insight §6', 'wisdom'),
  ('ذَهابُ النَّظَرِ خَيْرٌ مِنَ النَّـظَرِ إلى ما يُوجِبُ الفِتْنَةَ.', 'Loss of vision is better than looking at something that causes temptation.', 'Ghurar al-Hikam, Sight, Observation And Insight §7', 'wisdom'),
  ('رُبَّما أخْطَأ البَصيرُ رُشْدَهُ.', 'Sometimes the one who can see [also] loses his way.', 'Ghurar al-Hikam, Sight, Observation And Insight §8', 'wisdom'),
  ('فَقْدُ البَصََـرِأهْوَنُ مِنْ فِقْدانِ البَصيرَةِ.', 'Loss of eyesight is easier than loss of insight.', 'Ghurar al-Hikam, Sight, Observation And Insight §9', 'wisdom'),
  ('فاقِدُ البَصَرِ فاسِدُ النَّظَرِ.', 'One who has lost his sight makes wrong judgments.', 'Ghurar al-Hikam, Sight, Observation And Insight §10', 'wisdom'),
  ('اَلبَطَرُ يَسْلُبُ النِّعْمَةَ، ويَجْلِبُ النِّقْمَةَ.', 'Wantonness takes away blessings and brings chastisement.', 'Ghurar al-Hikam, Wantonness §1', 'wisdom'),
  ('الرَّاضي بِفِعْلِ قَوْم كالدَّاخِلِ فيهِ مَعَهُمْ، ولِكُلِّ داخِل في باطِل إثمانِ: إثْمُ الرِّضا بِهِ، وإثمُ العَمَلِ بِهِ.', 'One who is pleased with the action of a group is like one who participates in it with them, and for everyone who participates in falsehood there are two sins: the sin of being pleased with it and the sin of acting upon it.', 'Ghurar al-Hikam, Falsehood And Assisting It §1', 'wisdom'),
  ('الباطِلُ مُضادُّ الحَقِّ.', 'Falsehood is the opposer of truth.', 'Ghurar al-Hikam, Falsehood And Assisting It §2', 'wisdom'),
  ('اَلباطِلُ غَرُورٌ خادِعٌ.', 'Falsehood is a deceptive beguiler.', 'Ghurar al-Hikam, Falsehood And Assisting It §3', 'wisdom'),
  ('اَلباطِلُ أضْعَفُ نَصير.', 'Falsehood is the weakest supporter.', 'Ghurar al-Hikam, Falsehood And Assisting It §4', 'wisdom'),
  ('اَلباطِلُ يَزِلُّ بِراكِبِهِ.', 'Falsehood [is like a mount that] makes its rider stumble.', 'Ghurar al-Hikam, Falsehood And Assisting It §5', 'wisdom'),
  ('اَلأباطيلُ مُوقِعَةٌ فيِ الأضاليلِ.', 'Falsehoods hurl one into deviations.', 'Ghurar al-Hikam, Falsehood And Assisting It §6', 'wisdom'),
  ('اَلتَّظافُرُ عَلى نَصْرِ الباطِلِ لُؤْمٌ وخيانَةٌ.', 'Collaborating in support of falsehood is vileness and treachery.', 'Ghurar al-Hikam, Falsehood And Assisting It §7', 'wisdom'),
  ('خالِفْ مَنْ خالَفَ الحَقَّ إلى غَيْرِهِ، وَدَعْهُ، وَما رَضيَ لِنَفْسِهِ.', 'Oppose the one who opposes the truth for falsehood; and leave him and that which he has chosen for himself.', 'Ghurar al-Hikam, Falsehood And Assisting It §8', 'wisdom'),
  ('طَلَبُ التَّعاوُنِ على نُصْرَةِ الباطِلِ جنِايَةٌ وخيانَةٌ.', 'Seeking assistance in support of falsehood is a serious offence and an act of treachery.', 'Ghurar al-Hikam, Falsehood And Assisting It §9', 'wisdom'),
  ('ظَلَمَ الحَقَّ مَنْ نَصَرَ الباطِلَ.', 'One who helps falsehood has oppressed the truth.', 'Ghurar al-Hikam, Falsehood And Assisting It §10', 'wisdom'),
  ('غَرَضُ المُبْطِلِ الفَسادُ.', 'The aim of the falsifier is [to cause] corruption.', 'Ghurar al-Hikam, The Falsifier §1', 'wisdom'),
  ('إحْفَظْ بَطْنَكَ وفَرْجَكَ مِنَ الحَرامِ.', 'Protect your stomach and your private parts from what is forbidden.', 'Ghurar al-Hikam, The Stomach And The Private Parts §1', 'wisdom'),
  ('إحْفَظْ بَطْنَكَ وفَرْجَكَ فَفيهِما فِتنَتُكَ.', 'Protect your stomach and your private parts, for in these two lie your trials [and afflictions].', 'Ghurar al-Hikam, The Stomach And The Private Parts §2', 'wisdom'),
  ('بَطْنُ المَرْءِ عَدُّوُهُ.', 'A man’s stomach is his enemy.', 'Ghurar al-Hikam, The Stomach And The Private Parts §3', 'wisdom'),
  ('ما أبْعَدَ الخَيرَ مِمَّنْ هِمَّتُهُ بَطْنُهُ وفَرْجُهُ.', 'How far is goodness from the one whose efforts are [solely] for his stomach and private parts!', 'Ghurar al-Hikam, The Stomach And The Private Parts §4', 'wisdom'),
  ('أمْقَتُ العِبادِ إلَى اللّهِ سُبْحانَهُ مَنْ كانَ هَمُّهُ (هِمَّتُهُ) بَطْنُهُ وَفَرْجُهُ.', 'The most detested servant in the sight of Allah, the Glorified, is the one whose concern (and effort) is [solely] for his stomach and his private parts.', 'Ghurar al-Hikam, The Stomach And The Private Parts §5', 'wisdom'),
  ('باكِرُوا فَالبَرَكَةُ فيِ المُباكَرَةِ، وشاوِرُوا فَالنُّجْحُ فيِ المُشاوَرَةِ.', 'Wake up early [in the morning] for there is blessing in early rising; and consult each other, for success is in consultation.', 'Ghurar al-Hikam, Early Rising §1', 'forgiveness'),
  ('اَلبُكاءُ مِنْ خيفَةِ اللّهِ لِلْبُعْدِ عَنِ اللّهِ عِبادةُ العارِفينَ.', 'Weeping out of fear of Allah, because of being far from Allah, is the worship of the cognizant.', 'Ghurar al-Hikam, Weeping §1', 'wisdom'),
  ('اَلبُكاءُ مِنْ خَشيَةِ اللّهِ يُنيرُ القَلبَ ويَعْصِمُ مِنْ مُعاوَدَةِ الذَّنْبِ.', 'Weeping out of the fear of Allah illuminates the heart and protects [one] from repetition of sin.', 'Ghurar al-Hikam, Weeping §2', 'wisdom'),
  ('اَلبُكاءُ مِنْ خَشْيَةِ اللّهِ مِفْتاحُ الرَّحمَةِ.', 'Weeping out of the fear of Allah is the key to [divine] mercy.', 'Ghurar al-Hikam, Weeping §3', 'wisdom'),
  ('البُكاءُ سَجِيَّةُ المُشْفِقينَ.', 'Weeping is the trait of the soft-hearted [and those who fear Allah].', 'Ghurar al-Hikam, Weeping §4', 'wisdom'),
  ('بِالبُكاءِ مِنْ خَشيَةِ اللّهِ تُمَحَّصُ الذُّنُوبُ.', 'By weeping out of the fear of Allah, sins get purified.', 'Ghurar al-Hikam, Weeping §5', 'wisdom'),
  ('بُكاءُ العَبْدِ مِنْ خَشيَةِ اللّهِ يُمَحِّصُ ذُنُوبَهُ.', 'The weeping of a servant out of the fear of Allah clears away his sins.', 'Ghurar al-Hikam, Weeping §6', 'wisdom'),
  ('طُوبى لِمَنْ وُفِّقَ لِطاعَتِهِ، وبَكى على خَطيئَتِهِ.', 'Blessed is the one who is granted success in his worship and weeps because of his sins.', 'Ghurar al-Hikam, Weeping §7', 'wisdom'),
  ('شَـرُّ البِلادِ بَلَدٌ لا أمْنَ فيهِ وَلا خِصْبَ.', 'The worst of countries is the country in which there is neither peace nor productivity.', 'Ghurar al-Hikam, Countries And Homelands §1', 'wisdom'),
  ('شَـرُّ الأوطانِ ما لَمْ يَأمَنْ (لايأمَنُ) فيهِ القُطَّانُ.', 'The worst homelands are those in which the inhabitants are not safe.', 'Ghurar al-Hikam, Countries And Homelands §2', 'wisdom'),
  ('لَيْسَ بَلَدٌ أحَقُّ البِلادِ بِكَ مِنْ بَلَد، خَيْرُ البِلادِ ما حَمَلَكَ.', 'There is no country (or city) that has a greater right over you than another; the best country is the one that bears you.', 'Ghurar al-Hikam, Countries And Homelands §3', 'wisdom'),
  ('البَلاغَةُ ما سَهُلَ علَى المـَنْطِقِ وخَفَّ عَلَى الفِطْنَةِ.', 'Eloquence is that which is easy on speech and light on reasoning.', 'Ghurar al-Hikam, Eloquence §1', 'wisdom'),
  ('اَلبَلاغَةُ أنْ تُجِيبَ فلا تُبْطِئَ وتُصيبَ فَلا تُخْطِئَ.', 'Eloquence is to reply without hesitation and [to speak] correctly, without making mistakes.', 'Ghurar al-Hikam, Eloquence §2', 'wisdom'),
  ('قَدْ يُكْتَفى مِن البَلاغَةِ بِالإيجازِ.', 'Conciseness can be enough of an eloquence.', 'Ghurar al-Hikam, Eloquence §3', 'wisdom'),
  ('مَنْ قامَ بِفَتْقِ القَولِ ورَتْقِهِ فَقَدْ حازَ البَلاغَةَ.', 'One who undertakes the rending and mending of speech has attained eloquence.', 'Ghurar al-Hikam, Eloquence §4', 'wisdom'),
  ('آلَةُ(آية) البَلاغةِ: قَلْبٌ عَقُولٌ، ولِسانٌ قائِلٌ.', 'The tools of rhetoric are: an intelligent mind and an eloquent tongue.', 'Ghurar al-Hikam, Eloquence §5', 'wisdom'),
  ('رُبَّما اُرْتِجَ عَلَى الفَصيحِ الجَوابُ.', 'Sometimes even the eloquent one is left speechless.', 'Ghurar al-Hikam, Eloquence §6', 'wisdom'),
  ('مَنْ قَلَّتْ مُبالاتُهُ صُرعَ.', 'One whose attention reduces is [taken unawares and] thrown down.', 'Ghurar al-Hikam, Attention §1', 'wisdom'),
  ('في ذِكرِ بَني اُمَيَّةَ: هِيَ مُجاجَةٌ مِنْ لَذيدِ العَيْشِ، يَتَطَعَّمُونَها بُرْهَةً، وَيَلْفَظُونَها جُمْلَةً.', 'While recalling the [rule of the] Umayyads (he said): It is the spittle from the deliciousness of [this temporary] life; they [shall] taste it for a short while and then spit it all out.', 'Ghurar al-Hikam, The Umayyads §1', 'wisdom'),
  ('إنَّ البَهائِمَ هَمُّها بُطُونُها.', 'Verily the [only] concern of quadrupeds (i.e. animals with four legs) is their stomachs.', 'Ghurar al-Hikam, Quadrupeds And Predators §1', 'wisdom'),
  ('إنَّ السِّباعَ هَمُّها العُدْوانُ على غَيْرِها.', 'Indeed the [only] concern of predators is attacking other animals.', 'Ghurar al-Hikam, Quadrupeds And Predators §2', 'wisdom'),
  ('لا قِحَةَ كالبَهْتِ.', 'There is no shamelessness like fabricating lies.', 'Ghurar al-Hikam, Fabricating Lies §1', 'wisdom'),
  ('زِيارَةُ بَيْتِ اللّهِ أمْنٌ مِنْ عَذابِ جَهَنَّمَ.', 'Visiting the House of Allah is a safeguard against the torment of hellfire.', 'Ghurar al-Hikam, The House Of Allah §1', 'wisdom'),
  ('إنَّ هذا المالَ لَيسَ لي ولالَكَ، وإنَّما هُوَ لِلْمُسلِمينَ، وجَلْبُ أسيافِهمْ، فَإنْ شَرَكْتَهُمْ في حَرْبِهِم شَـرَكْتَهُمْ فيه، وإلاّ فَجَنا أيْديهِمْ، لا يَكُونُ لِغَيرِ أفْواهِهِمْ.', 'Verily this wealth is not for me or you, rather it belongs to the Muslims and [is] for obtaining their weapons [of defence]; so if you participate in their war [with them] then you are a partner in it, otherwise that which their hands have acquired cannot be for other than their [own] consumption.', 'Ghurar al-Hikam, The Treasury §1', 'wisdom'),
  ('تاجِرِ اللّهَ تَربَحْ.', 'Do business with Allah and you will profit.', 'Ghurar al-Hikam, Trade And Business With Allah §1', 'forgiveness'),
  ('مَنْ تاجَرَ اللّهَ رَبِحَ.', 'Whoever does business with Allah, profits.', 'Ghurar al-Hikam, Trade And Business With Allah §2', 'forgiveness'),
  ('مَنِ اتَّجرَ بِغَيرِ عِلْم، فَقَدِ ارْتَطَمَ فيِ الرِّبا.', 'One who carries out transactions without knowledge, falls into usury.', 'Ghurar al-Hikam, Trade And Business With Allah §3', 'forgiveness'),
  ('اَلتَّاجِرُ مُخاطِرٌ.', 'The merchant puts himself at risk [of doing something that is forbidden].', 'Ghurar al-Hikam, The Merchant §1', 'wisdom'),
  ('نِعْمَ الطَّهُورُ التُّرابُ.', 'What a good purifier earth is!', 'Ghurar al-Hikam, Earth §1', 'wisdom'),
  ('مَنْ تَرَكَ لِلّهِ سُبْحانَهُ شَيْئاً عَوَّضَهُ اللّهُ خَيْراً مِمّا تَرَكَ.', 'One who abandons something for the sake of Allah, the Glorified, is granted something better than it by Allah.', 'Ghurar al-Hikam, Abandoning For The Sake Of Allah §1', 'wisdom'),
  ('اَلتَّوبَةُ نَدَمٌ بِالقَلبِ، واسْتِغْفارٌ بِاللِّسانِ، وَتَرْكٌ بِالجَوارِحِ، وإضمارُ أن لايَعُودَ.', 'Repentance is heartfelt regret, seeking forgiveness with the tongue, abandoning [the sin] with the limbs and a determination never to repeat it again.', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §1', 'forgiveness'),
  ('إيَّاكَ أنْ تُسْلِفَ المَعْصيَةَ، وتُسَوِّفَ بالتَّوبَةِ، فَتَعْظُمَ لَكَ العُقُوبَةُ.', 'Be careful not to make haste in sinning and to delay repentance, thereby making your punishment greater.', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §2', 'forgiveness'),
  ('ألا تائِبٌ مِنْ خَطيئَتِهِ قَبْلَ حُضُورِ مَنيَّتِهِ.', 'Is there no one who is repentant for his sins before his death comes?', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §3', 'forgiveness'),
  ('التَّوْبَةُ مِمْحاةٌ.', 'Repentance is an eraser [of bad deeds].', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §4', 'forgiveness'),
  ('اَلمُقِرُّ بِالذُّنُوبِ تائِبٌ.', 'One who confesses his sins [and feels regret] is repentant.', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §5', 'forgiveness'),
  ('اَلتَّوبَةُ تَسْتَنْزِلُ الرَّحْمَةَ.', 'Repentance causes [divine] mercy to descend.', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §6', 'forgiveness'),
  ('إخْلاصُ التَّوبَةِ يُسْقِطُ الحَوْبَةَ.', 'Sincere repentance cancels [one’s] sins.', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §7', 'forgiveness'),
  ('اَلتَّوْبَةُ تُطَهِّرُ القُلُوبَ، وتَغْسِلُ الذُّنُوبَ.', 'Repentance purifies the hearts and washes away sins.', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §8', 'forgiveness'),
  ('بِالتَّوبَةِ تُمَحَّصُ السَّيـِّئاتُ.', 'Through repentance, sins are purged.', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §9', 'forgiveness'),
  ('بِالتَّوبَةِ تُكَفَّرُ الذُّنُوبُ.', 'Through repentance, sins are expiated.', 'Ghurar al-Hikam, Repentance And Returning (To Allah) §10', 'forgiveness'),
  ('أصْلُ الرِّضا حُسْنُ الثِّقَةِ بِاللّهِ.', 'The foundation of contentment is complete reliance on Allah.', 'Ghurar al-Hikam, Relying On Allah §1', 'character'),
  ('اَلثِّقَةُ بِاللّهِ أقْوى أمَل.', 'Relying on Allah is the strongest hope.', 'Ghurar al-Hikam, Relying On Allah §2', 'character'),
  ('اِكْتِسابُ الثَّوابِ أفْضلُ الأرْباحِ، والإقْبالُ عَلَى اللّهِ رَأسُ النَّجاحِ.', 'Acquiring [divine] reward is the best achievement and coming close to Allah is the pinnacle of success.', 'Ghurar al-Hikam, Reward §1', 'wisdom'),
  ('اَلثَّوابُ بِالمَشَقَّةِ.', 'Reward is gained in proportion to the difficulty endured.', 'Ghurar al-Hikam, Reward §2', 'wisdom'),
  ('لا رِبْحَ كالثَّوابِ.', 'There is no gain like divine reward.', 'Ghurar al-Hikam, Reward §3', 'wisdom'),
  ('لاذُخْرَ كالثَّوابِ.', 'There is no provision [for the Hereafter] like reward [for good deeds].', 'Ghurar al-Hikam, Reward §4', 'wisdom'),
  ('اِرْفَعْ ثَوبَكَ فَإنَّهُ أنْقى لَكَ، وأتْقى لِقَلْبِكَ، وأبْقى عَلَيكَ.', 'Raise your garment (i.e. do not let it be too long) for that is purer for you, safer for your heart and more long-lasting on you.', 'Ghurar al-Hikam, Garments §1', 'wisdom'),
  ('اِلْبَسْ ما لا تَشْتَهِرُ بِهِ ولا يُزْري بِكَ.', 'Wear that which neither makes you famous nor degrades you.', 'Ghurar al-Hikam, Garments §2', 'wisdom'),
  ('اِحْذَروُا الجُبْنَ، فَإنَّهُ عارٌ، ومَنْقَصَةٌ.', 'Be wary of cowardice for it is indeed disgraceful and [is] a deficiency.', 'Ghurar al-Hikam, Cowardice §1', 'wisdom'),
  ('اَلجُبْنُ افَةٌ، اَلْعَجْزُ سَخافَةٌ.', 'Cowardice is an affliction and impuissance is feeble-mindedness.', 'Ghurar al-Hikam, Cowardice §2', 'wisdom'),
  ('شِدَّةُ الجُبْنِ مِنْ عَجْزِ النَّفْسِ وَضَعْفِ اليَقينِ.', 'Extreme cowardice stems from impuissance of the self and weakness of conviction.', 'Ghurar al-Hikam, Cowardice §3', 'wisdom'),
  ('خَيْرُ الإجْتِهادِ ما قارَنَهُ التَّوْفيقُ.', 'The best striving is that which is accompanied by [divinely granted] success.', 'Ghurar al-Hikam, Diligence And Striving §1', 'purpose'),
  ('عَلَيْكَ بِالجِدِّ وإنْ لَمْ يُساعِدِ الجَدُّ.', 'You must be diligent even if you are not assisted by [good] fortune.', 'Ghurar al-Hikam, Diligence And Striving §2', 'purpose'),
  ('قَدْ سَعِدَ مَنْ جَدَّ.', 'One who is diligent becomes fortunate.', 'Ghurar al-Hikam, Diligence And Striving §3', 'purpose'),
  ('قُرِنَ الإجْتِهادُ بِالوِجْدانِ.', 'Striving has been linked to achievement.', 'Ghurar al-Hikam, Diligence And Striving §4', 'purpose'),
  ('مَنْ ضَعُفَ جِدُّهُ قَوِيَ ضِدُّهُ.', 'One whose diligence becomes weaker, his opponent gets stronger.', 'Ghurar al-Hikam, Diligence And Striving §5', 'purpose'),
  ('مَنْ رَكِبَ جِدَّهُ قَهَرَ ضِدَّهُ.', 'Whoever embarks upon [any action with] diligence, overpowers his opponent.', 'Ghurar al-Hikam, Diligence And Striving §6', 'purpose'),
  ('مَنْ أعْمَلَ اجْتِهادَهُ بَلَغَ مُرادَهُ.', 'One who employs diligence arrives at his goal.', 'Ghurar al-Hikam, Diligence And Striving §7', 'purpose'),
  ('مَنْ بَذَلَ جُهْدَ طاقَتِهِ بَلَغَ كُنْهَ إرادَتِهِ.', 'One who strives with all his effort arrives at the core of his desired objective.', 'Ghurar al-Hikam, Diligence And Striving §8', 'purpose'),
  ('لايَنْفَعُ اِجْتِهادٌ بِغَيرِ تَحْقيق.', 'Striving is useless without accomplishment.', 'Ghurar al-Hikam, Diligence And Striving §9', 'purpose'),
  ('لايَنْفَعُ إجتِهادٌ بِغَيرِ تَوْفيق.', 'Striving is useless without [divinely given] success.', 'Ghurar al-Hikam, Diligence And Striving §10', 'purpose'),
  ('التَّجارِبُ لا تَنْقَضي(وَالعاقِلُ مِنْها في زِيادَة).', 'Experiences don’t end.', 'Ghurar al-Hikam, Experience §1', 'wisdom'),
  ('اَلتَّجارِبُ عِلْمٌ مُسْتَفادٌ.', 'Experiences are beneficial knowledge.', 'Ghurar al-Hikam, Experience §2', 'wisdom'),
  ('اَلتَّجْرِبَةُ تُثْمِرُ الإعْتِبارَ.', 'Experience bears the fruit of learning.', 'Ghurar al-Hikam, Experience §3', 'wisdom'),
  ('ثَمَرَةُ التَجْربَةِ حُسْنُ الإخْتِيارِ.', 'The fruit of experience is making the right choice.', 'Ghurar al-Hikam, Experience §4', 'wisdom'),
  ('حِفْظُ التَّجارِبِ رَأسُ العَقلِ.', 'Preservation of experiences is the pinnacle of intelligence.', 'Ghurar al-Hikam, Experience §5', 'wisdom'),
  ('خَيْرُ ما جَرَّبْتَ ما وَعَظَكَ.', 'The best of what you have experienced is that which taught you a lesson.', 'Ghurar al-Hikam, Experience §6', 'wisdom'),
  ('في كُلِّ تَجْرِبَة مَوعِظَةٌ.', 'In every experience there is an admonition.', 'Ghurar al-Hikam, Experience §7', 'wisdom'),
  ('كَفى بِالتَّجارِبِ مُؤَدِّباً.', 'Experiences suffice as educators.', 'Ghurar al-Hikam, Experience §8', 'wisdom'),
  ('مَنْ يُجَرِّبْ يَزْدَدْ حَزْماً.', 'One who experiences, increases in judiciousness.', 'Ghurar al-Hikam, Experience §9', 'wisdom'),
  ('مَنْ كَثُرَتْ تَجْرِبَتُهُ قَلَّتْ غِرَّتُهُ.', 'One whose experiences increase, his negligence decreases.', 'Ghurar al-Hikam, Experience §10', 'wisdom'),
  ('المُجَرِّبُ أحْكَمُ مِنَ الطَّبيبِ.', 'The experienced person is more proficient than a doctor [who is inexperienced].', 'Ghurar al-Hikam, The Experienced §1', 'wisdom'),
  ('اَلجَزَعُ عِنْدَ البَلاءِ مِنْ تَمامِ المِحْنَةِ.', 'Anxiety during hardship completes [and enhances] the calamity.', 'Ghurar al-Hikam, Anxiety §1', 'patience'),
  ('اَلجَزَعُ عِنْدَ المُصيبَةِ أشَدُّ مِنَ المُصيبَةِ.', 'Anxiety during adversity is severer than the adversity itself.', 'Ghurar al-Hikam, Anxiety §2', 'patience'),
  ('اَلمُصيبَةُ واحِدَةٌ، وإنْ جَزَعَتْ صارَتْ اِثْنَـتَيْنِ.', 'The adversity is one, but if you become anxious it becomes twofold.', 'Ghurar al-Hikam, Anxiety §3', 'patience'),
  ('اَلمُصيبَةُ بِالصَّبْرِ أعْظَمُ المُصيبَتَيْنِ.', 'Adversity [endured] with patience is the better of the two adversities.', 'Ghurar al-Hikam, Anxiety §4', 'patience'),
  ('اَلجَزَعُ لايَدْفَعُ القَدَرَ ولكِنْ يُحـْبِطُ الأجْرَ.', 'Anxiety does not ward off destiny, rather it blocks recompense.', 'Ghurar al-Hikam, Anxiety §5', 'patience'),
  ('اَلجَزَعُ عِنْدَ المُصيبَةِ يَزيدُها، والصَّبْرُ عَلَيْها يُبيدُها.', 'Anxiety during adversity increases it whereas patience ends it.', 'Ghurar al-Hikam, Anxiety §6', 'patience'),
  ('إغْلِبُوا الجَزَعَ بِالصَّبْرِ، فإنَّ الجَزَعَ يَحبِطُ الأجرَ، ويُعَظِّمُ الفَجيعَةَ.', 'Overcome anxiety with patience, for anxiety voids recompense and magnifies the calamity.', 'Ghurar al-Hikam, Anxiety §7', 'patience'),
  ('اَلجَزَعُ هَلاكٌ.', 'Anxiety is [a cause of] destruction.', 'Ghurar al-Hikam, Anxiety §8', 'patience'),
  ('اَلجَزَعُ مِنْ أعوانِ الزَّمانِ.', 'Anxiety is one of the assistants of the [difficult] time.', 'Ghurar al-Hikam, Anxiety §9', 'patience'),
  ('اَلجَزَعُ يُعَظِّمُ المِحْنَةَ.', 'Anxiety magnifies the calamity.', 'Ghurar al-Hikam, Anxiety §10', 'patience'),
  ('مَنْ صَدَّقَ بِالمُجازاةِ لَمْ يُؤْثِرْ غَيْرَ الحُسْنى.', 'One who believes in [divine] requital does not choose [to do] anything but good.', 'Ghurar al-Hikam, Requital And Reward §1', 'wisdom'),
  ('مَنْ أيْقَنَ بِالمُجازاةِ لَـمْ يُؤثِرْ غَيْـرَ الحُسْنى.', 'One who is certain about requital does not choose [to do] anything but good.', 'Ghurar al-Hikam, Requital And Reward §2', 'wisdom'),
  ('عَلى قَدْرِ البَلاءِ يَكُونُ الجَزاءُ.', 'The reward is proportionate to the tribulation [endured].', 'Ghurar al-Hikam, Requital And Reward §3', 'wisdom'),
  ('على قَدْرِ النِّيَّةِ تَـكُونُ مِنَ اللّهِ العَطِيَّةُ.', 'The grant [of reward] from Allah is proportionate to the [sincerity of] intention.', 'Ghurar al-Hikam, Requital And Reward §4', 'wisdom'),
  ('مَنْ لَمْ يُوقِنْ بِالجَزاءِ أفْسَدَ الشَّكُّ يَقينَهُ.', 'One who is not certain of the recompense [for actions], doubt has corrupted his certitude.', 'Ghurar al-Hikam, Requital And Reward §5', 'wisdom'),
  ('لاتُسْرِعَنَّ إلى بادِرَة ولا تُعَجِّلَنَّ بِعُقُوبَة وَجَدْتَ عَنْها مَنْدُوحَةً فَإنَّ ذلِكَ مَنْهَكَةٌ لِلدّينِ مُقَرِّبٌ مِنَ الغِيَـرِ.', 'Never make haste in reacting harshly and never be quick to punish when there is an alternative, for this causes depletion of the faith and brings closer the transformations [of blessing into calamity].', 'Ghurar al-Hikam, Requital And Reward §6', 'wisdom'),
  ('إنَّ أعْجَلَ العُقُوبَةِ عُقُوبَةُ البَغْىِ.', 'The quickest punishment is the punishment for transgression.', 'Ghurar al-Hikam, Requital And Reward §7', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ قَدْ وَضَعَ العِقابَ عَلى مَعاصِيهِ ذِيادَةً لِعِبادِهِ عَنْ نَقِمَتِهِ.', 'Verily Allah, the Glorified, has ordained punishment for committing sins against Him in order to save His servants from His chastisement.', 'Ghurar al-Hikam, Requital And Reward §8', 'wisdom'),
  ('عُقُوبَةُ الكِرامِ أحْسَنُ مِنْ عَفْوِ اللِّئامِ.', 'The punishment of noble ones is better than the forgiveness of the vile ones.', 'Ghurar al-Hikam, Requital And Reward §9', 'wisdom'),
  ('عُقُوبَةُ الغَضُوبِ والحَقُودِ والحَسُودِ تُبْدَءُ بِأنْفُسِهِمْ.', 'The punishment of the hot tempered, spiteful and jealous people starts from [within] themselves.', 'Ghurar al-Hikam, Requital And Reward §10', 'wisdom'),
  ('خِدْمَةُ الجَسَدِ إعْطاؤُهُ ما يَسْتَدْعيهِ مِنَ المَلاذِّ والشَّهَواتِ والمُقْتَنَياتِ وَفي ذلِكَ هِلاكُ النَّفسِ.', 'Serving the body is granting it whatever it seeks of pleasures and desires and what it covets, but in [all] this is the destruction of the soul.', 'Ghurar al-Hikam, The Body §1', 'wisdom'),
  ('صِحَّةُ الأجْسامِ مِنْ أهْنَاِ الأقسامِ.', 'Physical health is one of the most wholesome bounties.', 'Ghurar al-Hikam, The Body §2', 'wisdom'),
  ('كَيفَ يُغْتَرُّ بِسَلامَةِ جِسْم مُعَرَّض للآفاتِ.', 'How can one be deceived by the health of a body that is prone to malady?', 'Ghurar al-Hikam, The Body §3', 'wisdom'),
  ('إيّاكَ والجَفاءَ، فَإنَّهُ يُفْسِدُ الإخاءَ، ويُمَقِّتُ إلَى اللّهِ والنّاسِ.', 'Beware of antipathy, for it corrupts brotherhood and makes one despised by Allah and the people.', 'Ghurar al-Hikam, Antipathy §1', 'wisdom'),
  ('الجَفاءُ شَيْـنٌ، اَلمَعْصِيَةُ حَيْنٌ.', 'Antipathy is a disgrace and sinning is [a cause of] destruction.', 'Ghurar al-Hikam, Antipathy §2', 'wisdom'),
  ('اَلجَفاءُ يُفْسِدُ الإخاءَ.', 'Antipathy spoils brotherhood.', 'Ghurar al-Hikam, Antipathy §3', 'wisdom'),
  ('عِنْدَ كَثْرَةِ الإفْضالِ وشِدَّةِ الإحْتِمالِ تَتَحَقَّقُ الجَلالةُ.', 'When acts of kindness increase and forbearance becomes strong, loftiness is attained.', 'Ghurar al-Hikam, Loftiness §1', 'wisdom'),
  ('سُئِلَ ـ عليه السّلام ـ عنِ الجِماعِ، فقال: حَياءٌ يُرْتَفَعُ، وعَوْراتٌ تَجْتَمِعُ، أشبَهُ شَْيء بِالجُنُونِ، اَلإصرارُ عَلَيْهِ هَرَمٌ، والإفاقَةُ مِنْهُ نَدَمٌ، ثَمَرَةُ حَلالِهِ الوَلَدُ، إنْ عاشَ فَتَنَ، وإنْ ماتَ حَزَنَ..', 'He (‘a) was asked about intercourse, so he said: [It is] shame that is lifted, loins that are joined and the closest thing to insanity. Persistence in it makes one senile and revival from it brings regret. When lawful, its fruit is a son who, if he lives, subjects [one] to trial and if he dies, causes sadness.', 'Ghurar al-Hikam, Intercourse §1', 'wisdom'),
  ('اَلجَمالُ الظّاهِرُ حُسْنُ الصُّورَةِ.', 'External beauty is [in possessing] good looks.', 'Ghurar al-Hikam, Beauty §1', 'character'),
  ('اَلجَمالُ الباطِنُ حُسْنُ السَّريرَةِ.', 'Internal beauty is [in possessing] a good heart.', 'Ghurar al-Hikam, Beauty §2', 'character'),
  ('جَمالُ الرَّجُلِ حِلْمُهُ.', 'The beauty of a man is his clemency.', 'Ghurar al-Hikam, Beauty §3', 'character'),
  ('جَمالُ الرَّجُلِ الوَقارُ.', 'The beauty of a man is dignity.', 'Ghurar al-Hikam, Beauty §4', 'character'),
  ('جَمالُ الحُرِّ تَجَنُّبُ العارِ.', 'Beauty of the freeman is [in] keeping away from dishonour.', 'Ghurar al-Hikam, Beauty §5', 'character'),
  ('زَكوةُ الجَمالِ العَفافُ.', 'The purity of beauty is [in] chastity.', 'Ghurar al-Hikam, Beauty §6', 'character'),
  ('مَنْ كَثُرَ جَميلُهُ أجمَعَ النّاسُ على تَفْضيلِهِ.', 'One whose beautiful actions increase, the people unite in elevating him.', 'Ghurar al-Hikam, The Beautiful §1', 'wisdom'),
  ('التَّجَمُّلُ مُرُوءَةٌ ظاهِرَةٌ.', 'Grooming oneself is an apparent [form of] magnanimity.', 'Ghurar al-Hikam, Grooming §1', 'wisdom'),
  ('اَلتَّجَمُلُ مِنْ أخْلاقِ المُؤمِنينَ.', 'Self-grooming is a characteristic of the believers.', 'Ghurar al-Hikam, Grooming §2', 'wisdom'),
  ('لَيْسَ كُلُّ مُجْمِل بِمَحْرُوم.', 'Not everyone who is moderate in seeking [his livelihood] is deprived.', 'Ghurar al-Hikam, Moderation §1', 'wisdom'),
  ('الجَنَّةُ خَيْرُ مَآل، والنّارُ شَرُّ مَقيل.', 'Paradise is the best place of return and hellfire is the worst place of residence.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §1', 'wisdom'),
  ('ألا وإنّي لَمْ أرَ كَالجَنَّةِ نامَ طالِبُها، ولا كالنَّارِ نامَ هارِبُها.', 'Indeed, I have not seen any place whose seeker is in slumber like Paradise and any place whose fleer is in slumber like hellfire.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §2', 'wisdom'),
  ('إنَّ أهلَ الجَنَّةِ كُلُّ مُؤْمِن هَين لَيْن.', 'Verily the people of Paradise constitute all the believers who are easygoing and gentle.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §3', 'wisdom'),
  ('إنَّ اللّهَ تعالى يُدْخِلُ بِحُسْنِ النِّيَّةِ وصالِحِ السَّريرَةِ مَنْ يَشاءُ مِنْ عِبادِهِ الجَنَّةَ.', 'Verily Allah, the Exalted, makes whomever He wishes, from those of his servants who posses sincere intentions and righteous hearts, enter Paradise.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §4', 'wisdom'),
  ('اَلجَنَّةُ دارُ الأمانِ.', 'Paradise is the abode of peace.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §5', 'wisdom'),
  ('إنْ كُنْتُمْ راغِبينَ لامُحالَةَ، فَارْغَبُوا في جَنَّة عَرْضُهاَ السَّمواتِ والأرضِ.', 'If you must be desirous of something, then be desirous of a Paradise, the span of which covers the heavens and the earth.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §6', 'wisdom'),
  ('اَلجَنَّةُ جَزاءُ المُطيعِ.', 'Paradise is the reward of the obedient.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §7', 'wisdom'),
  ('اَلجَنَّةُ دارُ الأتْقياءِ.', 'Paradise is the abode of the pious.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §8', 'wisdom'),
  ('اَلجَنَّةُ غايَةُ السّابِقينَ.', 'Paradise is the goal of the foremost [in righteousness].', 'Ghurar al-Hikam, Paradise And The People Of Paradise §9', 'wisdom'),
  ('اَلْجَنَّةُ أفْضَلُ غايَة.', 'Paradise is the most excellent goal.', 'Ghurar al-Hikam, Paradise And The People Of Paradise §10', 'wisdom'),
  ('اَلجُودُ فِي اللّهِ عِبادَةُ المُقَرَّبينَ.', 'Generosity for the sake of Allah is the worship of those who are close [to Allah].', 'Ghurar al-Hikam, Generosity §1', 'generosity'),
  ('اَلجُودُ مِنْ غَيْرِ خَوْف ولارَجاءِ مُكافاة، حَقيقَةُ الجُودِ.', 'Generosity without fear or hope of recompense is true generosity.', 'Ghurar al-Hikam, Generosity §2', 'generosity'),
  ('إسْمَحْ تُـكْرَمْ.', 'Give generously and you will be honoured.', 'Ghurar al-Hikam, Generosity §3', 'generosity'),
  ('أسْمَحُكُمْ أرْبَحُكُمْ.', 'The most generous of you is the one who will gain the most.', 'Ghurar al-Hikam, Generosity §4', 'generosity'),
  ('أحْسَنُ المَكارِمِ الجُودُ.', 'The most excellent of noble traits is generosity.', 'Ghurar al-Hikam, Generosity §5', 'generosity'),
  ('أحْسَنُ الجُودِ عَفْوٌ بَعْدَ مَقْدُرَة.', 'The best generosity is to forgive after gaining the upper hand.', 'Ghurar al-Hikam, Generosity §6', 'generosity'),
  ('أفْضَلُ الجُودِ بَذْلُ المَوْجُودِ.', 'The greatest generosity is being open-handed with whatever is available.', 'Ghurar al-Hikam, Generosity §7', 'generosity'),
  ('أفْضَلُ الجُودِ إيصالُ الحُقُوقِ إلى أهْلِها.', 'The greatest generosity is delivering the rights to their [rightful] owners.', 'Ghurar al-Hikam, Generosity §8', 'generosity'),
  ('أفْضَلُ الجُودِ ما كانَ عَنْ عُسْرَة.', 'The greatest generosity is giving despite [facing] hard times.', 'Ghurar al-Hikam, Generosity §9', 'generosity'),
  ('اَلجُودُ رِياسَةٌ، اَلمُلْكُ سِياسَةٌ.', 'Generosity is [true] leadership, sovereignty is [only] administration.', 'Ghurar al-Hikam, Generosity §10', 'generosity'),
  ('اَلجَوادُ مَحْبُوبٌ، مَحْمُودٌ، وإنْ لَمْ يَصِلْ مِنْ جُودِهِ إلى مادِحِهِ شَيْءٌ، والبَخِيْلُ ضِدُّ ذلِكَ.', 'The generous person is loved and praised, even if nothing of his generosity reaches his praiser, and the stingy person is the opposite of this.', 'Ghurar al-Hikam, The Generous §1', 'wisdom'),
  ('اَلجَوادُ فِي الدُّنْيا مَحْمُودٌ، وَفِي الآخِرَةِ مَسْعُودٌ.', 'The one who is generous is praised in this world and felicitous in the Hereafter.', 'Ghurar al-Hikam, The Generous §2', 'wisdom'),
  ('إنَّما سادَةُ أهْلِ الدُّنْيا (والآخِرَةِ) الأجْوادُ.', 'Verily the masters of the people of this world (and the Hereafter) are the generous.', 'Ghurar al-Hikam, The Generous §3', 'wisdom'),
  ('كُنْ جَواداً بِالحَقِّ، بَخيلاً بِالباطِلِ.', 'Be generous with the truth and miserly with falsehood.', 'Ghurar al-Hikam, The Generous §4', 'wisdom'),
  ('كُنْ جَواداً مُؤْثِراً، أوْ مُقْتَصِداً مُقَدِرّاً، وإيّاكَ أنْ تَكُونَ الثّالِثَ.', 'Be [either] selflessly generous or moderate in giving but do not be from the third kind (i.e. the misers).', 'Ghurar al-Hikam, The Generous §5', 'wisdom'),
  ('جارُ اللّهِ سُبْحانَهُ آمِنٌ، وعَدُوُّهُ خائِفٌ.', 'One who is close to Allah is safe, while [one who is] His enemy is frightened.', 'Ghurar al-Hikam, Proximity To Allah §1', 'wisdom'),
  ('جِوارُ اللّهِ مَبْذُولٌ لِمَنْ أطاعَهُ وتَجَنَّبَ مُخالَفَتَهُ.', 'Proximity to Allah is granted to those who obey Him and keep away from disobedience to Him.', 'Ghurar al-Hikam, Proximity To Allah §2', 'wisdom'),
  ('بِئْسَ الجارُ جارُ السُّوءِ.', 'The worst of neighbours is the wicked neighbour.', 'Ghurar al-Hikam, Neighbours §1', 'wisdom'),
  ('جارُ السُّوءِ أعْظَمُ الضَّـرّاءِ، وأشَدُّ البَلاءِ.', 'A wicked neighbour is the greatest adversity and the most serious tribulation.', 'Ghurar al-Hikam, Neighbours §2', 'wisdom'),
  ('جاوِرْمَنْ تَأمَنُ شَـرَّهُ، وَلايَعْدُوكَ خَيْـرُهُ.', 'Be a neighbour to one from whose evil you are safe and whose goodness does not turn away from you.', 'Ghurar al-Hikam, Neighbours §3', 'wisdom'),
  ('سَلْ عَنِ الجارِ قَبْلَ الدّارِ.', 'Ask about the neighbour before the house.', 'Ghurar al-Hikam, Neighbours §4', 'wisdom'),
  ('سُوءُ الجَوارِ والإساءَةُ إلَى الأبْرارِ مِنْ أعْظَمِ اللُّؤمِ.', 'Being a bad neighbour and offending the virtuous are the worst forms of vileness.', 'Ghurar al-Hikam, Neighbours §5', 'wisdom'),
  ('مَنْ حَسُنَ جَوارُهُ كَثُرَ جيرانُهُ.', 'One who is neighbourly gets many neighbours.', 'Ghurar al-Hikam, Neighbours §6', 'wisdom'),
  ('مَنْ أحْسَنَ إلى جيرانِهِ كَثُرَ خَدَمُهُ.', 'One who is good to his neighbours gets many helpers.', 'Ghurar al-Hikam, Neighbours §7', 'wisdom'),
  ('مِنَ الـمُرُوَّةِ تَعَهُّدُ الجيرانِ.', 'Taking care of one’s neighbour is an act of magnanimity.', 'Ghurar al-Hikam, Neighbours §8', 'wisdom'),
  ('اَلْجُوعُ خَيْرٌ مِنْ ذُلِّ الخُضُوعِ.', 'Hunger is better than the humiliation of subjugation.', 'Ghurar al-Hikam, Hunger §1', 'wisdom'),
  ('اَلتَّجَوُّعُ أنْفَعُ الدَّواءِ، اَلشِّبَعُ يُكْثِرُ الأدْواءَ.', 'Keeping oneself hungry is the most beneficial cure, whereas eating to one’s fill increases maladies.', 'Ghurar al-Hikam, Hunger §2', 'wisdom'),
  ('اَلجُوعُ خَيْرٌ مِنَ الخُضُوعِ.', 'Hunger is better than subjugation.', 'Ghurar al-Hikam, Hunger §3', 'wisdom'),
  ('تَأَدَّمْ بِالجُوعِ وتَأَدَّبْ بِالقُنُوعِ.', 'Complement your food with hunger and discipline yourself with contentment.', 'Ghurar al-Hikam, Hunger §4', 'wisdom'),
  ('نِعْمَ الإدامُ الجُوعُ.', 'The best condiment is hunger.', 'Ghurar al-Hikam, Hunger §5', 'wisdom'),
  ('نِعْمَ عَونُ الوَرَعِ التَّجَوُّعُ.', 'How good an assistant of piety hunger is!', 'Ghurar al-Hikam, Hunger §6', 'wisdom'),
  ('نِعْمَ العَونُ عَلى أشَـرِ(أسْرِ) النَّفْسِ وكَسْرِ عادَتِها التَّجَوُّعُ.', 'How good an assistant in cutting down the [desires of the carnal] self and breaking its [bad] habits hunger is!', 'Ghurar al-Hikam, Hunger §7', 'wisdom'),
  ('زَكوةُ الجاهِ بَذْلُهُ.', 'The alms-tax of high rank [and power] is benefitting others with it.', 'Ghurar al-Hikam, High Rank §1', 'wisdom'),
  ('مِنَ الواجِبِ عَلى ذِي الجاهِ أنْ يَبْذُلَهُ لِطالِبِهِ.', 'One of the obligations of a person who possesses a high rank is to use it to grant the [needs of] one who seeks from him.', 'Ghurar al-Hikam, High Rank §2', 'wisdom'),
  ('مَنْ بَذَلَ جاهَهُ اسْتَحْمَدَ.', 'One who benefits others with his high rank makes himself praiseworthy.', 'Ghurar al-Hikam, High Rank §3', 'wisdom'),
  ('إنَّ مَنْ بَذَلَ نَفْسَهُ في طاعَةِ اللّهِ ورَسُولِِهِ كانَتْ نَفْسُهُ ناجِيَةً سالِمَةً، وَصَفْقَتُهُ رابِحَةً غانِمَةً.', 'Whoever makes an effort to strive in obedience to Allah and His messenger, his soul shall be safe and sound [from the torments of the Hereafter] and his transaction will be profitable and gainful.', 'Ghurar al-Hikam, Struggle (Jihad) §1', 'wisdom'),
  ('إنَّ أوَّلَ ما تُغْلَبُونَ عَلَيهِ مِنَ الجِهادِ، جِهادٌ بِأيْديكُمْ، ثُمَّ بِألْسِنَتِكُمْ، ثُمَّ بِقُلُوبِكُمْ، فَمَنْ لَمْ يَعْرِفْ بِقَلْبِهِ مَعْرُوفاً، وَلَمْ يُنْكِرْ مُنْكَراً، قُلِّبَ فَجُعِلَ أعْلاهُ أسْفَلَهُ.', 'The first thing which you overcome through Jihād is through striving with your hands, then [if this is not possible] by your tongue, then [if this is not possible] with your hearts; and the one who neither supports good with his heart nor censures evil, is turned upside down (i.e. will face the wrath of Allah).', 'Ghurar al-Hikam, Struggle (Jihad) §2', 'wisdom'),
  ('الجِهادُ عِمادُ الدّينِ، ومِنْهاجُ السُّعَداءِ.', 'Struggling [in the way of Allah] is the pillar of faith and the path of the felicitous.', 'Ghurar al-Hikam, Struggle (Jihad) §3', 'wisdom'),
  ('اَلمُجاهِدُونَ تُفْتَحُ لَهُمْ أبْوابُ السَّماءِ.', 'The doors of the heavens are opened for those who strive [in the way of Allah].', 'Ghurar al-Hikam, Struggle (Jihad) §4', 'wisdom'),
  ('إنْ كانَتِ الرَّعايا قَبْلي تَشْكُوا حَيْفَ رُعاتِها فَإنِّي اليَوْمَ أشْكُو حَيْفَ رَعِيَّتي، كَأنِّي المَقُودُ وهُمُ القادَةُ، والمُوزَعُ وَهُمُ الوَزَعَةُ', 'If the people who came before me complained about the injustice of their rulers, then today I complain about the injustice of my people; it is as if I am led and they are the leaders, [and] I am restrained and they are the restrainers.', 'Ghurar al-Hikam, Struggle (Jihad) §5', 'wisdom'),
  ('ثوابُ الجِهادِ أعْظَمُ الثَّوابِ.', 'The reward for striving [in the way of Allah] is the greatest reward.', 'Ghurar al-Hikam, Struggle (Jihad) §6', 'wisdom'),
  ('والجِهادَ عِزّاً لِلإسْلامِ.', 'And [Allah has prescribed] Jihād as [a means of preserving the] honour of Islam.', 'Ghurar al-Hikam, Struggle (Jihad) §7', 'wisdom'),
  ('لا تَجْتَمِعُ عَزيمَةٌ ووَليمَةٌ.', 'Strong determination and lavishness do not go together.', 'Ghurar al-Hikam, Struggle (Jihad) §8', 'wisdom'),
  ('زَكوةُ البَدَنِ الجِهادُ والصِّيامُ.', 'The purification of the body is [in] striving and fasting.', 'Ghurar al-Hikam, Struggle (Jihad) §9', 'wisdom'),
  ('ألا وإنَّ الجِهادَ ثَمَنُ الجَنَّةِ، فَمَنْ جاهَدَ نَفْسَهُ مَلَكَها، وهِيَ أكْرَمُ ثَوابِ اللّهِ لِمَنْ عَرَفَها.', 'Indeed Jih ā d is the price of Paradise, so the one who struggles against his self will acquire it, and this is the greatest reward of Allah for the one who is cognizant of it.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §1', 'self-mastery'),
  ('أفْضَلُ الجِهادِ مُجاهَدَةُ المَرْءِ نَفْسَهُ.', 'The best Jih ā d is the struggle of a man against his [carnal] soul.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §2', 'self-mastery'),
  ('أفْضَلُ الجِهادِ جِهادُ النَّفْسِ عَنِ الهَوى، وفِطامُها عَنْ لَذّاتِ الدُّنيا.', 'The best Jih ā d is the struggle of the self against lustful desires, and its weaning away from the pleasures of this world.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §3', 'self-mastery'),
  ('أوَّلُ ما تُنْكِرُونَ مِنَ الجِهادِ، جِهادُ أنْفُسِكُمْ.', 'The first thing that you disavow from Jih ā d is struggling against your selves.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §4', 'self-mastery'),
  ('آخِرُ ما تَفْقِدُونَ مُجاهَدَةُ أهْوائِكُمْ وطاعَةُ أُولِي الأَمْرِ مِنْكُمْ.', 'The last things that you [should] lose are: the struggling against your selves and obedience to those who have authority among you.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §5', 'self-mastery'),
  ('إنَّ أفْضَلَ الجِهادِ مُجاهَدَةُ الرَّجُلِ نَفْسَهُ.', 'Indeed the best Jih ā d is the struggle of a man against his [carnal] soul.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §6', 'self-mastery'),
  ('إنَّ مُجاهَدَةَ النَّفْسِ لَتَزِمُّها عَنِ المَعاصِي، وتَعْصِمُها عَنِ الرَّدى.', 'Verily struggling against the self restrains it from sins and protects it from destruction.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §7', 'self-mastery'),
  ('إنَّ المُجاهِدَ نَفْسَهُ عَلى طاعَةِ اللّهِ وَعَنْ مَعاصِيهِ، عِنْدَاللّهِ سُبْحانَهُ بِمَنْزِلَةِ بَرّ شَهيد.', 'Verily the one who struggles with his [lower] self, in obedience to Allah and against disobedience to Him, has the status of a virtuous martyr in the sight of Allah.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §8', 'self-mastery'),
  ('إنَّ المُجاهِدَ نَفْسَهُ، والمُغالِبَ غَضَبَهُ، والمُحافِظَ عَلى طاعَةِ رَبِّهِ، يَرْفَعُ اللّهُ سُبْحانَهُ لَهُ ثَوابَ الصَّائِمِ القائِمِ ويُنيلُهُ دَرَجَةَ المُرابِطِ الصّابِرِ.', 'Indeed the one who struggles against his [lower] self, overcomes his anger and is careful in obeying [the commandments of] Allah, is raised by Allah, the Glorified, to the status of the one who fasts by day and stands in prayer by night, and is granted the rank of the patient soldier [who fights in His way].', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §9', 'self-mastery'),
  ('إنَّكَ إنْ جاهَدْتَ نَفْسَكَ حُزْتَ رِضَى اللّهِ.', 'Verily if you struggle against your [lower] self you will obtain the pleasure of Allah.', 'Ghurar al-Hikam, Struggling Against The Self (Jihad An-Nafs) §10', 'self-mastery'),
  ('اَلجَهْلُ،وَ البُخْلُ، مَساءَةٌ، ومَضَرَّةٌ.', 'Ignorance and miserliness are bad and harmful.', 'Ghurar al-Hikam, Ignorance §1', 'wisdom'),
  ('اَلجَهْلُ فِي الإنْسانِ أضَرُّ مِنَ الآكِلَةِ فِي البَدَنِ.', 'Ignorance in a human being is more harmful than gangrene [is] to the body.', 'Ghurar al-Hikam, Ignorance §2', 'wisdom'),
  ('اَلجَهْلُ مَطِيَّةٌ شَمُوسٌ، مَنْ رَكِبَها زَلَّ، ومَنْ صَحِبَها ضَلَّ.', 'Ignorance is a balky mount; whoever rides it stumbles and whoever accompanies it is led astray.', 'Ghurar al-Hikam, Ignorance §3', 'wisdom'),
  ('اَلجَهْلُ بِالفَضائِلِ مِنْ أقْبَحِ الرَّذائِلِ.', 'Ignorance of merits is one of the grossest demerits.', 'Ghurar al-Hikam, Ignorance §4', 'wisdom'),
  ('أعْظَمُ المَصائِبِ الجَهْلُ.', 'The greatest calamity is ignorance.', 'Ghurar al-Hikam, Ignorance §5', 'wisdom'),
  ('أسْوَءُ السُّقْمِ(القِسْمِ) الجَهْلُ.', 'The worst ailment is ignorance.', 'Ghurar al-Hikam, Ignorance §6', 'wisdom'),
  ('أعْظَمُ الجَهْلِ جَهْلُ الإنْسانِ أمْرَ نَفْسهِ.', 'The greatest ignorance is the ignorance of a person about himself.', 'Ghurar al-Hikam, Ignorance §7', 'wisdom'),
  ('اَلجَهْلُ وَبالٌ.', 'Ignorance is a curse.', 'Ghurar al-Hikam, Ignorance §9', 'wisdom'),
  ('اَلجَهْلُ مَوتٌ.', 'Ignorance is [a form of] death.', 'Ghurar al-Hikam, Ignorance §10', 'wisdom'),
  ('اَلنَّاسُ أعْداءُ ما جَهِلُوا.', 'People are enemies of that which they are ignorant of.', 'Ghurar al-Hikam, Ignorance §11', 'wisdom'),
  ('اَلجاهِلُ لَنْ يُلْقى أبَداً إلا مُفَرِّطاً، أو مُفْرِطاً.', 'An ignorant person is never found to be anything but falling short or excessive.', 'Ghurar al-Hikam, The Ignorant And The Foolish §1', 'wisdom'),
  ('اَلجاهِلُ لايَرْتَدِعُ، وبِالمَواعِظِ لا يَنْتَفِعُ.', 'Neither does an ignorant restrain himself [from wrongdoing] nor does he benefit from good advice.', 'Ghurar al-Hikam, The Ignorant And The Foolish §2', 'wisdom'),
  ('اَلجاهِلُ مَنْ أطاعَ هَواهُ في مَعصيَةِ رَبِّهِ.', 'An ignorant person is one who obeys his vain desires in disobedience to his Lord.', 'Ghurar al-Hikam, The Ignorant And The Foolish §3', 'wisdom'),
  ('اَلجاهِلُ يَسْتَوْحِشُ مِمّا يَأنَسُ بِه الحَكيْمُ.', 'The ignorant person feels aversion towards that which the wise person feels at ease with.', 'Ghurar al-Hikam, The Ignorant And The Foolish §4', 'wisdom'),
  ('اَلجاهِلُ لايَعْرِفُ العالِمَ لأنَّهُ لَمْ يَكُنْ قَبْلُ عالِماً.', 'The ignorant person does not understand the learned because he [himself] was never learned before.', 'Ghurar al-Hikam, The Ignorant And The Foolish §5', 'wisdom'),
  ('اَلجاهِلُ لا يَعْرِفُ تَقْصيرَهُ، وَلايَقْبَلُ مِنَ النَّصيحِ لهُ.', 'An ignorant person does not recognize his failure and does not accept the [good] advice given to him.', 'Ghurar al-Hikam, The Ignorant And The Foolish §6', 'wisdom'),
  ('اَلجاهِلُ يَعْتَمِدُ عَلى أمَلِهِ، ويُقَصِّرُ في عَمَلِهِ.', 'An ignorant person relies on his hopes and is negligent in his actions.', 'Ghurar al-Hikam, The Ignorant And The Foolish §7', 'wisdom'),
  ('اَلجاهِلُ صَخْرَةٌ لا يَنْفَجِرُ ماؤُها، وَشَجَرَةٌ لايَخْضَرُّعُودُها، وأرضٌ لايَظهَرُ عُشْبُها.', 'The ignorant person is like a rock through which water does not gush forth, and a tree, the branches of which do not become green, and a ground upon which foliage is not found.', 'Ghurar al-Hikam, The Ignorant And The Foolish §8', 'wisdom'),
  ('اَلْجاهِلُ مَيِّتٌ بَيْنَ الأحْياءِ.', 'An ignorant person is [like the] dead among the living.', 'Ghurar al-Hikam, The Ignorant And The Foolish §9', 'wisdom'),
  ('أشْقَى النّاسِ اَلجاهِلُ.', 'The most wretched of all people is the ignorant one.', 'Ghurar al-Hikam, The Ignorant And The Foolish §10', 'wisdom'),
  ('كَفى بِجَهَنَّمَ نَـكالاً.', 'Hell is sufficient as a punishment.', 'Ghurar al-Hikam, Hell Fire §1', 'wisdom'),
  ('وَقالَ ـ عَليه السّلامُ ـ في وَصْفِ جَهَنَّمَ: نارٌ شديدٌ كَلْبُها، عال لَحَبُها، ساطِعٌ لَهَبُها، مُتَأَجِّجٌ سَعيرُها، مُتَغَيِّظٌ زَفيرُها، بَعيدٌ خُمُودُها، ذاك وقُودُها، مُتَخَوِّفٌ وَعيدُها.', 'He (‘a) said in his description of hell: [It is] a fire whose burning is intense, its roar is loud, its flames are rising, its blaze is incinerating, its groans are terrifying, its abatement is remote, its fuel is igniting, [and] its horrors are terrifying.', 'Ghurar al-Hikam, Hell Fire §2', 'wisdom'),
  ('وقال ـ عليه السّلام ـ في وَصفِ جَهَنَّمِ: لايَظْعَنُ مُقيمُها، وَلا يُفادى أسيرُها، وَلا تُقْصَمُ كُبُولُها، لا مُدَّةَ لِلدّارِ فَتَفْنى، وَلا أجَلَ لِلْقَوْمِ فَيُقْضى.', 'He (‘a) said while describing hell: Its inmate cannot leave, its prisoner cannot be released by ransom and its shackles cannot be broken. This abode has no fixed age so that it may perish, nor is there a lifespan for its inmates that they may pass away.', 'Ghurar al-Hikam, Hell Fire §3', 'wisdom'),
  ('إنَّ أهْلَ النّارِ كُلُّ كَفُور مَكُور.', 'Verily all disbelieving schemers are inmates of the fire.', 'Ghurar al-Hikam, Hell Fire §4', 'wisdom'),
  ('وقالَ ـ عَليه السّلام ـ في وَصْفِ النّارِ: غَمِرٌ قَرارُها، مُظْلِمَةٌ أقْطارُها، حامِيَةٌ قُدُورُها، فَظيعَةٌ أُمُورُها.', 'He (‘a) also said in his description of hellfire: Its pits are engulfed [with fire], its sides are pitch-dark, its vessels are scorching hot and everything about it is horrid.', 'Ghurar al-Hikam, Hell Fire §5', 'wisdom'),
  ('لَنْ يَنْجُوَ مِنَ النّارِ إلاّ التّارِكُ عَمَلَها.', 'None will be saved from the fire of hell except the one who abandons its actions (i.e. the actions that lead to it).', 'Ghurar al-Hikam, Hell Fire §6', 'wisdom'),
  ('لَيْسَ لِهذا الجِلْدِ الرَّقيقِ صَبْرٌ عَلَى النّارِ.', 'This tender skin does not have the tolerance to withstand the fire [of hell].', 'Ghurar al-Hikam, Hell Fire §7', 'wisdom'),
  ('مَنْ أشْفَقَ مِنَ النّارِ اجْتَنَبَ المُحَرَّماتِ.', 'One who is afraid of hellfire keeps away from that which has been forbidden.', 'Ghurar al-Hikam, Hell Fire §8', 'wisdom'),
  ('وَفْدُ النّارِ أبَداً مُعَذَّبُونَ.', 'The inmates of hell are eternally tormented.', 'Ghurar al-Hikam, Hell Fire §9', 'wisdom'),
  ('وارِدُ النّارِ مَؤَبَّدُ الشَّقاءِ.', 'The one who enters hellfire is forever wretched.', 'Ghurar al-Hikam, Hell Fire §10', 'wisdom'),
  ('مَنْ أحَبَّنا بِقَلْبِهِ وَكانَ مَعَنا بِلِسانِهِ وقاتَلَ عَدُوَّنا بِسَيْفِهِ فَهُوَ مَعَنا فيِ الْجَنَّةِ في دَرَجَتِنا.', 'Whoever loves us with his heart, supports us with his speech and fights our enemies with his sword, then he will be with us in Paradise at our stage.', 'Ghurar al-Hikam, Lovers Of The Ahlulbayt §1', 'wisdom'),
  ('مَنْ أحَبَّنا بِقَلْبِهِ وأعانَنا بِلِسانِهِ ولَمْ يُقاتِلْ مَعَنا بِيَدِهِ فَهُوَ فِي الْجَنَّةِ دُونَ دَرَجَتِنا.', 'Whoever loves us with his heart and supports us with his speech but does not fight alongside us with his hand, then he will be in Paradise but not at our stage.', 'Ghurar al-Hikam, Lovers Of The Ahlulbayt §2', 'wisdom'),
  ('مَنْ أحَبَّنا بِقَلْبِهِ وأبْغَضَنا بِلِسانِهِ فَهُوَ فِي الْجَنَّةِ.', 'Whoever loves us with his heart but pretends to hate us with his tongue will go to Paradise.', 'Ghurar al-Hikam, Lovers Of The Ahlulbayt §3', 'wisdom'),
  ('مَنْ أحَبَّنا فَلْيَعْمَلْ بِعَمَلِنا، ولْيَتَجَلْبَبِ الْوَرَعَ.', 'He who loves us should emulate our actions and clothe himself with piety.', 'Ghurar al-Hikam, Lovers Of The Ahlulbayt §4', 'wisdom'),
  ('مَنْ أحَبَّنا فَلْيُعِدَّ لِلْبَلاءِ جِلْباباً.', 'One who loves us should prepare to be covered with afflictions.', 'Ghurar al-Hikam, Lovers Of The Ahlulbayt §5', 'wisdom'),
  ('مَنْ تَوَلانا فَلْيَلْبَسْ لِلْمِحَنِ إهاباً.', 'One who befriends us should have a thick skin for tribulations [that will befall him].', 'Ghurar al-Hikam, Lovers Of The Ahlulbayt §6', 'wisdom'),
  ('هَلَكَ فِيَّ رَجُلانِ: مُحِبٌّ غال، ومُبْغِضٌ قال.', 'Two types of people are destroyed because of me: the fanatic lover and the extreme hater.', 'Ghurar al-Hikam, Lovers Of The Ahlulbayt §7', 'wisdom'),
  ('لَوْ أحَبَّنِي جَبَلٌ لَتَهافَتَ.', 'If a mountain loved me, it would crumble.', 'Ghurar al-Hikam, Lovers Of The Ahlulbayt §8', 'wisdom'),
  ('فَقْدُ الأحِبَّةِ غُرْبَةٌ.', 'Losing a loved one leads to forlornness.', 'Ghurar al-Hikam, The Beloved §1', 'wisdom'),
  ('مَنْ أَحَبَّكَ نَهاكَ.', 'One who loves you forbids you [from evil].', 'Ghurar al-Hikam, The Beloved §2', 'wisdom'),
  ('مَنْ أَحَبَّ شَيْئاً لَهِجَ بِذِكْرِهِ.', 'One who loves something speaks about it constantly.', 'Ghurar al-Hikam, The Beloved §3', 'wisdom'),
  ('إنَّما يُحِبُّكَ مَنْ لايَتَمَلَّقُكَ ويُثْني عَلَيْكَ مَنْ لايُسْمِعُكَ.', 'Indeed only he who does not flatter you loves you, and only he who does not let you hear [his praise] praises you.', 'Ghurar al-Hikam, The Beloved §4', 'wisdom'),
  ('لِيَكُنْ أحَبُّ النَّاسِ إلَيْكَ وأخْظاهُمْ لَدَيْكَ أكْثَرُهُمْ سَعْياً في مَنافِعِ النّاسِ.', 'Let the most beloved person to you and the one who has the greatest status in your eyes be the one who strives hardest in benefiting people.', 'Ghurar al-Hikam, The Beloved §5', 'wisdom'),
  ('لِيَكُنْ أحَبُّ النّاسِ إلَيْكَ المُشْفِقُ النّاصِحُ.', 'Let the most beloved person to you be the compassionate adviser.', 'Ghurar al-Hikam, The Beloved §6', 'wisdom'),
  ('قُوَّةُ سُلْطانِ الحُجَّةِ أعْظَمُ مِنْ قَوَّةِ سُلْطانِ القُدْرَةِ.', 'The strength of the authority of evidence is stronger than the strength of the authority of force.', 'Ghurar al-Hikam, Evidence §1', 'wisdom'),
  ('لَمْ يُخْلِ اللّهُ سُبْحانَهُ عِبادَهُ مِنْ حُجَّة لازِمَة أوْ مَحَجَّة قائِمَة.', 'Allah, the Glorified, never leaves His servants without a necessary proof or an established, clear path.', 'Ghurar al-Hikam, The Proof (Of Allah) §1', 'wisdom'),
  ('لَمْ يَتْرُكِ اللّهُ سُبْحانَهُ خَلْقَهُ مُغْفَلاً، ولا أمْرَهُمْ مُهْمَلاً.', 'Allah, the Glorified, does not leave His creation unheeded, nor does He neglect their affairs.', 'Ghurar al-Hikam, The Proof (Of Allah) §2', 'wisdom'),
  ('لاحَقَّ لِمَحْجُوج.', 'One who is disproved has no right.', 'Ghurar al-Hikam, The Disproved §1', 'wisdom'),
  ('قَدْ يَسْتَظْهِرُ المُحْتَجُّ.', 'The one who presents a strong argument may get support.', 'Ghurar al-Hikam, The One Who Presents An Argument §1', 'wisdom'),
  ('مَنِ احْتَجَّ بِالحَقِّ فَلَجَ.', 'One who argues by truth, succeeds.', 'Ghurar al-Hikam, The One Who Presents An Argument §2', 'wisdom'),
  ('والحَجَّ تَقْوِيَةً لِلّدينِ.', 'The Hajj is a means of strengthening the religion.', 'Ghurar al-Hikam, The Hajj §1', 'wisdom'),
  ('اَلحِدَّةُ ضَرْبٌ مِنَ الجُنُونِ، لأنَّ صاحِبَها يَنْدَمُ، فَإنْ لَمْ يَنْدَمْ فَجُنُونُهُ مُسْتَحْكَمٌ.', 'Rage is a bout of insanity because its possessor regrets [afterwards], but if he does not feel regret, then his insanity is firmly established.', 'Ghurar al-Hikam, Rage §1', 'character'),
  ('دَعِ الحِدَّةَ، وتَفَكَّرْ فِي الحُجَّةِ، وتَحَفَّظْ مِنَ الخَطَلِ تَأمَنِ الزَّلَلَ.', 'Repel [your] rage, think about the proof and protect yourself from nonsense - you will be safe from slip-ups.', 'Ghurar al-Hikam, Rage §2', 'character'),
  ('قَدْ يَعْطِبُ المُتَحَذِّرُ.', 'One who is overly cautious may be destroyed.', 'Ghurar al-Hikam, The Cautious §1', 'wisdom'),
  ('مِنْ مَأْمَنِهِ يُؤْتَي الحَذِرُ.', 'Harm comes to the cautious one from his [own] place of security.', 'Ghurar al-Hikam, The Cautious §2', 'wisdom'),
  ('مَنْ حَذَّرَكَ كَمَنْ بَشَّـرَكَ.', 'One who warns you is like the one who brings you glad tidings.', 'Ghurar al-Hikam, The Warner §1', 'wisdom'),
  ('اَلجُنُودُ عِزُّ الدّينِ، وحُصُونُ الوُلاةِ.', 'Soldiers [who fight for Islam] are the glory of religion and the bastions of [its] leaders.', 'Ghurar al-Hikam, War, Soldiers And Armies §1', 'wisdom'),
  ('اَلفِرارُ في أوانِهِ يَعْدِلُ الظَّفَرَ في زَمانِه.', 'Fleeing at the right moment is equivalent to victory in its time.', 'Ghurar al-Hikam, War, Soldiers And Armies §2', 'wisdom'),
  ('اَلجُنُودُ حُصُونُ الرَّعِيَّةِ.', 'Soldiers are defenders of the people.', 'Ghurar al-Hikam, War, Soldiers And Armies §3', 'wisdom'),
  ('آفَةُ الجُنْدِ مُخالَفَةُ القادَةِ.', 'The bane of an army is opposing its commanders.', 'Ghurar al-Hikam, War, Soldiers And Armies §4', 'wisdom'),
  ('مَنْ خَذَلَ جُنْدَهُ نَصَرَ أضْدادَهُ.', 'One who abandons his army has helped his adversaries.', 'Ghurar al-Hikam, War, Soldiers And Armies §5', 'wisdom'),
  ('غُضُّواالأبْصارَ في الحُرُوبِ، فَإنَّهُ أرْبَطُ لِلْجَأْشِ، وأسْكَنُ لِلْقُلوُبِ.', 'Cast down your gaze in battles, for this will make you calmer and cause your hearts to be more tranquil.', 'Ghurar al-Hikam, War, Soldiers And Armies §6', 'wisdom'),
  ('قَدِّمُوا الدّارِعَ، وأخِّرُوا الحاسِرَ، وعَضُّوا عَلَى الأضْراسِ، فَإنَّهُ أنْبا لِلسُّيُوفِ عَنِ الْهامِ.', 'Put the armoured man forward and the unarmoured one behind, and grit your teeth because this will make the swords skip off the skulls.', 'Ghurar al-Hikam, War, Soldiers And Armies §7', 'wisdom'),
  ('وَمَنْ هالَهُ مابَيْنَ يَدَيْهِ نَـكَصَ عَلى عَقِبَيْهِ.', 'He who is frightened by what is in front of him retreats [and flees].', 'Ghurar al-Hikam, War, Soldiers And Armies §8', 'wisdom'),
  ('نافِحُوا بِالظُّبى، وَصِلُوا السُّيُوفَ بالخُطى، وطيبُوا عَنْ أنْفُسِكُمْ نَفْساً، وامْشُوا إلَى المَوْتِ مَشْياً سَجْحاً.', 'Defend [yourselves] with the edge of blades, charge forward [against the enemy] with your swords, give up your lives [for the sake of Allah] and walk towards death with calm.', 'Ghurar al-Hikam, War, Soldiers And Armies §9', 'wisdom'),
  ('والَّذي فَلَقَ الحَبَّةَ وبَـرَأَ النَّسَمَةَ، ما أسْلَمُوا، ولكِنِ اسْتَسْلَمُوا، وَأسَـرُّوا الكُفْرَ، فَلَمّا وَجَدُوا أعْواناً عَلَيْهِ أعْلَنُوا ما كانُوا أسَـرُّوا، وأظْهَرُوا ما كانُوا أبْطَنُوا.', 'By the one who splits the seed and creates the human being! They did not accept Islam, rather they succumbed to it [to remain safe] and hid their disbelief; and when they found supporters for it, they brought forth in the open that which they had hidden and made manifest that which they had concealed.', 'Ghurar al-Hikam, War, Soldiers And Armies §10', 'wisdom'),
  ('مَنْ عانَدَ اللّهَ قُصِمَ.', 'One who opposes Allah is crushed.', 'Ghurar al-Hikam, Waging War §1', 'wisdom'),
  ('مَنْ حارَبَ اللّهَ حُرِبَ.', 'One who fights against Allah is ruined.', 'Ghurar al-Hikam, Waging War §2', 'wisdom'),
  ('إنَّكَ إنْ حارَبْتَ اللّهَ حُرِبْتَ وهَلَكْتَ.', 'Indeed, if you fight against Allah, you will be defeated and destroyed.', 'Ghurar al-Hikam, Waging War §3', 'wisdom'),
  ('مَنْ حارَبَ النّاسَ حُرِبَ، ومَنْ أمِنَ السَّلَبَ سُلِبَ.', 'One who fights against the people will be fought and one who considers himself to be safe from plunder will be plundered.', 'Ghurar al-Hikam, Waging War §4', 'wisdom'),
  ('اَلْحُرُّ حُرٌّ وإنْ مَسَّهُ الضُّـرُّ.', 'The freeman is free even if hardship befalls him.', 'Ghurar al-Hikam, Freedom And The Free §1', 'wisdom'),
  ('اَلحُرِّيَةُ مُنَزَّهَةٌ مِنَ الْغِلِّ والْمَكْرِ.', 'Liberty is free of malice and deception.', 'Ghurar al-Hikam, Freedom And The Free §2', 'wisdom'),
  ('قَدْ يُضامُ الحُرُّ.', 'Sometimes the free man may be treated unjustly.', 'Ghurar al-Hikam, Freedom And The Free §3', 'wisdom'),
  ('لَنْ يُتَعَبَّدَ الحُرُّ حَتّى يُزالَ عَنْهُ الضُّـرُّ.', 'The free man will never become enslaved until distress is removed from him.', 'Ghurar al-Hikam, Freedom And The Free §4', 'wisdom'),
  ('لَيْسَ لِلأحْرارِ جَزاءٌ إلاّ الإكْرامُ.', 'There is no reward for the free except honour [and respect].', 'Ghurar al-Hikam, Freedom And The Free §5', 'wisdom'),
  ('لاتَـكُونَنَّ عَبْدَ غَيْرِكَ، وَقَدْ جَعَلَكَ اللّهُ سُبْحانَهُ حُرّاً، فَما خَيْرُ خَيْر لايُنالُ إلاّ بِشَـرّ، ويُسْـر لايُنالُ إلاّ بِعُسْر.', 'Do not be a slave to others while Allah, the Glorified, has made you free, for that which is good is never achieved except by overcoming evil, and ease is never acquired except through difficulty.', 'Ghurar al-Hikam, Freedom And The Free §6', 'wisdom'),
  ('اَلمُحْتَرِسُ مُلَقًّي.', 'One who is [overly] careful [not to put himself in any harm] is thrown [into it].', 'Ghurar al-Hikam, The Careful §1', 'wisdom'),
  ('مَنْ كَثُرَ احْتِراسُهُ سَلِمَ غَيْبُهُ.', 'One whose carefulness increases, his unseen [future] becomes sound.', 'Ghurar al-Hikam, The Careful §2', 'wisdom'),
  ('الحِرْصُ ذُلٌّ ومَهانَةٌ لِمَنْ يَسْتَشْعِرُهُ.', 'Greed is a disgrace and a humiliation for the one who espouses it.', 'Ghurar al-Hikam, Greed §1', 'wisdom'),
  ('اَلحِرْصُ رَأسُ الفَقْرِ، وأُسُّ الشَّـرِّ.', 'Greed is the cornerstone of poverty and the foundation of evil.', 'Ghurar al-Hikam, Greed §2', 'wisdom'),
  ('اَلحِرْصُ أحَدُ الشِّقائَيْنِ.', 'Greed is one of the two miseries.', 'Ghurar al-Hikam, Greed §3', 'wisdom'),
  ('اَلحِرْصُ، والشَّـرَهُ، والبُخْلُ، نَتيجَةُ الجَهْلِ.', 'Greed, gluttony and stinginess are the result of ignorance.', 'Ghurar al-Hikam, Greed §4', 'wisdom'),
  ('اَلحِرْصُ لايَزيدُ فِي الرِّزْقِ، ولكِنْ يُذِلُّ القَدْرَ.', 'Greed does not increase sustenance, rather it debases one’s status.', 'Ghurar al-Hikam, Greed §5', 'wisdom'),
  ('إنْتَقِمْ مِنْ حِرْصِكَ بِالقُنُوعِ، كَما تَنْتَقِمُ مِنْ عَدُوِّكَ بِالقِصاصِ.', 'Take revenge on your greed through contentment, just as you would avenge your enemy by retaliation.', 'Ghurar al-Hikam, Greed §6', 'wisdom'),
  ('إتَّقُوا الحِرْصَ، فَإنَّ صاحِبَهُ رَهينُ ذُلّ وعَناء.', 'Be cautious of greed, for its possessor is subject to humiliation and suffering.', 'Ghurar al-Hikam, Greed §7', 'wisdom'),
  ('إيّاكَ والحِرْصَ فَإنَّهُ شَيْنُ الدّينِ، وبِئْسَ القَرينُ.', 'Be wary of greed, for it is a disgrace to the religion and the worst companion.', 'Ghurar al-Hikam, Greed §8', 'wisdom'),
  ('إنَّ فِي الحِرْصِ لَعَناءً.', 'Verily in greed there is suffering.', 'Ghurar al-Hikam, Greed §9', 'wisdom'),
  ('اَلحِرْصُ عَلامَةُ الفَقْرِ.', 'Greed is a sign of penury.', 'Ghurar al-Hikam, Greed §11', 'wisdom'),
  ('اَلْحَريصُ فَقِيْرٌ، ولَوْ مَلَكَ الدُّنيا بِحَذافيرِها.', 'The one who is greedy is poor, even if he owns the whole world in its entirety.', 'Ghurar al-Hikam, The Greedy §1', 'wisdom'),
  ('اَلْحَريصُ تَعِبٌ.', 'The greedy one is [always] weary.', 'Ghurar al-Hikam, The Greedy §2', 'wisdom'),
  ('اَلْحَريصُ لايَكْتَفي.', 'The greedy one is never satisfied.', 'Ghurar al-Hikam, The Greedy §3', 'wisdom'),
  ('اَلْحَريصُ عَبْدُ المَطامِعِ.', 'The greedy person is a slave to [his] desires.', 'Ghurar al-Hikam, The Greedy §4', 'wisdom'),
  ('اَلْحَريصُ مَتْعُوبٌ فيما يَضُـرُّهُ.', 'The greedy person toils for that which will harm him.', 'Ghurar al-Hikam, The Greedy §5', 'wisdom'),
  ('اَلشَّـرِهُ لايَرْضى.', 'The glutton is never satisfied.', 'Ghurar al-Hikam, The Greedy §6', 'wisdom'),
  ('اَلْحَريصُ أسيرُ مَهانَة لايُفَكُّ أسْـرُهُ.', 'The greedy one is a prisoner of disgrace, never to be freed from his prison.', 'Ghurar al-Hikam, The Greedy §7', 'wisdom'),
  ('إنْ كُنْتَ حَريصاً عَلى طَلَبِ المَضْمُونِ لَكَ فَكُنْ حَريصاً عَلى أداءِ المَفْرُوضِ عَلَيْكَ.', 'If you are greedy in your desire for that which has been guaranteed to you (i.e. your sustenance) then be avid in performing that which has been made incumbent upon you.', 'Ghurar al-Hikam, The Greedy §8', 'wisdom'),
  ('عَجِبْتُ لِمَنْ عَلِمَ أنَّ اللّهَ قَدْ ضَمِنَ الأرْزاقَ، وقَدَّرَها، وأنَّ سَعْيَهُ لايَزيدُهُ فيما قُدِّرَ لَهُ مِنْها، وهُوَ حَريصٌ دائِبٌ في طَلَبِ الرِّزْقِ.', 'I wonder at the one who knows that Allah has guaranteed sustenance and allotted it, and that his effort will not increase what has [already] been allotted for him of it, yet he is greedy and unrelenting in his desire for [more] wealth.', 'Ghurar al-Hikam, The Greedy §10', 'wisdom'),
  ('كُلُّ حَريص فَقيرٌ.', 'Every greedy person is needy.', 'Ghurar al-Hikam, The Greedy §11', 'wisdom'),
  ('عَلى قَدْرِ الحِرمانِ تَـكُونُ الحِرْفَةُ.', 'The vocation [one undertakes] is based on the extent of deprivation.', 'Ghurar al-Hikam, Vocation §1', 'wisdom'),
  ('اَلْحِرفَةُ مَعَ العِفَّةِ خَيْـرٌ مِنَ الغِنى مَعَ الفُجُورِ.', 'A [simple] vocation with modesty is better than affluence with immorality.', 'Ghurar al-Hikam, Vocation §2', 'wisdom'),
  ('اَلحَرامُ سُحْتٌ.', 'The prohibited is illicit.', 'Ghurar al-Hikam, The Prohibited §1', 'wisdom'),
  ('اَلحِرمانُ خِذْلانٌ.', 'Deprivation is abandonment.', 'Ghurar al-Hikam, Deprivation And Frustration §1', 'wisdom'),
  ('عَجِبْتُ لِمَنْ يَرْجُو فَضْلَ مَنْ فَوْقَهُ، كَيْفَ يَحْرُمُ مَنْ دُونَهُ.', 'I wonder at the person who hopes for favour from the one who is above him, how can he deprive the one who is below him [of his own favour]?', 'Ghurar al-Hikam, Deprivation And Frustration §2', 'wisdom'),
  ('لَنْ تَسْكُنَ حُرْقَةُ الحِرْمانِ حَتّى يَتَحَقَّقَ الوِجْدانُ.', 'The anguish of deprivation will not be calmed until acquisition is realized.', 'Ghurar al-Hikam, Deprivation And Frustration §3', 'wisdom'),
  ('لاتَحْرِمِ المُضْطَرَّ وإنْ أسْرَفَ.', 'Do not deprive the distressed even if he is extravagant.', 'Ghurar al-Hikam, Deprivation And Frustration §4', 'wisdom'),
  ('لاتُخَيِّبِ المُحْتاجَ وَإنْ ألْحَفَ.', 'Do not frustrate the needy even if he insists [for more].', 'Ghurar al-Hikam, Deprivation And Frustration §5', 'wisdom'),
  ('أَيَسُـرُّكَ أنَ تَـكُوْنَ مِنْ حِزْبِ اللّهِ الغالِبينَ: إتَّقِ اللّهَ سُبْحانَهُ، وأحْسِنْ في كُلِّ أُمُورِكَ، فَإنَّ اللّهَ مَعَ الَّذينَ اتَّقَوْا والَّذينَ هُمْ مُحْسِنُونَ.', 'Would you like to be among the victorious party of Allah? [Then] fear Allah, the Glorified, and be righteous in all your affairs, for surely Allah is with those who guard [against evil] and those who go good [to others].', 'Ghurar al-Hikam, The Party Of Allah §1', 'wisdom'),
  ('اَلْحَزْمُ تَجَرُّعُ الغُصَّةِ، حَتّى تُمَكِّنَ الفُرْصَةُ.', 'Judiciousness means enduring agony until the opportunity [to react] avails itself.', 'Ghurar al-Hikam, Judiciousness §1', 'wisdom'),
  ('أواخِرُ مَصادِرِ التَّوَقّي أوائِلُ مَوارِدِ الحَذَرِ.', 'The last sources of self-preservation are the first points of caution.', 'Ghurar al-Hikam, Judiciousness §2', 'wisdom'),
  ('اَلحَزْمُ اَلنَّظَرُ فِي العَواقِبِ، ومُشاوَرَةُ ذَوِي العُقُولِ.', 'Judiciousness is considering the consequences [of actions] and consulting the wise.', 'Ghurar al-Hikam, Judiciousness §3', 'wisdom'),
  ('ألا وإنَّ مَنْ تَوَرَّطَ فِي الأُمُورِ مِنْ غَيْرِ نَظَر فِي العَواقِبِ فَقَدْ تَعَرَّضَ لِمُفْدِحاتِ النَّوائِبِ.', 'Indeed, the one who gets involved in matters without thinking about the consequences is vulnerable to grave calamities.', 'Ghurar al-Hikam, Judiciousness §4', 'wisdom'),
  ('أصْلُ العَزْمِ الحَزْمُ، وثَمَرَتُهُ اَلظَّفَرُ.', 'The root of determination is judiciousness, and its fruit is victory.', 'Ghurar al-Hikam, Judiciousness §5', 'wisdom'),
  ('اَلْحَزْمُ بِضاعَةٌ (و) التَّواني إضاعَةٌ.', 'Judiciousness is a provision and negligence is a loss.', 'Ghurar al-Hikam, Judiciousness §6', 'wisdom'),
  ('اَلحَزْمُ صِناعَةٌ.', 'Judiciousness is a skill.', 'Ghurar al-Hikam, Judiciousness §7', 'wisdom'),
  ('اَلحَزْمُ أسَدُّ الآراءِ.', 'Judiciousness is [having] the most pertinent of views.', 'Ghurar al-Hikam, Judiciousness §8', 'wisdom'),
  ('اَلحَزْمُ حِفْظُ التَجْرِبَةِ.', 'Judiciousness is preserving the [lessons learned through] experience.', 'Ghurar al-Hikam, Judiciousness §9', 'wisdom'),
  ('اَلحَزْمُ بِإجالَةِ الرَّأْيِ.', 'Judiciousness is [achieved] through weighing the opinions thoroughly.', 'Ghurar al-Hikam, Judiciousness §10', 'wisdom'),
  ('اَلحازِمُ مَنْ لا يَشْغَلُهُ النِّعْمَةُ عَنِ العَمَلِ لِلْعاقِبَةِ.', 'The judicious person is one who does not get too preoccupied with the blessing [he has been given] to work for his afterlife.', 'Ghurar al-Hikam, The Judicious §1', 'wisdom'),
  ('اَلحازِمُ مَنْ جادَ بِما في يَدِهِ، ولَمْ يُؤَخِّرْ عَمَلَ يَومِهِ إلى غَدِهِ.', 'The judicious person is one who is generous with what he has in his possession and does not postpone his work of today to tomorrow.', 'Ghurar al-Hikam, The Judicious §2', 'wisdom'),
  ('اَلحازِمُ مَنْ لَمْ يَشْغَلْهُ غُرُورُ دُنْياهُ عَنِ العَمَلِ لاُخْراهُ.', 'The judicious person is one who is not too preoccupied with the deceptions of his world to work for his Hereafter.', 'Ghurar al-Hikam, The Judicious §3', 'wisdom'),
  ('اَلحازِمُ مَنْ دارى زَمانَهُ.', 'The judicious person is one who is amicable with [the people of] his time.', 'Ghurar al-Hikam, The Judicious §4', 'wisdom'),
  ('اَلحازِمُ مَنْ حَنَّكَتْهُ التَّجارِبُ، وهَذَّبَتْهُ النَّوائِبُ.', 'The judicious person is one who has been made worldly-wise by experience and refined by calamities.', 'Ghurar al-Hikam, The Judicious §5', 'wisdom'),
  ('اَلحازِمُ مَنْ شَكَرَ النِّعْمَةَ مُقْبِلَةً، وصَبَرَ عَنْها، وَسَلاها مُوَلِّيَةً مُدْبِرَةً.', 'The judicious person is one who gives thanks for blessings that come to him and is patient and thinks no more of it when the blessings turn away or turn back from him.', 'Ghurar al-Hikam, The Judicious §6', 'wisdom'),
  ('اَلحازِمُ مَنْ يُؤَخِّرُ العُقُوبَةَ في سُلْطانِ الغَضَبِ، ويُعَجِّلُ مُكافاةَ الإحْسانِ إغْتِناماً لِفُرْصَةِ الإمكانِ.', 'The judicious person is one who delays meting out punishment when [he is] under the yoke of anger and expedites the repayment of favours by taking advantage of the available opportunity.', 'Ghurar al-Hikam, The Judicious §7', 'wisdom'),
  ('أحْزَمُكُمْ أزْهَدُكُمْ.', 'The most judicious of you is the most abstemious of you [from worldly pleasures].', 'Ghurar al-Hikam, The Judicious §8', 'wisdom'),
  ('أحْزَمُ النّاسِ مَنِ اسْتَهانَ بِأمْرِ دُنْياهُ.', 'The most judicious of all people is one who deems his worldly affairs to be unimportant.', 'Ghurar al-Hikam, The Judicious §9', 'wisdom'),
  ('أحْزَمُ النّاسِ مَنْ تَوَهَّمَ العَجْزَ لِفَرْطِ اسْتِظْهارِهِ.', 'The most judicious of people is the one who presumes his inability despite having numerous supporters.', 'Ghurar al-Hikam, The Judicious §10', 'wisdom'),
  ('لاتَأْسَ عَلى ما فاتَ.', 'Do not grieve for that which is lost.', 'Ghurar al-Hikam, Grief For What Has Been Lost §1', 'wisdom'),
  ('اَلحِسابُ قَبْلَ العِقابِ، اَلثَّوابُ بَعْدَ الحِسابِ.', 'The reckoning is before the punishment and the reward is after the reckoning.', 'Ghurar al-Hikam, The Reckoning §1', 'wisdom'),
  ('لاجَمالَ كَالْحَسَبِ.', 'There is no beauty like high regard.', 'Ghurar al-Hikam, High Regard §1', 'wisdom'),
  ('اَلْحَسَدُ أحَدُ العَذابَيْنِ.', 'Jealousy is one of the two torments.', 'Ghurar al-Hikam, Jealousy §1', 'wisdom'),
  ('اَلْحَسَدُ اَلأَمُ الرَّذِيْلَتَيْنِ.', 'Jealousy is the viler of the two depravities.', 'Ghurar al-Hikam, Jealousy §2', 'wisdom'),
  ('اَلْحَسَدُ داءٌ عَياءٌ، لايَزُولُ إلاّ بِهَلْكِ الحاسِدِ، أوْ مَوْتِ المَحْسُودِ.', 'Jealousy is an incurable disease, it does not end except by the destruction of the envier or the death of the envied.', 'Ghurar al-Hikam, Jealousy §3', 'wisdom'),
  ('اَلْحَسَدُ يَأكُلُ الحَسَناتِ كَما تَأكُلُ النّارَ الحَطَبَ.', 'Jealousy eats away good deeds just like fire consumes firewood.', 'Ghurar al-Hikam, Jealousy §4', 'wisdom'),
  ('اَلْحَسَدُ عَيْبٌ فاضِحٌ، وشُحٌّ (شَجىٌّ)فادِحٌ، لايَشْفي صاحِبَهُ إلاّ بُلُوغُ آمالِهِ فيمَنْ يَحْسُدُهُ.', 'Jealousy is a shameful flaw and a gross deficiency; one who possesses it is not cured except by realizing his hopes about the one whom he envies.', 'Ghurar al-Hikam, Jealousy §5', 'wisdom'),
  ('إحْذَرُوا الحَسَدَ، فَإنَّهُ يُزْري بِالنَّفْسِ.', 'Be cautious of jealousy, for it disparages the self.', 'Ghurar al-Hikam, Jealousy §6', 'wisdom'),
  ('إيّاكَ والحَسَدَ، فَإنَّهُ شَـرُّ شيمَة، وأقْبَحُ سَجِيَّة، وخَليقَةُ إبْلِيسَ.', 'Be wary of jealousy for it is the worst quality, the ugliest attribute and the trait of the Devil.', 'Ghurar al-Hikam, Jealousy §7', 'wisdom'),
  ('اَلْحَسَدُ يُضْني.', 'Jealousy is stressful.', 'Ghurar al-Hikam, Jealousy §8', 'wisdom'),
  ('اَلْحَسَدُ شَـرُّ الأمْراضِ.', 'Jealousy is the worst of diseases.', 'Ghurar al-Hikam, Jealousy §9', 'wisdom'),
  ('اَلْحَسَدُ حَبْسُ الرُّوحِ.', 'Jealousy is imprisonment of the soul.', 'Ghurar al-Hikam, Jealousy §10', 'wisdom'),
  ('اَلْحَسُودُ، والحَقُودُ لاتَدُومُ لَهُما مَسَـرَّةٌ.', 'Happiness does not last for the jealous and the spiteful.', 'Ghurar al-Hikam, The Jealous §1', 'wisdom'),
  ('اَلْحَسُودُ أبَداً عَليلٌ، والبَخيلُ أبَداً ذَلِيلٌ.', 'The jealous one is always ill and the miser is always abased.', 'Ghurar al-Hikam, The Jealous §2', 'wisdom'),
  ('اَلْحَسُودُ دائِمُ السُّقْمِ وإنْ كانَ صَحِيحَ الجِسْمِ.', 'The jealous one is always sick, even when his body is healthy.', 'Ghurar al-Hikam, The Jealous §3', 'wisdom'),
  ('اَلْحَسُودُ أبَداً عَلِيلٌ.', 'The jealous person is always ill.', 'Ghurar al-Hikam, The Jealous §4', 'wisdom'),
  ('اَلْحَسُودُ لايَبْرَءُ.', 'The jealous one is never cured.', 'Ghurar al-Hikam, The Jealous §5', 'wisdom'),
  ('اَلْحَسُودُ لايَسُودُ.', 'The jealous one never gains authority.', 'Ghurar al-Hikam, The Jealous §6', 'wisdom'),
  ('اَلْحَسُودُ غَضْبانٌ عَلَى القَدَرِ.', 'The jealous one is angry at destiny.', 'Ghurar al-Hikam, The Jealous §7', 'wisdom'),
  ('اَلْحَسُودُ كَثيرُ الحَسَراتِ، مُتَضاعِفُ السَّيـِّئاتِ.', 'The jealous one has many regrets and his sins are multiplied.', 'Ghurar al-Hikam, The Jealous §8', 'wisdom'),
  ('عِنْدَ تَظاهُرِ النِّعَمِ يَكْثُرُ الحُسّادُ.', 'When blessings are [openly] displayed, the enviers increase.', 'Ghurar al-Hikam, The Jealous §9', 'wisdom'),
  ('عَجِبْتُ لِغَفْلَةِ الحُسّادِ عَنْ سَلامَةِ الأجْسادِ.', 'I am amazed at the heedlessness of the jealous about the health of their bodies.', 'Ghurar al-Hikam, The Jealous §10', 'wisdom'),
  ('كُلُّ ذي رُتْبَة سَنِيَّة مَحْسُودٌ.', 'Every person of high rank is envied.', 'Ghurar al-Hikam, The Envied §1', 'wisdom'),
  ('قَدْ يَكْبُو الجَوادُ.', 'At times even a good steed may stumble.', 'Ghurar al-Hikam, The Sword And The Steed §1', 'wisdom'),
  ('قَدْ يَنْبُو الحُسامُ.', 'At times the [sharp] sword becomes blunt.', 'Ghurar al-Hikam, The Sword And The Steed §2', 'wisdom'),
  ('إكْتِسابُ الحَسَناتِ مِنْ أفْضَلِ المَكاسِبِ.', 'Acquiring of good deeds is one of the best of earnings.', 'Ghurar al-Hikam, Good Deeds §1', 'character'),
  ('لِكُلِّ حَسَنَة ثَوابٌ.', 'For every good deed there is recompense.', 'Ghurar al-Hikam, Good Deeds §2', 'character'),
  ('في كُلِّ حَسَنَة مَثُوبَةٌ.', 'In every good deed there is reward.', 'Ghurar al-Hikam, Good Deeds §3', 'character'),
  ('كُلُّ حَسَنَة لايُرادُ بِها وَجْهُ اللّهِ تَعالى فَعَلَيْها قُبْحُ الرِّياءِ وثَمَرَتُها قُبْحُ الْجَزاءِ.', 'Every good deed which is not done with the intention of seeking nearness to Allah, has the ugliness of ostentation in it and its fruit is an ugly requital.', 'Ghurar al-Hikam, Good Deeds §4', 'character'),
  ('اَلأخْدُ عَلَى العَدُوِّ بِالفَضْلِ أحَدُ الظَّفَرَيْنِ.', 'Showing kindness to the enemy is one of the two triumphs.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §1', 'character'),
  ('إتْباعُ الإحْسانِ بِالإحْسانِ مِنْ كَمالِ الجُودِ.', 'Following up one favour with another favour is from the perfection of munificence.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §2', 'character'),
  ('اَلإحْسانُ غَرِيزَةُ الأخْيارِ، والإساءَةُ غَرِيزَةُ الأشْرارِ.', 'Doing good is the nature of the righteous and doing evil is the nature of the wicked.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §3', 'character'),
  ('اَلكَرامَةُ تَُفْسُِدُ مِنَ اللَّئيمِ بِقَدْرِ ما تَُصْلَُحُ مِنَ الكَريمِ.', 'Benevolence from the wicked corrupts just as much as it reforms from the honourable.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §4', 'character'),
  ('اَلصَّنِيعَةُ إذا لَمْ تُرَبَّ أخْلَقَتْ، كَالثَّوْبِ البالي والأبْنِيَةِ المُتَداعِيَةِ.', 'If a righteous act is not nurtured, it wears away, just like worn out garments and dilapidated buildings.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §5', 'character'),
  ('أحْسِنْ تَسْتَرِقَّ.', 'Do good and you shall enthral.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §6', 'character'),
  ('أفْضِلْ تُقَدَّمْ.', 'Bestow goodness and you shall advance.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §7', 'character'),
  ('اِنْسَ رِفْدَكَ، أُذْكُرْ وَعْدَكَ.', 'Forget your gift, [and] remember your promise.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §9', 'character'),
  ('أعْطِ تَسْتَطِعْ(تَصْطَنِعْ).', 'Give and you shall become capable (or be chosen).', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §10', 'character'),
  ('اِنْعِمْ تُحْمَدْ.', 'Confer favours and you will be praised.', 'Ghurar al-Hikam, Good Turns And Benevolent Actions §12', 'character'),
  ('لايَكُنِ المُحْسِنُ والمُسيءُ عِنْدَكَ سَواءً، فَإنَّ ذلِكَ يُزَهِّدُ المُحْسِنَ فِي الإحْسانِ، ويُتابِـعُ المُسِيءَ إلَى الإسائَةِ.', 'Let not the good doer and the evildoer be equal in your eyes, for will make the good-doer abstain from his benevolence and will encourage the evildoer to continue his evil.', 'Ghurar al-Hikam, The Good Doer §1', 'character'),
  ('يَحْتاجُ ذُوالنّائِلِ إلَى السّائِلِ.', 'The charitable one needs the beggar.', 'Ghurar al-Hikam, The Good Doer §2', 'character'),
  ('كُنْ سَمِحاً ولاتَـكُنْ مُبَذِّراً.', 'Be open-handed but do not be wasteful.', 'Ghurar al-Hikam, The Good Doer §3', 'character'),
  ('اَلمُحْسِنُ مَنْ عَمَّ النّاسَ بِالإحْسانِ.', 'The good doer person is one who is benevolent to all people.', 'Ghurar al-Hikam, The Good Doer §4', 'character'),
  ('المُحْسِنُ مُعانٌ، اَلمُسِيءُ مُهانٌ.', 'The benevolent is supported, the malevolent is scorned.', 'Ghurar al-Hikam, The Good Doer §5', 'character'),
  ('المُحْسِنُ مَنْ صَدَّقَ أقْوالَهُ أفْعالُهُ.', 'The good doer is one whose words are affirmed by his actions.', 'Ghurar al-Hikam, The Good Doer §6', 'character'),
  ('المُحْسِنُ حَيٌّ وإنْ نُقِلَ إلى مَنازِلِ الأمـْواتِ.', 'The benevolent one is alive, even if he is transferred to the dwellings of the dead.', 'Ghurar al-Hikam, The Good Doer §7', 'character'),
  ('إذا رَأيْتُمُ الخَيْـرَ فَسارَعْتُمْ إلَيْهِ، ورَأيْتُمُ الشَّـرَّ فَتَباعَدتُمْ عَنْهُ، وكُنْتُمْ بِالطّاعاتِ عامِلِينَ، وفِي المَكارِمِ مُتَنافِسِينَ، كُنْتُمْ مُحْسِنينَ فائِزِينَ.', 'If you rush towards good whenever you see it, distance yourself from evil when you see it, act obediently [upon the commandments of Allah] and vie to acquire noble traits, then you are righteous and successful.', 'Ghurar al-Hikam, The Good Doer §8', 'character'),
  ('شَـرُّ المُحْسِنينَ اَلمُمْتَنُّ بِإحْسانِهِ.', 'The worst of the benevolent ones is the one who puts others under obligation by his favour.', 'Ghurar al-Hikam, The Good Doer §9', 'character'),
  ('صاحِبُ المَعْرُوفِ لايـَعْثُرُ، وإذا عَثَرَ وَجَدَ مُتَّكَأً.', 'The doer of good deeds does not stumble, and when he does stumble, he finds a support [to hold on to].', 'Ghurar al-Hikam, The Good Doer §10', 'character'),
  ('لايَنْفَعُ الحُسْنُ بِغَيْرِ نَجابَة.', 'Physical beauty is of no benefit without nobility.', 'Ghurar al-Hikam, Physical Beauty §1', 'character'),
  ('قُبْحُ الحَصَرِ خَيْـرٌ مِنْ جُرْحِ الهَذَرِ.', 'The ugliness of dyslogia is better than the harm of talking nonsense.', 'Ghurar al-Hikam, Dyslogia (The Inability To Express Oneself Effectively) §1', 'wisdom'),
  ('اَلحَصَرُ يُضَعِّفُ الحُجَّةَ.', 'The inability of effective expression weakens the argument.', 'Ghurar al-Hikam, Dyslogia (The Inability To Express Oneself Effectively) §2', 'wisdom'),
  ('اَلحَصَرُ خَيْرٌ مِنَ الهَذَرِ.', 'Dyslogia is better than babble.', 'Ghurar al-Hikam, Dyslogia (The Inability To Express Oneself Effectively) §3', 'wisdom'),
  ('اَلحَظُّ لِلإنْسانِ فِي الأُذُنِ لِنَفْسِهِ وَفِي اللِّسانِ لِغَيْرِهِ.', 'The fortune of a person that comes through the ears is for himself and that which is on the tongue for others.', 'Ghurar al-Hikam, Fortune §1', 'wisdom'),
  ('اَلحَظُّ يَسْعى إلى مَنْ لايَخْطُبُهُ.', 'Fortune rushes towards the one who does not seek it.', 'Ghurar al-Hikam, Fortune §2', 'wisdom'),
  ('اَلحُظْوَةُ عِنْدَ الخالِقِ بِالرَّغْبَةِ فيما لَدَيْهِ، اَلحُظْوَةُ عِنْدَ المَخْلُوقِ بِالرَّغْبَةِ عَمّا في يَدَيْهِ.', 'Favour is gained in the sight of the Creator by yearning for that which is with Him; favour is gained with the creatures by turning away from what they possess.', 'Ghurar al-Hikam, Gaining Favour §1', 'wisdom'),
  ('مَنْ حَفَرَ بِئْراً لأخيهِ أوْقَعَهُ اللّهُ في بِئْرِهِ.', 'One who digs a pit for his brother, Allah will cause him to fall in his [own] pit.', 'Ghurar al-Hikam, Digging A Pit For A Brother §1', 'wisdom'),
  ('مَنْ حَفَرَ لأخِيهِ المُؤْمِنِ بِئْراً أُوقِعَ فيها.', 'One who digs a pit for his believing brother will fall into it [himself].', 'Ghurar al-Hikam, Digging A Pit For A Brother §2', 'wisdom'),
  ('اَلحِقْدُ مِنْ طَبايِعِ الأشْرارِ.', 'Malice is from the nature of the wicked.', 'Ghurar al-Hikam, Spite And Malice §1', 'wisdom'),
  ('الحِقْدُ نارٌ لاتُطْفَيُ إلاّ بِالظَّفَرِ.(نارٌ كامِنَةٌ لايُطْفِئُها إلاّ مَوْتٌ أوْ ظَفَرٌ).', 'Spite is a fire that is not put out except by vanquish. (It is a raging fire that is not put out by anything other than death or vanquish).', 'Ghurar al-Hikam, Spite And Malice §2', 'wisdom'),
  ('اَلحِقْدُ يُذْرِي.', 'Malice wears away [its possessor].', 'Ghurar al-Hikam, Spite And Malice §3', 'wisdom'),
  ('اَلحِقْدُ شيمَةُ الحَسَدَةِ.', 'Spite is the trait of the jealous ones.', 'Ghurar al-Hikam, Spite And Malice §4', 'wisdom'),
  ('الحِقْدُ مَثارُ الغَضَبِ.', 'Malice is the motive of rage.', 'Ghurar al-Hikam, Spite And Malice §5', 'wisdom'),
  ('الحِقْدُ اَلأَمُ العُيُوبِ.', 'Spite is the vilest of flaws.', 'Ghurar al-Hikam, Spite And Malice §6', 'wisdom'),
  ('اَلحِقْدُ داءٌ دَوِيٌّ، ومَرَضٌ مُوبِي.', 'Malice is a painful ailment and an infectious disease.', 'Ghurar al-Hikam, Spite And Malice §7', 'wisdom'),
  ('اَلحِقْدُ خُلْقٌ دَنِيٌّ،وَمَرَضٌ مُرْدِي.', 'Malice is a vile characteristic and a fatal sickness.', 'Ghurar al-Hikam, Spite And Malice §8', 'wisdom'),
  ('تَجَنَّبُوا تَضاغُنَ القُلُوبِ، وَتَشاحُنَ الصُّدُورِ وتَدابُـرَ النُّفُوسِ، وَتَخاذُلَ الأيـْدي تَمْلِكُوا أمْرَكُمْ.', 'Keep away from harbouring grudges against each other, hating each other, quarrelling with one other and not lending a supporting hand to each other, [and by doing this] you will gain mastery over your affairs.', 'Ghurar al-Hikam, Spite And Malice §9', 'wisdom'),
  ('رَأسُ العُيُوبِ الحِقْدُ.', 'The cornerstone of flaws is spite.', 'Ghurar al-Hikam, Spite And Malice §10', 'wisdom'),
  ('لَيْسَ لِحَقُود أُخُوَّةٌ.', 'There is no brotherhood for the spiteful.', 'Ghurar al-Hikam, The Spiteful §1', 'wisdom'),
  ('مَنْ كَثُرَ حِقْدُهُ قَلَّ عِتابُهُ.', 'One whose spite increases, his censure decreases.', 'Ghurar al-Hikam, The Spiteful §2', 'wisdom'),
  ('مَنْ زَرَعَ الإِحَنَ حَصَدَ المِحَنَ.', 'One who sows hatred reaps tribulations.', 'Ghurar al-Hikam, The Spiteful §3', 'wisdom'),
  ('ما أنْكَدَ عَيْشَ الحَقُودِ.', 'How miserable is the life of a spiteful person!', 'Ghurar al-Hikam, The Spiteful §4', 'wisdom'),
  ('لا مَوَدَّةَ لِحَقُود.', 'The spiteful person has no love.', 'Ghurar al-Hikam, The Spiteful §5', 'wisdom'),
  ('اَلْحَقُودُ مُعَذَّبُ النَّفْسِ مُتَضاعِفُ الهَمِّ.', 'The spiteful one has a tormented soul is doubly distressed.', 'Ghurar al-Hikam, The Spiteful §6', 'wisdom'),
  ('اَلحَقُودُ لاراحَةَ لَهُ.', 'There is no repose for the spiteful.', 'Ghurar al-Hikam, The Spiteful §7', 'wisdom'),
  ('لاتَزْدَرِيَنَّ أحَداً حَتّى تَسْتَنْطِقَهُ.', 'Do not belittle anyone until you have heard from him.', 'Ghurar al-Hikam, Belittling Others §1', 'wisdom'),
  ('لاعَمَلَ كَالتَّحْقِيقِ.', 'There is no action like verification.', 'Ghurar al-Hikam, Verification §1', 'wisdom'),
  ('لاسُنَّـةَ أفْضَلُ مِنَ التَّحْقِيقِ.', 'There is no practice better than verification.', 'Ghurar al-Hikam, Verification §2', 'wisdom'),
  ('اَلحَقُّ سَيْفٌ قاطِعٌ.', 'Truth is an incisive sword.', 'Ghurar al-Hikam, The Truth §1', 'justice'),
  ('اَلْحَقُّ أفْضَلُ سَبِيل.', 'Truth is the best way.', 'Ghurar al-Hikam, The Truth §2', 'justice'),
  ('اَلحَقُّ أقْوى ظَهِير.', 'Truth is the strongest supporter.', 'Ghurar al-Hikam, The Truth §3', 'justice'),
  ('اَلْحَقُّ أوْضَحُ سَبِيل.', 'Truth is the clearest course.', 'Ghurar al-Hikam, The Truth §4', 'justice'),
  ('اَلْحَقُّ أحَقُّ أنْ يُتَّبَعَ.', 'The truth is worthier of being followed.', 'Ghurar al-Hikam, The Truth §5', 'justice'),
  ('اَلتَّعاوُنُ عَلى إقامَةِ الحَقِّ أمانَةٌ ودِيانَةٌ.', 'Assisting one another to establish the truth is [a sign of] trustworthiness and faith.', 'Ghurar al-Hikam, The Truth §6', 'justice'),
  ('اَلحَقُّ سَيْفٌ عَلى أهْلِ الباطِلِ.', 'Truth is a sword [to fight] against the followers of falsehood.', 'Ghurar al-Hikam, The Truth §7', 'justice'),
  ('اَلْحَقُّ مَنْجاةٌ لِكُلِّ عامِل (وحُجَّةٌ لِكُلِّ قائِل).', 'Truth is a refuge for every worker (and an argument for every speaker).', 'Ghurar al-Hikam, The Truth §8', 'justice'),
  ('بِالحَقِّ يَسْتَظْهِرُ المُحْتَجُّ.', 'Through truth, the petitioner gets support.', 'Ghurar al-Hikam, The Truth §9', 'justice'),
  ('بِالعُدُولِ عَنِ الحَقِّ تَـكُونُ الضَّلالَةُ.', 'It is by turning away from the truth that misguidance comes about.', 'Ghurar al-Hikam, The Truth §10', 'justice'),
  ('غَرَضُ المُحِقِّ الرَّشادُ.', 'The goal of one who is on the right is [following or remaining on] the right course.', 'Ghurar al-Hikam, One Who Is On The Right §1', 'wisdom'),
  ('إعْطاءُ هذا المالِ في حُقُوقِ اللّهِ دَخَلٌ في بابِ الجُودِ.', 'Giving this wealth in order to fulfil the rights of Allah has been made part of generosity.', 'Ghurar al-Hikam, The Rights Of Allah, The Most High §1', 'wisdom'),
  ('اَخْرِجْ مِنْ مالِكَ الحُقُوقَ، وأشْرِكْ فيهِ الصَّدِيقَ، ولْيَكُنْ كَلامُكَ في تَقْديِر، وهِمَّتـُكَ في تَفْكِير، تَأْمَنِ المَلامَةَ والنَّدامَةَ.', 'Take out the [rightful] dues from your wealth and share in your wealth with your friend; let your speech be measured and your endeavour well thought-out, [for by this] you will remain safe from censure and regret.', 'Ghurar al-Hikam, The Rights Of Allah, The Most High §2', 'wisdom'),
  ('حَقُ اللّهِ سُبْحانَهُ عَلَيْكُمْ فِي اليُسْرِ اَلْبِرُّ والشُّكْرُ وفِي العُسْرِ اَلرِّضا وَالصَّبْرُ.', 'The right of Allah, the Glorified, upon you in times of ease is piety and gratitude, and in times of hardship, [to have] contentment and patience.', 'Ghurar al-Hikam, The Rights Of Allah, The Most High §3', 'wisdom'),
  ('جَعَلَ اللّهُ سُبْحانَهُ حُقُوقَ عِبادِهِ مُقَدِّمَةً لِحُقُوقِهِ، فَمَنْ قامَ بِحُقُوقِ عِبادِ اللّهِ كانَ ذلِكَ مُؤَدِّياً إلَى القِيامِ بِحُقوقِ اللّهِ.', 'Allah, the Glorified, has placed the rights of His servants before His rights, so whoever fulfils the rights of the servants of Allah, then this helps one to fulfil the rights of Allah.', 'Ghurar al-Hikam, Rights Of The People §1', 'wisdom'),
  ('اَلمُحْتَكِرُ البَخيْلُ جامِعٌ لِمَنْ لايَشْكُرُهُ،وَقادِمٌ عَلى مَنْ لايَعْذُرُهُ.', 'The stingy hoarder accumulates for the one who does not thank him (i.e. his heirs) and proceeds towards the one who will not accept his excuse (i.e. Allah).', 'Ghurar al-Hikam, Hoarding And Hoarders §1', 'wisdom'),
  ('اَلإحْتِكارُ رَذِيلَةٌ.', 'Hoarding is a vice.', 'Ghurar al-Hikam, Hoarding And Hoarders §2', 'wisdom'),
  ('اَلإحْتِكارُ داعِيَةُ الحِرْمانِ.', 'Hoarding invites deprivation.', 'Ghurar al-Hikam, Hoarding And Hoarders §3', 'wisdom'),
  ('اَلمُحْتَكِرُ مَحْرُومٌ مِنْ نِعْمَتِهِ.', 'The hoarder is deprived of his blessing.', 'Ghurar al-Hikam, Hoarding And Hoarders §4', 'wisdom'),
  ('مِنْ طَبايِـعِ الأغْمارِ إتْعابُ النُّفُوسِ فِي الإحْتِكارِ.', 'It is from the nature of the inexperienced [and ignorant] to trouble the people by hoarding.', 'Ghurar al-Hikam, Hoarding And Hoarders §5', 'wisdom'),
  ('كُنْ مُقْتَدِراً (مُقَدِّراً)، ولاتَكُنْ مُحْتَكِراً.', 'Be solvent (or an assessor), and do not be a hoarder.', 'Ghurar al-Hikam, Hoarding And Hoarders §6', 'wisdom'),
  ('اَلإحْتِكارُ شِيمَةُ الفُجّارِ.', 'Hoarding is the practice of the vicious.', 'Ghurar al-Hikam, Hoarding And Hoarders §7', 'wisdom'),
  ('في حَمْلِ (عَمَلِ) عِبادِ اللّهِ عَلى أحْكامِ اللّهِ اِسْتِيفاءُ الحُقُوقِ وَكُلُّ الرِّفْقِ.', 'In impelling the servants of Allah to follow (or in their acting upon) the ordinances of Allah, there is the fulfilment of rights and all of kindness.', 'Ghurar al-Hikam, The Ordinances Of Allah §1', 'wisdom'),
  ('لَوْ حَفِظْتُمْ حُدُودَ اللّهِ سُبْحانَهُ لَعَجَّلَ لَكُمْ مِنْ فَضْلِهِ المَوْعُودَ.', 'If you were to preserve the bounds of Allah, the Glorified, He would hasten for you His promised bounty.', 'Ghurar al-Hikam, The Ordinances Of Allah §2', 'wisdom'),
  ('مَنْ قَصَّرَ عَنْ أحْكامِ الحُرِّيَّةِ أُعِيدَ إلَى الرِّقِّ.', 'One who neglects the commandments of freedom is made to return to serfdom.', 'Ghurar al-Hikam, The Ordinances Of Allah §3', 'wisdom'),
  ('اَلْحِكْمَةُ رَوْضَةُ العُقَلاءِ، ونُزْهَةُ النُّبَلاءِ.', 'Wisdom is a garden for the intelligent and a promenade for the noble.', 'Ghurar al-Hikam, Wisdom §1', 'wisdom'),
  ('اَلْحِكْمَةُ لاتَحِلُّ قَلْبَ المُنافِقِ إلاّ وهِيَ عَلَى ارْتِحال.', 'Wisdom does not settle in the heart of a hypocrite except that it departs from it [soon after].', 'Ghurar al-Hikam, Wisdom §2', 'wisdom'),
  ('اَلْحِكْمَةُ ضالَّةُ كُلِّ مُؤْمِن، فَخُذُوها ولَوْ مِنْ أفْواهِ المُنافِقينَ.', 'Wisdom is the lost property of every believer, so take it even if it be from the mouths of hypocrites.', 'Ghurar al-Hikam, Wisdom §3', 'wisdom'),
  ('اَلْحِكْمَةُ شَجَرَةٌ تَنْبُتُ فِي الْقَلْبِ، وتُثْمِرُ عَلَى اللِّسانِ.', 'Wisdom is a tree that grows in the heart and bears [its] fruit on the tongue.', 'Ghurar al-Hikam, Wisdom §4', 'wisdom'),
  ('اِسْتَشْعِرِ الْحِكْمَةَ، وتَجَلْبَبِ السَّكِينَةَ، فَإنَّهُما حِلْيَةُ الأبـْرارِ.', 'Fill your heart with wisdom and don the attire of tranquillity for these two are the ornaments of the virtuous.', 'Ghurar al-Hikam, Wisdom §5', 'wisdom'),
  ('أوَّلُ الْحِكْمَةِ تَرْكُ اللَّذّاتِ، وآخِرُها مَقْتُ الفانِياتِ.', 'The beginning of wisdom is abandoning [worldly] pleasures and its end is loathing the transitory.', 'Ghurar al-Hikam, Wisdom §6', 'wisdom'),
  ('أفْضَلُ الحِكْمَةِ مَعْرِفَةُ الإنْسانِ نَفْسَهُ، ووُقُوفُهُ عِنْدَ قَدْرِهِ.', 'The greatest wisdom is for the human being to know himself and to remain within his limits.', 'Ghurar al-Hikam, Wisdom §7', 'wisdom'),
  ('اَلْحِكْمَةُ تُرْشِدُ.', 'Wisdom guides [one] to the right.', 'Ghurar al-Hikam, Wisdom §8', 'wisdom'),
  ('اَلْحِكْمَةُ عِصْمَةٌ.', 'Wisdom is protection.', 'Ghurar al-Hikam, Wisdom §9', 'wisdom'),
  ('اَلْحِكَمُ رِياضُ النُّبَلاءِ.', 'Wisdoms are the gardens of the noble ones.', 'Ghurar al-Hikam, Wisdom §10', 'wisdom'),
  ('اَلْحُكَماءُ أشْرَفُ النّاسِ أنْفُساً، وأكْثَرُهُمْ صَبْراً، وأسْرَعُهُمْ عَفْواً، وَأوْسَعُهُمْ أخْلاقاً.', 'The wise are the most honourable of all people, the most patient of them, the quickest of them in forgiving and the best of them in character.', 'Ghurar al-Hikam, The Wise §1', 'wisdom'),
  ('اَلْحَكِيمُ يَشْفِي السّائِلَ، ويَجُودُ بِالفَضائِلِ.', 'The wise person cures the asker [of his ignorance] and is generous with virtues.', 'Ghurar al-Hikam, The Wise §2', 'wisdom'),
  ('جالِسِ الحُكَماءَ يَكْمُلْ عَقْلُكَ، وتَشْرُفْ نَفْسَكَ، ويَنْتَفِ عَنْكَ جَهْلُكَ.', 'Sit in the company of the wise and your intelligence will be improved, you will ennoble yourself and your ignorance will be removed from you.', 'Ghurar al-Hikam, The Wise §3', 'wisdom'),
  ('قَدْ يَزِلُّ الحَكِيمُ.', 'A wise person may [at times also] make a mistake.', 'Ghurar al-Hikam, The Wise §4', 'wisdom'),
  ('لَيْسَ بِحَكِيم مَنْ شَكى ضُـرَّهُ إلى غَيْرِ رَحيم.', 'He who complains of his troubles to one who is not compassionate is not a wise person.', 'Ghurar al-Hikam, The Wise §5', 'wisdom'),
  ('لَيْسَ بِحَكِيم مَنِ ابْتذَلَ بِانْبِساطِهِ إلى غَيْـرِ حَمِيم.', 'He who expresses his joy to one who is not his close friend is not a wise person.', 'Ghurar al-Hikam, The Wise §6', 'wisdom'),
  ('لَيْسَ بِحَكِيم مَنْ قَصَدَ بِحاجَتِهِ غَيْـرَ حَكِيم (كَرِيم).', 'He who intends to take his request to one who is not wise (or generous) is not a wise person.', 'Ghurar al-Hikam, The Wise §7', 'wisdom'),
  ('مَنْ كَشَفَ عَنْ مَقالاتِ الحُكَماءِ اِنْتَفَعَ بِحَقائِقِها.', 'One who unveils the words of the wise benefits from their hidden meanings.', 'Ghurar al-Hikam, The Wise §8', 'wisdom'),
  ('إنَّ كَلامَ الحَكِيمِ إذا كانَ صَواباً كانَ دَواءً، وإذا كانَ خَطاءً كانَ داءً.', 'Indeed the speech of a wise person, when it is correct, is a cure and when it is wrong, is a malady.', 'Ghurar al-Hikam, The Wise §9', 'wisdom'),
  ('اَلطّاعَةُ جُنَّـةُ الرَعِيَّةِ، والعَدْلُ جُنَّـةُ الدُّوَلِ.', 'Obedience is the shield of the people and justice is the shield of governments.', 'Ghurar al-Hikam, Government And Sovereignty §1', 'wisdom'),
  ('اَلذُّلُّ بَعْدَ العَزْلِ يُوازي عِزَّ الوِلايـَةِ.', 'The disgrace after being deposed is equal to the glory of sovereignty.', 'Ghurar al-Hikam, Government And Sovereignty §2', 'wisdom'),
  ('اِسْتِكانَةُ الرَّجُلِ فِي الْعَزْلِ، بِقَدْرِ شَـرِّهِ فِي الوِلايـَةِ.', 'The humiliation of the man being deposed is equivalent to his evil as a sovereign.', 'Ghurar al-Hikam, Government And Sovereignty §3', 'wisdom'),
  ('إعْدِلْ فِيما وُلِّيتَ، أُشْكُرْ لِلّهِ فِيما أُولِيتَ.', 'Be just in that which you have been given authority and thank Allah for that which has been granted to you.', 'Ghurar al-Hikam, Government And Sovereignty §4', 'wisdom'),
  ('أُحْرُسْ مَنْزِلَتَكَ عِنْدَ سُلْطانِكَ، واحْذَرْ أنْ يَحُطَّكَ عَنْها التَّهاوُنُ عَنْ حِفْظِ ما رَقاكَ إلَيْهِ.', 'Protect your status near your king and be cautious not to be belittled due to [your] negligence in protecting that which elevated you to it.', 'Ghurar al-Hikam, Government And Sovereignty §5', 'wisdom'),
  ('أقِمِ النّاسَ عَلى سُنَّتِهِمْ ودِينـِهِمْ، وَلْيَأْمَنْكَ بَرِئُهُمْ،وَ لْيَخَفْكَ مُرِيبُهُمْ، وَتَعاهَدْ ثُغُورَهُمْ وأطْرافَهُمْ.', 'Direct the people [based] on their practices and religions; let the innocent from among them be safe [from your wrath] and let the suspicious ones be afraid of you, and protect their frontiers and borders.', 'Ghurar al-Hikam, Government And Sovereignty §6', 'wisdom'),
  ('إجْعَلِ الدّينَ كَهْفَكَ، والعَدْلَ سَيْفَكَ، تَنْجُ مِنْ كُلِّ سُوء، وتَظْفَرْ (تَظْهَرْ) على كُلِّ عَدُوّ.', 'Make the religion your refuge and justice your sword, [then] you will be safe from every evil and will triumph over every foe.', 'Ghurar al-Hikam, Government And Sovereignty §7', 'wisdom'),
  ('إحْذَرِ الحَيْفَ والجَوْرَ، فَإنَّ الحَيْفَ يَدْعُو إلَى السَّيْفِ، والجَوْرَ يَعُودُ بِالجَلاءِ، ويُعَجِّلُ العُقُوبَةَ والإنْتِقامَ.', 'Be cautious of inequity and tyranny, for verily inequity invites the sword and tyranny leads to expulsion and hastens retribution and revenge.', 'Ghurar al-Hikam, Government And Sovereignty §8', 'wisdom'),
  ('أقْبَحُ شَـيْء جَوْرُ الوُلاةِ.', 'The most loathsome thing is the tyranny of rulers.', 'Ghurar al-Hikam, Government And Sovereignty §9', 'wisdom'),
  ('اَلمُلْكُ سِياسَةٌ.', 'Kingship is politics.', 'Ghurar al-Hikam, Government And Sovereignty §10', 'wisdom'),
  ('جُودُ الوُلاةِ بِفَيْءِ المُسْلِمينَ جَوْرٌ وخَتَرٌ.', 'The generosity of rulers with booty belonging to the Muslims is [an act of] injustice and betrayal.', 'Ghurar al-Hikam, The Ruler And Governer §1', 'wisdom'),
  ('سَبُعٌ أكُولٌ حَطُومٌ، خَيْـرٌ مِنْ وال ظَلُوم غَشُوم.', 'A predatory animal that is rapacious and tears it prey apart is better than an unjust and oppressive ruler.', 'Ghurar al-Hikam, The Ruler And Governer §2', 'wisdom'),
  ('شَـرُّ الوُلاةِ مَنْ يَخافُهُ البَرِيءُ.', 'The worst of rulers is one who is feared by the innocent.', 'Ghurar al-Hikam, The Ruler And Governer §3', 'wisdom'),
  ('مَنْ جارَتْ وِلايـَتُهُ زالَتْ دَوْلَتُهُ.', 'One whose rule is oppressive, his regime collapses.', 'Ghurar al-Hikam, The Ruler And Governer §4', 'wisdom'),
  ('مَنْ تَـكَبَّرَ في وِلايـَتِهِ كَثُرَ عِنْدَ عَزْلِهِ ذِلَّتُهُ.', 'One who is haughty in his rule, his disgrace is greater when he is deposed.', 'Ghurar al-Hikam, The Ruler And Governer §5', 'wisdom'),
  ('مَنِ اخْتالَ في وِلايـَتِهِ أبانَ عَنْ حَماقَتِهِ.', 'One who becomes vain in his rule exhibits his stupidity.', 'Ghurar al-Hikam, The Ruler And Governer §6', 'wisdom'),
  ('مِنْ حَقِّ الرّاعِي أنْ يَخْتارَ لِرَعِيَتِّهِ ما يَخْتارُهُ لِنَفْسِهِ.', 'It is from the right of the shepherd to choose for his flock that which he chooses for himself.', 'Ghurar al-Hikam, The Ruler And Governer §7', 'wisdom'),
  ('مِنَ النُّبْلِ أنْ تَتَـيَقَّظَ لإيجابِ حَقِّ الرَّعِيَةِ إلَيْكَ، وتَتَغابى عَنِ الجِنايَةِ عَلَيْكَ.', 'It is part of nobility that you [should] be attentive in fulfilling the rights of your subjects upon you and that you disregard any [of their] offences towards you.', 'Ghurar al-Hikam, The Ruler And Governer §8', 'wisdom'),
  ('وال ظَلُومٌ غَشُومٌ، خَيْـرٌ مِنْ فِتْنَة تَدُومُ.', 'An unjust and oppressive ruler is better than perpetual strife.', 'Ghurar al-Hikam, The Ruler And Governer §9', 'wisdom'),
  ('لاجَوْرَ أفْظَعُ مِنْ جَوْرِ حاكِم.', 'There is no oppression more severe than the oppression of a ruler.', 'Ghurar al-Hikam, The Ruler And Governer §10', 'wisdom'),
  ('كَيْفَ يَسْلَمُ مِنْ عَذابِ اللّهِ المُتَسَرِّعُ إلَى اليَمِينِ الفاجِرَةِ؟!', 'How can one be safe from the punishment of Allah when he is quick in making false oaths.', 'Ghurar al-Hikam, False Oaths §1', 'wisdom'),
  ('يَكْثُرُ حَلْفُ الرَّجُلِ لأرْبَع: مَهانَة يَعْرِفُها مِنْ نَفْسِهِ، أوضَراعَة يَجْعَلُها سَبِيلاً إلى تَصْديقِهِ، أوْ عَيّ لِمَنْطِقِهِ فَيَّتَخِدَ الأيـْمانَ حَشْواً وَصِلَةً لِكَلامِهِ، أوْ لِتُهْمَة قَدْ عُرِفَ بِها.', 'The swearing of a man increases for four [possible reasons]: something shameful that he knows about himself, or as a means of entreating by which he may be deemed truthful, or because of his inability to express himself so he takes oaths as verbiage to connect his speech, or because of an accusation that has been made upon him.', 'Ghurar al-Hikam, False Oaths §2', 'wisdom'),
  ('أسْـرَعُ شَـيْء عُقُوبَةً اَليَمِينُ الفاجِرَةُ.', 'The thing that brings the quickest punishment is a false oath.', 'Ghurar al-Hikam, False Oaths §3', 'wisdom'),
  ('لاتُعَوِّدْ نَفْسَكَ اليَمِينَ، فَإنَّ الحَلاّفَ لا يَسْلَمُ مِنَ الإثْمِ.', 'Do not habituate yourself to taking oaths, for verily the one who swears excessively is not safe from sin.', 'Ghurar al-Hikam, False Oaths §4', 'wisdom'),
  ('عَلَيْكَ بِلُزُومِ الحَلالِ، وحُسْنِ البِرِّ بِالعِيالِ،وَ ذِكْرِ اللّهِ في كُلِّ حال.', 'You should cling to the lawful, and to treating your family with kindness, and to remembering Allah in all circumstances.', 'Ghurar al-Hikam, The Lawful §1', 'wisdom'),
  ('قَدْ تَصْدُقُ الأَحْلامُ.', 'Dreams may [at times] come true.', 'Ghurar al-Hikam, Dreams §1', 'wisdom'),
  ('الرُؤْيا الصّالِحَةُ إحْدَى البِشارَتَيْنِ.', 'A good dream is one of the two [forms of] glad-tidings.', 'Ghurar al-Hikam, Dreams §2', 'wisdom'),
  ('أوَّلُ عِوَضِ الحَلِيمِ عَنْ حِلْمِهِ أنَّ النّاسَ كُلَّهُمْ أنْصارُهُ عَلى خَصْمِهِ.', 'The first compensation for the forbearing person from his forbearance is that all the people are [ready to be] his helpers against his enemy.', 'Ghurar al-Hikam, The Forebearing §1', 'wisdom'),
  ('اَلحَليْمُ يُعْلِي هِمَّتَهُ فيما جُنِيَ عَلَيْهِ مِنْ طَلَبِ سُوءِ المُكافاةِ.', 'The forbearing person raises his determination, in that which he has been oppressed, above seeking an evil retribution.', 'Ghurar al-Hikam, The Forebearing §2', 'wisdom'),
  ('إنَّ أفْضَلَ النّاسِ مَنْ حَلُمَ عَنْ قُدْرَة، وزَهَدَ عَنْ غُنْيَة، وأنْصَفَ عَنْ قُوَّة.', 'Indeed the best of people is one who is forbearing even when he is strong [enough to exact revenge], is not attached to the pleasures of this world even though he is well-off and is just even though he has power.', 'Ghurar al-Hikam, The Forebearing §3', 'wisdom'),
  ('اَلحَلِيمُ مَنِ احْتَمَلَ إخْوانَهُ.', 'The forbearing is one who tolerates [the flaws of] his brothers.', 'Ghurar al-Hikam, The Forebearing §4', 'wisdom'),
  ('الحَليمُ الَّذي لا يَشُقُّ عَلَيْهِ مَؤُنَةُ الحِلْمِ.', 'The forbearing is one for whom it is not difficult to act with tolerance.', 'Ghurar al-Hikam, The Forebearing §5', 'wisdom'),
  ('إنْ لَمْ تَـكُنْ حَلِيماً فَتَحَلَّمْ، فَإنَّهُ قَلَّ مَنْ تَشَبَّهَ بِقَوْم إلاّ أوْشَكَ أنْ يَصِيرَ مِنْهُمْ.', 'If you are not forbearing then act forbearing, for verily it is rare for a person who imitates a group not to soon become one among them.', 'Ghurar al-Hikam, The Forebearing §6', 'wisdom'),
  ('إنَّما الحَلِيمُ مَنْ إذا أُوذِيَ صَبَرَ، وإذا ظُلِمَ غَفَرَ.', 'Indeed only he is forbearing who is patient when he is offended and forgives when he is wronged.', 'Ghurar al-Hikam, The Forebearing §7', 'wisdom'),
  ('قَدْ يَزْهَقُ الحَلِيمُ.', 'Sometimes the forbearing person may get fed up.', 'Ghurar al-Hikam, The Forebearing §9', 'wisdom'),
  ('قَدْ يَتَزَيّي بِالحِلْمِ غَيْرُ الحَلِيمِ.', 'A person who is not forbearing may at times dress in the garb of forbearance.', 'Ghurar al-Hikam, The Forebearing §10', 'wisdom'),
  ('كُنْ حَلِيماً فِي الغَضَبِ،صَبُوراً فِي الرَّهَبِ، مُجْمِلاً فِي الطَّلَبِ.', 'Be forbearing in [times of] anger, very patient [and courageous] in fear, [and] moderate in your request.', 'Ghurar al-Hikam, The Forebearing §11', 'wisdom'),
  ('اَلْحِلْمُ أحَدُ المَنْقِبَتَيْنِ.', 'Forbearance is one of the two excellent traits.', 'Ghurar al-Hikam, Forbearance §1', 'wisdom'),
  ('اَلْحِلْمُ عِنْدَ شِدَّةِ الْغَضَبِ يُؤْمِنُ غَضَبَ الْجَبّارِ.', 'Forbearance during intense rage protects [one] from the wrath of the Almighty.', 'Ghurar al-Hikam, Forbearance §2', 'wisdom'),
  ('اَلْحِلْمُ يُطْفِيءُ نارَ الْغَضَبِ، والْحِدَّةُ تُؤَجِّجُ إحْراقَهُ.', 'Forbearance puts out the fire of rage and acrimoniousness stokes it.', 'Ghurar al-Hikam, Forbearance §3', 'wisdom'),
  ('أُحْلُمْ تُـكْرَمْ.', 'Be forbearing and you will be honoured.', 'Ghurar al-Hikam, Forbearance §4', 'wisdom'),
  ('أُحْلُمْ تُوَقَّرْ.', 'Be forbearing and you will be respected.', 'Ghurar al-Hikam, Forbearance §5', 'wisdom'),
  ('أَغْضِ عَلَى الْقَذى، وإلاّ لَمْ تَرْضَ أبَداً.', 'Bear [the actions of others] with patience, otherwise you will never be pleased.', 'Ghurar al-Hikam, Forbearance §6', 'wisdom'),
  ('احْتَجِبْ عَنِ الغَضَبِ بِالْحِلْمِ، وغُضَّ عَنِ الوَهْمِ بِالْفَهْمِ.', 'Veil [your] anger with forbearance and ignore misconceptions with understanding.', 'Ghurar al-Hikam, Forbearance §7', 'wisdom'),
  ('أقْوىَ النّاسِ مَنْ قَوِيَ عَلى غَضَبِهِ بِحِلْمِهِ.', 'The strongest of all people is the one who overcomes his anger with his forbearance.', 'Ghurar al-Hikam, Forbearance §8', 'wisdom'),
  ('أفْضَلُ الحِلْمِ كَظْمُ الغَيْظِ، ومِلْكُ النَّفْسِ مَعَ القُدْرَةِ.', 'The best forbearance is suppressing anger and exercising self-restraint despite having power [to exact revenge].', 'Ghurar al-Hikam, Forbearance §9', 'wisdom'),
  ('أشْجَعُ النّاسِ مَنْ غَلَبَ الجَهْلَ بِالحِلْمِ.', 'The most courageous of people is the one who defeats ignorance with forbearance.', 'Ghurar al-Hikam, Forbearance §10', 'wisdom'),
  ('لايَحْمَدُ حامِدٌ إلاّ رَبَّهُ.', 'A Praiser should praise none but his Lord.', 'Ghurar al-Hikam, Praise §1', 'wisdom'),
  ('مَنْ جَعَلَ الْحَمْدَ خِتامَ النِّعْمَةِ جَعَلَهُ اللّهُ سُبْحانَهُ مِفْتاحَ المَزِيدِ.', 'Whoever puts praise [for Allah] as the conclusion of a blessing, Allah, the Glorified, makes it the key for more [blessings].', 'Ghurar al-Hikam, Praise §2', 'wisdom'),
  ('مَنْ حَمِدَ اللّهَ أغْناهُ.', 'Whoever praises Allah, He makes him free from want.', 'Ghurar al-Hikam, Praise §3', 'wisdom'),
  ('إسْتَكْثِرْ مِنَ المَحامِدِ، فَإنَّ المَذامَّ قَلَّ مَنْ يَنْجُو مِنْها.', 'Try to increase your praiseworthy actions [and traits], for verily disgraceful actions [and traits] are such that very few gain salvation from them.', 'Ghurar al-Hikam, The Praiseworthy And The Disgraceful §1', 'wisdom'),
  ('اِرْضَ بِمُحَمَّد صلَّى اللّه عليه وآله وسلَّم رائِداً، وإلَى النَّجاةِ قائِداً.', 'Be pleased with Muhammad (s) as your guide [and role model] and as the one who will lead you to salvation.', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §1', 'wisdom'),
  ('اِقْتَدُوا بِهُدى نَبِيِّكُمْ، فَإنَّهُ أصْدَقُ الهُدى، واسْتَنُّوا بِسُنَّتِهِ، فَإنَّها أهْدىَ السُّنَنِ.', 'Follow the guidance of your Prophet for it is the truest guidance, and emulate his practices for they are the most exemplary practices.', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §2', 'wisdom'),
  ('إيّاكُمْ والْغُلُوَّ فينا، قُولُوا:إنّا مَرْبُوبُُونَ، واْعْتَقِدُوا في فَضْلِنا ما شِئْتُمْ.', 'Be cautious of exceeding the limits with regards to us; say that we are servants of our Lord, and then you may believe anything you wish about our merits.', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §3', 'wisdom'),
  ('ألا وَإنّا أهْلَ البَيْتِ أبْوابُ الحِكَمِ، وأنْوارُ الظُّلَمِ، وضِياءُ الأُمَمِ.', 'Indeed we, the household [of the Prophet], are the doors of wisdom, the lights that dispel darkness and the illumination of the nations.', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §4', 'wisdom'),
  ('أيْنَ تَتِيهُونَ، ومِنْ أيْنَ تُؤْتَوْنَ، وأنّى تُؤْفَكُونَ، وعَلامَ تعْمَهُونَ، وَبَيْنَـكُمْ عِتْرَةُ نَبِيِّكُمْ، وَهُمْ أزِمَّةُ الصِّدْقِ وألْسِنَةُ الْحَقِّ؟', 'Where are you wandering and where are you coming from and where are you straying to and what are you bewildered by while you have among you the progeny of your Prophet – they who are the guides towards right and speakers of truth?', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §5', 'wisdom'),
  ('أيْنَ الَّذينَ زَعَمُوا أنَّهُمُ الرّاسِخُونَ فِي العِلْمِ دُونَنا كِذْباً وبَغْياً عَلَيْنا وَحَسَداً لَنا، أنْ رَفَعَنا اللّهُ سُبْحانَهُ ووَضَعَهُمْ، وأعْطانا وحَرَمَهُمْ، وأدْخَلَنا وَأخْرَجَهُمْ، بِنا يُسْتَعْطَي الهُدى، وَيُسْتَجْلَي العَمى لا بِهِمْ.', 'Where are those who allege that they are firmly grounded in knowledge apart from us, while they lie and transgress against us, and harbour jealousy towards us because Allah, the Glorified, elevated us and lowered them, gave us and deprived them, put us in [His proximity] and expelled them; it is through us that guidance is granted and the blindness [of ignorance] is removed, not though them!', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §6', 'wisdom'),
  ('أحْسَنُ الحَسَناتِ حُبُّنا، وأسْوَءُ السَّـيِّئاتِ بُغْضُنا.', 'The most virtuous of good deeds is loving us and the most despicable of evil deeds is hating us.', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §7', 'wisdom'),
  ('أسْعَدُ النّاسِ مَنْ عَرَفَ فَضْلَنا، وتَقَرَّبَ إلَى اللّهِ بِنا، وأخْلَصَ حُبَّنا، وَعَمِلَ بِما إلَيْهِ نَدَبْنا، وانْتَهى عَمّا عَنْهُ نَهَيْنا، فَذاكَ مِنّا، وهُوَ فِي دارِ الْمُقامَةِ مَعَنا.', 'The most fortunate of all people is one who knows our merits, seeks nearness to Allah through us, is sincere in his love for us, acts on that which we have entrusted to him and keeps away from that which we have forbidden, for this person is from us and he will be with us in the Eternal Abode.', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §8', 'wisdom'),
  ('أوْلَى النّاسِ بِنا مَنْ والانا، وعادا مَنْ عادانا.', 'The nearest of people to us is one who loyally supports us and has enmity for our enemies.', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §9', 'wisdom'),
  ('إنَّ لـ﴿لاإلهَ إلاّ اللّهُ﴾ شُرُوطاً وَإنّي وذُرِّيَتي مِنْ شُرُوطِها.', 'Indeed, for [the proclamation:] ‘There is none worthy of worship but Allah’ there are some conditions, and verily I and my progeny are from its conditions.', 'Ghurar al-Hikam, Muhammad (S) And His Progeny §10', 'wisdom'),
  ('اَلْحُمْقُ اَلاِسْتِهْتارُ بِالفُضُولِ، ومُصاحَبَةُ الْجَهُولِ.', 'Foolishness is occupying oneself with the superfluous and accompanying the ignorant.', 'Ghurar al-Hikam, Foolishness §1', 'wisdom'),
  ('اَلْحُمْقُ داءٌ لا يُداوى، ومَرَضٌ لا يَبْرَءُ.', 'Foolishness is an ailment which cannot be remedied and a sickness that cannot be cured.', 'Ghurar al-Hikam, Foolishness §2', 'wisdom'),
  ('أفْقَرُ الفَقْرِ الْحُمْقُ.', 'The worst indigence is foolishness.', 'Ghurar al-Hikam, Foolishness §3', 'wisdom'),
  ('أضَرُّ شَـيْء الحُمْقُ.', 'The most harmful thing is foolishness.', 'Ghurar al-Hikam, Foolishness §4', 'wisdom'),
  ('أحْمَقُ الْحُمْقِ الاِغْتِرارُ.', 'The height of foolishness is being beguiled [by the pleasures of this world].', 'Ghurar al-Hikam, Foolishness §5', 'wisdom'),
  ('أكْبَرُ الْحُمْقِ اَلإغْراقُ فِي المَدْحِ والذَّمِّ.', 'The greatest foolishness is exaggeration in praise and censure.', 'Ghurar al-Hikam, Foolishness §6', 'wisdom'),
  ('أعْظَمُ الْحَماقَةِ اَلاِخْتِيالُ فِي الفاقَةِ.', 'The greatest foolishness is being conceited in [the state of] poverty.', 'Ghurar al-Hikam, Foolishness §7', 'wisdom'),
  ('اَلْحُمْقُ شَيْنٌ.', 'Foolishness is a disgrace.', 'Ghurar al-Hikam, Foolishness §8', 'wisdom'),
  ('الْحُمْقُ أضَـرُّ الأصْحابِ.', 'Foolishness is the most harmful companion.', 'Ghurar al-Hikam, Foolishness §9', 'wisdom'),
  ('اَلْحُمْقُ أدْوَأُ الدّاءِ.', 'Foolishness is the worst ailment.', 'Ghurar al-Hikam, Foolishness §10', 'wisdom'),
  ('اَلأحْمَقُ غَرِيبٌ في بَلْدَتِهِ، مُهانٌ بَيْنَ أعِزَّتِهِ.', 'The fool is a stranger in his [own] hometown, [and is] humiliated among his near ones.', 'Ghurar al-Hikam, The Fool §1', 'wisdom'),
  ('اَلأحْمَقُ لايَحْسُنُ بِالهَوانِ، ولايَنْفَكُّ عَنْ نَقْص وخُسْران.', 'A fool does not improve by abasement and he is does not separate from fault and loss.', 'Ghurar al-Hikam, The Fool §2', 'wisdom'),
  ('إحْذَرِ الأحْمَقَ، فَإنَّ مُداراتَهُ تُعَنِّيكَ (تُعْيِيكَ)، ومُوافَقَتَهُ تُرْدِيكَ، وَمُخالَفَتَهُ تُؤْذِيكَ، ومُصاحَبَتَهُ وَبالٌ عَلَيْكَ.', 'Be wary of the fool for verily, being amicable with him will bring you hardship (or exhaust you), agreeing with him will destroy you, disagreeing with him will cause you suffering and keeping his company will be [like] a curse upon you.', 'Ghurar al-Hikam, The Fool §3', 'wisdom'),
  ('أحْمَقُ النّاسِ مَنْ ظَنَّ أنَّهُ أعْقَلُ النّاسِ.', 'The most foolish of all people is the one who thinks that he is the most intelligent of all people.', 'Ghurar al-Hikam, The Fool §4', 'wisdom'),
  ('أحْمَقُ النّاسِ مَنْ يَمْنَعُ الْبِرَّ، ويَطْلُبُ الشُّكْرَ، ويَفْعَلُ الشَّـرَّ، ويَتَوَقَّعُ ثَوابَ الخَيْـرِ.', 'The most foolish of all people is the one who prevents good deeds and [then] seeks gratitude, and does evil and [then] expects the reward for [doing] good.', 'Ghurar al-Hikam, The Fool §5', 'wisdom'),
  ('أحْمَقُ النّاسِ مَنْ أنْكَرَ عَلى غَيْرِهِ رَذِيلَةً وهُوَ مُقِيمٌ عَلَيْها.', 'The most foolish of all people is the one who censures others for a vice while he [himself] performs it.', 'Ghurar al-Hikam, The Fool §6', 'wisdom'),
  ('اَلأحْمَقُ لا يَحْسُنُ بِالهَوانِ.', 'The fool does not improve by being disgraced.', 'Ghurar al-Hikam, The Fool §7', 'wisdom'),
  ('بُعْدُ الأحْمَقِ خَيْـرٌ مِنْ قُرْبِهِ، وسُكُوتُهُ خَيْـرٌ مِنْ نُطْقِهِ.', 'The remoteness of a fool is better than his nearness and his silence is better than his speech.', 'Ghurar al-Hikam, The Fool §8', 'wisdom'),
  ('تُعْرَفُ حَماقَةُ الرَّجُلِ بِالأشَرِ فِي النِّعْمَةِ، وكَثْرَةِ الذُّلِّ فِي الْمِحْنَةِ.', 'The foolishness of a person is recognized by [his] cheerfulness in times of blessing and increased abjectness in times of tribulation.', 'Ghurar al-Hikam, The Fool §9', 'wisdom'),
  ('تُعْرَفُ حِماقَةُ الرَّجُلِ في ثَلاث: في كَلامِهِ فِيما لا يَعْنِيهِ، وجَوابِهِ عَمّا لا يُسْئَلُ عَنْهُ، وتَهَوُّرِهِ فيِ الأُمُورِ.', 'The foolishness of a person is recognized in three things: in his talking about that which does not concern him, [in] his answering that which he was not asked and his recklessness in [his] affairs.', 'Ghurar al-Hikam, The Fool §10', 'wisdom'),
  ('اَلاِحْتِمالُ بُرْهانُ الْعَقْلِ، وعُنْوانُ الفَضْلِ.', 'Tolerance is proof of intelligence and a symbol of excellence.', 'Ghurar al-Hikam, Tolerance §1', 'wisdom'),
  ('اَلاِحْتِمالُ زَيْنُ الرِّفاقِ.', 'Tolerance is the ornament of companionship.', 'Ghurar al-Hikam, Tolerance §2', 'wisdom'),
  ('اَلاِحْتِمالُ زَيْنُ السِّياسَةِ.', 'Tolerance is the embellishment of politics [and leadership].', 'Ghurar al-Hikam, Tolerance §3', 'wisdom'),
  ('اَلاِحْتِمالُ يُجِلُّ القَدْرَ.', 'Tolerance dignifies one’s status.', 'Ghurar al-Hikam, Tolerance §4', 'wisdom'),
  ('الاِحْتِمالُ خُلْقٌ سَجِيحٌ.', 'Tolerance is a beautiful quality.', 'Ghurar al-Hikam, Tolerance §5', 'wisdom'),
  ('اِحْتِمالُ الدَّنِيَّةِ (اَلأذِيَّةِ) مِنْ كَرَمِ السَّجِيَّةِ.', 'Tolerating meanness (or annoyance) is from nobility of character.', 'Ghurar al-Hikam, Tolerance §6', 'wisdom'),
  ('بِتَحَمُّلِ المُؤَنِ تَـكْثُرُ المَحامِدُ.', 'By bearing the burden of provision (for the people), praises increase.', 'Ghurar al-Hikam, Tolerance §7', 'wisdom'),
  ('بِكَثْرَةِ الاِحْتِمالِ يَكْثُرُ الْفَضْلُ (العَقْلُ).', 'Through increased tolerance, one’s merit (or intelligence) increases.', 'Ghurar al-Hikam, Tolerance §8', 'wisdom'),
  ('بِالاِحْتِمالِ والْحِلْمِ يَكُونُ لَكَ النّاسُ أنْصاراً وأعْواناً.', 'Through tolerance and forbearance, people become your helpers and supporters.', 'Ghurar al-Hikam, Tolerance §9', 'wisdom'),
  ('بِكَثْرَةِ الاِحْتِمالِ يُعْرَفُ الْحَليمُ.', 'The forbearing one is recognized by his increased tolerance.', 'Ghurar al-Hikam, Tolerance §10', 'wisdom'),
  ('صَلاحُ البَدَنِ الحِمْيَةُ.', 'Fitness of the body is [in] abstinence from [harmful] foods.', 'Ghurar al-Hikam, Abstinence [From Food] §1', 'wisdom'),
  ('مَنْ لَمْ يَصْبِرْ عَلى مَضَضِ الْحِمْيَةِ طالَ سَقَمُهُ.', 'One who cannot patiently bear the agony of abstinence [from food], his sickness will be prolonged.', 'Ghurar al-Hikam, Abstinence [From Food] §2', 'wisdom'),
  ('إنَّ حَوائِجَ النّاسِ إلَيْكُمْ نِعْمَةٌ مِنَ اللّهِ عَلَيْكُمْ فَاغْتَنِمُوها وَلا تَمَلُّوها فَتَتَحَوَّلَ نَقْماً.', 'Verily the needs of the people that are addressed to you are a blessing from Allah upon you, so take advantage of them and do not be weary of them, lest they should turn into [divine] wrath.', 'Ghurar al-Hikam, Fulfilling Needs §1', 'wisdom'),
  ('لاتُؤَخِّرْ إنالَةَ الْمُحْتاجِ إلى غَد، فَإنَّكَ لاتَدْرِي ما يَعْرِضُ لَكَ ولَهُ في غَد.', 'Do not delay granting the needy to tomorrow, for you do not know what will happen to you and to him tomorrow.', 'Ghurar al-Hikam, Fulfilling Needs §2', 'wisdom'),
  ('عَلَيْكُمْ في قَضاءِ حَوائِجِكُمْ بِكِرامِ الأنْفُسِ والأُصُولِ تُنْجَحْ لَكُمْ عِنْدَهُمْ مِنْ غَيْرِ مَطال ولا مَنّ.', 'You must seek the fulfilment of your needs through people of honourable dispositions and origins, you will be successful [in getting what you need] with them, without any delay or any sense of obligation.', 'Ghurar al-Hikam, Fulfilling Needs §3', 'wisdom'),
  ('عَلَيْكُمْ في طَلَبِ الْحَوائِجِ بِشِرافِ النُّفُوسِ ذَوِي الأُصُولِ الطَيِّبَةِ، فَإنَّها (فَإنَّهُ) عِنْدَهُمْ أقْصى وهِيَ (وَهُمْ) لَدَيْكُمْ (لَدَيْهِمْ) أزْكى.', 'You must seek your needs from those who are honourable and of good origins, for they are more likely to fulfil them [quickly and without obligation] and they are purer in your eyes.', 'Ghurar al-Hikam, Fulfilling Needs §4', 'wisdom'),
  ('عَجِبْتُ لِرَجُل يَأتِيهِ أخُوهُ الْمُسْلِمُ فِي حاجَة، فَيَمْتَنِعُ عَنْ قَضائِها وَلايَرى نَفْسَهُ لِلْخَيْرِ أهْلاً، فَهَبْ أنَّهُ لاثَوابَ يُرْجى ولاعِقابَ يُتَّقى، أفَتَزهَدُونَ فِي مَكارِمِ الأخْلاقِ.', 'I am amazed at the person who is approached by his Muslim brother in need and refuses to fulfil it, not deeming himself worthy of [doing] good; so assume that he does not desire any reward nor does he fear any punishment. Do they lack interest in [acquiring] noble traits?', 'Ghurar al-Hikam, Fulfilling Needs §5', 'wisdom'),
  ('فَوْتُ الحاجَةِ خَيْـرٌ مِنْ طَلَبِها مِنْ غَيْرِ أهْلِها.', 'Not having your needs fulfilled is better than seeking them from those who are not worthy.', 'Ghurar al-Hikam, Fulfilling Needs §6', 'wisdom'),
  ('بَذْلُ الجاهِ زَكوةُ الْجاهِ.', 'Being generous with power [and fulfilling the needs of the people with it] is the alms-tax of power.', 'Ghurar al-Hikam, Fulfilling Needs §7', 'wisdom'),
  ('تَعْجِيلُ السَّراحِ نَجاحٌ.', 'Expediting the release [of the needy from his need] is [a means of] success.', 'Ghurar al-Hikam, Fulfilling Needs §8', 'wisdom'),
  ('لا يَسْتَقِيمُ قَضاءُ الحَوائِجِ إلاّ بِثَلاث: بِتَصْغِيرِها لِتَعْظُمَ، وسَتْرِها لِتَظْهَرَ، وتَعْجِيلِها لِتَهْنَأَ.', 'The fulfilling of needs is not made righteous except by three things: by considering it to be small such that it becomes great, by hiding it such that it is made apparent [by Allah] and by expediting it such that it becomes felicitous.', 'Ghurar al-Hikam, Fulfilling Needs §9', 'wisdom'),
  ('كُلُّ مُؤَجَّل يَتَعَلَّلُ بِالتَّسْوِيفِ.', 'Everyone who has been given time [to do good before his death] gives excuses for postponement [of good deeds].', 'Ghurar al-Hikam, Fulfilling Needs §10', 'wisdom'),
  ('إحْتَجْ إلى مَنْ شِئْتَ وَكُنْ (تَـكُنْ) أسِيْـرَهُ.', 'Express your needs to whomever you wish and (you will) become his captive.', 'Ghurar al-Hikam, Expressing Your Needs §1', 'forgiveness'),
  ('مَنِ احْتَجْتَ إلَيْهِ هُنْتَ عَلَيْهِ.', 'When you express your needs to someone, you abase yourself before him.', 'Ghurar al-Hikam, Expressing Your Needs §2', 'forgiveness'),
  ('مَنِ احْتاجَ إلَيْكَ كانَتْ طاعَتُهُ لَكَ بِقَدْرِ حاجَتِهِ إلَيْكَ.', 'One who seeks his needs from you, his obedience to you will be to the extent of his need from you.', 'Ghurar al-Hikam, Expressing Your Needs §3', 'forgiveness'),
  ('مَنِ احْتاجَ إلَيْكَ وَجَبَ إسْعافُهُ عَلَيْكَ.', 'When someone turns to you with his needs, it becomes obligatory upon you to help him.', 'Ghurar al-Hikam, Expressing Your Needs §4', 'forgiveness'),
  ('(وَ قيلَ لَهُ ـ عَليهِ السَّلامُ ـ كَيفَ تَجِدُكَ يا أميرَ المُؤمِنينَ؟ فقال: كَيْفَ يَكُونُ (حالُ) مَنْ يَفْنى بِبَقائِهِ، ويَسْقَمُ بِصِحَّتِهِ ويُؤتى مِنْ مَأْمَنِهِ؟!', '(When he was asked ‘how are you O Amīr al-Mu’minīn?’, he replied: ) How would he be whom life is driving towards death, whose state of health can be changed to sickness at any moment and who can be approached [by death] from his place of safety?!', 'Ghurar al-Hikam, How Are You? §1', 'wisdom'),
  ('قَدْ يُعْذَرُ المُتَحَيِّرُ الْمَبْهُوتُ.', 'It is possible for the one who is perplexed and bewildered to be excused.', 'Ghurar al-Hikam, The Perplexed §1', 'wisdom'),
  ('اَلتَّلَطُّفُ فِي الحِيْلَةِ أجْدى مِنَ الْوَسِيلَةِ.', 'Subtlety in [seeking] recourse is the most advantageous of all ways.', 'Ghurar al-Hikam, Recourse §1', 'wisdom'),
  ('لِكُلِّ شَـيْء حِيلَةٌ.', 'For everything there is recourse.', 'Ghurar al-Hikam, Recourse §2', 'wisdom'),
  ('مَنْ قَعَدَ عَنْ حِيلَتِهِ (جِبِلَّتِهِ)، أقامَتْهُ الشَّدائِدُ.', 'One who neglects his recourse (or natural disposition) is made to rise [towards it] by tribulations.', 'Ghurar al-Hikam, Recourse §3', 'wisdom'),
  ('اَلحَيُّ لا يَكْتَفِي.', 'The living one is never satisfied [and always seeks more].', 'Ghurar al-Hikam, Life And Being Alive §1', 'wisdom'),
  ('ثَمَرَةُ طُولِ الْحَياةِ السُّقْمُ والْهَرَمُ.', 'The fruit of long life is illness and senility.', 'Ghurar al-Hikam, Life And Being Alive §2', 'wisdom'),
  ('غايَةُ الْحَياةِ الْمَوْتُ.', 'The end of [this] life is death.', 'Ghurar al-Hikam, Life And Being Alive §3', 'wisdom'),
  ('ما أقْرَبَ الحَياةَ مِنَ المَوْتِ.', 'How close is life to death!', 'Ghurar al-Hikam, Life And Being Alive §4', 'wisdom'),
  ('ما أقْرَبَ الحَيَّ مِنَ المَيِّتِ لِلِحاقِهِ بِهِ.', 'How near is the living one to the dead because he will soon join him!', 'Ghurar al-Hikam, Life And Being Alive §5', 'wisdom'),
  ('ما أبْعَدَ المَيِّتَ مِنَ الحَيِّ لإنْقِطاعِهِ عَنْهُ.', 'How far is the dead one from the living by his separation from him!', 'Ghurar al-Hikam, Life And Being Alive §6', 'wisdom'),
  ('اَلْحَياءُ مِنَ اللّهِ سُبْحانَهُ تَقي عَذابَ النّارِ.', 'Being ashamed in front of Allah, the Glorified, protects [one] from the punishment of hell.', 'Ghurar al-Hikam, Modesty And Shame §1', 'character'),
  ('أحْياكُمْ أحْلَمُكُمْ.', 'The most modest among you are the most forbearing among you.', 'Ghurar al-Hikam, Modesty And Shame §2', 'character'),
  ('أحْسَنُ مَلابِسِ الدِّينِ اَلحَياءُ.', 'The best of religious attires is modesty.', 'Ghurar al-Hikam, Modesty And Shame §3', 'character'),
  ('أفْضَلُ الْحَياءِ اِسْتِحْياؤُكَ مِنَ اللّهِ.', 'The greatest modesty is your being ashamed in front of Allah.', 'Ghurar al-Hikam, Modesty And Shame §4', 'character'),
  ('أحْسَنُ الْحَياءِ اِسْتِحْياؤُكَ مِنْ نَفْسِكَ.', 'The best modesty is your being ashamed of yourself [in front of Allah].', 'Ghurar al-Hikam, Modesty And Shame §5', 'character'),
  ('إنَّ الْحَياءَ والْعِفَّةَ مِنْ خَلائِقِ الإيمانِ، وإنَّهُما لَسَجِيَّةُ الأحْرارِ، وَشيمَةُ الأبـْرارِ.', 'Verily modesty and chastity are from the characteristics of faith, and they are the traits of the free and the qualities of the virtuous.', 'Ghurar al-Hikam, Modesty And Shame §6', 'character'),
  ('اَلْحَياءُ جَميلٌ.', 'Modesty is beautiful.', 'Ghurar al-Hikam, Modesty And Shame §7', 'character'),
  ('اَلْحَياءُ مَحْرَمَةٌ.', 'Modesty is preventive.', 'Ghurar al-Hikam, Modesty And Shame §8', 'character'),
  ('اَلْحَياءُ يَمْنَعُ الرِّزْقَ.', 'Shame prevents livelihood.', 'Ghurar al-Hikam, Modesty And Shame §9', 'character'),
  ('اَلْحَياءُ مِفْتاحُ (كُلِّ) الْخَيْـرِ.', 'Modesty is the key to (every) good.', 'Ghurar al-Hikam, Modesty And Shame §10', 'character'),
  ('لا تُخْبِرْ بِما لَمْ تُحِطْ بِهِ عِلْماً.', 'Do not relate that which you have no knowledge about.', 'Ghurar al-Hikam, Narration And Transmission Of Information §1', 'wisdom'),
  ('لا تُخْبِرَنَّ إلاّ عَنْ ثِقَة فَتَكُونَ كَذَّاباً، وإنْ أخْبَرتَ عَنْ غَيرِهِ فَإنَّ الكَذِبَ مَهانَةٌ وذُلٌّ.', 'Never transmit information except from a reliable person otherwise you will become a liar, and if you transmit from other than him then surely telling lies is [a cause of] disgrace and dishonour.', 'Ghurar al-Hikam, Narration And Transmission Of Information §2', 'wisdom'),
  ('لاتُسْرِعْ إلَى النَّاسِ بِما يَكْرَهُونَ، فَيَقُولُوا فيكَ ما لايَعْلَمُونَ.', 'Do not hasten to the people with that which they dislike so that they [begin to] speak about you that which they do not know.', 'Ghurar al-Hikam, Narration And Transmission Of Information §3', 'wisdom'),
  ('اعْقِلُوا الخَبَرَ إذا سَمِعْتُمُوهُ عَقْلَ دِرايَة لا عَقْلَ رِوايَة، فَإنَّ رُواةَ العِلمِ كَثيرٌ، ورُعاتَهُ قَليلٌ.', 'Analyze the information when you hear it with the analysis of understanding (i.e. in order to understand it), not the analysis of narration (i.e. in order to narrate it to others), for indeed the narrators of information are many but those who consider it carefully are few.', 'Ghurar al-Hikam, Narration And Transmission Of Information §4', 'wisdom'),
  ('لَنْ يُصْدَقَ الخَبَـرُ حتّى يَتَحَقَّقَ العَيانُ.', 'Reports will never be accepted as true until [they are] verified by the eyes.', 'Ghurar al-Hikam, Narration And Transmission Of Information §5', 'wisdom'),
  ('اِصْحَبْ تَخْتَبِرْ.', 'Accompany [people] so that you may gauge [their true nature].', 'Ghurar al-Hikam, Gauging People §1', 'wisdom'),
  ('مَنِ اخْتَـبَرَ قَلا(وَ هَجَرَ).', 'One who gauges [the people] detests (or keeps away from) [them].', 'Ghurar al-Hikam, Gauging People §2', 'wisdom'),
  ('اَلطُمَأنِينَةُ إلى كُلِّ أحَد قَبْلَ الاِخْتِبارِ مِنْ قُصُورِ العَقْلِ.', 'Being at ease with every person before gauging [them] is from lack of intellect.', 'Ghurar al-Hikam, Gauging People §3', 'wisdom'),
  ('مَنِ اطْمَأنَّ قَبلَ الاِختِبارِ نَدِمَ.', 'One who feels at ease [with people] before gauging them, regrets.', 'Ghurar al-Hikam, Gauging People §4', 'wisdom'),
  ('إيّاك َ والخَديعَةَ، فَإنَّ الخَديعَةَ مِنْ خُلْقِ اللَّئيمِ.', 'Beware of [engaging in] deception, for verily deception is from the qualities of the vile.', 'Ghurar al-Hikam, Deception And The Deceitful §1', 'wisdom'),
  ('غَرَّ عَقْلَهُ مَنْ أتْبَعَهُ الخُدَعَ.', 'He who makes his intelligence follow deceptions has deluded it.', 'Ghurar al-Hikam, Deception And The Deceitful §2', 'wisdom'),
  ('مَنْ خادَعَ اللّهَ خُدِعَ.', 'One who tries to deceive Allah is [himself] deceived.', 'Ghurar al-Hikam, Deception And The Deceitful §3', 'wisdom'),
  ('لادينَ لِخَدَّاع.', 'The deceiver has no religion.', 'Ghurar al-Hikam, Deception And The Deceitful §4', 'wisdom'),
  ('اِضْرِب خادِمَكَ إذا عَصَى اللّهَ، واعْفُ عَنْهُ إذا عَصاكَ.', 'Beat your servant when he disobeys Allah but forgive him when he disobeys you.', 'Ghurar al-Hikam, The Servant §1', 'wisdom'),
  ('مِنْ عَلاماتِ الخِذلانِ اِسْتِحْسانُ القَبيحِ.', 'From the signs of being forsaken by Allah is considering that which is evil as something good.', 'Ghurar al-Hikam, The Servant §1', 'wisdom'),
  ('مِنْ دَلائِلِ الخِذْلانِ الاِسْتِهانَةُ بِحُقُوقِ الإخوانِ.', 'One of the indications of being forsaken by Allah is taking the rights of [one’s] brothers lightly.', 'Ghurar al-Hikam, The Servant §2', 'wisdom'),
  ('اَلخِذلانُ مُمِدُّ الجَهْلِ.', 'Abandonment is a support for ignorance.', 'Ghurar al-Hikam, The Servant §3', 'wisdom'),
  ('المَخْذولُ مَنْ لَهُ إلَى اللِّئامِ حاجَةٌ.', 'The forsaken is he who has to ask for something from the ignoble.', 'Ghurar al-Hikam, The Servant §4', 'wisdom'),
  ('اَلخَرَسُ خَيْرٌ مِنَ الكِذْبِ.', 'Muteness is better than lying.', 'Ghurar al-Hikam, Muteness §1', 'wisdom'),
  ('الخُرْقُ مُعاداةُ الآراءِ، ومُعاداةُ مَنْ يَقْدِرُ علَى الضَّـرّاءِ.', 'Ineptness is opposing [others’] views and having enmity with one who is capable of causing harm.', 'Ghurar al-Hikam, Ineptness §1', 'wisdom'),
  ('إيّاكَ والخُرْقَ، فَإنَّهُ شَيْنُ الأخلاقِ.', 'Be cautious of ineptness for it is disgraces [one’s] character.', 'Ghurar al-Hikam, Ineptness §2', 'wisdom'),
  ('اَقْبَحُ شَيْء الخُرْقُ.', 'The ugliest thing is ineptness.', 'Ghurar al-Hikam, Ineptness §3', 'wisdom'),
  ('اَسْوَءُ شَيْء اَلخُرْقُ.', 'The worst thing is ineptness.', 'Ghurar al-Hikam, Ineptness §4', 'wisdom'),
  ('اَلخُرْقُ شَينُ الخُلقِ.', 'Ineptness is a disgraceful attribute.', 'Ghurar al-Hikam, Ineptness §5', 'wisdom'),
  ('اَلْخُرْقُ شَرُّ خُلق.', 'Ineptness is the worst quality.', 'Ghurar al-Hikam, Ineptness §6', 'wisdom'),
  ('بِئسَ الشّيمَةُ الخُرْقُ.', 'How bad a quality ineptness is!', 'Ghurar al-Hikam, Ineptness §7', 'wisdom'),
  ('رَأسُ الجَهْلِ الخُرْقُ.', 'The height of ignorance is ineptness.', 'Ghurar al-Hikam, Ineptness §8', 'wisdom'),
  ('مَنْ كَثُرَ خُرْقُهُ اُسْتُرذِلَ.', 'One whose ineptness increases is scorned.', 'Ghurar al-Hikam, Ineptness §9', 'wisdom'),
  ('كَمْ مِنْ رَفيع وَضَعَهُ قُبْحُ خُرْقِهِ.', 'How many an elevated person has been degraded by the ugliness of his ineptitude!', 'Ghurar al-Hikam, Ineptness §10', 'wisdom'),
  ('رُبَّ رابح خاسر.', 'Many a person who gains is [actually] a loser.', 'Ghurar al-Hikam, The Loser §1', 'wisdom'),
  ('أخسَرُكُمْ أظْلَمُكُمْ.', 'The biggest loser from among you is the most unjust from among you.', 'Ghurar al-Hikam, The Loser §2', 'wisdom'),
  ('ما أخْسَرَ مَنْ لَيْسَ لَهُ فِي الآخِرَةِ نَصيبٌ.', 'How great a loser is he for whom there is no share [of reward] in the Hereafter!', 'Ghurar al-Hikam, The Loser §3', 'wisdom'),
  ('إذا أنتَ هُديتَ لِقَصْدِكَ فَكُنْ أخْشَعَ ما تَـكُونُ لِرَبِّكَ.', 'When you are guided to your goal then be most submissive in front of your Lord.', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §1', 'character'),
  ('كُلُّ شَيْء خاضِعٌ لِلّهِ.', 'Everything is humble in front of Allah.', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §2', 'character'),
  ('كُلُّ شَيْء خاشِعٌ لِلّهِ.', 'Everything is submissive in front of Allah.', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §3', 'character'),
  ('مَنْ خَشَعَ قَلْبُهُ حَشَعَتْ جَوارِحُهُ.', 'One whose heart submits, his limbs [also] submit.', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §4', 'character'),
  ('مَنْ خَضَعَ لِعَظَمَةِ اللّهِ ذَلَّتْ لَهُ الرِّقابُ.', 'Whoever is humble in front of the majesty of Allah, people become submissive to him.', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §5', 'character'),
  ('نِعمَ الطَّاعَةُ الأنْقيادُ، والخُضوعُ.', 'The best form of obedience is submission and humility.', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §6', 'character'),
  ('نِعمَ عَونُ الدُّعاءِ الخُشُوعُ.', 'How good a supporter of supplication submissiveness!', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §7', 'character'),
  ('لاعِبادَةَ كَالخُضُوعِ.', 'There is no worship like [that which is accompanied by] humility.', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §8', 'character'),
  ('الخُضُوعُ دِناءَةٌ', 'Humility means servility [in front of Allah].', 'Ghurar al-Hikam, Submissiveness And Humility In Front Of Allah §9', 'character'),
  ('مَنْ يَكُنِ اللّهُ سُبْحانَهُ خَصْمَهُ يُدحِضْ حُجَّتَهُ، ويُعَذِّبْهُ فِي الدُّنيا وَمََعادِهِ.', 'One whose enemy is Allah, the Glorified, his proof is refuted and he is punished in this world and in his Hereafter.', 'Ghurar al-Hikam, The Foe Of Allah §1', 'wisdom'),
  ('مَنْ يَكُنِ اللّهُ خَصْمَهُ يُدْحِضْ حُجَّتَهُ، وَيَكُنْ لَهُ حَرباً.', 'One whose enemy is Allah, his proof is refuted and Allah wages war with him.', 'Ghurar al-Hikam, The Foe Of Allah §2', 'wisdom'),
  ('اِلْقِ دَواتَكَ، وأطِلْ جَلْفَةَ قَلَمِكَ، وفَرِّقْ بَيْـنَ سُطورِكَ، وقَرْمِطْ بَينَ حُروفِكَ، فإنَّ ذلِكَ أجْدَرُبِصَباحَةِ الخَطِّ.', 'Put cotton in your inkpot, keep the nib of your pen long, leave space between your lines and keep the letters close to each other, for this makes the writing more beautiful.', 'Ghurar al-Hikam, Writing §1', 'wisdom'),
  ('اِفْتَحْ بَرْيَةَ قَلََمِكَ، واسْمِكْ شَحْمَتَهُ، وأيْمِنْ قِطَّتَكَ، يَجُدْ خَطُّكَ.', 'Open the sharpened nib of your pen, thicken its point [so that it does not break easily] and cut the edge on the right side so that your handwriting becomes good.', 'Ghurar al-Hikam, Writing §2', 'wisdom'),
  ('الخَطُّ لِسانُ اليَدِ.', 'Writing is the tongue of the hand.', 'Ghurar al-Hikam, Writing §3', 'wisdom'),
  ('لِقاحُ الخَواطِرِ المُذاكَرَةُ.', 'The imbuement of ideas is through deliberation.', 'Ghurar al-Hikam, Ideas §1', 'wisdom'),
  ('اَلمُخاطِرُ مُتَهَجِّمٌ عَلَى الغَرَرِ.', 'The daring risk-taker charges towards danger.', 'Ghurar al-Hikam, The Daring §1', 'wisdom'),
  ('كَثْرَةُ الخَطاءِ يُنْذِرُ بِوُفُورِ الجَهلِِ.', 'Making many mistakes points towards excessive ignorance.', 'Ghurar al-Hikam, Mistakes §1', 'wisdom'),
  ('اَلإخْلاصُ خَطَرٌ عَظيمٌ حتّى يُنْظَرَ بِما يُخْتَمُ لَهُ.', 'Sincerity is in grave danger, until it is seen what it concludes with.', 'Ghurar al-Hikam, Sincerity And Devotion §1', 'forgiveness'),
  ('أخْلِصْ تَنَلْ.', 'Be sincere and you will attain [success].', 'Ghurar al-Hikam, Sincerity And Devotion §2', 'forgiveness'),
  ('أخْلِصْ لِلّهِ عَمَلَكَ، وعِلْمَكَ، وحُبَّكَ، وبُغْضَكَ، وأخْذَكَ، وتَرْكَكَ، وكَلامَكَ، وصَمْتَكَ.', 'Let your action, your knowledge, your love, your hatred, your taking, your leaving, your speech and your silence [all] be [sincerely] for the sake of Allah.', 'Ghurar al-Hikam, Sincerity And Devotion §3', 'forgiveness'),
  ('اِلْزَمِ الإخْلاصَ فيِ السِّـرِّ والعَلانِيَةِ، والخَشيَةَ فِي الغَيْبِ والشَهادَةِ، والقَصْدَ فِي الفَقْرِ والغِنى، والعَدْلَ فِي الرِّضا والسَّخَطِ.', 'Adopt sincerity in secret and in the open, fear [of Allah] when unseen and seen, moderation in poverty and wealth, and equity in satisfaction and anger.', 'Ghurar al-Hikam, Sincerity And Devotion §4', 'forgiveness'),
  ('أخْلِصُوا إذا عَمِلْتُمْ.', 'Be sincere when you perform an action [and do it only for the pleasure of Allah].', 'Ghurar al-Hikam, Sincerity And Devotion §5', 'forgiveness'),
  ('اَلإخْلاصُ غايَةٌ.', 'Sincerity is the goal [of worship].', 'Ghurar al-Hikam, Sincerity And Devotion §6', 'forgiveness'),
  ('اَلإخْلاصُ فَوزٌ.', 'Sincerity is [a means of attaining] success.', 'Ghurar al-Hikam, Sincerity And Devotion §7', 'forgiveness'),
  ('اَلإخلاصُ خَيْرُ العَمَلِ.', 'Being sincere is the best of actions.', 'Ghurar al-Hikam, Sincerity And Devotion §8', 'forgiveness'),
  ('اَلإخْلاصُ ثَمَرَةُ العِبادَةِ.', 'Sincerity is the fruit of worship.', 'Ghurar al-Hikam, Sincerity And Devotion §9', 'forgiveness'),
  ('اَلإخْلاصُ شيمَةُ أفاضِلِ النَّاسِ.', 'Sincerity is the attribute of the most excellent people.', 'Ghurar al-Hikam, Sincerity And Devotion §10', 'forgiveness'),
  ('واعَجَبا أنْ تَـكُونَ الخِلافَةُ بِالصَّحابَةِ ولا تَـكُونَ بِالصَّحابَةِ والقَرابَةِ.', 'How strange it is that the succession [to the Prophet] is [decided] by companionship [only] and not by companionship and kinship.', 'Ghurar al-Hikam, Sucession §1', 'wisdom'),
  ('لِلّهِ سُبْحانَهُ حُكْمٌ بَيِّنٌ فِي المُسْتأثِرِ والجازِعِ.', 'With Allah, the Glorified, lies the clear verdict between the appropriator [Uthmān] and the protestor [who was responsible for his assassination].', 'Ghurar al-Hikam, The Caliphs §1', 'wisdom'),
  ('اَلخِلافُ يَهْدِمُ الآراءَ.', 'Disagreement wrecks [good] ideas.', 'Ghurar al-Hikam, Disagreement §1', 'wisdom'),
  ('اَلاُمُورُ المُنْتَظِمَةُ يُفْسِدُهَا الخِلافُ.', 'Organized affairs are disrupted by disagreement.', 'Ghurar al-Hikam, Disagreement §2', 'wisdom'),
  ('سَبَبُ الفُرْقَةِ اَلاِخْتِلافُ.', 'The cause of disunity is disagreement.', 'Ghurar al-Hikam, Disagreement §3', 'wisdom'),
  ('لَيْسَ مََعَ الخِلافِ اِيتِلافٌ.', 'With disagreement there is no harmony.', 'Ghurar al-Hikam, Disagreement §4', 'wisdom'),
  ('مِنَ الخِلافِ تَـكُونُ النَّبْوَةُ.', 'From disagreement stems repulsion [and hatred].', 'Ghurar al-Hikam, Disagreement §5', 'wisdom'),
  ('كَثْرَةُ الخِلافِ شِقاقٌ.', 'Too much disagreement is discord.', 'Ghurar al-Hikam, Disagreement §6', 'wisdom'),
  ('اَلخُلْفُ مَثارُ الحُُروبِ.', 'Disagreement is the motive for wars.', 'Ghurar al-Hikam, Disagreement §7', 'wisdom'),
  ('اَلمُخاصَمَةُ تُبْدي سَفَهَ الرَّجُلِ ولاتَزيدُ في حَقِّهِ.', 'Disputes demonstrate the foolishness of a person and do not increase his claim.', 'Ghurar al-Hikam, Disagreement §8', 'wisdom'),
  ('الخُلْقُ السَّجيحُ أحَدُ النِّعْمَتينِ.', 'A refined character is one of the two blessings.', 'Ghurar al-Hikam, Good Character §1', 'character'),
  ('أحْسَنُ شَيْء اَلخُلْقُ.', 'The best thing is [good] character.', 'Ghurar al-Hikam, Good Character §2', 'character'),
  ('أكْرَمُ الحَسَبِ الخُلْقُ.', 'The most honourable distinction is [good] character.', 'Ghurar al-Hikam, Good Character §3', 'character'),
  ('أحْسَنُ الشِّيَمِ شَرَفُ الهِمَمِ.', 'The best of qualities is honourable ambition.', 'Ghurar al-Hikam, Good Character §4', 'character'),
  ('أزْيَنُ الشِّيَمِ اَلْحِلمُ والعِفافُ.', 'The most beautiful qualities are forbearance and chastity.', 'Ghurar al-Hikam, Good Character §5', 'character'),
  ('أطْهَرُ النَّاسِ أعْراقاً أحْسَنُهُمْ أخْلاقاً.', 'The purest of all people in lineage is the best of them in character.', 'Ghurar al-Hikam, Good Character §6', 'character'),
  ('أرْضَى النَّاسِ مَنْ كانَتْ أخْلاقُهُ رَضِيَّةً.', 'The most pleased of all people is one whose character is agreeable.', 'Ghurar al-Hikam, Good Character §7', 'character'),
  ('أحْسَنُ السَّناءِ الخُلْقُ السَّجيحُ.', 'The best eminence is [in possessing] a beautiful character.', 'Ghurar al-Hikam, Good Character §8', 'character'),
  ('أشْرَفُ أخلاقِ الكَريمِ تَغافُلُهُ عَمَّا يَعْلَمُ.', 'The most honourable quality of the noble one is his feigning inattention [and ignorance] about that which he is aware [regarding the negative traits of others].', 'Ghurar al-Hikam, Good Character §9', 'character'),
  ('أفْضَلُ الشِّيَمِ السَّخاءُ والعِفَّةُ والسَّكينَةُ.', 'The best of qualities are generosity, chastity and tranquillity.', 'Ghurar al-Hikam, Good Character §10', 'character'),
  ('كُلُّ مَخْلُوق يَجْري إلى ما لايَدْري', 'Every creation is moving towards that which it has no knowledge of.', 'Ghurar al-Hikam, Creation §1', 'wisdom'),
  ('سَبَبُ الفُجورِ الخَلْوَةُ.', 'The cause of immorality is seclusion.', 'Ghurar al-Hikam, Seclusion §1', 'wisdom'),
  ('مُلازَمَةُ الخَلْوَةِ دَأْبُ الصُّلَحاءِ.', 'Remaining in seclusion (when it is required to safeguard faith) is the habit of the righteous.', 'Ghurar al-Hikam, Seclusion §2', 'wisdom'),
  ('وتَرْكَ شُـرْبِ الخَمْرِ تَحصيناً لِلْعَقْلِ.', 'Abandoning the drinking of wine is [commanded as] a protection for the mind.', 'Ghurar al-Hikam, Wine §1', 'wisdom'),
  ('خَـمْسَةٌ يَنْبَغي أنْ يُهانُوا: اَلدَّاخِلُ بَيْنَ اثْنَيْنِ، لَمْ يُدْخِلاهُ في أمْرِهما، وَالمُتَأمِّرُ على صاحِبِ البَيْتِ في بَيْتِهِ، والمُتَقَدِّمُ على مائِدَة لَمْ يُدْعَ إلَيها، وَالمُقبلُ بِحَديثِهِ على غَيرِ مُسْتَمِع، والجالِسُ فِي المَجالِسِ الَّتي لايَسْتَحِقُّها.', 'Five [types of people] are worthy of being humiliated: The one who interferes between two people when they have not involved him in their affair, the one who issues commands to the owner of the house [while] in his house, the one who approaches a dining table when he has not been invited to do so, the one who continues talking when nobody is listening and the one who sits in the place where he has no right to sit.', 'Ghurar al-Hikam, Five Bad Qualities §1', 'wisdom'),
  ('خَمْسٌ يُسْتَقْبَحْنَ مِنْ خَمْس: كَثْرَةُ الفُجورِ مِنَ العُلَماءِ، والحِرْصُ في الحُكَماءِ، والبُخلُ فيِ الأغْنياءِ، والقِحَةُ في النِّساءِ ومِنَ المَشايِخِ الزِّنا.', 'Five qualities are detested from five [people]: Excessive licentiousness from scholars, greed from sages, stinginess from the wealthy, shamelessness from women and from the elders, adultery.', 'Ghurar al-Hikam, Five Bad Qualities §2', 'wisdom'),
  ('إنَّ فيِ الخُمُولِ لَراحَةً.', 'Verily in anonymity [and lack of fame and prominence] there is peace of mind.', 'Ghurar al-Hikam, Anonymity §1', 'wisdom'),
  ('الخَوْفُ سِجْنُ النَّفْسِ عَنِ الذُّنُوبِ، ورادِعُها عَنِ المَعاصي.', 'Fear [of Allah] is the imprisonment of the self from sins and its impediment from vices.', 'Ghurar al-Hikam, Fear §1', 'wisdom'),
  ('الخَوْفُ مِنَ اللّهِ في الدُّنيا، يُؤْمِنُ الخَوْفَ فِي الآخِرَةِ مِنْهُ.', 'Fear of Allah in this world makes one safe from fear of Him in the Hereafter.', 'Ghurar al-Hikam, Fear §2', 'wisdom'),
  ('إرْهَبْ تُحذَرْ.', 'Fear [Allah] and you will be feared by the people.', 'Ghurar al-Hikam, Fear §3', 'wisdom'),
  ('أخْوَفُكُمْ أعْرَفُكُمْ.', 'The most fearful [of Allah] among you are the ones who know [Him] the most.', 'Ghurar al-Hikam, Fear §5', 'wisdom'),
  ('اَلخَوْفُ أمانٌ.', 'Fear [of Allah] is security.', 'Ghurar al-Hikam, Fear §6', 'wisdom'),
  ('اَلخَشْيَةُ مِنْ عَذابِ اللّهِ شِيمَةُ المُتَّقينَ.', 'Fear of the punishment of Allah is a quality of the God-wary.', 'Ghurar al-Hikam, Fear §7', 'wisdom'),
  ('اَلخَوْفُ جِلْبابُ العارِفينَ.', 'Fear [of Allah] is the gown of the Gnostics.', 'Ghurar al-Hikam, Fear §8', 'wisdom'),
  ('اَلوَجَلُ شِعارُ المُؤْمِنينَ.', 'Fear [of Allah] is the distinguishing feature of the believers.', 'Ghurar al-Hikam, Fear §9', 'wisdom'),
  ('إذا خِفْتَ الخالِقَ فَرَرْتَ إلَيهِ.', 'When you fear the Creator, you flee towards Him.', 'Ghurar al-Hikam, Fear §10', 'wisdom'),
  ('ثَمَرَةُ الخَوْفِ الأمْنُ.', 'The fruit of fear is security.', 'Ghurar al-Hikam, Fear §11', 'wisdom'),
  ('إذا خِفْتَ المَخْلُوقَ فَرَرْتَ مِنْهُ.', 'Whenever you fear the created [as opposed to the Creator], you flee from him.', 'Ghurar al-Hikam, Fearing Other Than Allah §1', 'wisdom'),
  ('إذا هِبْتَ أمْراً فَقَعْ فيهِ، فإنَّ شِدَّةَ تَوَقّيهِ أشَدُّ مِنَ الوُقُوعِ فيهِ.', 'When you are frightened of something then jump into it, for indeed the difficulty of safeguarding yourself from it is greater than [that of] entering into it.', 'Ghurar al-Hikam, Fearing Other Than Allah §2', 'wisdom'),
  ('وقال ـ عليه السّلام ـ في حَقِّ مَنْ ذَمَّهُ: جَعَلَ خَوْفَهُ مِنَ العِبادِ نَقْداً، ومِنْ خالِقِهِمْ (خالِقهِ) ضَماناً (ضِماراً) وَوَعْداً.', 'He (‘a) said about the one whom he censured: …he has made his fear of men ready currency while his fear of the Creator a mere guarantee or promise [to be carried out later].', 'Ghurar al-Hikam, Fearing Other Than Allah §3', 'wisdom'),
  ('مَنْ خافَ النَّاسَ أخافَهُ اللّهُ سُبْحانَهُ مِنْ كُلِّ شَيْء.', 'One who fears the people, Allah, the Glorified, makes him afraid of everything.', 'Ghurar al-Hikam, Fearing Other Than Allah §4', 'wisdom'),
  ('اَلخائِفُ لا عَيْشَ لَهُ.', 'The fearful one has no life.', 'Ghurar al-Hikam, The Fearful §1', 'wisdom'),
  ('كَمْ مِنْ خائِف وَفَدَ بِهِ خَوفُهُ على قَرارَةِ الأمْنِ.', 'How many a fearful person has been taken to a place of safety by his fear.', 'Ghurar al-Hikam, The Fearful §2', 'wisdom'),
  ('مَنْ هابَ خابَ.', 'One who fears, fails.', 'Ghurar al-Hikam, The Fearful §3', 'wisdom'),
  ('مَنْ لَمْ يُخِفْ أحَداً لَمْ يَخَفْ أبَداً.', 'One who does not frighten others will never be frightened [by anyone].', 'Ghurar al-Hikam, Frightening Others §1', 'wisdom'),
  ('مَنْ أخافَكَ لِكَى يُؤْمِنَكَ خَيْـرٌ لَكَ مِمَّنْ يُؤْمِنُكَ لِكَىْ يُخيفَكَ.', 'One who frightens you [from committing sins] in order to protect you [from punishment] is better than one who gives you a [false] sense of security on order that you may become frightened.', 'Ghurar al-Hikam, Frightening Others §2', 'wisdom'),
  ('لِلْخائِبِ الآئِسِ مَضَضُ الهَلاكِ.', 'For the frustrated and hopeless one there is the anguish of ruin [and loss].', 'Ghurar al-Hikam, The Frustrated §1', 'wisdom'),
  ('اَلخَيرُ لا يَفْنى.', 'Good does not perish.', 'Ghurar al-Hikam, Good §1', 'character'),
  ('اَلخَيْـرُ أسْهَلُ مِنْ فِعلِ الشَّـرِّ.', 'Good is easier [to do] than an evil action.', 'Ghurar al-Hikam, Good §2', 'character'),
  ('آفَةُ الخَيْرِ قَرينُ السُّوءِ.', 'The bane of goodness is an evil companion.', 'Ghurar al-Hikam, Good §3', 'character'),
  ('إذا عَقَدْتُمْ على عَزائِمِ خَيْر فَامْضُوها.', 'When you make the intention of doing good, then execute it.', 'Ghurar al-Hikam, Good §4', 'character'),
  ('إذا رَأيْتُمُ الخَيـْرَ فَخُذُوا بهِ.', 'When you witness [a] good [deed] then take to it.', 'Ghurar al-Hikam, Good §5', 'character'),
  ('ثَلاثٌ هُنَّ جِماعُ الخَيرِ: إسْداءُ النِّعَمِ، ورِعايَةُ الذِّمَمِ، وصِلَةُ الرَّحِمِ.', 'Three things consolidate that which is good: bestowing favours, guarding [one’s] sureties and keeping ties with near relatives.', 'Ghurar al-Hikam, Good §6', 'character'),
  ('جِماعُ الخَيرِ فيِ العَمَلِ بِما يَبْقى، والاسْتِهانَةِ بِما يَفنى.', 'Consolidation of good is in acting on that which lasts and making light of that which perishes.', 'Ghurar al-Hikam, Good §7', 'character'),
  ('أصلِح المُسيئَ بِحُسْنِ فِعالِكَ ودُلَّ عَلَى الخَيـْرِ بِجَميلِ مَقالِكَ.', 'Reform the evildoer with your good actions and guide [others] towards good by your beautiful [and kind] words.', 'Ghurar al-Hikam, Good §8', 'character'),
  ('اِفْعَلِ الخَيرَ ولا تُحَقِّرْ مِنْهُ شَيْئاً، فَإنَّ قَليلَهُ كَثيرٌ وفاعِلَهُ مَحبُورٌ.', 'Do good and do not consider any of it insignificant, for verily little of it is plenty and its doer is happy [in the Hereafter].', 'Ghurar al-Hikam, Good §9', 'character'),
  ('أكثِرْ سُرُورَكَ على ما قَدَّمْتَ مِنَ الخَيرِ، وحُزْنَكَ على ما فاتَ مِنْهُ.', 'Increase your gladness for that which you have sent forth of good deeds and [increase] your sadness for that which you have missed from it.', 'Ghurar al-Hikam, Good §10', 'character'),
  ('أرْبَعٌ مَنْ اُعْطِيَهُنَّ فَقَدْ اُعْطِيَ خَيْرَ الدُّنْيا وَالآخِرَةِ: صِدْقُ حَديث، وَأداءُ أمانَة، وعِفَّةُ بَطْن، وحُسْنُ خُلق.', 'Four [qualities] are such that whoever they have been given to has been given the good of this world and the Hereafter: truthful speech, fulfilling the trust, abstinence from consuming what is forbidden and good character.', 'Ghurar al-Hikam, Good Of This World And The Hereafter §1', 'mortality'),
  ('ثَلاثٌ مَنْ كُنَّ فيهِ فَقَدْ رُزِقَ خَيْرَ الدُّنْيا وَالآخِرَةِ: هُنَّ الرِّضا بِالقَضاءِ، وَالصَّبْرُ عَلَى البَلاءِ، وَالشُّكْرُ فِي الرَّخاءِ.', 'Three [traits] are such that whoever possesses them has been bestowed with the good of this world and the Hereafter. They are: being satisfied with what has been decreed [by Allah], patience in the face of hardship and thankfulness in times of ease [and prosperity].', 'Ghurar al-Hikam, Good Of This World And The Hereafter §2', 'mortality'),
  ('اِسْتَخِرْ ولا تَتَخَيَّرْ، فَكَمْ مَنْ تَخَيَّرَ أمْراً كانَ هَلاكُهُ فيهِ.', 'Seek what is best and do not chose what you want, for how many a person who has chosen what he wanted and found his own destruction in it!', 'Ghurar al-Hikam, Seeking What Is Best §1', 'wisdom'),
  ('إذا أمْضَيْتَ فَاسْتَخِرْ.', 'When you embark on something, seek what is best from it.', 'Ghurar al-Hikam, Seeking What Is Best §2', 'wisdom'),
  ('ما نَدِمَ مَنِ اسْتَخارَ.', 'He who seeks what is best [in his actions] does not regret.', 'Ghurar al-Hikam, Seeking What Is Best §3', 'wisdom'),
  ('سُنَّةُ الأخْيارِ لِينُ الكَلامِ، وإفْشاءُ السَّلامِ.', 'The practice of the virtuous ones is polite speech and spreading peace.', 'Ghurar al-Hikam, The Virtuous §1', 'wisdom'),
  ('مَنْ ساءَ اِخْتيارُهُ قَبُحَتْ آثارُهُ.', 'One whose choice is bad, his results become ugly.', 'Ghurar al-Hikam, Choice §1', 'wisdom'),
  ('مِنْ سُوءِ الاختيارِ مُغالَبَةُ الأكْفاءِ، ومُعاداةُ الرِّجالِ.', 'Some bad choices are seeking to overpower one’s equals and making enmity with people.', 'Ghurar al-Hikam, Choice §2', 'wisdom'),
  ('مِنْ أحْسَنِ الاخْتيارِ صُحْبَةُ الأخيارِ.', 'One of the best choices is accompanying the virtuous.', 'Ghurar al-Hikam, Choice §3', 'wisdom'),
  ('مِنْ سُوءِ الاخْتيارِ مُغالَبَةُ الأكْفاءِ، ومُكاشَفَةُ الأعْداءِ ومُناواةُ مَنْ يَقْدِرُ عَلَى الضَّـرّاءِ.', 'Some of the bad choices are fighting [and seeking to overpower] one’s equals, unveiling an enemy and showing hostility towards one who is able to do harm.', 'Ghurar al-Hikam, Choice §4', 'wisdom'),
  ('مِنْ أفْضَلِِ الاختيارِ وأحسَنِ الاستظْهارِ أنْ تَعْدِلَ فِي الحُكْمِ (القَضاءِ)، وتُجرِيَهُ فِي الخاصَّةِ والعامَّةِ عَلَى السَّواءِ.', 'One of the most excellent choices and best precautions [and supports] is for you to be just in your ruling (or judgment) and to carry it out among the special and the ordinary [people] equally.', 'Ghurar al-Hikam, Choice §5', 'wisdom'),
  ('مِنْ أفْضَلِ الاخْتيارِ التَّحَلّي بِالإيثارِ.', 'From the best of choices is adorning oneself with selflessness.', 'Ghurar al-Hikam, Choice §6', 'wisdom'),
  ('مِنْ حُسْنِ الاخْتيارِ مُقارَنَةُ الأخْيارِ، ومُفارَقَةُ الأشرارِ.', 'From the good choices [one makes] is keeping company with the virtuous and keeping a distance from the wicked.', 'Ghurar al-Hikam, Choice §7', 'wisdom'),
  ('بِئْسَ الاخْتيارُ الرِّضا بِالنَّقْصِ.', 'The worst choice is being satisfied with deficiency.', 'Ghurar al-Hikam, Choice §8', 'wisdom'),
  ('مَنْ لَمْ يَصْلُحْ عَلَى اخْتيارِ اللّهِ لَمْ يَصْلُحْ عَلَى اخْتيارِهِ لِنَفْسِهِ.', 'Whoever does not get reformed by that which Allah has chosen [for him] will not be reformed by what he chooses for himself.', 'Ghurar al-Hikam, The Choice Of Allah §1', 'wisdom'),
  ('جانِبُوا الخِيانَةَ فَإنَّها مُجانَبَةُ الإسلامِ.', 'Keep away from treachery for it is [a cause of] turning away from Islam.', 'Ghurar al-Hikam, Treachery And Disloyalty §1', 'wisdom'),
  ('رَأسُ النِّفاقِ الخِيانَةُ.', 'The cornerstone of hypocrisy is treachery.', 'Ghurar al-Hikam, Treachery And Disloyalty §2', 'wisdom'),
  ('رَأسُ الكُفْرِ الخِيانَةُ.', 'The peak of ingratitude is disloyalty.', 'Ghurar al-Hikam, Treachery And Disloyalty §3', 'wisdom'),
  ('غايَةُ الخِيانَةِ خِيانَةُ الخِلِّ الوَدُودِ ونَقْضُ العُهُودِ.', 'The highest form of treachery is the treachery of a beloved friend and the breaking of pledges.', 'Ghurar al-Hikam, Treachery And Disloyalty §4', 'wisdom'),
  ('مَنْ عَمِلَ بِالخِيانَةِ فَقَدْ ظَلَمَ الأمانَةَ.', 'One who acts with treachery has done injustice to the trust [that was entrusted to him].', 'Ghurar al-Hikam, Treachery And Disloyalty §5', 'wisdom'),
  ('مِنْ أفْحَشِ الخِيانَةِ خِيانَةُ الوَدائِعِ.', 'From the most grievous forms of treachery is being treacherous with trusts or deposits [that one has been entrusted with].', 'Ghurar al-Hikam, Treachery And Disloyalty §6', 'wisdom'),
  ('لا تَخُنْ مَنِ ائْتَمَنَكَ وإنْ خانَكَ، ولا تَشِنْ عَدُوَّكَ وإنْ شانَكَ.', 'Do not act treacherously towards one who trusts you, even if he is disloyal with you, and do not disgrace your enemy, even if he disgraces you.', 'Ghurar al-Hikam, Treachery And Disloyalty §7', 'wisdom'),
  ('لاتَجْتَمِعُ الخِيانَةُ، والاُخُوَّةُ.', 'Treachery and brotherhood do not go together.', 'Ghurar al-Hikam, Treachery And Disloyalty §8', 'wisdom'),
  ('إيّاكَ والخيانَةَ، فَإنَّها شَرُّ مََعصِيَة، وإنَّ الخائنَ لَمُعَذَّبٌ بِالنّارِ على خيانَتِهِ.', 'Keep away from treachery for it is the worst offence, and verily the treacherous one is surely punished with fire for his treachery.', 'Ghurar al-Hikam, Treachery And Disloyalty §9', 'wisdom'),
  ('أعْظَمُ الخِيانَةِ خِيانَةُ الأُمَّةِ.', 'The worst treachery is treachery against the nation.', 'Ghurar al-Hikam, Treachery And Disloyalty §10', 'wisdom'),
  ('الخائِنُ مَنْ شَغَلَ نَفْسَهُ بِغَيرِ نَفْسِِهِ، وكانَ يَوْمُهُ شَـرّاً مِنْ أمْسِهِ.', 'The treacherous person is one who busies himself with other than his self and his ‘today’ is worse than his ‘yesterday’.', 'Ghurar al-Hikam, The Treacherous §1', 'wisdom'),
  ('المُزيعُ والخائِنُ سَواءٌ.', 'The enticer [towards deviance] and the treacherous one are alike.', 'Ghurar al-Hikam, The Treacherous §2', 'wisdom'),
  ('اَلخائِنُ لا وَفاءَ لَهُ.', 'The treacherous person has no loyalty in him.', 'Ghurar al-Hikam, The Treacherous §3', 'wisdom'),
  ('مِنْ عَلاماتِ الخِذْلانِ ايتِمانُ الخُوّانِ.', 'From the signs of being forsaken [by Allah] is considering the treacherous to be trustworthy.', 'Ghurar al-Hikam, The Treacherous §4', 'wisdom'),
  ('رُبَّ دائب مُضَيِّع.', 'Many a diligent person also loses (or causes loss).', 'Ghurar al-Hikam, The Diligent And The Hardworking §1', 'wisdom'),
  ('رُبَّ كادِح لِمَنْ لايَشْكُرُهُ.', 'Many a person toils for the one who is not grateful to him.', 'Ghurar al-Hikam, The Diligent And The Hardworking §2', 'wisdom'),
  ('مَنِ اسْتَدْبَـرَ الأُمُورَ تَحَيَّرَ.', 'One who follows up [and thinks about] matters [that have passed], gets perplexed.', 'Ghurar al-Hikam, Following Up Matters §1', 'wisdom'),
  ('لا تَتَمَسَّكَنَّ بِمُدْبِر، ولا تُفارِقَنَّ مُقْبِلاً.', 'Never hold on to one who turns back and do not separate from the one who moves forward.', 'Ghurar al-Hikam, One Who Turns Back And The One Who Moves Forward §1', 'wisdom'),
  ('لَرُبَّما أقْبَلَ المُدْبِرُ، وأدْبَـرَ المُقْبِلُ.', 'It may be that sometimes the one who turns back moves forward and the one who moves forward turns back.', 'Ghurar al-Hikam, One Who Turns Back And The One Who Moves Forward §2', 'wisdom'),
  ('اَلقَلِيلُ مَعَ التَّدْبيرِ أبْقى مِنَ الكَثيرِ مَعَ التَّبْذيرِ.', 'Little [done] with planning is more lasting than a lot done with wastefulness.', 'Ghurar al-Hikam, Planning §1', 'wisdom'),
  ('أدَلُّ شَيْء على غَزارَةِ العَقْلِ حُسْنُ التَّدْبيرِ.', 'The most manifest sign of abundant intelligence is good planning.', 'Ghurar al-Hikam, Planning §2', 'wisdom'),
  ('التَّدْبيرُ بِالرَّأيِ، والرَّأيُ بِالفِكْرِ.', 'Planning comes with consideration and consideration comes with contemplation.', 'Ghurar al-Hikam, Planning §3', 'wisdom'),
  ('التَّدْبيرُ نِصْفُ المَعُونَةِ.', 'Planning is half of the assistance.', 'Ghurar al-Hikam, Planning §4', 'wisdom'),
  ('التَّدْبيرُ قَبْلَ العَمَلِ يُؤْمِنُ النَّدَمَ.', 'Planning before action saves one from regret.', 'Ghurar al-Hikam, Planning §5', 'wisdom'),
  ('التَّدْبيرُ قَبْلَ الفِعْلِ يُؤْمِنُ العِثارَ.', 'Planning before action saves one from error.', 'Ghurar al-Hikam, Planning §6', 'wisdom'),
  ('حُسْنُ التَّدْبيرِ، وتَجَنُّبُ التَّبْذيرِ مِنْ حُسْنِ السِّياسَةِ.', 'Good planning and keeping away from wastefulness are from good politics.', 'Ghurar al-Hikam, Planning §7', 'wisdom'),
  ('حُسْنُ التَّدْبيرِ يُنْمي قَليلَ المالِ، وسُوءُ التَّدْبيرِ يُفْني كَثيرَهُ.', 'Good planning makes little wealth grow while bad planning causes abundant wealth to perish.', 'Ghurar al-Hikam, Planning §8', 'wisdom'),
  ('سَبَبُ التَّدْميرِ سُوءُ التَّدبيرِ (سُوءُ التَّدبيرِ سَبَبُ التَّدْمير).', 'The cause of ruin is bad planning.', 'Ghurar al-Hikam, Planning §9', 'wisdom'),
  ('سُوءُ التَّدبيرِ مِفتاحُ الفَقْرِ.', 'Bad planning is the key to poverty.', 'Ghurar al-Hikam, Planning §10', 'wisdom'),
  ('جانِبُوا التَّخاذُلَ، والتَّدابُرَ، وقَطيعَةَ الأرْحامِ.', 'Keep away from abandonment, desertion and severing of ties with near relatives.', 'Ghurar al-Hikam, Desertion And Abandonment §1', 'wisdom'),
  ('قَلَّما يَعُودُ الإدْبارُ إقْبالاً.', 'It is seldom that one who turns back [and retreats] returns to the front.', 'Ghurar al-Hikam, Turning Backward §1', 'wisdom'),
  ('مِنْ عَلاماتِ الإدْبارِ مُقارَنَةُ الأرْذالِ.', 'From the signs of turning backward is accompanying the vile.', 'Ghurar al-Hikam, Turning Backward §2', 'wisdom'),
  ('مِنْ عَلاماتِ الإدْبارِ سُوءُ الظَّنِّ بالنَّصيحِ.', 'From the signs of turning backward is thinking ill of the one who gives you good advice.', 'Ghurar al-Hikam, Turning Backward §3', 'wisdom'),
  ('يُسْتَدَلُّ علَى الإدْبارِ بِأرْبَع:سُوْءُ التَّدْبيرِ، وقُبْحُ التَّبْذيرِ، وقِلَّةُ الإعْتِبارِ، وكَثْرَةُ الاعْتِذارِ (الاغْتِرارِ).', 'Turning backward is evinced by four things: bad planning, foul extravagance, lack of consideration and too many excuses.', 'Ghurar al-Hikam, Turning Backward §4', 'wisdom'),
  ('المَحاسِنُ فِي الإقبالِ هِيَ المَساوي فِي الإدْبارِ.', 'The merits in advancing forward are the demerits in turning backward.', 'Ghurar al-Hikam, Turning Backward §5', 'wisdom'),
  ('مَنْ دَخَلَ مَداخِلَ السُّوءِ أُتُّهِمَ.', 'One who enters into a place of evil is [suspected and] accused.', 'Ghurar al-Hikam, Entrance §1', 'wisdom'),
  ('لِكُلِّ داخِل دَهْشَةٌ وذُهُولٌ.', 'For everyone who enters [into an unfamiliar place] there is consternation and perplexity.', 'Ghurar al-Hikam, Entrance §2', 'wisdom'),
  ('لِكُلِّ داخِل دَهْشَةٌ فَابْدَأوا بِالسَّلامِ.', 'For everyone who enters there is [a feeling of] consternation, so begin with salaam 1 .', 'Ghurar al-Hikam, Entrance §3', 'wisdom'),
  ('لِكُلِّ قادِم حَيْرَةٌ فَابْسُطُوهُ بِالكَلامِ.', 'Everyone who arrives has [a feeling of] perplexity, so make him comfortable with [kind] words.', 'Ghurar al-Hikam, Entrance §4', 'wisdom'),
  ('أولَى النَّاسِ بِالحَذَرِ أسْلَمُهُمْ عَنِ الغِيَرِ.', 'Of all people, the person who needs to be most careful is the one who is most safe from abrupt changes [as this may be a means of gradually being drawn to his destruction].', 'Ghurar al-Hikam, Gradually Drawing Closer To Destruction §1', 'wisdom'),
  ('كَمْ مِنْ مُسْتَدرَج بِالإحْسانِ إلَيهِ.', 'How many a person is gradually drawn to his destruction through the good that is done to him.', 'Ghurar al-Hikam, Gradually Drawing Closer To Destruction §2', 'wisdom'),
  ('لافِقْهَ لِمَنْ لا يُديمُ الدَّرْسَ.', 'One who does not continue his study does not acquire deep understanding [of his subject].', 'Ghurar al-Hikam, Study §1', 'wisdom'),
  ('اَلمُسْتَدْرِكُ على شَفا صَلاح.', 'One who makes amends is on the brink of righteousness.', 'Ghurar al-Hikam, Rectification And Making Amends §1', 'wisdom'),
  ('تَدارَكْ في آخِرِ عُمْرِكَ ما أضَعْتَهُ في أوَّلِهِ تَسْعَدْ بِمُنْقَلَبِكَ.', 'Rectify at the end of your life that which you have neglected [and lost] earlier on and you will make your place of return a happy one.', 'Ghurar al-Hikam, Rectification And Making Amends §2', 'wisdom'),
  ('حُسْنُ الاستِدراكِ عُنْوانُ الصَّلاحِ.', 'Proper rectification [of one’s mistakes] is the symbol of righteousness.', 'Ghurar al-Hikam, Rectification And Making Amends §3', 'wisdom'),
  ('فازَ مَنْ أصْلَحَ عَمَلَ يَوْمِهِ، واسْتَدْرَكَ فَوارِطَ أمْسِهِ.', 'Successful is the one who reforms his current actions and makes amends for his past mistakes.', 'Ghurar al-Hikam, Rectification And Making Amends §4', 'wisdom'),
  ('مَنِ اسْتَدْرَكَ أصْلَحَ.', 'One who makes amends [for his past mistakes] reforms [himself].', 'Ghurar al-Hikam, Rectification And Making Amends §5', 'wisdom'),
  ('مَنِ اسْتَدْرَكَ فَوارِطَهُ أصْلَحَ.', 'One who rectifies his [past] mistakes reforms [himself].', 'Ghurar al-Hikam, Rectification And Making Amends §6', 'wisdom'),
  ('ما أبْعَدَ الاستِدراكَ مِنَ الفَوْتِ.', 'How far is making amends [for something] from [its initial] loss!', 'Ghurar al-Hikam, Rectification And Making Amends §7', 'wisdom'),
  ('تَعْجيلُ الاسْتِدْراكِ إصْلاحٌ.', 'Hastening rectification is reformation.', 'Ghurar al-Hikam, Rectification And Making Amends §8', 'wisdom'),
  ('دارِ النَّاسَ تَأمَنْ غَوائِلَهُمْ، وتَسْلَمْ مِنْ مَكائِدِهِمْ.', 'Be amicable with the people and you will be secure from their tribulations and will remain safe from their sly plots.', 'Ghurar al-Hikam, Amicableness §1', 'wisdom'),
  ('دارِ النّاسَ تَسْتَمْتِعْ بِإخائِهِمْ، والْقَهُمْ بِالبِشْرِ تُمِتْ أضْغانَهُمْ.', 'Be amicable with the people and you will enjoy their brotherhood; meet them with cheerfulness and you will cause their malice to die away.', 'Ghurar al-Hikam, Amicableness §2', 'wisdom'),
  ('دارِ عَدُوَّكَ، وأخْلُِصْ لِوَدوُدِكَ، تَحْفَظِ الأُخُوَّةَ، وتُحرِزِ المُـرُوءَةَ.', 'Be courteous to your enemy and be sincere with your close friend, [by this] you will protect [your] brotherhood and safeguard [your] magnanimity.', 'Ghurar al-Hikam, Amicableness §3', 'wisdom'),
  ('رَأسُ الحِكْمَةِ مُداراةُ النَّاسِ.', 'The cornerstone of wisdom is being amicable with the people.', 'Ghurar al-Hikam, Amicableness §4', 'wisdom'),
  ('سَلامَةُ العَيْشِ فِي المُداراةِ.', 'The soundness of life is in being amicable [with people].', 'Ghurar al-Hikam, Amicableness §5', 'wisdom'),
  ('مَنْ دارَى النَّاسَ سَلِمَ.', 'One who is amicable with people remains safe.', 'Ghurar al-Hikam, Amicableness §6', 'wisdom'),
  ('مَنْ لَمْ يُصْلِحْهُ حُسْنُ المُداراةِ أصْلَحَهُ سُوءُ المُكافاةِ.', 'One who is not improved by the virtue of amicableness becomes improved by the evil of retribution.', 'Ghurar al-Hikam, Amicableness §7', 'wisdom'),
  ('مَنْ دارَى النَّاسَ أمِنَ مَكرَهُمْ.', 'One who is amicable with the people is protected from their plotting.', 'Ghurar al-Hikam, Amicableness §8', 'wisdom'),
  ('مَنْ لَـمْ يُدارِ مَنْ فَوْقَهُ لَمْ يُدْرِكْ بِغْيَتَهُ.', 'He who is not amicable with the one who is above him will not realize his goal.', 'Ghurar al-Hikam, Amicableness §9', 'wisdom'),
  ('مُداراةُ الرِّجالِ مِنْ أفضَلِ الأعْمالِ.', 'Being amicable with people is one of the best actions', 'Ghurar al-Hikam, Amicableness §10', 'wisdom'),
  ('الدُّعاءُ لِلسّائِلِ أحَدُ الصَّدَقَتَيْنِ.', 'Supplication for a beggar is one of the two charities [that one can give].', 'Ghurar al-Hikam, Supplication And The Supplicant §1', 'wisdom'),
  ('أنْفَذُ السِّهامِ دَعْوَةُ المَظْلُومِ.', 'The most piercing arrow is the supplication of the oppressed.', 'Ghurar al-Hikam, Supplication And The Supplicant §2', 'wisdom'),
  ('أعْجَزُ النَّاسِ مَنْ عَجَزَ عَنِ الدُّعاءِ.', 'The most incapable of all people is the one who is unable to supplicate.', 'Ghurar al-Hikam, Supplication And The Supplicant §3', 'wisdom'),
  ('إنَّ كَرَمَ اللّهِ سُبْحانَهُ لا يَنْقُضُ حِكْمَتَهُ، فَلِذلِكَ لا يَقَعُ الإجابَةُ في كُلِّ دَعْوَة.', 'The kindness of Allah does not annul His wisdom; it is for this reason that not all supplications are answered.', 'Ghurar al-Hikam, Supplication And The Supplicant §4', 'wisdom'),
  ('إنَّ لِلّهِ سُبْحانَهُ سَطَوات ونَقِمات، فَإذا نَزَلَتْ بِكُمْ فَادْفَعُوها بِالدُّعاءِ، فَإنَّهُ لايَدْفَعُ البَلاءَ إلاّ الدُّعاءُ.', 'Verily Allah, the Glorified, has wraths and chastisements, so if [any of] it descends upon you, repel it with supplication; for indeed nothing can repel tribulation except supplication.', 'Ghurar al-Hikam, Supplication And The Supplicant §5', 'wisdom'),
  ('اَلدُّعاءُ سِلاحُ الأولياءِ.', 'Supplication is the weapon of the close friends [of Allah].', 'Ghurar al-Hikam, Supplication And The Supplicant §6', 'wisdom'),
  ('إذا أرادَ أحَدُكُمْ أنْ لا يَسْألَ اللّهَ سُبْحانَهُ شَيْئاً إلاّ أعْطاهُ فَلْيَيئَسْ مِنَ النَّاسِ، وَلايَكُونُ لَهُ رَجاءٌ إلاّ اللّهُ سُبْحانَهُ.', 'If any one of you wishes that he should never ask Allah, the Glorified, for anything but that He grants it to him, then he should lose hope in people and should not have hope in anyone other than Allah, the Glorified.', 'Ghurar al-Hikam, Supplication And The Supplicant §7', 'wisdom'),
  ('إذا كانَتْ لَكَ إلَى اللّهِ سُبْحانَهُ حاجَةٌ فَابْدأ بِالصَّلاةِ عَلَى النَّبيِّ صلَّى اللّه عليه وآله وسلَّم، ثُمَّ اسْألِ اللّهَ حاجَتَكَ، فإنَّ اللّهَ تعالى أكْرَمُ مِنْ أنْ يُسْألَ حاجَتَينِ فيَقْضِيَ إحديهُما وَيَمْنَعَ الأُخرى.', 'When you have any need [that you wish for] from Allah, the Glorified, then start by sending salutations on the Prophet (s) and then ask Allah for your need, for Allah, the Most High, is too generous to fulfil one of the two supplications that are made to Him and refuse the other.', 'Ghurar al-Hikam, Supplication And The Supplicant §8', 'wisdom'),
  ('بِالدُّعاءِ يُسْتَدْفَعُ البَلاءُ.', 'Through supplication, tribulations are repelled.', 'Ghurar al-Hikam, Supplication And The Supplicant §9', 'wisdom'),
  ('رُبَّما سَأَلْتَ الشَّيْءَ فَلَمْ تُعْطَهَ واُعْطيتَ خَيْراً مِنْهُ.', 'Sometimes you may ask for something but you are not granted it, rather you are given [something] better than it.', 'Ghurar al-Hikam, Supplication And The Supplicant §10', 'wisdom'),
  ('وَُقَِرَ سَمْعٌ لَمْ تَسْمَعِ الدَّاعِيَةُ.', 'Deaf is the ear that does not hear the call [of guidance].', 'Ghurar al-Hikam, The Call §1', 'wisdom'),
  ('ما اخْتَلَفَتْ دَعْوَتانِ إلاّ كانَتْ إحْديهُما ضَلالَةً.', 'Two calls never differ but that one of them leads to misguidance.', 'Ghurar al-Hikam, The Call §2', 'wisdom'),
  ('ضَلالُ الدَّليلِ هَلاكُ المُسْتَدِلِّ.', 'Deviation of the guide is the destruction of the seeker of guidance.', 'Ghurar al-Hikam, The Guide §1', 'wisdom'),
  ('كَمْ دَنِف نَجا وصَحيح هَوى.', 'How many [times has] a seriously ill person been saved while a healthy person died!', 'Ghurar al-Hikam, Seriously Ill §1', 'wisdom'),
  ('مَنْ قَرُبَ مِنَ الدَّنيَّةِ أُتُّهِمَ.', 'One who comes near the despicable is accused.', 'Ghurar al-Hikam, The Despicable §1', 'wisdom'),
  ('مُبايَنَةُ الدَّنايا تَكْبِتُ العَدُوَّ.', 'Disassociating oneself from loathsome actions and traits subdues the enemy.', 'Ghurar al-Hikam, Loathsome Actions And Traits §1', 'purpose'),
  ('الدُّنيا لا تَصْفُو لِشارِب، ولا تَفي لِصاحِب.', 'This world is neither clean for any drinker [to drink from] nor is it loyal to any owner.', 'Ghurar al-Hikam, This World §1', 'wisdom'),
  ('الدُّنيا مَلِيئَةٌ بِالمَصائِبِ طارِقَةٌ بِالفَجايِـعِ والنَّوائِبِ.', 'This world is filled with tribulations [and] stricken with tragedies and calamities.', 'Ghurar al-Hikam, This World §2', 'wisdom'),
  ('الدُّنيا مُنْتَقِلَةٌ فانِيَةٌ، إنْ بَقِيَتْ لَكَ لَمْ تَبْقَ لَها.', 'This world is fleeting and perishing; [even] if it remains for you, you will not remain for it.', 'Ghurar al-Hikam, This World §3', 'wisdom'),
  ('الدُّنيا أصْغَرُ وأحْقَرُ وأنْزَرُ مِنْ أنْ تُطاعَ فيهَا الأحْقادُ.', 'This world is smaller, more lowly and more insignificant than for one to keep grudges in [and because of] it.', 'Ghurar al-Hikam, This World §4', 'wisdom'),
  ('الدُّنيا سِجْنُ المُؤمِنِ، والمَوتُ تُحفَتُهُ، والجَنَّةُ مَأواهُ.', 'This world is a prison for the believer, death is his gift and Paradise is his [permanent] abode.', 'Ghurar al-Hikam, This World §5', 'wisdom'),
  ('الدُّنيا جَنَّةُ الكافِرِ، والمَوْتُ مُشْخِصُهُ، والنّارُ مَثْواهُ.', 'This world is a Paradise for the disbeliever, death is his dispatcher and hell is his [permanent] dwelling.', 'Ghurar al-Hikam, This World §6', 'wisdom'),
  ('الدُّنيا صَفْقَةُ مَغْبُون والإنْسانُ مَغْبُونٌ بِها.', 'This world is a deal of the [one who has been] defrauded and human being is defrauded by it.', 'Ghurar al-Hikam, This World §7', 'wisdom'),
  ('الدُّنيا إنِ انْجَلَتْ اِنْجَلَتْ، وإذا جَلَتْ اِرْتَحَلَتْ.', 'If this world unfolds, it opens up and when it disperses, it departs.', 'Ghurar al-Hikam, This World §8', 'wisdom'),
  ('الدُّنيا دُوَلٌ فَأجْمِلْ في طَلَبِها، واصْطَبِرْ حتّى تَأتيَكَ دُولَتُكَ.', 'This world takes turns, so be moderate in seeking it, and be patient until your turn comes to you.', 'Ghurar al-Hikam, This World §9', 'wisdom'),
  ('الدُّنيا عَرَضٌ حاضِرٌ،يَأكُلُ مِنْهُ البَرُّ والفاجِرُ، والآخِرَةُ دارُ حَقّ يَحْكُمُ فيها مَلِكٌ قادِرٌ.', 'This world is a present offering, [both] the virtuous and the vicious partake of it, but the Hereafter is the Abode of Truth wherein a [wise and] powerful king rules.', 'Ghurar al-Hikam, This World §10', 'wisdom'),
  ('رُبَّ دَواء جَلَبَ داءً.', 'Many a remedy brings about an ailment.', 'Ghurar al-Hikam, Remedy And Ailment §1', 'wisdom'),
  ('رُبَّ داء اِنْقَلَبَ دَواءً.', 'Many an ailment turns into a remedy.', 'Ghurar al-Hikam, Remedy And Ailment §2', 'wisdom'),
  ('رُبَّما كانَ الدَّواءُ داءً.', 'Sometimes the remedy is [itself] an ailment.', 'Ghurar al-Hikam, Remedy And Ailment §3', 'wisdom'),
  ('رُبَّما كانَ الدّاءُ شِفاءً.', 'Sometimes the ailment is [itself] a cure.', 'Ghurar al-Hikam, Remedy And Ailment §4', 'wisdom'),
  ('مَنْ كَثُرَتْ أدْواؤُهُ لَمْ يُعْرَفْ شِفاؤُهُ.', 'One whose ailments are many, his cure will not be known.', 'Ghurar al-Hikam, Remedy And Ailment §5', 'wisdom'),
  ('مَنْ لَمْ يَحْتَمِلْ مَرارَةَ الدَّواءِ دامَ ألَمُهُ.', 'One who does not bear the bitterness of the remedy, his pain persists.', 'Ghurar al-Hikam, Remedy And Ailment §6', 'wisdom'),
  ('لا دَواءَ لِمَشْغُوف (لِمشعوف) بِدائِهِ.', 'There is no remedy for the one who is fond of his ailment.', 'Ghurar al-Hikam, Remedy And Ailment §7', 'wisdom'),
  ('لاشِفاءَ لِمَن كَتَمَ طَبيبَهُ داءَهُ.', 'There is no cure for the one who hides his ailment from his doctor.', 'Ghurar al-Hikam, Remedy And Ailment §8', 'wisdom'),
  ('عَجِبْتُ لِمَنْ عَرَفَ دَواءَ دائِهِ فَلا يَطْلُبُهُ وإنْ وَجَدَهُ لَمْ يَتَداوَ بِهِ.', 'I am amazed at the one who knows the remedy of his ailment yet does not seek it, and if he finds it he does not apply it [to cure his ailment].', 'Ghurar al-Hikam, Remedy And Ailment §9', 'wisdom'),
  ('لِكُلِّ حَيّ داءٌ.', 'For every living thing there is an ailment.', 'Ghurar al-Hikam, Remedy And Ailment §10', 'wisdom'),
  ('أماراتُ الدُّوَلِ إنْشاءُ الحِيَلِ.', 'The signs of alternation of power are the creation of stratagems.', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §1', 'wisdom'),
  ('مِنْ أماراتِ الدَّوْلَةِ التَّيَقُّظُ (اليَقْظَـةُ) لِحِراسَةِ الأُمُورِ.', 'One of the signs of alternation of power is vigilance in safeguarding affairs.', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §2', 'wisdom'),
  ('مِنْ أعْوَدِ الغَنائِمِ دَوْلَةُ الأكارِمِ.', 'The sovereignty of the honourable is one of the most beneficial gains.', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §3', 'wisdom'),
  ('مِنْ دَلائِلِ الدَّوْلَةِ قِلَّةُ الغَفْلَةِ.', 'From the indicators of alternation of power is decrease of negligence.', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §4', 'wisdom'),
  ('ما حُصِّنَ الدُّوَلُ بِمِثْلِ العَدْلِ.', 'Nothing protects empires like justice.', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §5', 'wisdom'),
  ('يُسْتَدَلُّ على إدْبارِ الدُّوَلِ بِأرْبَع: تَضييعُ الأُصولِ، والتَّمَسُّكُ بِالغُرُورِ، وَ تَقْديمُ الأراذِلِ، وتأخيرُ الأفاضلِ.', 'The decline [and imminent fall] of empires is evinced by four things: neglecting the principles [and core values of justice and equity], clinging to vanities, promotion of the wicked and demotion of the virtuous.', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §6', 'wisdom'),
  ('دَوْلَةُ الأوْغادِ مَبْنِيَّةٌ علَى الجَورِ والفَسادِ.', 'The sovereignty of scoundrels is founded on oppression and corruption.', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §7', 'wisdom'),
  ('دَوْلَةُ الأكابِرِ (الاكارِم) مِنْ أفْضَلِ المَغانِمِ.', 'The sovereignty of the great (or honourable) people is one of the best of bounties.', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §8', 'wisdom'),
  ('لِكُلِّ دَوْلَة بُرْهَةٌ.', 'For every empire there is a period [after which it falls].', 'Ghurar al-Hikam, Alternation Of Power And Sovereignty §9', 'wisdom'),
  ('لا تُداهِنُوا فَيَقْتَحِمَ بِكُمْ الإدْهانُ علَى المَعصِيَةِ.', 'Do not flatter each other thereby letting flattery plunge you into sin.', 'Ghurar al-Hikam, Flattery §1', 'wisdom'),
  ('بِئسَ القِلادَةُ قِلادَةُ الدَّينِ.', 'The worst collar is the collar of debt.', 'Ghurar al-Hikam, Debt §1', 'wisdom'),
  ('كَثْرَةُ الدَّينِ تُصَيِّرُ الصّادِقَ كاذِباً، والمُنْجِزَ مُخْلِفاً.', 'Too much debt makes a truthful person a liar and an honest person dishonest.', 'Ghurar al-Hikam, Debt §2', 'wisdom'),
  ('الدَّينُ أحدُ الرِّقَيْنِ.', 'Debt is one of the two bondages.', 'Ghurar al-Hikam, Debt §3', 'wisdom'),
  ('الدَّينُ رِقٌّ، اَلقَضاءُ عِتْقٌ.', 'Debt is bondage, repayment is freedom.', 'Ghurar al-Hikam, Debt §4', 'wisdom'),
  ('الدِّينُ أشرفُ النَّسَبَيْنِ.', 'Religion is the more honourable of the two lineages.', 'Ghurar al-Hikam, Religion And Sharia Law §1', 'faith'),
  ('الدِّينُ والأدَبُ، نَتيجَةُ العَقْلِ.', 'Religion and good manners are a result of intelligence.', 'Ghurar al-Hikam, Religion And Sharia Law §2', 'faith'),
  ('أصْلُ الدِّينِ أداءُ الأمانَةِ، والوَفاءُ بِالعُهُودِ.', 'The foundation of religion is returning trusts [to their owners] and fulfilling pledges.', 'Ghurar al-Hikam, Religion And Sharia Law §3', 'faith'),
  ('اِعْلَمْ أنَّ أوَّلَ الدّينِ التَّسليمُ، وآخِرُهُ الإخلاصُ.', 'Know that the beginning of religion is submission and its end is sincere devotion.', 'Ghurar al-Hikam, Religion And Sharia Law §4', 'faith'),
  ('ألا وإنَّ شَرايِعَ الدِّينِ واحِدَةٌ، وسُبُلَهُ قاصِدَةٌ، فَمَنْ أخَذَ بِها لَحِقَ وَغَنِمَ، ومَنْ وَقَفَ عَنْها ضَلَّ ونَدِمَ.', 'Indeed the codes of religion are one and its ways are straight, so the one who follows it arrives [at the destination] and gains [success], and the one who stands away from it strays and regrets.', 'Ghurar al-Hikam, Religion And Sharia Law §5', 'faith'),
  ('أيْنَ تَذْهَبُ بِكُمُ المَذاهِبُ؟', 'Where are the different paths taking you?', 'Ghurar al-Hikam, Religion And Sharia Law §6', 'faith'),
  ('أيْنَ تَتِيْهُ بِكُمُ الغَياهِبُ، وتَخْتَدِعُكُمُ الكَواذِبُ؟', 'Where is the darkness misleading you and [how are] the falsehoods deceiving you?', 'Ghurar al-Hikam, Religion And Sharia Law §7', 'faith'),
  ('أيْنَ تَضِلُّ عُقُولُكُم، وتَزيغُ نُفُوسُكُمْ، أتَسْتَبْدِلُونَ الكِذْبَ بِالصِّدقِ، وَتَعْتاضُونَ الباطِلَ بِالحَقِّ؟', 'Where are your minds straying and your souls deviating [to]? Do you seek to substitute facts for lies and exchange truth for falsehood?', 'Ghurar al-Hikam, Religion And Sharia Law §8', 'faith'),
  ('أفْضَلُ السَّعادَةِ اِسْتِقامَةُ الدّينِ.', 'The greatest felicity is [in] the uprightness of religion.', 'Ghurar al-Hikam, Religion And Sharia Law §9', 'faith'),
  ('يَسيرُ الدّينِ خَيرٌ مِنْ كَثيرِ الدُّنيا.', 'Little religion is better than plenty of worldly possession.', 'Ghurar al-Hikam, Religion And Sharia Law §10', 'faith'),
  ('أفْضَلُ الذُّخْرِ الصَّنايِـعُ', 'The best savings are good actions.', 'Ghurar al-Hikam, The Savings §1', 'wisdom'),
  ('أفْضَلُ الذَّخائِرِ حُسْنُ الصَّنايِـعِ', 'The best of (all) savings are good actions.', 'Ghurar al-Hikam, The Savings §2', 'wisdom'),
  ('أفْضَلُ الذَّخائِرِ عِلْمٌ يُعْمَلُ بِهِ، ومَعْرُوفٌ لايُمَنُّ بِهِ.', 'The best of (all) savings is knowledge that is acted upon and good that is not followed by obligation', 'Ghurar al-Hikam, The Savings §3', 'wisdom'),
  ('الذِكْرُ أفْضَلُ الغَنِيمَتَيْنِ.', 'Remembering [Allah] is the better of the two gains.', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §1', 'faith'),
  ('اَلذِّكْرُ يُؤْنِسُ اللُبَّ، ويُنيرُ القَلْبَ، ويَسْتَنْزِلُ الرَّحمَةَ.', 'Remembering [Allah] comforts the soul, illuminates the heart and brings down the mercy [of Allah].', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §2', 'faith'),
  ('اَلذِّكْرُ نُورُ العَقْلِ، وحَياةُ النُّفُوسِ، وجَلاءُ الصُّدُورِ.', 'Remembering [Allah] is the light of intellect, the life of the souls and the polishing of the hearts.', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §3', 'faith'),
  ('اَلجُلوُسُ فِي المَسْجِدِ مِنْ بَعْدِ طُلُوعِ الفَجْرِ إلى حينِ طُلُوعِ الشَّمْسِ لِلاِشتِغالِ بِذِكْرِ اللّهِ سُبْحانَهُ أسْرَعُ في تَيْسيرِ الرِّزقِ مِنَ الضَّرْبِ في أقْطارِ الأرْضِ.', 'Sitting in the masjid from after dawn up to sunrise in order to remember [and praise] Allah, the Glorified, is quicker in making sustenance [more easily] obtainable than travelling to different parts of the land [in order to earn one’s livelihood].', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §4', 'faith'),
  ('اَلذِّكْرُ الجَميلُ أحَدُ الحَياتَيْنِ.', 'A beautiful remembrance is one of the two lives.', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §5', 'faith'),
  ('اَلذِّكْرُ الجَميلُ أحَدُ العُمْرَينِ.', 'A beautiful remembrance is one of the two lifetimes.', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §6', 'faith'),
  ('اَلذِّكرُ لَيْسَ مِنْ مَراسِمِ اللِّسانِ، ولا مِنْ مَناسِمِ الفِكْرِ، ولكِنَّهُ أوَّلٌ مِنَ المَذكُورِ، وَثان مِنَ الذّاكِرِ.', 'Remembering [Allah] is not from rituals of the tongue nor is it from the passing of thoughts rather it is first from the remembered and then from the rememberer.', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §7', 'faith'),
  ('اِشْحَنِ الخَلْوَةَ بِالذِّكْرِ، واصْحَبِ النِّعَمَ بِالشُّكْرِ.', 'Fill your solitude with the remembrance [of Allah] and accompany blessings with gratitude.', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §8', 'faith'),
  ('أفيضُوا في ذِكْرِ اللّهِ، فَإنَّهُ أحْسَنُ الذِّكْرِ.', 'Be abundant in your remembrance of Allah, for it is the best remembrance.', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §9', 'faith'),
  ('اِسْتَديمُوا الذِّكْرَ، فَإنَّهُ يُنيرُ القَلْبَ، وهُوَ أفْضَلُ العِبادَةِ.', 'Be constant in your remembrance [of Allah] for it illuminates the heart and is surely the best [form of] worship.', 'Ghurar al-Hikam, Remembrance [Of Allah] And The Reminder §10', 'faith'),
  ('الذُّنوبُ الدّاءُ، والدَّواءُ الاِسْتِغفارُ،وَ الشِّفاءُ أنْ لا تَعُودَ.', 'Vices are a disease, and its remedy is seeking forgiveness, and its cure is not repeating [the vices].', 'Ghurar al-Hikam, Vices And Those Who Commit Them §1', 'character'),
  ('تَهْوينُ الذَّنبِ أعْظَمُ مِنْ رُكُوبِ الذَّنْبِ.', 'Taking a sin lightly is worse than committing the sin.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §2', 'character'),
  ('تَرْكُ الذَّنْبِ شَديدٌ، وأشَدُّ مِنْهُ تَرْكُ الجَنَّةِ.', 'Giving up sin is difficult, but giving up Paradise is [going to be] more difficult.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §3', 'character'),
  ('تَأتينا أشْياءُ نَسْتَكْثِرُها إذا جَمَعْناها، وَنَسْتَقِلُّها إذا قَسَمْناها.', 'Things come to us that seem to be much when we amass them but which we consider to be less when we divide them.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §4', 'character'),
  ('اِحْذَرُوا الذُّنُوبَ المُورِطَةَ، والعُيُوبَ المُسْخِطَةَ.', 'Be careful of the sins that lead you to deep trouble the vices that bring the wrath of Allah.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §5', 'character'),
  ('إيّاكَ وانْتِهاكَ المَحارِمِ، فَإنَّها شيمَةُ الفُسّاقِ وأُولِي الفُجُورِ، والغَوايَةِ.', 'Refrain from desecration of the sacred, for indeed this is the practice of the wicked and the people of depravity and vice.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §6', 'character'),
  ('إيّاكَ والإصْرارَ، فَإنَّهُ مِنْ أكْبَرِ الكَبائِرِ وأعَظَمِ الجَرائِمِ.', 'Refrain from persistence [in committing vices] for it is surely the gravest of great sins and the worst of offences.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §7', 'character'),
  ('إيّاكَ والمُجاهَرَةَ بِالفُجُورِ، فَإنَّها مِنْ أشَدِّ المَ آثِمِ.', 'Refrain from exposing [your] sins, for this is one of the worst of offences.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §8', 'character'),
  ('إيّاكَ والمعصِيَةَ، فَإنَّ اللَئيمَ (الشَّقيَّ) مَنْ باعَ جَنَّـةَ المَأوى بِمَعْصِيَة دَنِيَّة مِنْ مَعاصِي الدُّنيا.', 'Refrain from vices, for the one who sells the eternal Paradise for a vile sin from the sins of this world is indeed wretched.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §9', 'character'),
  ('إيّاكَ أنْ تَسْتَسْهِلَ رُكُوبَ المَعاصي، فَإنَّها تَـكْسُوكَ فِي الدُّنيا ذِلَّةً، وتَـكْسِبُكَ فِي الآخِرَةِ سَخَطَ اللّهِ.', 'Do not take the committing of vices lightly, for verily it will cover you with humiliation in this world and earn you the wrath of Allah in the Hereafter.', 'Ghurar al-Hikam, Vices And Those Who Commit Them §10', 'character'),
  ('الإذاعَةُ خِيانَةٌ.', 'Divulgence [of secrets] is [and act of] disloyalty', 'Ghurar al-Hikam, Divulgence [Of Secrets] §1', 'wisdom'),
  ('اَلإذاعَةُ شيمَةُ الأغْيارِ.', 'Divulgence [of secrets] is the practice of the others [and not of the believers].', 'Ghurar al-Hikam, Divulgence [Of Secrets] §2', 'wisdom'),
  ('نِعْمَ المَرْءُ الرَّؤُفُ (المعرُوفُ).', 'What an excellent person the compassionate one is!', 'Ghurar al-Hikam, The Compassionate §1', 'wisdom'),
  ('اُقْصُرْ رَأيَكَ على ما يَلْزَمُكَ تَسْلَمْ، وَدَعِ الخَوضَ فيما لايَعنيكَ تَكْرُمْ.', 'Restrict your opinion to that which is necessary and you will be safe; avoid entering into that which does not concern you and you will be honoured.', 'Ghurar al-Hikam, The Compassionate §1', 'wisdom'),
  ('اِمْخِضُوا الرَّأيَ مَخْضَ السِّقاءِ، يُنْتِجْ سَديدَ الآراءِ.', 'Churn the opinion [like] the churning of a water-skin, and the outcome will be the most pertinent of opinions.', 'Ghurar al-Hikam, The Compassionate §2', 'wisdom'),
  ('أقْرَبُ الآراءِ مِنَ النُّهى أبْعَدُها مِنَ الهَوى.', 'The closest of opinions to reason will be the furthest of them from vain desire.', 'Ghurar al-Hikam, The Compassionate §3', 'wisdom'),
  ('أمْلَكُ النَّاسِ لِسِدادِ الرَّأيِ كُلُّ مُجَرِّب.', 'The ones who possess most pertinent opinions are those who have experience.', 'Ghurar al-Hikam, The Compassionate §4', 'wisdom'),
  ('أفْضَلُ النَّاسِ رَأياً مَنْ لا يَسْتَغْني عَنْ رَأيِ مُشير.', 'The person with the best opinion is he who does not consider himself needless of the counsel of an advisor.', 'Ghurar al-Hikam, The Compassionate §5', 'wisdom'),
  ('أفْضَلُ الرَّأيِ ما لَمْ يُفِتِ الفُرَصَ، ولَم يُورِثِ الغُصَصَ.', 'The best opinion is one which neither causes opportunities to be wasted nor brings about distress.', 'Ghurar al-Hikam, The Compassionate §6', 'wisdom'),
  ('إنَّ رَأيَكَ لا يَتَّسِعُ لِكُلِّ شَيْء، فَفَرِّغْهُ لِلْمُهِمِّ.', 'Indeed your opinion cannot encompass everything, so leave it for the important [issues].', 'Ghurar al-Hikam, The Compassionate §7', 'wisdom'),
  ('اَلرَّأيُ بِتَحصينِ الأسرارِ.', 'The [right] opinion is [acquired] by protecting secrets.', 'Ghurar al-Hikam, The Compassionate §8', 'wisdom'),
  ('بِإصابَة (بِأصالةِ) الرَّأيِ يَقْوَى الحَزْمُ.', 'Through correct opinion (or prudence), ones judiciousness is strengthened.', 'Ghurar al-Hikam, The Compassionate §9', 'wisdom'),
  ('المُرائي ظاهِرُهُ جَميلٌ، وَباطِنُهُ عَلِيلٌ.', 'The outside of the one who shows off is beautiful but his inside is sickly.', 'Ghurar al-Hikam, Showing Off §1', 'wisdom'),
  ('اِعْمَلُوا في غَيْرِ رِياء ولا سُمْعَة، فَإنَّهُ مَنْ يَعْمَلْ لِغَيرِ اللّهِ يَكِلْهُ اللّهُ سُبْحانَهُ إلى مَنْ عَمِلَ لَهُ.', 'Work without seeking to show off or for the sake of renown, for indeed the one who works for other than Allah is left by Allah to the one whom he worked for.', 'Ghurar al-Hikam, Showing Off §2', 'wisdom'),
  ('اَلرِّياءُ إشْراكٌ.', 'Showing off is [a form of] ascribing partners [to Allah].', 'Ghurar al-Hikam, Showing Off §3', 'wisdom'),
  ('آفَةُ العِبادَةِ الرِّياءُ.', 'The bane of worship is showing off.', 'Ghurar al-Hikam, Showing Off §4', 'wisdom'),
  ('يَسيرُ الرِّياءِ شِرْكٌ.', 'The smallest amount of showing off is polytheism.', 'Ghurar al-Hikam, Showing Off §5', 'wisdom'),
  ('لِسانُ المُرائي جَميلٌ، وفي قَلْبِهِ الدَّاءُ الدَّخيلُ.', 'The words of the one who shows off are beautiful, but in his heart there is an internal disease.', 'Ghurar al-Hikam, Showing Off §6', 'wisdom'),
  ('رُبَّ رَباح (أرباح تَؤُلُ) يَؤُلُ إلى خُسْران.', 'Many a profit turns back into loss.', 'Ghurar al-Hikam, Profit And Gain §1', 'wisdom'),
  ('الرّابِحُ مَنْ باعَ الدُّنيا بِالآخِرَةِ، واسْتَبْدَلَ بِالآجِلَةِ عَنِ العاجِلَةِ.', 'The gainer is one who has sold this world for the Hereafter and has exchanged the transient for the eternal.', 'Ghurar al-Hikam, Profit And Gain §2', 'wisdom'),
  ('اِجْعَلُوا كُلَّ رَجائِكُمْ لِلّهِ سُبْحانَهُ، ولا تَرْجُوا أحَداً سِواهُ فَإنَّهُ ما رَجا أحدٌ غَيْرَ اللّهِ تعالى إلاّ خابَ.', 'Keep all your hope for Allah, the Glorified, and do not have hope [in] anyone other than Him, for indeed no one has hoped in other than Allah, the Exalted, but that he has been disappointed.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §1', 'mercy'),
  ('أعْظَمُ البَلاءِ اِنْقِطاعُ الرَّجاءِ.', 'The greatest affliction is the severance of hope.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §2', 'mercy'),
  ('الرَّجاءُ لِرَحْمَةِ اللّهِ أنْجَحُ.', 'Hope in the mercy of Allah brings more success.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §3', 'mercy'),
  ('إنَّكُمْ إنْ رَجَوْتُمْ اللّهَ بَلَغْتُمْ آمالَكُمْ، وإنْ رَجَوْتُمْ غَيرَ اللّهِ خابَتْ أمانيُّكم وآمالُكُمْ.', 'Verily, if you have hope in Allah you will attain your hopes, but if you have hope in other than Allah then your hopes and aspirations will be frustrated.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §4', 'mercy'),
  ('رُبَّ رَجاء يُؤَدّي إلى حِرْمان.', 'Many a hope leads to deprivation.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §5', 'mercy'),
  ('رُبَّ رَجاء خائِب لأِْمَل كاذِب.', 'Many a frustrated hope is brought about by a false aspiration.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §6', 'mercy'),
  ('كُنْ لِما لاتَرْجُو أقْرَبُ مِنْكَ لِما تَرْجُو.', 'Be closer to that which you do not hope for than [you are to] that which you hope for.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §7', 'mercy'),
  ('لِكُلِّ غَيْبَة إيابٌ.', 'For every absence, there is a return.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §8', 'mercy'),
  ('لَرُبَّما قَرُبَ البَعيدُ وبَعُدَ القَريبُ.', 'At times the distant may come close and the close may become distant.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §9', 'mercy'),
  ('مَنْ رَجاكَ فَلا تُخَيِّبْ أمَلَهُ.', 'When one has hope in you, [then] do not disappoint his hope.', 'Ghurar al-Hikam, Hope In [The Mercy Of] Allah And [In] Others §10', 'mercy'),
  ('بِبَذْلِ الرَّحْمَةِ تُسْتَنْزَلُ الرَّحْمَةُ.', 'By showing compassion, [divine] mercy descends.', 'Ghurar al-Hikam, Mercy And Compassion §1', 'mercy'),
  ('رَحْمَةُ الضُّعَفاءِ تَسْتَنْزِلُ الرَّحْمَةَ.', 'Being compassionate to the weak brings down [divine] mercy.', 'Ghurar al-Hikam, Mercy And Compassion §2', 'mercy'),
  ('رَحْمَةُ مَنْ لا يَرْحَمُ تَمْنَعُ الرَّحْمَةَ، واسْتِبْقاءُ مَنْ لا يُبْقي يُهْلِكُ الاُمَّةَ.', 'Showing compassion to one who does not show compassion [to others] prevents [divine] mercy, and sparing one who does not spare others destroys the nation.', 'Ghurar al-Hikam, Mercy And Compassion §3', 'mercy'),
  ('عَجِبْتُ لِمَنْ يَرْجُو رَحْمَةَ مَنْ فَوْقَهُ كَيْفَ لايَرحَمُ مَنْ دُونَهُ.', 'I am amazed at the one who hopes for the mercy of one who is above him, how can he not show compassion to the one who is below him?!', 'Ghurar al-Hikam, Mercy And Compassion §4', 'mercy'),
  ('أشْعِر قَلْبَكَ الرَّحْمَةَ لِجَميعِ النَّاسِ والإحْسانَ إلَيْهِمْ تُنِلْهُمْ حَيْفاً وَلاتَكُنْ عَلَيْهِمْ سَيْفاً.', 'Make your heart feel compassion for all people and [show] kindness towards them, [and] do not oppress them or terrorize them.', 'Ghurar al-Hikam, Mercy And Compassion §5', 'mercy'),
  ('أَولَى النَّاسِ بِالرَّحْمَةِ المُحْتاجِ إلَيْها.', 'The most deserving of [showing] mercy among the people is the one who is most in need of it [himself].', 'Ghurar al-Hikam, Mercy And Compassion §6', 'mercy'),
  ('أبْلَغُ ما تَسْتَدِرُّ بِهِ الرَّحمَةُ أنْ تُضْمَرَ لِجَميعِ النَّاسِ الرَّحْمَةُ.', 'The best thing that draws forth mercy is having compassion for all people [in your heart].', 'Ghurar al-Hikam, Mercy And Compassion §7', 'mercy'),
  ('إذا عَجَزَ عَنِ الضُّعَفاءِ نَيْلُكَ فَلْتَسَعْهُمْ رَحْمَتُكَ.', 'When you are incapable of helping the weak [and needy] then let your compassion encompass them.', 'Ghurar al-Hikam, Mercy And Compassion §8', 'mercy'),
  ('كما تَرْحَمُ تُرْحَمُ.', 'Just as you show mercy, mercy will be shown to you.', 'Ghurar al-Hikam, Mercy And Compassion §9', 'mercy'),
  ('مَنْ لَمْ يَرْحَمْ لَمْ يُرْحَمْ.', 'One who shows no mercy will be shown no mercy.', 'Ghurar al-Hikam, Mercy And Compassion §10', 'mercy'),
  ('بِصِلَةِ الرَّحِمِ تَسْتَدِرُّ النِّعَمُ.', 'By keeping ties with near relatives, blessings flow forth [abundantly].', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §1', 'family'),
  ('بِقَطيعَةِ الرَّحِمِ تُسْتَجْلَبُ النِّقَمُ.', 'By cutting off ties with near relatives, [divine] retributions are brought down.', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §2', 'family'),
  ('بِرُّ الرَّجُلِ ذَوي رَحِمِهِ صَدَقَةٌ.', 'The kindness of a person towards his near relatives is a [form of] charity.', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §3', 'family'),
  ('حِراسَةُ النِّعَمِ في صِلَةِ الرَّحِمِ.', 'The protection of blessings is in keeping ties with near relatives.', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §4', 'family'),
  ('حُلُولُ النِّقَمِ في قَطيعَةِ الرَّحِمِ.', 'The descending of [divine] retributions is in cutting off ties with near relatives.', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §5', 'family'),
  ('رُبَّ قَريب أبْعدُ مِنْ بَعيد.', 'Many a near relative is farther away than one who is distant [or unrelated].', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §6', 'family'),
  ('رُبَّ مُواصَلَة خَيْرٌ مِنْها القَطيعَةُ.', 'Many ties are better to cut off than to keep.', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §7', 'family'),
  ('رُبَّ مُواصَلَة أدَّتْ إلى تَثْقيل.', 'Sometimes [certain] ties may result in heavy burdens [and obligations].', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §8', 'family'),
  ('صِلَةُ الرَّحِمِ تُدِرُّ النِّعَمَ وتَدْفَعُ النِّقَمَ.', 'Keeping ties with near relatives makes blessings flow forth and repels calamities.', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §9', 'family'),
  ('صِلَةُ الرَّحِمِ مِنْ أحسَنِ الشِّيَمِ.', 'Keeping ties with near relatives is one of the best practices.', 'Ghurar al-Hikam, Near Relatives And Keeping Or Cutting Off Ties With Them §10', 'family'),
  ('عِنْدَ تَضائُقِ حِلَقِ البَلاءِ يَكُونُ الرَّخاءُ.', 'When the circle of affliction tightens, ease follows.', 'Ghurar al-Hikam, Ease §1', 'wisdom'),
  ('فِي الرَّخاءِ تَكُونُ فَضيلَةُ الشُّكْرِ.', 'The excellence of gratitude is in times of ease.', 'Ghurar al-Hikam, Ease §2', 'wisdom'),
  ('مَنْ لَمْ تَرْتَدِعْ يَجْهَلْ.', 'One who does not restrain himself [from evils and excesses] is ignorant.', 'Ghurar al-Hikam, Restraint §1', 'wisdom'),
  ('بِتَجَنُّبِ الرَّذائِلِ تَنْجُو مِنَ العابِ.', 'By keeping away from depravities, you are saved from disgrace.', 'Ghurar al-Hikam, Depravities §1', 'wisdom'),
  ('لاتَغْنَ بِالرَّذائِلِ فَتَسْقُطَ قيمَتُكَ.', 'Do not make yourself needless through depravities such that your value is dropped.', 'Ghurar al-Hikam, Depravities §2', 'wisdom'),
  ('لايُفْلِحُ مَنْ يَتَبَجَّجُ بِالرَّذائِلِ.', 'He who delights in depravities will never succeed.', 'Ghurar al-Hikam, Depravities §3', 'wisdom'),
  ('كَفى بِالمَرْءِ رَذيلَةً أنْ يُعْجِبَ بِنَفْسهِ.', 'It is sufficient of a depravity for one to be pleased [and impressed] with himself.', 'Ghurar al-Hikam, Depravities §4', 'wisdom'),
  ('اَلاِنحِطاطُ إلَى الرَّذائِلِ سَهْلٌ مُرْد.', 'Decline into depravities easily destroys.', 'Ghurar al-Hikam, Depravities §5', 'wisdom'),
  ('اِسْتَنْزِلُوا الرِّزقَ بِالصَّدَقَةِ.', 'Make sustenance come down by [giving] charity.', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §1', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ أبى أنْ يَجْعَلَ أرزاقَ عِبادِهِ المُؤْمِنينَ إلاّ مِنْ حَيثُ لايَحتَسِبُونَ.', 'Verily Allah, the Glorified, dislikes to put the sustenance of his believing servants except [in places] from where they least expect it.', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §2', 'wisdom'),
  ('تَنْزِلُ مِنَ اللّهِ المَعُونَةُ عَلى قَدْرِ المَؤُنَةِ.', 'Assistance comes down from Allah to the extent of the provisions [that are required for sustenance].', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §3', 'wisdom'),
  ('رِزْقُكَ يَطْلُبُكَ، فَأرِحْ نَفْسَكَ مِنْ طَلَبِهِ.', 'Your sustenance is seeking you, so spare yourself the trouble of seeking it.', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §4', 'wisdom'),
  ('رَضِـيَ بِالحِْرمانِ طالِبُ الرِّزقِ مِنَ اللِّئامِ.', 'He who seeks sustenance from the wicked has accepted deprivation.', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §5', 'wisdom'),
  ('رِزْقُ كُلُّ امْرِء مُقَدَّرٌ كَتَقْديرِ أجَلِهِ.', 'The sustenance of every person is preordained just as the end of his life is predetermined.', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §6', 'wisdom'),
  ('رِزقُ المَرْءِ على قَدْرِ نِيَّتِهِ.', 'The sustenance of a person is proportionate to his intention.', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §7', 'wisdom'),
  ('سَوْفَ يَأتيكَ ما قُدِرَ لَكَ، فَخَفِّضْ فِي المُكْتَسَبِ.', 'That which has been decreed for you will come to you, so take it easy in your earning.', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §8', 'wisdom'),
  ('كُلُّكُمْ عِيالُ اللّهِ واللّهُ سُبْحانَهُ كافِلُ عِيالِهِ.', 'All of you are the dependants of Allah, and Allah, the Glorified, takes care of His dependants.', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §9', 'wisdom'),
  ('لِكُلِّ رِزق سَبَبٌ، فَأَجْمِلُوا فِي الطَّلَبِ.', 'For every sustenance there is a means, so be moderate in your seeking [it].', 'Ghurar al-Hikam, Sustenance And One Who Seeks It §10', 'wisdom'),
  ('مَنْ أقَلَّ الاِسْتِرسالَ سَلِمَ.', 'One who confides less in others is safe.', 'Ghurar al-Hikam, Confiding In Others §1', 'wisdom'),
  ('مَنْ أكْثَرَ الاِسْتِرسالَ نَدِمَ.', 'One who confides a lot in others regrets.', 'Ghurar al-Hikam, Confiding In Others §2', 'wisdom'),
  ('قِلَّةُ الاِسْتِرسالِ إلَى النَّاسِ أحْزَمُ.', 'Confiding less in people [and not telling them your secrets] is more judicious.', 'Ghurar al-Hikam, Confiding In Others §3', 'wisdom'),
  ('بِعَقلِ الرَّسولِ وأدَبِهِ يُسْتَدَلُّ على عَقْلِ المُرْسِلِ.', 'By the intelligence of the messenger and his etiquette, the intelligence of the sender [of the message] is gauged.', 'Ghurar al-Hikam, The Messenger And His Message §1', 'wisdom'),
  ('رَسُولُ الرَّجُلِ تَرْجُمانُ عَقْلِهِ، وكِتابُهُ أبْلَغُ مِنْ نُطْقِهِ.', 'A person’s messenger is the interpreter of his reason, and his written message is more conveying than his speech.', 'Ghurar al-Hikam, The Messenger And His Message §2', 'wisdom'),
  ('رَسُولُكَ تَرْجُمانُ عَقْلِكَ، واحْتِمالُكَ دَليلُ حِلْمِكَ.', 'You messenger is the interpreter of your intellect, and your tolerance is an indication of your forbearance.', 'Ghurar al-Hikam, The Messenger And His Message §3', 'wisdom'),
  ('رَسُولُكَ ميزانُ نُبْلِكَ، وقَلَمُكَ أبْلَغُ مَنْ يَنْطِقُ عَنْكَ.', 'Your messenger is the gauge of your nobility, and your pen is the most eloquent thing that speaks on your behalf.', 'Ghurar al-Hikam, The Messenger And His Message §4', 'wisdom'),
  ('لَقَدْ أخْطَاءَ العاقِلُ اللاَّهي الرُّشْدَ، وأصابَهُ ذُوالاِجْتِهادِ والجِدِّ.', 'Indeed the intelligent one who is heedless strays from the path of right guidance and the one who strives with seriousness [to find it] gets it.', 'Ghurar al-Hikam, Rectitude And Right Guidance §1', 'wisdom'),
  ('لَنْ تَعْرِفُوا الرُّشْدَ حتّى تَعْرِفُوا الَّذي تَرَكَهُ.', 'You will never know rectitude until you know the one who has abandoned it.', 'Ghurar al-Hikam, Rectitude And Right Guidance §2', 'wisdom'),
  ('مَنِ اسْتَرشَدَ عَلِمَ.', 'One who seeks right guidance becomes knowledgeable [about it].', 'Ghurar al-Hikam, Rectitude And Right Guidance §3', 'wisdom'),
  ('مَنِ اسْتَرشَدَ غَوِيّاً ضَلَّ.', 'One who seeks right guidance from the deviated, goes astray.', 'Ghurar al-Hikam, Rectitude And Right Guidance §4', 'wisdom'),
  ('مَنْ خالفَ رُشْدَهُ تَبِـعَ هَواهُ.', 'One who opposes his reason follows his desires.', 'Ghurar al-Hikam, Rectitude And Right Guidance §5', 'wisdom'),
  ('أفْضَلُ السُّبُلِ الرُّشْدُ.', 'The best of paths is [the path of] right guidance.', 'Ghurar al-Hikam, Rectitude And Right Guidance §6', 'wisdom'),
  ('قدْ أصابَ المُسْترْشِدُ.', 'It is possible for the seeker of right guidance to attain it.', 'Ghurar al-Hikam, Rectitude And Right Guidance §7', 'wisdom'),
  ('مَنْ أصْدَقَكَ في نَفْسِكَ فَقَدْ أرْشدَكَ.', 'One who is truthful to you about yourself has indeed guided you aright.', 'Ghurar al-Hikam, Rectitude And Right Guidance §8', 'wisdom'),
  ('لاضَلالَ مَعَ إرشاد.', 'There is no going astray with right guidance.', 'Ghurar al-Hikam, Rectitude And Right Guidance §9', 'wisdom'),
  ('مَنْ وُفِّقَ لِرَشادِهِ تَزَوَّدَ لِمَعادِهِ.', 'One who is successful in his [attaining] rectitude acquires provisions for his Hereafter.', 'Ghurar al-Hikam, Rectitude And Right Guidance §10', 'wisdom'),
  ('مَنْ رَضِيَ بِالقَضاءِ اِسْتَراحَ.', 'One who is pleased with the decree [of Allah] is at ease.', 'Ghurar al-Hikam, Being Pleased And Satisfied §1', 'wisdom'),
  ('أجدَرُ الأشياءِ بِصِدقِ الإيمانِ اَلرِّضا والتَّسْليمُ.', 'The thing which is most befitting of true faith is being satisfied [with what has been decrees] and total submission [to Allah].', 'Ghurar al-Hikam, Being Pleased And Satisfied §2', 'wisdom'),
  ('الرِّضا غَناءٌ والسُّخْطُ عَناءٌ.', 'Satisfaction is abundance while disappointment is agony.', 'Ghurar al-Hikam, Being Pleased And Satisfied §3', 'wisdom'),
  ('اَلرِّضا يَنْفي الحَزَنَ.', 'Satisfaction dispels sadness.', 'Ghurar al-Hikam, Being Pleased And Satisfied §4', 'wisdom'),
  ('اَلرِّضا ثَمَرَةُ اليَقينِ.', 'Satisfaction [with the decree of Allah] is the fruit of certitude.', 'Ghurar al-Hikam, Being Pleased And Satisfied §5', 'wisdom'),
  ('اَلرِّضا بِقَضاءِ اللّهِ يُهَوِّنُ عَظيمَ الرَّزايا.', 'Satisfaction with the decree of Allah makes great calamities easy [to bear].', 'Ghurar al-Hikam, Being Pleased And Satisfied §6', 'wisdom'),
  ('إنْ عَقَدْتَ أيْمانَكَ فَارْضَ بِالمَقْضِيِّ عَلَيكَ ولَكَ ولا تَرْجُ أحَداً إلاَّ اللّهَ سُبْحانَهُ، وانْتَظِرْ ما أتاكَ بِهِ القَدَرُ.', 'If you have made a covenant [to believe in Allah] then be satisfied with that which has been decreed against you and for you, and do not have hope in anyone other than Allah, the Glorified, and await that which is brought to you by [divine] decree.', 'Ghurar al-Hikam, Being Pleased And Satisfied §7', 'wisdom'),
  ('إنَّكُمْ إنْ رَضيتُمْ بِالقَضاءِ طابَتْ عَيْشَتُكُمْ وفُزْتُمْ بِالغَناءِ.', 'Indeed if you are pleased with the decree [of Allah], your lives will become enjoyable and you will attain prosperity.', 'Ghurar al-Hikam, Being Pleased And Satisfied §8', 'wisdom'),
  ('إذا لَمْ يَكُنْ ما تُريدُ، فلا تُبَلْ كَيفَ كُنْتَ.', 'When what you want does not happen, then do not fret about how you were [and be satisfied with the decree of Allah].', 'Ghurar al-Hikam, Being Pleased And Satisfied §9', 'wisdom'),
  ('بِالرِّضا بِقَضاءِ اللّهِ يُسْتَدَلُّ على حُسْنِ اليَقينِ.', 'By satisfaction with the decree of Allah, the strength of [one’s] certitude is evinced.', 'Ghurar al-Hikam, Being Pleased And Satisfied §10', 'wisdom'),
  ('اَلرَّغْبَةُ مِفْتاحُ النَّصَبِ.', 'Desire is the key to difficulty [and hardship].', 'Ghurar al-Hikam, Desire And Longing §1', 'wisdom'),
  ('ثَمَرةُ الرَّغْبَةِ التَّعَبُ.', 'The fruit of desire is hardship.', 'Ghurar al-Hikam, Desire And Longing §2', 'wisdom'),
  ('رَغْبَتُكَ في زاهِد فيكَ ذُلٌّ.', 'Your longing for the one who has no interest in you is a humiliation.', 'Ghurar al-Hikam, Desire And Longing §3', 'wisdom'),
  ('مَنْ رَغِبَ فيكَ عِندَ إقْبالِكَ زَهِدَ فيكَ عِنْدَ إدْبارِكَ.', 'One who desires your company when you advance [in rank] wishes to keep away from you when you fall.', 'Ghurar al-Hikam, Desire And Longing §4', 'wisdom'),
  ('مَنْ رَغِبَ في حَياتِكَ فَقَدْ تَعَلَّقَ بِحِبالِكَ.', 'One who desires that you remain alive has clutched on to your cord.', 'Ghurar al-Hikam, Desire And Longing §5', 'wisdom'),
  ('مَنْ رَغِبَ فيما عِنْدَ اللّهِ كَثُرَ سُجُودُهُ ورُكُوعُهُ.', 'One who desires that which is with Allah, his prostrations and bowings increase.', 'Ghurar al-Hikam, Desire And Longing §6', 'wisdom'),
  ('مَنْ رَغِبَ فيما عِندَ اللّهِ أخْلَصَ عَمَلَهُ.', 'One who desires that which is with Allah makes his actions sincere.', 'Ghurar al-Hikam, Desire And Longing §7', 'wisdom'),
  ('مَنْ رَغِبَ فيما عِندَاللّهِ بَلَغَ آمالَهُ.', 'One who desires that which is with Allah attains his hopes.', 'Ghurar al-Hikam, Desire And Longing §8', 'wisdom'),
  ('إنَّكُمْ إنْ رَغِبْتُمْ إلَى اللّهِ غَنِمْتُمْ ونَجَوْتُمْ وإنْ رَغِبْتُمْ إلَى الدُّنيا خَسِرْتُمْ وهَلَكْتُمْ.', 'Indeed if you desire [closeness to] Allah, you will become prosperous and will be saved, whereas if you desire the [attainment of this] world, you will be at a loss and will be destroyed.', 'Ghurar al-Hikam, Desire And Longing §9', 'wisdom'),
  ('اَلرِّفْقُ مِفْتاحُ الصَّوابِ، وشيمَةُ ذَوي الألباب.', 'Leniency is the key to rightness and the trait of the people of understanding.', 'Ghurar al-Hikam, Leniency And Gentleness §1', 'wisdom'),
  ('اَلرِّفْقُ يُيَسِّرُ الصِّعابَ، ويُسَهِّلُ شَديدَ الأسبابِ.', 'Leniency makes difficulties bearable and eases the harshness of situations.', 'Ghurar al-Hikam, Leniency And Gentleness §2', 'wisdom'),
  ('اَلرِّفْقُ لِقاحُ الصَّلاحِ، وعُنْوانُ النَّجاحِ.', 'Leniency is the infusion of goodness and the symbol of success.', 'Ghurar al-Hikam, Leniency And Gentleness §3', 'wisdom'),
  ('اُرْفُقْ تُوَفَّقْ.', 'Be lenient and you shall gain success.', 'Ghurar al-Hikam, Leniency And Gentleness §4', 'wisdom'),
  ('أفْضَلُ شَيْء الرِّفْقُ.', 'The best thing is gentleness.', 'Ghurar al-Hikam, Leniency And Gentleness §5', 'wisdom'),
  ('أكبَرُ البِرِّ الرِّفْقُ.', 'The greatest [form of] piety is gentleness.', 'Ghurar al-Hikam, Leniency And Gentleness §6', 'wisdom'),
  ('الرِّفْقُ مِفْتاحُ النَّجاحِ.', 'Leniency is the key to success.', 'Ghurar al-Hikam, Leniency And Gentleness §7', 'wisdom'),
  ('الرِّفْقُ مِفتاحُ الصَّوابِ.', 'Leniency is the key to rightness.', 'Ghurar al-Hikam, Leniency And Gentleness §8', 'wisdom'),
  ('الرِّفْقُ يَفُلُّ حَدَّ المُخالَفَةِ.', 'Gentleness blunts the edge of opposition.', 'Ghurar al-Hikam, Leniency And Gentleness §9', 'wisdom'),
  ('الرِّفْقُ عُنْوانُ النُّبْلِ.', 'Leniency is the symbol of nobility.', 'Ghurar al-Hikam, Leniency And Gentleness §10', 'wisdom'),
  ('رَحِمَ اللّهُ عَبْداً راقَبَ ذَنْبَهُ، وخافَ رَبَّهُ.', 'May Allah have mercy on the servant who scrutinizes his sins and fears his Lord.', 'Ghurar al-Hikam, Self-Scrutiny §1', 'wisdom'),
  ('المَرْكَبُ الهَنيءُ أحَدُ الراحَتَينْ.', 'A comfortable mode of transport is one of the two comforts.', 'Ghurar al-Hikam, Mode Of Transport §1', 'wisdom'),
  ('فَالأرْواحُ مُرْتَهَنَةٌ بِثِقْلِ أعْبائِها، مُوْقِنَةٌ بِغَيْبِ أنْبائِها، لا تُسْتَزادُ مِنْ صالِحِ عَمَلِها، ولا تُسْتَعْتَبُ مِنْ سَيِّءِ زَلَلِها.', '[In the Hereafter] the souls are held at ransom by the weight of their sins and have become certain of their unseen fates. Neither can good acts be added [to their record] nor are they given warning about their evil deeds [rather, the harsh punishment of hell awaits them].', 'Ghurar al-Hikam, The Souls §1', 'wisdom'),
  ('الرَّاحَةُ فِي الزُّهدِ.', 'Peace of mind is in abstinence from worldly pleasures.', 'Ghurar al-Hikam, Peace Of Mind §1', 'wisdom'),
  ('ما أقْرَبَ الرَّاحَةَ مِنَ التَّعَبِ.', 'How close is peace of mind to hardship [and discomfort]!', 'Ghurar al-Hikam, Peace Of Mind §2', 'wisdom'),
  ('قَدْ يُدْرَكُ المُرادُ.', 'Sometimes the intended objective may be acquired.', 'Ghurar al-Hikam, The Intended Objective §1', 'wisdom'),
  ('لِقاحُ الرِّياضَةِ دِراسَةُ الحِكْمَةِ وغَلَبَةُ العادَةِ.', 'That which infuses discipline is the study of wisdom and overcoming [bad] habits.', 'Ghurar al-Hikam, Discipline §1', 'wisdom'),
  ('لا تَنْجَعُ الرِّياضَةُ إلاّ في نَفْس يَقِظَة (يقِظة وهِمَّة).', 'Discipline is not beneficial except in a woken soul.', 'Ghurar al-Hikam, Discipline §2', 'wisdom'),
  ('لا ازْدِجارَ لِمَنْ لا إقْلاعَ لهُ.', 'He who has no desistance has no restraint.', 'Ghurar al-Hikam, Restraint §1', 'wisdom'),
  ('حَصِّنُوا أمْوالَكُمْ بِالزَّكاةِ.', 'Fortify [and protect] your wealth by [giving] charity.', 'Ghurar al-Hikam, Charity §1', 'generosity'),
  ('والزَّكاةَ تَسَبُّباً (تَسْبيباً) للرِّزقِ.', 'And charity [was prescribed as] a means of sustenance.', 'Ghurar al-Hikam, Charity §2', 'generosity'),
  ('مَنْ أدّى زَكوةَ مالِهِ وُقِيَ شُحَّ نَفْسهِ.', 'One who pays his zakāt is protected from the greediness of his soul.', 'Ghurar al-Hikam, Charity §3', 'generosity'),
  ('مَنْ أبْصَرَ زَلَّتَهُ صَغُرَتْ عِندَهُ زَلَّةُ غَيْرِهِ.', 'Whoever looks at his own lapses, the faults of others seem trivial to him.', 'Ghurar al-Hikam, Lapses §1', 'wisdom'),
  ('مَنْ عَمِىَ عَنْ زَلَّتِهِ اِسْتَعْظَمَ زَلَّةَ غَيْرِهِ.', 'Whoever is blind to his own lapses, the errors of others seem great to him.', 'Ghurar al-Hikam, Lapses §2', 'wisdom'),
  ('الزَّلَلُ مَنْدَمَةٌ.', 'Lapses are a cause of regret.', 'Ghurar al-Hikam, Lapses §3', 'wisdom'),
  ('زَلَّةُ المُتَوَقّي أشَدُّ زَلَّة، وعِلَّةُ اللَُّؤْمِ أقْبَحُ عِلَّة.', 'The lapse of one who is [evidently] pious is the worst of lapses and the sickness of ignobility is the most repulsive of sicknesses.', 'Ghurar al-Hikam, Lapses §4', 'wisdom'),
  ('زَلَّةُ القَدَمِ أهْوَنُ اسْتِدْراك.', 'The slip of the foot is the easiest to recover from [unlike other lapses].', 'Ghurar al-Hikam, Lapses §5', 'wisdom'),
  ('أبْغَضُ الخَلائِقِ إلَى اللّهِ الشَّيخُ الزَّانِي.', 'The most despised of creatures in the sight of Allah is the old adulterer.', 'Ghurar al-Hikam, Adultery §1', 'wisdom'),
  ('وتَرْكَ الزِّنا تَحْصيناً لِلأنْسابِ وتَرْكَ اللِّواطِ تَكْثيراً للنَّسْلِ.', 'The abandoning of adultery is [prescribed] for safeguarding the descendants and the renouncing of homosexuality is a means of increasing the progeny.', 'Ghurar al-Hikam, Adultery §2', 'wisdom'),
  ('ما زَنى غَيُورٌ قَطُّ.', 'A dignified person would never commit adultery.', 'Ghurar al-Hikam, Adultery §3', 'wisdom'),
  ('ما زَنى عَفيفٌ.', 'A chaste person does not commit adultery.', 'Ghurar al-Hikam, Adultery §4', 'wisdom'),
  ('الزَّوجَةُ الصَّالِحَةُ أحَدُ الكَسْبَيْنِ.', 'A righteous wife is one of the two [lofty] acquisitions.', 'Ghurar al-Hikam, The Wife §1', 'wisdom'),
  ('الزَّوجَةُ المُوافِقَةُ إحدَى الرَّاحَتَينِ.', 'An agreeable wife is one of the two comforts.', 'Ghurar al-Hikam, The Wife §2', 'wisdom'),
  ('شَرُّ الزَّوْجاتِ مَنْ لا تُواتي(لا تُواني).', 'The worst of wives is the one who does not comply [with her husband’s wishes].', 'Ghurar al-Hikam, The Wife §3', 'wisdom'),
  ('مَوْتُ الزَّوجَةِ حُزْنُ ساعَة.', 'The death of one’s wife is the sadness of the hour.', 'Ghurar al-Hikam, The Wife §4', 'wisdom'),
  ('ألا وقَدْ اُمِرْتُمْ بِالظَّعْنِ، ودُلِلْتُمْ عَلَى الزَّادِ، فَتَزَوَّدُوا مِنَ الدُّنيا ما تَحُوزونَ (تَحْرُزُونَ) بِِهِ أنْفُسَكُمْ غَداً.', 'Indeed, you have been commanded to decamp and have been shown your provision [for the journey], so take from this world the provisions that you can hold on to (or that will protect you) tomorrow.', 'Ghurar al-Hikam, Provision §1', 'wisdom'),
  ('إنَّ مِنَ الفَسادِ إضاعَةَ الزَّادِ.', 'Verily the wasting of provisions is from corruption.', 'Ghurar al-Hikam, Provision §2', 'wisdom'),
  ('تَزَوَّدُوا مِنْ أيّامِ الفَناءِ لِلبَقاءِ، فَقَدْ دُلِلْتُمْ علَى الزَّادِ، واُمِرْتُمْ بِالظَّعْنِ، وَحُثِثْتُمْ عَلَى المَسيرِ.', 'Take provisions from the days of transience for the everlasting [abode], for you have been shown your provision and commanded to decamp and [have been] driven upon the course.', 'Ghurar al-Hikam, Provision §3', 'wisdom'),
  ('تَزَوَّدُوا مِنَ الدُّنيا ما تَحْرُزُونَ (تَحُوزُونَ) بِهِ أنْفُسَكُمْ غَداً، وخُذُوا مِنَ الفَناءِ للبَقاءِ.', 'Take from this world the provisions that you can hold on to (or that will protect you) tomorrow and take from the transient for the everlasting.', 'Ghurar al-Hikam, Provision §4', 'wisdom'),
  ('زادُ المَرْءِ إلَى الآخرَةِ الوَرَعُ، والتُّقى.', 'The provision of a person for the Hereafter is piety and God-wariness.', 'Ghurar al-Hikam, Provision §5', 'wisdom'),
  ('عَلَيْكَ بِحُسْنِ التَأهُّبِ والاِسْتِعْدادِ، والاِستِكْثارِ مِنَ الزَّادِ.', 'You must be well prepared and ready, and increase in your provision [for the Hereafter].', 'Ghurar al-Hikam, Provision §6', 'wisdom'),
  ('عَجِبْتُ لِمَنْ عَرَفَ أنَّهُ مُنْتَقِلٌ عَنْ دُنياهُ كَيْفَ لايُحسِنُ التَّزَوُّدَ لأُخراهُ.', 'I am amazed at the one who knows that he will surely be moving away from his world, how can he not acquire a goodly provision for his Hereafter?!', 'Ghurar al-Hikam, Provision §7', 'wisdom'),
  ('كُلُّ امْرِء عَلى ما قَدَّمَ قادِمٌ وبِما عَمِلَ مَجْزِيٌّ.', 'Every person is approaching that which he has sent forward and will be recompensed for his actions.', 'Ghurar al-Hikam, Provision §8', 'wisdom'),
  ('كَما تُقَدِّمُ تَجِدُ.', 'As you send forth, so you shall find [waiting for you in the Hereafter].', 'Ghurar al-Hikam, Provision §9', 'wisdom'),
  ('كَما تَزْرَعُ تَحْصُدُ.', 'As you sow, so shall you reap.', 'Ghurar al-Hikam, Provision §10', 'wisdom'),
  ('إغْبابُ الزِّيارَةِ أمانٌ مِنَ المَلالَةِ.', 'Visiting [one’s brothers in faith] on a regular basis is protection from lethargy.', 'Ghurar al-Hikam, Visiting §1', 'wisdom'),
  ('زُرْ فِي اللّهِ أهْلَ طاعَتِهِ، وخُذِ الهِدايَةَ مِنْ أهْلِ وِلايَتِهِ.', 'Visit those who are obedient to Allah for His sake and take guidance from those who have been vested with His authority.', 'Ghurar al-Hikam, Visiting §2', 'wisdom'),
  ('زُورُوا فِي اللّهِ، وجالِسُوا فِي اللّهِ، واعْطُوا فِي اللّهِ، وامْنَعُوا فِي اللّهِ.', 'Visit each other for the sake of Allah, sit [and mingle] with each other for the sake of Allah, give for the sake of Allah and withhold for the sake of Allah.', 'Ghurar al-Hikam, Visiting §3', 'wisdom'),
  ('مَنْ كَثُرَتْ زِيارَتُهُ قَلَّتْ بَشاشَتُهُ.', 'One whose visits increase, his cheerfulness decreases.', 'Ghurar al-Hikam, Visiting §4', 'wisdom'),
  ('الزِّينَةُ بِحُسْنِ الصَّوابِ، لابِحُسْنِ الثيابِ.', 'Adornment is in righteous probity, not in elegant clothing.', 'Ghurar al-Hikam, Adornment §1', 'wisdom'),
  ('السُّؤالُ يُضْعِفُ لِسانَ المُتَكَلِّمِ، ويَكْسِرُ قَلْبَ الشُّجاعِ البَطَلِ، وَيُوقِفُ الحُرَّ العَزيْزِ مَوْقِفَ العَبْدِ الذَّليلِ، ويُذْهِبُ بَهاءَ الوَجْهِ، ويَمْحَقُ الرِّزْقَ.', 'Begging weakens the tongue of the speaker, breaks the heart of the courageous hero, puts the free honourable one in the position of a humbled slave, takes away the radiance of one’s face and wipes out one’s sustenance.', 'Ghurar al-Hikam, Begging And Asking People §1', 'wisdom'),
  ('المَسْئَلَةُ طَوْقُ المَذَلَّةِ، تَسْلُبُ العَزيزَ عِزَّهُ، والحَسيبَ حَسَبَهُ.', 'Begging is the collar of humiliation, it takes the honour away from the honourable and the stature away from the noble.', 'Ghurar al-Hikam, Begging And Asking People §2', 'wisdom'),
  ('الذُّلُّ في مَسْئَلَةِ النَّاسِ.', 'Humiliation [and disgrace] is in asking from people.', 'Ghurar al-Hikam, Begging And Asking People §3', 'wisdom'),
  ('المَسْئَلَةُ مِفْتاحُ الفَقْرِ.', 'Begging is the key to poverty.', 'Ghurar al-Hikam, Begging And Asking People §4', 'wisdom'),
  ('آفَةُ الطَّلَبِ عَدَمُ النَّجاحِ.', 'The bane of asking [others] is lack of success [in getting what one asks for].', 'Ghurar al-Hikam, Begging And Asking People §5', 'wisdom'),
  ('إذا أرَدْتَ أنْ تُطاعَ فَاسْأَلْ ما يُسْتَطاعُ.', 'If you want to be obeyed [or your request to be granted] then ask for that which is feasible.', 'Ghurar al-Hikam, Begging And Asking People §6', 'wisdom'),
  ('لِيَكُنْ مَسْألَتُكَ ما يَبْقى لَكَ جَمالُهُ ويُنْفى عَنْكَ وَبالُهُ.', 'Let your request be for a thing, the charm of which will last for you long after the negative consequences [of your asking] have ended.', 'Ghurar al-Hikam, Begging And Asking People §7', 'wisdom'),
  ('مَنْ أحْسَنَ المَسْألَةَ أُسْعِفَ.', 'One who asks properly is aided.', 'Ghurar al-Hikam, Begging And Asking People §8', 'wisdom'),
  ('مَنْ سَألَ غَيْرَ اللّهِ اِسْتَحَقَ الحِرْمانَ.', 'Whoever asks [from] other than Allah deserves to be deprived.', 'Ghurar al-Hikam, Begging And Asking People §9', 'wisdom'),
  ('مَنْ أكْثَرَ مَسْئَلَةَ النَّاسِ ذَلَّ.', 'One who increases his requests from people is humiliated.', 'Ghurar al-Hikam, Begging And Asking People §10', 'wisdom'),
  ('أجمِلُوا فِي الخِطابِ تَسْمَعُوا جَميلَ الجَوابِ.', 'Make your address polite and you will hear a polite reply.', 'Ghurar al-Hikam, Question And Answer §1', 'wisdom'),
  ('مَنْ أسْرَعَ فِي الجَوابِ لَمْ يُدْرِكِ الصَّوابَ.', 'One who hastens to reply does not arrive at the right [answer].', 'Ghurar al-Hikam, Question And Answer §2', 'wisdom'),
  ('مِنْ بُرهانِ الفَضْلِ صائِبُ الجَوابِ.', 'Giving correct reply is an evidence of merit.', 'Ghurar al-Hikam, Question And Answer §3', 'wisdom'),
  ('نَكيرُ الجَوابِ مِنْ نَكيرِ الخِطابِ.', 'A discourteous reply stems from a discourteous address.', 'Ghurar al-Hikam, Question And Answer §4', 'wisdom'),
  ('لا يَسْتَحْيِيَنَّ أحَدٌ إذا سُئِلَ عَمّا لا يَعْلَمُ أنْ يَقُولَ: لا أعْلَمُ.', 'When one is asked about that which he knows not, he should never feel ashamed to say: I do not know.', 'Ghurar al-Hikam, Question And Answer §5', 'wisdom'),
  ('لا تُسىِ اللَّفْظَ وإنْ ضاقَ عَلَيْكَ الجَوابُ.', 'Do not use harsh words [or foul language] even if you are unable to reply.', 'Ghurar al-Hikam, Question And Answer §6', 'wisdom'),
  ('لا تَسْئَلُنَّ عَمّا لَمْ يَكُنْ فَفِي الَّذي قَدكانَ عِلْمٌ كاف.', 'Never ask about that which has not [yet] happened, for in that which has already come about there is enough knowledge [that one can gain].', 'Ghurar al-Hikam, Question And Answer §7', 'wisdom'),
  ('لا تُسِئِِ الخِطابَ فَيَسُوءَكَ نَكيرُ الجَوابِ.', 'Do not be offensive in your address thereby being offended by the rudeness of the reply.', 'Ghurar al-Hikam, Question And Answer §8', 'wisdom'),
  ('مَنْ تَرَكَ قَوْلَ «لا أدري» أُصيبَ مَقاتِلُهُ.', 'One who abandons the words “I don’t know” comes upon his [place of] destruction.', 'Ghurar al-Hikam, Question And Answer §9', 'wisdom'),
  ('أحْضَرُ النّاسِ جَواباً مَنْ لَمْ يَغْضَبْ.', 'The person most prepared to [give a] reply is one who does not get angry.', 'Ghurar al-Hikam, Question And Answer §10', 'wisdom'),
  ('السَّبَبُ الَّذي أدْرَكَ بِهِ العاجِرُ بُغْيَتَهُ، هُوَ الَّذي أعْجَزَ القَّادِرَ عَنْ طَلِبَتِهِ.', 'The means by which an incapable person achieves his goal is the same one (means) that makes the powerful person incapable to achieving what he seeks.', 'Ghurar al-Hikam, Causes And Means §1', 'wisdom'),
  ('أوْثَقُ سَبَب أخَذَتْ بِهِ سَبَبٌ بَيْنَكَ وبَيْنَ اللّهِ.', 'The firmest rope that you can hold on to is the rope between you and Allah.', 'Ghurar al-Hikam, Causes And Means §2', 'wisdom'),
  ('لِكُلِّ شَيْء سَبَبٌ.', 'For everything there is a cause.', 'Ghurar al-Hikam, Causes And Means §3', 'wisdom'),
  ('أقْوَى الوَسائِلِ حُسْنُ الفَضائِلِ.', 'The strongest means [of gaining success in this world and the next] is having excellent [qualities and] merits.', 'Ghurar al-Hikam, Causes And Means §4', 'wisdom'),
  ('أفْضَلُ سَبَب كَفُّ الغَضَبِ، والتَّنَزُّهُ عَنْ مَذَلَّةِ الطَّلَبِ.', 'The best means [to achieve closeness to Allah] is refraining from anger and keeping away from the humiliation of asking [others].', 'Ghurar al-Hikam, Causes And Means §5', 'wisdom'),
  ('إنْ كُنْتُمْ لامُحالَةَ مُتَسابِقينَ فَتَسابَقُوا إلى إقامَةِ حُدوُدِ اللّهِ، والأمْرِ بِالمَعْرُوفِ.', 'If you must be competitors, then compete with each other in establishing the ordinances of Allah and in enjoining good.', 'Ghurar al-Hikam, Competition §1', 'wisdom'),
  ('اَلسُّجُودُ الجِسْماني: هُوَ وَضْعُ عَتائِقِ الوُجُوهِ عَلَى التُّرابِ، واسْتِقْبالُ الأرْضِ بِالراحَتَينِ والكَفَّيْنِ (وَالرُّكْبَتَيْنِ)، وأطْرافِ القَدَمَيْنِ مَعَ خُشُوعِ القَلْبِ وإخْلاصِ النّيَّةِ.', 'The physical prostration is putting the foreheads on the earth and placing the palms and knees on the ground along with the toes of the feet, with complete submissiveness of the heart and sincerity of intention.', 'Ghurar al-Hikam, Prostration And Bowing §1', 'wisdom'),
  ('وَالسُّجُودُ النَّفْساني: فَراغُ القَلْبِ مِنَ الفانياتِ، والإقْبالُ بِكُنْهِ الهِمَّةِ عَلَى الباقياتِ، وخَلْعُ الكِبْرِ والحَمِيَّةِ، وقَطْعُ العَلائِقِ الدُّنْيَويَّةِ، والتَّحَلّي بِالخَلائِقِ النَبَويَّةِ.', 'The spiritual [aspect of] prostration is emptying the heart of [love for] that which perishes, proceeding with firm resolution in endeavouring towards the everlasting, removing pride and fanaticism, cutting off worldly ties and adorning oneself with the etiquettes of the Prophet.', 'Ghurar al-Hikam, Prostration And Bowing §2', 'wisdom'),
  ('نِعْمَ العِبادَةُ السُّجُودُ والرُّكُوعُ.', 'What good forms of worship Prostration ( sujūd ) and bowing ( rukū’ ) are.', 'Ghurar al-Hikam, Prostration And Bowing §3', 'wisdom'),
  ('السِّجْنُ أحَدُ القَبْرَيْنِ.', 'The prison is one of the two [types of] graves.', 'Ghurar al-Hikam, Prison §1', 'wisdom'),
  ('مَنْ كَثُرَ سَخَطُهُ لَمْ يُعْرَفْ رِضاهُ.', 'One whose displeasure is much, his pleasure is not known.', 'Ghurar al-Hikam, Displeasure §1', 'wisdom'),
  ('مَنْ كَثُرَ سَخَطُهُ لَمْ يُعْتَبْ.', 'One whose displeasure is much is not admonished.', 'Ghurar al-Hikam, Displeasure §2', 'wisdom'),
  ('ما أقْبَحَ السُّخْطَ وأحْسَنَ الرِّضى.', 'How ugly is displeasure and how nice pleasure is!', 'Ghurar al-Hikam, Displeasure §3', 'wisdom'),
  ('كَفى بِالسَّخَطِ عَناءً.', 'Displeasure is enough of a suffering.', 'Ghurar al-Hikam, Displeasure §4', 'wisdom'),
  ('مَنْ تَسَخَّطَ بِالمَقْدُورِ حَلَّ بِهِ المَحْذُورُ.', 'Whoever is displeased with what has been destined, adversity befalls him.', 'Ghurar al-Hikam, Displeasure §5', 'wisdom'),
  ('لا تَكْرَهُوا سُخْطَ مَنْ يُرْضيهِ الباطِلُ.', 'Do not be upset by the displeasure of the one who is pleased with falsehood.', 'Ghurar al-Hikam, Displeasure §6', 'wisdom'),
  ('تَوَقَّ سَخَطَ مَنْ لايُنْجيكَ إلاَّ طاعَتُهُ، ولايُرْديكَ إلاّ مَعْصِيَتُهُ، وَلايَسَعُكَ إلاّ رَحْمَتُهُ، والْتَجِئْ إلَيْهِ، وتَوَكَّلْ عَلَيْهِ.', 'Be wary of the displeasure of the One aside from whose obedience nothing can save you, and aside from whose disobedience nothing can destroy you, and aside from whose mercy nothing can accommodate you; and turn to Him and trust in Him.Be wary of the displeasure of the One aside from whose obedience nothing can save you, and aside from whose disobedience nothing can destroy you, and aside from whose mercy nothing can accommodate you; and turn to Him and trust in Him.', 'Ghurar al-Hikam, Displeasure §7', 'wisdom'),
  ('السَّخاءُ يَكْسِبُ المَحَبَّةَ، ويَزينُ الأخْلاقَ.', 'Generosity earns love [of people] and adorns one’s character.', 'Ghurar al-Hikam, Generosity §1', 'generosity'),
  ('السَّخاءُ أحَدُ السَّعادَتَيْنِ.', 'Generosity is one of the two felicities.', 'Ghurar al-Hikam, Generosity §2', 'generosity'),
  ('السَّخاءُ يُمَحِصُّ الذُّنُوبَ، ويَجْلِبُ مَحَبَّةَ القُلُوبِ.', 'Generosity clears away sins and attracts the love of the hearts.', 'Ghurar al-Hikam, Generosity §3', 'generosity'),
  ('السَّخاءُ، والشَجاعَةُ، غَرائِزُ شَريفَةٌ، يَضَعُهَا اللّهُ سُبْحانَهُ فيمَنْ أحَبَّهُ، وامْتَحَنَهُ.', 'Generosity and courage are honourable instincts which Allah, the Glorified, puts in the one whom He loves and has subjected to trials.', 'Ghurar al-Hikam, Generosity §4', 'generosity'),
  ('السَّخاءُ أنْ تَكُونَ بِمالِكَ مُتَبَرِّعاً وعَنْ مالِ غَيرِكَ مُتَوَرِّعاً.', 'Generosity means being open-handed with your [own] wealth while being cautious with the wealth of others.', 'Ghurar al-Hikam, Generosity §5', 'generosity'),
  ('السَّخاءُ ما كانَ ابْتِداءً فَإنْ كانَ عَنْ مَسْئَلَة فَحَياءٌ وتَذَمُّمٌ.', 'Generosity is that which one gives [himself], for if he gives after being asked, then it is [a result of] shame and embarrassment.', 'Ghurar al-Hikam, Generosity §6', 'generosity'),
  ('السَّخاءُ ثَمَرَةُ العَقْلِ، والقَناعَةُ بُرْهانُ النُّبْلِ.', 'Generosity is the fruit of the intellect and contentment is the evidence of nobility.', 'Ghurar al-Hikam, Generosity §7', 'generosity'),
  ('السَّخاءُ والحَياءُ أفْضَلُ الخُلْقِ.', 'Generosity and shame are the best characteristics.', 'Ghurar al-Hikam, Generosity §8', 'generosity'),
  ('أشْجَعُ النَّاسِ أسْخاهُمْ.', 'The most courageous of people is the most generous of them.', 'Ghurar al-Hikam, Generosity §9', 'generosity'),
  ('أكْرَمُ الأخْلاقِ السَّخاءُ، وأعَمُّها نَفْعاً العَدْلُ.', 'The most honourable of qualities is generosity, and the most universal in benefit is justice.', 'Ghurar al-Hikam, Generosity §10', 'generosity'),
  ('مَنْ عَمِلَ بِالسَّدادِ مَلَكَ.', 'One who acts aptly, acquires [success].', 'Ghurar al-Hikam, Aptness §1', 'wisdom'),
  ('مَنْ سَعى في طَلَبِ السَّرابِ طالَ تَعَبُهُ، وكَثُرَ عَطَشُهُ.', 'One who strives in seeking a mirage, his hardship is prolonged and his thirst increases.', 'Ghurar al-Hikam, Mirage §1', 'wisdom'),
  ('مَنْ أمَّلَ الرِّيَّ مِنَ السَّرابِ، خابَ أمَلُهُ وماتَ بِعَطَشِهِ.', 'One who hopes to quench his thirst from a mirage, his hope will be dashed and he will die of thirst.', 'Ghurar al-Hikam, Mirage §2', 'wisdom'),
  ('مَنْ غَرَّهُ السَّرابُ تَقَطَّعَتْ بِهِ الأسْبابُ.', 'One who is deceived by the mirage [of this world], the means [of attaining prosperity in the Hereafter] are cut off for him.', 'Ghurar al-Hikam, Mirage §3', 'wisdom'),
  ('حُسْنُ السَّراحِ أحَدُ الرّاحَتَيْنِ.', 'Dismissal with kindness is one of the two reliefs.', 'Ghurar al-Hikam, Dismissal §1', 'wisdom'),
  ('صَلاحُ السَّرائِرِ بُرْهانُ صِحَّةِ البَصائِرِ.', 'The goodness of inward thoughts is evidence of the soundness of insight.', 'Ghurar al-Hikam, Inward Thoughts And Feelings §1', 'wisdom'),
  ('طُوبى لِمَنْ صَلُحَتْ سَريرَتُهُ، وحَسُنَتْ عَلانِيَتُهُ، وعَـزَلَ عَنِ النَّاسِ شَرَّهُ.', 'Blessed is the one whose inward thoughts are good, whose outward [character] is righteous and who does not harm the people.', 'Ghurar al-Hikam, Inward Thoughts And Feelings §2', 'wisdom'),
  ('عِنْدَ تَصْحيحِ الضَّمائِرِ يَبْدُو غِلُّ السَّرائِرِ.', 'When the consciences are being reformed, the hidden rancour becomes evident.', 'Ghurar al-Hikam, Inward Thoughts And Feelings §3', 'wisdom'),
  ('عِِنْدَ فَسادِ العَلانِيَةِ تَفْسُدُ السَّريرَةُ.', 'When the outward gets corrupted, the inward also get corrupted.', 'Ghurar al-Hikam, Inward Thoughts And Feelings §4', 'wisdom'),
  ('مَنْ حَسُنَتْ سَريرَتُهُ حَسُنَتْ عَلانِيَتُهُ.', 'One whose inward [feeling] is good, his outward [character] is righteous.', 'Ghurar al-Hikam, Inward Thoughts And Feelings §5', 'wisdom'),
  ('مَنْ حَسُنَتْ سَريرَتُهُ لَمْ يَخَفْ أحَداً.', 'One whose inward [feeling] is good [and honourable] is not afraid of anyone.', 'Ghurar al-Hikam, Inward Thoughts And Feelings §6', 'wisdom'),
  ('اِحْفَظْ أمْرَكَ، ولا تُنْكِحْ خاطِباً سِرَّكَ.', 'Protect your affair and do not give away your secret in marriage to whoever proposes!', 'Ghurar al-Hikam, Secret And Confidential Discussions §1', 'wisdom'),
  ('اِنْفَرِدْ بِسِرِّكَ، وَلا تُودِعْهُ حازِماً فَيَزِلَّ، ولاجاهِلاً فَيَخُونَ.', 'Keep your secret to yourself and neither entrust it to a judicious one who may err nor to an ignorant one who may betray [your trust].', 'Ghurar al-Hikam, Secret And Confidential Discussions §2', 'wisdom'),
  ('أفْضَلُ النَّجْوى، ماكانَ علَى الدّينِ والتُّقى، وأسْفَرَ عَنِ اتِّباعِ الهُدى، ومُخالَفَةِ الهَوى.', 'The best secret discussion is that which is founded on religion and God-wariness, and is based on following the path of guidance and opposing vain desires.', 'Ghurar al-Hikam, Secret And Confidential Discussions §3', 'wisdom'),
  ('اَلمَرْءُ أحْفَظُ لِسِـرِّهِ.', 'Man is more protective of his secret.', 'Ghurar al-Hikam, Secret And Confidential Discussions §4', 'wisdom'),
  ('إذاعَةُ سِرّ أُودِعْتَهُ غَدْرٌ.', 'Divulging the secret that has been entrusted to you is a [form of] betrayal.', 'Ghurar al-Hikam, Secret And Confidential Discussions §6', 'wisdom'),
  ('ثَلاثٌ لا يُسْتَوْدَعْنَ سِرّاً: المَرْأةُ، والنَّمّامُ،وَ الأحمَقُ.', 'Three people are not to be trusted with a secret: the woman, the telltale and the fool.', 'Ghurar al-Hikam, Secret And Confidential Discussions §7', 'wisdom'),
  ('سِرُّكَ سُرُورُكَ إنْ كَتَمْتَهُ وإنْ أذَعْتَهُ كانَ ثُبُوركَ.', 'Your secret is a source of happiness for you if you conceal it but if you divulge it, it is your destruction.', 'Ghurar al-Hikam, Secret And Confidential Discussions §8', 'wisdom'),
  ('لا يَسْلَمُ مَنْ أذاعَ سِرَّهُ.', 'He who divulges his secrets does not remain safe.', 'Ghurar al-Hikam, Secret And Confidential Discussions §9', 'wisdom'),
  ('سِرُّكَ أسيرُكَ فَإنْ أفْشَيْتَهُ صِرْتَ أسيرَهُ.', 'Your secret is your prisoner but if you divulge it, you become its prisoner.', 'Ghurar al-Hikam, Secret And Confidential Discussions §10', 'wisdom'),
  ('اَلسُّرُورُ يَبْسُطُ النَّفْسَ ويُثيرُ النِّشاطَ.', 'Happiness opens up the spirit and stimulates vitality.', 'Ghurar al-Hikam, Happiness And Putting Joy In The Hearts §1', 'wisdom'),
  ('رُبَّما تَنَغَّصَ السُّرُورُ.', 'At times happiness becomes roiled.', 'Ghurar al-Hikam, Happiness And Putting Joy In The Hearts §2', 'wisdom'),
  ('قَدْ يَتَنَغَّصُ السُّرُورُ.', 'Perhaps [the joy of] happiness may turn bitter.', 'Ghurar al-Hikam, Happiness And Putting Joy In The Hearts §3', 'wisdom'),
  ('كُلُّ سُرُور مُتَنَغِّصٌ.', 'Every joy [in this world] turns sour [eventually].', 'Ghurar al-Hikam, Happiness And Putting Joy In The Hearts §4', 'wisdom'),
  ('ما أوْدَعَ أحَدٌ (ما مِنْ أحَد أوْدَعَ) قَلْباً سُرُوراً إلاّ خَلَقَ اللّهُ مِنْ ذلِكَ السُّرُورِ لُطْفاً، فَإذا نَزَلَتْ بِهِ نائِبَةٌ جَرى إلَيْها كَالماءِ فِي انْحِدارِهِ حَتّى يَطْرُدَها عَنْهُ كَما تَطْرُدُ الغَريبَةُ مِنَ الإبِلِ.', 'No one puts joy in a [believer’s] heart except that Allah creates a grace from that joy, so whenever any calamity befalls him, it (the grace) flows over it just like the flowing of water until it expels the calamity from him just as the unfamiliar camel is expelled from the group of camels.', 'Ghurar al-Hikam, Happiness And Putting Joy In The Hearts §5', 'wisdom'),
  ('اَلإسْرافُ مَذْمُومٌ في كُلِّ شَيْء إلاّ في أفْعالِ الخَيْرِ.', 'Extravagance is blameworthy in everything except in doing good deeds.', 'Ghurar al-Hikam, Extravagance §1', 'wisdom'),
  ('ألا وإنَّ إعْطاءَ هذا المالِ في غَيرِ حَقِّهِ تَبْذيرٌ وإسْرافٌ.', 'Verily giving this wealth where it has no right to be given is wastefulness and extravagance.', 'Ghurar al-Hikam, Extravagance §2', 'wisdom'),
  ('أقْبَحُ البَذْلِ السَّـرَفُ.', 'The ugliest [form of] giving is extravagance.', 'Ghurar al-Hikam, Extravagance §3', 'wisdom'),
  ('إنَّ مَنْعَ المُقْتَصِدِ أحْسَنُ مِنْ عَطاءِ المُبَذِّرِ.', 'The refusal of the economizer is better than the granting of the extravagant.', 'Ghurar al-Hikam, Extravagance §4', 'wisdom'),
  ('إنَّ إمْساكَ الحافِظِ أجْمَلُ مِنْ بَذلِ المُضَيِّعِ.', 'Verily the withholding of preserver is more graceful than the giving of the squanderer.', 'Ghurar al-Hikam, Extravagance §5', 'wisdom'),
  ('اَلإسْرافُ يُفْنِى الجَزيلَ.', 'Extravagance wipes out the plentiful.', 'Ghurar al-Hikam, Extravagance §6', 'wisdom'),
  ('اَلإسْرافُ يُفْنِي الكَثيرَ.', 'Extravagance depletes the abundant.', 'Ghurar al-Hikam, Extravagance §7', 'wisdom'),
  ('اَلتَّبْذيرُ عُنْوانُ الفاقَةِ.', 'Wastefulness is the symbol [and cause] of poverty.', 'Ghurar al-Hikam, Extravagance §8', 'wisdom'),
  ('اَلتَّبْذيرُ قَرينٌ مُفْلِسٌ.', 'Wastefulness is a penniless companion.', 'Ghurar al-Hikam, Extravagance §9', 'wisdom'),
  ('ذَرِ الإسْرافَ مُقْتَصِداً، واذْكُرْ فِي اليَوْمِ غَداً.', 'Abandon extravagance by economizing, and recall [your] tomorrow today.', 'Ghurar al-Hikam, Extravagance §10', 'wisdom'),
  ('ومُجانَبَةَ السِّرْقَةِ، إيجاباً لِلْعِفَّةِ.', 'And the shunning of theft [has been prescribed] as a means of instilling virtue.', 'Ghurar al-Hikam, Theft §1', 'wisdom'),
  ('ساعِدْ أخاكَ عَلى كُلِّ حال، وزُلْ مَعَهُ حَيْثُما زالَ.', 'Aid your brother in every situation, and go with him wherever he goes.', 'Ghurar al-Hikam, Aid §1', 'wisdom'),
  ('السَّعادةُ ما أفْضَتْ إلَى الفَوْزِ.', 'Felicity is that which leads [one] to success.', 'Ghurar al-Hikam, Felicity §1', 'wisdom'),
  ('أماراتُ السَّعادَةِ إخْلاصُ العَمَلِ.', 'The signs of felicity are sincerity [of intentions] in action.', 'Ghurar al-Hikam, Felicity §2', 'wisdom'),
  ('خُلُوُّ الصَّدْرِ مِنَ الغِلِّ وَالحَسَدِ مِنْ سَعادَةِ العَبْدِ.', 'Having a heart that is free of rancour and jealousy is from the felicity of a servant.', 'Ghurar al-Hikam, Felicity §3', 'wisdom'),
  ('دَرَكُ السَّعادَةِ بِمُبادَرَةِ الخَيْراتِ والأعْمالِ الزّاكياتِ.', 'Felicity is gained by hastening good deeds and pure [and virtuous] actions.', 'Ghurar al-Hikam, Felicity §4', 'wisdom'),
  ('سَعادَةُ المَرْءِ اَلقَناعَةُ واَلرِّضا.', 'The felicity of a person is [in] contentment and satisfaction.', 'Ghurar al-Hikam, Felicity §5', 'wisdom'),
  ('سَعادَةُ الرَّجُلِ في إحْرازِ دينِهِ والعَمَلِ لآخِرَتِهِ.', 'The felicity of a man is in safeguarding his faith and working for his Hereafter.', 'Ghurar al-Hikam, Felicity §6', 'wisdom'),
  ('كَفى بِالمَرْءِ سَعادَةً أنْ يُوثَقَ بِهِ في أُمُورِ الدّينِ والدُّنيا.', 'It is enough of a felicity for a person that he be deemed trustworthy in religious and worldly affairs.', 'Ghurar al-Hikam, Felicity §7', 'wisdom'),
  ('كَفى بِالمَرْءِ سَعادَةً أنْ يَعْزِفَ عَمّا يَفْنى، ويَتَوَلَّهَ بِما يَبْقى.', 'It is enough of a felicity for a person to turn away from that which perishes and become occupied with that which is everlasting.', 'Ghurar al-Hikam, Felicity §8', 'wisdom'),
  ('لَنْ تُعْرَفَ حَلاوَةُ السَّعادَةِ حتّى تُذاقَ مَرارَةُ النَّحْسِ.', 'You will never know the sweetness of felicity until you taste the bitterness of misfortune.', 'Ghurar al-Hikam, Felicity §9', 'wisdom'),
  ('مِنَ السَّعادَةِ التَّوفيقُ لِصالِحِ الأعْمالِ.', 'It is part of felicity to be granted success in performing righteous deeds.', 'Ghurar al-Hikam, Felicity §10', 'wisdom'),
  ('السَعِيدُ مَنِ اسْتَهانَ بِالمَفْقُودِ.', 'The felicitous is one who considers that which is lost [to him] as insignificant.', 'Ghurar al-Hikam, The Felicitous §1', 'wisdom'),
  ('اَلسَّعيدُ مَنْ خافَ العِقابَ فَامَنَ، ورَجَا الثَّوابَ فَأحْسَنَ.', 'Felicitous is one who fears the punishment [of Allah] so he has faith, and hopes for divine reward so he does good deeds.', 'Ghurar al-Hikam, The Felicitous §2', 'wisdom'),
  ('إنَّ أسْعَدَ النَّاسِ مَنْ كانَ لَهُ مِنْ نَفْسِهِ بِطاعَةِ اللّهِ مُتَقاض.', 'Verily the most felicitous of people is one who has an exhorter in himself [that urges him] to obey Allah.', 'Ghurar al-Hikam, The Felicitous §3', 'wisdom'),
  ('اَلسَّعيدُ مَنْ أخْلَصَ الطَّاعَةَ.', 'Felicitous is one who makes his obedience [and worship] sincere.', 'Ghurar al-Hikam, The Felicitous §4', 'wisdom'),
  ('إنْ أحْبَبْتَ أنْ تَكُونَ أسْعَدَ النّاسِ بِما عَلِمْتَ فَاعْمَلْ.', 'If you would like to be the most felicitous of people through what you have learnt, then act upon it.', 'Ghurar al-Hikam, The Felicitous §5', 'wisdom'),
  ('إنَّما السَّعيدُ مَنْ خافَ العِقابَ فَأَمِنَ، ورَجا الثَّوابَ فَاحْسَنَ،وَ اشْتاقَ إلَى الجَنَّةِ فَادَّلَجَ.', 'Indeed only he is felicitous who fears divine punishment so he safeguards himself, and hopes for divine reward so he does good, and longs for Paradise so he wakes up [to worship] in the night.', 'Ghurar al-Hikam, The Felicitous §6', 'wisdom'),
  ('التَّشَمُرُّ لِلْجِدِّ مِنْ سَعادَةِ الجَدِّ.', 'Rolling up one’s clothes [in preparation] for serious work is from [one’s] good fortune.', 'Ghurar al-Hikam, Striving And Seeking §1', 'purpose'),
  ('أُطْلُبْ تَجِدْ.', 'Seek and you shall find.', 'Ghurar al-Hikam, Striving And Seeking §2', 'purpose'),
  ('عَلَيْكَ بِالسَّعِي ولَيْسَ عَلَيْكَ بِالنُّجْحِ.', 'It is upon you to strive but it is not upon you to succeed.', 'Ghurar al-Hikam, Striving And Seeking §3', 'purpose'),
  ('لَنْ يَضيعَ مِنْ سَعْيِكَ ما أصْلَحَكَ وأكْسَبَكَ الأجْرَ.', 'Never will your striving for that which improves you and earns divine reward be wasted.', 'Ghurar al-Hikam, Striving And Seeking §4', 'purpose'),
  ('مَنْ أسْرَعَ المَسيرَ أدْرَكَ المَقيلَ.', 'One who hastens his pace arrives at the place of rest [and repose].', 'Ghurar al-Hikam, Striving And Seeking §5', 'purpose'),
  ('مَنْ حَسُنَتْ مَساعيهِ طابَتْ مَراعيهِ.', 'One whose efforts are good, his place in the Hereafter will be good.', 'Ghurar al-Hikam, Striving And Seeking §6', 'purpose'),
  ('اِسْعَوْا في فِكاكِ رِقابِكُمْ قَبْلَ أنْ تُغْلَقَ رَهائِنُها.', 'Strive to free your necks [from the shackles of this world] before the doors of ransom are shut.', 'Ghurar al-Hikam, Striving And Seeking §7', 'purpose'),
  ('مَنْ أسْرَعَ إلَى النّاسِ بِما يَكْرَهُونَ قالُوا فيهِ ما لايَعْلَمُونَ.', 'Whoever hastens to the people with that which they dislike, they will speak about him that which they do not know.', 'Ghurar al-Hikam, Striving And Seeking §8', 'purpose'),
  ('رُبَّ ساع فيما يَضُرُّهُ.', 'Many a person strives in that which is harmful for him.', 'Ghurar al-Hikam, Striving And Seeking §9', 'purpose'),
  ('رُبَّ ساهِر لِراقِد.', 'Many a person is awake so that another can sleep.', 'Ghurar al-Hikam, Striving And Seeking §10', 'purpose'),
  ('اَلسَّفَرُ أحَدُ العَذابَيْنِ.', 'Travelling is one of the two torments.', 'Ghurar al-Hikam, Travel §1', 'wisdom'),
  ('كِذْبُ السَّفيرِ يُوَلِّدُ الفَسادَ، ويُفَوِّتُ المُرادَ ويُبْطِلُ الحَزْمَ،وَ يَنْقُضُ العَزْمَ.', 'The lies of an envoy give rise to corruption, cause the failure of the intended objective, nullify judiciousness and invalidate firm resolution.', 'Ghurar al-Hikam, The Envoy §1', 'wisdom'),
  ('سَفْكُ الدِّماءِ بِغَيْرِ حَقِّها يَدْعُوا إلى حُلُولِ النِقْمَةِ وزَوالِ النِّعْمَةِ.', 'Spilling blood without just cause invites the descending of divine wrath and the cessation of blessings.', 'Ghurar al-Hikam, Spilling Blood §1', 'wisdom'),
  ('شُقُّوا أمْواجَ الفِتَنِ بِسُفُنِ النَّجاةِ.', 'Cut through the waves of discord by [embarking on] the ships of salvation.', 'Ghurar al-Hikam, The Ships Of Salvation §1', 'wisdom'),
  ('إيّاكَ والسَّفَهَ فَإنَّهُ يُوحِشُ الرِّفاقَ.', 'Beware of dimwittedness for verily it causes one to be deserted by his friends.', 'Ghurar al-Hikam, Dimwittedness §1', 'wisdom'),
  ('اَلسَّفَهُ خُرْقٌ.', 'Dimwittedness is idiocy.', 'Ghurar al-Hikam, Dimwittedness §2', 'wisdom'),
  ('اَلسَّفَهُ جَريرَةٌ.', 'Dimwittedness [and insolence] is an offence.', 'Ghurar al-Hikam, Dimwittedness §3', 'wisdom'),
  ('اَلسَّفَهُ مِفْتاحُ السِّبابِ.', 'Dimwittedness is the key to ridicule.', 'Ghurar al-Hikam, Dimwittedness §4', 'wisdom'),
  ('اَلسَّفَهُ يَجْلُبُ الشَّـرَّ.', 'Dimwittedness attracts evil.', 'Ghurar al-Hikam, Dimwittedness §5', 'wisdom'),
  ('دَعِ السَّفَهَ فَإنَّهُ يُزْري بِالمَرْءِ ويَشينُهُ.', 'Shun dimwittedness, for verily it belittles a person and dishonor’s him.', 'Ghurar al-Hikam, Dimwittedness §6', 'wisdom'),
  ('سِلاحُ الجَهْلِ السَّفَهُ.', 'The weapon of ignorance is dimwittedness.', 'Ghurar al-Hikam, Dimwittedness §7', 'wisdom'),
  ('كَفى بِالسَّفَهِ عاراً.', 'Dimwittedness is enough as a disgrace.', 'Ghurar al-Hikam, Dimwittedness §8', 'wisdom'),
  ('كَثْرَةُ السَّفَهِ تُوجِبُ الشَّنَ آنَ وتَجْلُبُ البَغْضاءَ.', 'Increased dimwittedness brings about ill feelings and gives rise to hatred.', 'Ghurar al-Hikam, Dimwittedness §9', 'wisdom'),
  ('لَيْسَ السَّفَهُ كَالحِلْمِ.', 'Dimwittedness is not like intelligence.', 'Ghurar al-Hikam, Dimwittedness §10', 'wisdom'),
  ('أعْيى ما يَكُونُ الحَكيمُ إذا خاطَبَ سَفيهاً.', 'The wise person gets most fatigued when he speaks to a dimwit.', 'Ghurar al-Hikam, The Dimwit §1', 'wisdom'),
  ('أسْفَهُ السُّفَهاءِ المُتَبَجِّحُ بِفُحْشِ الكَلامِ.', 'The most dim-witted of all fools is the one who boasts with foul language.', 'Ghurar al-Hikam, The Dimwit §2', 'wisdom'),
  ('مَنْ داخَلَ السُّفَهاءَ حُقِّرَ.', 'One who enters the circle of dimwits is debased.', 'Ghurar al-Hikam, The Dimwit §3', 'wisdom'),
  ('مَنْ عَذَلَ سَفِيهاً فَقَدْ عَرَّضَ لِلسَّبِّ نَفْسَهُ.', 'One who censures a dimwit has exposed himself to insult.', 'Ghurar al-Hikam, The Dimwit §4', 'wisdom'),
  ('تَرْكُ جَوابِ السَّفيهِ أبْلَغُ جَوابِهِ.', 'Refraining from replying a dimwit is the best reply you can give him.', 'Ghurar al-Hikam, The Dimwit §5', 'wisdom'),
  ('لا يَعْرِفُ السَّفيهُ حَقَّ الحَليمِ.', 'The dimwit does not know the right of the wise one.', 'Ghurar al-Hikam, The Dimwit §6', 'wisdom'),
  ('لايُقَوِّمُ السَّفيهَ إلاّ مُرُّ الكَلامِ.', 'Nothing corrects the dimwit but bitter [and harsh] speech.', 'Ghurar al-Hikam, The Dimwit §7', 'wisdom'),
  ('مُقارَنَةُ السُّفَهاءِ تُفْسِدُ الخُلْقَ.', 'Accompanying the dimwit corrupts one’s character.', 'Ghurar al-Hikam, The Dimwit §8', 'wisdom'),
  ('مِنْ صِحَّةِ الأجْسامِ تَوَلُّدُ الأسْقامِ.', 'It is from the [good] health of the bodies that maladies originate.', 'Ghurar al-Hikam, Maladies §1', 'wisdom'),
  ('لا رَزِيَّةَ أعْظَمُ مِنْ دَوامِ سُقْمِ الجَسَدِ.', 'There is no affliction greater than the unrelenting physical ailment.', 'Ghurar al-Hikam, Maladies §2', 'wisdom'),
  ('لَيْسَ لِلأَجْسامِ نَجاةٌ مِنَ الأسْقامِ.', 'There is no escape for bodies from maladies.', 'Ghurar al-Hikam, Maladies §3', 'wisdom'),
  ('اَلوَقارُ حِلْيَةُ العَقْلِ.', 'Solemnity is the ornament of the intellect.', 'Ghurar al-Hikam, Calmness and Solemnity §1', 'wisdom'),
  ('اَلوَقارُ يُنْجِدُ (نَتيجَةُ) الحِلْمِ.', 'Solemnity supports (or gives rise to) forbearance.', 'Ghurar al-Hikam, Calmness and Solemnity §2', 'wisdom'),
  ('السَّكينَةُ عُنْوانُ العَقْلِ.', 'Calmness is a sign of intelligence.', 'Ghurar al-Hikam, Calmness and Solemnity §3', 'wisdom'),
  ('اَلوَقارُ بُرْهانُ النُّبْلِ.', 'Solemnity is evidence of nobility.', 'Ghurar al-Hikam, Calmness and Solemnity §4', 'wisdom'),
  ('إنْ تَوَقَّرْتَ أُكْرِمْتَ.', 'If you act with solemnity you will be honored.', 'Ghurar al-Hikam, Calmness and Solemnity §5', 'wisdom'),
  ('بِالوَقارِ تَكْثُرُ الهَيْبَةُ.', 'Through solemnity, one’s reverence increases.', 'Ghurar al-Hikam, Calmness and Solemnity §6', 'wisdom'),
  ('عَلَيْكَ بِالسَّكينَةِ فَإنَّها أفْضَلُ زينَة.', 'Espouse calmness, for indeed it is the best embellishment.', 'Ghurar al-Hikam, Calmness and Solemnity §7', 'wisdom'),
  ('كُنْ فِي المَلاءِ وَقُوراً، وَكُنْ فِي الخَلاءِ ذَكُوراً.', 'Be solemn when among the people and oft-remembering [of Allah and His bounties] when alone.', 'Ghurar al-Hikam, Calmness and Solemnity §8', 'wisdom'),
  ('لِتَكُنْ شيمَتُكَ الوَقارَ فَمَنْ كَثُرَ خُرْقُهُ اُسْتُرْذِلَ.', 'Let solemnity be your trait, for one whose silliness increases is scorned.', 'Ghurar al-Hikam, Calmness and Solemnity §9', 'wisdom'),
  ('مَنْ تَوَقَّرَ وُقِّرَ.', 'One who acts with solemnity is revered.', 'Ghurar al-Hikam, Calmness and Solemnity §10', 'wisdom'),
  ('رُبَّ سَلَف (سَلَب) عادَ خَلَفاً.', 'Many a thing that has been sent ahead (or has been pillaged) returns back [as it was before].', 'Ghurar al-Hikam, The Preceding §1', 'wisdom'),
  ('أبْخَلُ النَّاسِ مَنْ بَخِلَ بِالسَّلامِ.', 'The most miserly of people is the only who is stingy with his Salām.', 'Ghurar al-Hikam, Salāms And Greetings §1', 'wisdom'),
  ('بَذْلُ التَّحِيَّةِ مِنْ حُسْنِ الأخْلاقِ والسَّجِيَّةِ.', 'Offering greetings is one of the virtuous morals and traits.', 'Ghurar al-Hikam, Salāms And Greetings §2', 'wisdom'),
  ('اَلسِّلْمُ ثَمَرَةُ الحِلْمِ.', 'Peace is the fruit of forbearance.', 'Ghurar al-Hikam, Peace and Reconciliation §1', 'relationships'),
  ('اَلسِّلْمُ عِلَّةُ السَّلامَةِ وعَلامَةُ الاِسْتِقامَةِ.', 'Peace is the cause of security and the sign of steadfastness.', 'Ghurar al-Hikam, Peace and Reconciliation §2', 'relationships'),
  ('سالِمِ النّاسَ تَسْلَمْ، واعْمَلْ للآخِرَةِ تَغْنَمْ.', 'Be peaceful with people and you will be safe; work for the Hereafter and you will be successful.', 'Ghurar al-Hikam, Peace and Reconciliation §3', 'relationships'),
  ('مَنْ سالَمَ النّاسَ كَثُرَ أصْدِقائُهُ وقَلَّ أعْدائُهُ.', 'Whoever is peaceful with the people, his friends increase and his enemies decrease?', 'Ghurar al-Hikam, Peace and Reconciliation §4', 'relationships'),
  ('مَنْ سالَمَ النّاسَ سُتِرَتْ عُيُوبُهُ.', 'Whoever is peaceful with the people, his faults remain hidden.', 'Ghurar al-Hikam, Peace and Reconciliation §5', 'relationships'),
  ('مَنْ سالَمَ النّاسَ رَبِـحَ السَّلامَةَ.', 'One who is peaceful with the people gains security.', 'Ghurar al-Hikam, Peace and Reconciliation §6', 'relationships'),
  ('مَنْ رَضِيَ مِنَ النَّاسِ بِالمُسالَمَةِ سَلِمَ مِنْ غَوائِلِهِمْ.', 'One who is pleased to live peacefully with the people will be safe from their adversities.', 'Ghurar al-Hikam, Peace and Reconciliation §7', 'relationships'),
  ('وَجَدْتُ المُسالَمَةَ مالَمْ يَكُنْ وَهْنٌ فِي الإسْلامِ أنْجَعَ مِنَ القِتالِ.', 'I found the reconciliation that does not weaken Islam to be more beneficial than war.', 'Ghurar al-Hikam, Peace and Reconciliation §8', 'relationships'),
  ('لاعاقِبَةَ أسْلَمُ مِنْ عَواقِبِ السِّلْمِ.', 'There is no outcome sounder than the outcomes of peace.', 'Ghurar al-Hikam, Peace and Reconciliation §9', 'relationships'),
  ('الإسْلامُ هُوَ التَّسليمُ، والتَّسْليمُ هُوَ اليَقيْـنُ،وَ اليَقيْـنُ هُوَ التَّصْديقُ، وَالتَّصْديقُ هُوَ الإقْرارُ، والإقْرارُ هُوَ الأداءُ، والأداءُ هُوَ العَمَلُ.', 'Islam means submission [to the will of Allah], and submission means certitude, and certitude means attestation, and attestation means confirmation, and confirmation means execution, and execution means action.', 'Ghurar al-Hikam, Islam- §1', 'wisdom'),
  ('إنَّ للإسْلامِ غايَةً فَانْتَهُوا إلى غايَتِهِ، واخْرُجُوا إلَى اللّهِ مِمّا افْتَرَضَ عَلَيْكُمْ مِنْ حُقُوقِهِ.', 'Verily Islam has a goal, so strive towards its goal and proceed towards Allah by fulfilling that which He has ordained upon you of His rights.', 'Ghurar al-Hikam, Islam- §2', 'wisdom'),
  ('اَلإسْلامُ أبْلَجُ المَناهِجِ.', 'Islam is the most illuminated course.', 'Ghurar al-Hikam, Islam- §3', 'wisdom'),
  ('وقال ـ عليه السّلام ـ في ذكرِ الإسْلامِ: تَبْصِرَةٌ لِمَنْ عَزَمَ، وآيَةٌ لِمَنْ تَوَسَّمَ، وَعِبْرَةٌ لِمَنِ اتَّعَظَ، ونَجاةٌ لِمَنْ صَدَّقَ.', 'And he (‘a) said about Islam: It is an instruction for the resolute, a sign for the one who examines it [carefully], a lesson for the one who takes heed and a salvation for the one who accepts it.', 'Ghurar al-Hikam, Islam- §4', 'wisdom'),
  ('زينَةُ الإسْلامِ إعْمالُ الإحْسانِ.', 'The embellishment of Islam is performing righteous actions.', 'Ghurar al-Hikam, Islam- §5', 'wisdom'),
  ('شَرَعَ اللّهُ لَكُمُ الإسْلامَ، فَسَهَّلَ شَرايِعَهُ، وأعَزَّ أرْكانَهُ على مَنْ حارَبَهُ.', 'Allah has prescribed Islam for you and has made its laws easy, and He has strengthened its pillars against those who wage war with it.', 'Ghurar al-Hikam, Islam- §6', 'wisdom'),
  ('ظاهِرُ الإسْلامِ مُشْرِقٌ، وباطِنُهُ مُونِقٌ.', 'The outward side of Islam is radiant and its inward aspect is elegant.', 'Ghurar al-Hikam, Islam- §7', 'wisdom'),
  ('غايَةُ الإسْلامِ التَّسليمُ.', 'The objective of Islam is [complete] submission [to the will of Allah].', 'Ghurar al-Hikam, Islam- §8', 'wisdom'),
  ('وَالإسْلامَ أماناً مِنَ المَخاوِفِ.', 'Islam [has been prescribed] as a security form dangers.', 'Ghurar al-Hikam, Islam- §9', 'wisdom'),
  ('مِلاكُ الإسْلامِ صِدْقُ اللِّسانِ.', 'The basis of Islam is truthfulness [in speech].', 'Ghurar al-Hikam, Islam- §10', 'wisdom'),
  ('أفْضَلُ المُسْلِمينَ إسْلاماً مَنْ كانَ هَمُّهُ لأُخْراهُ،وَ اعْتَدَلَ خَوْفُهُ وَرَجاهُ.', 'The best of all Muslims in practicing Islam is he whose efforts are for his Hereafter and whose fear [of Allah’s wrath] is balanced with his hope [in His mercy].', 'Ghurar al-Hikam, The Muslims- §1', 'wisdom'),
  ('إنَّ المُسْلِمينَ (المُؤمِنين) مُسْتَكينُونَ.', 'Verily the Muslims (or the believers) are humble.', 'Ghurar al-Hikam, The Muslims- §2', 'wisdom'),
  ('مَنْ أسْلَمَ سَلِمَ.', 'One who accepts Islam [and submits to the will of Allah] remains safe [in the Hereafter].', 'Ghurar al-Hikam, The Muslims- §3', 'wisdom'),
  ('هُدِيَ مَنْ حَسُنَ إسْلامُهُ.', 'One who practices Islam properly is [truly] guided.', 'Ghurar al-Hikam, The Muslims- §4', 'wisdom'),
  ('اَلتَّسليمُ أنْ لاتَتَّهِمَ.', 'Submission means not blaming [Allah for what happens].', 'Ghurar al-Hikam, Submission to the Will of Allah- §1', 'wisdom'),
  ('إنْ أسْلَمْتَ نَفْسَكَ لِلّهِ سَلِمَتْ نَفْسُكَ.', 'If you submit your soul to Allah, your soul remains safe.', 'Ghurar al-Hikam, Submission to the Will of Allah- §2', 'wisdom'),
  ('سُنَّةُ الأَبـْرارِ حُسْنُ الاِسْتِسْلامِ.', 'The practice of the righteous people is complete submission [to the will of Allah].', 'Ghurar al-Hikam, Submission to the Will of Allah- §3', 'wisdom'),
  ('سالِمِ اللّهَ تَسْلَمْ أُخْراكَ.', 'Submit to Allah and your Hereafter will be saved.', 'Ghurar al-Hikam, Submission to the Will of Allah- §4', 'wisdom'),
  ('سَلِّمُوا لأمْرِ اللّهِ، وَلاِمْرِ وَلِيِّهِ، فَإنَّكُمْ لَنْ تَضِلُّوا مَعَ التَّسْليمِ.', 'Submit yourselves to the command of Allah and the command of His chosen servant, for verily you will never go astray with submission.', 'Ghurar al-Hikam, Submission to the Will of Allah- §5', 'wisdom'),
  ('غايَةُ التَّسْليمِ الفَوْزُ بِدارِ النَّعيمِ.', 'The end result of [complete] submission [to the will of Allah] is success in reaching the Abode of Bounties.', 'Ghurar al-Hikam, Submission to the Will of Allah- §6', 'wisdom'),
  ('فِي التَّسْليمِ إيمانٌ.', 'In submission there is faith.', 'Ghurar al-Hikam, Submission to the Will of Allah- §7', 'wisdom'),
  ('هُدِيَ مَنْ سَلَّمَ مَقادَتَهُ إلَى اللّهِ وَ رَسُوْلِهِ وَ وَلِيِّ أمْرِِهِ.', 'Guided is the one who submits to the guidance of Allah and His Prophet and the one vested with His authority.', 'Ghurar al-Hikam, Submission to the Will of Allah- §8', 'wisdom'),
  ('لا إيمانَ أفْضَلُ مِنَ الاِسْتِسْلامِ.', 'There is no faith better than surrendering to the will of Allah.', 'Ghurar al-Hikam, Submission to the Will of Allah- §9', 'wisdom'),
  ('إنَّكَ إنْ سالَمْتَ اللّهَ سَلِمْتَ وَفُزْتَ.', 'Verily if you submit to Allah, you will be safe and successful.', 'Ghurar al-Hikam, Submission to the Will of Allah- §10', 'wisdom'),
  ('مَنْ طَلَبَ السَّلامَةَ لَزِمَ الاِسْتِقامَةَ.', 'One who seeks security remains steadfast [on the straight path].', 'Ghurar al-Hikam, Security- §1', 'wisdom'),
  ('مَنْ أرادَ السَّلامَةَ فَعَلَيْهِ بِالقَصْدِ.', 'One who desires security should adopt moderation.', 'Ghurar al-Hikam, Security- §2', 'wisdom'),
  ('مَنْ رَغِبَ فِي السَّلامَةِ ألْزَمَ نَفْسَهُ الاِسْتِقامَةَ.', 'One who wishes for security keeps himself steadfast on the straight path.', 'Ghurar al-Hikam, Security- §3', 'wisdom'),
  ('مَنْ أحَبَّ السَّلامَةَ فَلْيُؤثِرِ الفَقْرَ، وَمَنْ أحَبَّ الرَّاحَةَ فَلْيُؤْثِرِ الزُّهْدَ فِي ِالدُّنيا.', 'One who loves security must prefer poverty [over wealth] and one who loves comfort must prefer abstinence from pleasures in this world.', 'Ghurar al-Hikam, Security- §4', 'wisdom'),
  ('مَنْ كانَ فيه ثَلاثٌ سَلِمَتْ لَهُ الدُّنيا وَالآخِرَةُ: يَأمُرُ بِالمَعْرُوفِ وَيَأْتَمِرُ بِهِ، وَ يَنْهى عَنِ المُنْكَرِ وَيَنْتَهي عَنْهُ وَيُحافِظُ عَلى حُدُودِ اللّهِ جَلَّ وَعَلا.', 'One who has three [qualities] in him, will remain safe both in this world and the next: He enjoins good and follows it himself, He forbids evil and keeps away from it himself, and he preserves the boundaries [and ordinances] of Allah, the Sublime and the Exalted.', 'Ghurar al-Hikam, Security- §5', 'wisdom'),
  ('لا وِقايَةَ أمْنَعُ مِنَ السَّلامَةِ.', 'There is no preservation more averting [of harm] than security [that is granted by Allah].', 'Ghurar al-Hikam, Security- §6', 'wisdom'),
  ('لالِباسَ أجْمَلُ مِنَ السَّلامَةِ.', 'There is no attire more appealing than security [and well-being].', 'Ghurar al-Hikam, Security- §7', 'wisdom'),
  ('رُبَّ سالِم بَعْدَ النَّدامَةِ.', 'Many a person remains safe after regret.', 'Ghurar al-Hikam, Security- §8', 'wisdom'),
  ('كُلُّ مُسْتَسْلِم مُوَقًّي.', 'Everyone who surrenders [to Allah] is protected.', 'Ghurar al-Hikam, The One Who Surrenders- §1', 'wisdom'),
  ('مَنِ اسْتَسْلَمَ سَلِمَ.', 'One who surrenders [to Allah] remains safe.', 'Ghurar al-Hikam, The One Who Surrenders- §2', 'wisdom'),
  ('مَنِ اسْتَسْلَمَ إلَى اللّهِ اِسْتَظْهَرَ.', 'One who surrenders himself to Allah is supported [by Him].', 'Ghurar al-Hikam, The One Who Surrenders- §3', 'wisdom'),
  ('مَنْ سَلَّمَ أمْرَهُ إلَى اللّهِ اِسْتَظْهَرَ.', 'One who submits his affair to Allah is supported [by Him].', 'Ghurar al-Hikam, The One Who Surrenders- §4', 'wisdom'),
  ('اَلمُسْتَسْلِمُ مُوَقًّي.', 'The one who surrenders [to Allah] is protected.', 'Ghurar al-Hikam, The One Who Surrenders- §5', 'wisdom'),
  ('اَلسُّلُوُّ حاصِدُ الشَّوْقِ.', 'Forgetfulness is the reaper of longing [and desire].', 'Ghurar al-Hikam, Forgetfulness- §1', 'wisdom'),
  ('مَنْ سَلا عَنِ المَسْلُوبِ كَأنْ لَمْ يُسْلَبْ.', 'One who forgets about what has been robbed from him, it is as if he has not been robbed.', 'Ghurar al-Hikam, Forgetfulness- §2', 'wisdom'),
  ('وَ عَزّى ـ عَليه السّلامُ ـ رَجُلاً ماتَ لَهُ وَلَدٌ وَ رُزِقَ لَهُ وَلَدٌ فقالَ: عَظَّمَ اللّهُ أجْرَكَ فيما أبادَ، وَبارَكَ لَكَ فيما أفادَ.', 'He (‘a) consoled a man whose son passed away and [at the same time] was blessed with the birth of [another] son saying: May Allah make your reward great [for your patience] in that which He took away, and may His blessings be with you in that which He has bestowed [upon you].', 'Ghurar al-Hikam, Condolences and Congratulations- §1', 'wisdom'),
  ('نِعْمَ الدَّلالَةُ حُسْنُ السَّمْتِ.', 'How good a guidance having a good mien is!', 'Ghurar al-Hikam, Mien- §1', 'wisdom'),
  ('جَعَلَ اللّهُ سُبْحانَهُ لَكُمْ أسْماعاً لِتَعِيَ ماعَناها، وَ أبْصاراً لِتَجْلُوَ مِنْ عَشاها.', 'Allah, the Glorified, has granted you with hearing so that it may heed [and comprehend] that which is concerns it and with sight so that what is dark for it may be brought to light [and seen clearly].', 'Ghurar al-Hikam, Hearing and Sight- §1', 'wisdom'),
  ('رَحِمَ اللّهُ عَبْداً سَمِعَ حُكْماً فَوَعى، وَ دُعِيَ إلى رَشاد فَدَنى، وَ أخَذَ بِحُجْزَةِ هاد فَنَجا.', 'May Allah have mercy on the servant who hears a ruling so he heeds it, is invited to the right path so he approaches it, and holds on to the guide so he is saved.', 'Ghurar al-Hikam, Listening and the listener- §1', 'wisdom'),
  ('لا يُؤْتَي العِلْمُ اِلاّمِنْ سُوءِ فَهْمِ السّامِعِ.', 'Knowledge is not ruined except by the miscomprehension of the listener.', 'Ghurar al-Hikam, Listening and the listener- §2', 'wisdom'),
  ('اِسْمَعْ تَعْلَمْ، وَ اصْمُتْ تَسْلَمْ.', 'Listen and you will learn; remain silent and you will be safe.', 'Ghurar al-Hikam, Listening and the listener- §3', 'wisdom'),
  ('مَنْ أحْسَنَ الاِسْتِماعَ تَعَجَّلَ الاِنْتِفاعَ.', 'One who listens well benefits quickly.', 'Ghurar al-Hikam, Listening and the listener- §4', 'wisdom'),
  ('لاتَطْمَعْ في كُلِّ ما تَسْمَعُ، فَكَفى بِذلِكَ غِرَّةً (خُرْقاً).', 'Do not desire for everything that you hear, for this suffices as gullibility (or foolishness).', 'Ghurar al-Hikam, Listening and the listener- §5', 'wisdom'),
  ('عَوِّدْ أُذُنَكَ حُسْنَ الاِسْتِماعِ، وَ لاتُصْغِ إلى ما لايَزيدُ في صَلاحِكَ اِسْتِماعُهُ، فَإنَّ ذلِكَ يُصْدِيُ القُلُوبَ وَيُوجِبُ المَذامَّ.', 'Train your ears to listen well and do not pay attention to that which does not increase anything useful for you by listening to it, for verily this corrodes the hearts and leads to dispraise.', 'Ghurar al-Hikam, Listening and the listener- §6', 'wisdom'),
  ('السَّامِعُ شَريكُ القائِلِ.', 'The listener is a partner of the speaker.', 'Ghurar al-Hikam, Listening and the listener- §7', 'wisdom'),
  ('لا تَنْقُضْ سُنَّةً صالِحَةً عُمِلَ بِها، وَ اجْتَمَعَتِ الأُلْفَةُ لَها، وَ صَلَحَتِ الرَّعيَّةُ عَلَيْها.', 'Do not discontinue the good practices that have been [previously] acted upon, and which the people have become familiar with, and which the masses have found suitable.', 'Ghurar al-Hikam, Righteous Practices- §1', 'wisdom'),
  ('إيّاكَ وَ الإساءَةَ، فَإنَّها خُلْقُ اللِّئامِ، وَإنَّ المُسِيءَ لَمُتَرَدّ في جَهَنَّمَ بِإساءَتِهِ.', 'Beware of doing wrong [to others], for indeed it is a vile quality and verily the one who hurts others will surely be thrown into hell because of his wrongs.', 'Ghurar al-Hikam, Doing Wrong to Others- §1', 'wisdom'),
  ('إنَّكَ إنْ أسَأتَ فَنَفْسَكَ تَمْتَهِنُ، وَ إيّاها تَغْبِنُ.', 'Verily if you do wrong [to others] then you are only debasing and harming yourself.', 'Ghurar al-Hikam, Doing Wrong to Others- §2', 'wisdom'),
  ('ضادُّوا الإسائَةَ بِالإحْسانِ.', 'Counter the wrongs [of others] by doing good [to them].', 'Ghurar al-Hikam, Doing Wrong to Others- §3', 'wisdom'),
  ('مَنْ شُكِرَ علَى الإسائَةِ سُخِرَ بِهِ.', 'One who is thanked for doing wrong is [actually] mocked for it.', 'Ghurar al-Hikam, Doing Wrong to Others- §4', 'wisdom'),
  ('مَنْ أساءَ إلى رَعِيَّتِهِ سَـرَّ حُسّادَهُ.', 'One who wrongs his subjects pleases his enviers.', 'Ghurar al-Hikam, Doing Wrong to Others- §5', 'wisdom'),
  ('مَنْ أساءَ اِجْتَلَبَ سُوءُ الجَزاءِ.', 'One who wrongs others brings upon himself a severe reprisal.', 'Ghurar al-Hikam, Doing Wrong to Others- §6', 'wisdom'),
  ('مَنْ عامَلَ النّاسَ بِالإساءَةِ كافَؤُهُ بِها.', 'Whoever treats people badly, they requite him with the same treatment.', 'Ghurar al-Hikam, Doing Wrong to Others- §7', 'wisdom'),
  ('مَنْ جَرى في مَيْدانِ إساءَتِهِ كَبا في جَرْيِهِ.', 'One who proceeds in the course of his offences stumbles in his progress.', 'Ghurar al-Hikam, Doing Wrong to Others- §8', 'wisdom'),
  ('لا تُسِيْ إلى مَنْ أحْسَنَ إلَيْكَ، فَمَنْ أساءَ إلى مَنْ أحْسَنَ إلَيْهِ مُنِعَ الإحْسانُ.', 'Do not wrong the person who does good to you, for one who wrongs the person who does him a favour will be denied favours [in the future].', 'Ghurar al-Hikam, Doing Wrong to Others- §9', 'wisdom'),
  ('مَنْ أساءَ إلى أهْلِهِ لَمْ يَتَّصِلْ بِهِ تَأْميلٌ.', 'Whoever wrongs his [own] family, no hope [of any goodness] can be attached to him.', 'Ghurar al-Hikam, Doing Wrong to Others- §10', 'wisdom'),
  ('كَمْ مِنْ مُسَوِّف بِالعَمَلِ حتّى هَجَمَ عَلَيْهِ الأجَلُ.', 'How many a person has postponed doing something until death falls upon him!', 'Ghurar al-Hikam, Procrastination §1', 'wisdom'),
  ('مُسَوِّفُ نَفْسِهِ بِالتَّوْبَةِ مِنْ هُجُومِ الأجَلِ عَلى أعْظَمِ الخَطَرِ.', 'The one who delays seeking repentance is in the greatest danger of the onslaught of death.', 'Ghurar al-Hikam, Procrastination §2', 'wisdom'),
  ('لا دِينَ لِمُسَوِّف بِتَوْبَتِهِ.', 'One who procrastinates in seeking repentance has no faith.', 'Ghurar al-Hikam, Procrastination §3', 'wisdom'),
  ('اَلسَّـيِّدُ مَحْسُودٌ، وَ الجَوادُ مَحْبُوبٌ مَوْدُودٌ.', 'The eminent one is envied and the munificent one is loved and adored.', 'Ghurar al-Hikam, Eminence And The Eminent §1', 'wisdom'),
  ('اَلسَّـيِّدُ مَنْ تَحَمَّلَ أثْقالَ إخْوانِهِ، وَ أحْسَنَ مُجاوَرَةَ جيرانِهِ.', 'The eminent person is one who bears the burdens of his brothers and is neighborly to his neighbor.', 'Ghurar al-Hikam, Eminence And The Eminent §2', 'wisdom'),
  ('اَلسَّـيِّدُ مَنْ لا يُصانِعُ، وَلا يُخادِعُ، وَلا تَغُرُّهُ المَطامِعُ.', 'The eminent person is one who neither flatters nor deceives, nor is he beguiled by greedy ambitions.', 'Ghurar al-Hikam, Eminence And The Eminent §3', 'wisdom'),
  ('اَلسَّـيِّدُ مَنْ تَحَمَّلَ المَؤُنَةَ، وَجادَ بِالمَعُونَةِ.', 'The eminent person is one who bears the responsibility of providing [for others] and is generous with his assistance.', 'Ghurar al-Hikam, Eminence And The Eminent §4', 'wisdom'),
  ('تَمامُ السُّؤْدَدِ اِبْتِداءُ الصَّنايِـعِ.', 'The completion of eminence is in taking the initiative to do good to others.', 'Ghurar al-Hikam, Eminence And The Eminent §5', 'wisdom'),
  ('سادَةُ النّاسِ فِي الدُّنيا الأسْخياءُ، وَفِي الآخِرَةِ الأتْقياءُ.', 'The eminent among the people in this world are the generous ones and in the Hereafter, the God-wary.', 'Ghurar al-Hikam, Eminence And The Eminent §6', 'wisdom'),
  ('فَضيلَةُ السَّادَةِ حُسْنُ العِبادَةِ.', 'The excellence of the eminent ones is in [their] devout worship [of Allah].', 'Ghurar al-Hikam, Eminence And The Eminent §7', 'wisdom'),
  ('فِعْلُ المَعْرُوفِ، وَ إغاثَةُ المَلْهُوفِ، وَ إقْراءُ الضُّيُوفِ آلَةُ السّيادَةِ.', 'Righteous action, aiding the aggrieved and inviting guests [to one’s home] are instruments [and means] of eminence.', 'Ghurar al-Hikam, Eminence And The Eminent §8', 'wisdom'),
  ('لَمْ يَسُدْ مَنِ افْتَقَرَ إخْوانُهُ إلى غَيْرِهِ.', 'One whose brothers have to turn to other than him [for their needs] has not attained eminence.', 'Ghurar al-Hikam, Eminence And The Eminent §9', 'wisdom'),
  ('مِنَ السُّؤْدَدِ الصَّبْرُ، لاِسْتِماعِ شَكْوَى المَلْهُوفِ.', 'Listening to the complaint of the aggrieved is part of eminence.', 'Ghurar al-Hikam, Eminence And The Eminent §10', 'wisdom'),
  ('إيّاكَ وَ مَقاعِدَ الأسْواقِ، فَإنَّها مَعارِضُ الفِتَنِ، وَمَحاضِرُ الشَيْطانِ.', 'Be wary of the sitting in the marketplaces, for indeed they are the locations of mischief and the visiting places of Satan.', 'Ghurar al-Hikam, Markets §1', 'wisdom'),
  ('مَجالِسُ الأسْواقِ مَحاضِرُ الشَّيْطانِ.', 'The gatherings of the marketplaces are the visiting places of Satan.', 'Ghurar al-Hikam, Markets §2', 'wisdom'),
  ('اَلسَّهَرُ أحَدُ الْحَياتَيْنِ.', 'Night vigil is one of the two lives.', 'Ghurar al-Hikam, Night Vigil §1', 'wisdom'),
  ('اَلسَّهَرُ رَوْضَةُ الْمُشْتاقينَ.', 'Night vigil is the garden of those who yearn [nearness of Allah].', 'Ghurar al-Hikam, Night Vigil §2', 'wisdom'),
  ('سَهَرُ اللَّيْلِ شِعارُ المُتَّقينَ، وَ شيمَةُ الْمُشتاقينَ.', 'Night vigil is the insignia of the pious and the quality of those who yearn.', 'Ghurar al-Hikam, Night Vigil §3', 'wisdom'),
  ('سَهَرُ العُيُونِ بِذِكْرِ اللّهِ خُلْصانُ الْعارِفينَ، وَ حُلْوانُ الْمُقَرَّبينَ.', 'Keeping vigil at night in the remembrance [and worship] of Allah is the devotion of the Gnostics and the delight of the Near Ones.', 'Ghurar al-Hikam, Night Vigil §4', 'wisdom'),
  ('سَهَرُ اللَّيْلِ في طاعَةِ اللّهِ رَبيعُ الأوْلياءِ، وَرَوْضَةُ السُّعَداءِ.', 'Keeping vigil at night in the worship of Allah is the spring of the friends [of Allah] and the garden of the felicitous.', 'Ghurar al-Hikam, Night Vigil §5', 'wisdom'),
  ('سَهَرُ اللَّيلِ(العيُونِ) بِذِكْرِ اللّهِ غَنِيمَةُ الأوْلياءِ، وَ سَجِيَّةُ الأتْقياءِ.', 'Keeping vigil at night in the remembrance [and worship] of Allah is the prize of the friends [of Allah] and the practice of the God-wary.', 'Ghurar al-Hikam, Night Vigil §6', 'wisdom'),
  ('سَهَرُ العُيُونِ بِذِكْرِ اللّهِ فُرْصَةُ السُّعَداءِ، وَ نُزْهَةُ الأوْلياءِ.', 'Keeping vigil at night in the remembrance of Allah is the opportunity of the felicitous and the promenade of the friends [of Allah].', 'Ghurar al-Hikam, Night Vigil §7', 'wisdom'),
  ('أسْهِرُوا عُيُونَكُمْ، وَ ضَمِّروُا بُطُونَكُمْ، وَ خُذُوا مِنْ أجْسادِكُمْ تَجُودُوا بِها عَلى أنْفُسِكُمْ.', 'Keep vigil at night and make your stomachs lean; and take away from your bodies so that you may be generous with it upon your souls.', 'Ghurar al-Hikam, Night Vigil §8', 'wisdom'),
  ('أفْضَلُ العِبادَةِ سَهَرُ العُيُونِ بِذِكْرِ اللّهِ سُبْحانَهُ.', 'The best of worship is staying awake at night in the remembrance of Allah, the Glorified.', 'Ghurar al-Hikam, Night Vigil §9', 'wisdom'),
  ('نِعْمَ عَوْنُ العِبادَةِ السَّهَرُ.', 'What a good helper of worship night vigil is!', 'Ghurar al-Hikam, Night Vigil §10', 'wisdom'),
  ('اَلتَسَهُّلُ يُدِرُّ الأرْزاقَ.', 'Facilitating [and making things easy for others] makes sustenance flow abundantly.', 'Ghurar al-Hikam, Facilitation §1', 'wisdom'),
  ('أقْبَحُ السِّيَرِ الظُّلْمُ.', 'The most loathsome mode of conduct is inequity.', 'Ghurar al-Hikam, Mode Of Conduct §1', 'wisdom'),
  ('بِالسِّيرَةِ العادِلَةِ يُقْهَرُ الْمُناوي.', 'Through an equitable conduct, the adversary is overpowered.', 'Ghurar al-Hikam, Mode Of Conduct §2', 'wisdom'),
  ('حُسْنُ السِّيرَةِ عُنْوانُ حُسْنِ السَّريرَةِ.', 'Good conduct is the sign of a good conscience.', 'Ghurar al-Hikam, Mode Of Conduct §3', 'wisdom'),
  ('حُسْنُ السِّيرَةِ جَمالُ القُدْرَةِ وَ حِصْنُ الاِمْرَةِ.', 'Good conduct is the beauty of power and the fortress of authority.', 'Ghurar al-Hikam, Mode Of Conduct §4', 'wisdom'),
  ('مَنْ ساءَتْ سيرَتُهُ سَرَّتْ مَنِيَّتُهُ.', 'One whose conduct is evil, his demise makes the people happy.', 'Ghurar al-Hikam, Mode Of Conduct §5', 'wisdom'),
  ('مَنْ ساءَتْ سيرَتُهُ لَمْ يَأْمَنْ أبَداً.', 'One whose conduct is evil will never be safe at any time.', 'Ghurar al-Hikam, Mode Of Conduct §6', 'wisdom'),
  ('وَيْلٌ لِمَنْ ساءَتْ سيرَتُهُ، وَ جارَتْ مَلَكَتُهُ وَ تَجَبَّرَ وَ اعْتَدى.', 'Woe be to the one whose conduct is evil, whose authority is oppressive, and who tyrannizes and infringes upon the rights [of those who are under him].', 'Ghurar al-Hikam, Mode Of Conduct §7', 'wisdom'),
  ('أصْعَبُ السِّياساتِ نَقْلُ الْعاداتِ.', 'The most difficult of administrative policies is the removal of habits [and customs].', 'Ghurar al-Hikam, Administrative Policies §1', 'wisdom'),
  ('بِئْسَ السِّياسَةُ الْجَوْرُ.', 'Tyranny is indeed an evil administrative policy.', 'Ghurar al-Hikam, Administrative Policies §2', 'wisdom'),
  ('جَمالُ السِّياسَةِ العَدْلُ فِي الاِمْرَةِ، وَ العَفْوُ مَعَ الْقُدْرَةِ.', 'The beauty of politics is [maintaining] justice in authority and pardoning despite having power [to punish].', 'Ghurar al-Hikam, Administrative Policies §3', 'wisdom'),
  ('حُسْنُ السِّياسَةِ قِوامُ الرَّعيَّةِ.', 'Good administration is the mainstay of the citizenry.', 'Ghurar al-Hikam, Administrative Policies §4', 'wisdom'),
  ('حُسْنُ السِّياسَةِ يَسْتَديمُ الرِّياسَةَ.', 'Good administration makes leadership last.', 'Ghurar al-Hikam, Administrative Policies §5', 'wisdom'),
  ('مَنْ حَسُنَتْ سِياسَتُهُ وَجَبَتْ طاعَتُهُ.', 'One whose administration is good, obeying him becomes obligatory.', 'Ghurar al-Hikam, Administrative Policies §6', 'wisdom'),
  ('مَنْ حَسُنَتْ سياسَتُهُ دامَتْ رِياسَتُهُ.', 'One whose administration is good, his leadership lasts.', 'Ghurar al-Hikam, Administrative Policies §7', 'wisdom'),
  ('مَنْ قَصُرَ عَنِ السِّياسَةِ صَغُرَ عَنِ الرِّياسَةِ.', 'One who falls short in administration [and politics] is poor in [and incapable of] leadership.', 'Ghurar al-Hikam, Administrative Policies §8', 'wisdom'),
  ('مِلاكُ السِّياسَةِ الْعَدْلُ.', 'The foundation of administration is justice.', 'Ghurar al-Hikam, Administrative Policies §9', 'wisdom'),
  ('لارِياسَةَ كَالعَدْلِ فِي السِّياسَةِ.', 'There is no leadership like [practicing] justice in administration.', 'Ghurar al-Hikam, Administrative Policies §10', 'wisdom'),
  ('شَيْئانِ لايَعْرِفُ فَضْلَهُما إلاّ مَنْ فَقَدَهُما الشَّبابُ وَالْعافِيَةُ.', 'Two things whose value is not understood except by the one who has lost them are youth and health.', 'Ghurar al-Hikam, Youth- §1', 'wisdom'),
  ('جَهْلُ الشّابِّ مَعْذُورٌ، وَ عِلْمُهُ مَحْقُورٌ.', 'The ignorance of a youth is excused and his knowledge is undermined.', 'Ghurar al-Hikam, Youth- §2', 'wisdom'),
  ('هَلْ يَنْتَظِرُ أهْلُ غَضاضَةِ (بِضاضَةِ)الشَّبابِ إلاّ حَوانِيَ الْهَرَمِ.', 'Are those who are the prime of youth awaiting anything other than the stooping of old age?', 'Ghurar al-Hikam, Youth- §3', 'wisdom'),
  ('لا تَجْتَمِعُ الشَّبيبَةُ وَ الهَرَمُ.', 'Youthfulness and senility do not go together.', 'Ghurar al-Hikam, Youth- §4', 'wisdom'),
  ('إيّاكَ وَ الْبِطْنَةَ، فَمَنْ لَزِمَها كَثُرَتْ أسْقامُهُ، وَ فَسَدَتْ أحْلامُهُ.', 'Be wary of gluttony, for whoever persists in it, his maladies increase and his dreams get corrupted.', 'Ghurar al-Hikam, Overeating and Gluttony- §1', 'wisdom'),
  ('إيّاكُمْ وَ الْبِطْنَةَ، فَإنَّها مِقْساةٌ لِلْقَلْبِ مَكْسَلَةٌ عَنِ الصَّلاةِ مَفْسَدَةٌ لِلْجَسَدِ.', 'Be wary of gluttony, for indeed it causes hardening of the heart, sluggishness in prayer and corruption of the body.', 'Ghurar al-Hikam, Overeating and Gluttony- §2', 'wisdom'),
  ('اَلبِطْنَةُ تَمْنَعُ الفِطْنَةَ.', 'Gluttony prevents astuteness.', 'Ghurar al-Hikam, Overeating and Gluttony- §3', 'wisdom'),
  ('مَنْ كَظَّتْهُ الْبِطْنَةُ حَجَبَتْهُ عَنِ الْفِطْنَةِ.', 'One who is cloyed by gluttony is obstructed by it from astuteness.', 'Ghurar al-Hikam, Overeating and Gluttony- §4', 'wisdom'),
  ('لا فِطْنَةَ مَعَ بِطْنَة.', 'There is no astuteness with gluttony.', 'Ghurar al-Hikam, Overeating and Gluttony- §5', 'wisdom'),
  ('لا تَجْتَمِعُ الفِطْنَةُ وَالْبِطْنَةُ.', 'Gluttony and astuteness do not go together.', 'Ghurar al-Hikam, Overeating and Gluttony- §6', 'wisdom'),
  ('التُّخْمَةُ تُفْسِدُ الْحِكْمَةَ.', 'Overeating corrupts wisdom.', 'Ghurar al-Hikam, Overeating and Gluttony- §7', 'wisdom'),
  ('البِطْنَة تَحْجُبُ الْفِطْنَةَ.', 'Gluttony obstructs astuteness.', 'Ghurar al-Hikam, Overeating and Gluttony- §8', 'wisdom'),
  ('اَلشَّبَعُ يُفْسِدُ الْوَرَعَ.', 'Eating to one’s fill corrupts piety.', 'Ghurar al-Hikam, Overeating and Gluttony- §9', 'wisdom'),
  ('إذا مُلِئَ البَطْنُ مِنَ الْمُباحِ عَمِيَ الْقَلْبُ عَنِ الصَّلاحِ.', 'When the stomach gets filled with the permissible, the heart becomes blind to righteousness.', 'Ghurar al-Hikam, Overeating and Gluttony- §10', 'wisdom'),
  ('مَنْ بَلَّغَكَ شَتْمَكَ فَقَدْ شَتَمَكَ.', 'One who informs you of your vilification has [himself] vilified you.', 'Ghurar al-Hikam, Vilification- §1', 'wisdom'),
  ('الشَّجاعَةُ أحَدُ الْعِزَّيْنِ.', 'Courage is one of the two honours.', 'Ghurar al-Hikam, Courage and the courageous- §1', 'character'),
  ('اَلشَّجاعَةُ نُصْرَةٌ حاضِرَةٌ، وَ فَضيلَةٌ ظاهِرةٌ.', 'Courage is a ready support and an evident merit.', 'Ghurar al-Hikam, Courage and the courageous- §2', 'character'),
  ('اَلشَّجاعَةُ زَيْنٌ، اَلجُبْنُ شَيْنٌ.', 'Courage is an embellishment, cowardice is a disgrace.', 'Ghurar al-Hikam, Courage and the courageous- §3', 'character'),
  ('اَلشَّجاعَةُ عِزٌّ حاضِرٌ، اَلْجُبْنُ ذُلٌّ ظاهِرٌ.', 'Courage is present honour, cowardice is evident dishonour.', 'Ghurar al-Hikam, Courage and the courageous- §4', 'character'),
  ('ثَمَرَةُ الشَّجاعَةِ الْغَيْرَةُ.', 'The fruit of courage is a sense of honour.', 'Ghurar al-Hikam, Courage and the courageous- §5', 'character'),
  ('زَكاةُ الشَّجاعَةِ الْجِهادُ في سَبيلِ اللّهِ.', 'The alms-tax of courage is struggling in the way of Allah.', 'Ghurar al-Hikam, Courage and the courageous- §6', 'character'),
  ('شَجاعَةُ الرَّجُلِ على قَدْرِ هِمَّتِهِ، وَ غَيْرَتُهُ على قَدْرِ حَمِيَّتِهِ.', 'The courage of a man is proportionate to his ambition, and his sense of honour is equivalent to his zeal.', 'Ghurar al-Hikam, Courage and the courageous- §7', 'character'),
  ('عَلى قَدْرِ الْحَمِيَّةِ تَكُونُ الشَّجاعَةُ.', 'It is to the extent of [one’s] zeal that courage is shown.', 'Ghurar al-Hikam, Courage and the courageous- §8', 'character'),
  ('مُعالَجَةُ النِّزالِ تُظْهِرُ شَجاعَةَ الأبْطالِ.', 'Fighting while dismounted [in battle] demonstrates the courage of champions.', 'Ghurar al-Hikam, Courage and the courageous- §9', 'character'),
  ('آفَةُ الشُّجاعِ إضاعَةُ الْحَزْمِ.', 'The bane of courage is loss of resolve.', 'Ghurar al-Hikam, Courage and the courageous- §10', 'character'),
  ('كُنْ فِي الشَّدائِدِ صَبُوراً، وَ فِي الزَّلازِلِ وَقُوراً.', 'Be patient in [the face of] difficulties and dignified in [times of] turbulent upheavals.', 'Ghurar al-Hikam, Difficulties- §1', 'wisdom'),
  ('لِلشَّدائِدِ تُدَّخَرُ الرِّجالُ.', 'It is for difficult times that [the friendships of important] men are preserved.', 'Ghurar al-Hikam, Difficulties- §2', 'wisdom'),
  ('اِعْتَزِمْ (اِعْتَرِمْ) بِالشِدَّةِ حينَ لايُغْني عَنْكَ إلاَّ الشِدَّةُ.', 'Be intent on [braving] difficulty when nothing will free you except difficulty.', 'Ghurar al-Hikam, Difficulties- §3', 'wisdom'),
  ('إيّاكَ ومُلابَسَةَ الشَّـرِّ، فَإنَّكَ تُنيلُهُ نَفْسَكَ قَبْلَ عَدُوِّكَ، وتُهْلِكُ بِهِ دينَكَ قَبْلَ إيصالِهِ إلى غَيْرِكَ.', 'Beware of surrounding yourself with evil, for you will be affected by it yourself before [harming] your enemy and you will destroy your religion by it before conveying it to others.', 'Ghurar al-Hikam, Evil And The Wicked §1', 'wisdom'),
  ('أكْبَرُ(أكْثَرُ) الشَّـرِّ فِي الاِسْتِخْفافِ بِمُولِمِ عِظَةِ المُشْفِقِ النَّاصِحِ، وَالاِغْتِرارِ بِحَلاوَةِ ثَناءِ الْمادِحِ الْكاشِحِ.', 'The greatest evil is in disparaging the painful advice of the compassionate, sincere adviser and being deceived by the sweetness of the flattery of the malicious praiser.', 'Ghurar al-Hikam, Evil And The Wicked §2', 'wisdom'),
  ('إنَّ فِي الشَّـرِّ لَوَقاحَةً.', 'Verily in evil there is impudence.', 'Ghurar al-Hikam, Evil And The Wicked §3', 'wisdom'),
  ('اَلشَّـرُّ وَقاحَةٌ.', 'Evil is impudence.', 'Ghurar al-Hikam, Evil And The Wicked §4', 'wisdom'),
  ('تَأخيرُ الشَّـرِّ إفادَةُ خَيْر.', 'Delaying of evil is advantageous to good.', 'Ghurar al-Hikam, Evil And The Wicked §5', 'wisdom'),
  ('اَلشَّـرُّ نَدامَةٌ.', 'Evil is [a cause of] regret.', 'Ghurar al-Hikam, Evil And The Wicked §6', 'wisdom'),
  ('اَلشَّـرُّ يَكْبُو بِراكِبِهِ.', 'Evil makes its rider fall.', 'Ghurar al-Hikam, Evil And The Wicked §7', 'wisdom'),
  ('اَلشَّـرُّ أقْبَحُ الأبْوابِ.', 'Evil is the ugliest of gates.', 'Ghurar al-Hikam, Evil And The Wicked §8', 'wisdom'),
  ('اَلشَّـرُّ مَنْطِقٌ وَبيٌّ.', 'Evil is pestilent speech.', 'Ghurar al-Hikam, Evil And The Wicked §9', 'wisdom'),
  ('اَلشَّـرُّ (الشَّـرَهُ) عُنْوانُ الْعَطِبَ.', 'Evil is the symbol of destruction.', 'Ghurar al-Hikam, Evil And The Wicked §10', 'wisdom'),
  ('اَلشَّـرَفُ بِالْهِمَمِ العالِيَةِ لا بِالرِّمَمِ البالِيَةِ.', 'Honor is attained by earnest endeavors not by worn-out bones [of one’s ancestors].', 'Ghurar al-Hikam, Honour And The Honourable §1', 'wisdom'),
  ('أعْظَمُ الشَّـرَفِ التَّواضُعُ.', 'The greatest honour is humility.', 'Ghurar al-Hikam, Honour And The Honourable §2', 'wisdom'),
  ('أفْضَلُ الشَّـرَفِ الأدَبُ.', 'The best honour is good etiquette.', 'Ghurar al-Hikam, Honour And The Honourable §3', 'wisdom'),
  ('أشْـرَفُ الشَّـرَفِ العِلمُ.', 'The most honourable of honours is knowledge.', 'Ghurar al-Hikam, Honour And The Honourable §4', 'wisdom'),
  ('أفْضَلُ الشَّـرَفِ بَذْلُ الإحْسانِ.', 'The best honour is doing good to others.', 'Ghurar al-Hikam, Honour And The Honourable §5', 'wisdom'),
  ('أفْضَلُ الشَّـرَفِ كَفُّ الأذى، وبَذْلُ الإحْسانِ.', 'The best honour is desisting from harming others and doing good to others.', 'Ghurar al-Hikam, Honour And The Honourable §6', 'wisdom'),
  ('اَلشَّـرَفُ مَزِيَّةٌ.', 'Honour is a virtue.', 'Ghurar al-Hikam, Honour And The Honourable §7', 'wisdom'),
  ('الشَّـرَفُ اِصْطِناعُ الْعَشيرَةِ.', 'Honour is doing good to one’s kinsfolk.', 'Ghurar al-Hikam, Honour And The Honourable §8', 'wisdom'),
  ('إنَّما الشَّـرَفُ بِالعَقْلِ والأدَبِ، لابِالْمالِ والْحَسَبِ.', 'Indeed honour is only attained by intellect and etiquette, not because of wealth and lineage.', 'Ghurar al-Hikam, Honour And The Honourable §9', 'wisdom'),
  ('سُلَّمُ الشَّـرَفِ التَّواضُعُ، والسَّخاءُ.', 'The ladder of honour is humility and generosity.', 'Ghurar al-Hikam, Honour And The Honourable §10', 'wisdom'),
  ('وسُئِلَ ـ عليهِ السّلامُ ـ عَنْ مَسافَةِ ما بَيْنَ الْمَشْرِقِ والْمَغْرِبِ؟ فَقالَ: مَسيرُ يَوْم لِلشَّمْْسِ.', 'He (‘a) was asked about the distance between the east and the west so he replied: It is a day’s journey for the sun.', 'Ghurar al-Hikam, East And West §1', 'wisdom'),
  ('أضَرُّ شَيْء الشِّـرْكُ.', 'The most harmful thing is polytheism.', 'Ghurar al-Hikam, Polytheism §1', 'wisdom'),
  ('أيْسَرُ الرِّياءِ الشِّـرْكُ.', 'The smallest amount of showing off is polytheism.', 'Ghurar al-Hikam, Polytheism §2', 'wisdom'),
  ('إنَّ أدْنىَ الرِّياءِ شِرْكٌ.', 'Verily the slightest showing off is polytheism.', 'Ghurar al-Hikam, Polytheism §3', 'wisdom'),
  ('اَلاْشْراكُ كُفْرٌ.', 'Ascribing partners [to Allah] is disbelief.', 'Ghurar al-Hikam, Polytheism §4', 'wisdom'),
  ('آفَةُ الإيمانِ الشِّـرْكُ.', 'The bane of faith is ascribing partners to Allah.', 'Ghurar al-Hikam, Polytheism §5', 'wisdom'),
  ('سَبَبُ الْهَلاكِ الشِّـرْكُ.', 'The cause of destruction is polytheism.', 'Ghurar al-Hikam, Polytheism §6', 'wisdom'),
  ('شارِكُوا الَّذي قَدْ أقْبَلَ عَلَيْهِ الرِّزْقُ، فَإنَّهُ أجْدَرُ بِالْحَظِّ، وأخْلَقُ بِالْغِنى.', 'stablish partnership with the one to whom sustenance has drawn near, for verily he is worthier of success and more befitting of prosperity.', 'Ghurar al-Hikam, Partnership §1', 'wisdom'),
  ('اَلشَّـرَهُ يَشينُ النَّفْسَ، ويُفْسِدُ الدِّينَ، ويُزْري بِالْفُتُوَّةِ.', 'Voraciousness tarnishes the soul, corrupts the religion and debases chivalry.', 'Ghurar al-Hikam, Voraciousness And The Voracious §1', 'wisdom'),
  ('اِحْذَرُوا الشَّـرََهَ فَإنَّهُ خُلْقٌ مُرْدي.', 'Beware of voraciousness, for verily it is a destructive quality.', 'Ghurar al-Hikam, Voraciousness And The Voracious §2', 'wisdom'),
  ('اِحْذَرِ الشَّرَهَ، فَكَمْ مِنْ أكْلَة مَـنَعَتْ أكلات.', 'Beware of voraciousness, for how many a food has prevented numerous other foods [from being consumed]!', 'Ghurar al-Hikam, Voraciousness And The Voracious §3', 'wisdom'),
  ('إيّاكَ والشَّـرَهَ، فَإنَّهُ يُفْسِدُ الْوَرَعَ، ويُدْخِلُ النّارَ.', 'You must refrain from voraciousness, for indeed it corrupts piety and causes one to enter the fire of hell.', 'Ghurar al-Hikam, Voraciousness And The Voracious §4', 'wisdom'),
  ('إيّاكَ والشَّـرَهَ، فَإنَّهُ رَأسُ كُلِّ دَنِيَّة، وأُسُّ كُلِّ رَذيلَة.', 'Refrain from voraciousness, for verily it is the root of every vileness and the foundation of every depravity.', 'Ghurar al-Hikam, Voraciousness And The Voracious §5', 'wisdom'),
  ('إيّاكُمْ ودَناءَةَ الشَّـرَهِ والطَّمَعِ، فَإنَّهُ رَأسُ كُلِّ شَـرّ، ومَزْرَعَةُ الذُّلِّ، وَمُهِينُ النَّفْسِ، ومُتْعِبُ الْجَسَدِ.', 'Beware of the vileness of voraciousness and greed, for verily it is the root of all evil, the plantation of disgrace, the debaser of the soul and the exhauster of the body.', 'Ghurar al-Hikam, Voraciousness And The Voracious §6', 'wisdom'),
  ('اَلشَّرَهُ مَذَلَّةٌ.', 'Voraciousness is [a cause of] ignominy.', 'Ghurar al-Hikam, Voraciousness And The Voracious §7', 'wisdom'),
  ('اَلشَّـرَهُ داعِيَةُ الشَّـرِّ.', 'Voraciousness invites [one] towards evil.', 'Ghurar al-Hikam, Voraciousness And The Voracious §8', 'wisdom'),
  ('اَلشَّـرَهُ أوَّلُ الطَّمَعِ.', 'Voraciousness is the beginning of avarice.', 'Ghurar al-Hikam, Voraciousness And The Voracious §9', 'wisdom'),
  ('اَلشَّـرَهُ سَجيَّةُ الأرْجاسِ.', 'Voraciousness is the trait of the filthy.', 'Ghurar al-Hikam, Voraciousness And The Voracious §10', 'wisdom'),
  ('اِحْذَرُوا عَدُوّاً نَفَذَ فِي الصُّدُورِ خَفِيّاً، ونَفَثَ فِي الآذانِ نَجِيّاً.', 'Be cautious of the enemy that enters the breast stealthily and whispers in the ears secretly.', 'Ghurar al-Hikam, Satan- §1', 'wisdom'),
  ('اِحْذَرُوا عَدُوَّ اللّهِ إبْلِيسَ أنْ يُعْدِيَكُمْ بِدائِهِ أوْ يَسْتَفِزَّكُمْ بِخَيْلِهِ ورَجِلِهِ، فَقَدْ فَوَّقَ لَكُمْ سَهْمَ الْوَعيْدِ ورَماكُمْ مِنْ مَكان قَريب.', 'Beware of the enemy of Allah, Iblīs, that he should not infect you with his disease [of evil] or entice you with his cavalry and his infantry, for he has aimed at you with the arrow of [false] threats and shot at you from close range.', 'Ghurar al-Hikam, Satan- §2', 'wisdom'),
  ('جَعَلَهُمْ مَرمى نَبْلِهِ، ومَوْطِأَ قَدَمِهِ، ومَأْخَذَ يَدِهِ.', 'He (Satan) has made them (the people) the target of his arrows, the ground that he steps on and the handle that he holds.', 'Ghurar al-Hikam, Satan- §3', 'wisdom'),
  ('جَعَلُوا (اِتَّخَذُوا)الشَّيْطانَ لأمْرِهِمْ مالِكاً(مِلاكاً)، وجَعَلَهُمْ (اِتَّخَذَهُمْ) لَهُ أشْراكاً، فَفَرَّخَ في صُدُورِهِمْ، وَدَبَّ ودَرَجَ في حُجُورِهِمْ، فَنَظَرَ بِأعْيُنِهِمْ، ونَطَقَ بِألْسِنَتِهِمْ، ورَكِبَ بِهِمُ الزَّلَلَ، وزَيَّنَ لَهُمُ الْخَطَلَ فِعْلَ مَنْ شَرَكَهُ الشَّيْطانُ في سُلْطانِهِ،وَ نَطَقَ بِالْباطِلِ عَلى لِسانِه.', 'They have taken Satan as the overseer of their affairs and he has made them his partners [in crime], so he hatches [his eggs] in their breasts and creeps and crawls into their laps. He sees with their eyes and speaks with their tongues. He leads them to misdeeds and adorns for them idle talk like the action of one whom Satan has made partner in his domain and speaks falsehood through his tongue.', 'Ghurar al-Hikam, Satan- §4', 'wisdom'),
  ('دَعاكُمْ رَبُّكُمْ سُبْحانَهُ فَنَفَرْتُمْ ووَلَّيْتُمْ، وَدَعاكُمُ الشَّيْطانُ فَاسْتَجَبْتُمْ وَأقْبَلْتُمْ.', 'Your Lord, the Glorified, called you but you turned away and fled, and Satan called you so you responded and drew closer [to him].', 'Ghurar al-Hikam, Satan- §5', 'wisdom'),
  ('صافُّوا الشَّيْطانَ بِالْمُجاهَدَةِ، وأغْلِبُوهُ بِالْمُخالَفَةِ تَزْكُوا أنْفُسُكُمْ، وَتَعْلُوا عِنْدَ اللّهِ دَرَجاتُكُمْ.', 'Stand against Satan through struggle and overpower him by opposition, [by doing this] your souls will be purified and your statuses will be elevated in the sight of Allah.', 'Ghurar al-Hikam, Satan- §6', 'wisdom'),
  ('غُرُورُ الشَّيْطانِ يُسَوِّلُ، ويُطْمِعُ.', 'The deception of Satan allures and entices.', 'Ghurar al-Hikam, Satan- §7', 'wisdom'),
  ('لا تُطيعُوا الأدْعياءَ الَّذينَ شَـرِبْتُمْ بِصَفْوِكُمْ كَدَرَهُمْ وخَلَطْتُمْ بِصِحَّتِكُمْ مَرَضَهُمْ، وأدْخَلْتُمْ في حَقِّكُمْ باطِلَهُمْ.', 'Do not follow the claimants [of Islam] whose dirty water you drink along with your clean one, whose sicknesses you mix with your health and whose falsehood you allow to enter into your rightful matters.', 'Ghurar al-Hikam, Satan- §8', 'wisdom'),
  ('لا تَجْعَلَنَّ لِلشَّيْطانِ في عَمَلِكَ نَصيباً، وَلا عَلى نَفْسِكَ سَبيلاً.', 'Never allot a portion for Satan in your actions and do not give him access to your soul.', 'Ghurar al-Hikam, Satan- §9', 'wisdom'),
  ('كُنْ مَشْغُولاً بِما أنْتَ عَنْهُ مَسْؤُلٌ.', 'Occupy yourself with that which you are answerable for.', 'Ghurar al-Hikam, Being Occupied- §1', 'wisdom'),
  ('مَنِ اشْتَغَلَ بِغَيْرِ المُهِمِّ ضَيَّعَ الأهَمَّ.', 'One who is occupied by the unimportant loses that which is more important.', 'Ghurar al-Hikam, Being Occupied- §2', 'wisdom'),
  ('شُغِلَ مَنِ الْجَـنَّةُ والنّارُ أمامَهُ.', 'He who puts Paradise and hell in front of him is [always] occupied.', 'Ghurar al-Hikam, Being Occupied- §3', 'wisdom'),
  ('شُغِلَ مَنْ كانَتِ النَّجاةُ ومَرْضاتُ اللّهِ مَرامَهُ.', 'He one whose goal is salvation and attaining the pleasure of Allah is [always] occupied.', 'Ghurar al-Hikam, Being Occupied- §4', 'wisdom'),
  ('الشَّفيعُ جَناحُ الطّالِبِ.', 'The intercessor is the wing of the seeker [which helps him attain what he seeks].', 'Ghurar al-Hikam, The Intercessor and the Interceder- §1', 'wisdom'),
  ('شافِعُ الْمُجْرِمِ خُضُوعُهُ بِالْمَعْذِرَةِ.', 'The interceder of a criminal is his humility in seeking pardon.', 'Ghurar al-Hikam, The Intercessor and the Interceder- §2', 'wisdom'),
  ('شافِعُ الْمُذْنِبِ إقْرارُهُ، وتَوْبَتُهُ اِعْتِذارُهُ.', 'The interceder of a sinner is his admission (of guilt), his repentance and his apology.', 'Ghurar al-Hikam, The Intercessor and the Interceder- §3', 'wisdom'),
  ('شافِعُ الْخَلْقِ العَمَلُ بِالْحَقِّ، ولُزُومُ الصِّدْقِ.', 'The interceder of mankind [on the Day of Reckoning] acting upon the right and adhering to the truth.', 'Ghurar al-Hikam, The Intercessor and the Interceder- §4', 'wisdom'),
  ('مَعَ الشِّقاقِ تَكُونُ النَّبْوَةُ.', 'With dissension there is aversion.', 'Ghurar al-Hikam, Dissension- §1', 'wisdom'),
  ('كُلُّ شَقاءِ إلى رَخاء.', 'Every wretchedness is [moving] towards ease.', 'Ghurar al-Hikam, Wretchedness- §1', 'wisdom'),
  ('مِنَ الشَّقاءِ اِحْتِقابُ الحَرامِ.', 'Collecting the [wealth that is] forbidden is part of wretchedness.', 'Ghurar al-Hikam, Wretchedness- §2', 'wisdom'),
  ('مِنَ الشَّقاءِ إفْسادُ المَعادِ.', 'Corrupting one’s Hereafter is from wretchedness.', 'Ghurar al-Hikam, Wretchedness- §3', 'wisdom'),
  ('مِنْ عَلامَةِ الشَّقاءِ غِشُّ الصَّديقِ.', 'One of the signs of wretchedness is cheating one’s friend.', 'Ghurar al-Hikam, Wretchedness- §4', 'wisdom'),
  ('مِنْ عَلاماتِ الشَّقاءِ الإسائَةُ إلَى الأخْيارِ.', 'One of the signs of wretchedness is offending the virtuous.', 'Ghurar al-Hikam, Wretchedness- §5', 'wisdom'),
  ('مِنْ شَقاءِ المَرْءِ أنْ يُفْسِدَ الشَّكُ يَقينَهُ.', 'It is from the wretchedness of a person for his certitude to get corrupted by doubt.', 'Ghurar al-Hikam, Wretchedness- §6', 'wisdom'),
  ('مِنَ الشَّقاءِ أنْ يَصُونَ المَرْءُ دُنْياهُ بِدينِهِ.', 'It is from wretchedness for a person to safeguard his world at the expense of his religion.', 'Ghurar al-Hikam, Wretchedness- §7', 'wisdom'),
  ('مِنَ الشَّقاءِ فَسادُ النِّيَّةِ.', 'Corruption of intention is from wretchedness.', 'Ghurar al-Hikam, Wretchedness- §8', 'wisdom'),
  ('إنَّ مِنَ الشَّقاءِ إفْسادَ المَعادِ.', 'Verily from wretchedness is corruption of one’s Hereafter.', 'Ghurar al-Hikam, Wretchedness- §9', 'wisdom'),
  ('اَلشقيُّ مَنِ اغْتَرَّ بِحالِهِ وانْخَدَعَ لِغُرُورِ آمالِهِ.', 'The wretched is one who is proud of his condition and is beguiled by the deception of his hopes.', 'Ghurar al-Hikam, The Wretched §1', 'wisdom'),
  ('أشْقاكُمْ أحْرَصُكُمْ.', 'The most wretched among you are the most greedy among you.', 'Ghurar al-Hikam, The Wretched §2', 'wisdom'),
  ('أشْقَى النّاسِ مَنْ باعَ دينَهُ بِدُنْيا غَيْرِهِ.', 'The most wretched of [all] people is one who sells his religion for someone else’s worldly gain.', 'Ghurar al-Hikam, The Wretched §3', 'wisdom'),
  ('كَمْ مِنْ شَقِيّ حَضَرَهُ أجَلُهُ وهُوَ مُجِدٌّ فِي الطَّلَبِ.', 'How many a wretched person has been visited by his death while he is striving to acquire [worldly gain].', 'Ghurar al-Hikam, The Wretched §4', 'wisdom'),
  ('اَلشُّكْرُ أحَدُ الجَزائَيْن.', 'Gratitude is one of the two rewards.', 'Ghurar al-Hikam, Gratitude And The Grateful §1', 'gratitude'),
  ('اَلشُّكْرُ عَلَى النِّعْمَةِ جَزاءٌ لِماضِيها، واجْتِلابٌ لآتيها.', 'Gratitude for blessings is a recompense for its past and a source of its [increase in the] future.', 'Ghurar al-Hikam, Gratitude And The Grateful §2', 'gratitude'),
  ('اَلشُّكْرُ أعْظَمُ قَدْراً مِنَ المَعْرُوفِ، لأنَّ الشُّكْرَ يَبْقى والمََعْرُوفَ يَفْنى.', 'Gratitude has greater value than a good action because the gratitude lasts while the good action comes to an end.', 'Ghurar al-Hikam, Gratitude And The Grateful §3', 'gratitude'),
  ('أُشْكُرْ تَزِدْ.', 'Be grateful and you will increase.', 'Ghurar al-Hikam, Gratitude And The Grateful §4', 'gratitude'),
  ('اِسْتَدِمِ الشُّكْرَ، تَدُمْ عَلَيْكَ النِّعْمَةُ.', 'Continue being grateful and the blessing upon you will continue.', 'Ghurar al-Hikam, Gratitude And The Grateful §5', 'gratitude'),
  ('اِشْتَغِلْ بِشُكْرِ النِّعْمَةِ عَنِ التَّطَرُّبِ بِها.', 'Occupy yourself in being grateful for the blessing rather than being delighted by it.', 'Ghurar al-Hikam, Gratitude And The Grateful §6', 'gratitude'),
  ('أكْثِرِ النَّظَرَ إلى مَنْ فُضِّلْتَ عَلَيْهِ، فَإنَّ ذلِكَ مِنْ أبْوابِ الشُّكرِ.', 'Look frequently at those over whom you have been given superiority, for verily this is one of the gates [and means] of gratitude.', 'Ghurar al-Hikam, Gratitude And The Grateful §7', 'gratitude'),
  ('أُشْكُرْ مَنْ أنْعَمَ عَلَيْكَ، وأنْعِمْ على مَنْ شَكَرَكَ، فَإنَّهُ لازَوالَ لِلنِّعْمَةِ إذا شُكِرَتْ، ولابَقاءَ لَها إذا كُفِرَتْ.', 'Be grateful to the one who favours you and favour the one who is grateful to you, for indeed there is no end to favours when they are appreciated and there is no continuation for them when they are unappreciated.', 'Ghurar al-Hikam, Gratitude And The Grateful §8', 'gratitude'),
  ('اِجْعَلْ جَزاءَ النِّعْمَةِ عَلَيْكَ الاَحْسانَ إلى مَنْ أساءَ إلَيْكَ.', 'Let the recompense for the blessing which has come upon you be the showing of goodness to one who wrongs you.', 'Ghurar al-Hikam, Gratitude And The Grateful §9', 'gratitude'),
  ('أحْسِنُوا جُوارَ نِعَمِ الدّينِ والدُّنيا بِالشُّكْرِ لِمَنْ دَلَّ (دَلَّكُم)عَلَيْها.', 'Be good neighbours to the blessings of religion and this world by showing gratitude to the one who guides you to them.', 'Ghurar al-Hikam, Gratitude And The Grateful §10', 'gratitude'),
  ('اَلشَكُ يُفْسِدُ اليَقينَ ويُبْطِلُ الدِّينَ.', 'Doubt corrupts certitude and nullifies faith.', 'Ghurar al-Hikam, Doubt and Misgiving- §1', 'wisdom'),
  ('إيّاكَ والشَّكَّ، فَإنَّهُ يُفْسِدُ الدِّينَ، ويُبْطِلُ اليَقينَ.', 'Be wary of doubt, for verily it corrupts religion and nullifies certitude.', 'Ghurar al-Hikam, Doubt and Misgiving- §2', 'wisdom'),
  ('أهْلَكُ شَيْء اَلشَّكُّ والاِرْتيابُ، وأمْلَكُ شَيْء الوَرَعُ وَالاِجْتِنابُ.', 'The most destructive thing is doubt and uncertainty, and the most constructive thing is piety and keeping aloof from sin.', 'Ghurar al-Hikam, Doubt and Misgiving- §3', 'wisdom'),
  ('اَلشَّكُّ اِرْتيابٌ.', 'Doubt is misgiving.', 'Ghurar al-Hikam, Doubt and Misgiving- §4', 'wisdom'),
  ('اَلشَّكُّ كُفْرٌ.', 'Doubt [in the existence of God] is disbelief.', 'Ghurar al-Hikam, Doubt and Misgiving- §5', 'wisdom'),
  ('اَلشَّكُّ يُفْسِدُ الدِّينَ.', 'Doubt corrupts religion.', 'Ghurar al-Hikam, Doubt and Misgiving- §6', 'wisdom'),
  ('اَلشَّكُّ يُحْبِطُ الإيمانَ.', 'Doubt nullifies faith.', 'Ghurar al-Hikam, Doubt and Misgiving- §7', 'wisdom'),
  ('اَلشَّكُّ ثَمَرَةُ الجَهْلِ.', 'Doubt is the fruit of ignorance.', 'Ghurar al-Hikam, Doubt and Misgiving- §8', 'wisdom'),
  ('اَلاِرْتيابُ يُوجِبُ الشِّرْكَ.', 'Doubt leads to polytheism.', 'Ghurar al-Hikam, Doubt and Misgiving- §9', 'wisdom'),
  ('اَلشَّكُّ يُطْفِيُ نُورَ القَلْبِ.', 'Doubt puts out the light of the heart.', 'Ghurar al-Hikam, Doubt and Misgiving- §10', 'wisdom'),
  ('مَنْ شَكى ضُـرَّهُ إلى غَيْـرِ مُؤْمِن، فَكَأنَّما شَكىَ اللّهَسُبْحانَهُ.', 'Whoever complains of his distress to [anyone] other than a believer, it is as if he has complained against Allah, the Glorified.', 'Ghurar al-Hikam, Complaining Of Distress §1', 'wisdom'),
  ('مَنْ شَكى ضُـرَّهُ إلى مُؤْمِن، فَكَأنَّما شَكى إلَى اللّهِ سُبْحانَهُ.', 'Whoever complains of his distress to a believer, it is as if he has complained to Allah, the Glorified.', 'Ghurar al-Hikam, Complaining Of Distress §2', 'wisdom'),
  ('مَنْ شَمِتَ بِزَلَّةِ غَيْرِهِ، شَمِتَ غَيْـرُهُ بِزَلَّتِهِ.', 'ne who is gleeful of the mistakes made by others, [then] others will be gleeful of his mistakes.', 'Ghurar al-Hikam, Schadenfreude §1', 'wisdom'),
  ('اَلشِّرْكَةُ فِي الرَّأْيِ تُؤَدّي إلَى الصَّوابِ.', 'Participating in deliberation leads to the appropriate decision.', 'Ghurar al-Hikam, Consultation And Deliberation §1', 'wisdom'),
  ('اِسْتَشِرْ أعْداءَكَ تَعْرِفْ مِنْ رَأْيِهِمْ مِقْدارَ عَداوَتِهِمْ، ومَواضِعَ مَقاصِدِهِمْ.', 'Consult your enemies; you will know from their opinion how much enmity they have [for you] and what their objectives are.', 'Ghurar al-Hikam, Consultation And Deliberation §2', 'wisdom'),
  ('اِسْتَشِرْ عَدُوَّكَ العاقِلَ، واحْذَرْ رَأْيَ صَديقِكَ الجاهِلَ.', 'Consult your intelligent enemy and be wary of the opinion of your ignorant friend.', 'Ghurar al-Hikam, Consultation And Deliberation §3', 'wisdom'),
  ('اِضْرِبُوا بَعْضَ الرَّأْيِ بِبَعْض يَتَوَلَّدْ مِنْهُ الصَّوابُ.', 'Compare some opinions with others, from this the right course of action will come to light.', 'Ghurar al-Hikam, Consultation And Deliberation §4', 'wisdom'),
  ('اِتَّهِمُوا عُقُولَكُمْ فَإنَّهُ مِنَ الثِّقَةِ بِها يَكُونُ الخَطاءُ.', 'Suspect your intellects, for indeed it is from trusting in them that mistakes are made.', 'Ghurar al-Hikam, Consultation And Deliberation §5', 'wisdom'),
  ('اَلمُشاوَرَةُ راحَةٌ لَكَ وتَعَبٌ لِغَيْرِكَ.', 'Consultation is [a means of] ease for you and a difficulty for others.', 'Ghurar al-Hikam, Consultation And Deliberation §6', 'wisdom'),
  ('أفْضَلُ مَنْ شاوَرْتَ ذُو التَّجارِبِ، وَشَـرُّ مَنْ قارَنْتَ ذُو المَعائِبِ.', 'The best person whom you can consult is the one with [abundant] experience and the worst person whom you can associate with is the one with [numerous] faults.', 'Ghurar al-Hikam, Consultation And Deliberation §7', 'wisdom'),
  ('اَلمُشاوَرَةُ اِسْتِظْهارٌ.', 'Consultation is [a means of] seeking [assistance and] support.', 'Ghurar al-Hikam, Consultation And Deliberation §8', 'wisdom'),
  ('اَلاِسْتِشارَةُ عَيْنُ الهِدايَةِ.', 'Seeking advice is the essence [and source] of guidance.', 'Ghurar al-Hikam, Consultation And Deliberation §9', 'wisdom'),
  ('اَلمُسْتَشيرُ مُتَحَصِّنٌ مِنَ السَّقَطِ.', 'The one who seeks advice is protected from failure.', 'Ghurar al-Hikam, Consultation And Deliberation §10', 'wisdom'),
  ('اَلشَّوْقُ شيمَةُ المُوقِنينَ.', 'Longing [for Allah and the Hereafter] is from the qualities of those who have certitude.', 'Ghurar al-Hikam, Eagerness and Longing- §1', 'wisdom'),
  ('اَلشَّوْقُ خُلْصانُ العارِفينَ.', 'Longing [for Allah] is the intimate companion of the Gnostics.', 'Ghurar al-Hikam, Eagerness and Longing- §2', 'wisdom'),
  ('مَنِ اشْتاقَ سَلا.', 'One who longs [for Allah] forgets [this world].', 'Ghurar al-Hikam, Eagerness and Longing- §3', 'wisdom'),
  ('مَنِ اشْتاقَ أدْلَجَ.', 'One who longs [for Allah] sets out [towards him] at nightfall.', 'Ghurar al-Hikam, Eagerness and Longing- §4', 'wisdom'),
  ('الشَهْوَةُ أحَدُ المُغْوِيَيْنِ.', 'Lust is one of the two causes of deviation.', 'Ghurar al-Hikam, Lust- §1', 'wisdom'),
  ('اَلشَّهَواتُ أعْلالٌ قاتِلاتٌ، وأفْضَلُ دَوائِها اِقْتِناءُ الصَّبْرِ عَنْها.', 'Lustful desires are fatal illnesses, and the best cure for them is acquiring patience against them.', 'Ghurar al-Hikam, Lust- §2', 'wisdom'),
  ('اَلشَّهَواتُ مَصائِدُ الشَّيْطانِ.', 'Lustful desires are the snares of Satan.', 'Ghurar al-Hikam, Lust- §3', 'wisdom'),
  ('اِغْلَبِ الشَّهْوَةَ، تَكْمُلْ لَكَ الحِكْمَةُ.', 'Overcome [your] lust, [and] your wisdom will be perfected.', 'Ghurar al-Hikam, Lust- §4', 'wisdom'),
  ('أُهْجُرُوا الشَّهَواتِ، فَإنَّها تَقُودُكُمْ إلى رُكُوبِ الذُّنُوبِ، والتَّهَجُّمِ عَلَى السَيِّئاتِ.', 'Turn your back on lustful desires, for indeed they drive you to perform sinful acts and to fall upon evil deeds.', 'Ghurar al-Hikam, Lust- §5', 'wisdom'),
  ('اَلشَّهَواتُ آفاتٌ قاتِلاتٌ، وخَيْرُ دَوائِها اِقْتِناءُ الصَّبْرِ عَنْها.', 'Lustful desires are fatal diseases, and the best cure for them is acquiring patience against them.', 'Ghurar al-Hikam, Lust- §6', 'wisdom'),
  ('إيّاكُمْ وتَحَكُّمَ الشَّهَواتِ عَلَيْكُمْ، فَإنَّ عاجِلَها ذَميمٌ، وآجِلَها وَخيمٌ.', 'Beware of allowing lustful desires to dominate you, for indeed its immediate result is dispraised and future consequence is detrimental.', 'Ghurar al-Hikam, Lust- §7', 'wisdom'),
  ('إيّاكُمْ وغَلَبَةَ الشَّهَواتِ عَلى قُلُوبِكُمْ، فَإنَّ بِدايَتَها مَلَكَةٌ، ونِهايَتَها هَلَكَةٌ.', 'Beware of letting lustful desires overpower you hearts, for indeed its beginning is bondage and its end is destruction.', 'Ghurar al-Hikam, Lust- §8', 'wisdom'),
  ('أوَّلُ الشَّهْوَةِ طَرَبٌ، وآخِرُها عَطَبٌ.', 'The beginning of lust is pleasure and its end is harm.', 'Ghurar al-Hikam, Lust- §9', 'wisdom'),
  ('اَلشَّهْوَةُ تُغْري.', 'Lust entices.', 'Ghurar al-Hikam, Lust- §10', 'wisdom'),
  ('مَنْ ماتَ عَلى فِراشِهِ وهُوَ على مَعْرِفَةِ حَقِّ رَبِّهِ ورَسُولِهِ وحَقِّ أهْلِ بَيْتِهِ ماتَ شَهيداً، ووَقَعَ أجْرُهُ عَلَى اللّهِ سُبْحانَهُ واسْتَوْجَبَ ثَوابَ ما نَوى مِنْ صالِحِ عَمَلِهِ، وقامَتْ نِيَّتُهُ مَقامَ إصْلاتِهِ سَيْفَهُ (بِسَيْفِهِ)، فَإنَّ لِكُلِّ شَْيء أجَلاً لايَعْدُوهُ.', 'One who dies on his bed while he is cognizant of the rights of his Lord, His Prophet and the right of his household, has died a martyr and his reward rests with Allah, the Glorified. He is also eligible for the recompense of the good acts he intended to do, as his intention takes the place of drawing his sword [in battle]. Indeed, for everything there is a [limited] term that it cannot go beyond.', 'Ghurar al-Hikam, The Martyr- §1', 'wisdom'),
  ('نَسْأَلُ اللّهَ سُبْحانَهُ مَنازِلَ الشُّهَداءِ، ومُعايَشَةَ السُّعَداءِ، ومُرافَقَةَ الأنْبِياءِ والأبْرارِ.', 'We ask Allah, the Glorified, for [our inclusion in] the ranks of the martyrs, the fellowship of the felicitous and the company of the Prophets and the virtuous ones.', 'Ghurar al-Hikam, The Martyr- §2', 'wisdom'),
  ('والشَّهادَةَ اِسْتِظْهاراً عَلَى المُجاحَداتِ.', 'And testimony [has been prescribed] as a means of overcoming denials.', 'Ghurar al-Hikam, Testimony- §1', 'wisdom'),
  ('مَنْ شَهِدَ لَكَ بِالباطِلِ شَهِدَ عَلَيْكَ بِمِثْلِهِ.', 'One who gives false testimony for you will give a similar testimony against you.', 'Ghurar al-Hikam, Testimony- §2', 'wisdom'),
  ('لاخَيْرَ في شَهادَةِ خائِن.', 'There is no good in the testimony of the treacherous.', 'Ghurar al-Hikam, Testimony- §3', 'wisdom'),
  ('حُسْنُ الشُّهْرَةِ حِصْنُ القُدْرَةِ.', 'Good renown is a fortification of power.', 'Ghurar al-Hikam, Fame and renown- §1', 'wisdom'),
  ('حُبُّ النَّباهَةِ رَأْسُ كُلِّ بَلِيَّة.', 'Love of fame is the cornerstone of every affliction.', 'Ghurar al-Hikam, Fame and renown- §2', 'wisdom'),
  ('كَفى بِالشَّيْبِ نَذيراً.', 'The grey hair of old age is enough of a warner.', 'Ghurar al-Hikam, Grey Hair of Old Age- §1', 'wisdom'),
  ('كَفى بِالشَّيْبِ ناعِياً.', 'The grey hair of old age is enough of an announcer [of impending death].', 'Ghurar al-Hikam, Grey Hair of Old Age- §2', 'wisdom'),
  ('غَيِّـرُوا الشَّيْبَ، ولاتَشَبَّهُوا بِاليَهُودِ.', 'Change your grey hair [by dyeing it] and do not resemble the Jews.', 'Ghurar al-Hikam, Grey Hair of Old Age- §3', 'wisdom'),
  ('إذَا ابْيَضَّ أسْوَدُكَ ماتَ أطْيَبُكَ.', 'When you’re black [hair] becomes white, your best [part of life] has passed away.', 'Ghurar al-Hikam, Grey Hair of Old Age- §4', 'wisdom'),
  ('اَلشَّيْبُ آخِرُ مَواعيدِ الفَناءِ.', 'Grey hair [of old age] is the last of the promises of annihilation.', 'Ghurar al-Hikam, Grey Hair of Old Age- §5', 'wisdom'),
  ('إنَّ أهْلَ الجَنَّةِ لَيَتَراؤُنَ مَنازِلَ شيعَتِنا، كَما يَتَراءَى الرَّجُلُ مِنْكُمْ الكَواكِبَ في أُفُقِ السَّماءِ.', 'Verily the People of Paradise will look at the stations of our followers just as a person among you looks at the celestial bodies in the sky.', 'Ghurar al-Hikam, The Followers (Shi’a)- §1', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ أطْلَعَ إلَى الأرضِ، فاخْتارَ لَنا شيعَةً يَنْصُرُونَنا، وَيَفْرَحُونَ لِفَرَحِنا، ويَحْزَنُونَ لِحُزْنِنا، ويَبْذُلُونَ أنْفُسَهُمْ وأمْوالَهُمْ فينا أُولئكَ مِنّا وإلَيْنا.', 'Verily Allah, the Glorified, checked the earth and chose for us followers who would help us, would be gladdened by our joy and saddened by our sadness, and would spend from their persons and their possessions in our way – these are the ones who are from us and shall rejoin us [in the Hereafter].', 'Ghurar al-Hikam, The Followers (Shi’a)- §2', 'wisdom'),
  ('شيعَتُنا كَالنَّحْلِ لَوْ عَرَفُوا مافي جَوْفِها لأَكَلُوها.', 'Our follower is like the bee. If they knew what was in its abdomen, they would surely have eaten it.', 'Ghurar al-Hikam, The Followers (Shi’a)- §3', 'wisdom'),
  ('شيعَتُنا كَالأُتْرُجَّةِ طَيِّبٌ رِيحُها، حَسَنٌ ظاهِرُها وباطِنُها.', 'Our follower is like the citron, its smell is fragrant and [both] its outward and inward are beautiful.', 'Ghurar al-Hikam, The Followers (Shi’a)- §4', 'wisdom'),
  ('اَلصَّبْرُ أوَّلُ لَوازِمِ الإتْقانِ (الإيْقانِ).', 'Patience is the first prerequisite of proficiency (or certitude).', 'Ghurar al-Hikam, Patience and the patient- §1', 'patience'),
  ('اَلصَّبْرُ عَلَى المُصِيْبَةِ يُجْزِلُ المَثُوبَةَ.', 'Patience in times of hardship makes reward abundant.', 'Ghurar al-Hikam, Patience and the patient- §2', 'patience'),
  ('اَلصَّبْرُ أحَدُ الظَّفَرَيْنِ.', 'Patience is one of the two triumphs.', 'Ghurar al-Hikam, Patience and the patient- §3', 'patience'),
  ('اَلصَّبْرُ عَلَى النَّوائِبِ يُنيلُ شَرَفَ المَراتِبِ (المَطالِبِ).', 'Patience in the face of calamities makes one attain honourable ranks.', 'Ghurar al-Hikam, Patience and the patient- §4', 'patience'),
  ('اَلصَّبْرُ عَلى طاعَةِ اللّهِ أهْوَنُ مِنَ الصَّبْرِ عَلى عُقُوبَتِهِ.', 'Patience in the obedience to Allah is easier than patience in the face of His chastisement.', 'Ghurar al-Hikam, Patience and the patient- §5', 'patience'),
  ('اَلصَّبْرُ عَلَى البَلاءِ أفْضَلُ مِنَ العافِيَةِ فِي الرَّخاءِ.', 'Patience in affliction is better than wellbeing in [times of] comfort.', 'Ghurar al-Hikam, Patience and the patient- §6', 'patience'),
  ('اَلصَّبْرُ أفْضَلُ سَجِيَّة، والعِلْمُ أشْرَفُ حِلْيَة وعَطِيَّة.', 'Patience is the best trait and knowledge is the most honourable embellishment and gift.', 'Ghurar al-Hikam, Patience and the patient- §7', 'patience'),
  ('اَلصَّبْرُ أنْ يَحْتَمِلَ الرَّجُلُ ما يَنُوبُهُ ويَكْظِمَ ما يُغْضِبُهُ.', 'Patience is for a person to bear that which befalls him and to suppress [his anger with] that which enrages him.', 'Ghurar al-Hikam, Patience and the patient- §8', 'patience'),
  ('اَلصَّبْرُ صبْرانِ: صَبْرٌ عَلى ما تَكْرَهُ، وصَبْرٌ عَمّا تُحِبُّ.', 'Patience is of two types: enduring what you hate and abstaining from what you love.', 'Ghurar al-Hikam, Patience and the patient- §9', 'patience'),
  ('اَلصَّبْرُ أحْسَنُ حُلَلِ الإيمانِ، وأشْرَفُ خَلائِقِ الإنْسانِ.', 'Patience is the best vestment of faith and the most honourable of human qualities.', 'Ghurar al-Hikam, Patience and the patient- §10', 'patience'),
  ('عَلِّمُوا صِبْيانَـكُمْ الصَّلاةَ،وَ خُذُوهُمْ بِها إذا بَلَغُوا الحُلُمَ.', 'Teach your young children [how to perform the ritual] prayer and make them accountable for it when they reach puberty.', 'Ghurar al-Hikam, Young Children- §1', 'family'),
  ('اَلصِحَّةُ أهْنَأُ اللَّذَّتَيْنِ.', 'Good health is the more salubrious of the two delights.', 'Ghurar al-Hikam, Good Health and the Healthy- §1', 'character'),
  ('اَلصِّحَّةُ أفْضَلُ النِّـعَمِ.', 'Good health is the best blessing.', 'Ghurar al-Hikam, Good Health and the Healthy- §2', 'character'),
  ('بِالصِّحَّةِ تُسْتَكْمَلُ اللَّذَّةُ.', 'With good health, enjoyment becomes complete.', 'Ghurar al-Hikam, Good Health and the Healthy- §3', 'character'),
  ('بِصِحَّةِ المِزاجِ تُوجَدُ لَذَّةُ الطَّعْمِ.', 'With good health, there is delight in the taste [of food].', 'Ghurar al-Hikam, Good Health and the Healthy- §4', 'character'),
  ('زَكاةُ الصِّحَّةِ اَلسَّعْيُ في طاعَةِ اللّهِ.', 'The alms-tax of good health is striving in the obedience of Allah.', 'Ghurar al-Hikam, Good Health and the Healthy- §5', 'character'),
  ('هَلْ يَنْتَظِرُ أهْلُ غَضاضَةِ الصِّحَّةِ إلاّ نَوازِلَ السَّقَمِ.', 'Are the people who are enjoying the vitality of good health awaiting anything other than the afflictions of illness?!', 'Ghurar al-Hikam, Good Health and the Healthy- §6', 'character'),
  ('لاتَجْتَمِعُ الصِّحَّةُ والنَّهَمُ.', 'Good health and gluttony do not go together.', 'Ghurar al-Hikam, Good Health and the Healthy- §7', 'character'),
  ('لاتُنالُ الصِّحَّةُ إلاّ بِالْحِمْيَةِ.', 'Good health is not attained except through a good diet.', 'Ghurar al-Hikam, Good Health and the Healthy- §8', 'character'),
  ('اَلصَّدْرُ رَقيبُ البَدَنِ.', 'he chest is the guard of the body.', 'Ghurar al-Hikam, The Chest- §1', 'wisdom'),
  ('الصَّدَقَةُ أعْظَمُ الرِّبْحَيْنِ.', 'harity is the greater of the two gains.', 'Ghurar al-Hikam, Charities- §1', 'wisdom'),
  ('اَلصَّدَقَةُ أفْضَلُ الذُّخْرَينِ.', 'Charity is the better of the two reserves.', 'Ghurar al-Hikam, Charities- §2', 'wisdom'),
  ('اَلصَّدَقَةُ تَسْتَنْزِلُ الرَّحْمَةَ.', 'Charity brings down mercy.', 'Ghurar al-Hikam, Charities- §3', 'wisdom'),
  ('اَلصَّدَقَةُ تَسْتَدْفِعُ البَلاءَ والنِّقْمَةَ.', 'Charity repels tribulation and calamity.', 'Ghurar al-Hikam, Charities- §4', 'wisdom'),
  ('إنَّكُمْ إلى إنْفاقِ مَا اكْتَسَبْتُمْ أحْوَجُ مِنْكُمْ إلَى اكْتِسابِ ما تَجْمَعُونَ.', 'Verily you are more in need of spending [in charity] that which you earn than [you are of] earning that which you amass.', 'Ghurar al-Hikam, Charities- §5', 'wisdom'),
  ('إذا أَمْلَقْتُمْ فَتاجِرُوا اللّهَ بِالصَّدَقَةِ.', 'When you become penniless then do business with Allah through charity.', 'Ghurar al-Hikam, Charities- §6', 'wisdom'),
  ('بِالصَّدَقَةِ تُفْسَخُ (تَفْسُحُ) الآجالُ.', 'Through charity, death gets deferred.', 'Ghurar al-Hikam, Charities- §7', 'wisdom'),
  ('بَـرَكَةُ المالِ فِي الصَّدَقَةِ.', 'The blessing of wealth is in charity.', 'Ghurar al-Hikam, Charities- §8', 'wisdom'),
  ('حَصِّنُوا أنْفُسَكُمْ بِالصَّدَقَةِ.', 'Safeguard yourselves through charity.', 'Ghurar al-Hikam, Charities- §9', 'wisdom'),
  ('خَيْرُ الصَّدَقَةِ أخْفاها.', 'The best charity is that which is given most secretly.', 'Ghurar al-Hikam, Charities- §10', 'wisdom'),
  ('اَلصِّدْقُ أقْوى دَعائِم الإيمانِ.', 'Truthfulness is the strongest column of faith.', 'Ghurar al-Hikam, Truthfulness- §1', 'justice'),
  ('اَلصِّدْقُ عِمادُ الإسْلامِ ودَعامَةُ الإيمانِ.', 'Truthfulness is the pillar of Islam and the column of faith.', 'Ghurar al-Hikam, Truthfulness- §2', 'justice'),
  ('اَلصِّدْقُ رَأسُ الإيمانِ، وزَيْنُ الإنْسانِ.', 'Truthfulness is the cornerstone of faith and the adornment of the human being.', 'Ghurar al-Hikam, Truthfulness- §3', 'justice'),
  ('اَلصِّدْقُ جَمالُ الإنْسانِ، ودَعامَةُ الإيمانِ.', 'Truthfulness is the beauty of a human being and the column of faith.', 'Ghurar al-Hikam, Truthfulness- §4', 'justice'),
  ('أُصْدُقْ تُنْجِحْ.', 'Be truthful and you will be successful.', 'Ghurar al-Hikam, Truthfulness- §5', 'justice'),
  ('اِلْزَمِ الصِّدْقَ والأمانَةَ، فَإنَّهُما سَجِيَّةُ الأبْرارِ.', 'Adopt truthfulness and trustworthiness for indeed these are the two traits of the righteous.', 'Ghurar al-Hikam, Truthfulness- §6', 'justice'),
  ('اِلْزَمِ الصِّدْقَ وإنْ خِفْتَ ضُرَّهُ فَإنَّهُ خَيْرٌ لَكَ مِنَ الكِذْبِ المَرْجُوِّ نَفْعُهُ.', 'Espouse truthfulness even if you fear harm may come of it, for indeed this is better for you than the lying from which benefit is expected.', 'Ghurar al-Hikam, Truthfulness- §7', 'justice'),
  ('اِغْتَنِمِ الصِّدْقَ في كُلِّ مَوْطِن تَغْنَمْ،وَ اجْتَنِبِ الشَّـرَّ والكِذْبَ تَسْلَمْ.', 'Seek benefit from truthfulness in every situation and you will gain; keep away from evil and dishonesty, and you will remain safe.', 'Ghurar al-Hikam, Truthfulness- §8', 'justice'),
  ('أُصْدُقُوا في أقْوالِكُمْ، وأخْلِصُوا في أعْمالِكُمْ، وتَزَكُّوا بِالوَرَعِ.', 'Be truthful in your words, be sincere in your actions and purify yourselves with piety.', 'Ghurar al-Hikam, Truthfulness- §9', 'justice'),
  ('أجَلُّ شَيْء اَلصِّدْقُ.', 'The most sublime thing is truthfulness.', 'Ghurar al-Hikam, Truthfulness- §10', 'justice'),
  ('إنَّ الصّادِقَ لَمُكْرَمٌ جَليلٌ، وإنَّ الكاذِبَ لَمُهانٌ ذَليلٌ.', 'Verily the truthful one is honoured and dignified, and indeed the liar is abased and humiliated.', 'Ghurar al-Hikam, The Truthful- §1', 'justice'),
  ('اَلصّادِقُ مُكْرَمٌ جَليلٌ.', 'The truthful one is honoured and dignified.', 'Ghurar al-Hikam, The Truthful- §2', 'justice'),
  ('اَلصّادِقُ عَلى شَرَفِ مَنْجاة وَكَرامَة.', 'The truthful one is on the highest rank of salvation and honour.', 'Ghurar al-Hikam, The Truthful- §3', 'justice'),
  ('رُبَّ صادِق مِنْ خَبَرِ الدُّنيا عِنْدَكَ مُكَذَّبٌ.', 'Many a truthful one who informs you about [a matter of] this world may be deemed a liar by you.', 'Ghurar al-Hikam, The Truthful- §4', 'justice'),
  ('كُنْ صادِقاً تَـكُنْ وَفيّاً.', 'Be truthful and you will become loyal.', 'Ghurar al-Hikam, The Truthful- §5', 'justice'),
  ('مَنْ صَدَقَ أصْلَحَ دِيانَتـَهُ.', 'One who is truthful improves his religiousness.', 'Ghurar al-Hikam, The Truthful- §6', 'justice'),
  ('مَنْ كانَ صَدُوقاً لَمْ يَعْدِمِ الكَرامَةَ.', 'One who is always truthful will not be deprived of honour.', 'Ghurar al-Hikam, The Truthful- §7', 'justice'),
  ('مَنْ صَدَقَتْ لَهْجَتُهُ قَوِيَتْ حُجَّتُهُ.', 'One whose language is truthful, his proof becomes strong.', 'Ghurar al-Hikam, The Truthful- §8', 'justice'),
  ('مَنْ صَدَقَتْ لَهْجَتُهُ صَحَّتْ حُجَّتُهُ.', 'One whose language is truthful, his proof is correct.', 'Ghurar al-Hikam, The Truthful- §9', 'justice'),
  ('مَنْ صَدَقَ نَجا.', 'One who is truthful is saved.', 'Ghurar al-Hikam, The Truthful- §10', 'justice'),
  ('في تَصارِيفِ الأحْوالِ تُعْرَفُ جَواهِرُ الرِّجالِ.', 'It is during the change of circumstances that the [real] gems among the people are known.', 'Ghurar al-Hikam, Change of Circumstances- §1', 'wisdom'),
  ('قَدْ يَلينُ الصَّليبُ.', 'The rigid [and difficult person or issue] may become soft.', 'Ghurar al-Hikam, The Rigid- §1', 'wisdom'),
  ('ثابِرُوا عَلى صَلاحِ المُؤمِنينَ والمُتَّقينَ.', 'Devote yourself to [working for] the welfare of the believers and pious ones.', 'Ghurar al-Hikam, Welfare of the Believers- §1', 'wisdom'),
  ('ما أبْعَدَ الصَّلاحَ مِنْ ذِي الشَّـرِّ الوَقاحِ.', 'How far is probity from the people of evil and impudence!', 'Ghurar al-Hikam, Welfare of the Believers- §2', 'wisdom'),
  ('مَنْ صَلُحَ مَعَ اللّهِ سُبْحانَهُ لَمْ يَفْسُدْ مَعَ أحَد.', 'One who is dutiful with Allah, the Glorified, does not spoil [his relationship] with anyone.', 'Ghurar al-Hikam, Being Dutiful with Allah- §1', 'wisdom'),
  ('إنْ سَمَتْ هِمَّتُكَ لإصْلاحِ النّاسِ، فَابْدَأْ بِنَفْسِكَ فَإنَّ تَعاطيكَ صَلاحَ غَيْرِكَ وأنْتَ فاسِدٌ أكْبَرُ العَيْبِ.', 'If your zeal for reforming the people becomes heightened, then begin with yourself; for indeed your pursuit for the righteousness of others while you are [yourself] corrupt, is the greatest flaw.', 'Ghurar al-Hikam, Reforming the People- §1', 'wisdom'),
  ('عَجِبْتُ لِمَنْ يَتَصَدّى لإصْلاحِ النّاسِ، ونَفْسُهُ أشَدُّ شَيْء فَساداً فلايُصْلِحُها وَيَتَعاطى إصْلاحَ غَيْرِهِ.', 'I am amazed at the one who sets out to reform the people while his own soul is more severely corrupted yet he does not reform it and pursues the reformation of others.', 'Ghurar al-Hikam, Reforming the People- §2', 'wisdom'),
  ('كَيْفَ يَصْلَحُ غَيْرَهُ مَنْ لايُصْلِحُ نَفْسَهُ؟!', 'How can one who does not reform himself reform others?!', 'Ghurar al-Hikam, Reforming the People- §3', 'wisdom'),
  ('أصْلِحْ إذا أنْتَ أفْسَدْتَ، وأتْمِمْ إذا أنْتَ أحْسَنْتَ.', 'Rectify when you have corrupted and complete [your good act] when you have done good.', 'Ghurar al-Hikam, Reforming the People- §4', 'wisdom'),
  ('أدْوَأُ الدَّاءِ الصَّلَفُ.', 'he worst disease is vainglory.', 'Ghurar al-Hikam, Vainglory- §1', 'wisdom'),
  ('رُبَّ صَلَف أوْرَثَ تَلَفاً.', 'Many a [show of ostentation and] vainglory brings about loss.', 'Ghurar al-Hikam, Vainglory- §2', 'wisdom'),
  ('اَلصَّلاةُ أفْضَلُ القُرْبَتَيْنِ.', 'Prayer is the better of the two means of [attaining] nearness [to Allah].', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §1', 'faith'),
  ('اَلصَّلاةُ حِصْنٌ مِنْ سَطَواتِ الشَّيْطانِ.', 'Prayer is a fortress [that protects] from the influences of Satan.', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §2', 'faith'),
  ('اَلصَّلاةُ حِصْنُ الرَّحْمنِ، ومِدْحَرَةُ الشَّيْطانِ.', 'Prayer is the fortress of the all-Merciful and the instrument for expelling Satan.', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §3', 'faith'),
  ('اَلصَّلاةُ تَسْتَنْزِلُ الرَّحْمَةَ.', 'Prayer causes [divine] mercy to descend.', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §4', 'faith'),
  ('إذا قامَ أحَدُكُمْ إلَى الصَّلاةِ فَلْيُصَلِّ صَلاةَ مُوَدِّع.', 'When one of you stands to perform prayer, then let him pray the prayer of one who is bidding farewell (i.e. he should assume that it is the last prayer he will perform in his lifetime).', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §5', 'faith'),
  ('والصَّلاةَ تَنْزيهاً عَنِ الكِبْرِ.', 'And prayer [was prescribed] as a purification from arrogance.', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §6', 'faith'),
  ('كَمْ مِنْ قائِم لَيْسَ لَهُ مِنْ قِيامِهِ إلاّ العَناءُ.', 'How many of those who stand [to perform prayer] have nothing in their prayer but [physical] effort.', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §7', 'faith'),
  ('لَوْ يَعْلَمُ المُصَلّي ما يَغْشاهُ مِنَ الرَّحْمَةِ لَما رَفَعَ رَأسَهُ مِنَ السُّجُودِ.', 'If the one who offers prayer knew how much divine mercy is descending upon him, he would surely not raise his head from prostration.', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §8', 'faith'),
  ('ما أهَمَّني ذَنْبٌ أُمْهِلْتُ فيهِ حَتّى أُصَلِّـيَ رَكْعَتَيْنِ.', 'I am not worried by a wrongdoing in which I am given time so that I can offer two units of prayer [and seek forgiveness].', 'Ghurar al-Hikam, Prayer and one who stands for Prayer- §9', 'faith'),
  ('الصَّمْتُ يُكْسِيكَ الوَقارَ، ويَكْفِيكَ مَؤُنَةَ الاِعتِذارِ.', 'Silence covers you with dignity and suffices as your provision for seeking pardon.', 'Ghurar al-Hikam, Silence- §1', 'character'),
  ('أُصْمُتْ تَسْلَمْ.', 'Be silent and you will remain safe.', 'Ghurar al-Hikam, Silence- §2', 'character'),
  ('اِلْزَمِ الصَّمْتَ، يَسْتُرْ (يَسْتَنِرْ) فِكْرُكَ', 'Espouse silence and your thoughts will remain hidden (or will become illuminated).', 'Ghurar al-Hikam, Silence- §3', 'character'),
  ('أُصْمُتْ دَهْرَكَ يَجِلَّ أمْرُك.', 'Remain silent in your lifetime and your affair will become lofty.', 'Ghurar al-Hikam, Silence- §4', 'character'),
  ('اِلْزَمِ الصَّمْتَ، فَأدْني نَفْعِهِ السَّلامَةُ.', 'Espouse silence, for the least of its benefits is safety.', 'Ghurar al-Hikam, Silence- §5', 'character'),
  ('اِلْزَمِ الصَّمْتَ، يَلْزَمْكَ النَّجاةُ والسَّلامَةُ، وَالْزَمِ الرِّضا يَلْزَمْكَ الغَناءُ وَالكَرامَةُ.', 'Espouse silence and you will be accompanied by safety and security; espouse contentment and you will be accompanied by prosperity and honour.', 'Ghurar al-Hikam, Silence- §6', 'character'),
  ('اِلْزَمِ السُّكُوتَ، واصْبِرْ عَلى القَناعَةِ بِأيْسَرِ القُوتِ تَعِزَّ(تَغِزَّ) في دُنْياكَ وتَعِزَّ في أُخْريكَ.', 'Espouse silence and be patient with contentment for the little provision [that you have], [and as a result] you will become great (or your will overcome) in your world and will become great in your Hereafter.', 'Ghurar al-Hikam, Silence- §7', 'character'),
  ('أحْسَنُ الصَّمْتِ ماكانَ عَنِ الزَّلَلِ.', 'The best silence is that which prevents [one] from error.', 'Ghurar al-Hikam, Silence- §8', 'character'),
  ('أحْمَدُ مِنَ البَلاغَةِ الصَّمْتُ حينَ لايَنْبَغِي الكَلامُ.', 'Remaining silent when speech is inappropriate is more praiseworthy than eloquence.', 'Ghurar al-Hikam, Silence- §9', 'character'),
  ('اَلصَّمْتُ وَقارٌ، اَلَهَذْرُ عارٌ.', 'Silence is dignity and idle talk is disgrace.', 'Ghurar al-Hikam, Silence- §10', 'character'),
  ('أشَدُّ المَصائِبِ سُوءُ الخَلَفِ.', 'The severest of hardships is [having] evil offspring.', 'Ghurar al-Hikam, Hardships- §1', 'patience'),
  ('اَلمَصائِبُ مِفْتاحُ الأجْرِ.', 'Hardships are the key to reward.', 'Ghurar al-Hikam, Hardships- §2', 'patience'),
  ('اَلثَّوابُ عِنْدَاللّهِ سُبْحانَهُ وتَعالى عَلى قَدْرِ المُصابِ.', 'Reward with Allah, the Glorified, is to the extent of the hardship undergone.', 'Ghurar al-Hikam, Hardships- §3', 'patience'),
  ('اَلمُصيبَةُ بِالصَّبْرِ أعْظَمُ المَصائِبِ.', 'The hardship of [lacking] patience is the greatest of hardships.', 'Ghurar al-Hikam, Hardships- §4', 'patience'),
  ('اَلمَصائِبُ بِالسَّوِيَّةِ مَقْسُومَةٌ بَيْنَ البَريَّةِ.', 'Hardships are divided equally among the creatures.', 'Ghurar al-Hikam, Hardships- §5', 'patience'),
  ('اَلمُصيبَةُ بِالدّينِ أعْظَمُ المَصائِبِ.', 'Hardship in religion is the greatest of hardships.', 'Ghurar al-Hikam, Hardships- §6', 'patience'),
  ('اَلثَّوابُ عَلَى المُصيبَةِ أعْظَمُ مِنْ قَدْرِ المُصِيبَةِ.', 'The reward for [bearing] hardship is greater than the extent of the hardship [itself].', 'Ghurar al-Hikam, Hardships- §7', 'patience'),
  ('إنَّكُمْ هَدَفُ النَّوائِبِ، ودَريئَةُ الأسْقامِ.', 'Indeed you are the target of calamities and the object of sicknesses.', 'Ghurar al-Hikam, Hardships- §8', 'patience'),
  ('قَدْ تُذِلُّ الرَّزِيَّةُ.', 'At times, tribulation may abase [a person].', 'Ghurar al-Hikam, Hardships- §9', 'patience'),
  ('إذا رَأيْتَ اللّهَ سُبْحانَهُ يُتابِـعُ عَلَيْكَ البَلاءَ فَقَدْ أيْقَظَكَ.', 'When you see that Allah, the Glorified, is continuously testing you [with hardships], then [know that] He has woken you [from your slumber of negligence].', 'Ghurar al-Hikam, Hardships- §10', 'patience'),
  ('اَلمُصيبُ واجِدٌ، اَلمُخْطِئُ فاقِدٌ.', 'The one who hits the mark, achieves and the one who errs, loses.', 'Ghurar al-Hikam, The one who hits the mark and the one who errs- §1', 'wisdom'),
  ('اَلإصابَةُ سَلامَةٌ، اَلخَطاءُ مَلامَةٌ، اَلعَجَلُ نَدامَةٌ.', 'Being right is [a means of] safety, erring is [a cause of] reproach and haste is [a reason for] regret.', 'Ghurar al-Hikam, The one who hits the mark and the one who errs- §2', 'wisdom'),
  ('ما كُلُّ رام يُصيبُ.', 'To everyone who shoots hits the mark.', 'Ghurar al-Hikam, The one who hits the mark and the one who errs- §3', 'wisdom'),
  ('اَلصَّوابُ أسَدُّ الفِعْلِ.', 'Correctness is [performing] the most appropriate action.', 'Ghurar al-Hikam, Correctness- §1', 'wisdom'),
  ('اَلصَّوابُ مِنْ فُروعِ الرَّوِيَّةِ.', 'Correctness is one of the branches of deliberation.', 'Ghurar al-Hikam, Correctness- §2', 'wisdom'),
  ('كَثْرَةُ الصَّوابِ تُنْبِئُ عَنْ وُفُورِ العَقْلِ.', 'Increased correctness points to abundant intelligence.', 'Ghurar al-Hikam, Correctness- §3', 'wisdom'),
  ('مَنْ تَوَخَّي الصَّوابَ أنْجَحَ.', 'One who strives for correctness becomes successful.', 'Ghurar al-Hikam, Correctness- §4', 'wisdom'),
  ('إذَا ازْدَحَمَ الجَوابُ نُفِيَ الصَّوابُ.', 'When the answer is overcomplicated, correctness is negated.', 'Ghurar al-Hikam, Correctness- §5', 'wisdom'),
  ('حُسْنُ الصُّورَةِ أوَّلُ السَّعادَةِ.', 'good countenance is the beginning of felicity.', 'Ghurar al-Hikam, Countenance- §1', 'wisdom'),
  ('حُسْنُ الصُّورَةِ اَلجَمالُ الظّاهِرُ.', 'A good countenance is an apparent beauty.', 'Ghurar al-Hikam, Countenance- §2', 'wisdom'),
  ('اَلصُّورَةُ الجَميلَةُ أوَّلُ السَّعادَتَيْنِ.', 'A beautiful countenance is the first of the two felicities.', 'Ghurar al-Hikam, Countenance- §3', 'wisdom'),
  ('اَلصِّيامُ أحَدُ الصِّحَّتَيْنِ.', 'Fasting is one of the two means to good health.', 'Ghurar al-Hikam, Fasting- §1', 'faith'),
  ('صِيامُ الأيامِ البيضِ مِنْ كُلِّ شَهْر تَرْفَعُ الدَّرَجاتِ وتُعَظِّمُ المَثُوباتِ.', 'Fasting on the ‘luminous days’ (i.e. on the 13th, 14th and 15th) of every [lunar] month raises the stations and magnifies the rewards.', 'Ghurar al-Hikam, Fasting- §2', 'faith'),
  ('صِيامُ القَلْبِ عَنِ الفِكْرِ فِي الآثامِ أفْضَلُ مِنْ صِيامِ البَطْنِ عَنْ الطَّعامِ.', 'Fasting of the heart from thinking about sins is better than fasting of the stomach from food.', 'Ghurar al-Hikam, Fasting- §3', 'faith'),
  ('صَوْمُ النَّفْسِ عَنْ لَذّاتِ الدُّنيا أنْفَعُ الصِّيامِ.', 'Fasting of the soul from the pleasures of this world is the most beneficial fasting.', 'Ghurar al-Hikam, Fasting- §4', 'faith'),
  ('صَوْمُ الجَسَدِ الإمْساكُ عَنِ الأغْذِيَةِ بِإرادَة وَاخْتِيار خَوْفاً مِنَ العِقابِ وَرَغْبَةً فِي الثَّوابِ والأجْرِ.', 'Fasting of the body means restraining oneself from food willfully and by choice, out of fear of punishment and out of desire for reward and recompense.', 'Ghurar al-Hikam, Fasting- §5', 'faith'),
  ('صَوْمُ النَّفْسِ إمْساكُ الحَواسِّ الخَمْسِ عَنْ سائِرِ المَ آثِمِ، وخُلُوُّ القَلْبِ عَنْ جَميعِ أسْبابِ الشَّـرِّ.', 'Fasting of the soul means restraining the five senses from all the sins and emptying the heart of all the motives of evil.', 'Ghurar al-Hikam, Fasting- §6', 'faith'),
  ('صَوْمُ القَلْبِ خَيْرٌ مِنْ صِيامِ اللِّسانِ، وصيامُ اللِّسانِ خَيْـرٌ مِنْ صِيامِ البَطْنِ.', 'Fasting of the heart is better than fasting of the tongue, and fasting of the tongue is better than fasting of the stomach.', 'Ghurar al-Hikam, Fasting- §7', 'faith'),
  ('والصّيامَ اِبْتِلاءً لإخْلاصِ الخَلْقِ.', 'And fasting [has been prescribed] as a test of the sincerity of the people.', 'Ghurar al-Hikam, Fasting- §8', 'faith'),
  ('كَمْ مِنْ صائِم لَيْسَ لَهُ مِنْ صِيامِهِ إلاّ الظِّماءُ.', 'How many of those who are fasting gain nothing from their fast but thirst!', 'Ghurar al-Hikam, Fasting- §9', 'faith'),
  ('للاِعْتِبارِ تُضْرَبُ الأمْثالُ.', 'In order to derive lessons, examples are given.', 'Ghurar al-Hikam, Giving Examples and using metaphors- §1', 'forgiveness'),
  ('لأهْلِ الاِعْتِبارِ تُضْرَبُ الأمْثالُ.', 'For people who take lesson, examples are given.', 'Ghurar al-Hikam, Giving Examples and using metaphors- §2', 'forgiveness'),
  ('لأهْلِ الفَهْمِ تُصَرَّفُ الأقْوالِ.', 'For people of understanding speech becomes figurative.', 'Ghurar al-Hikam, Giving Examples and using metaphors- §3', 'forgiveness'),
  ('ضُرُوبُ الأمْثالِ تُضْرَبُ لأُولِى النُّهى والألبابِ.', 'Metaphors are given for the people of intellect and insight.', 'Ghurar al-Hikam, Giving Examples and using metaphors- §4', 'forgiveness'),
  ('خَيْرُ الضِّحْكِ التَّبَسُّمُ.', 'The best [form of] laughter is a smile.', 'Ghurar al-Hikam, Laughter- §1', 'wisdom'),
  ('كَثْرَةُ ضِحْكِ الرَّجُلِ تُفْسِدُ وَقارَهُ.', 'The excessive laughter of a man corrupts his dignity.', 'Ghurar al-Hikam, Laughter- §2', 'wisdom'),
  ('كَثْرَةُ الضِّحْكِ تُوحِشُ الجَليسَ وتَشينُ الرَّئيسَ.', 'Excessive laughter alienates the companion and disgraces the leader.', 'Ghurar al-Hikam, Laughter- §3', 'wisdom'),
  ('مَنْ كَثُرَ ضِحْكُهُ قَلَّتْ هَيْبَتُهُ.', 'One whose laughter increases, his reverence decreases.', 'Ghurar al-Hikam, Laughter- §4', 'wisdom'),
  ('مَنْ كَثُرَ ضِحْكُهُ ماتَ قَلْبُهُ.', 'One whose laughter increases, his heart dies.', 'Ghurar al-Hikam, Laughter- §5', 'wisdom'),
  ('مَنْ كَثُرَ ضِحْكُهُ اُسْتُرْذِلَ.', 'One whose laughs excessively is regarded as being low.', 'Ghurar al-Hikam, Laughter- §6', 'wisdom'),
  ('لاتُبْدِعَنْ واضِحَة، وَقَدْ فَعَلْتَ الأُمُورَ الفاضِحَةَ.', 'Do not show your teeth [in laughter] while you have done such shameful deeds.', 'Ghurar al-Hikam, Laughter- §7', 'wisdom'),
  ('لا تُكْثِرَنَّ الضِّحْكَ، فَتَذْهَبَ هَيْبَتُكَ، ولا المُزاحَ فَيُسْتَخَفَّ بِكَ.', 'Never laugh too much such that your reverence is lost; and do not joke [too much] thereby [resulting in your] being taken lightly.', 'Ghurar al-Hikam, Laughter- §8', 'wisdom'),
  ('قَد يَدُومُ الضُّـرُّ.', 'Sometimes suffering may last [for long].', 'Ghurar al-Hikam, Suffering- §1', 'wisdom'),
  ('مَنْ كَشَفَ ضُـرَّهُ لِلنّاسِ عَذَّبَ نَفْسَهُ.', 'One who discloses his suffering to the people torments himself.', 'Ghurar al-Hikam, Suffering- §2', 'wisdom'),
  ('ضَرُوراتُ الأحْوالِ تُذِلُّ رِقابَ الرِّجالِ.', 'The necessities of [dire] conditions lower the necks of men.', 'Ghurar al-Hikam, Necessities- §1', 'wisdom'),
  ('ضَرُوراتُ الأحْوالِ تَحْمِلُ عَلى رُكُوبِ الأهْوالِ.', 'The necessities of [dire] conditions take one towards embarking on terrible deeds.', 'Ghurar al-Hikam, Necessities- §2', 'wisdom'),
  ('ضَرُورَةُ الفَقْرِ تَبْعَثُ عَلى فَظيعِ الأمْرِ.', 'The plight of poverty impels one towards a despicable affair.', 'Ghurar al-Hikam, Necessities- §3', 'wisdom'),
  ('إذا ضَعُفْتَ فَاضْعُفْ عَنْ مَعاصِي اللّهِ.', 'When you become weak, then be weak in the disobedience of Allah.', 'Ghurar al-Hikam, Weakness- §1', 'wisdom'),
  ('كُنْ مِمَّنْ لايَفْرُطُ بِهِ عُنْفٌ، ولايَقْعُدُ بِهِ ضَعْفٌ.', 'Be from among those who are neither overcome by violence nor affected by weakness.', 'Ghurar al-Hikam, Weakness- §2', 'wisdom'),
  ('أهْلَكُ شَيْء اِسْتِدامَةُ الضّلالِ.', 'The most destructive thing is persistent deviation.', 'Ghurar al-Hikam, Error and deviation- §1', 'wisdom'),
  ('كَمْ مِنْ ضَلالَة زُخْرِفَتْ بِ آيَة مِنْ كِتابِ اللّهِ كَما يُزَخْرَفُ الدِّرْهَمُ النُّحاسُ بِالفِضَّةِ المُمَوَّهَةِ.', 'How many a deviation has been embellished by a verse from the Book of Allah just as a bronze dirham is embellished by a coat of silver.', 'Ghurar al-Hikam, Error and deviation- §2', 'wisdom'),
  ('كَفى بِالمَرْءِ غَوايَةً أنْ يَأمُرَ النّاسَ بِما لا يَأْتَمِرُ بِهِ ويَنْهاهُمْ عَمّا لا يَنْتَهي عَنْهُ.', 'It is enough of an error for a person to command others to do what he does not do [himself] and forbids them from that which he does not refrain from.', 'Ghurar al-Hikam, Error and deviation- §3', 'wisdom'),
  ('ما ذا بَعْدَ الحَقِّ إلاّ الضَّلالُ.', 'What is there after truth except error?', 'Ghurar al-Hikam, Error and deviation- §5', 'wisdom'),
  ('اَلضَّمائِرُ الصِّحاحُ أصْدَقُ شَهادَةً مِنَ الألْسُنِ الفِصاحِ.', 'Healthy consciences are more truthful witnesses than eloquent tongues.', 'Ghurar al-Hikam, Inner Consciences- §1', 'wisdom'),
  ('صِحَّةُ الضَّمائِرِ مِنْ أفْضَلِ الذَّخائِرِ.', 'The soundness of consciences is from the best provisions.', 'Ghurar al-Hikam, Inner Consciences- §2', 'wisdom'),
  ('عِنْدَ تَحَقُّقِ الإخْلاصِ تَسْتَنيرُ الضَّمائِرُ.', 'When sincerity is achieved the consciences are illuminated.', 'Ghurar al-Hikam, Inner Consciences- §3', 'wisdom'),
  ('أكْرِمْ ضَيْفَكَ وإنْ كانَ حَقيراً، وقُمْ عَنْ مَجْلِسِكَ لاِبيكَ ومُعَلِّمِكَ وَإنْ كُنْتَ أميراً.', 'onor your guest even if he is ignoble; and stand up from your sitting place for your father and your teacher, even if you are a ruler.', 'Ghurar al-Hikam, Hospitality- §1', 'generosity'),
  ('اَلضِّيافَةُ رَأسُ المُرُوَّةِ.', 'Hospitality is the cornerstone of magnanimity.', 'Ghurar al-Hikam, Hospitality- §2', 'generosity'),
  ('لِكُلِّ ضيق مَخْرَجٌ.', 'For every agony there is a way out.', 'Ghurar al-Hikam, Agony- §1', 'wisdom'),
  ('مَا اشْتَدَّ ضيقٌ إلاّ قَرَّبَ اللّهُ فَرَجَهُ.', 'No agony intensifies but that Allah brings its relief closer.', 'Ghurar al-Hikam, Agony- §2', 'wisdom'),
  ('رُبَّ طَرَب يَعُودُ بِالحَربِ.', 'Many a time jubilation turns into rage.', 'Ghurar al-Hikam, Jubilation- §1', 'wisdom'),
  ('طُوبى لِمَنْ رَكِبَ الطَّريقَةَ الغَرّاءِ، ولَزِمَ المَحَجَّةَ البَيْضاءَ وتَوَلَّهَ بِالآخِرَةِ، وأعْرَضَ عَنِ الدُّنيا.', 'Blessed is the one who embarks on the way of the honorable and sticks to the highway of illumination [and truth]; and [one who] is infatuated with the Hereafter and turns away from this world.', 'Ghurar al-Hikam, The way and the course- §1', 'wisdom'),
  ('قد وضَحَتْ مَحَجَّةُ الحَقِّ لِطُلاّبِها.', 'Indeed, the highway of truth has been made manifest for those who seek it.', 'Ghurar al-Hikam, The way and the course- §2', 'wisdom'),
  ('قَدْ أُمْهِلُوا في طَلَبِ المَخْرَجِ، وَهُدُوا سَبيلَ المَنْهَجِ.', 'They have indeed been given time to seek deliverance and have been guided to the clear course.', 'Ghurar al-Hikam, The way and the course- §3', 'wisdom'),
  ('مَنْ عَدَلَ عَنْ واضِحِ المَسالِكِ سَلَكَ سُبُلَ المَهالِكِ.', 'One who deviates from the clear tracks ends up following the courses of destruction.', 'Ghurar al-Hikam, The way and the course- §4', 'wisdom'),
  ('مَنْ زَلَّ عَنْ مَحَجَّةِ الطَّريقِ وَقَعَ في حَيْرَةِ المَضيقِ.', 'One who slips from the highway of the course falls into the perplexity of narrowness.', 'Ghurar al-Hikam, The way and the course- §5', 'wisdom'),
  ('مَنْ عَدَلَ عَنْ واضِحِ المَحَجَّةِ، غَرِقَ فِي اللُّجَّةِ.', 'One who deviates from the clear highway drowns in the depths of the sea.', 'Ghurar al-Hikam, The way and the course- §6', 'wisdom'),
  ('أمْسِكْ عَنْ طَريق إذا خِفْتَ ضَلالَتَهُ.', 'Hold back from [traversing] a path when you fear its deviation.', 'Ghurar al-Hikam, The way and the course- §7', 'wisdom'),
  ('عَلَيْكَ بِمَنْهَجِ الاِسْتِقامَةِ، فَإنَّهُ يُكْسِبُكَ الكَرامَةَ، وَيَكْفيكَ المَلامَةَ.', 'Adopt the way of steadfastness, for indeed it will earn you honour and save you from reproach.', 'Ghurar al-Hikam, The way and the course- §8', 'wisdom'),
  ('عَلَيْكُمْ بِالمَحَجَّةِ البَيْضاءِ فَاسْلُكُوها، وإلاّ اسْتَبْدَلَ اللّهُ بِكُمْ غَيْرَكُمْ.', 'Take to the highway of illumination [and truth] and follow it, otherwise Allah will replace you with others.', 'Ghurar al-Hikam, The way and the course- §9', 'wisdom'),
  ('مَنْ زاغَ ساءَتْ عِنْدَهُ الحَسَنَةُ، وحَسُنَتْ عِنْدَهُ السَّيِّئَةُ، وسُكِرَ سُكْرَ الضَّلالَةِ.', 'Whoever deviates from the truth, good becomes evil for him and evil becomes good, and he gets intoxicated with the intoxication of misguidance.', 'Ghurar al-Hikam, The way and the course- §10', 'wisdom'),
  ('اَلطَّعامُ يُؤْكَلُ عَلى ثَلاثَةِ أضْرُب: مَعَ الإخْوانِ بِالسُّرُورِ،وَ مَعَ الفُقَراءِ بِالإيثارِ، ومَعَ أبناءِ الدُّنيا بِالمُرُوءَةِ.', 'Food is eaten and shared with three groups [in three situations]: alongside brothers with happiness, alongside the poor with selflessness and alongside the children of this world with magnanimity.', 'Ghurar al-Hikam, Food and sustenance- §1', 'wisdom'),
  ('بِئْسَ الطَّعامُ الحَرامُ.', 'How bad a food the forbidden [food] is!', 'Ghurar al-Hikam, Food and sustenance- §2', 'wisdom'),
  ('بِئْسَ القُوتُ أكْلُ مالِ الأيْتامِ.', 'How bad a sustenance consuming the wealth of orphans is!', 'Ghurar al-Hikam, Food and sustenance- §3', 'wisdom'),
  ('قَلَّ مَنْ أكْثَرَ مِنَ الطَّعامِ فَلَمْ يَسْقَمْ.', 'Few are those who increase their consumption of food and don’t fall ill [because of it].', 'Ghurar al-Hikam, Food and sustenance- §4', 'wisdom'),
  ('قَلَّ مَنْ أكْثَرَ مِنْ فُضُولِ الطَّعامِ إلاّ لَزِمَتْهُ الأسْقامُ.', 'Seldom does one increase his consumption of excess foods without getting afflicted by sicknesses.', 'Ghurar al-Hikam, Food and sustenance- §5', 'wisdom'),
  ('قِلَّةُ الغِذاءِ أكْرَمُ لِلنَّفْسِ، وأدْوَمُ لِلصِّحَّةِ.', 'Eating less food is more honorable for the soul and makes good health last longer.', 'Ghurar al-Hikam, Food and sustenance- §6', 'wisdom'),
  ('كُلُوا الأُتْرُجَّ قَبْلَ الطَّعامِ وبَعْدَهُ ف آلُ مُحَمَّد يَفْعَلُونَ ذلِكَ.', 'Eat citron before food and after it as the progeny of Muhammad (s) do this.', 'Ghurar al-Hikam, Food and sustenance- §7', 'wisdom'),
  ('مَنْ قَلَّ طَعامُهُ قَلَّتْ آلامُهُ.', 'Whoever eats less, his aches [and ailments] are reduced.', 'Ghurar al-Hikam, Food and sustenance- §8', 'wisdom'),
  ('مَنْ قَلَّتْ طُعْمَتُهُ خَفَّتْ عَلَيْهِ مَؤُنَتُهُ.', 'Whoever consumes less, [the burden of] his sustenance is lightened.', 'Ghurar al-Hikam, Food and sustenance- §9', 'wisdom'),
  ('مَنْ غَرَسَ في نَفْسهِ مَحَبَّةَ أنْواعِ الطَّعامِ اِجْتَنى ثِمارَ فُنُونِ الأسْقامِ.', 'One who sows in himself the love of different types of food, reaps the fruit of a variety of maladies.', 'Ghurar al-Hikam, Food and sustenance- §10', 'wisdom'),
  ('إذا أطْعَمْتَ فَاَشْبِـعْ.', 'When you feed [someone] then satiate him.', 'Ghurar al-Hikam, Feeding Others- §1', 'wisdom'),
  ('ما أكَلْتَهُ راحَ، وما أطْعَمْتَهُ فاحَ.', 'That which you have eaten has gone, but what you have fed to others spreads [like a pleasant fragrance].', 'Ghurar al-Hikam, Feeding Others- §2', 'wisdom'),
  ('إيّاكَ أنْ تَـكُونَ علَى النّاسِ طاعِناً، ولِنَفْسِكَ مُداهِناً، فَتَعْظُمَ عَلَيْكَ الحَوْبَةُ، وتُحْرَمَ المَثُوبَةَ.', 'Beware of being critical of the people while going easy on yourself, thereby rendering your sin grave and being deprived of reward.', 'Ghurar al-Hikam, Criticism- §1', 'wisdom'),
  ('أطِعْ تَغْنَمْ.', 'bey [Allah] and you will benefit.', 'Ghurar al-Hikam, Obedience and compliance- §1', 'wisdom'),
  ('أطِعْ تُرْبَحْ.', 'Obey [Allah] and you will gain.', 'Ghurar al-Hikam, Obedience and compliance- §2', 'wisdom'),
  ('أطِعِ اللّهَ في جُمَلِ أُمُورِكَ، فَإنَّ طاعَةَ اللّهِ فاضِلَةٌ عَلى كُلِّ شَيْء، واَلْزِمِ الوَرَعَ.', 'Obey Allah in all you affairs, for indeed obedience to Allah is superior to everything; and espouse piety.', 'Ghurar al-Hikam, Obedience and compliance- §3', 'wisdom'),
  ('أطِعِ اللّهَ سُبْحانَهُ في كُلِّ حال، ولا تُخْلِ قَلْبَكَ مِنْ خَوْفِهِ ورَجائِهِ طَرْفَةَ عَيْن، واَلْزَمِ الاِسْتِغْفارَ.', 'Obey Allah, the Glorified, in every situation, and do not empty your heart of His fear and His hope even for a split second, and always seek forgiveness [from Him].', 'Ghurar al-Hikam, Obedience and compliance- §4', 'wisdom'),
  ('أطِعْ مَنْ فَوْقَكَ، يُطِعْكَ مَنْ دُونَكَ، وأصْلِحْ سَريرَتَكَ يُصْلِحِ اللّهُ علانِيَتَكَ.', 'Obey the one who is above you and the one who is under you will obey you; rectify your inner self and Allah will rectify your outer state.', 'Ghurar al-Hikam, Obedience and compliance- §5', 'wisdom'),
  ('أطيعُوا اللّهَ حَسَبَ ما أمَرَكُمْ بِهِ رُسُلُهُ.', 'Obey Allah in accordance with what His Prophets have commanded you.', 'Ghurar al-Hikam, Obedience and compliance- §6', 'wisdom'),
  ('اِسْتَجيبُوا لأنْبِياءِ اللّهِ، وسَلِّمُوا لأمْرِهِمْ، واعْمَلُوا بِطاعَتِهِمْ، تَدْخُلُوا في شَفاعَتِهِمْ.', 'Respond to the calls of the Prophets of Allah and submit yourselves to their commands and be obedient to them, [as a result] you will be included in their intercession.', 'Ghurar al-Hikam, Obedience and compliance- §7', 'wisdom'),
  ('إيّاكَ أنْ يَفْقُدَكَ رَبُّكَ عِنْدَ طاعَتِهِ، أوْ يَراكَ عِنْدَ مَعْصِيَتِهِ فَيَمْقَتَكَ.', 'Beware of being missed by your Lord in His worship, or being seen by Him in His disobedience thereby making Him displeased with you.', 'Ghurar al-Hikam, Obedience and compliance- §8', 'wisdom'),
  ('دَرَكُ الخَيْراتِ بِلُزُومِ الطَّاعاتِ.', 'Achievement of goodness is through maintaining obedience.', 'Ghurar al-Hikam, Obedience and compliance- §9', 'wisdom'),
  ('اَلطّاعَةُ وفِعْلُ البِرِّ هُما المَتْجَرُ الرَّابِحُ.', 'Obedience and virtuous actions are the two profitable trades.', 'Ghurar al-Hikam, Obedience and compliance- §10', 'wisdom'),
  ('مَنْ أطاعَ أمْرَكَ أجَلَّ قَدْرَكَ.', 'One who obeys your command has exalted your status.', 'Ghurar al-Hikam, Obeying commandments- §1', 'wisdom'),
  ('ما أسْرَعَ صَرْعَةَ الطّاغي.', 'How quick is the downfall of a tyrant!', 'Ghurar al-Hikam, The Tyrant- §1', 'wisdom'),
  ('قَدْ يَخيبُ الطّالِبُ.', 'A seeker may fail [to achieve what he seeks].', 'Ghurar al-Hikam, The Seeker- §1', 'wisdom'),
  ('كُلُّ طالِب مَطْلُوبٌ.', 'Every seeker is [himself] sought [by death].', 'Ghurar al-Hikam, The Seeker- §2', 'wisdom'),
  ('كُلُّ طالِب غَيْرُ اللّهِ مَطْلُوبٌ.', 'Every seeker other than Allah is sought.', 'Ghurar al-Hikam, The Seeker- §3', 'wisdom'),
  ('كَمْ مِنْ طالِب خائِب ومَرْزُوق غَيْرِ طالِب.', 'How many a seeker is deprived while the one who does not seek is granted [sustenance].', 'Ghurar al-Hikam, The Seeker- §4', 'wisdom'),
  ('لِلطّالِبِ البالِغِ لَذَّةُ الإدْراكِ.', 'For the seeker who achieves what he seeks, there is delight in [his] accomplishment.', 'Ghurar al-Hikam, The Seeker- §5', 'wisdom'),
  ('لَيْسَ كُلُّ طالِب بِمَرْزُوق.', 'Not every seeker is granted [sustenance].', 'Ghurar al-Hikam, The Seeker- §6', 'wisdom'),
  ('مَنْ طَلَبَ شَيْئاً نالَهُ أو بَعْضَهُ.', 'Whoever seeks a thing achieves it, or part of it.', 'Ghurar al-Hikam, The Seeker- §7', 'wisdom'),
  ('مَنْ طَلَبَ ما في أيْدِي النّاسِ حَقَّرُوهُ.', 'Whoever seeks that which is in the possession of people, they debase him [for it].', 'Ghurar al-Hikam, The Seeker- §8', 'wisdom'),
  ('مَنْ طَلَبَ ما لايَكُونُ ضَيَّعَ مَطْلَبَهُ.', 'One who seeks that which is impossible loses his quest.', 'Ghurar al-Hikam, The Seeker- §9', 'wisdom'),
  ('ما كُلُّ طالِب يَخيبُ.', 'Not every seeker fails.', 'Ghurar al-Hikam, The Seeker- §10', 'wisdom'),
  ('قَدْ تَتَجَهَّمُ المَطالِبُ.', 'At times the matters that are pursued are regarded with displeasure.', 'Ghurar al-Hikam, Matters that are pursued- §1', 'wisdom'),
  ('رُبَّما عَزَّ المَطْلَبُ والاِكْتِسابُ.', 'Sometimes the matter that is pursued and [its] acquisition become difficult.', 'Ghurar al-Hikam, Matters that are pursued- §2', 'wisdom'),
  ('قَد يُدْرَكُ المَطْلُوبُ.', 'At times that which is sought after is attained.', 'Ghurar al-Hikam, The sought after- §1', 'wisdom'),
  ('اَلمَذَلَّةُ والمَهانَةُ والشَّقاءُ، فِي الطَّمَعِ، والحِرْصِ.', 'Abasement, disgrace and wretchedness are in covetousness and greed.', 'Ghurar al-Hikam, Covetousness- §1', 'wisdom'),
  ('اَلطَّمَعُ مُورِدٌ غَيْرُ مُصْدِر، وضامِنٌ غَيْرُ مُوف.', 'Covetousness makes one enter [into difficulties and humiliation] but does not make him return from it; and it gives a guarantee but does not fulfil it.', 'Ghurar al-Hikam, Covetousness- §2', 'wisdom'),
  ('أهْلَكُ شَيْء الطَّمَعُ.', 'The most destructive thing is covetousness.', 'Ghurar al-Hikam, Covetousness- §3', 'wisdom'),
  ('أضَرُّ شَيْء اَلطَّمَعُ.', 'The most harmful thing is covetousness.', 'Ghurar al-Hikam, Covetousness- §4', 'wisdom'),
  ('أقْبَحُ الشِّيَمِ اَلطَّمَعُ.', 'The ugliest of traits is covetousness.', 'Ghurar al-Hikam, Covetousness- §5', 'wisdom'),
  ('أسْوَءُ شَيْء اَلطَّمَعُ.', 'The worst thing is covetousness.', 'Ghurar al-Hikam, Covetousness- §6', 'wisdom'),
  ('أصْلُ الشَّـرَهِ اَلطَّمَعُ، وثَمَرَتُهُ اَلمَلامَةُ.', 'The root of avarice is covetousness and its fruit is reproach.', 'Ghurar al-Hikam, Covetousness- §7', 'wisdom'),
  ('أزْرى بِنَفْسهِ مَنِ اسْتَشْعَرَ الطَّمَعَ.', 'He who covers himself with covetousness has degraded himself.', 'Ghurar al-Hikam, Covetousness- §8', 'wisdom'),
  ('أكْثَرُ مَصارِعِ العُقُولِ تَحْتَ بُرُوقِ المَطامِعِ.', 'The places where intellects become most deficient are under the flashes of greed.', 'Ghurar al-Hikam, Covetousness- §9', 'wisdom'),
  ('اَلطَّمَعُ مُضِـرٌّ.', 'Covetousness is harmful.', 'Ghurar al-Hikam, Covetousness- §10', 'wisdom'),
  ('مَنِ اسْتَطالَ عَلَى الإخْوانِ لَمْ يَخْـلُصْ لَهُ إنْسانٌ.', 'Whoever is haughty with his brothers, nobody will be sincere with him.', 'Ghurar al-Hikam, Haughtiness- §1', 'wisdom'),
  ('مَنِ اسْتَطالَ عَلَى النّاسِ بِقُدْرَتِهِ سُلِبَ القُدْرَةُ.', 'Whoever is haughty with people because of his authority, his authority will get stripped away.', 'Ghurar al-Hikam, Haughtiness- §2', 'wisdom'),
  ('اَلاِسْتِطالَةُ لِسانُ الغِوايَةِ والجَهالَةِ.', 'Haughtiness is the language of error and ignorance.', 'Ghurar al-Hikam, Haughtiness- §3', 'wisdom'),
  ('لاتَسْتَطِلْ عَلى مَنْ لاتَسْتَرِقَّ.', 'Do not be haughty with the one whom you have not enslaved.', 'Ghurar al-Hikam, Haughtiness- §4', 'wisdom'),
  ('مِنَ البَليَّةِ سُوءُ الطَّويَّةِ.', 'One of the [great] tribulations is [having] evil inner thoughts.', 'Ghurar al-Hikam, Innermost thoughts- §1', 'wisdom'),
  ('اَلطَّيْشُ يُنَـكِّدُ العَيْشَ.', 'Frivolity [and heedlessness] makes life bitter.', 'Ghurar al-Hikam, Frivolity- §1', 'wisdom'),
  ('اَلظَّفَرُ بِالحَزْمِ، والحَزْمُ بِالتَّجارِبِ.', 'Victory is [attained] by prudence, and prudence comes through experience.', 'Ghurar al-Hikam, Victory- §1', 'wisdom'),
  ('حَلاوَةُ الظَّفَرِ تَمْحُو مَرارَةَ الصَّبْرِ.', 'The sweetness of victory effaces the bitterness of patience.', 'Ghurar al-Hikam, Victory- §2', 'wisdom'),
  ('زَكاةُ الظَّفَرِ الإحْسانُ.', 'The alms-tax of victory is benevolence.', 'Ghurar al-Hikam, Victory- §3', 'wisdom'),
  ('ما ظَفِرَ مَنْ ظَفَرَ الإثْمُ بِهِ.', 'He who has been vanquished by sin has not gained victory.', 'Ghurar al-Hikam, Victory- §4', 'wisdom'),
  ('مِفْتاحُ الظَّفَرِ لُزُومُ الصَّبْرِ.', 'The key to victory is remaining patient.', 'Ghurar al-Hikam, Victory- §6', 'wisdom'),
  ('لاتَبْطِرَنَّ بِالظَّفَرِ، فَإنَّكَ لا تَأمَنُ ظَفَرَ الزَّمانِ بِكَ.', 'Never become vain because of [your] victory, for indeed you are not safe from the victory of time over you.', 'Ghurar al-Hikam, Victory- §7', 'wisdom'),
  ('لا ظَفَرَ لِمَنْ لا صَبْرَ لَهُ.', 'There is no victory for the one who has no patience.', 'Ghurar al-Hikam, Victory- §8', 'wisdom'),
  ('اَلظَّفَرُ شافِعُ المُذْنِبِ.', 'Victory is the intercessor of the guilty.', 'Ghurar al-Hikam, Victory- §9', 'wisdom'),
  ('أُذْكُرْ عِنْدَ الظُّلْمِ عَدْلَ اللّهِ فيكَ، وعِنْدَ القُدْرَةِ قُدْرَةَ اللّهِ عَلَيْكَ.', 'In times of injustice, remember the justice of Allah with you and when you are powerful, [recall] the power of Allah over you.', 'Ghurar al-Hikam, Injustice and Oppression- §1', 'justice'),
  ('اِتَّقُوا البَغْيَ فَإنَّهُ يَجْلِبُ النِّقَمَ،وَ يَسْلُبُ النِّعَمَ،وَ يُوجِبُ الغِيَرَ.', 'Beware of oppression, for verily it brings [divine] retribution, dispels blessings and causes changes in circumstances.', 'Ghurar al-Hikam, Injustice and Oppression- §2', 'justice'),
  ('أُبْعُدُوا عَنِ الظُّلْمِ، فَإنَّهُ أعْظَمُ الجَرائِمِ، وأكْبَرُ المَ آثِمِ.', 'Distance yourselves from injustice, for indeed it is the greatest of wrongdoings and the biggest of sins.', 'Ghurar al-Hikam, Injustice and Oppression- §3', 'justice'),
  ('إيّاكَ والظُّلْمَ، فَمَنْ ظَلَمَ كَرُهَتْ أيّامُهُ.', 'Keep away from injustice for whoever acts unjustly, his days are abhorred.', 'Ghurar al-Hikam, Injustice and Oppression- §4', 'justice'),
  ('إيّاكَ والظُّلْمَ، فَإنَّهُ يَزُولُ عَمَّنْ تَظْلِمُهُ، ويَبْقى عَلَيْكَ.', 'Keep away from injustice, for indeed it will depart from the one whom you oppress and will remain upon you.', 'Ghurar al-Hikam, Injustice and Oppression- §5', 'justice'),
  ('إيّاكَ والبَغْيَ، فَإنَّهُ يُعَجِّلُ الصَّرْعَةَ، ويُحِلُّ بِالعامِلِ بِهِ العِبَـرَ.', 'Keep away from oppression, for verily it hastens one’s downfall and causes tears [of regret and sorrow] to flow from the one who acts upon it.', 'Ghurar al-Hikam, Injustice and Oppression- §6', 'justice'),
  ('إيّاكَ والظُّلْمَ، فَإنَّهُ أكْبَرُ المعَاصي، وإنَّ الظّالِمَ لَمُعاقَبٌ يَوْمَ القِيمَةِ بِظُلْمِهِ.', 'Keep away from injustice, for it is the biggest sin; and verily the unjust will surely be chastised on the Day of Resurrection because of his injustice.', 'Ghurar al-Hikam, Injustice and Oppression- §7', 'justice'),
  ('إيّاكَ والبَغْيَ، فَإنَّ الباغِيَ يُعَجِّلُ اللّهُ لَهُ النِّقْمَةَ، ويُحِلُّ بِهِ المَثُلاتِ.', 'Keep away from oppression, for verily Allah hastens chastisement for the oppressor and sends down exemplary punishments upon him.', 'Ghurar al-Hikam, Injustice and Oppression- §8', 'justice'),
  ('إيّاكُمْ وصَـرَعاتِ البَغْيِ، وفَضَحاتِ الغَدْرِ، وإثارَةَ كامِنِ الشَّـرِّ المُذَمِّمِ.', 'Avoid the downfalls of transgression, the disgraces of deceit and the arousal of the latent, reprehensible evil.', 'Ghurar al-Hikam, Injustice and Oppression- §9', 'justice'),
  ('أقْبَحُ الشِّيَمِ العُدْوانُ.', 'The most loathsome of traits is aggression.', 'Ghurar al-Hikam, Injustice and Oppression- §11', 'justice'),
  ('أظْلَمُ النَّاسِ مَنْ سَنَّ سُنَنَ الجَوْرِ، ومَحى سُنَنَ العَدْلِ.', 'he most unjust of men is one who establishes the practice of oppression and abolishes the practice of justice.', 'Ghurar al-Hikam, The unjust- §1', 'wisdom'),
  ('اَلظَّالِمُ يَنْتَظِرُ العُقُوْبَةَ.', 'Punishment awaits the unjust.', 'Ghurar al-Hikam, The unjust- §3', 'wisdom'),
  ('ظالِمُ النّاسِ يَوْمَ القِيمَةِ مَنْكُوبٌ بِظُلْمِهِ مُعَذَّبٌ مَحْرُوبٌ.', 'On the Day of Judgment, the oppressor of the people will be afflicted, chastised and despoiled because of his injustice.', 'Ghurar al-Hikam, The unjust- §4', 'wisdom'),
  ('لِكُلِّ ظالِم اِنْتِقامٌ.', 'For every oppressor there is a reprisal.', 'Ghurar al-Hikam, The unjust- §5', 'wisdom'),
  ('لِكُلِّ ظالِم عُقُوْبَةٌ لاتَعْدُوهُ، وصَرْعَةٌ لاتَخْطُوهُ.', 'For every oppressor there is a punishment that he cannot escape, and a downfall that will not pass him by.', 'Ghurar al-Hikam, The unjust- §6', 'wisdom'),
  ('لِلظّالِمِ اِنْتِقامٌ.', 'For the unjust there is reprisal.', 'Ghurar al-Hikam, The unjust- §7', 'wisdom'),
  ('لِلظّالِمِ بِكَفِّهِ عَضَّةٌ.', 'For the unjust there is a biting of his hand.', 'Ghurar al-Hikam, The unjust- §8', 'wisdom'),
  ('لِلظّالِمِ مِنَ الرِّجالِ ثَلاثُ عَلامات: يَظْلِمُ مَنْ فَوْقَهُ بِالمَعْصِيَةِ، ومَنْ دُوْنَهُ بِالغَلَبَةِ، ويُظاهِرُ الْقَوْمَ الظَّلَمَةَ.', 'There are three signs of the unjust among the people: being unjust to the one who is above him by disobedience, and to the one below him by overruling him, and supporting the faction of oppressors.', 'Ghurar al-Hikam, The unjust- §9', 'wisdom'),
  ('مَنْ ظَلَمَ ظُلِمَ.', 'One who oppresses [others] gets oppressed.', 'Ghurar al-Hikam, The unjust- §10', 'wisdom'),
  ('مَنْ ظَلَمَ أفْسَدَ أمْرَهُ.', 'One who acts unjustly corrupts his affair.', 'Ghurar al-Hikam, The unjust- §11', 'wisdom'),
  ('اِتَّقُوا دَعْوَةَ المَظْلُومِ، فَإنَّهُ يَسْألُ اللّهَ حَقَّهُ، واللّهُ سُبْحانَهُ أكْرَمُ مِنْ أنْ يُسْئَلَ حَقّاً إلاّ أجابَ.', 'Beware of the cry of the oppressed, for verily he asks Allah for his right, and Allah, the Glorified, is more bountiful than that He should be asked for a right except that He grants it.', 'Ghurar al-Hikam, The oppressed- §1', 'wisdom'),
  ('إنَّ دَعْوَةَ المَظْلُومِ مُجابَةٌ عِنْدَ اللّهِ سُبْحانَهُ، لأنَّهُ يَطْلُبُ حَقَّهُ واللّهُ تَعالى أعْدَلُ أنْ يَمْنَعَ ذا حَقّ حَقَّهُ.', 'Verily the cry of the oppressed is answered by Allah, the Glorified, because he is asking for his right, and Allah is far greater than that He should deny a person his right.', 'Ghurar al-Hikam, The oppressed- §2', 'wisdom'),
  ('إذا رَأيْتَ مَظْلُوماً فَأعِنْهُ عَلَى الظّالِمِ.', 'When you see an oppressed person, then help him against the oppressor.', 'Ghurar al-Hikam, The oppressed- §3', 'wisdom'),
  ('ظُلامَةُ المَظْلُومينَ يُمْهِلُهَا اللّهُ سُبْحانَهُ وَلا يُهْمِلُها.', 'The oppressors of the oppressed are given respite by Allah, the Glorified, but are not overlooked.', 'Ghurar al-Hikam, The oppressed- §4', 'wisdom'),
  ('قَدْ يُنْصَرُ المَظْلُومُ.', 'At times the oppressed are assisted.', 'Ghurar al-Hikam, The oppressed- §5', 'wisdom'),
  ('كُنْ لِلْمَظْلُومِ عَوْناً، وَلِلظّالِمِ خَصْماً.', 'Be a helper for the oppressed and an enemy of the oppressor.', 'Ghurar al-Hikam, The oppressed- §6', 'wisdom'),
  ('مَنْ لَمْ يُنْصِفِ المَظْلُومَ مِنَ الظّالِمِ عَظُمَتْ آثامُهُ.', 'Whoever does not seek justice for the oppressed from the oppressor, his sins are magnified.', 'Ghurar al-Hikam, The oppressed- §7', 'wisdom'),
  ('ما أقْرَبَ النُّصْرَةَ مِنَ المَظْلُومِ.', 'How close is succour to the oppressed!', 'Ghurar al-Hikam, The oppressed- §9', 'wisdom'),
  ('لايَنْتَصِرُ المَظْلُومُ بِلاناصِر.', 'The oppressed does not prevail without a helper.', 'Ghurar al-Hikam, The oppressed- §10', 'wisdom'),
  ('فِي احْتِقابِ المَظالِمِ زَوالُ القُدْرَةِ.', 'In amassing the usurped rights [of the people] there is cessation [and loss] of power.', 'Ghurar al-Hikam, Usurped rights- §1', 'wisdom'),
  ('في مَظالِمِ العِبادِ اِحْتِقابُ الآثامِ.', 'In [keeping] the usurped rights of the servants, there is amassing of sins.', 'Ghurar al-Hikam, Usurped rights- §2', 'wisdom'),
  ('ظَنُّ المُؤْمِنِ كِهانَةٌ.', 'The surmise of a believer is a divination.', 'Ghurar al-Hikam, Conjecture- §1', 'wisdom'),
  ('ظَنُّ الرَّجُلِ عَلى قَدْرِ عَقْلِهِ.', 'The conjecture of a man is to the extent of his intellect.', 'Ghurar al-Hikam, Conjecture- §2', 'wisdom'),
  ('ظَنُّ الإنْسانِ ميزانُ عَقْلِهِ، وفِعْلُهُ أصْدَقُ شاهِد عَلى أصْلِهِ.', 'The conjecture of a person is the measure of his intellect and his action is the truest witness about his origin.', 'Ghurar al-Hikam, Conjecture- §3', 'wisdom'),
  ('ظَنُّ ذَوِي النُّهى والألْبابِ أقْرَبُ شَيْء مِنَ الصَّوابِ.', 'The conjecture of the people of insight and intelligence is the closest thing to correctness.', 'Ghurar al-Hikam, Conjecture- §4', 'wisdom'),
  ('مَنْ حَسُنَ ظَنُّهُ أهْمَلَ.', 'One whose supposition [about others] is good, overlooks [their lapses].', 'Ghurar al-Hikam, Conjecture- §5', 'wisdom'),
  ('مَنْ ساءَ ظَنُّهُ تَأمَّلَ.', 'One whose assumption [about others] is negative, scrutinizes.', 'Ghurar al-Hikam, Conjecture- §6', 'wisdom'),
  ('مَنْ حَسُنَ ظَنُّهُ حَسُنَتْ نِيَّتُهُ.', 'One who thinks positively [about others], his intention becomes good.', 'Ghurar al-Hikam, Conjecture- §7', 'wisdom'),
  ('مَنْ ساءَ ظَنُّهُ ساءَتْ طَوِيَّتُهُ.', 'One who thinks ill [of others], his innermost thoughts become evil.', 'Ghurar al-Hikam, Conjecture- §8', 'wisdom'),
  ('مَنْ ساءَ ظَنُّهُ ساءَ وَهْمُهُ.', 'One who thinks ill [of others], his imagination becomes evil.', 'Ghurar al-Hikam, Conjecture- §9', 'wisdom'),
  ('مَنْ ظَنَّ بِكَ خَيْراً فَصَدِّقْ ظَنَّهُ.', 'When one thinks good of you, then prove his supposition to be true.', 'Ghurar al-Hikam, Conjecture- §10', 'wisdom'),
  ('نِعْمَ العَوْنُ المُظاهَرَةُ.', 'The best [form of] help is giving support.', 'Ghurar al-Hikam, Support- §1', 'wisdom'),
  ('نِعْمَ الحَزْمُ الاِسْتِظْهارُ.', 'How good a foresight precaution is!', 'Ghurar al-Hikam, Precaution- §1', 'wisdom'),
  ('أفْضَلُ العُدَدِ الاِسْتِظْهارُ.', 'The best equipage is precaution.', 'Ghurar al-Hikam, Precaution- §2', 'wisdom'),
  ('مَنِ اسْتَظْهَرَ بِاللّهِ أعْجَزَ قَهْرُهُ.', 'One who has the backing of Allah [and trusts in Him], his subjugation [by the enemy] becomes impossible.', 'Ghurar al-Hikam, Precaution- §3', 'wisdom'),
  ('قَدْ يُصابُ المُسْتَظْهِرُ.', 'The one who is precautious may [also at times] get afflicted.', 'Ghurar al-Hikam, Precaution- §4', 'wisdom'),
  ('صَلاحُ الظَّواهِرِ عُنْوانُ صِحَّةِ الضَّمائِرِ.', 'Uprightness of the exteriors is a symbol of the soundness of the inner consciences.', 'Ghurar al-Hikam, The Exteriors- §1', 'wisdom'),
  ('لِكُلِّ ظاهِر باطِنٌ عَلى مِثالِهِ، فَمَنْ طابَ ظاهِرُهُ طابَ باطِنُهُ، وما خَبُثَ ظاهِرُهُ خَبُثَ باطِنُهُ.', 'For every exterior there is a hidden interior that is like it, so one who’s exterior is good his interior is also good, and whoever has a bad exterior has a bad interior.', 'Ghurar al-Hikam, The Exteriors- §2', 'wisdom'),
  ('في خِفَّةِ الظَّهْرِ راحَةُ السِّـرِّ، وتَحْصينُ القَدْرِ.', 'In having a light burden there is inner peace and the safeguarding of [one’s] status.', 'Ghurar al-Hikam, Lightness of one’s burden- §1', 'wisdom'),
  ('مَنْ قامَ بِشَرائِطِ العُبُودِيَّةِ أُهِّلَ لِلْعِتْقِ.', 'One who fulfils the conditions of servitude deserves to be freed.', 'Ghurar al-Hikam, Servitude- §1', 'wisdom'),
  ('اَلعِبادَةُ الخالِصَةُ أنْ لايَرْجُوَ الرَّجُلُ إلاّ رَبَّهُ، ولا يَخافُ إلاّ ذَنْبَهُ.', 'Sincere worship means that a person [puts his] hopes in none other than his Lord and fears nothing but his wrongdoing.', 'Ghurar al-Hikam, Worship and the worshipper- §1', 'faith'),
  ('اِجْعَلْ لِنَفْسِكَ فيما بَيْنَكَ وبَيْنَ اللّهِ سُبْحانَهُ أفْضَلَ المَواقيتِ وَالأقْسامِ.', 'Reserve for yourself the best times and portions for that which is between you and Allah, the Glorified.', 'Ghurar al-Hikam, Worship and the worshipper- §2', 'faith'),
  ('أفْضَلُ العِبادَةِ عِفَّةُ البَطْنِ والفَرْجِ.', 'The best worship is safeguarding the stomach and private parts [from the forbidden].', 'Ghurar al-Hikam, Worship and the worshipper- §4', 'faith'),
  ('اَلعِبادَةُ فَوْزٌ.', 'Worship is [a means to] success.', 'Ghurar al-Hikam, Worship and the worshipper- §5', 'faith'),
  ('دَوامُ العِبادَةِ بُرْهانُ الظَّفَرِ بِالسَّعادَةِ.', 'Continued worship is proof of success in attainment of prosperity.', 'Ghurar al-Hikam, Worship and the worshipper- §6', 'faith'),
  ('زَيْنُ العِبادَةِ اَلخُشُوعُ.', 'The adornment of worship is humility [and submissiveness].', 'Ghurar al-Hikam, Worship and the worshipper- §7', 'faith'),
  ('صَلاحُ العِبادَةِ التَّوَكُّلُ.', 'The probity of worship is [in] having trust in Allah.', 'Ghurar al-Hikam, Worship and the worshipper- §8', 'faith'),
  ('غايَةُ العِبادَةِ الطّاعَةُ.', 'The goal [and purpose] of worship is obedience.', 'Ghurar al-Hikam, Worship and the worshipper- §9', 'faith'),
  ('فِي الانْفِرادِ لِعِبادَةِ اللّهِ كُنُوزُ الأرْباحِ.', 'In secluding oneself for the worship of Allah there are treasures of benefit.', 'Ghurar al-Hikam, Worship and the worshipper- §10', 'faith'),
  ('فازَ بِالسَّعادَةِ مَنْ أخْلَصَ العِبادَةَ.', 'He who makes his worship sincere succeeds in attaining prosperity.', 'Ghurar al-Hikam, Worship and the worshipper- §11', 'faith'),
  ('اَلْعِتابُ حَياةُ المَوَدَّةِ.', 'Goodwill [and friendly admonishment] is the life of friendship [and affection].', 'Ghurar al-Hikam, Reprimand- §1', 'wisdom'),
  ('كَثْرَةُ العِتابِ تُؤْذِنُ بِالاِرْتيابِ.', 'Too much reprimand indicates [one’s] suspicion.', 'Ghurar al-Hikam, Reprimand- §2', 'wisdom'),
  ('ما أُعْتِبَ مَنِ اغْتَفَرَ (افْتَقَرَ).', 'He who seeks forgiveness (or is indigent) is not reprimanded.', 'Ghurar al-Hikam, Reprimand- §3', 'wisdom'),
  ('لاتُعاتِبِ الجاهِلَ فَيَمْقُتْكَ، وعاتِبِ العاقِلَ يُحْبِبْكَ.', 'Do not reprimand the ignorant one as he will hate you, but reprimand the wise one as he will love you [for it].', 'Ghurar al-Hikam, Reprimand- §4', 'wisdom'),
  ('لا تُكْثِرَنَّ العِتابَ، فَإنَّهُ يُورِثُ الضَّغينَةَ ويَدْعُو إلَى البَغْضاءِ، واسْتَعْتِبْ لِمَنْ رَجَوْتَ اِعْتابَهُ.', 'Never be excessive in reprimanding, for indeed it brings about ill feelings and calls toward hatred; and seek to appease the one whom you hope to reprimand.', 'Ghurar al-Hikam, Reprimand- §5', 'wisdom'),
  ('إذا عاتَبْتَ فَاسْتَبْقِ.', 'When you reprimand then leave some room [to make amends and do not be excessive in reprimanding].', 'Ghurar al-Hikam, Reprimand- §6', 'wisdom'),
  ('إذا مَلَكْتَ فَأعْتِقْ.', 'When you become the owner [of a slave], then emancipate [him].', 'Ghurar al-Hikam, Emancipation- §1', 'wisdom'),
  ('عَثْرَةُ الاِسْتِرْسالِ لاتُسْتَقالُ.', 'The slip up of impudence cannot be pardoned.', 'Ghurar al-Hikam, Slip up- §1', 'wisdom'),
  ('أوْحَشُ الوَحْشَةِ العُجْبُ.', 'The most alienating estrangement is conceit.', 'Ghurar al-Hikam, Conciet- §1', 'wisdom'),
  ('اَلعُجْبُ هَلاكٌ.', 'Conceit is destruction.', 'Ghurar al-Hikam, Conciet- §2', 'wisdom'),
  ('اَلعُجْبُ حُمْقٌ.', 'Conceit is folly.', 'Ghurar al-Hikam, Conciet- §3', 'wisdom'),
  ('اَلعُجْبُ رَأسُ الحَماقَةِ.', 'Conceit is the cornerstone of foolishness.', 'Ghurar al-Hikam, Conciet- §4', 'wisdom'),
  ('اَلعُجْبُ رَأسُ الجَهْلِ.', 'Conceit is the cornerstone of ignorance.', 'Ghurar al-Hikam, Conciet- §5', 'wisdom'),
  ('اَلعُجْبُ عُنْوانُ الحَماقَةِ.', 'Conceit is the symbol of foolishness.', 'Ghurar al-Hikam, Conciet- §6', 'wisdom'),
  ('اَلإعْجابُ يَمْنَعُ الاِزدِيادَ.', 'Self-admiration prevents growth.', 'Ghurar al-Hikam, Conciet- §7', 'wisdom'),
  ('اَلعُجْبُ أضَرُّ قَرين.', 'Conceit is the most harmful associate.', 'Ghurar al-Hikam, Conciet- §8', 'wisdom'),
  ('اَلإعْجابُ ضِدُّ الصَّوابِ.', 'Self-admiration is contrary to reason.', 'Ghurar al-Hikam, Conciet- §9', 'wisdom'),
  ('اَلعُجْبُ يُفْسِدُ العَقْلَ.', 'Conceit corrupts the intellect.', 'Ghurar al-Hikam, Conciet- §10', 'wisdom'),
  ('اَلمُعْجِبُ لاعَقْلَ لَهُ.', 'The self-admiring one has no intelligence.', 'Ghurar al-Hikam, The Self-Admiring one- §1', 'self-mastery'),
  ('لَيْسَ لِمُعْجِب رَأيٌ.', 'The self-admiring one has no [valid] opinion [as he never consults with anyone else].', 'Ghurar al-Hikam, The Self-Admiring one- §2', 'self-mastery'),
  ('اَلْعَجْزُ مَعَ لُزُومِ الخَيْـرِ خَيْـرٌ مِنَ القُدْرَةِ مَعَ رُكُوبِ الشَّـرِّ.', 'Inability accompanied by espousing goodness is better than power accompanied by embarking on evil.', 'Ghurar al-Hikam, Inability- §1', 'wisdom'),
  ('اَلعَجْزُ إضاعَةٌ.', 'Inability is waste.', 'Ghurar al-Hikam, Inability- §2', 'wisdom'),
  ('اَلعَجْزُ مَضْيَعَةٌ.', 'Inability is ruin.', 'Ghurar al-Hikam, Inability- §3', 'wisdom'),
  ('اَلعَجْزُ سَبَبُ التَّضْييعِ.', 'Inability is a cause of loss.', 'Ghurar al-Hikam, Inability- §4', 'wisdom'),
  ('اَلعَجْزُ شَـرُّ مَطِيَّة.', 'Inability is the worst riding mount.', 'Ghurar al-Hikam, Inability- §5', 'wisdom'),
  ('اَلعَجْزُ يُثْمِرُ الهَلَكَةَ.', 'Inability bears the fruit of destruction.', 'Ghurar al-Hikam, Inability- §6', 'wisdom'),
  ('اَلعَجْزُ يُطْمِعُ الأَعْداءَ.', 'Inability makes enemies covetous.', 'Ghurar al-Hikam, Inability- §7', 'wisdom'),
  ('ثَمَرَةُ العَجْزِ فَوْتُ الطَّلَبِ.', 'The fruit of inability is losing what is sought.', 'Ghurar al-Hikam, Inability- §8', 'wisdom'),
  ('اَلعَجْزُ اِشْتِغالُكَ بِالمَضْمُونِ لَكَ عَنِ المَفْرُوضِ عَلَيْكَ وتَرْكُ القَناعَةِ بِما أُوتيتَ.', 'Inability [and failure] is [in] occupying yourself with that which has been guaranteed for you instead of that which has been made obligatory upon you, and abandoning contentment with what you have been given.', 'Ghurar al-Hikam, Inability- §9', 'wisdom'),
  ('أعْجَزُ النّاسِ آمَنُهُمْ لِوُقُوعِ الحَوادِثِ، وهُجُومِ الأجَلِ.', 'The most powerless of people are those who consider themselves the safest from sudden events and [from] the onslaught of their deaths.', 'Ghurar al-Hikam, The powerless- §1', 'wisdom'),
  ('رُبَّما أدْرَكَ العاجِزُ حاجَتَهُ.', 'Sometimes the powerless one acquires what he needs.', 'Ghurar al-Hikam, The powerless- §2', 'wisdom'),
  ('اَلعَجيزَةُ أحَدُ الوَجْهَيْنِ.', 'The derriere is one of the two faces.', 'Ghurar al-Hikam, The Derriere- §1', 'wisdom'),
  ('اَلعَجَلَةُ مَذْمُومَةٌ في كُلِّ أمْر إلاّ فيما يَدْفَعُ الشَّـرَّ.', 'Haste is dispraised in every affair except in that which repels evil.', 'Ghurar al-Hikam, Haste and the hasty- §1', 'wisdom'),
  ('اِحْذَرُوا العَجَلَةَ فَإنَّها تُثْمِرُ النَّدامَةَ.', 'Beware of haste, for indeed it bears the fruit of regret.', 'Ghurar al-Hikam, Haste and the hasty- §2', 'wisdom'),
  ('إيّاكَ والعَجَلَ، فَإنَّهُ عُنْوانُ الفَوْتِ والنَّدَمِ.', 'Keep away from haste, for verily it is the symbol of loss and regret.', 'Ghurar al-Hikam, Haste and the hasty- §3', 'wisdom'),
  ('إيّاكَ والعَجَلَ فَإنَّهُ مَقْرُونٌ بِالعِثارِ.', 'Keep away from haste, for surely it is associated with error.', 'Ghurar al-Hikam, Haste and the hasty- §4', 'wisdom'),
  ('اَلعَجَلُ (العُجْبُ) يُوجِبُ العِثارَ.', 'Haste (or conceit) leads to error.', 'Ghurar al-Hikam, Haste and the hasty- §5', 'wisdom'),
  ('اَلعَجَلَةُ تَمْنَعُ الإصابَةَ.', 'Haste prevents one from [successfully] achieving his goal.', 'Ghurar al-Hikam, Haste and the hasty- §6', 'wisdom'),
  ('اَلعَجَلُ قَبْلَ الإمْكانِ يُوجِبُ الغُصَّةَ.', 'Making haste before [having the] ability, causes distress.', 'Ghurar al-Hikam, Haste and the hasty- §7', 'wisdom'),
  ('ثَمَرَةُ العَجَلَةِ العِثارُ.', 'The fruit of haste is error.', 'Ghurar al-Hikam, Haste and the hasty- §8', 'wisdom'),
  ('مِنَ الحُمْقِ العَجَلَةُ قَبْلَ الإمْكانِ.', 'Being hasty before [possessing the] ability is part of foolishness.', 'Ghurar al-Hikam, Haste and the hasty- §9', 'wisdom'),
  ('مَعَ العَجَلِ يَكْثُرُ الزَّلَلُ.', 'With haste, errors abound.', 'Ghurar al-Hikam, Haste and the hasty- §10', 'wisdom'),
  ('كُلُّ مَعْدُود مُنْتَقِصٌ.', 'Every denumerable thing can diminish.', 'Ghurar al-Hikam, The Denumerable- §1', 'wisdom'),
  ('خَيْـرُ الاِسْتِعْدادِ ما أُصْلِحَ بِهِ المَعادُ.', 'The best preparation is that by which one’s Hereafter is improved.', 'Ghurar al-Hikam, Readiness and Preparation- §1', 'wisdom'),
  ('تَخَفَّفُوا فَإنَّ الغايَةَ أمامَكُمْ، والسّاعَةَ مِنْ وَرائِكُمْ تَحْدُوكُمْ.', 'Lighten your burden, for indeed the goal is in front of you and time is behind you, driving you forward.', 'Ghurar al-Hikam, Readiness and Preparation- §2', 'wisdom'),
  ('تَخَفَّفُوا تَلْحَقُوا، فَإنَّما يُنْتَظَرُ بِأوَّلِكُمْ آخِرُكُمْ.', 'Lighten your burden so as to catch up [with those who are ahead you], for indeed the last among you are only being awaited by the first among you [who have preceded them].', 'Ghurar al-Hikam, Readiness and Preparation- §3', 'wisdom'),
  ('تَيَسَّرْ لِسَفَرِكَ، وشِمْ بَرْقَ النَّجاةِ، وارْحَلْ مَطاياَ التَّشْمير.', 'Prepare for your journey, keep your gaze on the flash of salvation and travel on swift [and girded] mounts [of good deeds].', 'Ghurar al-Hikam, Readiness and Preparation- §4', 'wisdom'),
  ('ثُوبُوا (تُوبُوا) مِنَ الغَفْلَةِ، وتَنَبَّهُوا مِنَ الرَّقْدَةِ، وتَأهَّبُوا لِلنُّقْلَةِ، وَتَزَوَّدُوا لِلرِّحْلَةِ.', 'Return from negligence, awake from slumber, prepare yourself for the move and gather provisions for the journey.', 'Ghurar al-Hikam, Readiness and Preparation- §5', 'wisdom'),
  ('مَنِ اسْتَعَدَّ لِسَفَرِهِ قَرَّ عَيْناً بِحَضَرِهِ.', 'One who has prepared for his journey is delighted upon his arrival.', 'Ghurar al-Hikam, Readiness and Preparation- §6', 'wisdom'),
  ('اِرْتَدْ لِنَفْسِكَ قَبْلَ يَوْمِ نُزُولِكَ ووَطِّ المَنْزِلَ قَبْلَ حُلُولِكَ.', 'Select your abode for yourself before the day of your landing and prepare your dwelling before your arrival.', 'Ghurar al-Hikam, Readiness and Preparation- §7', 'wisdom'),
  ('اَلعَدْلُ أفْضَلُ السِّياسَتَيْنِ.', 'Justice is the better of the two policies.', 'Ghurar al-Hikam, Justice and the just- §1', 'justice'),
  ('اَلعَدْلُ رَأسُ الإيمانِ، وجَمّاعُ الإحْسانِ.', 'Justice is the cornerstone of faith and the accumulator of benevolence.', 'Ghurar al-Hikam, Justice and the just- §2', 'justice'),
  ('اَلْعَدْلُ قِوامُ الرَّعِيَّةِ، وجَمالُ الوُلاةِ.', 'Justice is the mainstay of the populace and the splendour of the rulers.', 'Ghurar al-Hikam, Justice and the just- §3', 'justice'),
  ('اَلعَدْلُ أنَّكَ إذا ظُلِمْتَ أنْصَفْتَ، والفَضْلُ أنَّكَ إذا قَدَرْتَ عَفَوْتَ.', 'Justice means that you act equitably when you are oppressed, and kindness means that when you gain authority, you forgive.', 'Ghurar al-Hikam, Justice and the just- §4', 'justice'),
  ('اِعْدِلْ تَحْكُمْ.', 'Be just and you will rule.', 'Ghurar al-Hikam, Justice and the just- §5', 'justice'),
  ('اِعْدِلْ تَمْلِكَ.', 'Be just and you will rule.', 'Ghurar al-Hikam, Justice and the just- §6', 'justice'),
  ('اِعْدِلْ تَدُمْ لَكَ القُدْرَةُ.', 'Be just and your power will last.', 'Ghurar al-Hikam, Justice and the just- §7', 'justice'),
  ('اِسْتَعِنْ عَلَى العَدْلِ بِحُسْنِ النِّيَّةِ فِي الرَّعيَّةِ، وقِلَّةِ الطَّمَعِ، وكَثْرَةِ الوَرَعِ.', 'Have recourse to justice with good intention for the populace, reduced covetousness and increased piety.', 'Ghurar al-Hikam, Justice and the just- §8', 'justice'),
  ('أسْنَى المَواهِبِ العَدْلُ.', 'The loftiest of endowments is justice.', 'Ghurar al-Hikam, Justice and the just- §9', 'justice'),
  ('أحْسَنُ العَدْلِ نُصْرَةُ المَظْلُومِ.', 'The best [form of] justice is assisting the oppressed.', 'Ghurar al-Hikam, Justice and the just- §10', 'justice'),
  ('خَيْـرُ الأُمُورِ (هذِهِ الاُمَّةِ) النَّمَطُ الأوْسَطُ، إلَيْهِ يَرْجِعُ الغالي وبِهِ يَلْحَقُ التّالي.', 'The best affair (of this ummah ) is [taking] the middle course; to it return those who have gone to the extreme and with it join those who have lagged behind.', 'Ghurar al-Hikam, The middle course- §1', 'wisdom'),
  ('اَلشَّدُّ بِالقِدِّ، وَلامُقارِنَةُ الضِّدِّ.', 'Being bound by straps is better [and more preferable] than accompanying the adversary.', 'Ghurar al-Hikam, Enmity and the Enemy- §1', 'wisdom'),
  ('عِلَّةُ المُعاداةِ قِلَّةُ المُبالاتِ.', 'The cause of enmity is lack of empathy [and consideration for others].', 'Ghurar al-Hikam, Enmity and the Enemy- §2', 'wisdom'),
  ('عَداوَةُ الأقارِبِ أمَرٌّ مِنْ لَسْعِ العَقارِبِ.', 'Enmity of near ones is more unpleasant than the sting of the scorpions.', 'Ghurar al-Hikam, Enmity and the Enemy- §3', 'wisdom'),
  ('كَثْرَةُ العَداوَةِ عَناءُ القُلُوبِ.', 'Too much enmity is disquieting for the hearts.', 'Ghurar al-Hikam, Enmity and the Enemy- §4', 'wisdom'),
  ('مَنْ عانَدَ النّاسَ مَقَتُوهُ.', 'Whoever stubbornly opposes the people, they hate him.', 'Ghurar al-Hikam, Enmity and the Enemy- §5', 'wisdom'),
  ('مَنْ أظْهَرَ عَداوَتَهُ قَلَّ كَيْدُهُ.', 'Whoever manifests his enmity, his stratagems are reduced.', 'Ghurar al-Hikam, Enmity and the Enemy- §6', 'wisdom'),
  ('مَنْ غالَبَ الضِّدَّ رَكِبَ الجِدَّ.', 'One who tries to overcome his adversary has embarked on a struggle.', 'Ghurar al-Hikam, Enmity and the Enemy- §7', 'wisdom'),
  ('مَنْ قارَنَ ضِدَّهُ ضَنِيَ جَسَدَهُ.', 'One who accompanies his adversary exhausts his body.', 'Ghurar al-Hikam, Enmity and the Enemy- §8', 'wisdom'),
  ('مَنِ اسْتَصْلَحَ عَدُوَّهُ زادَ في عَدَدِهِ.', 'One who reforms [and reconciles with] his enemy increases in his number.', 'Ghurar al-Hikam, Enmity and the Enemy- §9', 'wisdom'),
  ('مَنْ لا يُبالِكَ فَهُوَ عَدُوُّكَ.', 'Whoever is unconcerned about you, then he is your enemy.', 'Ghurar al-Hikam, Enmity and the Enemy- §10', 'wisdom'),
  ('اَلاِسْتِغْناءُ عَنِ العُذْرِ أعَزُّ مِنَ الصِّدْقِ.', 'Being needless of offering an excuse is more honourable than truthfulness [in your excuse].', 'Ghurar al-Hikam, Apologizing and offering excuses- §1', 'wisdom'),
  ('اَلإعْذارُ يُوجِبُ الاِعْتِذارُ.', 'Apologizing necessitates pardoning.', 'Ghurar al-Hikam, Apologizing and offering excuses- §2', 'wisdom'),
  ('إعادَةُ الاِعْتِذارِ تَذْكِيرٌ بِالذَّنْبِ.', 'Repeating the apology is a reminder of the sin.', 'Ghurar al-Hikam, Apologizing and offering excuses- §3', 'wisdom'),
  ('مَنِ اعْتَذَرَ مِنْ غَيْرِ ذَنْب فَقَدْ أوْجَبَ عَلى نَفْسهِ الذَّنْبَ.', 'One who seeks pardon without having sinned has imposed the sin upon his soul.', 'Ghurar al-Hikam, Apologizing and offering excuses- §4', 'wisdom'),
  ('مَنِ اعْتَرَفَ بِالجَريرَةِ اِسْتَحقَّ المَغْفِرَةَ.', 'One who admits his wrongdoing deserves forgiveness.', 'Ghurar al-Hikam, Apologizing and offering excuses- §5', 'wisdom'),
  ('مَنْ أحْسَنَ الاِعْتِذارَ اِسْتَحَقَّ الاِغْتِفارَ.', 'One who apologizes in a befitting manner deserves to be forgiven.', 'Ghurar al-Hikam, Apologizing and offering excuses- §6', 'wisdom'),
  ('مَنِ اعْتَذَرَ فَقدِ اسْتَقالَ.', 'One who apologizes has sought pardon.', 'Ghurar al-Hikam, Apologizing and offering excuses- §7', 'wisdom'),
  ('ما أذْنَبَ مَنِ اعْتَذَرَ.', 'He who seeks pardon has not sinned.', 'Ghurar al-Hikam, Apologizing and offering excuses- §8', 'wisdom'),
  ('نِعْمَ الشَّفيعُ الاِعْتِذارُ.', 'How good an intercessor seeking pardon is!', 'Ghurar al-Hikam, Apologizing and offering excuses- §9', 'wisdom'),
  ('لاتَعْتَذِرْ إلى مَنْ يُحِبُّ أنْ لايَجِدَلَكَ عُذْراً.', 'Do not offer an excuse to the one who would like to find you without an excuse.', 'Ghurar al-Hikam, Apologizing and offering excuses- §10', 'wisdom'),
  ('حَصِّنُوا الأعْراضَ بِالأمْوالِ.', 'Safeguard [your] reputations with wealth.', 'Ghurar al-Hikam, Dignity and Reputation- §1', 'wisdom'),
  ('ما صانَ الأعْراضُ كَالإعْراضِ عَنِ الدَّنايا وسُوءِ الأغْراضِ.', 'Nothing preserves reputations like turning away from vile traits and evil objectives.', 'Ghurar al-Hikam, Dignity and Reputation- §2', 'wisdom'),
  ('وَقُّوا أعْراضَكُمْ بِبَذْلِ أمْوالِكُمْ.', 'Protect your reputations by spending your wealth generously.', 'Ghurar al-Hikam, Dignity and Reputation- §3', 'wisdom'),
  ('وُفُورُ الأمْوالِ بِانْتِقاصِ الأعْراضِ لُؤْمٌ.', 'Abundance of wealth [that is attained] by the derogation of reputations is ignobility.', 'Ghurar al-Hikam, Dignity and Reputation- §4', 'wisdom'),
  ('وُفُورُ الدّينِ والعِرضِ بِابْتِذالِ الأمْوالِ مَوْهِبَةٌ سَنِيَّةٌ.', 'Plenitude of religion and dignity [that is acquired] through generously spending wealth is a sublime gift.', 'Ghurar al-Hikam, Dignity and Reputation- §5', 'wisdom'),
  ('وَقِّ عِرْضَكَ بِعَرَضِكَ تُـكْرَمْ، وتَفَضَّلْ تُخْدَمْ، واحْلُمْ تُقَدَّمْ.', 'Protect your dignity with your worldly possessions and you will be honoured, do good to others and you will be served, show clemency and you will be put forward (or you will advance).', 'Ghurar al-Hikam, Dignity and Reputation- §6', 'wisdom'),
  ('وُفُورُ العِرْضِ بِابْتِذالِ المالِ، وَصَلاحُ الدّينِ بِإفْسادِ الدُّنيا.', 'The plenitude of dignity is [attained] through the generous spending of wealth, and the uprightness of religion is [realized] through devaluing this world.', 'Ghurar al-Hikam, Dignity and Reputation- §7', 'wisdom'),
  ('ما حُصِّنَتِ الأعْراضُ بِمِثْلِ البَذْلِ.', 'Nothing safeguards reputations like spending generously.', 'Ghurar al-Hikam, Dignity and Reputation- §8', 'wisdom'),
  ('لاتَجْعَلْ عِرْضَكَ غَرَضاً لِقَوْلِ كُلِّ قائِل.', 'Do not make your dignity a subject of the speech of every speaker [by engaging in shameful deeds].', 'Ghurar al-Hikam, Dignity and Reputation- §9', 'wisdom'),
  ('مَنْ بَذَلَ عِرْضَهُ ذَلَّ.', 'One who sacrifices his dignity is abased.', 'Ghurar al-Hikam, Dignity and Reputation- §10', 'wisdom'),
  ('اَلمَعْرِفَةُ دَهَشٌ، والخُلُوُّ مِنْها غَطَشٌ.', 'Cognizance is perplexity and being devoid of it is dim-sightedness.', 'Ghurar al-Hikam, Cognizance- §1', 'wisdom'),
  ('أفْضَلُ المَعْرِفَةِ، مَعْرِفَةُ الإنْسانِ نَفْسَهُ.', 'The most excellent cognizance is the human being’s cognizance of himself.', 'Ghurar al-Hikam, Cognizance- §2', 'wisdom'),
  ('أكْثَرُ النّاسِ مَعْرِفَةً لِنَفْسِهِ أخْوَفُهُمْ لِرَبِّهِ.', 'Of all the people, the most cognizant of himself is the most fearful of his Lord.', 'Ghurar al-Hikam, Cognizance- §3', 'wisdom'),
  ('أعْرَفُ النّاسِ بِالزَّمانِ مَنْ لَمْ يَتَعَجَّبْ مِنْ أحْداثِهِ.', 'The person most cognizant of his age is the one who is not astonished by its events.', 'Ghurar al-Hikam, Cognizance- §4', 'wisdom'),
  ('اَلمَعْرِفَةُ نُورُ القَلْبِ.', 'Cognizance is the light of the heart.', 'Ghurar al-Hikam, Cognizance- §5', 'wisdom'),
  ('اَلمَعْرِفَةُ اَلفَوْزُ بِالقُدْسِ.', 'Cognizance is the successful attainment of [purification and] the sacred.', 'Ghurar al-Hikam, Cognizance- §6', 'wisdom'),
  ('اَلمَعْرِفَةُ بُرْهانُ الفَضْلِ(النُّبْلِ).', 'Cognizance is the evidence of excellence (or nobility).', 'Ghurar al-Hikam, Cognizance- §7', 'wisdom'),
  ('ثَمَرَةُ المََعْرِفَةِ العُزُوفُ عَنْ دارِ الفَناءِ.', 'The fruit of cognizance is becoming averse to the evanescent abode.', 'Ghurar al-Hikam, Cognizance- §8', 'wisdom'),
  ('رُبَّ مَعْرِفَة أدَّتْ إلى تَضليل.', 'Many a cognizance leads to misguidance.', 'Ghurar al-Hikam, Cognizance- §9', 'wisdom'),
  ('عُرِفَ اللّهُ سُبْحانَهُ بِفَسْخِ العَزائِمِ، وحَلِّ العُقُودِ وكَشْفِ الضُّـرِّ، وَالبَلِيَّةِ عَمَّنْ أخْلَصَ لَهُ النِّيَّةَ.', 'Allah is known by the revocation of resolutions, the undoing of binds and the relieving of hardship and affliction from the one whose intention is sincere.', 'Ghurar al-Hikam, Cognizance- §10', 'wisdom'),
  ('كُلُّ عارِف مَهْمُومٌ.', 'Every cognizant one is sorrowful.', 'Ghurar al-Hikam, The Cognizant- §1', 'wisdom'),
  ('كُلُّ عارِف عائِفٌ.', 'Every cognizant one is averse [to the temporary pleasures of this world].', 'Ghurar al-Hikam, The Cognizant- §2', 'wisdom'),
  ('كَيْفَ يَعْرِفُ غَيْرَهُ مَنْ يَجْهَلُ نَفْسَهُ؟!', 'How can one know others when he is ignorant of himself?!', 'Ghurar al-Hikam, The Cognizant- §3', 'wisdom'),
  ('اَلعارِفُ مَنْ عَرَفَ نَفْسَهُ فَأَعْتَقَها، ونَزَّهَها عَنْ كُلِّ ما يُبَعِّدُها وَيُوبِقُها.', 'The cognizant one is he who knows his soul and thus frees it and purifies it from all that distances it [from the Truth] and destroys it.', 'Ghurar al-Hikam, The Cognizant- §4', 'wisdom'),
  ('اَلعارِفُ وَجْهُهُ مُسْتَبْشِرٌ مُتَبَسِّمٌ، وقَلْبُهُ وَجِلٌ مَحْزُونٌ.', 'The face of the cognizant one is cheerful and smiling while his heart is fearful and sad.', 'Ghurar al-Hikam, The Cognizant- §5', 'wisdom'),
  ('مَنْ تَعزَّزَ بِاللّهِ لَمْ يُذِلَّهُ سُلْطانٌ.', 'One who is given honour by Allah cannot be humiliated by any king.', 'Ghurar al-Hikam, Glory and the Honored One- §1', 'wisdom'),
  ('مَنِ اعْتَزَّ بِغَيْرِ اللّهِ ذَلَّ.', 'One who seeks honour through [anyone] other than Allah is abased.', 'Ghurar al-Hikam, Glory and the Honored One- §2', 'wisdom'),
  ('مَنِ اعْتَزَّ بِغَيْرِ اللّهِ أهْلَكَهُ العِزُّ.', 'One who seeks glory through [anyone] other than Allah is destroyed by [the] glory.', 'Ghurar al-Hikam, Glory and the Honored One- §3', 'wisdom'),
  ('مَنْ يَطْلُبِ العِزَّ بِغَيْرِ حَقّ يَذِلُّ.', 'One who seeks glory without having any right to it gets humiliated.', 'Ghurar al-Hikam, Glory and the Honored One- §4', 'wisdom'),
  ('مَنِ اعْتَزَّ بِغَيْرِ الحَقِّ أذَلَّهُ اللّهُ بِالحَقِّ.', 'One who seeks glory through [anything] other than truth, Allah humiliates him with [the] truth.', 'Ghurar al-Hikam, Glory and the Honored One- §5', 'wisdom'),
  ('لاعِزَّ إلاّ بِالطّاعَةِ.', 'There is no glory except through obedience [to Allah].', 'Ghurar al-Hikam, Glory and the Honored One- §6', 'wisdom'),
  ('اَلعَزيزُ مَنِ اعْتَزَّ بِالطّاعَةِ.', 'The honoured is the one who becomes honoured through obedience [to Allah].', 'Ghurar al-Hikam, Glory and the Honored One- §7', 'wisdom'),
  ('إذا طَلَبْتَ العِزَّ فَاطْلُبْهُ بِالطّاعَةِ.', 'When you seek glory, then seek it through obedience [to Allah].', 'Ghurar al-Hikam, Glory and the Honored One- §8', 'wisdom'),
  ('ما عَزَّ مَنْ ذَلَّ جيرانُهُ.', 'He whose neighbours are abased is not honoured.', 'Ghurar al-Hikam, Glory and the Honored One- §9', 'wisdom'),
  ('اَلعِزُّ إدْراكُ الاِنْتِصارِ.', 'Glory is the attainment of [the power to exact] revenge.', 'Ghurar al-Hikam, Glory and the Honored One- §10', 'wisdom'),
  ('فِي اعْتِزالِ أبْناءِ الدُّنيا جِماعُ الصَّلاحِ.', 'In seclusion from the worldly people there is accumulation of goodness.', 'Ghurar al-Hikam, Seclusion- §1', 'wisdom'),
  ('مَنِ اعْتَزَلَ سَلِمَ.', 'One who secludes [from the people] himself remains safe.', 'Ghurar al-Hikam, Seclusion- §2', 'wisdom'),
  ('مَنِ اخْتَبـَرَ اِعْتَزَلَ.', 'One who tests [the people who love this world] secludes himself [from them].', 'Ghurar al-Hikam, Seclusion- §3', 'wisdom'),
  ('مَنِ اعْتَزَلَ حَسُنَتْ زَهادَتُهُ.', 'One who secludes himself, his indifference towards the pleasures of this world becomes strong.', 'Ghurar al-Hikam, Seclusion- §4', 'wisdom'),
  ('مَنِ اعْتَزَلَ سَلِمَ وَرَعُهُ.', 'Whoever secludes himself, his piety remains safeguarded?', 'Ghurar al-Hikam, Seclusion- §5', 'wisdom'),
  ('مَنِ اعْتَزَلَ النّاسَ سَلِمَ مِنْ شَرِّهِمْ.', 'One who secludes himself from the people is safe from their evil.', 'Ghurar al-Hikam, Seclusion- §6', 'wisdom'),
  ('نِعْمَ العِبادَةُ العُزْلَةُ.', 'How good a worship seclusion is!', 'Ghurar al-Hikam, Seclusion- §7', 'wisdom'),
  ('مَنِ انْفَرَدَ عَنِ النّاسِ صانَ دينَهُ.', 'One who isolates himself from the people preserves his religion.', 'Ghurar al-Hikam, Seclusion- §8', 'wisdom'),
  ('مَنِ انْفَرَدَ عَنِ النّاسِ أَنِسَ بِاللّهِ سُبْحانَهُ.', 'One who isolates himself from the people becomes intimate with Allah, the Glorified.', 'Ghurar al-Hikam, Seclusion- §9', 'wisdom'),
  ('اَلسَّلامَةُ فِي التَّفَرُّدِ.', 'Safety is in solitude.', 'Ghurar al-Hikam, Seclusion- §10', 'wisdom'),
  ('مَنْ أظْهَرَ عَزْمَهُ بَطَلَ حَزْمُهُ.', 'Whoever reveals his decision [to others], his judiciousness gets nullified.', 'Ghurar al-Hikam, Resolve- §1', 'wisdom'),
  ('مَنْ ساءَ عَزْمُهُ رَجَعَ عَلَيْهِ سَهْمُهُ.', 'Whoever resolves to do evil, his arrow returns to him.', 'Ghurar al-Hikam, Resolve- §2', 'wisdom'),
  ('لاتَعْزِمْ عَلى مالَمْ تَسْتَبِنِ الرُّشْدَ فيهِ.', 'Do not resolve upon that in which you find no clear guidance.', 'Ghurar al-Hikam, Resolve- §4', 'wisdom'),
  ('لاخَيْرَ في عَزْم بِلا حَزْم.', 'There is no good in [making a] resolution without determination.', 'Ghurar al-Hikam, Resolve- §5', 'wisdom'),
  ('اَلعُسْرُ يَشينُ الأخْلاقَ، وَيُوحِشُ الرِّفاقَ.', 'Adversity degrades morals and alienates friends.', 'Ghurar al-Hikam, Adversity- §1', 'wisdom'),
  ('العُسْرُ لُؤْمٌ.', 'Adversity is a reproach.', 'Ghurar al-Hikam, Adversity- §2', 'wisdom'),
  ('اَلعُسْرُ يُفْسِدُ الأخْلاقَ.', 'Adversity corrupts morals.', 'Ghurar al-Hikam, Adversity- §3', 'wisdom'),
  ('مُعاشَرَةُ ذَوِي الفَضائِلِ حَياةُ القُلُوبِ.', 'ocial interaction with people of merits is enlivening for the hearts.', 'Ghurar al-Hikam, Social Interaction and mingling- §1', 'purpose'),
  ('لايَكُنْ أهْلُكَ وذُو وُدِّكَ (ذُوُوكَ)أشْقَى النّاسِ بِكَ.', 'Let not your family or those whom you love be the most miserable of people because of you.', 'Ghurar al-Hikam, Social Interaction and mingling- §2', 'purpose'),
  ('لاتُوحِشَنَّ امْرَءً يَسُوءُكَ فِراقُهُ.', 'Do not alienate a person whose separation will harm you.', 'Ghurar al-Hikam, Social Interaction and mingling- §3', 'purpose'),
  ('يُبْتَلى مُخالِطُ النّاسِ بِقَرينِ السُّوءِ، ومداجاةِ العَدُوِّ.', 'The one who mingles with people is afflicted by the evil associate and the hypocrisy of the enemy.', 'Ghurar al-Hikam, Social Interaction and mingling- §4', 'purpose'),
  ('أبْقِ يُبْقَ عَلَيْكَ.', 'Preserve [the respect of others] and your respect will be preserved.', 'Ghurar al-Hikam, Social Interaction and mingling- §5', 'purpose'),
  ('اِخْلِطِ الشِدَّةَ بِرِفْق، وارْفُقْ ما كانَ الرِّفْقُ أوْفَقَ.', 'Mix sternness with gentleness, and be gentle as long as gentleness is more befitting.', 'Ghurar al-Hikam, Social Interaction and mingling- §6', 'purpose'),
  ('أَشْعِرْ قَلْبَكَ الرَّحْمَةَ لَجَميعِ النّاسِ والإحْسانِ إلَيْهِمْ، وَلاتُنِلْهُمْ حَيْفاً، وَلاتَـكُنْ عَلَيْهِمْ سَيْفاً.', 'Imbibe your heart with mercy for all the people and kindness towards them, and do not oppress them or be [like] a sword over them.', 'Ghurar al-Hikam, Social Interaction and mingling- §7', 'purpose'),
  ('إسْتَقْبِـحْ مِنْ نَفْسِكَ ما تَسْتَقْبِحُهُ مِنْ غَيْرِكَ، وارْضَ لِلنّاسِ بِما تَرْضاهُ لِنَفْسِكَ.', 'Loathe from yourself what you loathe from others and like for people what you like for yourself.', 'Ghurar al-Hikam, Social Interaction and mingling- §9', 'purpose'),
  ('قِلَّةُ الخُلْطَةِ تَصُونُ الدّينَ، وتُريحُ مِنْ مُقارَنَةِ الأشْرارِ.', 'Reduced mingling preserves religion and relieves one from having to associate with wicked people.', 'Ghurar al-Hikam, Social Interaction and mingling- §10', 'purpose'),
  ('أنْصِفِ النّاسَ مِنْ نَفْسِكَ، وأهْلِكَ، وَخاصَّتِكَ، ومَنْ لَكَ فيهِ هَوًى، وأعْدِلْ فِي العَدُوِّ والصَّدِيقِ.', 'Be equitable to people over yourself, your family, your near ones and those from whom you desire something, and be just with both enemy and friend.', 'Ghurar al-Hikam, Social Interaction and mingling- §11', 'purpose'),
  ('قَدْ خَرَقَتِ الشَّهَواتُ عَقْلَهُ، وأماتَتْ قَلْبَهُ، ووَلَّهَتْ عَلَيْها نَفْسَهُ.', 'Desires have rent asunder his intellect and killed his heart while his mind is infatuated with them.', 'Ghurar al-Hikam, The Lover- §1', 'wisdom'),
  ('مَنِ اعْتَصَمَ بِاللّهِ نَجّاهُ.', 'Whoever seeks protection from Allah, He saves him.', 'Ghurar al-Hikam, Seeking protection from Allah- §1', 'wisdom'),
  ('مَنِ اعْتَصَمَ بِاللّهِ لَمْ يَضُـرَّهُ شَيْطانٌ.', 'One who seeks protection from Allah is not harmed by Satan.', 'Ghurar al-Hikam, Seeking protection from Allah- §2', 'wisdom'),
  ('مَنِ اعْتَصَمَ بِاللّهِ عَزَّ مَطْلَبُهُ.', 'Whoever clings to Allah, his wish is fulfilled [and his goal is achieved].', 'Ghurar al-Hikam, Seeking protection from Allah- §3', 'wisdom'),
  ('اَلْجِئْ نَفْسَكَ فِي الأُمُورِ كُلِّها إلى إلهِكَ، فَإنَّكَ تُلْجِئُها إلى كَهْف حَريز.', 'Entrust your soul, in all your affairs, to your Lord, for indeed [by your so doing] you are turning to a secure refuge.', 'Ghurar al-Hikam, Seeking protection from Allah- §4', 'wisdom'),
  ('اِعْتَصِمْ في أحْوالِكَ كُلِّها بِاللّهِ، فَإنَّكَ تَعْتَصِمُ مِنْهُ سُبْحانَهُ بِمانِع عَزيز.', 'Seek protection with Allah in all situations, for indeed you will be clinging to One, Glorified be He, who is a powerful protector.', 'Ghurar al-Hikam, Seeking protection from Allah- §5', 'wisdom'),
  ('عَلَيْكَ بِالاِعْتِصامِ بِاللّهِ في كُلِّ أُمُورِكَ، فَإنَّها عِصْمَةٌ مِنْ كُلِّ شَـيْء.', 'You must seek protection from Allah in all your affairs, for indeed this is a [means of] protection from everything.', 'Ghurar al-Hikam, Seeking protection from Allah- §6', 'wisdom'),
  ('اَلعِصْمَةُ نِعْمَةٌ.', 'Preserving oneself from sin is a blessing.', 'Ghurar al-Hikam, Preserving oneself from sin- §1', 'forgiveness'),
  ('مَنْ أُلْهِمَ العِصْمَةَ أمِنَ الزَّلَلَ.', 'One who is inspired with preservation [from sin] is saved from error.', 'Ghurar al-Hikam, Preserving oneself from sin- §2', 'forgiveness'),
  ('مِنَ العِصْمَةِ تَعَذُّرُ المَعاصي.', 'Being unable to sin is [also] a form of preservation [against sin].', 'Ghurar al-Hikam, Preserving oneself from sin- §3', 'forgiveness'),
  ('رُبَّ عَطَب تَحْتَ طَلَب.', 'Sometimes there is destruction is under what is sought.', 'Ghurar al-Hikam, Destruction and damage- §1', 'wisdom'),
  ('رُكُوبُ المَعاطِبِ عُنْوانُ الحَماقَةِ.', 'Embarking on acts that lead to [places of] destruction is the symbol of foolishness.', 'Ghurar al-Hikam, Destruction and damage- §2', 'wisdom'),
  ('رُبَّ عاطِب بَعْدَ السَّلامَةِ.', 'Many a person is destroyed after having remained safe [and survived a disaster].', 'Ghurar al-Hikam, Destruction and damage- §3', 'wisdom'),
  ('مَنْ كَثُرَتْ عَواطِفُهُ (عَوارِفُهُ) كَثُرَتْ مَعارِفُهُ.', 'One whose empathy (or kind acts) increases, his acquaintances increases.', 'Ghurar al-Hikam, Empathy- §1', 'wisdom'),
  ('مَنْ أعْظَمَكَ لإكْثارِكَ، اِسْتَقَلَّكَ عِنْدَ إقْلالِكَ.', 'One who respects you because of your opulence, belittles you in your [time of] poverty.', 'Ghurar al-Hikam, Respect- §1', 'wisdom'),
  ('لاتَسْتَعْظِمَنَّ أحَداً حَتّى تَسْتَكْشِفَ مَعْرِفَتَهُ.', 'Never regard anyone as venerable until you discover the level of his cognizance.', 'Ghurar al-Hikam, Respect- §2', 'wisdom'),
  ('اَلعِفافُ يَصُونُ النَّفْسَ، ويُنَزِّهُها عَنِ الدَّنايا.', 'Chastity preserves the soul and purifies it from vile demerits.', 'Ghurar al-Hikam, Chastity- §1', 'wisdom'),
  ('اَلعِفَّةُ تُضَعِّفُ الشَّهْوَةَ.', 'Chastity weakens lust.', 'Ghurar al-Hikam, Chastity- §2', 'wisdom'),
  ('اَلعِفافُ زَهادَةٌ.', 'Chastity is renunciation [of worldly pleasures].', 'Ghurar al-Hikam, Chastity- §3', 'wisdom'),
  ('اَلعِفَّةُ أفْضَلُ (أصْلُ) الفُتُوَّةِ.', 'Chastity is the best (or the root of) magnanimity.', 'Ghurar al-Hikam, Chastity- §4', 'wisdom'),
  ('اَلعِفافُ أفْضَلُ شيمَة.', 'Chastity is the best trait.', 'Ghurar al-Hikam, Chastity- §5', 'wisdom'),
  ('اَلعِفَّةُ شيمَةُ الأكْياسِ.', 'Chastity is the trait of the sagacious.', 'Ghurar al-Hikam, Chastity- §6', 'wisdom'),
  ('اَلعِفَّةُ رَأْسُ كُلِّ خَيْـر.', 'Chastity is the cornerstone of goodness.', 'Ghurar al-Hikam, Chastity- §7', 'wisdom'),
  ('اَلكَفُّ عَمّا في أيْدِي النّاسِ عِفَّةٌ، وكِبَرُ هِمَّة.', 'Restraining oneself from [coveting] that which people possess is chastity and high-mindedness.', 'Ghurar al-Hikam, Chastity- §8', 'wisdom'),
  ('(أهْلُ) اَلعَفافُِ أشْرَفُ الأشْرافِ.', 'The people of chastity are the most honourable of the honourables.', 'Ghurar al-Hikam, Chastity- §9', 'wisdom'),
  ('بِالعَفافِ تَزْكُوالأعْمالُ.', 'Through chastity actions become purified.', 'Ghurar al-Hikam, Chastity- §10', 'wisdom'),
  ('اَلعَوافي إذا دامَتْ جُهِلَتْ، وإذا فُقِدَتْ عُرِفَتْ.', 'Good health is such that when it lasts, it is disregarded and when it is lost, its value is known.', 'Ghurar al-Hikam, Well-being- §1', 'wisdom'),
  ('إنَّ العافِيَةَ فِي الدّينِ والدُّنيا، لَنِعْمَةٌ جَليلَةٌ(جَميلَةٌ)، ومَوْهِبَةٌ جَزيلَةٌ.', 'Verily well-being in religion and [in] this world is a great (or beautiful) blessing and a bountiful gift.', 'Ghurar al-Hikam, Well-being- §2', 'wisdom'),
  ('اَلعافِيَةُ أهْنَى النِّعَمِ.', 'Well-being is the most pleasant of blessings.', 'Ghurar al-Hikam, Well-being- §3', 'wisdom'),
  ('لاعَيْشَ أهْنَأُ مِنَ العافِيَةِ.', 'There is no life more pleasant than [life] with good health.', 'Ghurar al-Hikam, Well-being- §4', 'wisdom'),
  ('لالِباسَ أفْضَلُ مِنَ العافِيَةِ.', 'There is no attire better than well-being.', 'Ghurar al-Hikam, Well-being- §5', 'wisdom'),
  ('كُلُّ عافِيَة إلى بَلاء.', 'Every well-being is [headed] towards affliction.', 'Ghurar al-Hikam, Well-being- §6', 'wisdom'),
  ('اَلعافِيَةُ أفْضَلُ اللِّباسَيْنِ.', 'Well-being is the better of the two attires.', 'Ghurar al-Hikam, Well-being- §7', 'wisdom'),
  ('بِالعافِيَةِ تُوجَدُ لَذَّةُ الحَياةِ.', 'Through well-being, life becomes pleasurable.', 'Ghurar al-Hikam, Well-being- §8', 'wisdom'),
  ('ثَوْبُ العافِيَةِ أهْنَأُ المَلابِسِ.', 'The garment of well-being is the most pleasant of attires.', 'Ghurar al-Hikam, Well-being- §9', 'wisdom'),
  ('دَوامُ العافِيَةِ أهْنَأُ عَطِيَّة، وأفْضَلُ قِسْم.', 'Lasting good health is the most pleasant gift and the best portion.', 'Ghurar al-Hikam, Well-being- §10', 'wisdom'),
  ('اَلمُبادَرَةُ إلى العَفْوِ مِنْ أخْلاقِ الكِرامِ.', 'Hastening to forgive is from the morals of the honourable.', 'Ghurar al-Hikam, Forgiveness and pardon- §1', 'forgiveness'),
  ('اَلعَفْوُ أعْظَمُ الفَضِيلَتَيْنِ.', 'Forgiveness is the greater of the two virtues.', 'Ghurar al-Hikam, Forgiveness and pardon- §2', 'forgiveness'),
  ('أُعْفُ تُنْصَرْ.', 'Forgive and you will be supported.', 'Ghurar al-Hikam, Forgiveness and pardon- §3', 'forgiveness'),
  ('أقِلْ تُقَلْ.', 'Pardon and you will be pardoned.', 'Ghurar al-Hikam, Forgiveness and pardon- §4', 'forgiveness'),
  ('أحْسِنْ إلى مَنْ أساءَ إلَيْكَ، واعْفُ عَمَّنْ جَنى عَلَيْكَ.', 'Do good to the one who does evil to you and forgive the one who wrongs you.', 'Ghurar al-Hikam, Forgiveness and pardon- §5', 'forgiveness'),
  ('ِاغْتَفِرْ زَلَّةَ صَديقِكَ، يُزَكِّكَ عَدُوُّكَ.', 'Forgive the mistake of your friend, [and] your enemy will consider you to be virtuous.', 'Ghurar al-Hikam, Forgiveness and pardon- §6', 'forgiveness'),
  ('اِغْتَفِرْ ما أغْضَبَكَ لِما أرْضاكَ.', 'Forgive that which angers you for the sake of that which pleases you.', 'Ghurar al-Hikam, Forgiveness and pardon- §7', 'forgiveness'),
  ('اِقْبَلْ أعْذارَ النّاسِ، تَسْتَمْتِعْ بِإخائِهِمْ، والقَهُمْ بِالبِشْرِ، تُمِتْ أضْغانَهُمْ.', 'Accept the excuses of people and you will enjoy their brotherhood; meet them with cheerfulness and you will cause their malice [and grudges against you] to die away.', 'Ghurar al-Hikam, Forgiveness and pardon- §9', 'forgiveness'),
  ('أقيلُوا ذَوِى المُروُءاتِ عَثَراتِهِمْ، فَما يَعْثِرُ مِنْهُمْ عاثِرٌ إلاّ ويَدُ اللّهِ تَرْفَعُهُ.', 'Pardon the errors of the magnanimous, for none of them slips but that the Hand of Allah lifts him [back] up.', 'Ghurar al-Hikam, Forgiveness and pardon- §10', 'forgiveness'),
  ('اَلعَفْوُ أحْسَنُ الإحْسانِ.', 'Forgiveness is the best of favours.', 'Ghurar al-Hikam, Forgiveness and pardon- §11', 'forgiveness'),
  ('لِكُلِّ أمْر عاقِبَةٌ حُلْوَةٌ أوْ مُرَّةٌ.', 'For every matter there is an outcome, [be it] sweet or bitter.', 'Ghurar al-Hikam, Outcomes- §1', 'wisdom'),
  ('مَنِ انْتَظَرَ العَواقِبَ سَلِمَ.', 'One who expects [and considers] the outcomes remains safe.', 'Ghurar al-Hikam, Outcomes- §2', 'wisdom'),
  ('مَنْ نَظَرَ فِي العَواقِبِ سَلِمَ.', 'One who considers the outcomes remains safe.', 'Ghurar al-Hikam, Outcomes- §3', 'wisdom'),
  ('مَنْ نَظَرَ فِي العَواقِبِ سَلِمَ مِنَ النَّوائِبِ.', 'One who considers the outcomes remains safe from calamities.', 'Ghurar al-Hikam, Outcomes- §4', 'wisdom'),
  ('مَنْ راقَبَ العَواقِبَ أمِنَ المَعاطِبَ.', 'One who is careful of the outcomes is safe from peril [and destruction].', 'Ghurar al-Hikam, Outcomes- §5', 'wisdom'),
  ('مَنِ انْتَظَرَ العاقِبَةَ صَبَرَ.', 'One who awaits a [positive] outcome is patient.', 'Ghurar al-Hikam, Outcomes- §6', 'wisdom'),
  ('مَنْ راقَبَ العَواقِبَ سَلِمَ مِنَ النَّوائِبِ.', 'One who is careful of the outcomes remains safe from calamities.', 'Ghurar al-Hikam, Outcomes- §7', 'wisdom'),
  ('إذا هَمَمْتَ بِأمْر فَاجْتَنِبْ ذَميمَ العَواقِبِ فيهِ.', 'When you endeavour to act upon a matter, then eschew the blameworthy outcomes in it.', 'Ghurar al-Hikam, Outcomes- §8', 'wisdom'),
  ('راقِبِ العَواقِبَ تَنْجُ مِنَ المَعاطِبِ.', 'Be careful of the outcomes and you will be saved from destruction.', 'Ghurar al-Hikam, Outcomes- §9', 'wisdom'),
  ('فِي العَواقِبِ شاف أوْ مُريح.', 'In the outcomes [of matters] there is [either] a curer or a comforter.', 'Ghurar al-Hikam, Outcomes- §10', 'wisdom'),
  ('مِنَ العُقُوقِ إضاعَةُ الحُقُوقِ.', 'Disregarding the rights [of your parents] is from [the acts of] filial impiety.', 'Ghurar al-Hikam, Filial impiety- §1', 'wisdom'),
  ('اَلعَقْلُ شَرَفٌ كَريمٌ لايَبْلى.', 'The intellect is an honourable nobility that does not wear away.', 'Ghurar al-Hikam, The Intellect- §1', 'wisdom'),
  ('اَلعَقْلُ غَريزَةٌ، تَزِيدُ بِالعِلْمِ والتَّجارِبِ.', 'The intellect is an inborn quality that increases through knowledge and experience.', 'Ghurar al-Hikam, The Intellect- §2', 'wisdom'),
  ('اَلعَقْلُ، والعِلْمُ، مَقْرُونانِ في قَرَن، لايَفْتَرِقانِ، ولايَتَبايَنانِ.', 'The intellect and knowledge are joined together in one linkage, they neither separate nor do they differ.', 'Ghurar al-Hikam, The Intellect- §3', 'wisdom'),
  ('اَلعَقْلُ أغْنَى الغِنى، وغايَةُ الشَّرَفِ فِي الآخِرَةِ والدُّنيا.', 'The intellect is the greatest of riches and the highest honour in [both] the Hereafter and this world.', 'Ghurar al-Hikam, The Intellect- §4', 'wisdom'),
  ('اَلعَقْلُ أجْمَلُ زِينَة، والعِلْمُ أشْرَفُ مَزِيَّة.', 'The intellect is the most beautiful adornment and knowledge is the most honourable merit.', 'Ghurar al-Hikam, The Intellect- §5', 'wisdom'),
  ('اَلعَقْلُ أصْلُ العِلْمِ، وداعِيَةُ الفَهْمِ.', 'The intellect is the root of knowledge and the herald of understanding.', 'Ghurar al-Hikam, The Intellect- §6', 'wisdom'),
  ('اَلعَقْلُ مَنْفَعَةٌ، والعِلْمُ مَرْفَعةٌ، والصَّبْرُ مَدْفَعَةٌ.', 'Intelligence is an advantage, knowledge is an elevation and patience is a defence [and a means of repelling hardships].', 'Ghurar al-Hikam, The Intellect- §7', 'wisdom'),
  ('اَلعَقْلُ خَلِيلُ المُؤْمِنِ، والعِلْمُ وَزيرُهُ، والصَّبْرُ أمِيرُ جُنُودِهِ، والعَمَلُ قَيِّمُهُ.', 'The intellect is the close friend of a believer, knowledge is his vizier, patience is the commander of his army and action is his overseer.', 'Ghurar al-Hikam, The Intellect- §8', 'wisdom'),
  ('اَلعَقْلُ صاحِبُ جَيْشِ الرَّحْمنِ، والهَوى قائِدُ جَيْشِ الشَّيْطانِ، وَالنَّفْسُ مُتَجاذِبَةٌ بَيْنَهُما، فَأيُّهُما غَلَبَ كانَتْ في حَيِّزِهِ.', 'The intellect is the leader of the army of the Most Merciful and vain desire is the chief of the army of Satan, and the soul is pulled back and forth between them, so whichever of them is victorious, it (i.e. the soul) is in its domain.', 'Ghurar al-Hikam, The Intellect- §9', 'wisdom'),
  ('اَلعَقْلُ والشَّهْوَةُ ضِدّانِ، ومُؤَيِّدُ العَقْلِ العِلْمُ، ومُزَيِّنُ الشَّهْوَةِ الهَوى، والنَّفْسُ مُتَنازِعَةٌ بَيْنَهُما، فَأيُّهُما قَهَرَ كانَتْ في جانِبِهِ.', 'Intellect and lust are opposites; the supporter of the intellect is knowledge and the adorner of lust is vain desire, and the soul is contended for between the two, so whichever is triumphant, it is on its side.', 'Ghurar al-Hikam, The Intellect- §10', 'wisdom'),
  ('اَلعاقِلُ مَنْ عَقَلَ لِسانَهُ.', 'The intelligent person is one who fetters his tongue.', 'Ghurar al-Hikam, The Intelligent- §1', 'wisdom'),
  ('اَلعاقِلُ مَنْ تَغَمَّدَ الذُّنُوبَ بِالغُفْرانِ.', 'The intelligent person is one who covers up sins with forgiveness.', 'Ghurar al-Hikam, The Intelligent- §2', 'wisdom'),
  ('اَلعاقِلُ مَنْ هَجَرَ شَهْوَتَهُ، وَباعَ دُنْياهُ بِ آخِرَتِهِ.', 'The intelligent person is one who forsakes his lust and sells his world for his Hereafter.', 'Ghurar al-Hikam, The Intelligent- §3', 'wisdom'),
  ('اَلعاقِلُ لايَتَكَلَّمُ إلاّ بِحاجَتِهِ أو حُجَّتِهِ.', 'The intelligent person does not speak except when he needs to or in order to present his case.', 'Ghurar al-Hikam, The Intelligent- §4', 'wisdom'),
  ('اَلعاقِلُ مَنْ تَوَرَّعَ عَنِ الذُّنُوبِ، وتَنَزَّهَ مِنَ العُيُوبِ.', 'The intelligent person is one who abstains from sins and keeps himself free from faults.', 'Ghurar al-Hikam, The Intelligent- §5', 'wisdom'),
  ('اَلعاقِلُ مَنْ عَقَلَ لِسانَهُ إلاّ عَنْ ذِكْرِ اللّهِ.', 'The intelligent person is one who fetters his tongue except from the remembrance [and extolment] of Allah.', 'Ghurar al-Hikam, The Intelligent- §6', 'wisdom'),
  ('اَلعاقِلُ مَنْ عَصى هَواهُ في طاعَةِ رَبِّهِ.', 'The intelligent person is one who opposes his vain desire in obedience to his Lord.', 'Ghurar al-Hikam, The Intelligent- §7', 'wisdom'),
  ('اَلعاقِلُ مَنْ أحْسَنَ صَنائِعَهُ، وَوَضَعَ سَعْيَهُ في مَواضِعِهِ.', 'The intelligent person is one who performs acts of kindness and puts his effort in its correct place.', 'Ghurar al-Hikam, The Intelligent- §8', 'wisdom'),
  ('اَلعاقِلُ إذا سَكَتَ فَكَرَ، وإذا نَطَقَ ذَكَرَ، وإذا نَظَرَ اِعْتَبـَرَ.', 'When the intelligent one is quiet, he reflects and when he speaks, he remembers [and extols Allah] and when he observes, he takes lesson.', 'Ghurar al-Hikam, The Intelligent- §9', 'wisdom'),
  ('اَلعاقِلُ مَنِ اتَّهَمَ رَأيَهُ، ولَمْ يَثِقْ بِكُلِّ ما تُسَوِّلُ لَهُ نَفْسُهُ.', 'The intelligent person is one who suspects his [own] opinion and does not trust everything that his self makes decorous for him.', 'Ghurar al-Hikam, The Intelligent- §10', 'wisdom'),
  ('لَـتَرْجِعَنَّ الفُرُوعُ عَلى أُصُولِها والمَعْلُولاتُ إلى عِلَلِها والجُزْئيّاتُ إلى كُلِّياتِها.', 'The branches will surely return to their roots, and the effects to their causes, and the particulars to their universals.', 'Ghurar al-Hikam, The Cause And The Effects- §1', 'wisdom'),
  ('اَلْعِلْمُ يَهْدي إلَى الحَقِّ.', 'Knowledge guides [one] to the truth.', 'Ghurar al-Hikam, Knowledge- §1', 'wisdom'),
  ('اَلْعِلْمُ مِصْباحُ العَقْلِ، ويَنْبُوعُ الفَضْلِ.', 'Knowledge is the lamp of the intellect and the fountain of excellence.', 'Ghurar al-Hikam, Knowledge- §2', 'wisdom'),
  ('اَلْعِلْمُ قاتِلُ الجَهْلِ، ومُكْسِبُ النُّبْلِ.', 'Knowledge is the killer of ignorance and the earner of nobility.', 'Ghurar al-Hikam, Knowledge- §3', 'wisdom'),
  ('اَلْعِلْمُ بِلاعَمَل وَبالٌ.', 'Knowledge without action is a plague.', 'Ghurar al-Hikam, Knowledge- §4', 'wisdom'),
  ('اَلْعِلْمُ كَنْزٌ عَظيمٌ لايَفْنى.', 'Knowledge is a great treasure that does not get exhausted.', 'Ghurar al-Hikam, Knowledge- §5', 'wisdom'),
  ('اَلْعِلْمُ أحَدُ الحَياتَيْنِ.', 'Knowledge is one of the two lives.', 'Ghurar al-Hikam, Knowledge- §6', 'wisdom'),
  ('اَلْعِلْمُ أفْضَلُ الأنْيسَيْنِ.', 'Knowledge is the better of the two intimate companions.', 'Ghurar al-Hikam, Knowledge- §7', 'wisdom'),
  ('اَلْعِلْمُ باللّهِ أفْضَلُ العِلْمَينِ.', 'Knowledge about Allah is the better of the two types of knowledge.', 'Ghurar al-Hikam, Knowledge- §9', 'wisdom'),
  ('اَلْعِلْمُ وِراثَةٌ كَريمَةٌ، ونِعْمَةٌ عَمِيمَةٌ.', 'Knowledge is an honourable heritage and a universal blessing.', 'Ghurar al-Hikam, Knowledge- §10', 'wisdom'),
  ('اَلْعِلْمُ يُنْجي مِنَ الاِرْتباكِ فِي الحِيْـرَةِ.', 'Knowledge saves [one] from being entangled in perplexity.', 'Ghurar al-Hikam, Knowledge- §11', 'wisdom'),
  ('اَلعالِمُ مَنْ شَهِدَتْ بِصِحَّةِ أقْوالِهِ أفْعالُهُ.', 'The scholar is one whose actions attest to the veracity of his words.', 'Ghurar al-Hikam, The Scholar- §1', 'wisdom'),
  ('اَلعُلَماءُ غُرَباءٌ لِكَثْرَةِ الجُهّالِ.', 'Scholars are strangers [in their own land] because of the large numbers of ignorant people.', 'Ghurar al-Hikam, The Scholar- §2', 'wisdom'),
  ('اَلعالِمُ مَنْ لايَشْبَعُ مِنَ العِلْمِ، وَلايَتَشَبَّعُ بِهِ.', 'The scholar is one who is not satisfied with [his] knowledge nor does he allow himself to be satiated by it.', 'Ghurar al-Hikam, The Scholar- §3', 'wisdom'),
  ('اَلعالِمُ يَعْرِفُ الجاهِلَ لأنَّهُ كانَ قَبْلُ جاهِلاً.', 'The scholar recognizes the ignorant one because he used to be ignorant [himself] before.', 'Ghurar al-Hikam, The Scholar- §4', 'wisdom'),
  ('اَلعالِمُ كُلُّ العالِمِ مَنْ لَمْ يَمْنَعِ العِبادَ الرَّجاءَ لِرَحْمَةِ اللّهِ ولَمْ يُؤْمِنْهُمْ مَكْرَاللّهِ.', 'The scholar who is truly a scholar, is one who does not prevent the servants from having hope in the mercy of Allah and [at the same time] does not give them false security from the scheme of Allah.', 'Ghurar al-Hikam, The Scholar- §5', 'wisdom'),
  ('اَلعالِمُ والمُتَعَلِّمُ شَريكانِ فِي الأجْرِ، وَلاخَيْـرَ فيما بَيْنَ ذلِكَ.', 'The scholar and the student are partners in reward; there no good in anything between this.', 'Ghurar al-Hikam, The Scholar- §6', 'wisdom'),
  ('اَلعُلَماءُ أطْهَرُ النّاسِ أخْلاقاً، وأقَلُّهُمْ فِي المَطامِعِ أعْراقاً.', 'Scholars are the purest of people in character and the least rooted in [vain] desires.', 'Ghurar al-Hikam, The Scholar- §7', 'wisdom'),
  ('اَلعالِمُ حَيٌّ بَيْـنَ المَوْتى.', 'The scholar is a living [person] among the dead.', 'Ghurar al-Hikam, The Scholar- §8', 'wisdom'),
  ('إيّاكَ أنْ تَسْتَخِفَّ بِالعُلَماءِ، فَإنَّ ذلِكَ يُزْري بِكَ، ويُسِـيءُ الظَّنَّ بِكَ، والمَخِيلَةَ فيكَ.', 'Be careful not to disparage scholars, for indeed this will degrade you and make others think ill of you and expect evil from you.', 'Ghurar al-Hikam, The Scholar- §9', 'wisdom'),
  ('أعْلَمُكُمْ أخْوَفُكُمْ.', 'The most learned among you are the most fearful of you.', 'Ghurar al-Hikam, The Scholar- §10', 'wisdom'),
  ('أعْوَنُ الأشْياءِ عَلى تَزْكِيَةِ العَقْلِ التَّعْليمُ.', 'The most helpful thing in purifying the intellect is education.', 'Ghurar al-Hikam, Education and learning- §1', 'wisdom'),
  ('تَعَلَّمْ تَعْلَمْ، وتَـكَرَّمْ تُـكْرَمْ.', 'Learn and you will become knowledgeable, honour and you will be honoured.', 'Ghurar al-Hikam, Education and learning- §2', 'wisdom'),
  ('تَواضَعُوا لِمَنْ تَتَعَلَّمُوا مِنْهُ العِلْمَ، ولِمَنْ تُعَلِّمُونَهُ، ولاتَـكُونُوا مِنْ جَبابِرَةِ العُلَماءِ، فَلا يَقُومَ جَهْلُكُمْ بِعِلْمِكُمْ.', 'Be humble in front of the one from whom you gain knowledge and the one whom you teach; and do not be from among the haughty scholars, lest your ignorance rises alongside you knowledge.', 'Ghurar al-Hikam, Education and learning- §3', 'wisdom'),
  ('تَعَلَّمِ العِلْمَ فَإنَّكَ إنْ كُنْتَ غَنِيّاً زانَكَ، وإنْ كُنْتَ فَقيراً مانَكَ (صانَكَ).', 'Acquire knowledge, for indeed if you are wealthy it will adorn you and if you are poor it will provide for you (or guard you).', 'Ghurar al-Hikam, Education and learning- §4', 'wisdom'),
  ('تَعَلَّمْ عِلْمَ مَنْ يَعْلَمُ، وعَلِّمْ عِلْمَكَ مَنْ يَجْهَلُ، فَإذا فَعَلْتَ ذلِكَ، عَلَّمَكَ ما جَهِلْتَ، وانْتَفَعْتَ بِما عَلِمْتَ.', 'Learn the knowledge of the one who knows, and teach your knowledge to the one who is ignorant, for if you do this, he will be teach you that which you are ignorant of and you will benefit [others] with what you have learnt.', 'Ghurar al-Hikam, Education and learning- §5', 'wisdom'),
  ('واضِعُ العِلْمِ عِنْدَ غَيْرِ أهْلِهِ ظالِمٌ لَهُ.', 'He who places knowledge with one who is unworthy of it has wronged it [or him].', 'Ghurar al-Hikam, Education and learning- §6', 'wisdom'),
  ('تَعَلَّمُوا العِلْمَ تُعْرَفُوا بِهِ، واعْمَلُوا بِهِ تَـكُونُوا مِنْ أهْلِهِ.', 'Gain knowledge and you will be known by it, act upon it and you will be one of its worthy possessors.', 'Ghurar al-Hikam, Education and learning- §8', 'wisdom'),
  ('إذا لَمْ تَـكُنْ عالِماً ناطِقاً فَكُنْ مُسْتَمِعاً واعِياً.', 'If you are not an articulating scholar then be an attentive listener.', 'Ghurar al-Hikam, The student- §1', 'wisdom'),
  ('عَلَى المُتَعَلِّمِ أنْ يَدْأبَ نَفْسَهُ في طَلَبِ العِلْمِ، وَلايَمَلَّ مِنْ تَعَلُّمِهِ وَلايَسْتَكْثِرُ ما عَلِمَ.', 'The student must discipline himself in his quest for knowledge and must neither become bored of his studies nor overestimate what he already knows.', 'Ghurar al-Hikam, The student- §2', 'wisdom'),
  ('مَنْ تَعَلَّمَ عَلِمَ.', 'One who learns becomes knowledgeable.', 'Ghurar al-Hikam, The student- §3', 'wisdom'),
  ('مَنْ لَمْ يَتَعَلَّمْ لَمْ يَعْلَمْ.', 'One who does not learn does not become knowledgeable.', 'Ghurar al-Hikam, The student- §4', 'wisdom'),
  ('مَنْ تَعَلَّمَ العِلْمَ لِلْعَمَلِ بِهِ لَمْ يُوحِشْهُ كَسادُهُ.', 'One who gains knowledge so that he can act upon it is not distressed by its dullness.', 'Ghurar al-Hikam, The student- §5', 'wisdom'),
  ('مَنْ لَمْ يَتَعَلَّمْ فِي الصِّغَرِ لَمْ يَتَقَدَّمْ فِي الكِبَرِ.', 'One who does not learn in his young age, does not progress in his old age.', 'Ghurar al-Hikam, The student- §6', 'wisdom'),
  ('مَنْ لَمْ يَصْبِرْ عَلى مَضَضِ التَّعْليمِ(التَّعَلُّمِ) بَقِيَ في ذُلِّ الجَهْلِ.', 'One who does not bear the hardships of gaining knowledge (or education) remains in the abject ignorance?', 'Ghurar al-Hikam, The student- §7', 'wisdom'),
  ('مَنْ لَمْ يُدْئِبْ (لَمْ يُذِبْ) نَفْسَهُ فِي اكْتِسابِ العِلْمِ لَمْ يُحْرِزْ قَصَباتِ السَّبْقِ.', 'One who does not discipline himself (or spend his life) in acquiring knowledge cannot gain great successes.', 'Ghurar al-Hikam, The student- §8', 'wisdom'),
  ('لايَسْتَنْكِفَنَّ مَنْ لَمْ يَكُنْ يَعْلَمُ أنْ يَتَعَلَّمَ.', 'The one who does not know must never be too proud to learn.', 'Ghurar al-Hikam, The student- §9', 'wisdom'),
  ('لاتُحَدِّثِ الجُهّالَ بِما لايَعْلَمُونَ فَيُكَذِّبُوكَ بِهِ، فَإنَّ لِعِلْمِكَ عَلَيْكَ حَقّاً، وحَقُّهُ عَلَيْكَ بَذْلَهُ لِمُسْتَحِقِّهِ ومَنْعُهُ مِنْ غَيْرِ مُسْتَحِقِّهِ.', 'Do not speak to the ignorant ones about that which they do not know such that they belie you, for indeed your knowledge has a right over you and its right is that you bestow it to those who are deserving of it and deny it to those who are not deserving of it.', 'Ghurar al-Hikam, The student- §10', 'wisdom'),
  ('اَلعُمْرُ الَّذي أعْذَرَ اللّهُ سُبْحانَهُ فيهِ إلَى ابْنِ آدَمَ وأنْذَرَ، السِّتُّونَ.', 'The age up to which Allah, the Glorified, accepts the excuse of human beings and warns them is sixty years.', 'Ghurar al-Hikam, Age and Lifespan- §1', 'wisdom'),
  ('اَلعُمْرُ الَّذي يَبْلُغُ الرَّجُلُ فيهِ الأشُدَّ، اَلأرْبَعُونَ.', 'The age in which a person reaches maturity is forty.', 'Ghurar al-Hikam, Age and Lifespan- §2', 'wisdom'),
  ('إحْذَرُوا ضِياعَ الأعْمارِ فيما لايَبْقى لَكُمْ، فَفائِتُها لايَعُودُ.', 'Be wary of wasting your lifetimes in that which will not remain for you, for that which has passed from it does not return.', 'Ghurar al-Hikam, Age and Lifespan- §3', 'wisdom'),
  ('إنَّ عُمْرَكَ مَهْرُ سَعادَتِكَ، إنْ أنْفَذْتَهُ (أنْفَدْتَهُ) في طاعَةِ رَبِّكَ.', 'Verily your lifetime is the dower of your prosperity if you spend it in obedience to your Lord.', 'Ghurar al-Hikam, Age and Lifespan- §4', 'wisdom'),
  ('إنَّ أنْفاسَكَ أجْزاءُ عُمْرِكَ، فَلا تُفْنِها إلاّ في طاعَة تُزْلِفُكَ.', 'Verily your breaths are portions of your life, so do not use them up except in the obedience that brings you closer [to Allah].', 'Ghurar al-Hikam, Age and Lifespan- §5', 'wisdom'),
  ('إنَّ عُمْرَكَ وَقْتُكَ الَّذي أنْتَ فيهِ.', 'Verily your lifetime is the time which you find yourself in.', 'Ghurar al-Hikam, Age and Lifespan- §6', 'wisdom'),
  ('إنَّ عُمْرَكَ عَدَدَ أنْفاسِكَ، وعَلَيْها رَقيبٌ تُحْصيها.', 'Verily your lifespan is the number of your breaths, and there is a watcher who counts them.', 'Ghurar al-Hikam, Age and Lifespan- §7', 'wisdom'),
  ('إنَّ اللَّيْلَ والنَّهارَ مُسْرِعانِ في هَدْمِ الأعْمارِ.', 'Indeed the night and day are quick in razing the lifetimes.', 'Ghurar al-Hikam, Age and Lifespan- §8', 'wisdom'),
  ('إنَّ ماضِيَ عُمْرِكَ أجَلٌ، وآتِيَهُ أمَلٌ، والوَقْتُ عَمَلٌ.', 'Indeed your life’s past is that which has come to pass and its future is hope, and the present is [time for] action.', 'Ghurar al-Hikam, Age and Lifespan- §9', 'wisdom'),
  ('إنَّ غايَةً تَنْقُصُهَا اللَّحْظَةُ، وتَهْدِمُهَا السّاعَةُ، لَحَرِيَّةٌ بِقَصْرِ المُدَّةِ.', 'Verily the life that is being shortened every moment and being dismantled every hour must be regarded as very short.', 'Ghurar al-Hikam, Age and Lifespan- §10', 'wisdom'),
  ('آفَةُ العُمْرانِ جَوْرُ السُّلْطانِ.', 'The bane of development and prosperity is the oppression of a tyrant.', 'Ghurar al-Hikam, Development and prosperity- §1', 'wisdom'),
  ('مَنْ تَعَمَّقَ لَمْ يَنْبُ إلَى الحَقِّ.', 'One who delves too deep [in trying to understand the essence of Allah] does not return to the truth.', 'Ghurar al-Hikam, Delving deep- §1', 'wisdom'),
  ('اَلْعَمَلُ بِلا عِلْم ضَلالٌ.', 'Action without knowledge is misguidance.', 'Ghurar al-Hikam, Actions and deeds- §1', 'purpose'),
  ('اَلْعَمَلُ الصَّالِحُ أفْضَلُ الزادَيْنِ.', 'Righteous action is the better of the two provisions.', 'Ghurar al-Hikam, Actions and deeds- §2', 'purpose'),
  ('أعْمالُ العِبادِ فِي الدُّنيا نَصْبُ أعْيُنِهِمْ فِي الآخِرةِ.', 'The actions of servants in this world are [brought] before their eyes in the Hereafter.', 'Ghurar al-Hikam, Actions and deeds- §4', 'purpose'),
  ('ألشَّـرَفُ عِنْدَ اللّهِ سُبْحانَهُ بِحُسْنِ الأعْمالِ، لابِحُسْنِ الأقْوالِ.', 'Honour in the sight of Allah, the Glorified, is through righteous actions, not by beautiful words.', 'Ghurar al-Hikam, Actions and deeds- §5', 'purpose'),
  ('اَلتَّقْصِيرُ فِي العَمَلِ لِمَنْ وَثِقَ بِالثَّوابِ عَلَيْهِ غَبْنٌ.', 'Falling short in action, for the one who is certain of its reward, is foolishness.', 'Ghurar al-Hikam, Actions and deeds- §6', 'purpose'),
  ('اِشْتِغالُ النَّفْسِ بِما لايَصْحَبُها بَعْدَ المَوْتِ مِنْ أكْثَرِ الوَهْنِ.', 'Busying oneself with that which will not accompany you after death is from the greatest weakness.', 'Ghurar al-Hikam, Actions and deeds- §7', 'purpose'),
  ('اَلأقاويلُ مَحْفُوظَةٌ، والسَّرائِرُ مَبْلُوَّةٌ، وكُلُّ نَفْس بِما كَسَبَتْ رَهِينَةٌ.', 'Utterances are recorded, secrets are [going to be] revealed and every soul is held hostage by what it has earned.', 'Ghurar al-Hikam, Actions and deeds- §9', 'purpose'),
  ('اَلقَرينُ الصّالِحُ هُوَ العَمَلُ الصّالِحُ.', 'The [most] righteous companion is righteous action.', 'Ghurar al-Hikam, Actions and deeds- §10', 'purpose'),
  ('اِعْمَلْ تَدَّحِرْ.', 'Act [in this world] so that you can store [provisions for the Hereafter].', 'Ghurar al-Hikam, Actions and deeds- §11', 'purpose'),
  ('اِعْمَلْ بِالعِلْمِ تُدْرِكْ غُنْماً.', 'Act upon [your] knowledge and you will attain [great] benefit.', 'Ghurar al-Hikam, Actions and deeds- §12', 'purpose'),
  ('لاتُعامِلْ مَنْ لا تَقْدِرُ عَلَى الاِنْتِصافِ مِنْهُ.', 'Do not make any dealings with one from whom you have no power to demand justice.', 'Ghurar al-Hikam, Dealings- §1', 'wisdom'),
  ('أشَدُّ النّاسِ عَمىً: مَنْ عَمِيَ عَنْ حُبِّنا وفَضْلِنا، وَناصَبَنا العَداوَةَ بِلا ذَنْب سَبَقَ مِنّا إلَيْهِ إلاّ أنّا دَعَوْناهُ إلَى الحَقِّ، ودَعاهُ سَوانا إلَى الفِتْنَةِ والدُّنيا، فَ آثَرُوها، ونَصَبُوا العَداوَةَ لَنا.', 'The blindest of people is one who is blind to our love and our excellence, and one who has hatred for us without any wrongdoing on our part towards him, except that we invited him to the truth while others invited him to temptation and [the pleasures of] this world, so they preferred it and displayed hatred towards us.', 'Ghurar al-Hikam, Blindness and the blind- §1', 'wisdom'),
  ('رُبَّما أصابَ العَمِيُّ (الأعْمى) قَصْدَهُ.', 'Sometimes the blind one arrives at his goal.', 'Ghurar al-Hikam, Blindness and the blind- §2', 'wisdom'),
  ('مَنْ عَمِيَ عَمّا بَيْنَ يَدَيْهِ غَرَسَ الشَّكَّ بَيْنَ جَنْبَيْهِ.', 'One who is blind to that which is in front of him instils doubt within himself.', 'Ghurar al-Hikam, Blindness and the blind- §3', 'wisdom'),
  ('رِضى المُتَعَنِّتِ غايَةٌ لاتُدْرَكُ.', 'Pleasing the obstinate one is a goal that cannot be attained.', 'Ghurar al-Hikam, The Obstinate- §1', 'wisdom'),
  ('مَنْ خَبُثَ عُنْصُرُهُ ساءَ مَحْضَرُهُ.', 'ne whose lineage is wicked, his presence [in any gathering] is bad.', 'Ghurar al-Hikam, Descent and lineage- §1', 'wisdom'),
  ('مَنْ كَرُمَ مَحْتِدُهُ حَسُنَ مَشْهَدُهُ.', 'One whose lineage is honourable, his presence is good.', 'Ghurar al-Hikam, Descent and lineage- §2', 'wisdom'),
  ('مِنْ شَرَفِ الأعْراقِ كَرَمُ الأخْلاقِ.', 'Good manners are from the [signs of] honourable descent.', 'Ghurar al-Hikam, Descent and lineage- §3', 'wisdom'),
  ('رَأسُ السُّخْفِ العُنْفُ.', 'The height of folly is violence.', 'Ghurar al-Hikam, Violence- §1', 'wisdom'),
  ('راكِبُ العُنْفِ يَتَعَذَّرُ مَطْلَبُهُ.', 'Whoever acts violently, his goal becomes difficult [to achieve].', 'Ghurar al-Hikam, Violence- §2', 'wisdom'),
  ('مَنْ رَكِبَ العُنْفَ نَدِمَ.', 'One who acts violently, regrets.', 'Ghurar al-Hikam, Violence- §3', 'wisdom'),
  ('مَنْ عامَلَ بِالعُنْفِ نَدِمَ.', 'One who perpetrates violence, regrets.', 'Ghurar al-Hikam, Violence- §4', 'wisdom'),
  ('وُقُوعُكَ فيما لايَعنيكَ جَهْلٌ مُضِلٌّ.', 'Your getting involved in that which is of no concern to you is misguided ignorance.', 'Ghurar al-Hikam, That which is of no concern- §1', 'wisdom'),
  ('لاتَشْتَغِلْ بِما لايَعْنيكَ، ولاتتَكَلَّفْ فَوْقَ ما يَكْفِيكَ، واجْعَلْ كُلَّ هَمِّكَ لِما يُنْجيكَ.', 'Do not busy yourself with that which is of no concern to you, and do not take upon yourself more than what is enough for you, and exert all your efforts for that which will save you.', 'Ghurar al-Hikam, That which is of no concern- §2', 'wisdom'),
  ('دَعْ ما لايَعْنيكَ، واشْتَغِلْ بِمُهِمِّكَ الَّذي يُنْجيكَ.', 'Leave aside that which does not concern you and busy yourself with the important work that will save you [in the Hereafter].', 'Ghurar al-Hikam, That which is of no concern- §3', 'wisdom'),
  ('طُوبى لِمَنْ قَصَّرَ هِمَّتَهُ عَلى ما يَعْنيهِ، وجَعَلَ كُلَّ جِدِّهِ لِما يُنْجيهِ.', 'Blessed is the one who reduces his effort in that which does not concern him and exerts all his efforts for that which will save him.', 'Ghurar al-Hikam, That which is of no concern- §4', 'wisdom'),
  ('مَنِ اطَّرَعَ ما يَعْنيهِ وَقَعَ إلى ما لايَعْنيهِ.', 'One who discards that which is of concern to him falls into that which does not concern him.', 'Ghurar al-Hikam, That which is of no concern- §5', 'wisdom'),
  ('مَنْ أطالَ الحَديثَ فيما لايَنْبَغي فَقَدْ عَرَّضَ نَفْسَهُ لِلْمَلامَةِ.', 'One who prolongs his talk about that which he ought not to [speak of] has indeed made himself liable to dispraise.', 'Ghurar al-Hikam, That which is of no concern- §6', 'wisdom'),
  ('أكْبَرُ الكُلْفَةِ تَعَنّيكَ فيما لايَعْنيكَ.', 'The greatest inconvenience is troubling yourself with that which does not concern you.', 'Ghurar al-Hikam, That which is of no concern- §7', 'wisdom'),
  ('مَنِ اشْتَغَلَ بِما لايَعْنيهِ فاتَهُ مايَعْنيهِ.', 'One who occupies himself with that which does not concern him loses that which is important to him.', 'Ghurar al-Hikam, That which is of no concern- §8', 'wisdom'),
  ('مَنِ اشْتَغَلَ بِغَيْرِ ضَرُورَتِهِ فَوَّتَهُ ذلِكَ مَنْفَعَتَهُ.', 'Whoever occupies himself with that which is unnecessary, it causes him to lose [what is more to] his benefit.', 'Ghurar al-Hikam, That which is of no concern- §9', 'wisdom'),
  ('قَدْ يَسْتَقيمُ المُعَوَّجُ.', 'At times the crooked may become straight.', 'Ghurar al-Hikam, The crooked- §1', 'wisdom'),
  ('أفْضَلُ العِبادَةِ غَلَبَةُ العادَةِ.', 'The best worship is overcoming [a bad] habit.', 'Ghurar al-Hikam, Habit- §1', 'wisdom'),
  ('اَلعادَةُ طَبْعُ ثان.', 'Habit is second nature.', 'Ghurar al-Hikam, Habit- §2', 'wisdom'),
  ('اَلعادَةُ عَدُوٌُّّ مُتَمَلِّكٌ.', 'Habit is an enslaving enemy.', 'Ghurar al-Hikam, Habit- §3', 'wisdom'),
  ('آفَةُ الرِّياضَةِ غَلَبَةُ العادَةِ.', 'The bane of training [of the self] is the overpowering habit.', 'Ghurar al-Hikam, Habit- §4', 'wisdom'),
  ('بِغَلَبَةِ العاداتِ الوُصُولُ إلى أشْرَفِ المَقاماتِ.', 'Through overpowering [evil] habits, there is attainment of lofty stations.', 'Ghurar al-Hikam, Habit- §5', 'wisdom'),
  ('بِئْسَ العادَةُ الفُضُولُ.', 'Superfluity [in speech] is one of the worst habits.', 'Ghurar al-Hikam, Habit- §6', 'wisdom'),
  ('غَيِّـروُا العاداتِ تَسْهُلْ عَلَيْكُمْ الطّاعاتُ.', 'Change your habits and acts of worship will become easier for you [to perform].', 'Ghurar al-Hikam, Habit- §7', 'wisdom'),
  ('غَيْرُ مُدْرِكِ الدَرَّجاتِ مَنْ أطاعَ العاداتِ.', 'One who submits to his [evil] habits does not attain lofty stations.', 'Ghurar al-Hikam, Habit- §8', 'wisdom'),
  ('لِلْعادَةِ عَلى كُلِّ إنْسان سُلْطانٌ.', 'Habit has authority over every human being.', 'Ghurar al-Hikam, Habit- §9', 'wisdom'),
  ('مَنْ جَعَلَ دَيْدَنَهُ الهَزْلَ لَمْ يُعْرَفْ جِدُّهُ.', 'Whoever makes jesting his habit, his seriousness is not known.', 'Ghurar al-Hikam, Habit- §10', 'wisdom'),
  ('طُوبى لِمَنْ ذَكَرَ المَعادَ فَاسْتَكْثَرَ مِنَ الزَّادِ.', 'Blessed is the one who remembers the [Day of] Resurrection and thus increases his provisions.', 'Ghurar al-Hikam, Ressurection and the hour- §1', 'wisdom'),
  ('طُوبى لِمَنْ ذَكَرَ المَعادَ فَأحْسَنَ.', 'Blessed is the one who remembers the Resurrection and thus does good [deeds].', 'Ghurar al-Hikam, Ressurection and the hour- §2', 'wisdom'),
  ('عَلَيْكَ بِالجِدِّ والاِجْتِهادِ في إصْلاحِ المَعادِ.', 'You must work hard and struggle to improve your Hereafter.', 'Ghurar al-Hikam, Ressurection and the hour- §3', 'wisdom'),
  ('قَدْ أسْفَرَتِ السّاعَةُ عَنْ وَجْهِها، وظَهَرَتِ العَلامَةُ لِمُتَوَسِّمِها.', 'The Hour [of reckoning] has shown its face and the sign [of its coming] is evident for the one who recognizes it.', 'Ghurar al-Hikam, Ressurection and the hour- §4', 'wisdom'),
  ('قَدْ أشْـرَفَتِ السّاعَةُ بِزَلازِلِها وَأناخَتْ بِكَلاكِلِها.', 'The Hour has drawn near with its quakes and it has settled down with its chest on the ground.', 'Ghurar al-Hikam, Ressurection and the hour- §5', 'wisdom'),
  ('قَدْ شَخَصُوا عَنْ (مِنْ) مُسْتَقَّرِ الأجْداثِ، وصارُوا إلى مَقامِ الحِسابِ، وأُقيمَتْ عَلَيْهِمُ الحُجَجُ.', 'They have risen from the resting place in their graves and gone towards the site of reckoning, and evidence has been brought against them.', 'Ghurar al-Hikam, Ressurection and the hour- §6', 'wisdom'),
  ('مَنْ أصْلَحَ المَعادَ ظَفِرَ بِالسَّدادِ.', 'One who improves his Hereafter attains success through the right [course].', 'Ghurar al-Hikam, Ressurection and the hour- §7', 'wisdom'),
  ('صَلاحُ المَعادِ بِحُسْنِ العَمَلِ.', 'The goodness of the Hereafter is [attained] through good deeds.', 'Ghurar al-Hikam, Ressurection and the hour- §9', 'wisdom'),
  ('عِنْدَ مُعايَنَةِ أهْوالِ القِيامَةِ تَكْثُرُ مِنَ المُفَرِّطينَ النَّدامَةُ.', 'When the horrors of the Day of Reckoning will be witnessed, there will be many who will show extreme regret.', 'Ghurar al-Hikam, Ressurection and the hour- §10', 'wisdom'),
  ('اِشْتِغالُكَ بِإصْلاحِ مَعادِكَ يُنْجيكَ مِنْ عَذابِ النّارِ.', 'Being occupied with improving your Hereafter will save you from the chastisement of hellfire.', 'Ghurar al-Hikam, Ressurection and the hour- §11', 'wisdom'),
  ('مُبايَنَةُ العَوامِ مِنْ أفْضَلِ المُرُوَّةِ.', 'Separating yourself from the masses is from the best magnanimity.', 'Ghurar al-Hikam, The Masses- §1', 'wisdom'),
  ('أعِنْ تُعَنْ.', 'Assist and you will be assisted.', 'Ghurar al-Hikam, Assistance- §1', 'wisdom'),
  ('أعِنْ أخاكَ عَلى هِدايَتِهِ.', 'Assist your bother in gaining his guidance.', 'Ghurar al-Hikam, Assistance- §2', 'wisdom'),
  ('كَما تُعينُ تُعانُ.', 'Just as you assist [others], you are assisted.', 'Ghurar al-Hikam, Assistance- §3', 'wisdom'),
  ('لاتُعِنْ قَوِيّاً عَلى ضَعيف.', 'Do not assist a strong person over a weak one.', 'Ghurar al-Hikam, Assistance- §4', 'wisdom'),
  ('مَنْ أعانَ عَلى مُسْلِم فَقدْ بَرِئَ مِنَ الإسْلامِ.', 'One who assists [a disbeliever] against a Muslim has indeed exited from the fold of Islam.', 'Ghurar al-Hikam, Assistance- §5', 'wisdom'),
  ('مَنِ اسْتَعانَ بِالضَّعيفِ أبانَ عَنْ ضَعْفِهِ.', 'One who seeks assistance from the weak demonstrates his [own] weakness.', 'Ghurar al-Hikam, Seeking assistance- §1', 'wisdom'),
  ('مَنِ اسْتَعانَ بِغَيْرِ مُسْتَقِلّ ضَيَّعَ أمْرَهُ.', 'Whoever seeks assistance from one who is not independent has wasted his affair.', 'Ghurar al-Hikam, Seeking assistance- §2', 'wisdom'),
  ('مَنِ اسْتَعانَ بِعَدُوِّهِ عَلى حاجَتِهِ إزْدادَ بُعْداً مِنْهُ.', 'Whoever seeks the assistance of his enemy in order to fulfil his need, increases his distance from it [instead of getting it].', 'Ghurar al-Hikam, Seeking assistance- §3', 'wisdom'),
  ('مَنِ اسْتَعانَ بِاللّهِ أعانَهُ.', 'One who seeks assistance from Allah is assisted by Him.', 'Ghurar al-Hikam, Seeking assistance- §4', 'wisdom'),
  ('عَلَيْكَ بِالاِسْتِعانَةِ بِإلهِكَ، والرَّغْبَةِ إلَيْهِ في تَوْفيقِكَ، وتَرْكِكَ كُلَّ شائِبَة (شائِنَة) أوْلَجَتْكَ في شُبْهَة، أوْ أسْلَمَتْكَ إلى ضَلالَة.', 'Seek assistance from your Lord, and ask Him to grant you success and the abandonment of every shortcoming (or disgraceful act) that drives you into doubt or surrenders you to misguidance.', 'Ghurar al-Hikam, Seeking assistance- §5', 'wisdom'),
  ('مَنِ اسْتَعانَ بِذَوِى الألْبابِ سَلَكَ سَبيلَ الرَّشادِ.', 'One who seeks assistance from the people of intellect traverses the path of right guidance.', 'Ghurar al-Hikam, Seeking assistance- §6', 'wisdom'),
  ('اَلمَعُونَةُ تَنْزِلُ مِنَ اللّهِ عَلى قَدْرِ المَؤُنَةِ.', 'Succour descends from Allah to the extent of one’s requirement.', 'Ghurar al-Hikam, Succor- §1', 'wisdom'),
  ('عَلى قَدْرِ المَؤُنَةِ تَكُونُ مِنَ اللّهِ المَعُونَةُ.', 'To the extent of the need, there is succour from Allah.', 'Ghurar al-Hikam, Succor- §2', 'wisdom'),
  ('مَنْ وَجَّهَ رَغْبَتَهُ إلَيْكَ وَجَبَتْ مَعُونَتُهُ عَلَيْكَ.', 'Whoever turns his request to you [and seeks his need from you], assisting him becomes incumbent upon you.', 'Ghurar al-Hikam, Succor- §3', 'wisdom'),
  ('الوَفاءُ لأهْلِ الغَدْرِ غَدْرٌ عِنْدَ اللّهِ سُبْحانَهُ.', 'Being loyal to the treacherous is treachery in the sight of Allah, the Glorified.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §1', 'wisdom'),
  ('اَلْوَفاءُ تَوْأَمُ الأمانَةِ وزَيْنُ الأُخُوَّةِ.', 'Loyalty is the twin of trustworthiness and the adornment of brotherhood.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §2', 'wisdom'),
  ('اَلْوَفاءُ حِفْظُ الذِّمامِ، والمُرُوءَةُ تَعَهُّدُ ذَوِى الأرْحامِ.', 'Loyalty means preserving the rights [of others] and magnanimity means caring for one’s close relatives.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §3', 'wisdom'),
  ('إنَّ الوَفاءَ تَوْأَمُ الصِّدْقِ، وما أعْرِفُ جُنَّةً أوْقى مِنْهُ.', 'Verily loyalty is the twin of truthfulness and I do not know of a shield that is more protective than it.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §4', 'wisdom'),
  ('اَلوَفاءُ نُبْلٌ.', 'Loyalty is nobility.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §5', 'wisdom'),
  ('اَلوَفاءُ تَوْأَمُ الصِّدْقِ.', 'Loyalty is the twin of truthfulness.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §6', 'wisdom'),
  ('اَلوَفاءُ سَجِيَّةُ الكِرامِ.', 'Loyalty is the trait of the honourable.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §7', 'wisdom'),
  ('اَلوَفاءُ عُنْوانُ وُفُورِ الدّينِ، وقُوَّةِ الأمانَةِ.', 'Loyalty is the symbol of abundant religiosity and strong trustworthiness.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §8', 'wisdom'),
  ('إنْ وَقَعَتْ بَيْنَكَ وبَيْنَ عَدُوِّكَ قِصَّةٌ عَقَدْتَ بِها صُلْحاً وألبَسْتَهُ بِها ذِمَّةً، فَحُطْ عَهْدَكَ بِالوَفاءِ، وارْعَ ذِمَّتَكَ بِالأمانَةِ، واجْعَلْ نَفْسَكَ جُنَّةً بَيْنَكَ وبَيْنَ ما أعْطَيْتَ مِنْ عَهْدِكَ.', 'If something happens between you and your enemy, which leads you to a truce and the enacting of a peace treaty, then preserve your pact with loyalty and guard your pledge with trust, and make your soul a shield between you and that which you have pledged.', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §9', 'wisdom'),
  ('آفَةُ العُهُودِ قِلَّةُ الرِّعايَةِ.', 'The bane of covenants is lack of care [in fulfilling them].', 'Ghurar al-Hikam, Keeping promises and fulfilling pledges- §10', 'wisdom'),
  ('أكْبَرُ العَيْبِ أنْ تَعيبَ غَيْرَكَ بِما هُوَ فيكَ.', 'The greatest flaw is that you fault others for what is [also] in you.', 'Ghurar al-Hikam, Flaws and faults- §1', 'wisdom'),
  ('أعْجَزُ النّاسِ مَنْ قَدَرَ عَلى أنْ يُزيلَ النَّقْصَ عَنْ نَفْسِهِ ولَمْ يَفْعَلْ.', 'The most incompetent of all people is one who is able to remove a flaw in himself but does not do so.', 'Ghurar al-Hikam, Flaws and faults- §2', 'wisdom'),
  ('إنَّ لِلنّاسِ عُيُوباً، فَلا تَكْشِفْ ما غابَ عَنْكَ، فَإنَّ اللّهَ سُبْحانَهُ يَحْلُمُ عَلَيْها، واسْتُرِ العَوْرَةَ مَا اسْتَطَعْتَ يَسْتُرِ اللّهُ سُبْحانَهُ ما تُحِبُّ سَتْـرَهُ.', 'Verily everyone has faults, so do not expose that which is hidden from you, for indeed Allah, the Glorified, has hidden them out of clemency; and hide the faults [of others] as much as possible, [and in return] Allah, the Glorified, will hide that which you would like to remain hidden.', 'Ghurar al-Hikam, Flaws and faults- §3', 'wisdom'),
  ('تَكادُ ضَمائِرُ القُلُوبِ تَطَّلِعُ عَلى سَرائِرِ العُيُوبِ.', 'The inner hearts will soon become aware of the secret faults.', 'Ghurar al-Hikam, Flaws and faults- §4', 'wisdom'),
  ('تَأَمُّلُ العَيْبِ عَيْبٌ.', 'Scrutinizing the faults of others is a fault [in itself].', 'Ghurar al-Hikam, Flaws and faults- §5', 'wisdom'),
  ('عَجِبْتُ لِمَنْ يُقالُ: إنَّ فيهِ الشَّـرَّ الَّذي يَعْلَمُ أنَّهُ فيهِ كَيْفَ يَسْخَطُ.', 'I am surprised at the one about whom it is said: ‘Indeed in him there is evil,’ and he knows it is in him, how can he be annoyed?', 'Ghurar al-Hikam, Flaws and faults- §6', 'wisdom'),
  ('عَجِبْتُ لِمَنْ يُوصَفُ بِالخَيْرِ الَّذي يَعْلَمُ أنَّهُ لَيْسَ فيهِ كَيْفَ يَرضى.', 'I am amazed at the one who is described with a good trait that he knows is not in him, how can he be pleased?', 'Ghurar al-Hikam, Flaws and faults- §7', 'wisdom'),
  ('ذَوُوا العُيُوبِ يُحِبُّونَ إشاعَةَ مَعائِبِ النّاسِ لِيَتَّسِعَ لَهُمُ العُذْرُ في مَعائِبِهِمْ.', 'Those with faults love to spread the faults of people so that they get a greater excuse for their own faults.', 'Ghurar al-Hikam, Flaws and faults- §8', 'wisdom'),
  ('عَجِبْتُ لِمَنْ يُنْكِرُ عُيُوبَ النّاسِ ونَفْسُهُ أكْثَرُ شَـيْء مَعاباً وَلايُبْصِرُها.', 'I am amazed at one who disapproves of the faults of people while he has more faults himself and does not see them.', 'Ghurar al-Hikam, Flaws and faults- §9', 'wisdom'),
  ('عَيْنُ المُحِبِّ عَمِيَّةٌ عَنْ مَعائِبِ المَحْبُوبِ، وأُذُنُهُ صَمّاءٌ عَنْ قُبْحِ مَساويهِ.', 'The eyes of the lover are blind to the faults of his beloved, and his ears are deaf to the ugliness of his evils.', 'Ghurar al-Hikam, Flaws and faults- §10', 'wisdom'),
  ('مَنْ عَيَّرَ بِشَـيْء بُلِيَ بِهِ.', 'Whoever taunts others for something is himself affected by it.', 'Ghurar al-Hikam, Taunting- §1', 'wisdom'),
  ('أطْيَبُ العَيْشِ القَناعَةُ.', 'The most pleasant life is [a life of] contentment.', 'Ghurar al-Hikam, Lifestyle- §1', 'wisdom'),
  ('أسْوَءُ النّاسِ عَيْشاً الحَسُودُ.', 'The person with the worst lifestyle of all people is the jealous one.', 'Ghurar al-Hikam, Lifestyle- §2', 'wisdom'),
  ('أهْنَى العَيْشِ إطْراحُ الكُلَفِ.', 'The most felicitous lifestyle is achieved by abandoning unnecessary constraints [and formalities].', 'Ghurar al-Hikam, Lifestyle- §3', 'wisdom'),
  ('أحْسَنُ النّاسِ عَيْشاً مَنْ عاشَ النّاسُ في فَضْلِهِ.', 'Of all the people, the person who has the best lifestyle is one in whose grace other people live.', 'Ghurar al-Hikam, Lifestyle- §4', 'wisdom'),
  ('أنْعَمُ النّاسِ عَيْشاً مَنْ مَنَحَهُ اللّهُ سُبْحانَهُ القَناعَةَ، وأصْلَحَ لَهُ زَوْجَهُ.', 'The person with the most blessed lifestyle is one who has been granted contentment by Allah, the Glorified, and who has been given a good wife.', 'Ghurar al-Hikam, Lifestyle- §5', 'wisdom'),
  ('إنَّ أهْنَأَ النّاسِ عَيْشاً مَنْ كانَ بِما قَسَمَ اللّهُ لَهُ راضِياً.', 'Verily the person who has the happiest life of all people is one who is satisfied with what Allah has apportioned for him.', 'Ghurar al-Hikam, Lifestyle- §6', 'wisdom'),
  ('إنَّ أحْسَنَ النّاسِ عَيْشاً، مَنْ حَسُنَ عَيْشُ النّاسِ في عَيْشِهِ.', 'Verily the person with the best lifestyle is one through whose life the lives of others are improved.', 'Ghurar al-Hikam, Lifestyle- §7', 'wisdom'),
  ('اَلمَنِيَّةُ، ولاالدَّنِيَةُ.', 'Death is preferable to abasement.', 'Ghurar al-Hikam, Lifestyle- §8', 'wisdom'),
  ('اَلمَوْتُ، ولاابْتِذالُ الخِزْيَةِ(الحُرِّيَةُ).', 'Death is preferable to succumbing to disgrace (or giving up freedom).', 'Ghurar al-Hikam, Lifestyle- §9', 'wisdom'),
  ('اَلتَّقَلُّلُ، ولاالتّذَلُّلُ.', 'Having less is preferable to humiliation.', 'Ghurar al-Hikam, Lifestyle- §10', 'wisdom'),
  ('غَضُّ الطَّرْفِ مِنَ المُرُوءَةِ.', 'Lowering the gaze is a sign of magnanimity.', 'Ghurar al-Hikam, Lowering the gaze- §1', 'wisdom'),
  ('غَضُّ الطَّرْفِخَيْرٌ مِنْ كَثيرِ النَّظَرِ.', 'Lowering the gaze is better than staring.', 'Ghurar al-Hikam, Lowering the gaze- §2', 'wisdom'),
  ('غَضُّ الطَّرْفِ مِنْ أفْضَلِ الوَرَعِ.', 'Lowering the gaze is one of the best [acts of] piety.', 'Ghurar al-Hikam, Lowering the gaze- §3', 'wisdom'),
  ('غَضُّ الطَّرْفِ مِنْ كَمالِ الظَّرْفِ.', 'Lowering the gaze is from perfect gracefulness.', 'Ghurar al-Hikam, Lowering the gaze- §4', 'wisdom'),
  ('مَنْ غَضَّ طَرْفَهُ أراحَ قَلْبَهُ.', 'One who lowers his gaze relieves his heart.', 'Ghurar al-Hikam, Lowering the gaze- §5', 'wisdom'),
  ('مَنْ غَضَّ طَرْفَهُ قَلَّ أسَفُهُ وأمِنَ تَلَفُهُ.', 'One who lowers his gaze, his regret reduces and he is saved from harm.', 'Ghurar al-Hikam, Lowering the gaze- §6', 'wisdom'),
  ('نِعْمَ الوَرَعُ غَضُّ الطَّرْفِ.', 'How good an act of piety lowering the gaze is!', 'Ghurar al-Hikam, Lowering the gaze- §7', 'wisdom'),
  ('نِعْمَ صارِفُ الشَّهَواتِ غَضُّ الأبْصارِ.', 'How good a curtailer of lustful desires lowering the gaze is!', 'Ghurar al-Hikam, Lowering the gaze- §8', 'wisdom'),
  ('لامُرُوَّةَ كَغَضِّ الطَّرْفِ.', 'There is no magnanimity like lowering the gaze.', 'Ghurar al-Hikam, Lowering the gaze- §9', 'wisdom'),
  ('مَنْ لَمْ يَتَغافَلْ وَلايَغُضَّ عَنْ كَثير مِنَ الأُمُورِ تَنَغَّصَتْ عيشَتُهُ.', 'One who does not feign negligence and lower his gaze in many situations, his life becomes bitter.', 'Ghurar al-Hikam, Lowering the gaze- §10', 'wisdom'),
  ('لَيْسَ العِيانُ كَالخَبَرِ.', 'Seeing something [yourself] is not the same as being informed about it.', 'Ghurar al-Hikam, Seeing- §1', 'wisdom'),
  ('لاخَيْـرَ في مُعين مُهين.', 'There is no good in a helper who humiliates.', 'Ghurar al-Hikam, Helper- §1', 'wisdom'),
  ('أقْبَحُ العَيِّ الضَّجْرُ.', 'The worst inarticulateness is [that which is caused by] irritation.', 'Ghurar al-Hikam, Inarticulateness- §1', 'wisdom'),
  ('اَلْخَرَسُ خَيْـرٌ مِنَ العَيِّ (الغَيِّ).', 'Muteness is better than inarticulateness (or error).', 'Ghurar al-Hikam, Inarticulateness- §2', 'wisdom'),
  ('عَلامَةُ العَيِّ تَكْرارُ الكَلامِ عِنْدَ المُناظَرَةِ، وكَثْرَةُ التَّبَجُّجِ عِنْدَ المُحاوَرَةِ.', 'The sign of inarticulateness is repeating oneself during a debate and increased excitement during conversation.', 'Ghurar al-Hikam, Inarticulateness- §3', 'wisdom'),
  ('لابَيانَ مَعَ عَيّ.', 'No declaration can be made with inarticulateness.', 'Ghurar al-Hikam, Inarticulateness- §4', 'wisdom'),
  ('اَلعَيُّ حَصَـرٌ.', 'Inarticulateness is beleaguering.', 'Ghurar al-Hikam, Inarticulateness- §5', 'wisdom'),
  ('قَليلٌ تُحْمَدُ مَغَبَّتُهُ خَيْرٌ مِنْ كَثير تَضُرُّ عاقِبَتُهُ.', 'Little with a praised outcome is better than plenty with a harmful consequence.', 'Ghurar al-Hikam, Outcome- §1', 'wisdom'),
  ('اَلمَغْبُوطُ مَنْ قَوِيَ يَقينُهُ.', 'Enviable is the one whose certitude is strong.', 'Ghurar al-Hikam, The Enviable- §1', 'wisdom'),
  ('رُبَّ مَغْبُوط بِرَجاء هُوَ داؤُهُ.', 'Many a person is envied [by others] for something which is [actually] his affliction.', 'Ghurar al-Hikam, The Enviable- §2', 'wisdom'),
  ('كَمْ مِنْ مَغْبُوط بِنِعْمَتِهِ وهُوَ فِي الاخِرَةِ مِنَ الهالِكينَ.', 'How many a person is envied for the blessing he has been given [in this world] while he is among those who will be destroyed in the Hereafter.', 'Ghurar al-Hikam, The Enviable- §3', 'wisdom'),
  ('اَلْمَغْبُونُ مَنْ فَسَدَ دينُهُ.', 'Deceived is the one whose faith is corrupt.', 'Ghurar al-Hikam, The Deceived- §2', 'wisdom'),
  ('اَلْمَغْبُونُ مَنْ باعَ جَنَّـةً عَلِيَّةً بِمَعْصِيَة دَنِيَّة.', 'Deceived is the one who sells a lofty Paradise for a lowly sin.', 'Ghurar al-Hikam, The Deceived- §3', 'wisdom'),
  ('مَنْ أغْبَنُ مِمَّنْ باعَ اللّهَ سُبْحانَهُ بِغَيْرِهِ.', 'Who is more deceived than one who exchanges Allah, the Glorified, for other than Him?!', 'Ghurar al-Hikam, The Deceived- §4', 'wisdom'),
  ('اَلغَباوَةُ غِوايَةٌ.', 'Imbecility is misguidance.', 'Ghurar al-Hikam, Imbecility- §1', 'wisdom'),
  ('ضادُّوا الغَباوَةَ بِالفِطْنَةِ.', 'Counter imbecility with astuteness.', 'Ghurar al-Hikam, Imbecility- §2', 'wisdom'),
  ('كَفى بِالمَرْءِ غَباوَةً أنْ يَنْظُرَ مِنْ عُيُوبِ النّاسِ إلى ما خَفِيَ عَلَيْهِ مِنْ عُيُوبِهِ.', 'It is enough of imbecility for a person to look at the faults of people when the same faults are hidden to him of himself.', 'Ghurar al-Hikam, Imbecility- §3', 'wisdom'),
  ('مِنْ أقْبَحِ الشِّيَمِ الغَباوَةُ.', 'Imbecility is from the most detestable of traits.', 'Ghurar al-Hikam, Imbecility- §4', 'wisdom'),
  ('اَلْغَدْرُ يُعَظِّمُ الوِزْرَ ويُزْري بِالقَدْرِ.', 'Treachery increases the burden [of sin] and degrades one’s status.', 'Ghurar al-Hikam, Treachery- §2', 'wisdom'),
  ('إيّاكَ والغَدْرَ، فَإنَّهُ أقْبَحُ الخِيانَةِ، وإنَّ الغَدُورَ لَمُهانٌ عِنْدَاللّهِ.', 'Beware of treachery, for indeed it is the ugliest betrayal; and verily the treacherous one is humiliated in the sight of Allah.', 'Ghurar al-Hikam, Treachery- §3', 'wisdom'),
  ('أقْبَحُ الغَدْرِ إذاعَةُ السِّرِّ.', 'The worst treachery is divulging the secret [that has been entrusted to you].', 'Ghurar al-Hikam, Treachery- §4', 'wisdom'),
  ('اَلْغَدْرُ شيمَةُ اللِّئامِ.', 'Treachery is the quality of the wicked.', 'Ghurar al-Hikam, Treachery- §5', 'wisdom'),
  ('اَلغَدْرُ يُضاعِفُ السَّيِّئاتِ.', 'Treachery multiplies [one’s] sins.', 'Ghurar al-Hikam, Treachery- §6', 'wisdom'),
  ('جانِبُوا الغَدْرَ فَإنَّهُ مُجانِبُ القُرآنِ.', 'Eschew treachery, for indeed it takes you away from the Qur’an.', 'Ghurar al-Hikam, Treachery- §7', 'wisdom'),
  ('غَدْرُ الرَّجُلِ مَسََبَّةٌ عَلَيْهِ.', 'The treachery of a man is a disgrace upon him.', 'Ghurar al-Hikam, Treachery- §8', 'wisdom'),
  ('كُنْ عامِلاً بِالخَيْرِ، ناهِياً عَنِ الشَّرِّ، مُنْكِراً شيمَةَ الغَدْرِ.', 'Be one who acts with goodness, forbids evil and shuns the trait of treachery.', 'Ghurar al-Hikam, Treachery- §9', 'wisdom'),
  ('مَنْ غَدَرَ شانَهُ غَدْرُهُ.', 'One who acts treacherously is sullied by his treachery.', 'Ghurar al-Hikam, Treachery- §10', 'wisdom'),
  ('ما غَدَرَ مَنْ أيْقَنَ بِالمَرْجِـعِ.', 'He who is certain about the place of [final] return does not act treacherously.', 'Ghurar al-Hikam, Treachery- §11', 'wisdom'),
  ('اِحْذَرْ أنْ يَخْدَعَكَ (يَخْتَدِعَكَ)الغُرُورُ بِالحائِلِ اليَسيرِ، أوْ يَسْتَزِلَّكَ السُّرُورُ بِالزّائِلِ الحَقيرِ.', 'Be cautious of being deceived by the delusion of a small hindrance or being made to stumble by the joy of an insignificant transitory pleasure [of this world].', 'Ghurar al-Hikam, Delusion- §1', 'wisdom'),
  ('جِماعُ الغُرُورِ فِي الاِسْتِنامَةِ إلَى العَدُوِّ.', 'The consolidation of delusion is in sleeping with ease in the presence of the enemy.', 'Ghurar al-Hikam, Delusion- §2', 'wisdom'),
  ('طُوبى لِمَنْ لَمْ تَقْتُلْهُ قاتِلاتُ الغُرُورِ.', 'Blessed be the one who has not been killed by the lethal poisons of deception.', 'Ghurar al-Hikam, Delusion- §3', 'wisdom'),
  ('كَفى بِالمَرْءِ غُرُوراً أنْ يَثِقَ بِكُلِّ ما تُسَوِّلُ لَهُ نَفْسُهُ.', 'It is enough of a delusion for a person to trust all that his soul lures him towards.', 'Ghurar al-Hikam, Delusion- §4', 'wisdom'),
  ('وقالَ ـ عَلَيْهِ السّلامُ ـ في حَقِّ مَنْ أثنى عَلَيْهِ: لَمْ تَقْتُلْهُ قاتِلاتُ الغُرُورِ، وَلَمْتُغَمَّ (وَلَمْ تُعَمَّ) عَلَيْهِ مُشْتَبِهاتُ الأُمُورِ.', 'He (‘a) said about the one whom he praised: He has not been killed by the lethal poisons of delusion and has not been covered (or overcome) by the uncertainties of matters.', 'Ghurar al-Hikam, Delusion- §5', 'wisdom'),
  ('لَمْ يُفَكِّرْ في عَواقِبِ الأُمُورِ مَنْ وَثِقَ بِزُورِالغُرُورِ وصَبا إلى زُورِ السُّرُورِ.', 'He who trusts in the falsehood of delusions and yearns for the false [and short-lived] joys has not thought about the consequences of matters.', 'Ghurar al-Hikam, Delusion- §6', 'wisdom'),
  ('مَنِ اغْتَرَّ بِالمَهَلِ اِغْتَصَّ بِالأجَلِ.', 'One who is deluded by respite, is tormented by death.', 'Ghurar al-Hikam, Delusion- §7', 'wisdom'),
  ('كَفى بِالاِغْتِرارِ جَهْلاً.', 'Delusion is suffices as ignorance.', 'Ghurar al-Hikam, Delusion- §8', 'wisdom'),
  ('مَنِ اغْتَّرَ بِحالِهِ قَصَّرَ عَنِ احْتِيالِهِ.', 'One who is deluded by his condition, reduces his efforts.', 'Ghurar al-Hikam, Delusion- §9', 'wisdom'),
  ('مَنِ اغْتَرَّ بِمُسالَمَةِ الزَّمَنِ اِغْتَصَّ بِمُصادَمَةِ المِحَنِ.', 'One who is deluded by the peacefulness of the time gets distressed by the impact of calamities.', 'Ghurar al-Hikam, Delusion- §10', 'wisdom'),
  ('اَلْحَجَرُ الغَصْبُ فِي الدّارِ رَهْنٌ لِخَرابِها.', 'ne usurped stone in a house is the guaranty of its ruin.', 'Ghurar al-Hikam, Usurpation- §1', 'wisdom'),
  ('اَلْغَضَبُ يُرْدي صاحِبَهُ، ويُبْدي مَعايِبَهُ.', 'Anger strikes down its possessor and exposes his faults.', 'Ghurar al-Hikam, Anger- §1', 'self-mastery'),
  ('اَلغَضَبُ نارٌ مُوقَدَةٌ، مَنْ كَظَمَهُ أطْفَأَها، ومَنْ أطْلَقَهُ كانَ أوَّلَ مُحْتَرِق بِها.', 'Anger is a kindled fire, one who suppresses it extinguishes the fire and one who lets it burn freely is the first person who will be burnt by it.', 'Ghurar al-Hikam, Anger- §2', 'self-mastery'),
  ('اَلْغَضَبُ يُثيرُ كَوامِنَ الحِقْدِ.', 'Anger arouses hidden feelings of malice.', 'Ghurar al-Hikam, Anger- §3', 'self-mastery'),
  ('إيّاكَ والغَضَبَ، فَأوَّلُهُ جُنُونٌ، وآخِرُهُ نَدَمٌ.', 'Keep away from anger, for its beginning is madness and its end is regret.', 'Ghurar al-Hikam, Anger- §4', 'self-mastery'),
  ('أقْدَرُ النّاسِ عَلَى الصَّوابِ مَنْ لَمْ يَغْضَبْ.', 'The person who is most capable of being on the right is one who does not get angry.', 'Ghurar al-Hikam, Anger- §5', 'self-mastery'),
  ('أفْضَلُ المِلْكِ مِلْكُ الغَضَبِ.', 'The best control is control over anger.', 'Ghurar al-Hikam, Anger- §6', 'self-mastery'),
  ('اِبْقَ لِرِضاكَ مِنْ غَضَبِكَ، وإذا طِرْتَ فَقَعْ شَكِيراً.', 'Leave some room from your anger for your satisfaction, and when you fly off [in a rage] then calm back down.', 'Ghurar al-Hikam, Anger- §7', 'self-mastery'),
  ('اِحْتَرِسُوا مِنْ سَوْرَةِ الغَضَبِ، وأعِدُّوا لَهُ ما تُجاهِدُونَهُ، بِهِ مِنَ الكَظْمِ وَالحِلْمِ.', 'Guard yourselves from the vehemence of anger, and prepare for it the restraint and forbearance that will help you fight against it.', 'Ghurar al-Hikam, Anger- §8', 'self-mastery'),
  ('اِحْذَرُوا الغَضَبَ، فَإنَّهُ نارٌ مُحْرِقَةٌ.', 'Beware of anger, for it is indeed a burning fire.', 'Ghurar al-Hikam, Anger- §9', 'self-mastery'),
  ('أفْضَلُ النّاسِ مَنْ كَظَمَ غَيْظَهُ، وحَلُمَ عَنْ قُدْرَة.', 'The best of people is one who swallows his anger and displays forbearance despite having power [to take revenge].', 'Ghurar al-Hikam, Anger- §10', 'self-mastery'),
  ('اِسْتَغْفِرْ، تُرْزَقْ.', 'Seek forgiveness and you will be provided sustenance.', 'Ghurar al-Hikam, Seeking forgiveness- §1', 'forgiveness'),
  ('أفْضَلُ التَّوَسُّلِ (التَّوَصُّلِ) الاِسْتِغْفارُ.', 'The best supplication (or means of coming closer to Allah) is seeking forgiveness.', 'Ghurar al-Hikam, Seeking forgiveness- §2', 'forgiveness'),
  ('اَلاِسْتِغْفارُ يَمْحُو الأوْزارَ.', 'Seeking forgiveness wipes out [one’s] sins.', 'Ghurar al-Hikam, Seeking forgiveness- §3', 'forgiveness'),
  ('اَلاِسْتِغْفارُ دَواءُ الذُّنُوبِ.', 'Seeking forgiveness is the remedy of sins.', 'Ghurar al-Hikam, Seeking forgiveness- §4', 'forgiveness'),
  ('اَلإسْتِغْفارُ أعْظَمُ جَزاءً، وأسْرَعُ مَثُوبَةً.', 'Seeking forgiveness has the greatest recompense and the quickest reward.', 'Ghurar al-Hikam, Seeking forgiveness- §5', 'forgiveness'),
  ('حُسْنُ الاِسْتِغْفارِ يُمَحِّصُ الذُّنُوبَ.', 'Sincere repentance purges one’s sins.', 'Ghurar al-Hikam, Seeking forgiveness- §6', 'forgiveness'),
  ('لَوْ أنَّ النّاسَ حينَ عَصَوْا أنابُوا وَاسْتَغْفَرُوا لَمْ يُعَذَّبُوا وَلَمْيَهْلِكُوا.', 'If the people were to turn in repentance [to Allah] and seek forgiveness whenever they disobeyed [or sinned], they would neither be punished nor would they be destroyed.', 'Ghurar al-Hikam, Seeking forgiveness- §7', 'forgiveness'),
  ('مَنْ أُعْطِيَ الاِسْتِغْفارَ لَمْ يُحْرَمِ المَغْفِرَةَ.', 'One who has been granted [the opportunity to seek] repentance shall not be deprived of forgiveness.', 'Ghurar al-Hikam, Seeking forgiveness- §8', 'forgiveness'),
  ('مَنِ اسْتَغْفَرَ اللّهَ أصابَ المَغْفِرَةَ.', 'One who seeks forgiveness from Allah attains absolution.', 'Ghurar al-Hikam, Seeking forgiveness- §9', 'forgiveness'),
  ('نِعْمَ الوَسيلَةُ اَلاِسْتِغْفارُ.', 'What a good means [of gaining the pleasure of Allah] seeking forgiveness is!', 'Ghurar al-Hikam, Seeking forgiveness- §10', 'forgiveness'),
  ('إنْتِباهُ العُيُونِ لايَنْفَعُ مَعَ غَفْلَةِ القُلُوبِ.', 'The wakefulness of eyes is of no benefit with the negligence of hearts.', 'Ghurar al-Hikam, Negligence- §1', 'wisdom'),
  ('اَلْغَفْلَةُ تَكْسِبُ الاِغْتِرارَ، وتُدْني مِنَ البَوارِ.', 'Negligence reaps delusion and brings one closer to destruction.', 'Ghurar al-Hikam, Negligence- §2', 'wisdom'),
  ('اِحْذَرُوا الغَفْلَةَ،فَإنَّها مِنْ فَسادِ الحِسِّ.', 'Be cautious of negligence, for indeed it is from the corruption of [one’s sensory] perception.', 'Ghurar al-Hikam, Negligence- §3', 'wisdom'),
  ('إيّاكَ والغَفْلَةَ، والاِغْتِرارَ بِالمُهْلَةِ، فَإنَّ الغَفْلَةَ تُفْسِدُ الأعْمالَ، وَالآجالَ تَقْطَعُ الآمالَ.', 'Beware of negligence and being deluded by respite, for indeed negligence corrupts deeds, and death cut off hopes.', 'Ghurar al-Hikam, Negligence- §4', 'wisdom'),
  ('اَلْغَفْلَةُ ضَلالَةٌ، اَلغِرَّةُ جَهالَةٌ.', 'Negligence is misguidance and heedlessness is ignorance.', 'Ghurar al-Hikam, Negligence- §5', 'wisdom'),
  ('اَلْغَفْلَةُ طَرَبٌ.', 'Negligence is joy.', 'Ghurar al-Hikam, Negligence- §6', 'wisdom'),
  ('اَلْغَفْلَةُ أضَرُّ الأعْداءِ.', 'Negligence is the most harmful enemy.', 'Ghurar al-Hikam, Negligence- §7', 'wisdom'),
  ('اَلْغَفْلَةُ شيمَةُ النَّوْكى.', 'Negligence is the trait of the foolish.', 'Ghurar al-Hikam, Negligence- §8', 'wisdom'),
  ('اَلْغَفْلَةُ ضِدُّ الحَـزْمِ.', 'Negligence is the opposite of judiciousness.', 'Ghurar al-Hikam, Negligence- §9', 'wisdom'),
  ('اَلْغَفْلَةُ ضَلالُ النُّفُوسِ وعُنْوانُ النُّحُوسِ.', 'Negligence is the misguidance of souls and the symbol of misfortunes.', 'Ghurar al-Hikam, Negligence- §10', 'wisdom'),
  ('عَجِبْتُ لِغافـِل، والمَوْتُ حَثيثٌ في طَلَبِهِ.', 'I am amazed at the one who is negligent, while death is swift in seeking him.', 'Ghurar al-Hikam, The Negligent- §1', 'wisdom'),
  ('مَنْ طالَبَ غَفْلَتُهُ تَعَجَّلَتْ هَلَكَتُهُ.', 'One whose negligence is prolonged, his destruction is hastened.', 'Ghurar al-Hikam, The Negligent- §2', 'wisdom'),
  ('مَنْ غَلَبَتْ عَلَيْهِ الغَفْلَةُ ماتَ قَلْبُهُ.', 'One whose negligence overcomes him, his heart dies.', 'Ghurar al-Hikam, The Negligent- §3', 'wisdom'),
  ('مَنْ غَفَلَ عَنْ حَوادِثِ الأيّامِ أيْقَظَهُ الحِمامُ.', 'One who is negligent about the events of [his] days is awakened by death.', 'Ghurar al-Hikam, The Negligent- §4', 'wisdom'),
  ('وَيْلٌ لِمَنْ غَلَبَتْ عَلَيْهِ الغَفْلَةُ فَنَسِيَ الرِّحْلَةَ ولَمْ يَسْتَعِدَّ.', 'Woe be to the one who is overcome by negligence so he forgets his [final] journey and does nor prepare for it.', 'Ghurar al-Hikam, The Negligent- §5', 'wisdom'),
  ('لاعَمَلَ لِغافِل.', 'No deed is accepted from the negligent one.', 'Ghurar al-Hikam, The Negligent- §6', 'wisdom'),
  ('قَدْ يَغْلِبُ المَغْلُوبُ.', 'At times the [one who is] vanquished may gain victory.', 'Ghurar al-Hikam, The Victor and the vanquished- §1', 'wisdom'),
  ('مَنْ غالَبَ مَنْ فَوْقَهُ قُهِرَ.', 'He who tries to vanquish the one who is above him is overpowered.', 'Ghurar al-Hikam, The Victor and the vanquished- §2', 'wisdom'),
  ('كُلُّ غالِب غَيْرُ اللّهِ مَغْلُوبٌ.', 'Every victor other than Allah, is vanquished.', 'Ghurar al-Hikam, The Victor and the vanquished- §3', 'wisdom'),
  ('لاتُغالِبْ مَنْ لاتَقْدِرُعَلى دَفْعِهِ.', 'Do not pick a fight with one whom you cannot repel.', 'Ghurar al-Hikam, Fighting- §1', 'wisdom'),
  ('غَلَطُ (غَلَظُ) الإنْسانِ فيمَنْ يَنْبَسِطُ إلَيْهِ أحْظَرُ شَيْء عَلَيْهِ.', 'A person’s mistake about (or harshness towards) the one who is friendly towards him is one of the most forbidden things for him.', 'Ghurar al-Hikam, Mistake- §1', 'wisdom'),
  ('شَرُّ ما أُلْقِيَ فِي القُلُوبِ الغُلُولُ.', 'The worst thing that can come upon the hearts is betrayal.', 'Ghurar al-Hikam, Betrayal- §1', 'wisdom'),
  ('اَلْغَشُوشُ لِسانُهُ حُلْوٌ، وَقَلْبُهُ مُرٌّ.', 'The tongue of a perfidious person is sweet but his heart is bitter.', 'Ghurar al-Hikam, Rancor and perfidy- §1', 'wisdom'),
  ('أفْظَعُ الغِشِّ غِشُّ الأئِمَّةِ.', 'The vilest perfidy is the perfidy of the leaders.', 'Ghurar al-Hikam, Rancor and perfidy- §2', 'wisdom'),
  ('إنَّ أغَشَّ النّاسِ أغَشُّهُمْ لِنَفْسِهِ وأعْصاهُمْ لِرَبِّهِ.', 'Verily the most perfidious of all people is the one who is most deceitful to himself and most disobedient to his Lord.', 'Ghurar al-Hikam, Rancor and perfidy- §3', 'wisdom'),
  ('اَلْغِشُّ سَجِيَّةُ المَرَدَةِ.', 'Perfidy is the trait of the recalcitrant.', 'Ghurar al-Hikam, Rancor and perfidy- §4', 'wisdom'),
  ('اَلغِلُّ بَذْرُ الشَّرِّ.', 'Rancour is the seed of evil.', 'Ghurar al-Hikam, Rancor and perfidy- §5', 'wisdom'),
  ('اَلغِلُّ داءُ القُلُوبِ.', 'Rancour is the malady of hearts.', 'Ghurar al-Hikam, Rancor and perfidy- §6', 'wisdom'),
  ('اَلغِشُّ يَكْسِبُ المَسَبَّةَ.', 'Perfidy earns vituperation.', 'Ghurar al-Hikam, Rancor and perfidy- §7', 'wisdom'),
  ('اَلْغِلُّ يُحْبِطُ الحَسَناتِ.', 'Rancour nullifies good deeds.', 'Ghurar al-Hikam, Rancor and perfidy- §8', 'wisdom'),
  ('اَلْغِشُّ شَرُّ المَكْرِ.', 'Perfidy is the worst craftiness.', 'Ghurar al-Hikam, Rancor and perfidy- §9', 'wisdom'),
  ('اَلْغِشُّ مِنْ أخْلاقِ اللِّئامِ.', 'Perfidy is from the characteristics of the wicked.', 'Ghurar al-Hikam, Rancor and perfidy- §10', 'wisdom'),
  ('اَلْغَمُّ يَقْبِضُ النَّفْسَ، ويَطْوِى الاِنْبِساطَ.', 'Grief makes one dispirited and ends one’s joy.', 'Ghurar al-Hikam, Grief- §1', 'wisdom'),
  ('اَلحُزنُ يَهْدِمُ الجَسَدَ.', 'Sorrow destroys the body.', 'Ghurar al-Hikam, Grief- §2', 'wisdom'),
  ('اَلأحْزانُ سُقْمُ القُلُوبِ.', 'Sorrows are the ailment of the hearts.', 'Ghurar al-Hikam, Grief- §3', 'wisdom'),
  ('اَلحُزْنُ شِعارُ المُؤْمِنينَ.', 'Grief is the distinguishing mark of the believers.', 'Ghurar al-Hikam, Grief- §4', 'wisdom'),
  ('اَلْهَمُّ يُذيبُ الجَسَدَ.', 'Grief wears away the body.', 'Ghurar al-Hikam, Grief- §5', 'wisdom'),
  ('اَلْحُزْنُ والجَزَعُ لايَرُدّانِ الفائِتَ.', 'Sorrow and anxiety do not bring back what has been lost.', 'Ghurar al-Hikam, Grief- §6', 'wisdom'),
  ('بِقَدْرِ اللَّذَّةِ يَكُونُ التَّغْصيصُ.', 'To the extent of pleasure, there is distress.', 'Ghurar al-Hikam, Grief- §7', 'wisdom'),
  ('مَنْ تَجَرَّعَ الغُصَصَ أدْرَكَ الفُرَصَ.', 'One who bears his distress [patiently] realizes [his] opportunities.', 'Ghurar al-Hikam, Grief- §8', 'wisdom'),
  ('اَلْهَمُّ أحَدُ الهِرَمَيْنِ.', 'Grief is one of the two senilities.', 'Ghurar al-Hikam, Grief- §9', 'wisdom'),
  ('إطْرَحْ عَنْكَ وارِداتِ الهُمُومِ بِعَزائِمِ الصَّبْرِ، وحُسْنِ اليَقينِ.', 'Cast away the sorrows that come upon you through resolute patience and virtuous certitude.', 'Ghurar al-Hikam, Grief- §10', 'wisdom'),
  ('اِسْتَغْنِ عَمَّنْ شِئْتَ وكُنْ (تَكُنْ) نَظِيرَهُ.', 'Dispense with your dependency on anyone and you will be like him.', 'Ghurar al-Hikam, Being independent of others- §1', 'wisdom'),
  ('مَنِ اسْتَغْنى عَنِ النّاسِ أغْناهُ اللّهُ سُبْحانَهُ.', 'One who is independent from people, Allah, the Glorified, enriches him.', 'Ghurar al-Hikam, Being independent of others- §2', 'wisdom'),
  ('مَنِ اسْتَغْنى كَرُمَ عَلى أهْلِهِ ومَنِ افْتَقَرَ هانَ عَلَيْهِمْ.', 'One who becomes independent becomes an honour for his people and one who is needy becomes contemptible to them.', 'Ghurar al-Hikam, Being independent of others- §3', 'wisdom'),
  ('مَا اسْتَغْنَيْتَ عَنْهُ خَيْرٌ مِمَّا اسْتَغْنَيْتَ بِهِ.', 'That which you have no need for is better than that through which you gain independence.', 'Ghurar al-Hikam, Being independent of others- §4', 'wisdom'),
  ('اَلْغَنِيُّ مَنِ اسْتَغْنى بِالقَناعَةِ.', 'A rich person is he who becomes rich through contentment.', 'Ghurar al-Hikam, Affluence and the rich- §1', 'wisdom'),
  ('اَلْغَنِيُّ مَنْ آثَرَ القَناعَةَ.', 'A [truly] rich person is one who prefers contentment.', 'Ghurar al-Hikam, Affluence and the rich- §2', 'wisdom'),
  ('اَلْغَنِيُّ (اَلْغِنى)فِي الغُرْبَةِ وَطَنٌ.', 'The rich person feels at home [even when he is] in a strange land.', 'Ghurar al-Hikam, Affluence and the rich- §3', 'wisdom'),
  ('جَهْلُ الغَنِيِّ يَضَعُهُ، وعِلْمُ الفَقيرِ يَرْفَعُهُ.', 'The ignorance of a rich person abases him whereas the knowledge of a poor person elevates him.', 'Ghurar al-Hikam, Affluence and the rich- §4', 'wisdom'),
  ('رُبَّ غَنِىّ أذَلُّ مِنْ نَقَد.', 'At times a rich person may be lowlier than an ugly sheep.', 'Ghurar al-Hikam, Affluence and the rich- §5', 'wisdom'),
  ('رُبَّ غَنِىّ أفْقَرُ مِنْ فَقير.', 'Sometimes a rich person may be needier than a poor person.', 'Ghurar al-Hikam, Affluence and the rich- §6', 'wisdom'),
  ('قَليلٌ مِنَ الأغْنِياءِ مَنْ يُواسي ويُسْعِفُ.', 'Few are the rich who [financially] support and assist others.', 'Ghurar al-Hikam, Affluence and the rich- §7', 'wisdom'),
  ('كَمْ مِنْ غَنِىّ يُسْتَغْنى عَنْهُ.', 'How many of the rich are unneeded [because of their unwillingness to help others].', 'Ghurar al-Hikam, Affluence and the rich- §8', 'wisdom'),
  ('مِنَ الواجِبِ عَلَى الغَنِيِّ أنْ لايَضُنَّ عَلَى الفَقيرِبِمالِهِ.', 'It is obligatory upon the rich person not to withhold his wealth from the poor.', 'Ghurar al-Hikam, Affluence and the rich- §9', 'wisdom'),
  ('لاتَعُدَّنَّ غَنِياً مَنْ لَمْ يُرْزَقْ مِنْ مالِهِ.', 'Never count the one from whose wealth others don’t get sustenance as a rich person.', 'Ghurar al-Hikam, Affluence and the rich- §10', 'wisdom'),
  ('بِإغاثَةِ المَلْهُوفِ يَكُونُ لَكَ مِنْ عَذابِ اللّهِ حِصْنٌ.', 'Through aiding the aggrieved, there is a protection for you from the chastisement of Allah.', 'Ghurar al-Hikam, Coming to the aid of the aggrieved- §1', 'wisdom'),
  ('مِنْ كَفّاراتِ الذُّنُوبِ العِظامِ إغاثَةُ المَلْهُوفِ.', 'From the expiations of great sins is aiding the aggrieved.', 'Ghurar al-Hikam, Coming to the aid of the aggrieved- §2', 'wisdom'),
  ('مِنْ أفْضَلِ المَعْرُوفِ إغاثَةُ المَلْهُوفِ.', 'Coming to the aid of the aggrieved is one of the best benevolent acts.', 'Ghurar al-Hikam, Coming to the aid of the aggrieved- §3', 'wisdom'),
  ('ما حَصَلَ الأجْرُ بِمِثْلِ إغاثَةِ المَلْهُوفِ.', 'Nothing beings reward like aiding the aggrieved.', 'Ghurar al-Hikam, Coming to the aid of the aggrieved- §4', 'wisdom'),
  ('اَلسّامِعُ لِلْغِيْبَةِ أحَدُ المُغتابَيْنِ.', 'The one who listens to gossip is one of the two backbiters.', 'Ghurar al-Hikam, Backbiting- §1', 'character'),
  ('إيّاكَ والغيبَةَ، فَإنَّها تُمَقِّتُكَ إلَى اللّهِ والنّاسِ، وتُحْبِطُ أجْرَكَ.', 'Beware of backbiting, for indeed it makes you hated by Allah and the people, and renders you rewards void.', 'Ghurar al-Hikam, Backbiting- §2', 'character'),
  ('اَلأمُ النّاسِ اَلمُغْتابُ.', 'The wicked of [all] people is the backbiter.', 'Ghurar al-Hikam, Backbiting- §3', 'character'),
  ('أبْغَضُ الخَلائِقِ إلَى اللّهِ المُغْتابُ.', 'The most hated of creatures in the sight of Allah is the backbiter.', 'Ghurar al-Hikam, Backbiting- §4', 'character'),
  ('إنَّ ذِكْرَ الغيبَةِ شَرُّ الإفْكِ.', 'Verily the mentioning of slander is the worst falsehood.', 'Ghurar al-Hikam, Backbiting- §5', 'character'),
  ('اَلغيبَةُ شَرُّ الإفْكِ.', 'Slander is the worst falsehood.', 'Ghurar al-Hikam, Backbiting- §6', 'character'),
  ('اَلغيبَةُ آيَةُ المُنافِقِ.', 'Backbiting is the sign of a hypocrite.', 'Ghurar al-Hikam, Backbiting- §7', 'character'),
  ('اَلغيبَةُ جُهْدُ العاجِزِ.', 'Backbiting is the effort of the feeble.', 'Ghurar al-Hikam, Backbiting- §8', 'character'),
  ('اَلغيبَةُ قُوتُ كِلابِ النّارِ.', 'Backbiting is the food of the dogs of hell.', 'Ghurar al-Hikam, Backbiting- §9', 'character'),
  ('اَلسّامِعُ لِلْغيبَةِ كَالمُغْتابِ.', 'The one who listens to gossip is just like the backbiter.', 'Ghurar al-Hikam, Backbiting- §10', 'character'),
  ('فِي الغَيْبِ العَجَبُ.', 'In the unseen there is wonder.', 'Ghurar al-Hikam, The unseen- §1', 'wisdom'),
  ('إيّاكَ والتَّغايُـرَ في غَيْرِ مَوْضِعِهِ، فَإنَّ ذلِكَ يَدْعُو الصَّحِيحَةَ إلَى السَّقَمِ، والبَريئَةَ إلَى الرَّيْبِ.', 'Beware of being possessive in a situation where it is not required, for verily this will lead the soul that is sound to become sick and the one that is innocent [and calm] into suspicion [and uneasiness].', 'Ghurar al-Hikam, The unseen- §1', 'wisdom'),
  ('دَلِيلُ غَيْرَةِ الرَّجُلِ عِفَّتُهُ.', 'The proof of a man’s sense of honour is his chastity.', 'Ghurar al-Hikam, The unseen- §2', 'wisdom'),
  ('غَيْرَةُ الرَّجُلِ إيمانٌ.', 'A man’s sense of honour is faith.', 'Ghurar al-Hikam, The unseen- §3', 'wisdom'),
  ('غَيْرَةُ المَرْأةِ عُدْوانٌ.', 'The possessiveness of a woman is transgression.', 'Ghurar al-Hikam, The unseen- §4', 'wisdom'),
  ('غَيْرَةُ الرَّجُلِ عَلى قَدْرِ أنَفَتِهِ.', 'A man’s sense of honour is to the extent of his self-respect.', 'Ghurar al-Hikam, The unseen- §5', 'wisdom'),
  ('غَيْرَةُ المُؤمِنِ بِاللّهِ سُبْحانَهُ.', 'The believer’s possessiveness is for [the sake of] Allah, the Glorified.', 'Ghurar al-Hikam, The unseen- §6', 'wisdom'),
  ('أسْوَءُ شَيْء عاقِبَةً الغَيُّ.', 'The thing with the worst outcome is deviation [from the right path].', 'Ghurar al-Hikam, Deviation from the right path- §1', 'wisdom'),
  ('اَلغَيُّ أشَرٌ.', 'Deviation is insolence.', 'Ghurar al-Hikam, Deviation from the right path- §2', 'wisdom'),
  ('مَنْ عامَلَ بِالغَيِّ كُوفِيَ بِهِ.', 'One who deals offensively [with others] is dealt with in the same way.', 'Ghurar al-Hikam, Deviation from the right path- §3', 'wisdom'),
  ('وَيْلٌ لِمَنْ تَمادى في غَيِّهِ، ولَمْ يَفِئْ إلَى الرُّشْدِ.', 'Woe be to the one who persists in his deviation and does not return to the right path.', 'Ghurar al-Hikam, Deviation from the right path- §4', 'wisdom'),
  ('لاوَرَعَ مَعَ عَىّ.', 'There is no piety with deviation.', 'Ghurar al-Hikam, Deviation from the right path- §5', 'wisdom'),
  ('مَنْ بَلَغَ غايَةَ ما يُحِبُّ فَلْيَتَوَقَّعْ غايَةَ ما يَكْرَهُ.', 'Whoever attains the utmost of what he loves, then let him expect the utmost of what he hates.', 'Ghurar al-Hikam, The utmost- §1', 'wisdom'),
  ('تَفَأَّلْ بِالخَيْرِ تُنْجِـحْ.', 'Be optimistic and you will become successful.', 'Ghurar al-Hikam, Being optimistic- §1', 'wisdom'),
  ('اَلفِتْنَةُ (القُنْيَة) مَقْرُونَةٌ بِالعَناءِ.', 'Unrest (or acquisition [of property]) is accompanied by hardship.', 'Ghurar al-Hikam, Unrest- §1', 'wisdom'),
  ('كُنْ فِي الفِتْنَةِ كَابْنِ اللَّبُونِ، لاضَرْعَ فَيُحْلَبَ ولاظَهْرَ فَيُرْكَبَ.', 'In times of unrest, be like an adolescent camel that has neither udders for milking nor a back strong enough for riding.', 'Ghurar al-Hikam, Unrest- §2', 'wisdom'),
  ('مَنْ شَبَّ نارَ الفِتْنَةِ كانَ وَقُوداً لَها.', 'One who ignites the fire of sedition will become fuel for it.', 'Ghurar al-Hikam, Unrest- §3', 'wisdom'),
  ('مِنْ أعْظَمِ المِحَنِ دَوامُ الفِتَنِ.', 'One of the greatest tribulations is the continuation of strife.', 'Ghurar al-Hikam, Unrest- §4', 'wisdom'),
  ('قَدْلَعَمْري يَهْلِكُ في لَهَبِ الفِتْنَةِ المُؤْمِنُ، ويَسْلَمُ فيها غَيْرُ المُسْلِمِ.', 'I swear by my life that in the flames of unrest [that come after me], the believer will get destroyed while the non-Muslim shall remain safe.', 'Ghurar al-Hikam, Unrest- §5', 'wisdom'),
  ('ما كُلُّ مَفْتُون يُعاتَبُ.', 'Not everyone who is enthralled is reproached.', 'Ghurar al-Hikam, The one who is enthralled- §1', 'wisdom'),
  ('اَلفُتُوَّةُ نائِلٌ مَبْذُولٌ، وأذىً مَكْفُوفٌ.', 'Chivalry is a gift that is granted and a harm that is restrained.', 'Ghurar al-Hikam, Chivalry- §1', 'wisdom'),
  ('ما تَزَيَّنَ الإنْسانُ بِزِينَة أجْمَلَ مِنَ الفُتُوَّةِ.', 'The human being has not been adorned with anything more beautiful than chivalry.', 'Ghurar al-Hikam, Chivalry- §2', 'wisdom'),
  ('نِظامُ الفُتُوَّةِ اِحْتِمالُ عَثَراتِ الإخْوانِ،وَ حُسْنُ تَعَهُّدِ الجيرانِ.', 'The order of chivalry is being tolerant of the mistakes of one’s brothers and fulfilling one’s obligation towards his neighbours.', 'Ghurar al-Hikam, Chivalry- §3', 'wisdom'),
  ('اَلْفُجُورُ دارُ حِصْن ذَلِيل، لايَمْنَعُ أهْلَهُ، ولايُحْرِزُ مَنْ لَجَأَ إلَيْهِ.', 'Wickedness is a decrepit fortress, it does not prevent [any harm from reaching] its people, nor does it protect the one who seeks refuge in it.', 'Ghurar al-Hikam, Wickedness and immorality- §1', 'wisdom'),
  ('إيّاكَ وَمَحاضِرَ الفُسُوقِ، فَإنَّها مُسْخِطَةٌ لِلرَّحْمنِ، مُصْلِيَةٌ لِلنِّيرانِ.', 'Beware of immoral gatherings, for indeed they anger the Most Merciful and take you to the fire of hell.', 'Ghurar al-Hikam, Wickedness and immorality- §2', 'wisdom'),
  ('اَلفُجُورُ مِنْ شِيَمِ الكُفّارِ.', 'Wickedness is from the traits of the disbelievers.', 'Ghurar al-Hikam, Wickedness and immorality- §3', 'wisdom'),
  ('إنَّ الفُجّارَ كُلُّ ظَلُوم خَتُور.', 'Verily the wicked comprise of all the oppressive and treacherous people.', 'Ghurar al-Hikam, Wickedness and immorality- §4', 'wisdom'),
  ('اَلفاجِرُ مُجاهِرٌ.', 'The wicked is one who declares [his sins] openly.', 'Ghurar al-Hikam, Wickedness and immorality- §5', 'wisdom'),
  ('اَلفاسِقُ لاغيبَةَ لَهُ.', 'There is no [sin for] backbiting for the [openly] corrupt.', 'Ghurar al-Hikam, Wickedness and immorality- §6', 'wisdom'),
  ('اَلفَجُورُ لاتَقِيَّةَ لَهُ.', 'The immoral person has no [sense of] caution.', 'Ghurar al-Hikam, Wickedness and immorality- §7', 'wisdom'),
  ('دُوَلُ الفُجّارِ مَذَلَّةُ الأبْرارِ.', 'The reign of the wicked is the [cause of] abasement of the virtuous.', 'Ghurar al-Hikam, Wickedness and immorality- §8', 'wisdom'),
  ('فِرُّوا كُلَّ الفِرارِ مِنَ الفاجِرِ الفاسِقِ.', 'Flee far away from the wicked, immoral one.', 'Ghurar al-Hikam, Wickedness and immorality- §9', 'wisdom'),
  ('قَطيعَةُ الفاجِرِ غُنْمٌ.', 'The cutting off ties with an immoral person is a gain.', 'Ghurar al-Hikam, Wickedness and immorality- §10', 'wisdom'),
  ('اِحْذَرْ فُحْشَ القَوْلِ والكِذْبَ، فَإنَّهُما يُزْرِيانِ بِالقائِلِ.', 'Be careful of obscene language and lies, for indeed they degrade the speaker.', 'Ghurar al-Hikam, Obscentiy- §1', 'wisdom'),
  ('سَفَهُكَ عَلى مَنْ فَوْقَكَ جَهْلٌ مُرْد.', 'Using obscene language with one who is above you is destructive ignorance.', 'Ghurar al-Hikam, Obscentiy- §2', 'wisdom'),
  ('سَفَهُكَ عَلى مَنْ دُونَكَ جَهْلٌ مُزْر.', 'Using obscene language with one who is below you is abasing ignorance.', 'Ghurar al-Hikam, Obscentiy- §3', 'wisdom'),
  ('سَفَهُكَ عَلى مَنْ في دَرَجَتِكَ نِقارٌ كَنِقارِ الديكَيْنِ، وهِراشٌ كَهِراشِ الكَلْبَيْنِ، ولَنْ يَفْتَرِقا إلاّ مَجْرُوحَيْنِ، أوْ مَفْضُوحَيْنِ، ولَيْسَ ذلِكَ فِعْلُ الحُكَماءِ، ولاسُنَّةُ العُقَلاءِ، ولَعَلَّهُ أنْ يَحْلُمَ عَنْكَ، فَيَكُونَ أوْزَنَ مِنْكَ وأكرَمَ، وَأنْتَ أنْقَصُ مِنْهُ وأَلأَمُ.', 'Using obscene language with one who is at your level is a pecking like the pecking of two cockerels, and a quarrelling like the quarrelling of two dogs, they will never separate until they are wounded or humiliated, and this is neither the act of the wise nor the practice of the intelligent; and it may be that he (your rival) shows forbearance towards you, thereby becoming greater than you and more honourable, while you remain lower than him and more contemptible.', 'Ghurar al-Hikam, Obscentiy- §4', 'wisdom'),
  ('مَنْ سافَهَ شُتِمَ.', 'One who uses obscene language is reviled.', 'Ghurar al-Hikam, Obscentiy- §5', 'wisdom'),
  ('مَنْ كَثُرَسَفَهُهُ اُسْتُرْذِلَ.', 'One whose obscenity increases is regarded as vile.', 'Ghurar al-Hikam, Obscentiy- §6', 'wisdom'),
  ('ما أفْحَشَ كَريمٌ قَطُّ.', 'An honourable person never uses obscene language, ever.', 'Ghurar al-Hikam, Obscentiy- §7', 'wisdom'),
  ('لاأوْقَحَ مِنْ بَذِىّ.', 'There is none more shameless than the one who utters obscenities.', 'Ghurar al-Hikam, Obscentiy- §8', 'wisdom'),
  ('إنَّ الْفُحْشَ والتَّفَحُّشَ لَيْسا مِنْ خَلائِقِ الإسْلامِ.', 'Indeed obscene language and vulgarities are not from the morals of Islam.', 'Ghurar al-Hikam, Obscentiy- §9', 'wisdom'),
  ('مَنْ أفْحَشَ شَفى حُسّادَهُ.', 'One who uses obscene language cures [the envy of] his enviers [and brings them joy].', 'Ghurar al-Hikam, Obscentiy- §10', 'wisdom'),
  ('ما لابْنِ آدَمَ والفَخْرَ، وأوَّلُهُ نُطْفَةٌ، وآخِرُهُ جيفَةٌ، لايَرْزُقُ نَفْسَهُ، وَلايَدْفَعُ حَتْفَهُ.', 'What reason has a human being to be proud when his beginning is a drop of semen and his end is a carcass; neither can he sustain himself nor can he repel his [own] death!', 'Ghurar al-Hikam, Pride and boasting- §1', 'wisdom'),
  ('لاتَدُلَّنَّ بِحالَة بَلَغْتَها بِغَيْرِ آلَة، ولاتَفْخِرَنَّ بِمَرْتَبـَة نِلْتَها مِنْ غَيْرِ مَنْقَبَة، فَإنَّ ما يَبْنيهِ الإتِّفاقُ يَهْدِمُهُ الاِسْتِحْقاقُ.', 'Never become proud of a state that you attained without [any] device [and hard work], and never be arrogant of a rank that you attained without merit, for indeed that which is built by circumstance is destroyed by entitlement.', 'Ghurar al-Hikam, Pride and boasting- §2', 'wisdom'),
  ('لاحُمْقَ أعْظَمُ مِنَ الفَخْرِ.', 'There is no foolishness greater than arrogance.', 'Ghurar al-Hikam, Pride and boasting- §3', 'wisdom'),
  ('يَنْبَغي أنْ يَكُونَ التَّفاخُرُ بِعَلِيِّ الهِمَمِ، والوَفاءِ بِالذِّمَمِ، والمُبالَغَةِ فيِ الكَرَمِ، لابِبَوالِى الرِّمَمِ، ورَذائِلِ الشِّيَمِ.', 'Boasting ought to be about the greatest effort, keeping promises and being overly generous, not about the worn out bones [of one’s ancestors] and evil traits.', 'Ghurar al-Hikam, Pride and boasting- §4', 'wisdom'),
  ('اَلاِفْتِخارُ مِنْ صِغَرِ الأقْدارِ.', 'Boastfulness stems from the smallness of [one’s] status [and worth].', 'Ghurar al-Hikam, Pride and boasting- §5', 'wisdom'),
  ('إيّاكَ ومُساماةَ اللّهِ سُبْحانَهُ في عَظَمَتِهِ، فَإنَّ اللّهَ تَعالى يُذِلُّ كُلَّ جَبّار، وَيُهينُ كُلَّ مُخْتال.', 'Beware of contesting with Allah, the Glorified, in His greatness, for Allah, the Most High, abases every tyrant and belittles every boaster.', 'Ghurar al-Hikam, Pride and boasting- §6', 'wisdom'),
  ('أضْيَقُ ما يَكُونُ الحَرَجُ أقْرَبُ ما يَكُونُ الفَرَجُ.', 'The more restricting [and difficult] the hardship, the closer the relief.', 'Ghurar al-Hikam, Relief and waiting for relief- §1', 'wisdom'),
  ('أقْرَبُ ما يَكُونُ الفَرَجُ عِنْدَ تَضايُقِ الأمْرِ.', 'The time when relief is closest is when the affair becomes unbearable.', 'Ghurar al-Hikam, Relief and waiting for relief- §2', 'wisdom'),
  ('عِنْدَ اِنْسِدادِ الفُرَجِ تَبْدُومَطالِـعُ الفَرَجِ.', 'When the openings [and ways] get blocked, the rays of relief begin to appear.', 'Ghurar al-Hikam, Relief and waiting for relief- §3', 'wisdom'),
  ('عِنْدَ تَناهِي الشَّدائِدِ يَكُونُ تَوَقُّعُ الفَرَجِ.', 'When the difficulties reach their peak, there is hope for relief.', 'Ghurar al-Hikam, Relief and waiting for relief- §4', 'wisdom'),
  ('أوَّلُ العِبادَةِ اِنْتِظارُ الفَرَجِ بِالصَّبْرِ.', 'The first act of worship is waiting for relief with patience.', 'Ghurar al-Hikam, Relief and waiting for relief- §5', 'wisdom'),
  ('تَوَقُّعُ الفَرَجِ إحْدىَ الراحَتَيْنِ.', 'Expecting relief is one of the two comforts.', 'Ghurar al-Hikam, Relief and waiting for relief- §6', 'wisdom'),
  ('كَمْ مِنْ فَرَح أفْضى بِهِ فَرَحُهُ إلى حُزْن مُخَلَّد.', 'How many a joyful [person] has been driven by his joy towards perpetual sorrow.', 'Ghurar al-Hikam, Happiness and joy- §1', 'wisdom'),
  ('لا تَفْرَحْ بِما هُوَ آت.', 'Do not be joyful about that which is coming [to you].', 'Ghurar al-Hikam, Happiness and joy- §2', 'wisdom'),
  ('لاتَفْرَحَنَّ بِسَقْطَةِ غَيْرِكَ فَإنَّكَ لاتَدْري ما يُحْدِثُ بِكَ الزَّمانُ.', 'Never be joyful about the downfall of others for verily you do not know what time will do to you.', 'Ghurar al-Hikam, Happiness and joy- §3', 'wisdom'),
  ('لاتَبْتَهِجَنَّ بِخَطاءِ غَيْرِكَ فَإنَّكَ لَنْ تَمْلِكَ الإصابَةَ أبَداً.', 'Do not be happy with the mistake of others, for indeed you will not always be correct.', 'Ghurar al-Hikam, Happiness and joy- §4', 'wisdom'),
  ('فِرُّوا إلَى اللّهِ سُبْحانَهُ ولاتَفِرُّوا مِنْهُ فَإنَّهُ مُدْرِكُكُمْ ولَنْ تُعْجِزُوهُ.', 'Flee towards Allah, the Glorified, and do not flee away from Him, for indeed He will find you and you will not escape Him.', 'Ghurar al-Hikam, Fleeing to Allah- §1', 'wisdom'),
  ('لَيْسَ كُلُّ غائِب يَؤُُوُبُ.', 'Not everything that has gone comes back.', 'Ghurar al-Hikam, Opportunity and its loss- §1', 'purpose'),
  ('مَنْ غافَصَ الفُرَصَ أمِنَ الغُصَصَ.', 'One who takes advantage of [unexpected] opportunities remains safe from distress.', 'Ghurar al-Hikam, Opportunity and its loss- §2', 'purpose'),
  ('مَنْ وَجَدَ مَوْرِداً عَذْباً يَرْتَوي مِنْهُ فَلَمْ يَغْتَنِمْهُ يُوشِكُ أنْ يَظْمَأَ ويَطْلُبَهُ فَلا يَجِدُهُ.', 'Whoever finds a place where sweet water enters and he can quench his thirst with it but does not take advantage of it, he will soon feel thirsty and seek it, but will not find it.', 'Ghurar al-Hikam, Opportunity and its loss- §3', 'purpose'),
  ('رُبَّ فائِت لايُدْرَكُ لِحاقُهُ.', 'Many a lost thing is such that it cannot be regained.', 'Ghurar al-Hikam, Opportunity and its loss- §4', 'purpose'),
  ('رُبَّ ساع سَريع نَجا، وطالِب بَطيء رَجا.', 'It may be that he who strives and acts quickly is saved [and succeeds] while the slow seeker [only] hopes [to attain it in the future].', 'Ghurar al-Hikam, Opportunity and its loss- §5', 'purpose'),
  ('عَوْدُ الفُرْصَةِ بَعيدٌ مَرامُها.', 'The return of an opportunity [that is lost] is far off and unlikely.', 'Ghurar al-Hikam, Opportunity and its loss- §6', 'purpose'),
  ('غافِصِ الفُرْصَةَ عِنْدَ إمْكانِها فَإنَّكَ غَيْرُ مُدْرِكِها بَعْدَ فَوْتِها.', 'Seize the opportunity when it arises, for indeed you will not get it [again] after you lose it.', 'Ghurar al-Hikam, Opportunity and its loss- §7', 'purpose'),
  ('تَنَفَّسُوا قَبْلَ ضيقِ الخِناقِ، وانْقادُوا قَبْلَ عُنْفِ السِّياقِ.', 'Breathe before the necks are strangled, and yield before being driven violently.', 'Ghurar al-Hikam, Opportunity and its loss- §8', 'purpose'),
  ('خُذُوا مَهَلَ الأيّامِ، وحُوطُواْ قَواصِيَ الإسْلامِ، وبادِرُوا هُجُومَ الحِمامِ.', 'Take the respite of the days, protect the boundaries of Islam, and anticipate the sudden attack of death.', 'Ghurar al-Hikam, Opportunity and its loss- §9', 'purpose'),
  ('رَحِمَ اللّهُ امْرَءاً إغْتَنَمَ المَهَلَ، وبادَرَ العَمَلَ، وأَكْمَشَ مِنْ وَجَل.', 'May Allah have mercy on the one who takes the benefit of respite [and opportunity], hastens towards good deeds and cowers out of fear [of Allah].', 'Ghurar al-Hikam, Opportunity and its loss- §10', 'purpose'),
  ('المُتَقَرِّبُ بِأداءِ الفَرائِضِ والنَّوافِلِ مُتَضاعِفُ الأرْباحِ.', 'The one who seeks nearness [to Allah] by performing the obligatory and the recommended [acts], doubles his gain.', 'Ghurar al-Hikam, The obligatory and recommended acts- §1', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ فَرَضَ عَلَيْكُمْ فَرائِضَ فَلا تُضَيِّعُوها، وحَدَّ لَكُمْ حُدُوداً فَلا تَعْتَدُوها، وَنَهاكُمْ عَنْ أشْياءَ فَلا تَنْتَهِكُوها،', 'Verily Allah, the Glorified, has made the obligatory [acts] incumbent upon you, so do not neglect them; and has delimited boundaries for you, so do not transgress them; and has forbidden you from certain things, so do not violate them; and has remained silent about certain things, though not out of forgetfulness, so do not undertake them.', 'Ghurar al-Hikam, The obligatory and recommended acts- §2', 'wisdom'),
  ('إنَّ مَنْ شَغَلَ نَفْسَهُ بِالمَفْرُوضِ عَلَيْهِ عَنِ المَضْمُونِ لَهُ، ورَضِيَ بِالمَقْدُورِ عَلَيْهِ ولَهُ، كانَ أكْثَرَ النّاسِ سَلامَةً في عافِيَة، ورِبْحاً في غِبْطَة، وَغَنيمَةً في مَسَرَّة.', 'Verily whoever busies himself with what is obligatory upon him instead of that which has been guaranteed for him, and is satisfied with what has been decreed for and against him; he will be the healthiest person in wellbeing, the most profiting from felicity and the most benefitting from happiness.', 'Ghurar al-Hikam, The obligatory and recommended acts- §3', 'wisdom'),
  ('إنَّكَ إنِ اشْتَغَلْتَ بِفَضائِلِ النَّوافِلِ عَنْ أداءِ الفَرائِضِ فَلَنْ يَقُومَ فَضْلٌ تَكْسِبُهُ بِفَرْض تُضَيِّعُهُ.', 'Verily if you were to occupy yourself with meritorious supererogatory acts instead of fulfilling the obligatory ones, then the merit you acquire will never make up for the religious obligation that you have neglected.', 'Ghurar al-Hikam, The obligatory and recommended acts- §4', 'wisdom'),
  ('إذا أضَرَّتِ النَّوافِلُ بِالفَرائِضِ فَارْفُضُوها.', 'When recommended acts come in the way of obligatory actions, then abandon them.', 'Ghurar al-Hikam, The obligatory and recommended acts- §5', 'wisdom'),
  ('عَلَيْكَ بِحِفْظِ كُلِّ أمْر لاتُعْذَرُ بِإضاعَتِهِ.', 'It is upon you to preserve every matter that you cannot be excused for neglecting.', 'Ghurar al-Hikam, The obligatory and recommended acts- §6', 'wisdom'),
  ('قَضاءُ اللَّوازِمِ مِنْ أفْضَلِ المَكارِمِ.', 'Fulfilling the obligatory is from the most noble of actions.', 'Ghurar al-Hikam, The obligatory and recommended acts- §7', 'wisdom'),
  ('لاعِبادَةَ كَأداءِ الفَرائِضِ.', 'There is no worship like the performing of obligatory acts.', 'Ghurar al-Hikam, The obligatory and recommended acts- §8', 'wisdom'),
  ('لاقُرْبَةَ بِالنَّوافِلِ إذا أضَرَّتْ بِالفَرائِضِ.', 'No closeness is achieved through recommended actions if they hamper the obligatory actions.', 'Ghurar al-Hikam, The obligatory and recommended acts- §9', 'wisdom'),
  ('لاتَقْضِ نافِلَةً في وَقْتِ فَريضَة، إبْدَأْ بِالفَريضَةِ ثُمَّ صَلِّ ما بَدا لَكَ.', 'Do not perform a recommended act at the time of an obligatory one; start with the obligatory [prayer] and then pray whatever more you wish to.', 'Ghurar al-Hikam, The obligatory and recommended acts- §10', 'wisdom'),
  ('اِحْذَرُوا التَّفْريطَ فَإنَّهُ يُوجِبُ المَلامَةَ.', 'Be wary of neglect for verily it causes censure.', 'Ghurar al-Hikam, Neglect- §1', 'wisdom'),
  ('اَلتَفْريطُ مُصيبَةُ القادِرِ.', 'Neglect is an affliction of the capable.', 'Ghurar al-Hikam, Neglect- §2', 'wisdom'),
  ('ثَمَرَةُ التَّفْريطِ مَلامَةٌ.', 'The fruit of neglect is censure.', 'Ghurar al-Hikam, Neglect- §3', 'wisdom'),
  ('ضادُّوا التفْريطَ بِالحَزْمِ.', 'Counter neglect with judiciousness [and resoluteness].', 'Ghurar al-Hikam, Neglect- §4', 'wisdom'),
  ('مِنَ الفَراغِ تَكُونُ الصَّبْوَةُ.', 'From idleness comes inclination towards [vain] desire.', 'Ghurar al-Hikam, Idleness- §1', 'wisdom'),
  ('مَعَ الفَراغِ تَكُونُ الصَّبْوَةُ.', 'With idleness there is inclination towards [vain] desire.', 'Ghurar al-Hikam, Idleness- §2', 'wisdom'),
  ('إيّاكَ والفُرْقَةَ، فَإنَّ الشّاذَّ مِنَ النّاسِ لِلشَّيْطانِ.', 'Beware of separation [from the people], for indeed the one who is isolated from the people is [a target] for Satan.', 'Ghurar al-Hikam, Seperation and isolation- §1', 'wisdom'),
  ('إيّاكُمْ والفُرْقَةَ، فَإنَّ الشّاذَّ عَنْ أهْلِ الحَقِّ لِلشَّيْطانِ، كَما أنَّ الشّاذَّ مِنَ الغَنَمِ لِلذِّئْبِ.', 'Beware of separation, for indeed the one who is isolated from the people of truth is [prey] for Satan just as the lonely sheep is [prey] for the wolf.', 'Ghurar al-Hikam, Seperation and isolation- §2', 'wisdom'),
  ('بِئْسَ السَّعْيُ اَلتَّفْرِقَةُ بَيْنَ الأليفَيْنِ.', 'The worst endeavour is separating two close friends.', 'Ghurar al-Hikam, Seperation and isolation- §3', 'wisdom'),
  ('لِكُلِّ جَمْع فُرْقَةٌ.', 'For every gathering there is separation.', 'Ghurar al-Hikam, Seperation and isolation- §4', 'wisdom'),
  ('اِلْـزَمُوا الجَماعَةَ، واجْتَنِبُوا الفُرْقَةَ.', 'Remain with the community and eschew separation.', 'Ghurar al-Hikam, Seperation and isolation- §5', 'wisdom'),
  ('هَلَكَ مَنِ ادَّعى، وخابَ مَنِ افْتَرى.', 'Destroyed is the one who makes a [wrongful] claim, and unsuccessful is the one who fabricates [a lie].', 'Ghurar al-Hikam, Fabrication of lies- §1', 'wisdom'),
  ('مَنْ سَرَّهُ الفَسادُ ساءَهُ المَعادُ.', 'One who is pleased by corruption is displeased by the Hereafter.', 'Ghurar al-Hikam, Corruption- §1', 'wisdom'),
  ('لاصَلاحَ مَعَ إفْساد.', 'There is no rectitude with corruption.', 'Ghurar al-Hikam, Corruption- §2', 'wisdom'),
  ('مَنْ فَسَدَ مَعَ اللّهِ لَمْ يَصْلُحْ مَعَ أحَد.', 'One who corrupts [his relationship] with Allah will not be upright with anyone.', 'Ghurar al-Hikam, Corruption- §3', 'wisdom'),
  ('لاتُفْسِدْ ما يَعْنيكَ صَلاحُهُ.', 'Do not corrupt the thing whose rectitude is important for you.', 'Ghurar al-Hikam, Corruption- §4', 'wisdom'),
  ('اَلفَشَلُ مَنْقَصَةٌ.', 'Indolence is deficiency.', 'Ghurar al-Hikam, Indolence and lassitude- §1', 'wisdom'),
  ('تَداوَمِنْ داءِ الفَتْرَةِ في قَلْبِكَ بِعَزيمَة، وَمِنْ كَرَى الْغَفْلَةِ في ناظِرِكَ بِيَقْظَة.', 'Cure the ailment of lassitude in your heart through determination and the slumber of negligence in your eyes through alertness.', 'Ghurar al-Hikam, Indolence and lassitude- §2', 'wisdom'),
  ('عارُ الفَضيحَةِ يُكَدِّرُ حَلاوَةَ اللَّذَّةِ.', 'The shame of ignominy embitters the sweetness of pleasure.', 'Ghurar al-Hikam, Ignominy- §1', 'wisdom'),
  ('أكْرِهْ نَفْسَكَ عَلَى الفَضائِلِ، فَإنَّ الرَّذائِلَ أنْتَ مَطْبُوعٌ عَلَيْها.', 'Compel yourself to [acquire] virtues, for indeed you have a natural propensity for vices.', 'Ghurar al-Hikam, Virtues and vices- §1', 'character'),
  ('اَلاِرْتِقاءُ إلَى الفَضائِلِ صَعْبٌ مُنـْج.', 'Ascending towards virtues is a hardship that saves.', 'Ghurar al-Hikam, Virtues and vices- §2', 'character'),
  ('يُنْبِئُ عَنْ فَضْلِكَ عِلْمُكَ وعَنْ إفْضالِكَ بَذْلُكَ.', 'Your knowledge conveys your merit and your generosity tells of your kindness.', 'Ghurar al-Hikam, Virtues and vices- §3', 'character'),
  ('إذَا اتَّقَيْتَ المُحَرماتِ، وتَوَرَّعْتَ عَنِ الشُّبَهاتِ وأدَّيْتَ المَفْرُوضاتِ، وَتَنَفَّلْتَ بِالنَّوافِلِ فَقَدْ أكْمَلْتَ فِي الدِّينِ اَلفَضائِلَ.', 'When you keep away from the forbidden, refrain from that which you are unsure about, fulfil that which is obligatory and perform the acts that are recommended, then you have perfected the virtues of faith.', 'Ghurar al-Hikam, Virtues and vices- §4', 'character'),
  ('رَأْسُ الفَضائِلِ مُلْكُ الغَضَبِ وإماتَةُ الشَّهْوَةِ.', 'The peak of [all] merits is controlling anger and eradicating lustful desires.', 'Ghurar al-Hikam, Virtues and vices- §5', 'character'),
  ('عِنْدَ تَعاقُبِ الشَّدائِدِ تَظْهَرُ فَضائِلُ الإنْسانِ.', 'During successive hardships the virtues of a person become manifest.', 'Ghurar al-Hikam, Virtues and vices- §6', 'character'),
  ('عُنْوانُ فَضيلَةِ المَرْءِ عَقْلُهُ، وحُسْنُ خُلْقِهِ.', 'The symbol of a person’s merit is his intelligence and good character.', 'Ghurar al-Hikam, Virtues and vices- §7', 'character'),
  ('غايَةُ الفَضائِلِ العَقْلُ.', 'The highest of all merits is intelligence.', 'Ghurar al-Hikam, Virtues and vices- §8', 'character'),
  ('غايَةُ الفَضائِلِ العِلْمُ.', 'The highest of all merits is knowledge.', 'Ghurar al-Hikam, Virtues and vices- §9', 'character'),
  ('فَضْلُ الرَّجُلِ يُعْرَفُ مِنْ قَوْلِهِ.', 'The merit of a man is known from his speech.', 'Ghurar al-Hikam, Virtues and vices- §10', 'character'),
  ('شَرُّ ما شَغَلَ بِهِ المَرْءُ وَقْتَهُ الفُضُولُ.', 'The worst thing which a person occupies his time with is the superfluous.', 'Ghurar al-Hikam, The superfluous- §1', 'wisdom'),
  ('ضِياعُ العُقُولِ في طَلَبِ الفُضُولِ.', 'The wastage of intellects is in seeking the superfluous.', 'Ghurar al-Hikam, The superfluous- §2', 'wisdom'),
  ('مَنْ أمْسَكَ عَنِ الفُضُولِ عَدَّلَتْ رَأْيَهُ العُقُولُ.', 'Whoever restrains himself from the superfluous, his view is harmonized by the intellects.', 'Ghurar al-Hikam, The superfluous- §3', 'wisdom'),
  ('مَنِ اشْتَغَلَ بِالفُضُولِ فاتَهُ مِنْ مُهِمِّهِ المَأْمُولُ.', 'Whoever occupies himself with the superfluous, the important matter that he hopes for eludes him.', 'Ghurar al-Hikam, The superfluous- §4', 'wisdom'),
  ('اَلفِطْنَةُ بِالبَصيرَةِ.', 'Astuteness is [gained] through discernment.', 'Ghurar al-Hikam, Astuteness- §1', 'wisdom'),
  ('اَلفِطْنَةُ هِدايَةٌ.', 'Astuteness is [a means of attaining] guidance.', 'Ghurar al-Hikam, Astuteness- §2', 'wisdom'),
  ('اَلفَقْدُ أحْزانٌ.', 'Loss is [a cause of] sorrows.', 'Ghurar al-Hikam, Loss- §1', 'wisdom'),
  ('اَلفَقْرُ صَلاحُ المُؤمِنِ، ومُريحُهُ مِنْ حَسَدِ الجيرانِ، وتَمَلُّقِ الإخْوانِ،وَ تَسَلُّطِ السُّلْطانِ.', 'Poverty is beneficial for the believer, and gives him comfort from the jealousy of the neighbours, the flattery of the brothers and the domination of the ruler.', 'Ghurar al-Hikam, Poverty- §1', 'wisdom'),
  ('إنَّ الفَقْرَ مِذَلَّةٌ لِلنَّفْسِ، مِدْهَشَةٌ لِلْعَقْلِ، جالِبٌ لِلْهُمُومِ.', 'Verily poverty is disgracer for the soul, a confounder of the intellect, and a bringer of sorrows.', 'Ghurar al-Hikam, Poverty- §2', 'wisdom'),
  ('اَلفَقْرُ يُنسي.', 'Poverty causes forgetfulness.', 'Ghurar al-Hikam, Poverty- §3', 'wisdom'),
  ('اَلفَقْرُ زينَةُ الإيمانِ.', 'Poverty is the adornment of faith.', 'Ghurar al-Hikam, Poverty- §4', 'wisdom'),
  ('اَلقَبْرُ خَيْرٌ مِنَ الفَقْرِ.', 'The grave is better than poverty.', 'Ghurar al-Hikam, Poverty- §5', 'wisdom'),
  ('اَلفَقْرُ مَعَ الدَّيْنِ اَلْمَوْتُ الأحْمَرُ.', 'Poverty with debt is [like] a red death.', 'Ghurar al-Hikam, Poverty- §6', 'wisdom'),
  ('اَلفَقْرُ يُخْرِسُ الفَطِنَ عَنْ حُجَّتِهِ.', 'Poverty disables the astute one from [presenting] his argument.', 'Ghurar al-Hikam, Poverty- §7', 'wisdom'),
  ('اَلفَقْرُ فِي الوَطَنِ غُرْبَةٌ.', 'Poverty in one’s homeland is like being a stranger in it.', 'Ghurar al-Hikam, Poverty- §8', 'wisdom'),
  ('اَلفَقْرُ الفادِحُ أجْمَلُ مِنَ الغِنَى الفاضِحِ.', 'Extreme poverty is better than disgraceful affluence.', 'Ghurar al-Hikam, Poverty- §9', 'wisdom'),
  ('اَلفَقْرُ والغِنى بَعْدَ العَرْضِ عَلَى اللّهِ سُبْحانَهُ.', 'True poverty and wealth are [determined] after presenting [the account of] one’s deeds before Allah, the Glorified.', 'Ghurar al-Hikam, Poverty- §10', 'wisdom'),
  ('اَلْفَقيرُ الرّاضي ناج مِنْ حَبائِلِ إبْلِيسَ، والغَنِيُّ واقِعٌ في حَبائِلِهِ.', 'The pauper who is satisfied is saved from the traps of Satan, whereas the rich person falls into his snares.', 'Ghurar al-Hikam, The pauper- §1', 'wisdom'),
  ('أمْقَتُ العِبادِ إلَى اللّهِ اَلْفَقيرُ المَزْهُوُّ، والشَّيْخُ الزّانِ، والعالِمُ الفاجِرُ.', 'The most hated of servants in the sight of Allah are: the pauper who is haughty, the elderly fornicator and the immoral scholar.', 'Ghurar al-Hikam, The pauper- §2', 'wisdom'),
  ('أكْثَرُ النّاسِ حُمْقاً الفَقيرُ المُتَكَبِّرُ.', 'The most foolish of people is the arrogant pauper.', 'Ghurar al-Hikam, The pauper- §3', 'wisdom'),
  ('أغْنَى النّاسِ فِي الآخِرَةِ أفْقَرُهُمْ فِي ا لدُّنيا.', 'The richest people in the Hereafter are the poorest of them in this world.', 'Ghurar al-Hikam, The pauper- §4', 'wisdom'),
  ('اَلفَقيرُ فِي الوَطِنِ غُرْبَةٌ(مُمْتَهَنٌ).', 'The poor person is [like] a stranger (or is scorned) in his hometown.', 'Ghurar al-Hikam, The pauper- §5', 'wisdom'),
  ('اَلمُقِلُّ غَريبٌ في بَلْدَتِهِ.', 'The needy person is a stranger in his own homeland.', 'Ghurar al-Hikam, The pauper- §6', 'wisdom'),
  ('جالِسِ الفُقَراءَ تَزْدَدْ شُكْراً.', 'One who sits in the company of the poor increases in [his] gratitude.', 'Ghurar al-Hikam, The pauper- §7', 'wisdom'),
  ('رُبَّ فَقير أغْنى مِنْ كُلِّ غَنِىّ.', 'Many a poor person is wealthier than all the rich people.', 'Ghurar al-Hikam, The pauper- §8', 'wisdom'),
  ('غِنَى الفَقيرِ قَناعَتُهُ.', 'The wealth of a poor person is his contentment.', 'Ghurar al-Hikam, The pauper- §9', 'wisdom'),
  ('كَمْ مِنْ فَقِير يُفْتَقَرُ إلَيْهِ.', 'How many a poor person is needed by someone else.', 'Ghurar al-Hikam, The pauper- §10', 'wisdom'),
  ('اَلفَقِيهُ كُلُّ الفَقيهِ مَنْ لَمْ يُقَنِّطِ النّاسَ مِنْ رَحْمَةِ اللّهِ ولَمْ يُؤْيِسْهُمْ مِنْ رَوْحِ اللّهِ.', 'The true scholar is one who neither makes people lose hope in the mercy of Allah nor cause them to despair of the comfort of Allah.', 'Ghurar al-Hikam, The Learned Scholars- §1', 'wisdom'),
  ('آفَةُ الفُقَهاءِ عَدَمُ الصِّيانَةِ.', 'The bane of scholars is not safeguarding themselves [from error].', 'Ghurar al-Hikam, The Learned Scholars- §2', 'wisdom'),
  ('إذا تَفَقَّهَ الرَّفيعُ تَواضَعَ.', 'When the elevated one becomes learned, he shows humility.', 'Ghurar al-Hikam, The Learned Scholars- §3', 'wisdom'),
  ('إذا تَفَقَّهَ الوَضيعُ تَرَفَّعَ.', 'When the vile one becomes a scholar, he considers himself to be above [others].', 'Ghurar al-Hikam, The Learned Scholars- §4', 'wisdom'),
  ('إذا فَقِهْتَ فَتَفَقَّهْ في دينِ اللّهِ.', 'When you [wish to] learn, then become learned in the religion of Allah.', 'Ghurar al-Hikam, The Learned Scholars- §5', 'wisdom'),
  ('أفْكِرْ تَسْتَبْصِرْ.', 'Think and you will perceive.', 'Ghurar al-Hikam, Thinking and the thinker- §1', 'wisdom'),
  ('أصْلُ العَقْلِ الفِكْرُ، وثَمَرَتُهُ السَّلامَةُ.', 'The root of wisdom is reflection, and its fruit is wellbeing.', 'Ghurar al-Hikam, Thinking and the thinker- §2', 'wisdom'),
  ('أصْلُ السَّلامَةِ مِنَ الزَّلَلِ، اَلفِكْرُ قَبْلَ الفِعْلِ، والرَّوِيَّةُ قَبْلَ الكَلامِ.', 'The root of safety from error is thinking before acting, and reflecting before speaking.', 'Ghurar al-Hikam, Thinking and the thinker- §3', 'wisdom'),
  ('إنَّ النّاظِرَ بِالقَلْبِ، اَلعامِلَ بِالبَصَرِ، يَكُونُ مُبْتَدَأُ عَمَلِهِ أنْ يَنْظُرَ عَمَلَهُ، عَلَيْهِ، أمْ لَهُ، فَإنْ كانَ لَهُ، مَضى فيهِ وإنْ كانَ عَلَيْهِ، وَقَفَ عَنْهُ.', 'Verily the one who observes with his heart and acts with foresight begins his action by first looking at [the consequence of] his action, is it his favour or against him; if it is in his favour then he goes ahead with it and if it is against him then he holds back from [doing] it.', 'Ghurar al-Hikam, Thinking and the thinker- §4', 'wisdom'),
  ('اَلفِكْرُ يَهْدي، اَلصِّدْقُ يُنْجي.', 'Thinking guides, truth saves.', 'Ghurar al-Hikam, Thinking and the thinker- §5', 'wisdom'),
  ('اَلفِكْرُ عِبادَةٌ.', 'Contemplation is worship.', 'Ghurar al-Hikam, Thinking and the thinker- §6', 'wisdom'),
  ('اَلفِكْرُ يُنيرُ اللُبَّ.', 'Contemplation illuminates the mind.', 'Ghurar al-Hikam, Thinking and the thinker- §8', 'wisdom'),
  ('اَلحِيلَةُ فائِدَةُ الفِكْرِ.', 'The benefit of thinking is finding solutions.', 'Ghurar al-Hikam, Thinking and the thinker- §9', 'wisdom'),
  ('اَلفِكْرُ يَهْدي إلَى الرَّشادِ.', 'Thinking guides [one] towards the way of right guidance.', 'Ghurar al-Hikam, Thinking and the thinker- §10', 'wisdom'),
  ('اَلفِكْرُ نُزْهَةُ المُتَّقينَ.', 'Thinking is the recreation of the God-fearing.', 'Ghurar al-Hikam, Thinking and the thinker- §11', 'wisdom'),
  ('لايُفْلِحُ مَنْ يَسُرُّهُ ما يُضِرُّهُ.', 'One who is pleased by that which harms him will not be successful.', 'Ghurar al-Hikam, Sucessfulness- §1', 'wisdom'),
  ('المُفْلِحُ مَنْ نَهَضَ بِجَناح، أوِ اسْتَسْلَمَ فَاسْتَراحَ.', 'The successful one is he who [either] spreads his wings 1 or remains peaceful and enjoys ease.', 'Ghurar al-Hikam, Sucessfulness- §2', 'wisdom'),
  ('مَنْ فَوَّضَ أمْرَهُ إلَى اللّهِ سَدَّدَهُ.', 'Whoever leaves his matter to Allah, He resolves it (for him).', 'Ghurar al-Hikam, Leaving the matter to Allah- §1', 'wisdom'),
  ('اَلْفَهْمُ بِالفِطْنَةِ.', 'Understanding is [achieved] though intelligence.', 'Ghurar al-Hikam, Understanding- §1', 'wisdom'),
  ('اَلفَهْمُ آيَةُ العِلْمِ.', 'Understanding is a sign of knowledge.', 'Ghurar al-Hikam, Understanding- §2', 'wisdom'),
  ('مَنْ تَفَهَّمَ فَهِمَ.', 'One who tries to understand, understands.', 'Ghurar al-Hikam, Understanding- §3', 'wisdom'),
  ('مَنْ تَفَهَّمَ اِزْدادَ.', 'One who tries to understand increases [his understanding].', 'Ghurar al-Hikam, Understanding- §4', 'wisdom'),
  ('مَنْ فَهِمَ عَلِمَ غَوْرَ العِلْمِ.', 'One who understands learns the depth of knowledge.', 'Ghurar al-Hikam, Understanding- §5', 'wisdom'),
  ('مَنْ عَدِمَ الفَهْمَ عَنِ اللّهِ سُبْحانَهُ لَمْ يَنْـتَفِعْ بِمَوْعِظَةِ واعِظ.', 'One who is not granted understanding by Allah, the Glorified, does not benefit from the advice of any adviser.', 'Ghurar al-Hikam, Understanding- §6', 'wisdom'),
  ('مَاافْتَقَرَ مَنْ مَلَكَ فَهْماً.', 'One who possesses understanding does not become needy.', 'Ghurar al-Hikam, Understanding- §7', 'wisdom'),
  ('جاوِرِ(جاوِزِ) القُبُورَ تَعْتَبِرْ.', 'Stay near (or pass by) the graves and you will learn a lesson.', 'Ghurar al-Hikam, Graves- §1', 'wisdom'),
  ('نِعْمَ الصِّهْرُ القَبْرُ.', 'How excellent a son-in-law the grave is!', 'Ghurar al-Hikam, Graves- §2', 'wisdom'),
  ('مَنِ اسْتَقْبَلَ الأُمُورَ أبْصَرَ.', 'One who faces [and anticipates] issues [with thought and reflection], perceives.', 'Ghurar al-Hikam, Facing issues- §1', 'wisdom'),
  ('إنَّكُمْ إنْ أقْبَلْتُمْ عَلَى اللّهِ أقْبَلْتُمْ، وإنْ أدْبَرْتُمْ عَنْهُ أدْبَرْتُمْ.', 'Verily if you turn towards Allah you have progressed, and if you turn away from Him, you have regressed.', 'Ghurar al-Hikam, Turning towards Allah- §1', 'wisdom'),
  ('بِالإقْبالِ تُطْرَدُ النُّحُوسُ.', 'By turning towards [Allah] misfortunes are warded off.', 'Ghurar al-Hikam, Turning towards Allah- §2', 'wisdom'),
  ('حُسْنُ الاِخْتيارِ، واِصْطِناعُ الأحْرارِ، وفَضْلُ الاِسْتِظْهارِ، مِنْ دَلائِلِ الإقْبالِ.', 'Making a good choice, doing good to the freemen and taking adequate precaution [or support] are from the signs of turning [to Allah].', 'Ghurar al-Hikam, Turning towards Allah- §3', 'wisdom'),
  ('لِكُلِّ إقْبال إدْبارٌ.', 'For every advance [and progress] there is a retreat [and a regress].', 'Ghurar al-Hikam, Turning towards Allah- §4', 'wisdom'),
  ('مِنْ عَلاماتِ الإقْبالِ اِصْطِناعُ الرِّجالِ.', 'One of the signs of turning [towards Allah] is doing good to the people.', 'Ghurar al-Hikam, Turning towards Allah- §5', 'wisdom'),
  ('مِنْ عَلاماتِ الإقْبالِ: سَدادُ الأقْوالِ، والرِّفْقُ فِي الأفْعالِ.', 'From the signs of turning [to Allah] are: correctness of speech and kindness in actions.', 'Ghurar al-Hikam, Turning towards Allah- §6', 'wisdom'),
  ('إنَّ أكْرَمَ المَوتِ القَتْلُ، والَّذي نَفْسي بِيَدِهِ لألْفُ ضَرْبَة بِالسَّيْفِ أهْوَنُ (عَلَيَّ) مِنْ ميتَة عَلَى الفِراشِ.', 'Verily the most honourable of deaths is martyrdom. By He in whose hand my soul is, one thousand strikes with the sword are indeed easier [for me] than dying on the bed.', 'Ghurar al-Hikam, Martyrdom in the way of Allah- §1', 'wisdom'),
  ('مَنِ اقْتَحَمَ اللُّجَجَ غَرِقَ.', 'One who plunges into the depths of the sea, drowns.', 'Ghurar al-Hikam, Plunging in- §1', 'wisdom'),
  ('اَلتَّسَلُّطُ عَلَى الضَّعيفِ والمَمْلُوكِ مِنْ لُزُومِ (لُؤْمِ) القُدْرَةِ.', 'Dominating the weak and the slave are from the exigencies (or wickedness) of power.', 'Ghurar al-Hikam, Power and might- §1', 'wisdom'),
  ('اَلْقُدْرَةُ تُظْهِرُ مَحْمُودَ الخِصالِ ومَذْمُومَها.', 'Power manifests the praiseworthy and blameworthy qualities [of an individual].', 'Ghurar al-Hikam, Power and might- §2', 'wisdom'),
  ('آفَةُ القُدْرَةِ مَنْعُ الإحْسانِ.', 'The bane of power is withholding favour.', 'Ghurar al-Hikam, Power and might- §3', 'wisdom'),
  ('آفَةُ الاِقْتِدارِ اَلبَغْيُ والعُتُوُّ.', 'The bane of might is aggression and defiance.', 'Ghurar al-Hikam, Power and might- §4', 'wisdom'),
  ('اَلْقُدْرَةُ تُنْسِى الحَفيظَةَ.', 'Power makes one forget [about] self-preservation.', 'Ghurar al-Hikam, Power and might- §5', 'wisdom'),
  ('إذا كَثُرَتِ القُدْرَةُ قَلَّتِ الشَّهْوَةُ.', 'When power increases, desire decreases.', 'Ghurar al-Hikam, Power and might- §6', 'wisdom'),
  ('إذا قَلَّتِ المَقْدُرَةُ كَثُرَ التَّعَلُّلُ بِالمَعاذِيرِ.', 'When [one’s] capability is reduced, the offering of excuses increases.', 'Ghurar al-Hikam, Power and might- §7', 'wisdom'),
  ('زَكاةُ القُدْرَةِ الإنْصافُ.', 'The alms-tax of power is even-handedness.', 'Ghurar al-Hikam, Power and might- §8', 'wisdom'),
  ('مِنْ أحْسَنِ أفْعالِ القادِرِ أنْ يَغْضِبَ فَيَحْلُمَ.', 'One of the best actions of the powerful person is for him to show forbearance when he is angry.', 'Ghurar al-Hikam, Power and might- §9', 'wisdom'),
  ('مَنْ جَهِلَ قَدْرَهُ عَدا طَوْرَهُ.', 'One who does not know his worth, transgresses his limits.', 'Ghurar al-Hikam, Status and worth- §1', 'wisdom'),
  ('مَنْ تَعَدّى حَدَّهُ أهانَهُ النّاسُ.', 'One who oversteps his limits is humiliated by the people.', 'Ghurar al-Hikam, Status and worth- §3', 'wisdom'),
  ('مَنْ جَهِلَ مَوْضِعَ قَدَمِهِ عَثُرَ بِدَواعِي نَدَمِهِ.', 'One who is ignorant about the place where he steps is made to stumble by the reasons of his regret.', 'Ghurar al-Hikam, Status and worth- §4', 'wisdom'),
  ('مَنِ اقْتَصَرَ عَلى قَدْرِهِ كانَ أبْقى لَهُ.', 'One who limits himself to his [rightful] status, it will be more lasting for him.', 'Ghurar al-Hikam, Status and worth- §5', 'wisdom'),
  ('مَنْ جَهِلَ قَدْرَهُ جَهِلَ كُلَّ قَدْر.', 'One who is ignorant of his own worth does not know anyone’s worth.', 'Ghurar al-Hikam, Status and worth- §6', 'wisdom'),
  ('مَنْ عَرَفَ قَدْرَهُ لَمْ يُضَعْ بَيْنَ النّاسِ.', 'One who knows his worth is not disparaged among the people.', 'Ghurar al-Hikam, Status and worth- §7', 'wisdom'),
  ('ما هَلَكَ مَنْ عَرَفَ قَدْرَهُ.', 'He who knows his worth does not get ruined.', 'Ghurar al-Hikam, Status and worth- §8', 'wisdom'),
  ('ما عَقَلَ مَنْ عَدا طَوْرَهُ.', 'He who oversteps his limits has not used his intellect.', 'Ghurar al-Hikam, Status and worth- §9', 'wisdom'),
  ('نِعِمّا لِلْعَبْدِ أنْ يَعْرِفَ قَدْرَهُ، ولايَتَجاوَزَ حَدَّهُ.', 'How good it is for a servant to know his status and not to overstep his limits!', 'Ghurar al-Hikam, Status and worth- §10', 'wisdom'),
  ('هَلَكَ مَنْ لَمْ يَعْرِفْ قَدْرَهُ.', 'Ruined is the one who does not know his status.', 'Ghurar al-Hikam, Status and worth- §11', 'wisdom'),
  ('لاتُقْدِمْ عَلى ما تَخْشَى العَجْزَ عَنْهُ.', 'Do not undertake that which you are afraid of being incapable of.', 'Ghurar al-Hikam, Undertaking- §1', 'wisdom'),
  ('لاتُغْلِقْ باباً يُعْجِزُكَ اِفْتِتاحُهُ.', 'Do not close a door which you are unable to open.', 'Ghurar al-Hikam, Undertaking- §2', 'wisdom'),
  ('إذا عَلَوْتَ فَلا تُفَكِّرْ فيمَنْ دُونَكَ مِنَ الجُهّالِ، ولكِنِ اقْتَدِ بِمَنْ فَوْقَكَ مِنَ العُلَماءِ.', 'When you are high, do not think of the one who is below you from the ignorant ones, rather follow [the example of] those who are above you from among the scholars.', 'Ghurar al-Hikam, To follow- §1', 'wisdom'),
  ('إذا أنْكَرْتَ مِنْ عَقْلِكَ شَيْئاً فَاقْتَدِ بِرَأْيِ عاقِل يُزيلُ ما أنْكَرْتَهُ.', 'When you are unable to understand something with your intellect then follow the opinion of the intelligent one and he will remove your ignorance about it.', 'Ghurar al-Hikam, To follow- §2', 'wisdom'),
  ('اَلْقُرْآنُ أفْضَلُ الهِدايَتَيْنِ.', 'The Qur’an is the better of the two forms of guidance.', 'Ghurar al-Hikam, The Quran- §1', 'wisdom'),
  ('أحْسِنُوا تِلاوَةَ القُرْآنِ فَإنَّهُ أنْفَعُ (أحْسَنُ) القَصَصِ، واسْتَشْفُوا بِهِ فَإنَّهُ شِفاءُ الصُّدُورِ.', 'Excel in your recitation of the Qur’an, for it is indeed the most beneficial (or the best) of stories, and seek cure from it, for it is the cure for [what is in] the breasts.', 'Ghurar al-Hikam, The Quran- §2', 'wisdom'),
  ('اِتَّبِعُوا النٌّورَ الَّذي لايُطْفَأُ، والوَجْهَ الَّذي لايَبْلى، واسْتَسْلِمُوْا، وسَلِّمُوا لأمْرِهِ، فَإنَّكُمْ لَنْ تَضِلُّوا مَعَ التَّسليمِ.', 'Follow the light that is not put out and the face that does not become old, and surrender and submit to its command, for indeed you will not go astray with submission [to it].', 'Ghurar al-Hikam, The Quran- §3', 'wisdom'),
  ('أفْضَلُ الذِّكْرِ القُرْآنُ، بِهِ تُشْرَحُ الصُّدُورُ وتَسْتَنيرُ السَّرائِرُ.', 'The best reminder is the Qur’an, through it the breasts are expanded and the souls are illuminated.', 'Ghurar al-Hikam, The Quran- §4', 'wisdom'),
  ('إنَّ القُرْآنَ ظاهِرُهُ أنيقٌ، وباطِنُهُ عَمِيقٌ، لاتَفْنى عَجائِبُهُ، ولاتَنْقَضي غَرائِبُهُ، ولا تُكْشَفُ الظُّلُماتُ إلاّ بِهِ.', 'Verily the outer aspect of the Qur’an is elegant and its inner aspect is profound [in meaning]; its marvels do not end, its wonders do not cease, and the darkness [of ignorance and misguidance] is not removed except through it.', 'Ghurar al-Hikam, The Quran- §5', 'wisdom'),
  ('إنَّ هذا القُرْآنَ هُوَ النّاصِحُ الَّذي لايَغُشُّ، والهادِي الَّذي لايُضِلُّ، وَالمُحَدِّثُ الَّذي لايَكْذِبُ.', 'Verily this Qur’an is the adviser that does not deceive, the guide that does not lead astray and the speaker that does not lie.', 'Ghurar al-Hikam, The Quran- §6', 'wisdom'),
  ('تَدَبَّرُوا آياتِ القُرْآنِ واعْتَبِرُوا بِهِ فَإنَّهُ أبْلَغُ العِبَرِ.', 'Reflect upon the verses of the Qur’an and learn lessons from it, for indeed it is the best imparter of lessons.', 'Ghurar al-Hikam, The Quran- §7', 'wisdom'),
  ('تَعَلَّمُوا القُرْآنَ فَإنَّهُ رَبيعُ القُلُوبِ، واسْتَشْفُوا بِنُورِهِ فَإنَّهُ شِفاءُ الصُّدُورِ.', 'Learn the Qur’an, for it is indeed the spring of the hearts and seek a cure from its light, for verily it is the cure of the hearts.', 'Ghurar al-Hikam, The Quran- §8', 'wisdom'),
  ('تَمَسَّكْ بِحَبْلِ القُرْآنِ وانْتَصِحْهُ، وحَلِّلْ حَلالَهُ، وحَرِّمْ حَرامَهُ، وَاعْمَلْ بِعَزائِمِهِ وأحْكامِهِ.', 'Hold fast to the rope of the Qur’an and take counsel from it, consider as permissible what it permits and forbidden what it forbids, and act on its injunctions and rulings.', 'Ghurar al-Hikam, The Quran- §9', 'wisdom'),
  ('جَمالُ القُرآنِ البَقَرَةُ وآلُ عِمْرانَ.', 'The charm of the Qur’an are [in the surahs] al-Baqarah and Aāl ‘Imrān .', 'Ghurar al-Hikam, The Quran- §10', 'wisdom'),
  ('قَدْ يَبْعُدُ القريب.', 'The near one may [at times] become distanced.', 'Ghurar al-Hikam, The near one- §1', 'wisdom'),
  ('التَّقَرُّبُ إلَى اللّهِ تَعالى بِمَسْئَلَتِهِ، وإلَى النّاسِ بِتَرْكِها.', 'Attaining nearness to Allah is [achieved] by asking [from] Him and [gaining closeness] to the people is [achieved] by refraining from asking [them for anything].', 'Ghurar al-Hikam, Attaining nearness to Allah- §1', 'wisdom'),
  ('اِجْعَلْ شَكْواكَ إلى مَنْ يَقْدِرُ عَلى غِناكَ.', 'Address your complaints to one who is capable of sufficing you.', 'Ghurar al-Hikam, Attaining nearness to Allah- §2', 'wisdom'),
  ('تَقَرَّبْ إلََى اللّهِ سُبْحانَهُ فَإنَّهُ يُزْلِفُ المُتَقَرِّبينَ إلَيْهِ.', 'Seek nearness to Allah, the Glorified, for verily He brings closer those who seek nearness to Him.', 'Ghurar al-Hikam, Attaining nearness to Allah- §3', 'wisdom'),
  ('تَقَرَّبْ إلَى اللّهِ سُبْحانَهُ بِالسُّجُودِ والرُّكُوعِ والخُضُوعِ لِعَظَمَتِهِ والخُشُوعِ(الخُنُوعِ).', 'Seek nearness to Allah, the Glorified, through prostration ( sujūd ), bowing ( rukū’ ), submission to His majesty and reverence (or subservience).', 'Ghurar al-Hikam, Attaining nearness to Allah- §4', 'wisdom'),
  ('لا يُقَرِّبُ مِنَ اللّهِ سُبْحانَهُ إلاّ كَثْرَةُ السُّجُودِ والرُّكُوعِ', 'Nothing brings one closer to Allah, the Glorified, except copious prostration ( sujūd ) and bowing ( rukū’ ).', 'Ghurar al-Hikam, Attaining nearness to Allah- §5', 'wisdom'),
  ('ما أخْلَقَ مَنْ عَرَفَ رَبَّهُ أنْ يَعْتَرِفَ بِذَنْبِهِ.', 'How appropriate it is for one who knows his Lord to admit his sins.', 'Ghurar al-Hikam, Admission and confession of one’s sins- §1', 'forgiveness'),
  ('نِعْمَ شافِعُ المُذْنِبِ الإقْرارُ.', 'The best intercessor for a sinner is [his] admission [of guilt].', 'Ghurar al-Hikam, Admission and confession of one’s sins- §2', 'forgiveness'),
  ('لاَاعْتِذارَ أمْحى لِلذَّنْبِ مِنَ الإقرار ِ.', 'There is no apology that wipes out sins more than admission [of one’s guilt].', 'Ghurar al-Hikam, Admission and confession of one’s sins- §3', 'forgiveness'),
  ('يُسْتَثْمَرُ العَفْوُ بِالإقْرارِ أكْثَرَ مِمّا يُسْتَثْمَرُ بِالاِعْتِذارِ.', 'Pardon bears more fruit with admission [of one’s guilt] than it does with giving excuses.', 'Ghurar al-Hikam, Admission and confession of one’s sins- §4', 'forgiveness'),
  ('اَلاِعْتِرافُ شَفيعُ الجاني.', 'Confession is the intercessor of the wrongdoer.', 'Ghurar al-Hikam, Admission and confession of one’s sins- §5', 'forgiveness'),
  ('الإقْرارُ اِعْتِذارٌ.', 'Admission [of one’s guilt] is [a means of] seeking pardon.', 'Ghurar al-Hikam, Admission and confession of one’s sins- §6', 'forgiveness'),
  ('مَنْ أقْرَضَ اللّهَ جَزاهُ.', 'One who gives a loan to Allah is recompensed by Him.', 'Ghurar al-Hikam, Lending to Allah- §1', 'wisdom'),
  ('اِغْتَنِمْ مَنِ اسْتَقْرَضَكَ في حالِ غِناكَ لِيَجْعَلَ قَضاءَهُ (قَضاهُ) في يَوْمِ عُسْرَتِكَ.', 'Take benefit from the one who takes a loan from you in your time of prosperity so that you may take its repayment in your time of hardship.', 'Ghurar al-Hikam, Lending to Allah- §2', 'wisdom'),
  ('مَنِ اسْتَدامَ قَرْعَ البابِ ولَجَّ ولَجَ.', 'One who continues knocking the door insistently [eventually] enters through it.', 'Ghurar al-Hikam, Knockng the door- §1', 'wisdom'),
  ('أوْفَرُ القِسْمِ صِحَّةُ الجِسْمِ.', 'The most bountiful share is good health.', 'Ghurar al-Hikam, The [allotted] Share- §1', 'wisdom'),
  ('أهْنَأُ الأقْسامِ اَلقَناعَةُ، وصِحَّةُ الأجْسامِ.', 'The most pleasant share is contentment and good health.', 'Ghurar al-Hikam, The [allotted] Share- §2', 'wisdom'),
  ('أغْنَى النّاسِ اَلرّاضي بِقِسْمِ اللّهِ.', 'The wealthiest of people is one who is pleased with what Allah has allotted to him.', 'Ghurar al-Hikam, The [allotted] Share- §3', 'wisdom'),
  ('بِتَقْديرِ أقْسامِ اللّهِ لِلْعِبادِ قامَ وَزْنُ العالَمِ، وتَمَّتْ هذِهِ الدُّنْيا لاِهْلِها.', 'By the measured apportionment of Allah for the servants, the balance of this world has been established and this world has been made complete for its inhabitants.', 'Ghurar al-Hikam, The [allotted] Share- §4', 'wisdom'),
  ('مَنْ وَثِقَ بِقِسْمِ اللّهِ لَمْ يَتَّهِمْهُ فِي الرِّزْقِ.', 'One who trusts in the allotment of Allah does not blame Him with regards to sustenance.', 'Ghurar al-Hikam, The [allotted] Share- §5', 'wisdom'),
  ('لاتَحْمِلْ عَلى يَوْمِكَ هَمَّ سَنَتِكَ كَفاكَ كُلَّ يَـوْم ما قُدِّرَ لَكَ فيهِ، فَإنْ تَكُنِ السَّنَةُ مِنْ عُمْرِكَ فَإنَّ اللّهَ سُبْحانَهُ سَيَأْتيكَ في كُلِّ غَد جَديد بِما قَسَمَ لَكَ وَإنْ لَمْ تَكُنْ مِنْ عُمْرِكَ فَما هَمُّكَ بِما لَيْسَ لَكَ.', 'Do not put the worry of your [entire] year on your day. That which is apportioned for you each day suffices for you in it. Then if you are to live another year, verily Allah, the Glorified, will bring to you what He has apportioned for you in each new day and if you will not live that long then why are you worried about that which is not for you?', 'Ghurar al-Hikam, The [allotted] Share- §6', 'wisdom'),
  ('ضادُّوا القَسْوَةَ بِالرِّقَّةِ.', 'Counter hard-heartedness with gentleness.', 'Ghurar al-Hikam, Hard-heartedness- §1', 'wisdom'),
  ('مِنْ أعْظـَمِ الشَّقاوَةِ القَساوَةُ.', 'Hard-heartedness is from the greatest wretchedness.', 'Ghurar al-Hikam, Hard-heartedness- §2', 'wisdom'),
  ('لا لُؤْمَ أشَدُّ مِنَ القَسْوَةِ.', 'There is no wickedness more ruthless than hard-heartedness.', 'Ghurar al-Hikam, Hard-heartedness- §3', 'wisdom'),
  ('ضاعَ مَنْ كانَ لَهُ مَقْصَدٌ غَيْرُ اللّهِ.', 'Lost is the one who has a goal other than Allah.', 'Ghurar al-Hikam, Goals- §1', 'wisdom'),
  ('مَنْ ساءَ مَقْصَدُهُ ساءَ مَوْرِدُهُ.', 'One whose goal is evil, his place of arrival [in the Hereafter] will be bad.', 'Ghurar al-Hikam, Goals- §2', 'wisdom'),
  ('اَلاِقْتِصادُ يُنْمِى القَليلَ.', 'Moderation makes [that which is] little grow [and increase].', 'Ghurar al-Hikam, Moderation- §1', 'wisdom'),
  ('اَلاِقْتِصادُ يُنْمِى اليَسيرَ.', 'Moderation makes the small grow [big].', 'Ghurar al-Hikam, Moderation- §2', 'wisdom'),
  ('اَلاِقْتِصادُ نِصْفُ المَؤُنَةِ.', 'Moderation [in one’s expenses] is half of livelihood.', 'Ghurar al-Hikam, Moderation- §3', 'wisdom'),
  ('آفَةُ الاِقْتِصادِ البُخْلُ.', 'The bane of moderation is stinginess.', 'Ghurar al-Hikam, Moderation- §4', 'wisdom'),
  ('خُذِ القَصْدَ فِي الأُمُورِ، فَمَنْ أخَذَ القَصْدَ خَفَّتْ عَلَيْهِ المُؤَنُ.', 'Be moderate in [your] affairs, for whoever is moderate, the burden of his expenses is lightened.', 'Ghurar al-Hikam, Moderation- §5', 'wisdom'),
  ('طَريقَتُنا اَلقَصْدُ، وَسُنَّتُنا اَلرُّشْدُ.', 'Our way is moderation and our practice is right guidance.', 'Ghurar al-Hikam, Moderation- §6', 'wisdom'),
  ('عَلَيْكَ بِالقَصْده فِي الأُمُورِ فَمَنْ عَدَلع عَنِ القَصْدِ جارَ، ومَنْ أخَذَ بِهِ عَدَلَ.', 'You must be moderate in your affairs, for the one who deviates from moderation is unjust and one who takes to it is just.', 'Ghurar al-Hikam, Moderation- §7', 'wisdom'),
  ('عَلَيْكَ بالقَصْدِ فَإنَّهُ أعْوَنُ شَيْء عَلى حُسْنِ العَيْشِ، ولَنْ يَهْلِكَ امْرُؤٌ حَتّى يُؤْثِرَ شَهْوَتَهُ عَلى دينِهِ.', 'Espouse moderation, for indeed it is the most helpful thing in attaining a fruitful life; and a person will never be destroyed until he prefers his lust over his faith.', 'Ghurar al-Hikam, Moderation- §8', 'wisdom'),
  ('عَلَيْكُمْ بِالقَصْدِ فِي المَطاعِمِ فَإنَّهُ أبْعَدُ مِنَ السَّرَفِ، وأصَحُّ لِلْبَدَنِ، وأعْوَنُ عَلَى العِبادَةِ.', 'Espouse moderation in food, for indeed it is farther from extravagance, healthier for the body and more assisting in the performance of worship.', 'Ghurar al-Hikam, Moderation- §9', 'wisdom'),
  ('غايَةُ الاِقْتِصادِ القَناعَةُ.', 'The height of moderation is contentment.', 'Ghurar al-Hikam, Moderation- §10', 'wisdom'),
  ('لِسانُ المُقَصِّرِ قَصيرٌ.', 'The tongue of the neglectful is short.', 'Ghurar al-Hikam, One who is neglectful and falls short- §1', 'wisdom'),
  ('مَنْ قَصَّرَ عابَ.', 'One who falls short is deficient.', 'Ghurar al-Hikam, One who is neglectful and falls short- §2', 'wisdom'),
  ('مَنْ قَصَّرَ في أيّامِ أمَلِهِ قَبْلَ حُضُورِ أجَلِهِ فَقَدْ خَسِرَ عُمْرَهُ، وضَرَّهُ أجَلُهُ.', 'One who is neglectful in his days of hope, before his death comes, has indeed made a loss in his life and is harmed by his death.', 'Ghurar al-Hikam, One who is neglectful and falls short- §3', 'wisdom'),
  ('اَلسَيْفُ فاتِقٌ، والدّينُ راتِقٌ، فَالدّينُ يَأمُرُ بِالمَعْرُوفِ، والسَّيْفُ يَنْهى عَنِ المُنْكَرِ، قالَ اللّهُ تَعالى: ﴿ولَكُمْ فِي القِصاصِ حَيوةٌ﴾.', 'The sword rents asunder and the religion joins together; for religion commands good and the sword forbids evil. Allah, the Exalted, says: Indeed in retaliation there is life for you.', 'Ghurar al-Hikam, Retaliation- §1', 'wisdom'),
  ('أشَدُّ النّاسِ عَذاباً يَوْمَ القِيامَةِ المُتَسَخِّطُ لِقَضاءِ اللّهِ.', 'The most severely chastised of all people on the Day of Judgment will be the one who resents the decree of Allah.', 'Ghurar al-Hikam, Divine decree and destiny- §1', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ يُجْرِى الأُمُورَ عَلى ما يَقْضيهِ لا عَلى ما تَرْتَضيهِ.', 'Verily Allah, the Glorified, manages affairs in accordance with what He decrees, not according to what pleases you.', 'Ghurar al-Hikam, Divine decree and destiny- §2', 'wisdom'),
  ('اَلمَقادِيرُ تَجْري بِخِلافِ التَّقْديرِ والتَّدْبيرِ.', 'Divine decree works contrary to the estimations and planning [of the people].', 'Ghurar al-Hikam, Divine decree and destiny- §4', 'wisdom'),
  ('اَلقَدَرُ يَغْلِبُ الحاذِرَ.', 'Destiny overpowers the cautious.', 'Ghurar al-Hikam, Divine decree and destiny- §5', 'wisdom'),
  ('اَلاِتِّكالُ عَلَى القَضاءِ أرْوَحُ.', 'Reliance on [divine] decree is more comforting.', 'Ghurar al-Hikam, Divine decree and destiny- §6', 'wisdom'),
  ('اَلمَقاديرُ لاتُدْفَعُ بِالقُوَّةِ والمُغالَبَةِ.', 'Devine decree cannot be repelled by strength and struggle.', 'Ghurar al-Hikam, Divine decree and destiny- §7', 'wisdom'),
  ('آفَةُ المَجْدِ عَوائِقُ القَضاءِ.', 'The impediments of divine decree are the bane of eminence.', 'Ghurar al-Hikam, Divine decree and destiny- §8', 'wisdom'),
  ('إذا نَزَلَ القَدَرُ بَطَلَ الحَذَرُ.', 'When the destiny descends, caution becomes nullified.', 'Ghurar al-Hikam, Divine decree and destiny- §9', 'wisdom'),
  ('إذا حَلَّتِ المَقادِيرُ بَطَلَتِ التَّدابِيرُ.', 'When divine decree comes, the plans [of people] are nullified.', 'Ghurar al-Hikam, Divine decree and destiny- §10', 'wisdom'),
  ('إذا كانَ القَدَرُ لايُرَدُّ، فَالاِحْتِراسخ باطِلٌ.', 'When destiny cannot be repelled, then cautiousness is futile.', 'Ghurar al-Hikam, Divine decree and destiny- §11', 'wisdom'),
  ('أفْظَعُ (أقْطَعُ) شَيْء ظُلْمُ القُضاةِ.', 'The most abominable (or divisive) thing is the injustice of judges.', 'Ghurar al-Hikam, Judges- §1', 'wisdom'),
  ('آفَةُ القُضاةِ الطَّمَعُ.', 'The bane of judges is greed.', 'Ghurar al-Hikam, Judges- §2', 'wisdom'),
  ('شَرُّ القُضاةِ مَنْ جارَتْ أقْضِيَتُهُ.', 'The worst of judges is one whose judgments are oppressive.', 'Ghurar al-Hikam, Judges- §3', 'wisdom'),
  ('مَنْ جارَتْ أقْضِيَتُهُ، زالَتْ قُدْرَتُهُ.', 'One whose judgments are oppressive, his power comes to an end.', 'Ghurar al-Hikam, Judges- §5', 'wisdom'),
  ('مَنِ انْقَطَعَ إلى غَيْرِ اللّهِ شَقِيَ وتَعَنّى.', 'One who cuts himself off [from Allah and turns] towards other than Allah becomes wretched and faces hardship.', 'Ghurar al-Hikam, Being cut off from Allah- §1', 'wisdom'),
  ('رُبَّ قاعِد عَمّا يَسُرُّهُ.', 'Many a person sits back from that which would delight him.', 'Ghurar al-Hikam, Sitting back- §1', 'wisdom'),
  ('ما أعْظَمَ فَوْزَ مَنِ اقْتَفى أثَرَ النَّبيَّينَ.', 'How great is the success of the one who follows in the footsteps of the Prophets!', 'Ghurar al-Hikam, Emulation- §1', 'wisdom'),
  ('حَرامٌ عَلى كُلِّ قَلْب مُتَوَلِّه بِالدُّنْيا أنْ يَسْكُنَهُ التَّقْوى.', 'It is forbidden upon every heart which is inclined to this world that God-wariness should reside in it.', 'Ghurar al-Hikam, The heart- §1', 'wisdom'),
  ('حارِبُوا هذِهِ القُلُوبَ فَإنَّها سَريعَةُ العِثارِ (الدِّثار).', 'Wage war against these hearts [and their desires], for indeed they are quick to stumble (or get obliterated).', 'Ghurar al-Hikam, The heart- §2', 'wisdom'),
  ('حُزْنُ القُلُوبِ يُمَحِّصُ الذُّنُوبَ.', 'Sadness of the hearts purges the sins.', 'Ghurar al-Hikam, The heart- §3', 'wisdom'),
  ('خُلُوُّ القَلْبِ مِنَ التَّقْوى يَمْلأُهُ مِنْ فِتَنِ الدُّنيا.', 'When the heart is empty of God-wariness, it gets filled with the lures of this world.', 'Ghurar al-Hikam, The heart- §4', 'wisdom'),
  ('ذَلِّلْ قَلْبَكَ بِاليَقينِ، وقَرِّرْهُ بِالفَناءِ، وبَصِّرْهُ فَجايِـعَ الدُّنْيا.', 'Humble your heart with certitude, make it acknowledge the transience of this life, and make it see the calamities of this world.', 'Ghurar al-Hikam, The heart- §5', 'wisdom'),
  ('زينَةُ القُلُوبِ إخْلاصُ الإيمانِ.', 'The adornment of the hearts is sincerity of faith.', 'Ghurar al-Hikam, The heart- §6', 'wisdom'),
  ('شَرُّ القُلُوبِ الشّاكُّ في إيمانِهِ.', 'The worst of hearts is the one that doubts in its faith.', 'Ghurar al-Hikam, The heart- §7', 'wisdom'),
  ('طُوبى لِلْمُنْكَسِرَةِ قُلُوبُهُمْ مِنْ أجْلِ اللّهِ.', 'Blessed are those whose hearts are broken for the sake of Allah.', 'Ghurar al-Hikam, The heart- §8', 'wisdom'),
  ('طُوبى لِمَنْ شَغَلَ قَلْبَهُ بِالفِكْرِ، ولِسانَهُ بِالذِّكْرِ.', 'Blessed is the one who occupies his heart with reflection and his tongue with remembrance [of Allah].', 'Ghurar al-Hikam, The heart- §9', 'wisdom'),
  ('طُوبى لِمَنْ خَلا مِنَ الغِلِّ صَدْرُهُ وسَلِمَ مِنَ الغِشِّ قَلْبُهُ.', 'Blessed is the one whose chest is void of rancour and whose heart is safe from deception.', 'Ghurar al-Hikam, The heart- §10', 'wisdom'),
  ('قَليلٌ يَدُومُ خَيْرٌ مِنْ كَثير يَنْقَطِعُ.', 'Little that is continuous is better than a lot that is discontinuous.', 'Ghurar al-Hikam, Little- §1', 'wisdom'),
  ('اَلتَّقَلُّلُ ولا التَّذَلُّلْ.', 'Having less is all right, but being humiliated, never!', 'Ghurar al-Hikam, Little- §2', 'wisdom'),
  ('أقَلُّ شَيْء الصِّدْقُ والأمانَةُ.', 'he least of things [required for salvation] is truthfulness and trustworthiness.', 'Ghurar al-Hikam, The least- §1', 'wisdom'),
  ('مَنْ قَلَّ ذَلَّ.', 'One who is less [in generosity and affection] is abased.', 'Ghurar al-Hikam, Being less- §1', 'wisdom'),
  ('طُولُ القُنُوتِ والسُّجُودِ يُنْجي مِنْ عَذابِ النّارِ.', 'Prolonged qunūt and prostration saves one from the punishment of hellfire.', 'Ghurar al-Hikam, Qunut (Raising hands in supplication)- §1', 'forgiveness'),
  ('عَجِبْتُ لِمَنْ يَقْنَطُ ومَعَهُ النَّجاةُ وهُوَ الاِسْتِغْفارُ.', 'I am amazed at the one who loses hope while he has with him salvation in the form of repentance.', 'Ghurar al-Hikam, Despair- §1', 'wisdom'),
  ('قَتَلَ القُنُوطُ صاحِبَهُ.', 'Despair kills its owner.', 'Ghurar al-Hikam, Despair- §2', 'wisdom'),
  ('كُلُّ قانِط آئِسٌ.', 'Every despairing one has lost hope.', 'Ghurar al-Hikam, Despair- §3', 'wisdom'),
  ('اَلقانِعُ ناج مِنْ آفاتِ المَطامِعِ.', 'The contented one is saved from the woes of covetousness.', 'Ghurar al-Hikam, Contentment and the contented- §1', 'detachment'),
  ('اِقْنَعْ تَعُزُّ.', 'Be content and you will gain honour.', 'Ghurar al-Hikam, Contentment and the contented- §2', 'detachment'),
  ('اِقْنَعْ بِما أُوتِيتَهُ، تَكُنْ مَكْفِيّاً.', 'Be content with what you are given and you will be made sufficient.', 'Ghurar al-Hikam, Contentment and the contented- §3', 'detachment'),
  ('اِقْنَعُوا بِالقَليلِ مِنْ دُنْياكُمْ لِسَلامَةِ ديـنِكُمْ، فَإنَّ المُؤمِنَ اَلبُلْغَةُ اليَسيرَةُ مِنَ الدُّنْيا تُقْنِعُهُ.', 'Be content with little from your worldly possessions for the safety of your religion, for indeed the believer is satisfied with the little that he gets of this world.', 'Ghurar al-Hikam, Contentment and the contented- §4', 'detachment'),
  ('أغْنَى النّاسِ القانِعُ.', 'The wealthiest of all people is the contented one.', 'Ghurar al-Hikam, Contentment and the contented- §5', 'detachment'),
  ('اَلْعَبْدُ حُرٌّ ما قَنِعَ، الحُرُّ عَبْدٌ ما طَمِعَ.', 'A slave is free as long as he is content and a freeman is a slave as long as he covets.', 'Ghurar al-Hikam, Contentment and the contented- §6', 'detachment'),
  ('اَلقَناعَةُ عُنْوانُ(عَوْنُ) الفاقَةِ.', 'Contentment is the helper of poverty.', 'Ghurar al-Hikam, Contentment and the contented- §7', 'detachment'),
  ('اَلقَناعَةُ أبْقى عِزّ.', 'Contentment is the most lasting honour.', 'Ghurar al-Hikam, Contentment and the contented- §8', 'detachment'),
  ('اَلمُسْتَريحُ مِنَ النّاسِ اَلقانِعُ.', 'The most at ease among the people is the contented one.', 'Ghurar al-Hikam, Contentment and the contented- §9', 'detachment'),
  ('اَلقَناعَةُ عَلامَةُ الأتْقياءِ.', 'Contentment is the sign of the God-wary.', 'Ghurar al-Hikam, Contentment and the contented- §10', 'detachment'),
  ('اَلْقِنْيَةُ أحْزانٌ.', 'Acquisitions are [a cause of] sorrows.', 'Ghurar al-Hikam, Acquisitions- §1', 'wisdom'),
  ('اَلْقِنْيَةُ سَلِبٌ.', 'Acquisitions are deprivation [from peace of mind].', 'Ghurar al-Hikam, Acquisitions- §2', 'wisdom'),
  ('اَلْقِنْيَةُ (اَلفِتْنَةُ) تَجْلِبُ الحَزَنَ.', 'Acquisitions bring about sadness.', 'Ghurar al-Hikam, Acquisitions- §3', 'wisdom'),
  ('اَلْقِنْيَةُ يَنْبُوعُ الأحْزانِ.', 'Acquisitions are a spring of sorrows.', 'Ghurar al-Hikam, Acquisitions- §4', 'wisdom'),
  ('اَلْقِنْيَةُ نَهْبُ الأحْداثِ.', 'Acquisitions are the spoils of disasters.', 'Ghurar al-Hikam, Acquisitions- §5', 'wisdom'),
  ('اِطِّراحُ الكُلَفِ أشْرَفُ قِنْيَة.', 'The discarding of hardships [one endures for attaining worldly gain] is the best of acquisitions.', 'Ghurar al-Hikam, Acquisitions- §6', 'wisdom'),
  ('بِقَدْرِ القِنْيَةِ يَتَضاعَفُ اَلحُزْنُ والغُمُومُ.', 'To the extent of [one’s] acquisitions, sorrow and grief is multiplied.', 'Ghurar al-Hikam, Acquisitions- §7', 'wisdom'),
  ('ثَمَرَةُ المُقْتَنَياتِ الحُزْنُ.', 'The fruit of acquisitions is sorrow.', 'Ghurar al-Hikam, Acquisitions- §8', 'wisdom'),
  ('اَلكَلامُ بَيْنَ خَلَّتَيْ سَوْء: هُما الإكْثارُ، والإقْلالُ، فَالإكْثارُ هَذَرٌ، وَالإقْلالُ عَيٌّ وحَصَرٌ.', 'Speech is between two bad qualities, namely: too much and too little; too much [of it] is babble and too little is inarticulateness and speechlessness.', 'Ghurar al-Hikam, Speech and speaking- §1', 'wisdom'),
  ('اَلإكْثارُ يُزِلُّ الحَكيمَ، ويُمِلُّ الحَليمَ، فَلا تُـكْثِرْ فَتُضْجِرْ، ولاتُفَرِّطْ فَتُهَنْ.', 'Speaking too much makes the wise one stumble and makes the tolerant one weary, therefore do not talk so much that others get fed up and do not be so reticent that you are humiliated.', 'Ghurar al-Hikam, Speech and speaking- §2', 'wisdom'),
  ('اَلكَلامُ في وَثاقِكَ ما لَمْ تَتَكَلَّمْ بِهِ، فَإذا تَكَلَّمْتَ صِرْتَ في وَثاقِهِ.', 'Speech is in your control as long as you have not uttered it, but once you utter it you become shackled by it.', 'Ghurar al-Hikam, Speech and speaking- §3', 'wisdom'),
  ('اَلكَلامُ كَالدَّواءِ قَليلُهُ يَنْفَعُ،وَ كَثيرُهُ قاتِلٌ.', 'Speech is like medicine, a little of it is beneficial but too much of it can be fatal.', 'Ghurar al-Hikam, Speech and speaking- §4', 'wisdom'),
  ('أقْلِلْ كَلامَكَ، تَأمَنْ مَلاماً.', 'Reduce your speech and you will remain safe from censure.', 'Ghurar al-Hikam, Speech and speaking- §6', 'wisdom'),
  ('إيّاكَ ومُسْتَهْجَنَ الكَلامِ، فَإنَّهُ يُوغِرُ القُلُوبَ.', 'Beware of offensive speech for indeed it fills the hearts with spite [and hatred].', 'Ghurar al-Hikam, Speech and speaking- §7', 'wisdom'),
  ('إيّاكَ وكَثْرَةَ الكَلامِ، فَإنَّهُ يُكْثِرُ الزَّلَلَ، ويُورِثُ المَلَلَ.', 'Beware of excessive speech for indeed it increases errors and brings about weariness.', 'Ghurar al-Hikam, Speech and speaking- §8', 'wisdom'),
  ('إيّاكَ وفُضُولَ الكَلامِ، فَإنَّهُ يُظْهِرُ مِنْ عُيُوبِكَ ما بَطَنَ، ويُحَرِّكُ عَلَيْكَ مِنْ أعْدائِكَ ما سَكَنَ.', 'Beware of excessive [and impertinent] speech, for indeed it manifests your hidden flaws and provokes your silent enemies.', 'Ghurar al-Hikam, Speech and speaking- §9', 'wisdom'),
  ('إيّاكَ وما يُسْتَهْجَنُ مِنَ الكَلامِ، فَإنَّهُ يَحْبِسُ (يَحيسُ) عَلَيْكَ اللِّئامَ، ويُنَفِّرُ عَنْكَ الكِرامَ.', 'Beware of speech which is offensive, for indeed it confines you to [the company of] vile people and repels the honourable ones from you.', 'Ghurar al-Hikam, Speech and speaking- §10', 'wisdom'),
  ('إيّاكَ والكَلامَ فيما لاتَعْرِفُ طريقَتَهُ، ولاتَعْلَمُ حَقيقَتَهُ، فَإنَّ قَوْلَكَ يَدُلُّ عَلى عَقْلِكَ، وعِبارَتَكَ تُنْبِئُ عَنْ مَعْرِفَتِكَ، فَتَوَقَّ مِنْ طُولِ لِسانِكَ ما أمِنْتَهُ، واخْتَصِرْ مِنْ كَلامِكَ مَا اسْتَحْسَنْتَهُ، فَإنَّهُ بِكَ أجْمَلُ وعَلى فَضْلِكَ أدَلُّ.', 'Beware of speaking about something whose way you are unfamiliar with and whose reality you are unaware of, for indeed your speech indicates your intellect, and your expression informs about your level of understanding, so limit your long tongue to that which keeps you safe, and make your speech concise to [the extent of] what is deemed good, for indeed this is more beautiful for you and more indicative of your merit.', 'Ghurar al-Hikam, Speech and speaking- §11', 'wisdom'),
  ('اَلاِسْتِقامَةُ سَلامَةٌ.', 'Steadfastness is safety.', 'Ghurar al-Hikam, Steadfastness- §1', 'wisdom'),
  ('لاسَبيلَ أشْرَفُ مِنَ الاِسْتِقامَةِ.', 'There is no path that is nobler than steadfastness.', 'Ghurar al-Hikam, Steadfastness- §2', 'wisdom'),
  ('لامَسْلَكَ أسْلَمُ مِنَ الاِسْتِقامَةِ.', 'There is no course more secure than steadfastness.', 'Ghurar al-Hikam, Steadfastness- §3', 'wisdom'),
  ('كَيْفَ يَسْتَقيمُ قَلْبُ مَنْ لَمْ يَسْتَقِمْ دينُهُ.', 'How can the heart of one whose faith is not steadfast be upright?', 'Ghurar al-Hikam, Steadfastness- §4', 'wisdom'),
  ('مَنْ لَزِمَ الاِسْتِقامَةَ لَمْ يََعدِمِ السَّلامَةَ.', 'One who remains steadfast is not bereft of safety.', 'Ghurar al-Hikam, Steadfastness- §5', 'wisdom'),
  ('لايُقيمُ أمْرَ اللّهِ سُبْحانَهُ إلاّ مَنْ لايُصانِعُ ولايُخادِعُ، ولاتَغُرُّهُ المَطامِعُ.', 'The command of Allah, the Glorified, is not established [and executed] except by one who neither corrupts nor beguiles, nor is he deceived by [that which he] desires.', 'Ghurar al-Hikam, Establishing the command of Allah- §1', 'wisdom'),
  ('اَلْقَوِيُّ مَنْ قَمَعَ لَذَّتَهُ.', 'A strong person is one who subdues his pleasures.', 'Ghurar al-Hikam, The strong- §1', 'wisdom'),
  ('آفَةُ القَوِيِّ اِسْتِضْعافُ الخَصْمِ.', 'The bane of the strong person is underestimating the enemy.', 'Ghurar al-Hikam, The strong- §2', 'wisdom'),
  ('إذا قَويتَ فَاقْوِ عَلى طاعَةِ اللّهِ سُبْحانَهُ.', 'When you [wish to] become strong, then be strong in the obedience of Allah, the Glorified.', 'Ghurar al-Hikam, The strong- §3', 'wisdom'),
  ('اَلكِبْرُ داع إلَى التَّقَحُّمِ فِي الذُّنُوبِ.', 'Arrogance is an inviter towards plunging into sins.', 'Ghurar al-Hikam, Arrogance- §1', 'wisdom'),
  ('اَلْكِبْرُ خَلِيقَةٌ مُرْدِيَةٌ، مَنْ تَكَثَّرَ بِها قَلَّ.', 'Arrogance is a destructive trait, one who seeks to increase by it, diminishes.', 'Ghurar al-Hikam, Arrogance- §2', 'wisdom'),
  ('اَلْكِبْرُ يُساوِرُ القُلُوبَ مُساوَرَةَ السُّمُومِ القاتِلَةِ.', 'Arrogance grips the hearts just like a fatal poison.', 'Ghurar al-Hikam, Arrogance- §3', 'wisdom'),
  ('اِقْمَعُوا نَواجِمَ الفَخْرِ، واقْدِعُوا لَوامِعَ (طَوالِعَ) الكِبْرِ.', 'Suppress the manifestations of pride and restrain the flashes (or risings) of arrogance.', 'Ghurar al-Hikam, Arrogance- §4', 'wisdom'),
  ('اِحْذَرِ الكِبْرَ فَإنَّهُ رَأْسُ الطُغْيانِ، ومَعْصيَةُ الرَّحْمنِ.', 'Beware of arrogance, for it is the cornerstone of tyranny and disobedience to the Most Merciful.', 'Ghurar al-Hikam, Arrogance- §5', 'wisdom'),
  ('إيّاكَ والكِبْرَ، فَإنَّهُ أعْظَمُ الذُّنُوبِ، وألأمُ العُيُوبِ، وهُوَ حِلْيَةُ إبْلِيسَ.', 'Beware of arrogance, for indeed it is the greatest of sins and the vilest of faults, and it is the ornament of the Devil.', 'Ghurar al-Hikam, Arrogance- §6', 'wisdom'),
  ('إيّاكَ والتَّجَبُّرَ عَلى عِبادِ اللّهِ، فَإنَّ كُلَّ مُتَجَبِّر يَقْصِمُهُ اللّهُ.', 'Beware of behaving haughtily with the servants of Allah, for every haughty one is crushed by Allah.', 'Ghurar al-Hikam, Arrogance- §7', 'wisdom'),
  ('أقْبَحُ الخُلْقِ التَّكَبُّرُ.', 'The ugliest character is arrogance.', 'Ghurar al-Hikam, Arrogance- §8', 'wisdom'),
  ('أكْثَرُ النّاسِ ضَعَةً مَنْ تَعاظَمَ في نَفْسهِ.', 'The lowliest of all people is one who considers himself to be great.', 'Ghurar al-Hikam, Arrogance- §9', 'wisdom'),
  ('اَلتَّكَبُّرُ يَضَعُ.', 'Arrogance humiliates.', 'Ghurar al-Hikam, Arrogance- §10', 'wisdom'),
  ('المُتَجَبِّـرُ الظّالِمُ تُوبِقُهُ آثامُهُ.', 'The haughty oppressor is destroyed by his sins.', 'Ghurar al-Hikam, The arrogant one- §1', 'wisdom'),
  ('عَجِبْتُ لِمُتَكَبِّر كانَ أمْسِ نُطْفَةً، وهُوَ فِي غَد جيفَةً.', 'I am amazed at the arrogant one who was [nothing but] a drop of semen yesterday and will tomorrow be [just] a corpse.', 'Ghurar al-Hikam, The arrogant one- §2', 'wisdom'),
  ('قَدْ يَذِلُّ المُتَجَبِّرُ.', 'At times the haughty one is humiliated.', 'Ghurar al-Hikam, The arrogant one- §3', 'wisdom'),
  ('كُلُّ مُتَكَبِّر حَقيرٌ.', 'Every arrogant one is low.', 'Ghurar al-Hikam, The arrogant one- §4', 'wisdom'),
  ('لَيْسَ لِمُتَكَبِّر صَديقٌ.', 'The arrogant one has no friend.', 'Ghurar al-Hikam, The arrogant one- §5', 'wisdom'),
  ('مَنْ تَكَبَّرَ حُقِّرَ.', 'One who becomes arrogant is abased.', 'Ghurar al-Hikam, The arrogant one- §6', 'wisdom'),
  ('مَنْ تَكَبَّرَ مُقِتَ.', 'One who shows arrogance is loathed.', 'Ghurar al-Hikam, The arrogant one- §7', 'wisdom'),
  ('مَنْ تَكَبَّرَ عَلَى النّاسِ ذَلَّ.', 'One who is arrogant towards the people gets humiliated.', 'Ghurar al-Hikam, The arrogant one- §8', 'wisdom'),
  ('مَنْ تَجَبَّرَ عَلى مَنْ دُونَهُ كُسِرَ.', 'One who is haughty with the one who is below him gets broken [and pulled down from his position].', 'Ghurar al-Hikam, The arrogant one- §9', 'wisdom'),
  ('مَنْ كانَ مُتَكَبِّراً لَمْ يَعْدِمِ التَّلَّفَ.', 'One who is arrogant will not be devoid of loss [and injury].', 'Ghurar al-Hikam, The arrogant one- §10', 'wisdom'),
  ('اَلْكِتابُ أحَدُ المُحَدِّثَيْنِ.', 'The book is one of the two interlocutors.', 'Ghurar al-Hikam, The book and writing- §1', 'wisdom'),
  ('إذا كَتَبْتَ كِتاباً فَأعِدْ فيهِ النَّظَرَ قَبْلَ خَتْمِهِ، فَإنَّما تَخْتِمُ عَلى عَقْلِكَ.', 'When you write something then take another look at it before putting a seal on it, for indeed [by putting a seal on it] you are only putting a seal on your intellect [as your intelligence will be gauged by your writing].', 'Ghurar al-Hikam, The book and writing- §2', 'wisdom'),
  ('كِتابُ الرَّجُلِ عُنْوانُ عَقْلِهِ، وبُرهانُ فَضْلِهِ.', 'The writing of a man is the symbol of his intellect and the evidence of his merit.', 'Ghurar al-Hikam, The book and writing- §3', 'wisdom'),
  ('كِتابُ المَرْءِ مِعْيارُ فَضْلِهِ، ومِسْبارُ نُبْلِهِ.', 'The writing of a person is the gauge of his merit and the measure of his nobility.', 'Ghurar al-Hikam, The book and writing- §4', 'wisdom'),
  ('نِعْمَ المُحَدِّثُ الكِتابُ.', 'How good an interlocutor a book is!', 'Ghurar al-Hikam, The book and writing- §5', 'wisdom'),
  ('اَلكِتابُ تَرْجُمانُ النِّـيَّةِ.', 'Writing is the interpreter of intention.', 'Ghurar al-Hikam, The book and writing- §6', 'wisdom'),
  ('اَلكُتُبُ بَساتينُ العُلَماءِ.', 'Books are the gardens of scholars.', 'Ghurar al-Hikam, The book and writing- §7', 'wisdom'),
  ('مَنْ تَسَلّى بِالكُتُبِ لَمْ تَفُتْهُ سُلْوَةٌ.', 'Whoever takes solace [and delight] in [reading] books will never lack [any] solace.', 'Ghurar al-Hikam, The book and writing- §8', 'wisdom'),
  ('اَلكِتْمانُ مِلاكُ النَّجْوى.', 'Secrecy is the basis of confidential conversations.', 'Ghurar al-Hikam, Secrecy- §1', 'wisdom'),
  ('قُرِنَ الإكْثارُ بِالمَلَلِ.', 'Loquaciousness has been paired up with boredom.', 'Ghurar al-Hikam, Loquaciousness- §1', 'wisdom'),
  ('مَنْ أكْثَرَ هُجِرَ.', 'One who is loquacious is abandoned.', 'Ghurar al-Hikam, Loquaciousness- §2', 'wisdom'),
  ('مَنْ كَثُرَ مَقالُهُ سُئِمَ.', 'One who talks too much makes others fed up.', 'Ghurar al-Hikam, Loquaciousness- §3', 'wisdom'),
  ('مَنْ كَثُرَ كَلامُهُ زَلَّ.', 'One who speaks too much [makes] blunders.', 'Ghurar al-Hikam, Loquaciousness- §4', 'wisdom'),
  ('مَنْ كَثُرَ كَلامُهُ كَثُرَ مَلامُهُ.', 'One who speaks too much gets rebuked more.', 'Ghurar al-Hikam, Loquaciousness- §5', 'wisdom'),
  ('مَنْ أكْثَرَ مِنْ شَيْء عُرِفَ بِهِ.', 'One who does too much of something is known by it.', 'Ghurar al-Hikam, Loquaciousness- §6', 'wisdom'),
  ('تَكَثُّرُكَ (تَكَبُّرُكَ) بِما لايَبْقى لَكَ ولاتَبْقى لَهُ مِنْ أعْظَمِ الجَهْلِ.', 'Amassing that which does not last for you and for which you will not remain is from the greatest ignorance.', 'Ghurar al-Hikam, Amassing [wealth]- §1', 'detachment'),
  ('اَلْكِذْبُ يُرْدي مُصاحِبَهُ، ويُنْجي مُجانِبَهُ.', 'Lying destroys the one who accompanies it and saves the one who eschews it.', 'Ghurar al-Hikam, Lying- §1', 'character'),
  ('اَلْكِذْبُ فِي العاجِلَةِ عارٌ وفِي الآ جِلَةِ عَذابُ النّارِ.', 'Lying is [a cause of] disgrace in this world and [leads one to] hellfire in the Hereafter.', 'Ghurar al-Hikam, Lying- §2', 'character'),
  ('أقْبَحُ الخَلائِقِ اَلْكِذْبُ.', 'The most repulsive quality is dishonesty.', 'Ghurar al-Hikam, Lying- §3', 'character'),
  ('اَلْكِذْبُ خِيانَةٌ.', 'Lying is treachery.', 'Ghurar al-Hikam, Lying- §4', 'character'),
  ('اَلْكِذْبُ يُرْدي.', 'Lying makes one fall [into destruction].', 'Ghurar al-Hikam, Lying- §5', 'character'),
  ('اَلْكِذْبُ عَدُوُّ الصِّدْقِ.', 'Lying is the enemy of truthfulness.', 'Ghurar al-Hikam, Lying- §6', 'character'),
  ('اَلْكِذْبُ عَيْبٌ فاضِحٌ.', 'Dishonesty is a disgraceful flaw.', 'Ghurar al-Hikam, Lying- §7', 'character'),
  ('اَلْكِذْبُ مُجانِبُ الإيمانِ.', 'Lying is alien to [and incompatible with] faith.', 'Ghurar al-Hikam, Lying- §8', 'character'),
  ('اَلْكِذْبُ مَهانَةٌ وخِيانَةٌ (وَنَدامَةٌ).', 'Lying is disgrace and treachery (and regret).', 'Ghurar al-Hikam, Lying- §9', 'character'),
  ('اَلْكِذْبُ يُزْري بِالإنْسانِ.', 'Lying degrades a person.', 'Ghurar al-Hikam, Lying- §10', 'character'),
  ('اَلكَذَّابُ مُتَّهَمٌ في قَوْلِهِ، وإنْ قَوِيَتْ حُجَّتُهُ، وصَدَقَتْ لَهْجَتُهُ.', 'The [one who is known to be a] incessant liar is suspected in his speech, even if his proof is strong and his tone is truthful.', 'Ghurar al-Hikam, The liar- §1', 'wisdom'),
  ('اَلكَذّابُ والمَيِّتُ سَواءٌ، فَإنَّ (لأنَّ) فَضيلَةَ الحَيِّ عَلَى المَيِّتِ اَلثِّقَةُ بِهِ، فَإذا لَمْ يُوثَقْ بِكَلامِهِ بَطَلَتْ حَياتُهُ.', 'The incessant liar and the dead are similar, for indeed (or because) the merit of the living over the dead is the ability to rely on him, so if his words are not reliable then [it is as if] his life is nullified.', 'Ghurar al-Hikam, The liar- §2', 'wisdom'),
  ('أبْعَدُ النّاسِ مِنَ الصَّلاحِ اَلكَذُوبُ وذُوالوَجْهِ الوَقاحِ.', 'The furthest of all people from goodness is the incessant liar and the brazen-faced.', 'Ghurar al-Hikam, The liar- §3', 'wisdom'),
  ('اَلكاذِبُ مُهانٌ ذَليلٌ.', 'The liar is disgraced and humiliated.', 'Ghurar al-Hikam, The liar- §4', 'wisdom'),
  ('اَلْكاذِبُ عَلى شَفا مَهْواة ومَهانَة.', 'A liar is at the brink of an abyss [of ruin] and disgrace.', 'Ghurar al-Hikam, The liar- §5', 'wisdom'),
  ('كَفاكَ مُوَبِّخاً عَلَى الكِذْبِ عِلْمُكَ بِأنَّكَ كاذِبٌ.', 'Your knowing that you are a liar suffices as a rebuke for lying.', 'Ghurar al-Hikam, The liar- §6', 'wisdom'),
  ('لَيْسَ لِكَذُوب أمانَةٌ ولا لِفَجُور صِيانَةٌ.', 'There is no trustworthiness in an incessant liar and there is no safeguarding [from sin] in the morally corrupt.', 'Ghurar al-Hikam, The liar- §7', 'wisdom'),
  ('مَنْ كَذَبَ أفْسَدَ مُرُوَّتَهُ.', 'One who lies corrupts his magnanimity.', 'Ghurar al-Hikam, The liar- §8', 'wisdom'),
  ('مَنْ كَثُرَ كِذْبُهُ لَمْ يُصَدَّقْ.', 'One who lies excessively is not believed.', 'Ghurar al-Hikam, The liar- §9', 'wisdom'),
  ('مَنْ عُرِفَ بِالكِذْبِ لَمْ يُقْبَلْ صِدْقُهُ.', 'One who is known for lying, [even] his truth will not be accepted.', 'Ghurar al-Hikam, The liar- §10', 'wisdom'),
  ('اَلْكَرَمُ حُسْنُ السَّجيَّةِ واجْتِنابُ الدَّنيَّة.', 'Being noble-minded means having a good character and eschewing lowly traits.', 'Ghurar al-Hikam, Nobleness and munificence- §1', 'wisdom'),
  ('اَلْكَرَمُ بَذْلُ الجُودِ، وإنجازُ المَوْعُودِ.', 'Munificence is [in] giving generously and fulfilling promises.', 'Ghurar al-Hikam, Nobleness and munificence- §2', 'wisdom'),
  ('اَلْكَرَمُ إيثارُ عُذُوبَةِ الثَّناءِ عَلى حُبِّ المالِ.', 'Nobleness is [in] preferring the pleasantness of praise over the love of wealth.', 'Ghurar al-Hikam, Nobleness and munificence- §3', 'wisdom'),
  ('أحْسَنُ الكَرَمِ اَلإيثارُ.', 'The best munificence is altruism.', 'Ghurar al-Hikam, Nobleness and munificence- §4', 'wisdom'),
  ('أعْلى مَراتِبِ الكَرَمِ الإيثارُ.', 'The highest level of munificence is self-sacrifice.', 'Ghurar al-Hikam, Nobleness and munificence- §5', 'wisdom'),
  ('أفْضَلُ الكَرَمِ إتْمامُ النِّـعَمِ.', 'The most excellent munificence is completing [one’s] favours.', 'Ghurar al-Hikam, Nobleness and munificence- §6', 'wisdom'),
  ('اَلْكَرَمُ فَضْلٌ، الوَفاءُ نُبْلٌ.', 'Munificence is excellence and loyalty is nobility.', 'Ghurar al-Hikam, Nobleness and munificence- §7', 'wisdom'),
  ('اَلْكَرَمُ مَعْدِنُ الخَيْرِ.', 'Nobleness is the source of goodness.', 'Ghurar al-Hikam, Nobleness and munificence- §8', 'wisdom'),
  ('اَلْكَرَمُ أفْضَلُ السُّؤْدَدِ.', 'Munificence is the best eminence.', 'Ghurar al-Hikam, Nobleness and munificence- §9', 'wisdom'),
  ('اَلْكَرَمُ أفْضَلُ الشِّيَمِ.', 'Munificence is the best of traits.', 'Ghurar al-Hikam, Nobleness and munificence- §10', 'wisdom'),
  ('اَلْكَرِيمُ مَنْ تَجَنَّبَ المَحارِمَ وتَنَزَّهَ عَنِ العُيُوبِ.', 'The noble-minded person is one who keeps away from the forbidden and steers clear of [disgraceful] flaws.', 'Ghurar al-Hikam, The noble-minded and the munificent- §1', 'wisdom'),
  ('اَلْكَرِيمُ مَنْ جاءَ بِالمَوْجُودِ.', 'The munificent person is one who brings [and gives away] whatever is available.', 'Ghurar al-Hikam, The noble-minded and the munificent- §2', 'wisdom'),
  ('اَلْكَرِيمُ مَن جازَى الإسائَةَ بِالإحْسانِ.', 'A noble-minded person is one who repays evil with good.', 'Ghurar al-Hikam, The noble-minded and the munificent- §3', 'wisdom'),
  ('اَلْكَرِيمُ يَزْدَجِرُ عَمّا يَفْتَخِرُ بِهِ اللَئِيمُ.', 'A noble-minded person is repulsed by that which the wicked take pride in.', 'Ghurar al-Hikam, The noble-minded and the munificent- §4', 'wisdom'),
  ('اَلْكَرِيمُ يَجْفُو إذا عُنِّفَ، ويَلِينُ إذَا اسْتُعْطِفَ.', 'The munificent one cuts off his favour when he is approached harshly and is soft [and kind] when he is entreated [politely]', 'Ghurar al-Hikam, The noble-minded and the munificent- §5', 'wisdom'),
  ('اَلْكَريمُ إذا قَدَرَ صَفَحَ، وإذا مَلَكَ سَمَحَ، وإذا سُئِلَ أنْجَحَ.', 'When a noble-minded person is able [to take revenge] he forgives, and when he gains possession [of something] he grants generously, and when he is asked [for something] he accords [it].', 'Ghurar al-Hikam, The noble-minded and the munificent- §6', 'wisdom'),
  ('اَلكَريمُ يَأبَى العارَ، ويُكْرِمُ الجارَ.', 'A noble-minded person rejects disgrace and honours his neighbour.', 'Ghurar al-Hikam, The noble-minded and the munificent- §7', 'wisdom'),
  ('اَلْكَريمُ يَرى مَكارِمَ أفْعالِهِ دَيْناً عَلَيْهِ يَقْضيهِ.', 'A noble-minded person considers his virtuous actions as a debt that he has to repay.', 'Ghurar al-Hikam, The noble-minded and the munificent- §8', 'wisdom'),
  ('اَلْكَريمُ يَرْفَعُ نَفْسَهُ في كُلِّ ما أسْداهُ عَنْ حُسْنِ المُجازاتِ.', 'The noble-minded person raises himself above [the expectation of] rewards in everything good that he does.', 'Ghurar al-Hikam, The noble-minded and the munificent- §9', 'wisdom'),
  ('اَلْكَريمُ إذَا احْتاجَ إلَيْكَ أعْفاكَ، وإذَا احْتَجْتَ إلَيْهِ كَفاكَ.', 'When a noble-minded person needs you he excuses you [from helping him] and when you need him he suffices you.', 'Ghurar al-Hikam, The noble-minded and the munificent- §10', 'wisdom'),
  ('مَنْ لَمْ تُقَوِّمْهُ الكَرامَةُ قَوَّمَتْهُ الإهانَةُ.', 'One who is not set aright by high esteem is put right by indignity.', 'Ghurar al-Hikam, High-esteem- §1', 'wisdom'),
  ('مَنْ لَمْ تُصْلِحْهُ الكَرامَةُ أصْلَحَتْهُ الإهانَةُ.', 'One who is not reformed by high esteem is reformed by indignity.', 'Ghurar al-Hikam, High-esteem- §2', 'wisdom'),
  ('مَنْ زادَهُ اللّهُ كَرامَةً فَحَقيقٌ بِه أنْ يَزيدَ النّاسَ إكْراماً.', 'It is a right upon one whose esteem has been increased by Allah that he should [in turn] be more respectful to the people.', 'Ghurar al-Hikam, High-esteem- §3', 'wisdom'),
  ('مَنْ رَبّاهُ الهَوانُ أبْطَـرَتْهُ الكَرامَةُ.', 'One who is raised by disgrace is made vain by high esteem.', 'Ghurar al-Hikam, High-esteem- §4', 'wisdom'),
  ('إذا رَغِبْتَ فِي المَكارِمِ فَاجْتَنِبِ المَحارِمَ.', 'When you desire to acquire noble traits then keep away from the forbidden.', 'Ghurar al-Hikam, Noble traits and deeds- §1', 'wisdom'),
  ('تَبادَرُوا المَكارِمَ، وسارِعُوا إلى تَحَمُّلِ المَغارِمِ، واسْعَوْا في حاجَةِ مَنْ هُوَ نائِمٌ، يَحْسُنْ لَكُمْ فِي الدّارَيْنِ الجَزاءُ،وَ تَنالُوا مِنَ اللّهِ عَظيمَ الحَباءِ.', 'Rush towards noble deeds, make haste in bearing the liabilities [of others] and hurry to fulfil the needs of the one who is unaware [of your assistance], your reward will thus be good in both abodes, and you will acquire a great prize from Allah.', 'Ghurar al-Hikam, Noble traits and deeds- §2', 'wisdom'),
  ('ثابِرُوا عََلَى اقْتِناءِ المَكارِمِ، وتَحَمَّلُوا أعْباءَ المَغارِمِ، تُحْرِزُوا قَصَباتِ المَغانِمِ.', 'Work hard to acquire noble traits and bear the burden of [others’] liabilities, [as a result] you will achieve the greatest gains.', 'Ghurar al-Hikam, Noble traits and deeds- §3', 'wisdom'),
  ('خَيْرُ المَكارِمِ الإيثارُ.', 'The best of noble traits is altruism.', 'Ghurar al-Hikam, Noble traits and deeds- §4', 'wisdom'),
  ('رُوحُوا فِي المَكارِمِ،وَ ادَّلِجُوا في حاجَةِ مَنْ هُوَ نائِمٌ.', 'End your day’s work with noble deeds and begin the night by fulfilling the needs of the one who is asleep [and unaware of your assistance].', 'Ghurar al-Hikam, Noble traits and deeds- §5', 'wisdom'),
  ('عَلَيْكَ بِمَكارِمِ الخِلالِ واصْطِناعِ الرِّجالِ فَإنَّهُما يَقِيانِ مَصارِعَ السَّوْءِ ويُوجِبانِ الجَلالَةَ.', 'Acquire noble traits and do good to the people, for indeed these two things protect one from falling into difficulties and lead to loftiness.', 'Ghurar al-Hikam, Noble traits and deeds- §6', 'wisdom'),
  ('غايَةُ المَكارِمِ اَلإيثارُ.', 'The pinnacle of noble traits is altruism.', 'Ghurar al-Hikam, Noble traits and deeds- §7', 'wisdom'),
  ('مِنْ أفْضَلِ المَكارِمِ تَحَمُّلُ المَغارِمِ، وإقْراءُ الضُّيُوفِ.', 'From the best noble deeds is bearing the liabilities [and debts of others] and being hospitable to one’s guests.', 'Ghurar al-Hikam, Noble traits and deeds- §8', 'wisdom'),
  ('مِنْ أحْسَنِ المَكارِمِ بَثُّ المَعْرُوفِ.', 'One of the best noble deeds is spreading goodness [and virtue].', 'Ghurar al-Hikam, Noble traits and deeds- §9', 'wisdom'),
  ('مِـنْ أحْسَنِ المَكارِمِ تَجَنُّبُ المَحارِمِ.', 'One of the best noble deeds is keeping away from the forbidden.', 'Ghurar al-Hikam, Noble traits and deeds- §10', 'wisdom'),
  ('مَكْرُوهٌ تُحْمَدُ عاقِبَتُهُ، خَيْرٌ مِنْ مَحْبُوب تُذَمُّ مَغَبَّتُهُ.', 'The disliked act which has a praiseworthy result is better than the action which one loves [but] whose outcome is dispraised.', 'Ghurar al-Hikam, The disliked- §1', 'wisdom'),
  ('أزْكَى الْمَكاسِبِ كَسْبُ الحَلالِ.', 'The purest of earnings is lawful earning.', 'Ghurar al-Hikam, Earnings- §1', 'wisdom'),
  ('بِئْسَ الْكَسْبُ الحَرامُ.', 'The worst kind of earning is the unlawful [earning].', 'Ghurar al-Hikam, Earnings- §2', 'wisdom'),
  ('رُكُوبُ الأهْوالِ يَكْسِبُ الأمْوالَ.', 'Embarking on the terrifying [and surmounting one’s fears] brings wealth.', 'Ghurar al-Hikam, Earnings- §3', 'wisdom'),
  ('مَنِ اكْتَسَبَ حَراماً اِحْتَقَبَ آثاماً.', 'One who earns by unlawful means accumulates sins.', 'Ghurar al-Hikam, Earnings- §4', 'wisdom'),
  ('مَنْ دامَ كَسَلُهُ خابَ أمَلُهُ.', 'One who is always lazy, his hopes get dashed.', 'Ghurar al-Hikam, Laziness and the lazy- §1', 'wisdom'),
  ('لاتَتَّكِلْ في أُمُورِكَ عَلى كَسْلان.', 'Do not rely on a lazy person in your affairs.', 'Ghurar al-Hikam, Laziness and the lazy- §2', 'wisdom'),
  ('رَضِيَ بِالذُّلِّ مَنْ كَشَفَ ضُرَّهُ لِغَيْرِهِ.', 'One who reveals his distress to others has accepted humiliation.', 'Ghurar al-Hikam, Revealing and removing distress- §1', 'wisdom'),
  ('ما مِنْ عَمَل أحَبَّ إلَى اللّهِ تَعالى مِنْ ضُرّ يَكْشِفُهُ رَجْلٌ عَنْ رَجُل.', 'No action is more beloved to Allah, the Most High, than for a person to remove the distress [and adversity] from another person.', 'Ghurar al-Hikam, Revealing and removing distress- §2', 'wisdom'),
  ('اَلْكاظِمُ مَنْ أماتَ أضْغانَهُ.', 'The suppressor of anger is one who extirpates his grudges.', 'Ghurar al-Hikam, Suppressing anger- §1', 'self-mastery'),
  ('اِكْظِمِ الغَيْظَ تَزْدَدْ حِلْماً.', 'Suppress [your] anger and you will increase in forbearance.', 'Ghurar al-Hikam, Suppressing anger- §2', 'self-mastery'),
  ('اَلكَظْمُ ثَمَرَةُ الحِلْمِ.', 'Suppression [of anger] is the fruit of forbearance.', 'Ghurar al-Hikam, Suppressing anger- §3', 'self-mastery'),
  ('رَأْسُ الحِلْمِ الكَظْمُ.', 'The cornerstone of forbearance is suppression [of anger].', 'Ghurar al-Hikam, Suppressing anger- §4', 'self-mastery'),
  ('طُوْبى لِمَنْ كَظَمَ غَيْظَهُ ولَمْ يُطْلِقْهُ، وعَصى أمْرَ نَفْسِهِ فَلَمْ يُهْلِكْهُ.', 'Blessed is the one who suppresses his anger and does not let it loose, and [who] disobeys the command of his [carnal] soul and thus is not destroyed by it.', 'Ghurar al-Hikam, Suppressing anger- §5', 'self-mastery'),
  ('كَمْ مِنْ غَيظ تُجُرِّعَ مَخافَةَ ما هُوَ أشَدُّ مِنْهُ.', 'How many a time is anger suppressed out of the fear of that which is more severe than it.', 'Ghurar al-Hikam, Suppressing anger- §6', 'self-mastery'),
  ('مَنْ كَظَمَ غَيْظَهُ كَمُلَ حِلْمُهُ.', 'Whoever suppresses his anger, his forbearance becomes complete.', 'Ghurar al-Hikam, Suppressing anger- §7', 'self-mastery'),
  ('اِكْظَمِ الغَيْظَ عِنْدَ الغَضَبِ وتَجاوَزْ مَعَ الدَّوْلَةِ تَكُنْ لَكَ العاقِبَةُ.', 'Suppress [your] rage when you are angry and overlook [the fault of others] despite having authority, [in this way] the outcome will be in your favour.', 'Ghurar al-Hikam, Suppressing anger- §8', 'self-mastery'),
  ('اِصْطِناعُ الكَفُورِ مِنْ أعْظَمِ الجُرْمِ.', 'Doing good to an ingrate is from the greatest of crimes.', 'Ghurar al-Hikam, Ingratitude- §1', 'gratitude'),
  ('كُفْرُ النِّعْمَةِ مُزيلُها وشُكْرُها مُسْتَديمُها.', 'Being ungrateful for a blessing causes it to be taken away and being thankful for it causes it to last.', 'Ghurar al-Hikam, Ingratitude- §2', 'gratitude'),
  ('كُفْرانُ النِّعَـمِ يُزِلُّ القَدَمَ ويَسْلُبُ النِّعَمَ.', 'Ingratitude for blessings makes one stumble and strips away the blessings.', 'Ghurar al-Hikam, Ingratitude- §3', 'gratitude'),
  ('كُفْرُالنِّعْمَةِ لُؤْمٌ، وصُحْبَةُ الأحْمَقِ شُؤْمٌ.', 'Ungratefulness for a blessing is vileness, and accompanying a fool is [a cause of] misfortune.', 'Ghurar al-Hikam, Ingratitude- §4', 'gratitude'),
  ('كُفْرُ النِّعْمَةِ مُزيلُها.', 'Being ungrateful for a blessing is the cause of its removal.', 'Ghurar al-Hikam, Ingratitude- §5', 'gratitude'),
  ('كافِرُ النِّعْمَةِ كافِرُ فَضْلِ اللّهِ.', 'The one who is unthankful for blessings is ungrateful for the bounty of Allah.', 'Ghurar al-Hikam, Ingratitude- §6', 'gratitude'),
  ('كُفْرُ النِّعَمِ مَجْلَبَةٌ لِحُلُولِ النِّقَمِ.', 'Ingratitude for blessings is the thing that brings [divine] retribution.', 'Ghurar al-Hikam, Ingratitude- §7', 'gratitude'),
  ('كافِرُ النِّعْمَةِ مَذْمُومٌ عِنْدَ الخالِقِ والخَلائِقِ.', 'The one who is ungrateful for blessings is dispraised in the sight of the Creator and the creation.', 'Ghurar al-Hikam, Ingratitude- §8', 'gratitude'),
  ('لَيْسَ مِنَ التَّوْفيقِ كُفْرانُ النِّـعَمِ.', 'Ingratitude for blessings is not a success [rather it is a failure].', 'Ghurar al-Hikam, Ingratitude- §9', 'gratitude'),
  ('لانِعْمَةَ مََعَ كُفْر.', 'There is no blessing with ingratitude.', 'Ghurar al-Hikam, Ingratitude- §10', 'gratitude'),
  ('اَلْكافِرُ خَبٌّ لَئِيمٌ،خَؤُنٌ، مَغْرُورٌ بِجَهْلِهِ، مَغْبُونٌ.', 'The disbeliever is a vile deceiver, perfidious, deluded by his ignorance and duped.', 'Ghurar al-Hikam, The disbeliever- §1', 'wisdom'),
  ('اَلكافِرُ اَلدُّنيا جَنَّـتُهُ، والعاجِلَةُ هِمَتُّهُ، والمَوْتُ شَقاوَتُهُ، والنّارُ غايَتُهُ.', 'For the disbeliever, this world is his Paradise, the transient is what he strives for, death is [the cause of] his wretchedness and hellfire is his final end.', 'Ghurar al-Hikam, The disbeliever- §2', 'wisdom'),
  ('اَلْكافِرُ فاجِرٌ جاهِلٌ.', 'The disbeliever is an immoral, ignorant person.', 'Ghurar al-Hikam, The disbeliever- §3', 'wisdom'),
  ('اَلْكافِرُ شَرِسُ الخَليقَةِ، سَـيِّيءُ الطَّريقَةِ.', 'The disbeliever is ill-tempered and has an evil manner.', 'Ghurar al-Hikam, The disbeliever- §4', 'wisdom'),
  ('اَلْكافِرُ خَبٌّ، ضَبٌّ، جاف، خائِنٌ.', 'The disbeliever is a misguiding deceiver, hard-hearted, [and] perfidious.', 'Ghurar al-Hikam, The disbeliever- §5', 'wisdom'),
  ('غايَةُ الكافِرِ النّارُ.', 'The final end of the disbeliever is hellfire.', 'Ghurar al-Hikam, The disbeliever- §6', 'wisdom'),
  ('ما كَفَرَ الكافِرُ حَتّى جَهِلَ.', 'The disbeliever did not disbelieve until he became ignorant.', 'Ghurar al-Hikam, The disbeliever- §7', 'wisdom'),
  ('هَمُّ الكافِرِ لِدُنْياهُ، وسَعْيُهُ لِعاجِلَتِهِ، وغايَتُهُ شَهْوَتُهُ.', 'The concern of the disbeliever is for his [life in this] world, his efforts are for the transient [pleasures] and his goal is [fulfilling] his lust.', 'Ghurar al-Hikam, The disbeliever- §8', 'wisdom'),
  ('اَلْكُفْرُ خِذْلانٌ.', 'Disbelief is disappointment [and failure].', 'Ghurar al-Hikam, Disbelief- §1', 'wisdom'),
  ('ضادُّوا الكُفْرَ بِالإيمانِ.', 'Counter disbelief with faith.', 'Ghurar al-Hikam, Disbelief- §2', 'wisdom'),
  ('اَلكُفْرُ مَغْرَمٌ.', 'Disbelief is loss.', 'Ghurar al-Hikam, Disbelief- §3', 'wisdom'),
  ('اَلْكَفُّ عَمّا في أيْدِي النّاسِ أحَدُ السَّخائَيْنِ.', 'Restraining yourself from that which others possess is one of the two generosities.', 'Ghurar al-Hikam, Restraint- §1', 'wisdom'),
  ('إنَّ الكَفَّ عِنْدَ حَيْرَةِ الضَّلالِ خَيْرٌ مِنْ رُكُوبِ الأهْوالِ.', 'Verily restraint during the confusion of misguidance is better than embarking on terrors.', 'Ghurar al-Hikam, Restraint- §3', 'wisdom'),
  ('لاوَرَعَ كَالكَفِّ.', 'There is no piety like self-restraint.', 'Ghurar al-Hikam, Restraint- §4', 'wisdom'),
  ('اَلرِّضا بِالكَفافِ خَيْرٌ مِنَ السَّعْيِ فِي الإسْرافِ.', 'Being pleased with what is sufficient is better than striving for lavishness.', 'Ghurar al-Hikam, Sufficiency- §1', 'wisdom'),
  ('اَلرِّضا بِالكَفافِ يُؤَدّي إلَى العَفافِ.', 'Being pleased with what suffices leads to virtue.', 'Ghurar al-Hikam, Sufficiency- §2', 'wisdom'),
  ('طُوبى لِمَنْ تَحَلّى بِالعَفافِ ورَضِيَ بِالكَفافِ.', 'Blessed is the one who adorns himself with virtue and is satisfied with what suffices.', 'Ghurar al-Hikam, Sufficiency- §3', 'wisdom'),
  ('مَنِ اقْتَنَعَ بِالكَفافِ أدّاهُ إلَى العَفافِ.', 'One who is content with that which suffices is led by it towards virtue.', 'Ghurar al-Hikam, Sufficiency- §4', 'wisdom'),
  ('مَنِ اقْتَصَرَ عَلَى الكَفافِ تَعَجَّلَ الرّاحَةَ وتَـبَوَّءَ خَفْضَ الدَّعَةِ.', 'One who limits himself to what suffices hastens comfort and lives in an abode of ease.', 'Ghurar al-Hikam, Sufficiency- §5', 'wisdom'),
  ('لا غِنى بِأحَد مِنَ الاِرْتيادِ، وقَدْرِ بَلاغِهِ مِنَ الزّادِ.', 'No one can dispense with the need to seek his sustenance and that which he requires of provisions.', 'Ghurar al-Hikam, Sufficiency- §6', 'wisdom'),
  ('أطِلْ يَدَكَ في مُكافاةِ مَنْ أحْسَنَ إلَيْكَ، فَإنْ لَمْ تَقْدِرْ فَلا أقَلَّ مِنْ أنْ تَشْكُرَهُ.', 'Extend your hand in recompense to the one who has done good to you, and if you are unable [to do this] then the very least you should do is thank him.', 'Ghurar al-Hikam, Recompense- §1', 'wisdom'),
  ('اَلمُكافاةُ عِتْقٌ.', 'Recompense is liberation.', 'Ghurar al-Hikam, Recompense- §2', 'wisdom'),
  ('مَنْ هَمَّ أنْ يُكافِيَ عَلى مَعْرُوف فَقَدْ كافى.', 'One who endeavours to recompense the good that is done to him has indeed recompensed it.', 'Ghurar al-Hikam, Recompense- §3', 'wisdom'),
  ('مَنْ لَمْ يُجازِ الإساءَةَ بِالإحْسانِ فَلَيْسَ مِنَ الكِرامِ.', 'One who does not recompense offence with favour is not from the noble-minded ones.', 'Ghurar al-Hikam, Recompense- §4', 'wisdom'),
  ('مِنْ كَمالِ الإيمانِ مُكافاةُ المُسيءِ بِالإحْسانِ.', 'Recompensing the wrongdoer with favour is from the perfection of faith.', 'Ghurar al-Hikam, Recompense- §5', 'wisdom'),
  ('أشَدُّ النّاسِ عُقُوبَةً رَجُلٌ كافَئَ الإحْسانَ بِالإساءَةِ.', 'The most severely punished of all people is one who recompenses good with evil.', 'Ghurar al-Hikam, Recompense- §6', 'wisdom'),
  ('إذا قَصُرَتْ يَدُكَ عَنِ المُكافاةِ فَأطِلْ لِسانَكَ بِالشُّكْرِ.', 'When your hand is short and unable to recompense [the one who does good to you] then lengthen your speech with gratitude.', 'Ghurar al-Hikam, Recompense- §7', 'wisdom'),
  ('رُدَّ الحَجَرَ مِنْ حَيثُ جاءَكَ، فَإنَّهُ لايُرَدُّ الشَّرُّ إلاّ بِالشَّرِّ.', 'Return the stone from whence it came to you, for indeed evil is not repulsed except by evil.', 'Ghurar al-Hikam, Recompense- §8', 'wisdom'),
  ('مَنْ حَسُنَتْ كِفايَتُهُ أحَبَّهُ سُلْطانُهُ.', 'One whose competence is good is loved by his sovereign.', 'Ghurar al-Hikam, Competence- §1', 'wisdom'),
  ('مَنْ رُفِعَ بِلا كِفايَة وُضِعَ بِلا جِنايَة.', 'One who is raised [to a high rank] without competence is dropped without wrongdoing.', 'Ghurar al-Hikam, Competence- §2', 'wisdom'),
  ('مَنْ أحْسَنَ الكِفايَةَ اِسْتَحَقَّ الوِلايَةَ.', 'One whose competence is good deserves [to be given] authority.', 'Ghurar al-Hikam, Competence- §3', 'wisdom'),
  ('مَنْ كَلَّفَكَ ما لاتُطيقُ فَقَدْ أفْتاكَ في عِصْيانِهِ.', 'One who imposes upon you a duty that you are unable to bear has indeed asked you to disobey him.', 'Ghurar al-Hikam, Duty- §1', 'wisdom'),
  ('اَلتَّكَلُّفُ مِنْ أخْلاقِ المُنافِقينَ.', 'Affectation is from the morals of the hypocrites.', 'Ghurar al-Hikam, Duty- §2', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ أمَرَ عِبادَهُ تَخْييراً، وَنَهاهُمْ تَحْذيراً، وكَلَّفَ يَسيراً، ولَمْ يُكَلِّفْ عَسيراً، وأعْطَى عَلىَ القَليلِ كَثيراً، ولَمْ يُعْصَ مَغْلُوباً، ولَمْ يُطَعْ مُكْرَهاً،وَ لَمْ يُرْسِلِ الأنْبِياءَ لَعِباً، ولَمْ يُنْزِلِ الكِتابَ عَبَثاً، وما خَلَقَ السَّماواتِ والأرْضَ وما بَيْنَهُما باطِلاً، ذلِكَ ظَنُّ الَّذينَ كَفَرُوا فَوَيْلٌ لِلَّذينَ كَفَرُوا مِنَ النّارِِ.', 'Verily Allah, the Glorified, commanded His servants by choice and forbade them by warning. He made duties easy and did not impose difficult duties. For a little He gave plenty. He is not disobeyed out of defeat nor is He obeyed by force. He did not send prophets for sport, nor did He reveal the Book to the creation for amusement. He did not create the Heavens and the earth in vain: That is a conjecture of the faithless. So woe to the faithless for the Fire.', 'Ghurar al-Hikam, Duty- §3', 'wisdom'),
  ('لِلْمُتَكَلِّمِ أوْقاتٌ.', 'For every speaker there are times [and conditions where he is able to speak].', 'Ghurar al-Hikam, The speaker- §1', 'wisdom'),
  ('لَقَدْ طِرْتَ شَكيراً، وَهَدَرْتَ صَقْباً(سَقْباً).', 'You have started flying while still a nestling and growling before coming of age.', 'Ghurar al-Hikam, The speaker- §2', 'wisdom'),
  ('اَلْكامِلُ مَنْ غَلَبَ جِدُّهُ هَزْلَهُ.', 'The ideal [person] is one whose seriousness prevails over his jesting [and frivolity].', 'Ghurar al-Hikam, The ideal one- §1', 'wisdom'),
  ('اَلْكَمالُ في ثَلاث، اَلصَّبْرُ عَلَى النَّوائِبِ، والتَّوَرُّعُ فِي المَطالِبِ، وَإسْعافُ الطّالِبِ.', 'Perfection is in three things: Patience in calamities, piety in pursuits and fulfilling the needs of the seeker.', 'Ghurar al-Hikam, Perfection- §1', 'wisdom'),
  ('اَلْكَمالُ فِي الدُّنيا مَفْقُودٌ.', 'Perfection [of what is desired] is non-existent in this world.', 'Ghurar al-Hikam, Perfection- §2', 'wisdom'),
  ('لَنْ تُدْرِكَ الكَمالَ حَتّى تَرْقى عَنِ النَّقْصِ.', 'You will never attain perfection until you rise above imperfection.', 'Ghurar al-Hikam, Perfection- §3', 'wisdom'),
  ('مِنْ كَمالِ الإنْسانِ ووُفُورِ فَضْلِهِ اِسْتِشْعارُهُ بِنَفْسِهِ النُّقْصانَ.', 'From the perfection of a human being and the abundance of his merit is his own feeling of imperfection [in himself].', 'Ghurar al-Hikam, Perfection- §4', 'wisdom'),
  ('مَنْ لَمْ يَتَحَرَّزْ مِنَ المَكائِدِ، قَبْلَ وُقُوعِها لَمْ يَنْفَعْهُ الأسَفُ بَعْدَ هُجُومِها.', 'One who is not cautious of [evil] plots before they occur, does not benefit from regret after their assault.', 'Ghurar al-Hikam, Plots- §1', 'wisdom'),
  ('اَلْكَيِّسُ أصْلُهُ عَقْلُهُ، ومُرُوءَتُهُ خُلْقُهُ،وَ دينُهُ حَسَبُهُ.', 'The foundation of a sagacious person is his intellect, his magnanimity is his character and his religion is his distinction.', 'Ghurar al-Hikam, The sagacious- §1', 'wisdom'),
  ('اَلْكَيِّسُ مَنْ كانَ يَوْمُهُ خَيْراً مِنْ أمْسِهِ،وَعَقَلَ الذَمَّ عَنْ نَفْسِهِ.', 'The sagacious person is one whose today is better than his yesterday and [one who] keeps blame away from himself [by not doing anything blameworthy].', 'Ghurar al-Hikam, The sagacious- §2', 'wisdom'),
  ('اَلْكَيِّسُ مَنْ أحْيا فَضائِلَهُ، وأماتَ رَذائِلَهُ بِقَمْعِهِ شَهْوَتَهُ وَهَواهُ.', 'The sagacious person is one who enlivens his virtues and kills off his vices by subduing his lust and his vain desires.', 'Ghurar al-Hikam, The sagacious- §3', 'wisdom'),
  ('اَلْكَيِّسُ مَنْ كانَ غافِلاً عَنْ غَيْرِهِ ولِنَفْسِهِ كَثيرِ التَّقاضي.', 'The sagacious person is one who is inattentive towards others while expecting much from [and constantly judging] himself.', 'Ghurar al-Hikam, The sagacious- §4', 'wisdom'),
  ('اَلْكَيِّسُ مَنْ مَلَكَ عِنانَ شَهْوَتِهِ.', 'The sagacious person is one who controls the reins of his lustful desires.', 'Ghurar al-Hikam, The sagacious- §5', 'wisdom'),
  ('اَلْكَيِّسُ مَنْ تَجَلْبَبَ الحَياءَ، وادَّرَعَ الحِلْمَ.', 'The sagacious person is one who dons the garment of modesty and the armour of forbearance.', 'Ghurar al-Hikam, The sagacious- §6', 'wisdom'),
  ('أكْيَسُ الأكْياسِ مَنْ مَقَتَ دُنْياهُ، وقَطَعَ مِنْها أمَلَهُ ومُناهُ، وصَرَفَ عَنْها طَمَعَهُ وَرَجاهُ.', 'The most sagacious person of all is one who loathes this world, cuts off his hope and aspiration from it, and turns his desire and expectation away from it.', 'Ghurar al-Hikam, The sagacious- §7', 'wisdom'),
  ('إنَّ الأكْياسَ هُمُ الَّذينَ لِلدُّنْيا مَقَتُوا، وأعْيُنَهُمْ عَنْ زَهْرَتِها أغْمَضُوا، وَقُلُوبَهُمْ عَنْها صَرَفُوا، وبِالدّارِ الباقِيَةِ تَوَلَّهُوا.', 'Verily the sagacious people are those who have loathing for this world and lower their eyes from its splendour; they turn their hearts away from it and yearn passionately for the everlasting abode.', 'Ghurar al-Hikam, The sagacious- §8', 'wisdom'),
  ('إنَّ الكَيِّسَ مَنْ كانَ لِشَهْوَتِهِ مانِعاً، ولِنَزْوَتِهِ عِنْدَ الحَفيظَةِ واقِماً قامِعاً.', 'Verily the sagacious person is one who restrains his lustful desire and subdues his outburst in times of anger by quelling it.', 'Ghurar al-Hikam, The sagacious- §9', 'wisdom'),
  ('اَلْكَيِّسُ صَديقُهُ الحَقُّ وعَدُوُّهُ الباطِلُ.', 'The sagacious person’s friend is truth and his enemy is falsehood.', 'Ghurar al-Hikam, The sagacious- §10', 'wisdom'),
  ('لاإلهَ إلاّ اللّهُ عَزيمَةُ الإيمانِ، وفاتِحَةُ الإحْسانِ، ومَرْضاةُ الرَّحْمنِ، وَمَدْحَرَةُ الشَّيْطانِ.', '‘There is no God but Allah’ is the declaration of faith, the first step towards good deeds and acquiring the pleasure of the Most Merciful, and a means of repelling Satan.', 'Ghurar al-Hikam, There is no God but Allah- §1', 'wisdom'),
  ('اَللُّؤْمُ إيثارُ حُبِّ المالِ عَلى لَذَّةِ الحَمْدِ والثَّناءِ.', 'Vileness is preferring the love of wealth over the delight of praise and commendation.', 'Ghurar al-Hikam, Vileness- §1', 'wisdom'),
  ('اَللُّؤْمُ مُضادٌّ لِسائِرِ الفَضائِل، وجامِعٌ لِجَميعِ الرَّذائِلِ والسَّوْءاتِ وَالدَّنايا.', 'Vileness is the opposite of all the virtues and the combination of all the vices, evils and lowly traits.', 'Ghurar al-Hikam, Vileness- §2', 'wisdom'),
  ('أعْظَمُ اللُّؤْمِ، حَمْدُ المَذْمُومِ.', 'The greatest vileness is praising the blameworthy.', 'Ghurar al-Hikam, Vileness- §3', 'wisdom'),
  ('اَللُّؤْمُ أُسُّ الشَّرِّ.', 'Vileness is the foundation of evil.', 'Ghurar al-Hikam, Vileness- §4', 'wisdom'),
  ('اَللُّؤْمُ جَمّاعُ المَذامِّ.', 'Vileness is the accumulator of dispraise.', 'Ghurar al-Hikam, Vileness- §5', 'wisdom'),
  ('اَللُّؤْمُ يُوجِبُ الغِشَّ.', 'Vileness necessitates deceit.', 'Ghurar al-Hikam, Vileness- §6', 'wisdom'),
  ('اَللُّؤْمُ إيثارُ المالِ عَلَى الرِّجالِ.', 'Vileness is preferring wealth over people.', 'Ghurar al-Hikam, Vileness- §7', 'wisdom'),
  ('اَللُّؤْمُ قَبيحٌ فَلا تَجْعَلْهُ لُبْسَكَ.', 'Vileness is ugly so do not make it your attire.', 'Ghurar al-Hikam, Vileness- §8', 'wisdom'),
  ('مِنْ عَلاماتِ اللُّؤْمِ تَعْجيلُ العُقُوبَةِ.', 'Hastening punishment is one of the signs of vileness.', 'Ghurar al-Hikam, Vileness- §9', 'wisdom'),
  ('مِنْ عَلاماتِ اللُّؤْمِ الغَدْرُ بِالمَواثيقِ.', 'Betraying [one’s] agreements is one of the signs of vileness.', 'Ghurar al-Hikam, Vileness- §10', 'wisdom'),
  ('اَللَّئِيمُ إذا بَلَغَ فَوْقَ مِقْدارِهِ تَنَكَّرَتْ أحْوالُهُ.', 'When the vile one attains a position above his status, his condition changes [for the worse].', 'Ghurar al-Hikam, The vile- §1', 'wisdom'),
  ('اَللَّئِيمُ يَجْفُو إذَا اسْتُعْطِفَ، وَيَلينُ إذا عُنِّفَ.', 'The vile one is harsh when he is approached entreatingly and becomes soft when he is berated.', 'Ghurar al-Hikam, The vile- §2', 'wisdom'),
  ('اَللَّئِيمُ لايَتْبَعُ إلاّ شَكْلَهُ، ولايَميلُ إلاّ إلى مِثْلِهِ.', 'The vile person does not follow anyone except the one who is like him and he does not incline towards anyone but the one who is similar to him.', 'Ghurar al-Hikam, The vile- §3', 'wisdom'),
  ('اَللَّئِيمُ لايُرْجى خَيْرُهُ، ولايُسْلَمُ مِنْ شَرِّهِ، ولايُؤْمَنُ مِنْ غَوائِلِهِ.', 'No good is expected from a vile person, and no one is safe from his evil and secure from his ills.', 'Ghurar al-Hikam, The vile- §4', 'wisdom'),
  ('اَللَّئِيمُ يُدْرِعُ العارَ، ويُؤْذِي الأحْرارَ.', 'The vile one dons the attire of dishonour and harms the freemen.', 'Ghurar al-Hikam, The vile- §5', 'wisdom'),
  ('اَللَّئِيمُ يَرى سَوالِفَ إحْسانِهِ دَيْناً لَهُ يَقْتَضيهِ.', 'The vile one considers his favours as debts that he will demand repayment for [in the future].', 'Ghurar al-Hikam, The vile- §6', 'wisdom'),
  ('اَللَّئِيمُ إذَا احْتاجَ إلَيْكَ أجفاكَ، وإذَا احْتَجْتَ إلَيْهِ عَنّاكَ.', 'The vile one is such that when he needs you he puts you in difficulty, and when you need him he torments you.', 'Ghurar al-Hikam, The vile- §7', 'wisdom'),
  ('اِحْذَرِ اللَّئِيمَ إذا أكْرَمْتَهُ، وَالرَّذْلَ إذا قَدَّمْتَهُ، والسِّفْلَةَ إذا رَفَعْتَهُ.', 'Be cautious of the vile one when you honour him, and the depraved one when you bring him forward, and the lowly one when you raise him.', 'Ghurar al-Hikam, The vile- §8', 'wisdom'),
  ('اَللَّئِيْمُ يُعْلي هِمَّتَهُ فيما جُنِيَ عَلَيْهِ مِنْ طَلَبِ سُوءِ المُكافاةِ.', 'The vile one spares no effort in seeking evil vengeance for the wrong that has been done to him.', 'Ghurar al-Hikam, The vile- §9', 'wisdom'),
  ('إيّاكَ أنْ تَعْتَمِدَ عَلَى اللَّئْيمِ، فَإنَّهُ يَخْذُلُ مَنِ اعْتَمَدَ عَلَيْهِ.', 'Beware of depending on the vile one, for indeed he forsakes the one who depends on him.', 'Ghurar al-Hikam, The vile- §10', 'wisdom'),
  ('ما بَعْدَ التَّبْيينِ إلاّ اللَّبْسُ.', 'There is nothing after clarification but confusion.', 'Ghurar al-Hikam, Confusion- §1', 'wisdom'),
  ('اَللَّبَنُ أحَدُ اللَّحْمَيْنِ.', 'Milk is one of the two meats.', 'Ghurar al-Hikam, Milk- §1', 'wisdom'),
  ('اَللَّجُوجُ لارَأْيَ لَهُ.', 'The stubborn one has no [valid] opinion.', 'Ghurar al-Hikam, The stubborn- §1', 'wisdom'),
  ('لَيْسَ لِلَجُوج تَدْبيرٌ.', 'The stubborn one has no planning.', 'Ghurar al-Hikam, The stubborn- §2', 'wisdom'),
  ('لاتُمارِيَنَّ اللَّجُوجَ في مَحْفِل.', 'Never argue with a stubborn person in a gathering.', 'Ghurar al-Hikam, The stubborn- §3', 'wisdom'),
  ('لارَأْيَ لِلَجُوج.', 'A stubborn person has no [valid] opinion.', 'Ghurar al-Hikam, The stubborn- §4', 'wisdom'),
  ('اَللَّجاجُ يَكْبُو بِراكِبِهِ.', 'Stubbornness causes its rider to stumble.', 'Ghurar al-Hikam, Stubbornness- §1', 'wisdom'),
  ('اَللَّجاجُ يُنْتِجُ الحُرُوبَ، ويُوغِرُ القُلُوبَ.', 'Stubbornness gives rise to hostilities and kindles rancour in the hearts.', 'Ghurar al-Hikam, Stubbornness- §2', 'wisdom'),
  ('اَللَّجاجُ أكْثَرُ (أكْبَرُ) الأشْياءِ مَضَرَّةً فِي العاجِلِ والآجِلِ.', 'Stubbornness is the most harmful of all things in this life and the next.', 'Ghurar al-Hikam, Stubbornness- §3', 'wisdom'),
  ('إيّاكَ ومَذْمُومَ اللَّجاجِ، فَإنَّهُ يُثيرُ الحُرُوبَ.', 'Beware of blameworthy stubbornness, for indeed it provokes hostilities.', 'Ghurar al-Hikam, Stubbornness- §4', 'wisdom'),
  ('اَللَّجاجُ يَشينُ النَّفْسَ.', 'Stubbornness tarnishes the soul.', 'Ghurar al-Hikam, Stubbornness- §7', 'wisdom'),
  ('اَللَّجاجُ يَنْبُو بِراكِبِهِ.', 'Stubbornness causes its rider to fall off.', 'Ghurar al-Hikam, Stubbornness- §9', 'wisdom'),
  ('اَللَّجاجُ عُنْوانُ العَطَبِ.', 'Stubbornness is the symbol of destruction [and ruin].', 'Ghurar al-Hikam, Stubbornness- §10', 'wisdom'),
  ('اَللَّجاجُ يَعْقِبُ الضُّرَّ.', 'Stubbornness is followed by detriment.', 'Ghurar al-Hikam, Stubbornness- §11', 'wisdom'),
  ('اَللَّجاجُ يُفْسِدُ الرَّأْيَ.', 'Stubbornness corrupts opinion.', 'Ghurar al-Hikam, Stubbornness- §12', 'wisdom'),
  ('اَللَّجاجَةُ تُورِثُ مالَيْسَ لِلْمَرْءِ إلَيْهِ حاجَةٌ.', 'Stubbornness brings to a person that which he is not in need of.', 'Ghurar al-Hikam, Stubbornness- §13', 'wisdom'),
  ('اَلاْلْحاحُ داعِيَةُ الحِرْمانِ.', 'Importunity is an inviter of deprivation.', 'Ghurar al-Hikam, Importunity- §1', 'wisdom'),
  ('كَفى بِالإلْحاحِ مَحْرَمَةً.', 'Importunity is enough as a [reason for] deprivation.', 'Ghurar al-Hikam, Importunity- §2', 'wisdom'),
  ('كَثْرَةُ الإلْحاحِ تُوجِبُ المَنْعَ.', 'Excessive importunity leads to refusal.', 'Ghurar al-Hikam, Importunity- §3', 'wisdom'),
  ('كَثْرَةُ إلْحاحِ الرَّجُلِ تُوجِبُ حِرْمانَهُ.', 'The excessive importunity of a man leads to his deprivation.', 'Ghurar al-Hikam, Importunity- §4', 'wisdom'),
  ('مَنْ كَثُرَ إلْحاحُهُ حُرِمَ.', 'One whose importunity increases gets deprived.', 'Ghurar al-Hikam, Importunity- §5', 'wisdom'),
  ('مَنْ ألَحَّ فِي السُّؤالِ أبْرَمَ.', 'One who is importunate in asking irritates [people].', 'Ghurar al-Hikam, Importunity- §6', 'wisdom'),
  ('مَنْ ألَحَّ فِي السُّؤالِ حُرِمَ.', 'One who is importunate in asking gets deprived.', 'Ghurar al-Hikam, Importunity- §7', 'wisdom'),
  ('مَنْ ألَحَّ في سُؤالِهِ دَعا إلى حِرْمانِهِ.', 'One who is importunate in his asking invites his own deprivation.', 'Ghurar al-Hikam, Importunity- §8', 'wisdom'),
  ('مَنْ عَرَفَ الأيّامَ لَمْ يَغْفُلْ عَنِ الاِسْتِعْدادِ.', 'One who understands the times [in which he lives] does not neglect to prepare [for what is to come].', 'Ghurar al-Hikam, Important events- §1', 'wisdom'),
  ('مَنْ أقْعَدَتْهُ نِكايَةُ الأيّامِ أقامَتْهُ مَعُونَةُ الكِرامِ.', 'One who is crippled by the hardship of the times is raised by the assistance of the noble-minded ones.', 'Ghurar al-Hikam, Important events- §2', 'wisdom'),
  ('ما أسْرَعَ السّاعاتِ فيِ الأيّامِ وأسْرَعَ الأيّامَ فيِ الشُّهُورِ وأسْرَعَ الشُّهُورَ فِي السَّنَةِ وأسْرَعَ السَّنَةَ فِي العُمْرِ.', 'How quick the hours pass in the day and how fast the days pass in the month and how quick the months pass in the year and how fast the years pass in the lifetime!', 'Ghurar al-Hikam, Important events- §3', 'wisdom'),
  ('اَلأيّامُ صَحائِفُ آجالِكُمْ فَخَلِّدُوها (فَجَلِّدُوها) أحْسَنَ أعْمالِكُمْ.', 'Days are the pages of your lifetime so eternize [or bind] them with your best deeds.', 'Ghurar al-Hikam, Important events- §4', 'wisdom'),
  ('اَلسّاعاتُ مُكْمَنُ الآفاتِ.', 'Hours are the lurking place of banes.', 'Ghurar al-Hikam, Important events- §5', 'wisdom'),
  ('السّاعاتُ تَنْهَبُ الأعْمارَ (الآجالَ)،.', 'Hours plunder lifetimes.', 'Ghurar al-Hikam, Important events- §6', 'wisdom'),
  ('اَلأيّامُ تُفيدُ التَّجارِبَ.', 'The passing of days brings the benefit of experiences.', 'Ghurar al-Hikam, Important events- §7', 'wisdom'),
  ('اَلسّاعاتُ تُنَقِّصُ الأعْمارَ.', 'Hours diminish lifetimes.', 'Ghurar al-Hikam, Important events- §8', 'wisdom'),
  ('اَلأيّامُ تُوضِحُ السَّرائِرَ الكامِنَةَ.', 'The passing of days reveals the hidden secrets.', 'Ghurar al-Hikam, Important events- §9', 'wisdom'),
  ('إنَّما أنْتَ عَدَدُ أيّام فَكُلُّ يَوْم يَمْضي عَلَيْكَ يَمْضي بِبَعْضِكَ، فَخَفِّضْ فيِ الطَّلَبِ، وأجْمِلْ فِي المُكْتَسَبِ.', 'Verily you are only [the sum total of] a fixed number of days, and every day that passes you by takes a piece of you with it, so reduce your desires and be moderate in your earning.', 'Ghurar al-Hikam, Important events- §10', 'wisdom'),
  ('مَنْ لاحَى الرِّجالَ كَثُرَ أعْدائُهُ.', 'Whoever insults [and disputes with] the people, his enemies increase.', 'Ghurar al-Hikam, Insults- §1', 'wisdom'),
  ('اَللَّذَّةُ تُلْهي.', 'Pleasure distracts.', 'Ghurar al-Hikam, Pleasure and delight- §1', 'wisdom'),
  ('اَللَّذّاتُ مُفْسِداتٌ.', 'Pleasures are corrupters.', 'Ghurar al-Hikam, Pleasure and delight- §2', 'wisdom'),
  ('اَللَّذّاتُ آفاتٌ.', 'Pleasures are woes.', 'Ghurar al-Hikam, Pleasure and delight- §3', 'wisdom'),
  ('رَأْسُ الآفاتِ الوَلَهُ بِاللَّذّاتِ.', 'The root of [all] woes is being distracted by [worldly] pleasures.', 'Ghurar al-Hikam, Pleasure and delight- §4', 'wisdom'),
  ('رُبَّ لَذَّة فيها الحِمامُ.', 'Many a pleasure has death [hidden] in it.', 'Ghurar al-Hikam, Pleasure and delight- §5', 'wisdom'),
  ('قَلَّ مَنْ غَرِىَ بِاللَّذّاتِ إلاّ كانَ بِها هَلاكُهُ.', 'Few are those who are enticed by pleasures but that their destruction is caused by it.', 'Ghurar al-Hikam, Pleasure and delight- §6', 'wisdom'),
  ('كَمْ مِنْ لَذَّة دَنِيَّة مَـنَعَتْ سَنِيَّ دَرَجات.', 'How many a vile pleasure has prevented one from [attaining] lofty stations.', 'Ghurar al-Hikam, Pleasure and delight- §7', 'wisdom'),
  ('مَا الْتَذَّ أحَدٌمِنَ الدُّنْيا لَذَّةً إلاّ كانَتْ لَهُ يَوْمَ القِيمَةِ غُصَّةً.', 'Nobody delights in any of the pleasures of this world but that it will be a distress for him on the Day of Resurrection.', 'Ghurar al-Hikam, Pleasure and delight- §8', 'wisdom'),
  ('لاخَيْرَ في لَذَّة لاتَبْقى.', 'There is no good in a pleasure that does not last.', 'Ghurar al-Hikam, Pleasure and delight- §9', 'wisdom'),
  ('لالَذَّةَ في شَهْوَة فانِيَة.', 'There is no pleasure in transient desires.', 'Ghurar al-Hikam, Pleasure and delight- §10', 'wisdom'),
  ('اَللِّسانُ مِعْيارٌ أرْجَحَهُ العَقْلُ، وأطاشَهُ الجَهْلُ.', 'The tongue is a gauge that is given weight by the intellect and made light by ignorance.', 'Ghurar al-Hikam, The tongue- §1', 'wisdom'),
  ('أُخْزُنْ لِسانَكَ، كَما تَخْزُنُ ذَهَبَكَ ووَرِقَكَ.', 'Safeguard your tongue just as you treasure your gold and your money.', 'Ghurar al-Hikam, The tongue- §2', 'wisdom'),
  ('اِحْفَظْ رَأسَكَ مِنْ عَثْرَةِ لِسانِكَ، وازْمُمْهُ بِالنُّهى والحَزْمِ، والتُّقى، وَالعَقْلِ.', 'Protect your head from the slips of your tongue, and constrain it with reason, judiciousness, God-wariness and intellect.', 'Ghurar al-Hikam, The tongue- §3', 'wisdom'),
  ('اِحْبِسْ لِسانَكَ قَبْلَ أنْ يُطيلَ حَبْسَكَ، ويُرْديَ نَفْسَكَ، فَلا شَيْءَ أوْلى بِطُولِ سِجْن مِنْ لِسان يَعْدِلُ عَنِ الصَّوابِ، ويَتَسَرَّعُ إلَى الجَوابِ.', 'Restrain your tongue before it prolongs your incarceration and destroys your soul, for there is nothing more worthy of long imprisonment than a tongue that has strayed from the right and is hasty in responding.', 'Ghurar al-Hikam, The tongue- §4', 'wisdom'),
  ('اِحْذَرُوا اللِّسانَ فَإنَّهُ سَهْمٌ يُخْطي.', 'Be cautious of the tongue for indeed it is an arrow that can miss its mark.', 'Ghurar al-Hikam, The tongue- §5', 'wisdom'),
  ('إيّاكَ أنْ تَجْعَلَ مَرْكَبَكَ لِسانَكَ في غَيْبَةِ إخْوانِكَ، أوْ تَقُولَ ما يَصيرُ عَلَيْكَ حُجَّةً، وفِي الإسائَةِ إلَيْك َ عِلَّةً.', 'Beware of making your tongue a medium for slandering your brothers, or of saying that which will become proof against you and a reason for harming you.', 'Ghurar al-Hikam, The tongue- §6', 'wisdom'),
  ('ألا وإنَّ اللِّسانَ بَضْعَةٌ مِنَ الإنْسانِ، فَلا يُسْعِدُهُ القَوْلُ إذَا امْتَنَعَ، وَلايُمْهِلُهُ النُّطْقُ إذَا اتَّسَعَ.', 'Know that the tongue is a part of a person’s body, so when he desists, speech will not assist him and when he opens up [and is ready to speak], speech will not give him time to pause.', 'Ghurar al-Hikam, The tongue- §7', 'wisdom'),
  ('ألا وَإنَّ اللِّسانَ الصّادِقَ يَجْعَلُهُ اللّهُ لِلْمَرْءِ فِي النّاسِ خَيْرٌ مِنَ المالِ يُورِثُهُ مَنْ لايَحْمَدُهُ.', 'Now surely the good repute of a man that is preserved for him by Allah among the people is better than the wealth that is inherited by those who do not praise him.', 'Ghurar al-Hikam, The tongue- §8', 'wisdom'),
  ('إنَّ لِسانَكَ يَقْتَضيكَ ما عَوَّدْتَهُ.', 'Verily your tongue demands from you that which you have made it accustomed to.', 'Ghurar al-Hikam, The tongue- §9', 'wisdom'),
  ('اَللِّسانُ تَرْجُمانُ الجَنانِ.', 'The tongue is the interpreter of the heart.', 'Ghurar al-Hikam, The tongue- §10', 'wisdom'),
  ('مَنْ كُنْتَ سَبَباً لَهُ في بَلائِهِ، وَجَبَ عَلَيْكَ التَّلَطُّفُ في عَلاجِ دائِهِ.', 'When you are the cause of someone’s affliction, it is obligatory upon you to show courtesy [and kindness] in trying to remedy his affliction.', 'Ghurar al-Hikam, Courteousness- §1', 'wisdom'),
  ('رُبَّ لَغْو يَجْلُبُ شَرّاً.', 'Many a vain talk results in evil [action].', 'Ghurar al-Hikam, Vain talk- §1', 'wisdom'),
  ('حُسْنُ اللِّقاءِ يَزيدُ في تَأَكُّدِ الإخاءِ.', 'Good meetings strengthen the bond of brotherhood.', 'Ghurar al-Hikam, Meeting- §1', 'wisdom'),
  ('حُسْنُ المَلْقاءِ (اللِّقاءِ) أحَدُ النُّجْحَيْنِ.', 'Good encounters (or meetings) are one of the two successes.', 'Ghurar al-Hikam, Meeting- §2', 'wisdom'),
  ('مَنْ أحَبَّ لِقاءَ اللّهِ سُبْحانَهُ سَلا عَنِ الدُّنْيا.', 'One who loves to meet Allah, the Glorified, forgets this world.', 'Ghurar al-Hikam, Meeting Allah- §1', 'wisdom'),
  ('مَنِ اكْتَفى بِالتَّلْويحِ اِسْتَغْنى عَنِ التَّصْريحِ.', 'One who settles for hinting [and indirect reference] becomes needless of declaration.', 'Ghurar al-Hikam, Hinting- §1', 'wisdom'),
  ('اَلاِفْراطُ فِي المَلامَةِ يَشُبُّ نارَ اللَّجاجَةِ.', 'Excessiveness in reproach ignites the fire of obstinacy.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §1', 'wisdom'),
  ('أهْوَنُ شَيْء لائِمَةُ الجُهّالِ.', 'The easiest thing is censuring the ignorant ones.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §2', 'wisdom'),
  ('إذا ذَمَمْتَ فَاقْتَصِرْ.', 'When you [have to] censure [someone], make it short.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §3', 'wisdom'),
  ('رُبَّ مَلُوم ولاذَنْبَ لَهُ.', 'Many a person who is reproached has done nothing wrong.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §4', 'wisdom'),
  ('عِنْدَ كَثْرَةِ العِثارِ والزَّلَلِ تَكْثُرُ المَلامَةُ.', 'When slips and errors increase, reproach increases.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §5', 'wisdom'),
  ('قَدْ يَنْجَعُ المَلامُ.', 'Blame may at times be beneficial.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §6', 'wisdom'),
  ('اَلتَّقْريعُ أحَدُ العُقُوبَتَيْنِ.', 'Reproof is one of the two punishments.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §7', 'wisdom'),
  ('إعادَةُ التَّقْريعِ أشَدُّ مِنْ مَضَضِ الضَّرْبِ.', 'Repetition of [the] reprimand is more severe than the pain of a beating.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §8', 'wisdom'),
  ('كَثْرَةُ التَّقْـريعِ تُوغِرُ القُلُوبَ، وتُوحِشُ الأصْحابَ.', 'Too much reproof instils hatred in the hearts and alienates the companions.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §9', 'wisdom'),
  ('مَنْ كَثُرَ لَوْمُهُ كَثُرَ عارُهُ.', 'One whose reproach increases, his disgrace increases.', 'Ghurar al-Hikam, Reproach, reprimand and censure- §10', 'wisdom'),
  ('اَللَّهْوُ يُفْسِدُ عَزائِمَ الجِدِّ.', 'Amusement corrupts serious resolutions.', 'Ghurar al-Hikam, Amusement- §1', 'wisdom'),
  ('أُهْجُرِ اللَّهْوَ فَإنَّكَ لَمْ تُخْلَقْ عَبَثاً فَتَلْهُوَ،وَ لَمْ تُتْرَكْ سُدىً فَتَلْغُوَ.', 'Keep away from amusements for indeed you have not been created aimlessly so that you may be amused, and you have not been left without purpose so that you may indulge in vanities.', 'Ghurar al-Hikam, Amusement- §2', 'wisdom'),
  ('أبْعَدُ النّاسِ عَنِ الصَّلاحِ المُسْتَهْتَرُ بِاللَّهْوِ.', 'The furthest of all people from righteousness is one who is [excessively] fond of amusement.', 'Ghurar al-Hikam, Amusement- §3', 'wisdom'),
  ('أوَّلُ اللَّهْوِ لَعْبٌ، وآخِـرُهُ حَرْبٌ.', 'The beginning of amusement is play and its end is war.', 'Ghurar al-Hikam, Amusement- §4', 'wisdom'),
  ('أبْعَدُ النّاسِ مِنَ النَّجاحِ اَلمُسْتَهْتَرُ بِاللَّهْوِ والمَزاحِ.', 'The furthest of all people from prosperity is one who is fond of amusement and jest.', 'Ghurar al-Hikam, Amusement- §5', 'wisdom'),
  ('اللَّهْوُ مِنْ ثِمارِ الجَهْلِ.', 'Amusement is from the fruits of ignorance.', 'Ghurar al-Hikam, Amusement- §6', 'wisdom'),
  ('اَللَّهْوُ قُوتُ الحَماقَةِ.', 'Amusement is the provision of foolishness.', 'Ghurar al-Hikam, Amusement- §7', 'wisdom'),
  ('رُبَّ لَهْو يُوحِشُ حُرّاً.', 'Many an amusement alienates a freeman.', 'Ghurar al-Hikam, Amusement- §8', 'wisdom'),
  ('شَرُّ ما ضُيِّعَ فيهِ العُمْرُ اللَّعْبُ.', 'The worst thing that one’s lifetime can be wasted on is idle sport.', 'Ghurar al-Hikam, Amusement- §9', 'wisdom'),
  ('مَنْ كَثُرَ لَهْوُهُ اُسْتُحْمِقَ.', 'One whose amusement increases is considered a fool.', 'Ghurar al-Hikam, Amusement- §10', 'wisdom'),
  ('اَللَّيْلُ والنَّهارُ دائِبانِ في طَيِّ الباقينَ، ومَحْوِ آثارِ الماضينَ.', 'The night and day are pursuing their courses in covering those who remain and wiping out the traces of those who have passed away.', 'Ghurar al-Hikam, Night and day- §1', 'wisdom'),
  ('إنَّ لَيْلَكَ ونَهارَكَ لايَسْتَوْعِبانِ لِجَميعِ حاجاتِكَ فَاقْسِمْها (فَاقْسِمْهُما) بَيْنَ عَمَلِكَ وراحَتِكَ.', 'Verily your night and day are not enough to meet all your needs, so divide them between your work and your relaxation.', 'Ghurar al-Hikam, Night and day- §2', 'wisdom'),
  ('إنَّ اللَّيْلَ والنَّهارَ يَعْمَلانِ فيكَ، فَاعْمَلْ فيهما، ويَأْخُذانِ مِنْكَ فَخُذْ مِنْهُما.', 'Verily the night and day are working in you [by making you older] so work in them, and they are taking from you so take from them.', 'Ghurar al-Hikam, Night and day- §3', 'wisdom'),
  ('كُرُورُ اللَّيلِ والنَّهارِ مَكْمَنُ الآفاتِ وداعِى الشَّتاتِ.', 'The succession of the night and day is the hiding place of calamities and the herald of separation [from loved ones].', 'Ghurar al-Hikam, Night and day- §4', 'wisdom'),
  ('كُرُورُ الأيّامِ أحْلامٌ، ولَذّاتُها آلامٌ، ومَواهِبُها فَناءٌ وأسْقامٌ.', 'The succession of days are [like] dreams, their pleasures are [causes of] agonies and their gifts are [fraught with] evanescence and maladies.', 'Ghurar al-Hikam, Night and day- §5', 'wisdom'),
  ('مَنْ عَطَفَ عَلَيْهِ اللَّيْلُ والنَّهارُ أبْلَياهُ.', 'One whose nights and days pass him by is made old by them.', 'Ghurar al-Hikam, Night and day- §6', 'wisdom'),
  ('إنَّ مَنْ كانَ مَطِيَّـتَهُ اللَّيلُ والنَّهارُ، فَإنَّهُ يُسارُ بِهِ وإنْ كانَ واقِفاً، وَيَقْطَعُ المَسافَةَ وإنْ كانَ مُقيماً وادِعاً.', 'Verily one whose riding mount is the night and day is carried [forward] by it even when he is stationary, and he traverses the distance even if he is settled in one place.', 'Ghurar al-Hikam, Night and day- §8', 'wisdom'),
  ('بِلينِ الجانِبِ تَأْنَسُ النُّفُوسُ.', 'Through gentleness, the souls feel at ease.', 'Ghurar al-Hikam, Gentleness and softness- §1', 'wisdom'),
  ('كُنْ لَيِّناً مِنْ غَيْرِ ضَعْف، شَديداً مِنْ غَيْرِ عُنْف.', 'Be soft without being weak and stern without using force.', 'Ghurar al-Hikam, Gentleness and softness- §2', 'wisdom'),
  ('مَنْ لانَتْ عَريكَتُهُ وَجَبَتْ مَحَبَّتُهُ.', 'One whose nature is gentle, loving him is unavoidable.', 'Ghurar al-Hikam, Gentleness and softness- §3', 'wisdom'),
  ('مَنْ لانَ عُودُهُ كَثُفَتْ أغْصانُهُ.', 'One whose wood is soft, his branches become thick.', 'Ghurar al-Hikam, Gentleness and softness- §4', 'wisdom'),
  ('مَنْ تَلِنْ حاشِيَتُهُ يَسْتَدِمْ مِنْ قَوْمِهِ المَحَبَّةَ.', 'One who has a gentle demeanour makes his community’s love [for him] last.', 'Ghurar al-Hikam, Gentleness and softness- §5', 'wisdom'),
  ('مَنْ لَمْ يَلِنْ لِمَنْ دُونَهُ لَمْ يَنَلْ حاجَتَهُ.', 'One who is not lenient with the one who is under him will not obtain what he requires.', 'Ghurar al-Hikam, Gentleness and softness- §6', 'wisdom'),
  ('ألِنْ كَنَفَكَ وتَواضَعْ لِلّهِ يَرْفَعْكَ.', 'Make your demeanour gentle and humble yourself in front of Allah, He will elevate you.', 'Ghurar al-Hikam, Gentleness and softness- §7', 'wisdom'),
  ('ألِنْ كَنَفَكَ فَإنَّ مَنْ يُلِنْ كَنَفَهُ يَسْتَدِمْ مِنْ قَوْمِهِ المَحَبَّةَ.', 'Make your demeanour gentle for indeed whoever has a gentle demeanour, his community’s love [for him] will last.', 'Ghurar al-Hikam, Gentleness and softness- §8', 'wisdom'),
  ('إنَّما المَجْدُ أنْ تُعْطِيَ فِي الغُرْمِ، وتَعْفُوَ عَنِ الجُرْمِ.', 'erily distinction is nothing but your giving that which you owe [of the rights of others] and forgiving the offences [of others].', 'Ghurar al-Hikam, Distinction- §1', 'wisdom'),
  ('لَمْ يُدْرِكِ المَجْدَ مَنْ عَداهُ الحَمْدُ.', 'He who has been forgone by praise does not attain distinction.', 'Ghurar al-Hikam, Distinction- §2', 'wisdom'),
  ('مانالَ المَجْدَ مَنْ عَداهُ الحَمْدُ.', 'He who has been forgone by praise will not acquire distinction.', 'Ghurar al-Hikam, Distinction- §3', 'wisdom'),
  ('ما أدْرَكَ المَجْدَ مَنْ فاتَهُ الجِدُّ.', 'One who lacks diligence does not attain distinction.', 'Ghurar al-Hikam, Distinction- §4', 'wisdom'),
  ('إنَّ لِلمِحَنِ غايات لابُدَّ مِنِ انْقِضائِها، فَنامُوا لَها إلى حينِ انْقِضائِها، فَإنَّ إعْمالَ الحيلَةِ فيها قَبْلَ ذلِكَ زِيادَةٌ لَها.', 'Verily tribulations have certain extents that have to be passed so remain in slumber until they pass, for indeed trying to find a solution before this only increases [and prolongs] it.', 'Ghurar al-Hikam, Tribulations- §1', 'wisdom'),
  ('إنَّ لِلْمِحَنِ غايات، ولِلْغاياتِ نِهايات، فَاصْبِرُوا لَها حَتّى تَبْلُغَ نِهاياتِها، فَالتَّحَرُّكُ لَها قَبْلَ اِنْقِضائِها زِيادَةٌ لَها.', 'Verily tribulations have certain extents, and the extents have limits, so remain patient until you reach their limits, for trying to find a solution for them before they have passed only increases [and prolongs] them.', 'Ghurar al-Hikam, Tribulations- §2', 'wisdom'),
  ('اَلْمِحْنَةُ مَقْرُونَةٌ بِحُبِّ الدُّنْيا.', 'Tribulation is linked with love of this world.', 'Ghurar al-Hikam, Tribulations- §3', 'wisdom'),
  ('قُرِنَتِ المِحْنَةُ بِحُبِّ الدُّنْيا.', 'Tribulation has been linked to love of this world.', 'Ghurar al-Hikam, Tribulations- §4', 'wisdom'),
  ('اِحْتَرِسُوا مِنْ سَوْرَةِ الإطْراءِ والمَدْحِ، فَإنَّ لَهُما ريحاً خبيثَةً فِي القَلْبِ.', 'Be on your guard against excessive flattery and praise for indeed these two have a foul odour in the heart.', 'Ghurar al-Hikam, Praise and extolment- §1', 'wisdom'),
  ('إيّاكَ أنْ تُثْنِيَ عَلى أحَد بِما لَيْسَ فيهِ، فَإنَّ فِعْلَهُ يَصْدُقُ عَنْ وَصْفِهِ وَيُكَذِّبُكَ.', 'Beware of praising anyone for something that is not in him, for indeed his action affirms his attribute and belies you.', 'Ghurar al-Hikam, Praise and extolment- §2', 'wisdom'),
  ('أقْبَحُ الصِّدْقِ ثَناءُ الرَّجُلِ عَلى نَفْسهِ.', 'The ugliest truth is a person’s praise for himself.', 'Ghurar al-Hikam, Praise and extolment- §3', 'wisdom'),
  ('إنَّ مادِحَكَ لَخادِعٌ لِعَقْلِكَ غاشٌّ لَكَ في نَفْسِكَ بِكاذِبِ الإطْراءِ وزُورِ الثَّناءِ، فَإنْ حَرَمْتَهُ نَوالَكَ أوْ مَنَعْتَهُ إفْضالَكَ، وَسَمَكَ بِكُلِّ فَضيحَة، ونَسَبَكَ إلى كُلِّ قَبيحَة.', 'Verily the person who praises you is surely a deceiver of your intellect, [and] a cheater who cheats you about yourself with false compliments and spurious praise; so if you deprive him of your grant or withhold from him your favour, he will label you with every scandal and will attribute every ugly act to you.', 'Ghurar al-Hikam, Praise and extolment- §4', 'wisdom'),
  ('اَلإطْراءُ يُحْدِثُ الزَّهْوَ وَيُدْني مِنَ الغِرَّةِ.', 'Commendation causes vainglory and brings one closer to heedlessness.', 'Ghurar al-Hikam, Praise and extolment- §5', 'wisdom'),
  ('إذا مَدَحْتَ فَاخْتَصِرْ.', 'When you praise, be brief.', 'Ghurar al-Hikam, Praise and extolment- §6', 'wisdom'),
  ('إذا زُكِّيَ أحَدٌ مِنَ المُتَّقينَ، خافَ مِمّا يُقالُ لَهُ فَيَقُولُ: أنَا أعْلَمُ بِنَفْسي مِنْ غَيْري، ورَبّي أعْلَمُ بِنَفْسي مِنّي، اَللّهُمَّ لاتُؤاخِذْني بِما يَقُولُونَ، واجْعَلْني أفْضَلَ مِمّا يَظُنُّونَ.', 'When one of the pious believers is extolled [for his virtues], he fears what is said about him, so he says: I know myself better than others, and my Lord knows me better than myself. O Allah! Do not hold me accountable for what they say and make me better than what they think of me.', 'Ghurar al-Hikam, Praise and extolment- §7', 'wisdom'),
  ('تَزْكِيَةُ الأشْرارِ مِنْ أعْظَمِ الأَوْزارِ.', 'Recommendation of the evil ones is one of the greatest sins.', 'Ghurar al-Hikam, Praise and extolment- §8', 'wisdom'),
  ('حُبُّ الإطْراءِ والمَدْحِ مِنْ أوْثَقِ فُرَصِ الشَّيْطانِ.', 'Love for compliments and praise is from the surest opportunities of Satan.', 'Ghurar al-Hikam, Praise and extolment- §9', 'wisdom'),
  ('خَيْرُ الثَّناءِ ما جَرى عَلى اَلْسِنَةِ الأبْرارِ.', 'The best praise is that which flows from the tongues of the righteous.', 'Ghurar al-Hikam, Praise and extolment- §10', 'wisdom'),
  ('اَلْمَرْءُ حَيْثُ وَضَعَ نَفْسَهُ بِرِياضَتِهِ وطاعَتِهِ، فَإنْ نَزَهَها تَنَزَّهَتْ، وإنْ دَنَسَها تَدَنَّسَتْ.', 'A person is in the position where he places his soul through his devotion and obedience, so if he purifies it, it becomes pure and if he sullies it, it becomes sullied.', 'Ghurar al-Hikam, The human being- §1', 'wisdom'),
  ('اَلرَّجُلُ حَيْثُ اخْتارَ لِنَفْسِهِ إنْ صانَها اِرْتَفَعَتْ، وَإنِ ابْتَذَلَها اِتَّضَعَتْ.', 'A person is in the position that he chooses for his soul. If he preserves it, it becomes elevated and if he does not preserve it, it becomes abased.', 'Ghurar al-Hikam, The human being- §2', 'wisdom'),
  ('اَلْمَرْءُ بِأصْغَرَيْهِ: بِقَلْبِهِ، ولِسانِهِ، إنْ قاتَلَ قاتَلَ بِجَنان، وإنْ نَطَقَ نَطَقَ بِبَيان.', 'A person is [gauged] by his two small parts: his heart and his tongue. If he battles, he fights with his heart and if he speaks, he speaks by his articulation.', 'Ghurar al-Hikam, The human being- §3', 'wisdom'),
  ('اَلْمَرْءُ يَتَغَيَّرُ في ثَلاث: اَلقُرْبُ مِنَ المُلُوكِ، والوِلاياتُ، والغَناءُ مِنَ الفَقْرِ، فَمَنْ لَمْ يَتَغَيَّرْ في هذِهِ فَهُوَ ذُو عَقْل قَويم، وخُلْق مُسْتَقيم.', 'The human being changes in three instances: when he is close to kings, when he gains positions of authority and when he becomes wealthy. So whoever does not change in these conditions, then he is one who possesses a strong intellect and an upright character.', 'Ghurar al-Hikam, The human being- §4', 'wisdom'),
  ('اَلْمَرْءُ بِفِطْنَتِهِ لابِصُورَتِهِ.', 'A man is [to be gauged] by his astuteness not by his appearance.', 'Ghurar al-Hikam, The human being- §5', 'wisdom'),
  ('اَلْمَرْءُ بِهِمَّتِهِ لابِقُنْيَتِهِ.', 'A person is [valued] by his endeavour [and effort], not by his [material] acquisition.', 'Ghurar al-Hikam, The human being- §6', 'wisdom'),
  ('اَلْمَرْءُ بِهِمَّتِهِ.', 'A man is [gauged] by his endeavour.', 'Ghurar al-Hikam, The human being- §7', 'wisdom'),
  ('اَلرَّجُلُ بِجَنانِهِ.', 'A person is [judged] by [what is in] his heart.', 'Ghurar al-Hikam, The human being- §8', 'wisdom'),
  ('اَلْمَرْءُ بِإيمانِهِ.', 'A person is [gauged] by his faith.', 'Ghurar al-Hikam, The human being- §9', 'wisdom'),
  ('حَسَبُ الرَّجُلِ مالُهُ، وكَرَمُهُ دينُهُ.', 'The distinction of a man is [by] his wealth but his honour is [by] his religion.', 'Ghurar al-Hikam, The human being- §10', 'wisdom'),
  ('اَلْمُـرُوءَةُ اجْتِنابُ الرَّجُلِ ما يَشِينُهُ واكْتِسابُهُ ما يَزينُهُ.', 'Magnanimity is a person’s eschewal of that which dishonours him and his earning that which embellishes him.', 'Ghurar al-Hikam, Magnanimity- §1', 'wisdom'),
  ('اَلْمُرُوءَةُ اَلْعَدْلُ فِي الإمْرَةِ، والعَفْوُمَعَ القُدْرَةِ، والمُواساةُ فِي العِشْرَةِ (العُسْرَةِ).', 'Magnanimity is [displaying] equity when in authority, showing forgiveness despite having the power [to take revenge] and being financially supportive [to those in need] in one’s society (or in times of hardship).', 'Ghurar al-Hikam, Magnanimity- §2', 'wisdom'),
  ('اَلْمُرُوءَةُ بَثُّ المَعْرُوفِ، وقِرَى الضُّيُوفِ.', 'Magnanimity is spreading goodness and being hospitable to guests.', 'Ghurar al-Hikam, Magnanimity- §3', 'wisdom'),
  ('اَلْمُروءَةُ اسْمٌ جامِعٌ لِسائِرِ الفَضائِلِ والمَحاسِنِ.', 'Magnanimity is a title that encompasses all the [other] merits and virtues.', 'Ghurar al-Hikam, Magnanimity- §4', 'wisdom'),
  ('أشْرَفُ اَلْمُرُوءَةِ حُسْنُ الأُ خُوَّةِ.', 'The most honourable magnanimity is loyal brotherhood.', 'Ghurar al-Hikam, Magnanimity- §5', 'wisdom'),
  ('أحْسَنُ الْمُرُوءَةِ حِفْظُ الوُدِّ.', 'The best magnanimity is preserving goodwill [and affection].', 'Ghurar al-Hikam, Magnanimity- §6', 'wisdom'),
  ('أصْلُ المُرُوءَةِ اَلْحَياءُ، وثَمَرَتُها العِفَّةُ.', 'The root of magnanimity is modesty and its fruit is chastity.', 'Ghurar al-Hikam, Magnanimity- §7', 'wisdom'),
  ('أشْرَفُ المُرُوءَةِ مِلْكُ الغَضَبِ، وإماتَةُ الشَّهْوَةِ.', 'The most honourable magnanimity is controlling one’s anger and killing one’s lustful desires.', 'Ghurar al-Hikam, Magnanimity- §8', 'wisdom'),
  ('أفْضَلُ المُرُوءَةِ اِحْتِمالُ جِناياتِ الإخْوانِ.', 'The most excellent magnanimity is tolerating the offenses of one’s brothers.', 'Ghurar al-Hikam, Magnanimity- §9', 'wisdom'),
  ('أفْضَلُ المُرُوءَةِ اِسْتِبْقاءُ الرَّجُلِ ماءَ وَجْهِهِ.', 'The most excellent magnanimity is for a man to preserve his dignity.', 'Ghurar al-Hikam, Magnanimity- §10', 'wisdom'),
  ('اَلمَرَضُ حَبْسُ البَدَنِ.', 'Sickness is [a form of] confinement of the body.', 'Ghurar al-Hikam, Sickness- §1', 'wisdom'),
  ('شَيْئانِ لايُؤْنَفُ مِنْهُما: اَلمَرَضُ، وذُوالقَرابَةِ المُفْتَقِرِ.', 'There are two things that should not be scorned: sickness and the poor relative.', 'Ghurar al-Hikam, Sickness- §2', 'wisdom'),
  ('مَنْ كَتَمَ الأطِبّاءَ مَرَضَهُ خانَ بَدَنَهُ.', 'One who hides his sickness from the physicians has betrayed his body.', 'Ghurar al-Hikam, Sickness- §3', 'wisdom'),
  ('مَنْ كَتَمَ مَكْنُونَ دائِهِ عَجَزَ طَبيبُهُ عَنْ شِفائِهِ.', 'Whoever conceals his hidden ailment, his physician becomes incapable of curing him.', 'Ghurar al-Hikam, Sickness- §4', 'wisdom'),
  ('اَلمَرَضُ أحَدُ الحَبْسَيْنِ.', 'Sickness in one of the two confinements.', 'Ghurar al-Hikam, Sickness- §5', 'wisdom'),
  ('اَلمِراءُ بَذْرُ الشَّرِّ.', 'Disputation is the seed of evil.', 'Ghurar al-Hikam, Disputation and argument- §1', 'wisdom'),
  ('اَلْجَدَلُ فِي الدّينِ يُفْسِدُ اليَقينَ.', 'Argument in religion corrupts certitude.', 'Ghurar al-Hikam, Disputation and argument- §2', 'wisdom'),
  ('ثَمَرَةُ المِراءِ الشَّحْناءُ.', 'The fruit of disputation is hatred.', 'Ghurar al-Hikam, Disputation and argument- §3', 'wisdom'),
  ('سَبَبُ الشَّحْناءِ كَثْرَةُ المِراءِ.', 'Too much disputation is the cause of hatred [and enmity].', 'Ghurar al-Hikam, Disputation and argument- §4', 'wisdom'),
  ('سِتَّةٌ لايُمارُونَ: اَلْفَقيهُ وَالرَّئيسُ وَالدَّنيُّ والبَذيُّ والمَرْأَةُ وَالصَّبيُّ.', 'One should not dispute with six types of people: the jurist, the leader, the low, the lewd, the woman and the child.', 'Ghurar al-Hikam, Disputation and argument- §5', 'wisdom'),
  ('مَنْ كَثُرَ مِراؤُهُ لَمْ يَأْمَنِ الغَلَطَ.', 'One whose disputation increases does not remain safe from error.', 'Ghurar al-Hikam, Disputation and argument- §6', 'wisdom'),
  ('مَنْ عَوَّدَ نَفْسَهُ المِراءَ صارَ دَيْدَنَهُ.', 'Whoever accustoms himself to disputation, it becomes his habit.', 'Ghurar al-Hikam, Disputation and argument- §7', 'wisdom'),
  ('مَنْ جَعَلَ دَيْدَنَهُ المِراءَ لَمْ يُصْبِحْ لَيْلَهُ.', 'One who makes disputation his habit will not turn his night into day [and will remain in the darkness of ignorance].', 'Ghurar al-Hikam, Disputation and argument- §8', 'wisdom'),
  ('مَنْ كَثُرَ مِرائُهُ بِالْباطِلِ دامَ عَماؤُهُ عَنِ الحَقِّ.', 'One whose false disputations increase, his blindness from the truth persists.', 'Ghurar al-Hikam, Disputation and argument- §9', 'wisdom'),
  ('مَنْ مارَى السَّفيهَ فَلا عَقْلَ لَهُ.', 'One who disputes with a fool has no intelligence.', 'Ghurar al-Hikam, Disputation and argument- §10', 'wisdom'),
  ('اَلمُزاحُ فِرْقَةٌ تَتْبَعُها ضَغِْينَةٌ.', 'Joking is a [cause of] separation that is followed by rancour.', 'Ghurar al-Hikam, Joking- §1', 'wisdom'),
  ('إيّاكَ أنْ تَذْكُرَ مِنَ الكَلامِ (ماكانَ) مُضْحِكاً، وإنْ حَكَيْتَهُ عَنْ غَيْرِكَ.', 'Beware of recalling that which was funny in the speech [of others], even if you narrate it from someone else.', 'Ghurar al-Hikam, Joking- §2', 'wisdom'),
  ('اَلإفْراطُ فِي المَزْحِ خُرْقٌ.', 'Excessiveness in joking is foolishness.', 'Ghurar al-Hikam, Joking- §3', 'wisdom'),
  ('دَعِ المُزاحَ فَإنَّهُ لِقاحُ الضَّغينَةِ.', 'Abandon [excessive] joking for indeed it is the conception of rancour.', 'Ghurar al-Hikam, Joking- §4', 'wisdom'),
  ('فيِ السَّفَهِ وكَثْرَةِ المُزاحِ الخُرْقُ.', 'In impudence and excessive joking there is foolishness.', 'Ghurar al-Hikam, Joking- §5', 'wisdom'),
  ('كَثْرَةُ المُزاحِ تُسْقِطُ الهَيبَةَ.', 'Too much joking diminishes one’s reverence [and dignity].', 'Ghurar al-Hikam, Joking- §6', 'wisdom'),
  ('كَثْرَةُ المُزاحِ تُذْهِبُ البَهاءَ وتُوجِبُ الشَّهْناءَ.', 'Too much joking takes away prestige and brings about enmity [and rancour].', 'Ghurar al-Hikam, Joking- §7', 'wisdom'),
  ('لِكُلِّ شَيْء بَذْرٌ، وبَذْرُ العَداوَةِ المُزاحُ.', 'Everything has a seed, and the seed of enmity is joking.', 'Ghurar al-Hikam, Joking- §8', 'wisdom'),
  ('مَنْ مَزَحَ اُسْتُخِفَّ بِهِ.', 'One who jokes [excessively] is taken lightly.', 'Ghurar al-Hikam, Joking- §9', 'wisdom'),
  ('مَنْ كَثُرَ مُزاحُهُ اُسْتُجْهِلَ.', 'One whose joking increases is deemed ignorant.', 'Ghurar al-Hikam, Joking- §10', 'wisdom'),
  ('اِمْشِ بِدَأْبِكَ(بِدائِكَ) ما مَشى بِكَ.', 'Keep walking in your customary way (or with your ailment 1 ) as long as you can.', 'Ghurar al-Hikam, Walking- §1', 'wisdom'),
  ('اَلمَطَلُ والمَنُّ مُنَكِّدَا الإحْسانِ.', 'Delay and obligation are the spoilers of [the] favour [one does to others].', 'Ghurar al-Hikam, Delay- §1', 'wisdom'),
  ('اَلمَطَلُ أحَدُ المَنْعَيْنِ.', 'Delay [in giving] is one of the two refusals.', 'Ghurar al-Hikam, Delay- §2', 'wisdom'),
  ('اَلمَطَلُ عَذابُ النَّفْسِ.', 'Delay [and procrastination] is a chastisement of the soul.', 'Ghurar al-Hikam, Delay- §3', 'wisdom'),
  ('اَلْمَكْرُ والغُلُّ مُجانِبَا الإيمانِ.', 'Scheming and malice are things that keep faith away.', 'Ghurar al-Hikam, Scheming- §1', 'wisdom'),
  ('إيّاكَ والمَكْرَ، فَإنَّ الْمَكْرَ لَخُلْقٌ ذَميمٌ.', 'Beware of scheming, for indeed scheming [and plotting] is a blameworthy quality.', 'Ghurar al-Hikam, Scheming- §2', 'wisdom'),
  ('اَلمَكْرُ لُؤْمٌ، اَلخَديعَةُ شُؤْمٌ.', 'Scheming is wickedness, deception is evil.', 'Ghurar al-Hikam, Scheming- §3', 'wisdom'),
  ('اَلمَكْرُ شيمَةُ المَرَدَةِ.', 'Scheming is the practice of the mutinous.', 'Ghurar al-Hikam, Scheming- §4', 'wisdom'),
  ('اَلمَكْرُ سَجِيَّةُ اللِّئامِ.', 'Scheming is the trait of the wicked.', 'Ghurar al-Hikam, Scheming- §5', 'wisdom'),
  ('اَلمَكْرُ بِمَنِ ائْتَمَنَكَ كُفْرٌ.', 'Scheming against one who trusts in you is ingratitude [and betrayal].', 'Ghurar al-Hikam, Scheming- §6', 'wisdom'),
  ('آفَةُ الذُّكاءِ اَلْمَكْرُ.', 'The bane of cleverness is scheming.', 'Ghurar al-Hikam, Scheming- §7', 'wisdom'),
  ('رَأْسُ الحِكْمَةِ تَجَنُّبُ الخُدَعِ.', 'The cornerstone of wisdom is eschewing deceptions.', 'Ghurar al-Hikam, Scheming- §8', 'wisdom'),
  ('رُبَّ مُحْتال صَرَعَتْهُ حيلَتُهُ.', 'Many a plotter has been struck down by his own stratagem.', 'Ghurar al-Hikam, Scheming- §9', 'wisdom'),
  ('مَنْ أمِنَ مَكْرَ اللّهِ هَلَكَ.', 'One who feels secure from the devising of Allah is destroyed.', 'Ghurar al-Hikam, The devising of Allah- §1', 'forgiveness'),
  ('مَنْ أمِنَ المَكْرَ لَقِيَ الشَّـرَّ.', 'One who feels secure from the devising [of Allah] meets with harm.', 'Ghurar al-Hikam, The devising of Allah- §2', 'forgiveness'),
  ('اَلمَكُورُ شَيْطانٌ.', 'The one who always hatches plots [against others] is a devil.', 'Ghurar al-Hikam, The schemer and the plotter- §1', 'wisdom'),
  ('اَلْمَكُورُ شَيْطانٌ في صُورَةِ الإنْسانِ.', 'The one who is always scheming [against others] is a devil in the form of a human being.', 'Ghurar al-Hikam, The schemer and the plotter- §2', 'wisdom'),
  ('مَنْ مَكَرَ حاقَ بِهِ مَكْرُهُ.', 'One who schemes is afflicted by his own scheming.', 'Ghurar al-Hikam, The schemer and the plotter- §3', 'wisdom'),
  ('مَنْ مَكَرَ بِالنَّاسِ رَدَّ اللّهُ سُبْحانَهُ مَكْرَهُ في عُنُقِهِ.', 'Whoever schemes against people, Allah, the Glorified, turns his scheme back on him.', 'Ghurar al-Hikam, The schemer and the plotter- §4', 'wisdom'),
  ('لاأمانَةَ لِمَكُور.', 'There is no trustworthiness in the schemer.', 'Ghurar al-Hikam, The schemer and the plotter- §5', 'wisdom'),
  ('لايَحيقُ المَكْرُ السَّيئُ إلاّ بِأهْلِهِ.', 'Evil scheming does not beset anyone but those who practice it.', 'Ghurar al-Hikam, The schemer and the plotter- §6', 'wisdom'),
  ('إيّاكَ والمَلَقَ، فَإنَّ المَلَقَ لَيْسَ مِنْ خَلائِقِ الإيمانِ.', 'Beware of flattery, for indeed flattery is not from the characteristics of faith [and the faithful].', 'Ghurar al-Hikam, Flattery- §1', 'wisdom'),
  ('لَيْسَ المَلَقُ مِنْ خُلْقِ الأنْبِياءِ.', 'Flattery is not part of the character of Prophets.', 'Ghurar al-Hikam, Flattery- §2', 'wisdom'),
  ('مَنْ كَثُرَ مَلَقُهُ لَمْ يُعْرَفْ بِشْرُهُ.', 'One whose flattery increases, his [sincere] joyfulness is not recognized.', 'Ghurar al-Hikam, Flattery- §3', 'wisdom'),
  ('اَلسُّلْطانُ الجائِرُ، والعالِمُ الفاجِرُ أشَدُّ النّاسِ نِكايَةً.', 'A tyrant ruler and an immoral scholar are the most harmful of all people.', 'Ghurar al-Hikam, Kings and rulers- §1', 'wisdom'),
  ('اِصْحَبِ السُّلْطان َ بِالحَذَرِ،وَ الصَّدِيقَ بِالتَّواضُعِ والبِشْرِ، والعَدُوَّ بِما تَقُومُ بِهِ عَلَيْهِ حُجَّتُكَ.', 'Accompany the ruler with caution, the friend with humility and cheerfulness, and the enemy with that which you can [use to] establish your proof over him.', 'Ghurar al-Hikam, Kings and rulers- §2', 'wisdom'),
  ('إنَّ السُّلْطانَ لأمينُ اللّهِ فِي الأرْضِ، ومُقيمُ العَدْلِ فِي البِلادِ والعِبادِ، ووَزَعَتُهُ فِي الأرْضِ.', 'Verily the ruler is a trustee of Allah on earth, the establisher of justice in the lands and among the people, and the one who deters people from misdeeds in the land.', 'Ghurar al-Hikam, Kings and rulers- §3', 'wisdom'),
  ('اَلسُّلْطانُ الجائِرُ يُخيفُ البَرِيَّ.', 'The tyrant king frightens the innocent.', 'Ghurar al-Hikam, Kings and rulers- §4', 'wisdom'),
  ('اَلأميرُ السُّوءُ يَصْطَنِعُ البَذِيَّ.', 'An evil commander commissions the vulgar one [to work for him].', 'Ghurar al-Hikam, Kings and rulers- §5', 'wisdom'),
  ('آفَةُ المُلُوكِ سُوءُ السَّريرَةِ.', 'The bane of kings is evil intentions.', 'Ghurar al-Hikam, Kings and rulers- §6', 'wisdom'),
  ('آفَةُ الْوُزَراءِ خُبْثُ السَّريرَةِ.', 'The bane of viziers is wicked inner thoughts.', 'Ghurar al-Hikam, Kings and rulers- §7', 'wisdom'),
  ('آفَةُ الزُّعَماءِ ضَعْفُ السِّياسَةِ.', 'The bane of leaders is weakness in politics.', 'Ghurar al-Hikam, Kings and rulers- §8', 'wisdom'),
  ('آفَةُ المُلْكِ ضَعْفُ الحِمايَةِ.', 'The bane of a kingdom is [having] weak defences.', 'Ghurar al-Hikam, Kings and rulers- §9', 'wisdom'),
  ('إذا مَلَكْتَ فَارْفُقْ.', 'When you become the ruler then be kind [to your subjects].', 'Ghurar al-Hikam, Kings and rulers- §10', 'wisdom'),
  ('وقالَ ـ عَلَيْهِ السَّلامُ ـ في حَقِّ الأشْتَرِ النَّخَعي لَمّا بَلَغَهُ وَفاتُهُ رَحِمَهُ اللّه: لَوْ كانَ جَبَلاً لَكانَ فِنْداً، لايَرتَقيهِ الحافِرُ، وَلا يُوفي عَلَيْهِ الطّائِرُ.', 'He (‘a) said about al-Ashtar al-Nakha‘ī when he was informed about his death (may Allah have mercy upon him): If he was a mountain, he would have been a great one, no hoofed animal would have reached its peak and no bird would have been able to fly over it.', 'Ghurar al-Hikam, Malik al-Ashtar- §1', 'wisdom'),
  ('وَقالَ ـ عَلَيْهِ السّلامُ ـ في حَقِّ الأشْتَرِ النَخَعِي: هُوَ سَيْفُ اللّهِ لايَنْبُو عَنِ الضَّرْبِ، ولاكَليلُ الحَدِّ ولاتَسْتَهْويهِ بِدْعَةٌ، ولاتَتيهُ بِهِ غَوايَةٌ.', 'He (‘a) said about al-Ashtar al-Nakha‘ī: He is the sword of Allah that does not fail to strike and is not blunt in its edge; he is not impressed by any innovations nor is he led astray by misguidance [and temptation].', 'Ghurar al-Hikam, Malik al-Ashtar- §2', 'wisdom'),
  ('إنَّ مَعَ كُلِّ إنْسان مَلَكَيْنِ يَحْفَظانِهِ، فَإذا جاءَ أجَلُهُ خَلَّيا بَيْنَهُ وبَيْنَهُ، وَإنَّ الأجَلَ لَجُنَّةٌ حَصينَةٌ.', 'Verily with every person there are two angels who protect him, and when his time is up they leave him alone with his impending death, and verily the [decreed] lifetime [of a person] is a strong protective shield.', 'Ghurar al-Hikam, Angels- §1', 'wisdom'),
  ('وقالَ ـ عَلَيهِ السّلام ـ في ذِكْرِ المَلائِكَةِ: هُمْ أُسَراءُ إيمان، لَمْ يَفُكَّهُمْ مِنْهُ (مِنْ ريقَتِهِ) زَيْغٌ ولاعُدُولٌ.', 'He (‘a) said about angels: They are captives of faith; neither divergence nor deviation breaks them from its hold.', 'Ghurar al-Hikam, Angels- §2', 'wisdom'),
  ('رُبَّ مَمْلُوك لايُسْتَطاعُ فِراقُهُ.', 'Many a slave is such that one cannot bear his separation.', 'Ghurar al-Hikam, The slave- §1', 'wisdom'),
  ('مَنْ أحْسَنَ المَلَكَةَ أمِنَ الهَلَكَةَ.', 'One whose disposition is good [with those who are under him] remains safe from annihilation.', 'Ghurar al-Hikam, Disposition- §1', 'wisdom'),
  ('لَيْسَ لِمَلُول إخاءٌ.', 'One who is fed-up has no [sense of] brotherhood.', 'Ghurar al-Hikam, One who is fed-up- §1', 'wisdom'),
  ('لَيْسَ لِمَلُول مُرُوَّةٌ.', 'One who is fed-up has no magnanimity.', 'Ghurar al-Hikam, One who is fed-up- §2', 'wisdom'),
  ('لاتَأمَنَنَّ مَلُولاً وإنْ تَحَلّى بِالصِّلَةِ، فَإنَّهُ لَيْسَ فيِ البَرْقِ الخاطِفِ مُسْتَمْتَعٌ لِمَنْ يَخُوضُ الظُّلْمَةَ.', 'Never feel secure from the one who is fed-up [with you] even if he is endowed with gifts for indeed there is no enjoyment in lightening for the one who is plunged into darkness.', 'Ghurar al-Hikam, One who is fed-up- §3', 'wisdom'),
  ('لاأُخُوَّةَ لِمَلُول', 'There is no brotherhood for the one who is fed-up.', 'Ghurar al-Hikam, One who is fed-up- §4', 'wisdom'),
  ('لاخُلَّةَ لِمَلُول.', 'There is no friendship for the one who is fed-up.', 'Ghurar al-Hikam, One who is fed-up- §5', 'wisdom'),
  ('اَلْمَلَلُ (المُلْكُ) يُفْسِدُ الأُ خُوَّةَ.', 'Irritation (or kingship) corrupts brotherhood.', 'Ghurar al-Hikam, Irritation- §1', 'wisdom'),
  ('كُلُّ مُمْتَنِع صَعْبٌ مَنالُهُ ومَرامُهُ.', 'Every inaccessible thing is difficult to obtain and seek.', 'Ghurar al-Hikam, The inaccessible- §1', 'wisdom'),
  ('اَلْمَنُّ يُسَوِّدُ النِّعْمَةَ.', 'Putting someone under obligation blackens the favour.', 'Ghurar al-Hikam, To put [others] under obligation- §1', 'wisdom'),
  ('اَلْمَنُّ مُفْسِدَةُ الصَّنِيعَةِ.', 'Obligation is the corruptor of good actions.', 'Ghurar al-Hikam, To put [others] under obligation- §2', 'wisdom'),
  ('اَلْمَنُّ يُنَـكِّدُ الإحْسانَ.', 'Obligation spoils the favour.', 'Ghurar al-Hikam, To put [others] under obligation- §3', 'wisdom'),
  ('اَلْمَنُّ يُفْسِدُ الصَّنيعَةَ.', 'Obligation corrupts the good act.', 'Ghurar al-Hikam, To put [others] under obligation- §4', 'wisdom'),
  ('اَلْمَنُّ يُفْسِدُ الإحْسانَ.', 'Obligation corrupts the favour.', 'Ghurar al-Hikam, To put [others] under obligation- §5', 'wisdom'),
  ('اللُّؤْمُ مَعَ الاِمْتِنانِ.', 'There is wickedness with obligation.', 'Ghurar al-Hikam, To put [others] under obligation- §6', 'wisdom'),
  ('اَلتَّكَرُّمُ مَعَ الاِمْتِنانِ لُؤْمٌ.', 'Doing acts of kindness along with obligation is vileness.', 'Ghurar al-Hikam, To put [others] under obligation- §7', 'wisdom'),
  ('آفَةُ السَّخاءِ المَنُّ.', 'The bane of generosity is obligation.', 'Ghurar al-Hikam, To put [others] under obligation- §8', 'wisdom'),
  ('بِالمَنِّ يُكَدَّرُ الإحْسانُ.', 'Through obligation the favour is spoilt.', 'Ghurar al-Hikam, To put [others] under obligation- §9', 'wisdom'),
  ('بِكَثْرَةِ المَنِّ تُـكَدَّرُ الصَّنيعَةُ.', 'By putting a lot of obligation, the good action is spoilt.', 'Ghurar al-Hikam, To put [others] under obligation- §10', 'wisdom'),
  ('اَلْمَوْتُ اَلْزَمُ لَكُمْ مِنْ ظِلِّكُمْ، وأمْلَكُ بِكُمْ (أمْلَكُكُمْ)مِنْ أنْفُسِكُمْ.', 'Death clings to you more closely than your own shadows and has greater authority over you than [you have over] yourselves.', 'Ghurar al-Hikam, Death- §1', 'mortality'),
  ('أَدِمْ ذِكْرَ المَوْتِ، وذِكْرَ ما تَقْدِمُ عَلَيْهِ بَعْدَ المَوْتِ ولاتَتَمَنَّ المَوْتَ إلاّ بِشَرط وَثيق.', 'Continuously remember death and remember what you will face after death; and never wish for death except after being sure that you have fulfilled the condition for security [in the Hereafter].', 'Ghurar al-Hikam, Death- §2', 'mortality'),
  ('أكْثِرْ ذِكْرَ المَوْتِ وَما تَهْجِمُ عَلَيْهِ، وتُفْضي إلَيْهِ بَعْدَ المَوْتِ حَتّى يَأتِيَكَ، وَقَدْ أخَذْتَ لَهُ حِذْرَكَ،وَ شَدَدْتَ لَهُ أزْرَكَ، ولايَأتِيَكَ بَغْتَةً فَيَبْهَرَكَ.', 'Increase your remembrance of death and of the place you have to go suddenly and return to after death, until it comes to you while you are on your guard against it and have prepared yourself for it, and let it not come over you suddenly thereby taking you by surprise.', 'Ghurar al-Hikam, Death- §3', 'mortality'),
  ('اِسْتَعِدُّوا لِلْمَوْتِ فَقَدْ أظَلَّكُمْ (أطَلَّكُمْ).', 'Prepare yourselves for death for indeed it overshadows you.', 'Ghurar al-Hikam, Death- §4', 'mortality'),
  ('أسْمِعُوا دَعْوَةَ المَوْتِ آذانَكُمْ قَبْلَ أنْ يُدْعى بِكُمْ.', 'Let your ears hear the call of death before it calls you.', 'Ghurar al-Hikam, Death- §5', 'mortality'),
  ('اُذْكُرُوا هادِمَ اللَّذّاتِ، ومُنَغِّصَ الشَّهَواتِ، وداعِيَ الشَّتاتِ.', 'Remember the destroyer of pleasures and the spoiler of lustful desires and the caller towards separation.', 'Ghurar al-Hikam, Death- §6', 'mortality'),
  ('اِحْذَرِ المَوْتَ، وأحْسِنْ لَهُ الإسْتِعْدادَ، تَسْعَدْ بِمُنْقَلَبِكَ.', 'Beware of death and be adequately prepared for it, [for by this] you will be happy in your place of [final] return.', 'Ghurar al-Hikam, Death- §7', 'mortality'),
  ('إحْذَرْ قِلَّةَ الزّادِ، وأكْثِرْ مِنَ الاِسْتِعْدادِ لِرِحْلَتِكَ.', 'Beware of insufficient provisions and increase your preparations for your departure.', 'Ghurar al-Hikam, Death- §8', 'mortality'),
  ('ألا مُسْتَعِدٌّ لِلِقاءِ رَبِّهِ قَبْلَ زُهُوقِ نَفْسِهِ.', 'Is there nobody who is ready to meet his Lord before his soul leaves [his body]?', 'Ghurar al-Hikam, Death- §9', 'mortality'),
  ('أفْضَلُ تُحْفَةِ المُؤْمِنِ المَوْتُ.', 'The best gift for a believer is death.', 'Ghurar al-Hikam, Death- §10', 'mortality'),
  ('لاتَذْكُرِ المَوْتى بِسُوء، فَكَفى بِذلِكَ إثْماً.', 'Do not remember the dead negatively [by recalling their bad actions] for this suffices as a sin.', 'Ghurar al-Hikam, The dead- §1', 'wisdom'),
  ('اَلْمالُ يُكْرِمُ صاحِبَهُ فِي الدُّنْيا، ويُهِينُهُ عِنْدَ اللّهِ سُبْحانَهُ.', 'Wealth honours its possessor in this world and abases him in front of Allah, the Glorified.', 'Ghurar al-Hikam, Wealth and riches- §1', 'detachment'),
  ('اَلْمالُ يُكْرِمُ صاحِبَهُ ما بَذَلَهُ، ويُهينُهُ ما بَخِلَ بِهِِ.', 'Wealth honours its possessor as long as he spends it and abases him when he is miserly with it.', 'Ghurar al-Hikam, Wealth and riches- §2', 'detachment'),
  ('اَلْمالُ والبَنُونُ زِينَةُ الحَياةِ الدُّنْيا، والعَمَلُ الصّالِحُ حَرْثُ الآخِرَةِ.', 'Wealth and children are the ornaments of this worldly life while good action is the tillage of the Hereafter.', 'Ghurar al-Hikam, Wealth and riches- §3', 'detachment'),
  ('اَلْمالُ يَرْفَعُ صاحِبَهُ فيِ الدُّنْيا ويَضَعُهُ فِي الآخِرَةِ.', 'Wealth elevates its possessor in this world but lowers him in the Hereafter.', 'Ghurar al-Hikam, Wealth and riches- §4', 'detachment'),
  ('اَلْمالُ وَبالٌ عَلى صاحِبِهِ إلاّ ما قَدَّمَ مِنْهُ.', 'Wealth is a burden for its possessor except that which he sends ahead from it [for the Hereafter].', 'Ghurar al-Hikam, Wealth and riches- §5', 'detachment'),
  ('اَلْمالُ فِتْنَةُ النَّفْسِ ونَهْبُ الرَّزايا.', 'Wealth is the tribulation of the soul and the plunder of calamities.', 'Ghurar al-Hikam, Wealth and riches- §6', 'detachment'),
  ('اَلْمالُ تَنْقُصُهُ النَّفَقَةُ، وَالعِلْمُ يَـزْكُو عَلَى الإنْفاقِ.', 'Wealth is reduced by spending [it] whereas knowledge grows when it is given away [and shared with others].', 'Ghurar al-Hikam, Wealth and riches- §7', 'detachment'),
  ('أمْسِكْ مِنَ المالِ بِقَدْرِ ضَرُورَتِكَ،وَ قَدِّمِ الفَضْلَ لِيَوْمِ فاقَتِكَ.', 'Hold on to wealth according to the extent of your need, and forward the rest for the day of your indigence.', 'Ghurar al-Hikam, Wealth and riches- §8', 'detachment'),
  ('إيّاكَ والاِسْتيثارَ (الاِسْتِتارَ)بِما لِلنّاسِ فيهِ أُسْوَةٌ، والتَّغابي عَمّا وَضَحَ لِلنّاظِرينَ فَإنَّهُ مَأْخُوذٌ مِنْكَ لِغَيْرِكَ.', 'Beware of reserving for yourself (or concealing) that which all the people have an equal right to and turning a blind eye to what is manifest for the onlookers otherwise it will surely be taken from you and given to someone else.', 'Ghurar al-Hikam, Wealth and riches- §9', 'detachment'),
  ('أفْضَلُ المالِ مَا اسْتُرِقَّ بِهِ الأحْرارُ.', 'The best wealth is that by which the freemen become enthralled.', 'Ghurar al-Hikam, Wealth and riches- §10', 'detachment'),
  ('كُلُّ شَيْء يَمِيلُ إلى جِنْسِهِ.', 'Everything inclines towards its [own] kind.', 'Ghurar al-Hikam, Inclination- §1', 'wisdom'),
  ('كُلُّ أمْر يَميلُ إلى مِثْلِهِ.', 'Every person inclines towards one who is like him.', 'Ghurar al-Hikam, Inclination- §2', 'wisdom'),
  ('كُلُّ طَيْر يَأْوي إلى شَكْلِهِ.', 'Every bird stays close to its [own] kind.', 'Ghurar al-Hikam, Inclination- §3', 'wisdom'),
  ('اَلنُّبْلُ بِالتَّحَلِّي بِالجُودِ والوَفاءُ بِالْعُهُودِ.', 'Nobility is [attained] by adorning [oneself] with generosity and fulfilling [one’s] promises.', 'Ghurar al-Hikam, Nobility and the noble- §1', 'wisdom'),
  ('إنَّما النُّبْلُ اَلتَّبـَرِّي عَنِ الْمَخازي.', 'Verily nobility is nothing but the shunning of disgraceful actions.', 'Ghurar al-Hikam, Nobility and the noble- §2', 'wisdom'),
  ('عادَةُ النُّبَلاءِ السَّخاءُ والْكَظْمُ والْعَفْوُ والْحِلْمُ.', 'The habits of the noble ones are: generosity, suppressing anger, forgiveness and forbearance.', 'Ghurar al-Hikam, Nobility and the noble- §3', 'wisdom'),
  ('عُنْوانُ النُّبْلِ الإحْسانُ إلَى النّاسِ.', 'The symbol of nobility is doing good to people.', 'Ghurar al-Hikam, Nobility and the noble- §4', 'wisdom'),
  ('مِنْ النُّبْلِ أنْ يَبْذُلَ الرَّجُلُ مالَهُ ويَصُونَ عِرْضَهُ.', 'It is from nobility for a man to spend his wealth and safeguard his dignity.', 'Ghurar al-Hikam, Nobility and the noble- §5', 'wisdom'),
  ('مِنْ عَلاماتِ النُّبْلِ اَلْعَمَلُ بِسُنَّةِ الْعَدْلِ.', 'Acting on the principle of justice is from the signs of nobility.', 'Ghurar al-Hikam, Nobility and the noble- §6', 'wisdom'),
  ('يُسْتَدَلُّ عَلى نُبْلِ الرَّجُلِ بِقِلَّةِ مَقالِهِ وعَلى تَفَضُّلِهِ بِكَثْرَةِ إحْتِمالِهِ.', 'The nobility of a man is evinced by the paucity of his speech and his merit is deduced from his abundant tolerance.', 'Ghurar al-Hikam, Nobility and the noble- §7', 'wisdom'),
  ('كُوُنُوا قَوْماً صيحَ بِهِمْ فَانْتَـبَهُوا.', 'Be a community that is cried out to so they wake up.', 'Ghurar al-Hikam, Attentiveness- §1', 'wisdom'),
  ('إنْتِباهُ الْعُيُونِ لايَنْفَعُ مَعَ غَفْلَةِ القُلُوبِ.', 'Alertness of the eyes does not benefit while the hearts are negligent.', 'Ghurar al-Hikam, Attentiveness- §2', 'wisdom'),
  ('ألا مُتَنَبِّهٌ مِنْ رَقْدَتِهِ قَبْلَ حِينِ مَنِيَّتِهِ.', 'Is there no one who will wake from his slumber before the time of his death?!', 'Ghurar al-Hikam, Attentiveness- §3', 'wisdom'),
  ('اِسْتَمِعُوا مِنْ رَبّانِيِّكُمْ وأَحْضِرُوهُ قُلُوبَكُمْ واسْمَعُوا إنْ هَتَفَ بِكُمْ.', 'Listen to your godly leader, keep your hearts open for him and listen [to him] if he calls out to you.', 'Ghurar al-Hikam, Prophets, Messengers and Imams- §1', 'wisdom'),
  ('اِسْمَعُوا (اِقْبَلُوا) النَّصِيْحَةَ مِمّنْ أهْداها إلَيْكُمْ واعْقِلُوها عَلى أنْفُسِكُمْ.', 'Listen to (or accept) advice from the one who gifts it to you and preserve it in your minds.', 'Ghurar al-Hikam, Prophets, Messengers and Imams- §2', 'wisdom'),
  ('رُسُلُ اللّهِ سُبْحانَهُ تَراجِمَةُ الْحَقِّ والسُّفَراءُ بَيْنَ الْخالِقِ وَالْخَلْقِ.', 'Messengers of Allah, the Glorified, are interpreters of the truth and intermediaries between the Creator and the creation.', 'Ghurar al-Hikam, Prophets, Messengers and Imams- §3', 'wisdom'),
  ('لِرُسُلِ اللّهِ في كُلِّ حُكْم تَبْيِينٌ.', 'The Messengers of Allah have a clear elucidation for every [divine] command.', 'Ghurar al-Hikam, Prophets, Messengers and Imams- §4', 'wisdom'),
  ('أنْجَحُكُمْ أصْدَقُكُمْ.', 'The most successful of you are the most truthful among you.', 'Ghurar al-Hikam, Success, prosperity and salvation- §1', 'wisdom'),
  ('أدْرَكُ النّاسِ لِحاجَتِهِ ذُو الْعَقْلِ الْمُتَرَفِّقُ.', 'The person who attains his objective the most is one who has intelligence and is mild-mannered.', 'Ghurar al-Hikam, Success, prosperity and salvation- §2', 'wisdom'),
  ('إنْ كُنْتُمْ لِلنَّجاةِ طالِبِينَ فَارْفَضُوا الْغَفْلَةَ واللَّهْوَ والْزَمُوا الاِجْتِهادَ والْجِدَّ.', 'If you seek of prosperity, then reject negligence and diversion, and espouse diligence and effort.', 'Ghurar al-Hikam, Success, prosperity and salvation- §3', 'wisdom'),
  ('آفَةُ النُّجْحِِ اَلْكَسَلُ.', 'The bane of success is laziness.', 'Ghurar al-Hikam, Success, prosperity and salvation- §4', 'wisdom'),
  ('قَدْ يُنالُ النُّجْحُ.', 'At times success may be attained.', 'Ghurar al-Hikam, Success, prosperity and salvation- §5', 'wisdom'),
  ('قَدْ يُعْيِي إنْدِمالُ الْجُرْحِ.', 'The healing of a wound may at times lead to disability.', 'Ghurar al-Hikam, Success, prosperity and salvation- §6', 'wisdom'),
  ('ما أقْرَبَ النَّجاحَ مِمَّنْ عَجَّلَ السَّراحَ.', 'How close is success to one who is quick to release [and send forth his provisions for the Hereafter].', 'Ghurar al-Hikam, Success, prosperity and salvation- §7', 'wisdom'),
  ('مِلاكُ النَّجاةِ لُزُومُ الإيمانِ وصِدْقُ الإيقانِ.', 'The basis of salvation is espousing faith and [having] true certitude.', 'Ghurar al-Hikam, Success, prosperity and salvation- §8', 'wisdom'),
  ('لا يَفُوزُ بِالنَّجاةِ إلاّ مَنْ قامَ بِشَرائِطِ الإيمانِ.', 'None is successful in attaining salvation but the one who fulfils the requirements of faith.', 'Ghurar al-Hikam, Success, prosperity and salvation- §9', 'wisdom'),
  ('لانَجاةَ لِمَنْ لاإيمانَ لَهُ.', 'There is no salvation for one who has no faith.', 'Ghurar al-Hikam, Success, prosperity and salvation- §10', 'wisdom'),
  ('مَنِ اسْتَنْجَدَ ذَليلاًذَلَّ.', 'One who seeks help from the lowly is abased.', 'Ghurar al-Hikam, Help and seeking help- §1', 'wisdom'),
  ('مَنْ لَمْ يُنْجِدْ لَمْ يُنْجَدْ.', 'One who does not help [others] is not helped.', 'Ghurar al-Hikam, Help and seeking help- §2', 'wisdom'),
  ('لاخَيْـرَ فِي الْمُناجاةِ إلاّ لِرَجُلَيْنِ:عالِم ناطِق، أوْ مُسْتَمِع واع.', 'There is no good in secret conversation except for two people: the articulating scholar or the cautious listener [who can keep secrets].', 'Ghurar al-Hikam, Secret conversation- §1', 'wisdom'),
  ('اَلنَّدَمُ أحَدُ التَوْبَتَيْنِ.', 'Remorse is one of the two [forms of] repentance.', 'Ghurar al-Hikam, Remorse and regret- §1', 'wisdom'),
  ('اِنْدَمْ عَلى ما أسَأْتَ ولاتَنْدَمْ عَلى مَعْرُوف صَنَعْتَ.', 'Be remorseful about the evil that you have done and do not regret the good act that you have performed.', 'Ghurar al-Hikam, Remorse and regret- §2', 'wisdom'),
  ('اَلنَّدَمُ اِسْتِغْفارٌ.', 'Remorse is [a form of] repentance.', 'Ghurar al-Hikam, Remorse and regret- §3', 'wisdom'),
  ('اَلنَّدَمُ عَلَى الْخَطيِئَةِ يَمْحُوها.', 'Being remorseful for a misdeed causes it to be wiped off.', 'Ghurar al-Hikam, Remorse and regret- §4', 'wisdom'),
  ('اَلنَّدَمُ عَلَى الخَطِيئَةِ اِسْتِغْفارٌ.', 'Being remorseful for a misdeed is [a form of] repentance.', 'Ghurar al-Hikam, Remorse and regret- §5', 'wisdom'),
  ('اَلنَّدَمُ عَلَى الذَّنْبِ يَمْنَعُ مِنْ مُعاوَدَتِهِ.', 'Being remorseful for [committing] a sin prevents one from returning to it.', 'Ghurar al-Hikam, Remorse and regret- §6', 'wisdom'),
  ('نَدَمُ الْقَلْبِ يُكَفِّرُ الذَّنْبَ ويُمَحِّصُ الجَرِيرَةَ.', 'Remorsefulness of the heart covers up the sin and purges the wrongdoing.', 'Ghurar al-Hikam, Remorse and regret- §7', 'wisdom'),
  ('طُوبى لِكُلِّ نادِم عَلى زَلَّتِهِ مُسْتَدْرِك فارِطَ عَثْرَتِهِ.', 'Blessed is every remorseful one who regrets his mistake and makes up for his past error.', 'Ghurar al-Hikam, The remorseful- §1', 'wisdom'),
  ('مَنْ نَدِمَ فَقَدْ تابَ.', 'One who is remorseful has repented.', 'Ghurar al-Hikam, The remorseful- §2', 'wisdom'),
  ('اَلإنْذارُ إعْذارٌ.', 'Warning is vindication.', 'Ghurar al-Hikam, Warning- §1', 'wisdom'),
  ('لاتُلاحِ الدَّنِيَّ فَيَجْتَرِئَ عَلَيْكَ.', 'Do not argue with a vile person for he will be bold [and disrespectful] with you.', 'Ghurar al-Hikam, Dispute- §1', 'wisdom'),
  ('لاتُنازِ عِ السُّفَهاءَ ولاتَسْتَهْتِرْ بِالنِّساءِ فَإنَّ ذلِكَ يُزْري بِالْعُقَلاءِ.', 'Do not dispute with the fools and do not be infatuated with women, for indeed this degrades the intelligent ones.', 'Ghurar al-Hikam, Dispute- §2', 'wisdom'),
  ('مُنازَعةُ السَّفَل تَشينُ السّادَةَ.', 'Disputing with the ignoble ones disgraces the [status of the] eminent ones.', 'Ghurar al-Hikam, Dispute- §3', 'wisdom'),
  ('اَلمَنْزِلُ البَهِيُّ أحَدُ الْجَنَّتَيْنِ.', 'A beautiful home is one of the two Paradises.', 'Ghurar al-Hikam, The home- §1', 'wisdom'),
  ('مَنْ ضاقَتْ ساحَتُهُ قَلَّتْ راحَتُهُ.', 'One whose space is restricted, his comfort is less.', 'Ghurar al-Hikam, The home- §2', 'wisdom'),
  ('اِحْذَرْ مَنازِلَ الْغَفْلَةِ والْجَفاءِ وقِلَّةَ الأعْوانِ عَلى طاعَةِ اللّهِ.', 'Avoid [building homes in] places of negligence and wickedness and [places where] there is a paucity of supporters for the obedience of Allah.', 'Ghurar al-Hikam, The home- §3', 'wisdom'),
  ('كَمْ مِنْ بان مالا يَسْكُنُهُ.', 'How many a builder has built that which he does not reside in.', 'Ghurar al-Hikam, The home- §4', 'wisdom'),
  ('التَّنَـزُّهُ عَنِ المعاصي عِبادَةُ التَّوابِيْنَ.', 'Remaining free from sins is the worship of the penitents.', 'Ghurar al-Hikam, Remaining pure and free from sin- §1', 'forgiveness'),
  ('اَلنَّزاهَةُ عَيْنُ الظَّرْفِ.', 'Keeping away from sin is the essence of astuteness.', 'Ghurar al-Hikam, Remaining pure and free from sin- §2', 'forgiveness'),
  ('اَلتَّنَـزُّهُ أوَّلُ النُّبْلِ.', 'Remaining free from sin is the beginning of nobility.', 'Ghurar al-Hikam, Remaining pure and free from sin- §3', 'forgiveness'),
  ('اَلنَّزاهَةُ آيَةُ العِفَّةِ.', 'Keeping away from sin is the sign of chastity.', 'Ghurar al-Hikam, Remaining pure and free from sin- §4', 'forgiveness'),
  ('اَلنَّزاهَةُ مِنْ شِيَمِ النُّفُوسِ الطّاهِرَةِ.', 'Keeping away from sin is one of the traits of the immaculate souls.', 'Ghurar al-Hikam, Remaining pure and free from sin- §5', 'forgiveness'),
  ('كُنْ مُتَنَزِّهاً تَكُنْ تَقِيّاً.', 'Be free from sin and you will be pious.', 'Ghurar al-Hikam, Remaining pure and free from sin- §6', 'forgiveness'),
  ('رُبَّ نُزْهَة عادَتْ نُغْصَةً.', 'Sometimes an outing may turn into a bitter experience.', 'Ghurar al-Hikam, Outing- §1', 'wisdom'),
  ('قَدْ تَنْقَلِبُ النُّـزْهَةُ غُصَّةً.', 'An outing may turn into an agony.', 'Ghurar al-Hikam, Outing- §2', 'wisdom'),
  ('رُبَّ مُتَنَسِّك ولادينَ لَهُ.', 'A person may be a devotee while he [actually] has no religion.', 'Ghurar al-Hikam, The devotee- §1', 'wisdom'),
  ('اَلنِّساءُ أعْظَمُ الفِتْنَـتَيْنِ.', 'Women are the greater of the two temptations.', 'Ghurar al-Hikam, Women- §1', 'wisdom'),
  ('اَلنِّساءُ لَحْمٌ عَلى وَضَم إلاّ ما ذُبَّ عَنْهُ.', 'Women are [like] meat on the butcher’s block, except that which is protected [and defended].', 'Ghurar al-Hikam, Women- §2', 'wisdom'),
  ('اِتَّقُوا شِرارَ النِّساءِ، وكـُونُوا مِنْ خِيارِهِنَّ عَلى حَذَر.', 'Beware of evil women, and be on your guard [even] from the good among them.', 'Ghurar al-Hikam, Women- §3', 'wisdom'),
  ('إيّاكَ وكَثْرَةَ الْوَلَهِ بِالنِّساءِ، والإغْراءَ(الاِغْتِرارَ) بِلَذّاتِ الدُّنيا، فَإنَّ الْوَلِهَ بِالنِّساءِ مُمْتَحَنٌ، والغَرِيَّ بِاللَّذّاتِ مُمْتَهَنٌ.', 'Beware of excessive infatuation with women and being tempted (or deceived) by the pleasures of this world, for indeed the one who is infatuated with women faces trials and the one who is tempted by the pleasures [of this world] is abased.', 'Ghurar al-Hikam, Women- §4', 'wisdom'),
  ('إيّاكَ ومُشاوَرَةَ النِّساءِ، فَإنَّ رَأْيَهُنَّ إلى أفَن، وعَزْمَهُنَّ إلى وَهَن، وَاكْفُفْ عَلَيْهِنَّ مِنْ أبْصارِهِنَّ، فَحِجابُكَ لَهُنَّ خَيْـرٌ مِنَ الاِرْتِيابِ بِهِنَّ، ولَيْسَ خُرُوجُهُنَّ بِشَـرّ مِنْ إدْخالِكَ مَنْ لايُوثَقُ بِِهِ عَلَيْهِنَّ، وإنِ اسْتَطَعْتَ أنْ لا يَعْرِفْنَ (لا يَعْرِفَهُنَّ) غَيْرَكَ فَافْعَلْ.', 'Beware of consulting with women, for indeed their opinions are inclined towards immaturity and their decisions are infirm; and restrain their gazes [by keeping them behind the veil], for your veiling them is better than being suspicions about them, and their coming out [in public] is not worse than your letting one who cannot be trusted enter their abode; and if you are able to ensure that they do not get acquainted with anybody other than you then do it.', 'Ghurar al-Hikam, Women- §5', 'wisdom'),
  ('إنَّ النِّساءَ هَمُّهُنَّ زِينَةُ الْحَياةِ الدُّنيا والْفَسادُ فِيها.', 'Verily women are [only] concerned about the ornaments of this world and [creating] mischief herein.', 'Ghurar al-Hikam, Women- §6', 'wisdom'),
  ('اَلاِسْتِهْتارُ بِالنِّساءِ شِيمَةُ النَّوْكى.', 'Being infatuated with women is the trait of the foolish.', 'Ghurar al-Hikam, Women- §7', 'wisdom'),
  ('إنْ رَأَيْتَ مِنْ نِسائِكَ ريبَةً، فاجْعَلْ لَهُنَّ النَّكِيرَ عَلَى الكَبِيرِ والصَّغِيرِ وإيّاكَ أنْ تُـكَرِّرَ الْعَتْبَ، فَإنَّ ذلِكَ يُغْرِي بِالذَّنْبِ، ويُهَوِّنُ العَتْبَ.', 'If you see something suspicious from your women, then assign to them a guard who will watch over the old and young [among the family, and not for the women in particular as this will cause them unease], and beware not to continuously scold them for this will incite them to commit sins and make it easy for them to bear the scolding [as they will become accustomed to it].', 'Ghurar al-Hikam, Women- §8', 'wisdom'),
  ('خَيْرُ خِصالِ النِّساءِ شَـرُّ خِصالِ الرِّجالِ.', 'The best of traits for women is the worst of traits for men.', 'Ghurar al-Hikam, Women- §9', 'wisdom'),
  ('طاعَةُ النِّساءِ غايَةُ الْجَهْلِ.', 'Obedience to women is the height of ignorance.', 'Ghurar al-Hikam, Women- §10', 'wisdom'),
  ('مَنْ نَسِيَ اللّهَ أنْساهُ نَفْسَهُ.', 'Whoever forgets Allah, He makes him forget himself.', 'Ghurar al-Hikam, Forgetting Allah- §1', 'wisdom'),
  ('النِّسْيانُ ظُلْمَةٌ وفَقْدٌ.', 'Forgetting [Allah] is darkness and loss.', 'Ghurar al-Hikam, Forgetting Allah- §2', 'wisdom'),
  ('مَنْ نَسِيَ سُبْحانَهُ أنْساهُ اللّهُ نَفْسَهُ وأعْمى قَلْبَهُ.', 'One who forgets [Allah,] the Glorified, Allah makes him forget himself and blinds his heart.', 'Ghurar al-Hikam, Forgetting Allah- §3', 'wisdom'),
  ('اَلنُّصْحُ يُثْمِرُ الْمَحَبَّةَ.', 'Sincere advice reaps affection.', 'Ghurar al-Hikam, Sincere advice- §1', 'forgiveness'),
  ('اَلنَّصِيحَةُ مِنْ أخْلاقِ الْكِرامِ.', 'Giving sincere advice is a characteristic of the noble ones.', 'Ghurar al-Hikam, Sincere advice- §2', 'forgiveness'),
  ('رُبَّما نَصَحَ غَيْرُ النّاصِحِ.', 'Sometimes advice is given by one who is not sincere.', 'Ghurar al-Hikam, Sincere advice- §3', 'forgiveness'),
  ('رُبَّما غَشَّ الْمُسْتَنْصَحُ.', 'At times one from whom sincere advice is sought, deceives.', 'Ghurar al-Hikam, Sincere advice- §4', 'forgiveness'),
  ('طُوبى لِمَنْ أطاعَ ناصِحاً يَهْديهِ وتَجَنَّبَ غاوِياً يُرْدِيهِ.', 'Blessed is the one who follows the adviser who guides him and keeps away from the misguided person who leads him to destruction.', 'Ghurar al-Hikam, Sincere advice- §5', 'forgiveness'),
  ('قَدْ جَهِلَ مَنِ اسْتَنْصَحَ أعْدائَهُ.', 'He who seeks advice from his enemies is indeed ignorant.', 'Ghurar al-Hikam, Sincere advice- §6', 'forgiveness'),
  ('قَدْ نُصِحْتُمُ فَانْتَصِحُوا وبُصِّرْتُمْ فَأبْصِرُوا وأُرْشِدْتُمْ فاسْتَرْشِدُوا.', 'You have been advised so take the advice, you have been shown [the truth] so see [it], and you have been guided aright so accept the guidance.', 'Ghurar al-Hikam, Sincere advice- §7', 'forgiveness'),
  ('قَدْ دُلِلْتُمْ إنِ اسْتَدْلَلْتُمْ وَوُعِظْتُمْ إنِ اتَّعَظْتُمْ ونُصِحْتُمْ إنِ انْتَصَحْتُمْ.', 'You have been guided if you seek guidance and have been admonished if you seek admonishment and have been advised if you seek advice.', 'Ghurar al-Hikam, Sincere advice- §8', 'forgiveness'),
  ('كَيْفَ يَنْتَفِعُ بِالنَّصِيحَةِ مَنْ يَلْتَذُّ بِالفَضِيحَةِ؟!', 'How can one who takes pleasure in [acts that bring] disgrace benefit from sincere advice?!', 'Ghurar al-Hikam, Sincere advice- §9', 'forgiveness'),
  ('مَنْ تاجَرَكَ بِالنُّصْحِ فَقَدْ أجْزَلَ لَكَ الرِّبْحَ.', 'One who trades with you by [giving you] advice has indeed made your profit abound.', 'Ghurar al-Hikam, Sincere advice- §10', 'forgiveness'),
  ('إنْ كُنْتُمْ لامُحالَةَ مُتَعَصَّبينَ فَتَعَصَّبُوا لِنُصْرَةِ الْحَقِّ وإغاثَةِ الْمَلْهُوفِ.', 'If you must be fanatical, then be fanatical in assisting the truth and aiding the aggrieved.', 'Ghurar al-Hikam, Supporting the truth- §1', 'wisdom'),
  ('لَوْ لَمْ تَتَخاذَلُوا عَنْ نُصْرَةِ الْحَقِّ لَمْ تَهِنُوا عَنْ تَوْهِينِ الْباطِلِ.', 'If you had not turned away from assisting the truth, you would not have felt weakness in overpowering falsehood.', 'Ghurar al-Hikam, Supporting the truth- §2', 'wisdom'),
  ('مَنْ نَصَرَ الْحَقَّ أفْلَحَ.', 'One who assists the truth shall be successful.', 'Ghurar al-Hikam, Supporting the truth- §3', 'wisdom'),
  ('اُنْصُرِ اللّهَ بِقَلْبِكَ ولِسانِكَ ويَدِكَ فَإنَّ اللّهَ سُبْحانَهُ قَدْ تَكَفَّلَ بِنُصْرَةِ مَنْ يَنْصُرُهُ.', 'Assist Allah with your heart, your tongue and your hand, for indeed Allah, the Glorified, has guaranteed assistance to one who assists Him.', 'Ghurar al-Hikam, Supporting the truth- §4', 'wisdom'),
  ('مَنْ نامَ عَنْ نُصْرَةِ وَلِيِّهِ اِنْتَـبَهَ بِوَطْأَةِ عَدُوِّهِ.', 'One who neglects to assist his friend is awoken by the footsteps of his [advancing] enemy.', 'Ghurar al-Hikam, Supporting the truth- §5', 'wisdom'),
  ('مَنْ أحَدَّ سِنانَ الْغَضَبِ لِلّهِ سُبْحانَهُ قَوِيَ عَلى أشِدّاءِ الْباطِلِ.', 'He who sharpens the spearhead of anger for the sake of Allah acquires the strength to defeat the stalwarts of falsehood.', 'Ghurar al-Hikam, Supporting the truth- §6', 'wisdom'),
  ('لَمْ يَعْدَمِ النَّصْرَ مَنِ انْتَصَرَ بِالصَّبْرِ.', 'One who seeks assistance through patience will not be deprived of victory.', 'Ghurar al-Hikam, Supporting the truth- §7', 'wisdom'),
  ('مَنْ نَصَرَ الباطِلَ خَسِرَ.', 'One who assists falsehood faces loss.', 'Ghurar al-Hikam, Supporting falsehood- §1', 'wisdom'),
  ('مَنِ انْتَصَرَ بِأعْداءِ اللّهِ اِسْتَحَقَّ الْخِذْلانَ.', 'Whoever seeks support from the enemies of Allah deserves to be forsaken.', 'Ghurar al-Hikam, Seeking support- §1', 'wisdom'),
  ('مَنْ إنْتَصَرَ بِاللّهِ عَزَّ نَصْـرُهُ.', 'Whoever seeks support from Allah attains a glorious victory.', 'Ghurar al-Hikam, Seeking support- §2', 'wisdom'),
  ('مَنْ يَكُنِ اللّهُ نَصِيرَهُ يَغْلِبُ خَصْمَهُ ويَكُنْ لَهُ حِزْباً.', 'One whose helper is Allah gains victory over his enemy and gains [in Him] the support [like that] of a [large] group.', 'Ghurar al-Hikam, One whose supporter is Allah- §1', 'wisdom'),
  ('لا يَنْتَصِفُ الْبَرُّ مِنَ الفاجِرِ.', 'The virtuous one does not seek justice from the vicious.', 'Ghurar al-Hikam, Seeking justice- §1', 'justice'),
  ('لا يَنْـتَصِفُ عالِمٌ مِنْ جاهِل.', 'A scholar does not seek justice from an ignorant person.', 'Ghurar al-Hikam, Seeking justice- §2', 'justice'),
  ('لا يَنْـتَصِفُ الكَريمُ مِنَ اللَّئِيمِ.', 'The noble person does not seek justice from the wicked.', 'Ghurar al-Hikam, Seeking justice- §3', 'justice'),
  ('لا يُنْـتَصَفُ مِنْ سَفِيه قَطُّ إلاّ بِالحِلْمِ عَنْهُ.', 'Justice can never be sought from the foolish one except by being forbearing with him.', 'Ghurar al-Hikam, Seeking justice- §4', 'justice'),
  ('اَلإنْصافُ راحَةٌ، اَلشَّرُ وَقاحَةٌ.', 'Equity is [a source of] comfort, evil is [a sign of] impudence.', 'Ghurar al-Hikam, Equity- §1', 'wisdom'),
  ('اَلإنْصافُ عُنْوانُ النُّبْلِ.', 'Equity is a symbol of nobility.', 'Ghurar al-Hikam, Equity- §2', 'wisdom'),
  ('اَلإنْصافُ شيمَةُ الأشْرافِ.', 'Equity is a trait of the honourable ones.', 'Ghurar al-Hikam, Equity- §3', 'wisdom'),
  ('اَلإنْصافُ أفْضَلُ الْفَضائِلِ.', 'Equity is the most superior of merits.', 'Ghurar al-Hikam, Equity- §4', 'wisdom'),
  ('ـ اَلإنْصافُ مِنَ النَّفْسِ كَالْعَدْلِ فِي الإمـْرَةِ.', 'Being equitable with others is like being just [while] in authority.', 'Ghurar al-Hikam, Equity- §6', 'wisdom'),
  ('إنَّ أعْظَمَ المَثُوبَةِ مَثُوبَةُ الإنْصافِ.', 'Indeed the greatest reward is the reward of [justice and] equity.', 'Ghurar al-Hikam, Equity- §7', 'wisdom'),
  ('إنَّكَ إنْ أنْصَفْتَ مِنْ نَفْسِكَ أزْلَفَكَ اللّهُ.', 'Verily if you show fairness to others, Allah will bring you closer [to Him].', 'Ghurar al-Hikam, Equity- §11', 'wisdom'),
  ('بِالنَّصَفَةِ تَدُومُ الْوُصْلَةُ.', 'Through fairness relationships last.', 'Ghurar al-Hikam, Equity- §12', 'wisdom'),
  ('ثَلاثَةٌ لا يَنْتَصِفُونَ مِنْ ثَلاثَة أبَداً: اَلْعاقِلُ مِنَ الأحْمَقِ، والْبَـرُّ مِنَ الْفاجِرِ، والْكَريمُ مِنَ اللَّئِيمِ.', 'Three types of people never seek justice from three other types: the intelligent person from the fool, the virtuous from the vicious, and the noble one from the wicked.', 'Ghurar al-Hikam, Equity- §13', 'wisdom'),
  ('عَلَى الإنْصافِ تَرْسُخُ الْمَوَّدَةُ.', 'It is on equity that affection is established.', 'Ghurar al-Hikam, Equity- §14', 'wisdom'),
  ('اَلمُنْصِفُ كَثِيرُ الأوْلِياءِ والأوِدّاءِ.', 'The equitable person has many friends and intimates.', 'Ghurar al-Hikam, The equitable- §1', 'wisdom'),
  ('أنْصَفُ النّاسِ مَنْ أنْصَفَ مِنْ نَفْسِهِ مِنْ غَيْرِ حاكِم عَلَيْهِ.', 'The most equitable of people is one who shows fairness himself, without being compelled to do so by any authority.', 'Ghurar al-Hikam, The equitable- §2', 'wisdom'),
  ('إنَّ مِنْ فَضْلِ الرَّجُلِ أنْ يُنْصِفَ مِنْ نَفْسِهِ، ويُحْسِنَ إلى مَنْ أساءَ إلَيْهِ.', 'Indeed it is from the merit of a man to be fair with others, and to do good to the one who does him evil.', 'Ghurar al-Hikam, The equitable- §3', 'wisdom'),
  ('اَلمُنْصِفُ كَرِيمٌ، اَلظّالِمُ لَئِيمٌ.', 'The equitable person is noble whereas the oppressor is wicked.', 'Ghurar al-Hikam, The equitable- §4', 'wisdom'),
  ('لاخَيْـرَ فِي المَنْظَرِ إلاّ مَعَ حُسْنِ المَخْبَرِ.', 'There is no good in that which is viewed except when accompanied with a good source of information [or good elocution].', 'Ghurar al-Hikam, The viewed- §1', 'wisdom'),
  ('إجْعَلْ لِكُلِّ إنْسان مِنْ خَدَمِكَ عَمَلاً تَأْخُذُهُ بِهِ فَإنَّ ذلِكَ أحْرى أنْ لا يَتَواكَلُوا في خِدْمَتِكَ.', 'Assign for each one of your servants work that you hold him responsible for, as indeed this is more appropriate to ensure that they do not depend upon one another in your service.', 'Ghurar al-Hikam, Being systematic in work- §1', 'wisdom'),
  ('اَلنِّعْمَةُ مَوْصُولَةٌ بِالشُّكْرِ، والشُّكْرُ مَوْصُولٌ بِالْمَزِيدِ، وهُما مَقْرُونانِ في قَرَن، فَلَنْ يَنْقَطِعَ المَزِيدَ مِنَ اللّهِ سُبْحانَهُ حَتّى يَنْقَطِعَ الشُّكْرُ مِنَ الشَّاكِرِ.', 'Blessing is linked to gratitude and gratitude is linked to increase [in blessings], and these two are linked together in one chain, for increase [in blessings] from Allah, the Glorified, will never cease until the gratitude of the thankful one ceases.', 'Ghurar al-Hikam, Blessing- §1', 'forgiveness'),
  ('اِسْتَصْلِحْ كُلَّ نِعْمَة أنْعَمَهَا اللّهُ عَلَيْكَ، وَلاتُضِعْ نِعْمَةً مِنْ نِعَمِ اللّهِ عِنْدَكَ.', 'Seek good out of every blessing that Allah has bestowed upon you and do not waste any favour of Allah over you.', 'Ghurar al-Hikam, Blessing- §2', 'forgiveness'),
  ('ولْـيُرَ عَلَيْكَ أثَرُ ما أنْعَمَ اللّهُ سُبْحانَهُ بِهِ عَلَيْكَ.', 'Let the effect of that which Allah, the Glorified, has blessed you with be seen on you.', 'Ghurar al-Hikam, Blessing- §3', 'forgiveness'),
  ('اِسْتَتِمُّوا نِعَمَ اللّهِ عَلَيْكُمْ بِالصَّبْرِ عَلى طاعَتِهِ، والْمُحافَظَةِ عَلى مَا اسْتَحْفَظَكُمْ مِنْ كتابِهِ.', 'Seek the perfection of Allah’s blessing upon you through patience in obedience to Him and preserving that which He has commanded you to preserve [and act upon] of His book.', 'Ghurar al-Hikam, Blessing- §4', 'forgiveness'),
  ('اِحْذَرُوا نِفارَ النِّعَمِ فَما كُلُّ شارِد بِمَرْدُود.', 'Beware of the slipping away of blessings, for not everything that runs away comes back.', 'Ghurar al-Hikam, Blessing- §5', 'forgiveness'),
  ('الا وإنَّ مِنَ النِّعَمِ سَعَةُ الْمالِ، وأفْضَلُ مِنْ سَعَةِ المالِ صِحَّةُ الْبَدَنِ، وأفْضَلُ مِنْ صِحَّةِ الْبَدَنِ تَقْوَى الْقَلْبِ.', 'Indeed, one of the blessings is affluence, but good health is better than affluence, and the God-wariness of the heart is [even] better than good health.', 'Ghurar al-Hikam, Blessing- §6', 'forgiveness'),
  ('أفْضَلُ ما مَنَّ اللّهُ سُبْحانَهُ بِهِ عَلى عِبادِهِ: عِلْمٌ، وعَقْلٌ، ومُلْكٌ وَعَدْلٌ.', 'The best things that Allah, the Glorified, has blessed his servants with are: knowledge, intelligence, power and justice.', 'Ghurar al-Hikam, Blessing- §7', 'forgiveness'),
  ('أحْسَنُ النّاسِ حالاً فِي النِّعَمِ مَنِ اسْتَدامَ حاضِرَها بِالشُّكْرِ وارْتَجَعَ فائِتَها بِالصَّبْرِ.', 'The person who is in the best condition of all people is he who makes present blessings last by being grateful for them and gets those that are lost restored through patience.', 'Ghurar al-Hikam, Blessing- §8', 'forgiveness'),
  ('أقَلُّ ما يَلْزَمُكُمْ لِلّهِ تَعالى أنْ لاتَسْتَعِينُوا بِنِعَمِهِ عَلى مَعاصِيهِ.', 'The least that you must do for Allah, the Most High, is ensure that you do not use His blessings as a means of disobeying [and sinning against] Him.', 'Ghurar al-Hikam, Blessing- §9', 'forgiveness'),
  ('إنَّ لِلّهِ سُبْحانَهُ عِباداً يَخْتَصُّهُمْ بِالنِّعَمِ لِمَنافِعِ الْعِبادِ، يُقِرُّ ها فِي أيْدِيهِمْ ما بَذَلُوها فَإذا مَنَعُوها نَزَعَها مِنْهُمْ وحَوَّلَها إلى غَيْرِهِمْ.', 'Verily Allah, the Glorified, has certain selected servants upon whom He bestows blessings for the benefit of the people, causing these [blessings] to remain in their possession as long as they grant them [to the people], but if they withhold them [from the people], He takes away these blessings from them and transfers them to others.', 'Ghurar al-Hikam, Blessing- §10', 'forgiveness'),
  ('بِقَدْرِ السُّرُورِ اَلتَّنْغيصُ.', 'To the extent of happiness there is trouble.', 'Ghurar al-Hikam, Trouble- §1', 'wisdom'),
  ('لالَذَّةَ بِتَنْغِيص.', 'There is no pleasure with trouble.', 'Ghurar al-Hikam, Trouble- §2', 'wisdom'),
  ('كُلُّ شَيْء يَنْفُرُ مِنْ ضِدِّهِ.', 'Everything is averse to its opposite.', 'Ghurar al-Hikam, Aversion- §1', 'wisdom'),
  ('عَرِّجُوا عَنْ طَريقِ المُنافَرَةِ وضَعُوا تِيجانَ الْمُفاخَرَةِ.', 'Turn away from the path of mutual aversion and abandon the crowns of boastfulness.', 'Ghurar al-Hikam, Aversion- §2', 'wisdom'),
  ('اَلنَفْسُ الْكَريمَةُ لاتُؤَثِّرُ فِيهَا النَّكِباتُ.', 'The noble soul is not affected by misfortunes.', 'Ghurar al-Hikam, The soul and holding it to account- §1', 'wisdom'),
  ('اَلنَّفْسُ الشَّريفَةُ لاتَثْقُلُ عَلَيْهَا المَؤُناتُ.', 'The honourable soul does not find it difficult to [spend wealth in order to] acquire provisions.', 'Ghurar al-Hikam, The soul and holding it to account- §2', 'wisdom'),
  ('اَلنَّفْسُ الدَّنِيَّةُ لاتَنْفَكُّ عَنِ الدَّنائاتِ.', 'The ignoble soul does not separate from [its] vile attributes.', 'Ghurar al-Hikam, The soul and holding it to account- §3', 'wisdom'),
  ('إزْراءُ الرَّجُلِ عَلى نَفْسِهِ بُرْهانُ رَزانَةِ عَقْلِهِ وعُنْوانُ وُفُورِ فَضْلِهِ.', 'A person’s upbraiding of his own soul is evidence of the gravity of his intellect and the symbol of his abundant merit.', 'Ghurar al-Hikam, The soul and holding it to account- §4', 'wisdom'),
  ('اَلنُّفُوسُ طَلِقَةٌ لكِنْ أيْدِى العُقُولِ تُمْسِكُ أعِنَّتَها عَنِ النُّحُوسِ.', 'Souls are free but the hands of the intellects hold their reins and protect them from [wretchedness and] misfortune.', 'Ghurar al-Hikam, The soul and holding it to account- §5', 'wisdom'),
  ('اَلرَّاضِي عَنْ نَفْسِهِ مَغْبُونٌ والواثِقُ بِها مَفْتُونٌ.', 'One who is pleased with himself is cheated and one who is overconfident is faced with affliction.', 'Ghurar al-Hikam, The soul and holding it to account- §6', 'wisdom'),
  ('اَلرَّاضِي عَنْ نَفْسِهِ مَسْتُورٌ عَنْهُ عَيْبُهُ، ولَوْ عَرَفَ فَضْلَ غَيْرِهِ كَساهُ (لَساءَهُ) ما بِهِ مِنَ النَّقْصِ والخُسْرانِ.', 'The one who is pleased with himself cannot see his own faults but if he were to know the merits of others, he would cover up (and feel ashamed of) the faults and flaws that are in him.', 'Ghurar al-Hikam, The soul and holding it to account- §7', 'wisdom'),
  ('اَلنَّفْسُ الأمـّارَةُ المُسَوِّلَةُ تَتَمَلَّقُ تَمَلُّقَ الْمُنافِقِ، وتَتَصَنَّعُ بِشِيمَةِ الصَّدِيقِ المُوافِقِ، حَتّى إذا خَدَعتْ وتَمَكَّنَتْ تَسَلَّطَتْ تَسَلُّطَ العَدُوِّ، وَتَحَكَّمَتْ تَحَكُّمَ الْعُتُوِّ، فَأَوْرَدَتْ مَوارِدَ السُّوءِ.', 'The refractory, alluring soul flatters as the hypocrite flatters and feigns the attribute of an assenting friend, until such a time when it deceives and gains mastery, then it dominates as an enemy would dominate and dictates as the tyrant would dictate, thereby taking one into the places of evil.', 'Ghurar al-Hikam, The soul and holding it to account- §8', 'wisdom'),
  ('أكْرِمْ نَفْسَكَ ما أعانَتْكَ عَلى طاعَةِ اللّهِ.', 'Honour your soul as long as it aids you in the obedience of Allah.', 'Ghurar al-Hikam, The soul and holding it to account- §9', 'wisdom'),
  ('أهِنْ نَفْسَكَ ما جَمَحَتْ بِكَ إلى مَعاصِي اللّهِ.', 'Humiliate your soul as long as it makes you recalcitrant in the disobedience of Allah.', 'Ghurar al-Hikam, The soul and holding it to account- §10', 'wisdom'),
  ('إيّاكَ والإمْساكَ فَإنَّ ما أمْسَكْتَهُ فَوْقَ قُوتِ يَوْمِكَ كُنْتَ فيهِ خازِناً لِغَيْرِكَ.', 'Beware of withholding [charity], for indeed you are [only] a treasurer for someone else in that which you withhold from what is in excess of your daily requirement.', 'Ghurar al-Hikam, Giving and withholding charity- §1', 'generosity'),
  ('إنْ تَبْذُلُوا أمْوالَكُمْ في جَنْبِ اللّهِ فَإنَّ اللّهَ مُسْرِعُ الخَلَفَ.', 'If you spend your wealth for the sake of Allah, then [know that] indeed Allah is quick in recompense.', 'Ghurar al-Hikam, Giving and withholding charity- §2', 'generosity'),
  ('إذا رُزِقْتَ فَأنْفِقْ.', 'When you are blessed with sustenance then give charity.', 'Ghurar al-Hikam, Giving and withholding charity- §3', 'generosity'),
  ('إذا رُزِقْتَ فَأوْسِعْ.', 'When you are blessed with sustenance then give generously.', 'Ghurar al-Hikam, Giving and withholding charity- §4', 'generosity'),
  ('ثِيابُكَ عَلى غَيْرِكَ أبْقى لَكَ مِنْها عَلَيْكَ.', 'Your garments are more lasting for you when worn by others rather than yourself.', 'Ghurar al-Hikam, Giving and withholding charity- §5', 'generosity'),
  ('دِرْهَمٌ يَنْفَعُ خَيْرٌ مِنْ دينار يَصْرَعُ.', 'A dirham that benefits [others] is better than a dinar 1 that throws one into ruin.', 'Ghurar al-Hikam, Giving and withholding charity- §6', 'generosity'),
  ('دِرْهَمُ الفَقيرِ أزْكى عِنْدَ اللّهِ مِنْ دينارِ الغَنِيِّ.', 'The dirham of a poor man is purer in the sight of Allah than the dinar of the rich.', 'Ghurar al-Hikam, Giving and withholding charity- §7', 'generosity'),
  ('رُبَّ يَسير أنْمى مِنْ كَثير.', 'Many a thing that is little grows and develops much more than that which is plenty.', 'Ghurar al-Hikam, Giving and withholding charity- §8', 'generosity'),
  ('قَلِيلٌ لَكَ خَيْرٌ مِنْ كَثير لِغَيْرِكَ.', 'Little that belongs to you is better than plenty that belongs to others.', 'Ghurar al-Hikam, Giving and withholding charity- §9', 'generosity'),
  ('لَيْسَ لأَحَد مِنْ دُنْياهُ إلاّ ما أنْفَقَهُ عَلى أُخْراهُ.', 'Nobody gains anything from his worldly life except that which he spends on others.', 'Ghurar al-Hikam, Giving and withholding charity- §10', 'generosity'),
  ('إيّاكَ والنِّفاقَ فَإنَّ ذَا الوَجْهَيْنِ لايَكُونُ وَجيهاً عِنْدَ اللّهِ.', 'Beware of hypocrisy, for indeed the two-faced person is not eminent in the sight of Allah.', 'Ghurar al-Hikam, Hypocrisy- §1', 'wisdom'),
  ('اَلنِّفاقُ أخُوالشِّرْكِ.', 'Hypocrisy is the brother of polytheism.', 'Ghurar al-Hikam, Hypocrisy- §2', 'wisdom'),
  ('اَلنِّفاقُ شَيْنُ الأخْلاقِ.', 'Hypocrisy is a disgraceful character.', 'Ghurar al-Hikam, Hypocrisy- §3', 'wisdom'),
  ('اَلنِّفاقُ تَوْأَمُ الكُفْرِ.', 'Hypocrisy is the twin of disbelief.', 'Ghurar al-Hikam, Hypocrisy- §4', 'wisdom'),
  ('اَلنِّفاقُ يُفْسِدُ الإيمانَ.', 'Hypocrisy corrupts [one’s] faith.', 'Ghurar al-Hikam, Hypocrisy- §5', 'wisdom'),
  ('اَلنِّفاقُ مِنْ أثافِي الذُّلِّ.', 'Hypocrisy is from the andirons of ignominy.', 'Ghurar al-Hikam, Hypocrisy- §6', 'wisdom'),
  ('اَلنِّفاقُ مَبْنِيٌّ عَلَى المَيْنِ.', 'Hypocrisy is founded on falsehood.', 'Ghurar al-Hikam, Hypocrisy- §7', 'wisdom'),
  ('ما أقْبَحَ بِالإنْسانِ باطِناً عَليلاً وظاهِراً جَميلاً.', 'How reprehensible it is for a human being to have a sick interior and a beautiful exterior.', 'Ghurar al-Hikam, Hypocrisy- §8', 'wisdom'),
  ('اَلمُنافِقُ لِسانُهُ يَسُرُّ وقَلْبُهُ يَضُرُّ.', 'A hypocrite’s tongue pleases but his heart causes harm.', 'Ghurar al-Hikam, The Hypocrite- §1', 'wisdom'),
  ('اَلمُنافِقُ قَوْلُهُ جَمِيلٌ وفِعْلُهُ الدّاءُ الدّخِيلُ.', 'A hypocrite’s words are beautiful but his actions are a painful malady.', 'Ghurar al-Hikam, The Hypocrite- §2', 'wisdom'),
  ('اَلمُنافِقُ وَقِحٌ غَبِيٌّ مُتَمَلِّقٌ شَقِيٌّ.', 'The hypocrite is a shameless, foolish, wretched sycophant.', 'Ghurar al-Hikam, The Hypocrite- §3', 'wisdom'),
  ('اَلمُنافِقُ لِنَفْسِهِ مُداهِنٌ وَعَلَى النّاسِ طاعِنٌ.', 'The hypocrite flatters himself but maligns others.', 'Ghurar al-Hikam, The Hypocrite- §4', 'wisdom'),
  ('أظْهَرُ النّاسِ نِفاقاً مَنْ أمَرَ بِالطّاعَةِ ولَمْ يَعْمَلْ بِها، ونَهى عَنِ المَعْصِيَةِ ولَمْ يَنْتَهِ عَنْها.', 'The most obvious of hypocrite among the people is one who enjoins obedience [to Allah] but does not act upon it himself, and forbids sin but does not refrain from it himself.', 'Ghurar al-Hikam, The Hypocrite- §5', 'wisdom'),
  ('اِحْذَرُوا أهْلَ النِّفاقِ، فَإنَّهُمْ الضَّالُّونَ المُضِلُّونَ، الزّالُّونَ المُزِلُّونَ، قُلُوبُهُمْ دَوِيَّةٌ، وَصِحافُهُمْ نَقِيَّةٌ.', 'Be cautious of the hypocrites for indeed they are misguided and misguide others, they have erred and make others err, their hearts are diseased while their outward appearance looks pure.', 'Ghurar al-Hikam, The Hypocrite- §6', 'wisdom'),
  ('اَلمُنافِقُ مُريبٌ.', 'The hypocrite is sceptical [and puts others in doubt].', 'Ghurar al-Hikam, The Hypocrite- §7', 'wisdom'),
  ('اَلمُنافِقُ مَكُورٌ مُضِرٌّ، مُرْتابٌ.', 'The hypocrite is sly, harmful and suspicious.', 'Ghurar al-Hikam, The Hypocrite- §8', 'wisdom'),
  ('إنّي أخافُ عَلَيْكُمْ كُلَّ عَليمِ اللِّسانِ مُنافِقِ الجِنانِ، يَقُولُ ماتَعْلَمُونَ وَيَفْعَلُ ما تُنْكِرونَ.', 'I fear for you from every eloquent speaker who is a hypocrite at heart, he says what you know [to be good] but does what you dislike [and know to be bad].', 'Ghurar al-Hikam, The Hypocrite- §9', 'wisdom'),
  ('وقالَ ـ عَلَيْهِ السّلامُ ـ في وَصْفِ المنافِقينَ: حَسَدُ الرَّخاءِ ومُؤَكِّدُوا البَلاءِ، ومُقْنِطُوا الرَّجاءِ، لَهُمْ بِكُلِّ طَريق صَريعٌ، وإلى كُلِّ قَلْبِ شَفيعٌ، وَلِكُلِّ شَجْو دُمُوعٌ.', 'He (‘a) described the hypocrites thus: they are jealous of [those in] comfort, intensify [the] distress [of the distressed] and destroy hopes [of the hopeful]. Their fallen victims are lying on every path, they have means to approach every heart and they have false tears for every [occasion of] grief.', 'Ghurar al-Hikam, The Hypocrite- §10', 'wisdom'),
  ('كَفى بِالْمَرْءِ مَنْقَصَةً أنْ يُعَظِّمَ نَفْسَهُ.', 'It suffices as a deficiency for a man to consider himself as great.', 'Ghurar al-Hikam, Deficiency- §1', 'wisdom'),
  ('اَلمَنْقُوصُ مَسْتُورٌ عَنْهُ عَيْبُهُ.', 'The deficient one is he whose faults are hidden from him.', 'Ghurar al-Hikam, The Deficient- §1', 'wisdom'),
  ('ألْمُبادَرَةُ إلَى الاِنْتِقامِ مِنْ شِيَمِ اللِّئامِ.', 'Rushing to take revenge is from the traits of the wicked.', 'Ghurar al-Hikam, Revenge- §1', 'wisdom'),
  ('أقْبَحُ أفْعالِ المُقْتَدِرِ اَلاِنْتِقامُ.', 'The most revolting act of a powerful person is revenge.', 'Ghurar al-Hikam, Revenge- §2', 'wisdom'),
  ('سُوءُ العُقُوبَةِ مِنْ لُؤْمِ الظَّفَرِ.', 'Evil retribution [and revenge] is from the vileness of victory.', 'Ghurar al-Hikam, Revenge- §3', 'wisdom'),
  ('مَنْ عاقَبَ المُذْنِبَ فَسَدَ فَضْلُهُ.', 'One who punishes the guilty [instead of forgiving him], his merit [and kindness] gets corrupted.', 'Ghurar al-Hikam, Revenge- §4', 'wisdom'),
  ('مَنِ انْتَقَمَ مِنَ الجاني أبْطَلَ فَضْلَهُ فِي الدُّنْيا وفاتَهُ ثَوابُ الآخِرَةِ.', 'Whoever takes revenge on the wrongdoer nullifies his merit in this world and loses the reward of the Hereafter.', 'Ghurar al-Hikam, Revenge- §5', 'wisdom'),
  ('مُعاجَلَةُ الاِنْتِقامِ مِنْ شِيَمِ اللِّئامِ.', 'Being hasty in taking revenge is from the traits of the wicked.', 'Ghurar al-Hikam, Revenge- §6', 'wisdom'),
  ('كَيْفَ لايُوقِظُكَ بَياتُ نِقَمِ اللّهِ وقَدْ تَوَرَّطْتَ بِمَعاصِيهِ مَدارِجَ سَطَواتِهِ؟!', 'How is it that you are not kept awake by the [fear of] Allah’s punishments that befall you by night while you lie in the way of Allah’s wrath because of your disobedience to Him?!', 'Ghurar al-Hikam, Divine wrath- §1', 'wisdom'),
  ('ما أقْرَبَ النَّقِمَةَ مِنْ أهْلِ البَغْيِ(الظُّلْمِ) والعُدْوانِ.', 'How close is the punishment of Allah to the oppressors (or the unjust) and wrongdoers!', 'Ghurar al-Hikam, Divine wrath- §2', 'wisdom'),
  ('اَلا وقَدْ أمَرَنِيَ اللّهُ بِقِتالِ أهْلِ النَّكْثِ، والبَغْىِ، والفَسادِ فِي الأرْضِ، فَأمَّا النّاكِثُونَ فَقَدْ قاتَلْتُ، وأمَّا القاسِطُونَ فَقَدْ جاهَدْتُ، وأمَّا المارِقَةُ فَقَدْ دَوَّخْتُ، وأمّا شَيْطانُ الرَّدْهَةِ فَإنّي كُفيتُهُ بِصَعْقَة سَمِعْتُ لَها وَجيبَ قَلْبِهِ، وَرَجَّةَ صَدْرِهِ.', 'Indeed Allah has commanded me to fight against those who revolt and break pledges and create strife on the earth. As for the defaulters, I have fought them and as for the iniquitous, I have struggled against them and as for the transgressors, I have vanquished them. As for the Satan of the pit, I have dealt with him with an overpowering scream, until I heard the restless beating of his heart and the trembling of his chest.', 'Ghurar al-Hikam, The Defaulters, The Iniquitous And The Transgressors §1', 'wisdom'),
  ('مَنْ أكْثَرَ المَناكِحَ غَشِيَتْهُ الفَضائِحُ.', 'One who marries many women is engulfed by embarrassments.', 'Ghurar al-Hikam, Marraiges- §1', 'wisdom'),
  ('إيّاكَ والنَّمِيمَةَ، فَإنَّها تَزْرَعُ الضَّغِينَةَ، وتُبَعِّدُ عَنِ اللّهِ وَالنّاسِ.', 'Beware of talebearing, for indeed it plants [the seed of] rancour and distances one from Allah and the people.', 'Ghurar al-Hikam, Talebearing- §1', 'wisdom'),
  ('أسْوَءُ الصِّدْقِ النَّمِيمَةُ.', 'The worst [type of] truthful speech is gossip.', 'Ghurar al-Hikam, Talebearing- §2', 'wisdom'),
  ('اَلنَّمِيمَةُ شيمَةُ المارِقِ.', 'Talebearing is the characteristic of a traitor.', 'Ghurar al-Hikam, Talebearing- §3', 'wisdom'),
  ('اَلنَّمِيمَةُ ذَنْبٌ لايُنْسى.', 'Talebearing is an offense [and a sin] that cannot be forgotten.', 'Ghurar al-Hikam, Talebearing- §4', 'wisdom'),
  ('بِئْسَ الشّيمَةُ النَّميمَةُ.', 'The worst trait is talebearing.', 'Ghurar al-Hikam, Talebearing- §5', 'wisdom'),
  ('مَنْ سَعى بِالنَّميمَةِ حارَبَهُ القَريبُ ومَقَتَهُ البَعيدُ.', 'One who seeks to slander [others] by talebearing is fought by the near one and hated by the one who is far [from him].', 'Ghurar al-Hikam, Talebearing- §6', 'wisdom'),
  ('مَنْ نَقَلَ إلَيْكَ نَقَلَ عَنْكَ.', 'One who narrates to you [about others] narrates [to others] about you.', 'Ghurar al-Hikam, Talebearing- §7', 'wisdom'),
  ('لاتَعْجِلَنَّ إلى تَصْديقِ واش وإنْ تَشَبَّهَ بِالنّاصِحينَ فَإنَّ السّاعِيَ ظالِمٌ لِمَنْ سَعى بِهِ غاشٌّ لِمَنْ سَعى إلَيْهِ.', 'Do not be quick in accepting the words of a talebearer, even if he resembles the good advisers, for indeed the slanderer oppresses the one whom he slanders [about] and deceives the one whom he slanders to.', 'Ghurar al-Hikam, Talebearing- §8', 'wisdom'),
  ('لاتَكُونُوا مَساييحَ ولامَذاييعَ.', 'Be neither scandalmongers nor revealers of others’ secrets.', 'Ghurar al-Hikam, Talebearing- §9', 'wisdom'),
  ('لاتَجْتَمِعُ أمانَةٌ ونَميمَةٌ.', 'Trustworthiness and talebearing do not go together.', 'Ghurar al-Hikam, Talebearing- §10', 'wisdom'),
  ('اَلنّاسُ كَصُوَر فِي الصَّحِيفَةِ (صَحيفَة) كُلَّما طُوِيَ بَعْضُها نُشِرَ بَعْضُها.', 'People are like writings on a scroll [of parchment], whenever part of it is rolled up, another part of it is unrolled.', 'Ghurar al-Hikam, People- §1', 'wisdom'),
  ('اَلنّاسُ أبْناءُ الدُّنيا والوَلَدُ مَطْبُوعٌ عَلى حُبِّ أُمِّهِ.', 'People are children of this world, and a child is naturally inclined to love its mother.', 'Ghurar al-Hikam, People- §2', 'wisdom'),
  ('اَلنّاسُ طالِبانِ: طالِبٌ ومَطْلُوبٌ، فَمَنْ طَلَبَ الدُّنيا طَلَبَهُ الْمَوْتُ حَتّى يُخْرِجَهُ عَنْها، ومَنْ طَلَبَ الآخِرَةَ طَلَبَتْهُ الدُّنيا حَتّى يَسْتَوْفِيَ رِزْقَهُ مِنْها.', 'People are divided into two types of seekers, and each seeker is also sought after; so whoever seeks this world is sought after by death until it takes him out from it, and whoever seeks the Hereafter is sought after by this world, until he gets his sustenance from it in full.', 'Ghurar al-Hikam, People- §3', 'wisdom'),
  ('اَلنّاسُ ثَلاثَةٌ: فَعالِمٌ رَبّانيٌّ، ومُتَعَلِّمٌ عَلى سَبِيلِ نَجاة، وهِمَجٌ رِعاعٌ أتْباعُ كُلِّ ناعِق، لَمْ يَسْتَضِيْئُوا بِنُورِ العِلْمِ، ولَمْ يَلْجَئُوا إلى رُكْن وَثيق.', 'People are of three types: the godly scholar, the student who is on the path of salvation and the uncultivated rabble who run after every caller, neither seeking light from the effulgence of knowledge nor taking recourse to any strong support.', 'Ghurar al-Hikam, People- §4', 'wisdom'),
  ('اَلنّاسُ كَالشَّجَرِ شَرابُهُ واحِدٌ، وثَمَرُهُ مُخْتَلِفٌ.', 'People are like trees, their drink is one but their fruits are different.', 'Ghurar al-Hikam, People- §5', 'wisdom'),
  ('اَلنّاسُ مَنْقُوصُونَ مَدْخُولُونَ إلاّ مَنْ عَصَمَ اللّهُ سُبْحانَهُ، سائِلُهُمْ مُتَعَنِّتٌ، ومُجيبُهُمْ مُتَكَلِّفٌ، يَكادُ أفْضَلُهُمْ رَأْياً أنْ يَرُدَّهُ عَنْ فَضْلِ رَأيِهِ الرِّضى وَالسَّخَطُ، ويَكادُ أصْلَبُهُمْ عُوداً تَنْكَأُهُ اللَّحظَةُ وتَسْتَحِيلُهُ الكَلِمَةُ الْواحِدَةُ.', 'People are made deficient and flawed, except those whom Allah, the Glorified, protects. The questioner among them aims to embarrass and confuse while the answerer creates trouble. It is not long until the one who has the best views among them is turned away from his good opinion by pleasure or displeasure, and at any moment the most strong-willed among them will get affected by a single glance or transformed by a single expression.', 'Ghurar al-Hikam, People- §6', 'wisdom'),
  ('اَلنّاسُ فِي الدُّنيا عاملانِ: عاملٌ فِي الدُّنيا لِلدُّنيا، قَدْ شَغَلَتْهُ دُنْياهُ عَنْ آخِرَتِهِ، يَخْشى عَلى مَنْ يُخَلِّفُ الْفَقْرَ، ويَأمَنُهُ عَلى نَفْسِهِ، فَيُفْنِي عُمْرَهُ في مَنْفَعةِ غَيْرِهِ وعامِلٌ فِي الدُّنيا لِما بَعْدَها، فَجائَهُ الَّذي لَهُ بِغَيْرِ عَمَل، فَأحْرَزَ الْحَظَّيْنِ مَعاً، ومَلَكَ الدّارَيْنِ جَميعاً.', 'The people who work in this world are of two types: one works in this world for this world; his world has indeed distracted him from his Hereafter. He fears poverty for those whom he will leave behind but feels safe from it himself; so he spends his entire life for the benefit of others. The other one works in this world for that which is to come after it, so that which is [allotted] for him comes to him without [extra] work. Thus he acquires both the shares together and gains possession of both the abodes collectively.', 'Ghurar al-Hikam, People- §7', 'wisdom'),
  ('اَلنّاسُ مِنْ خَوْفِ الذُّلِّ مُتَعَجِّلُوا الذُّلِّ.', 'Out of fear of humiliation, people are hastening [towards] humiliation.', 'Ghurar al-Hikam, People- §8', 'wisdom'),
  ('أفْضَلُ النّاسِ أنْفَعُهُمْ لِلنّاسِ.', 'The best of people are those who benefit others the most.', 'Ghurar al-Hikam, People- §9', 'wisdom'),
  ('أسْعَدُ النّاسِ اَلعاقِلُ المُؤمِنُ.', 'The most felicitous person is the intelligent believer.', 'Ghurar al-Hikam, People- §10', 'wisdom'),
  ('اَلنَّوْمُ راحَةٌ مِنْ ألَم ومُلائِمُهُ المَوْتُ.', 'Sleep is a relief from pain and its counterpart is death.', 'Ghurar al-Hikam, Sleep- §1', 'wisdom'),
  ('بِئْسَ الغَريمُ النَّوْمُ يُفْني قَصيرَ العُمْرِ ويُفَوِّتُ كَثيرَ الأجْرِ.', 'What a bad rival sleep is! It wastes the short life [a person has] and causes one to lose a lot of reward.', 'Ghurar al-Hikam, Sleep- §2', 'wisdom'),
  ('مَنْ كَثُرَ في لَيْلِهِ نَوْمُهُ فاتَهُ مِنَ العَمَلِ ما لايَسْتَدْرِكُهُ في يَوْمِهِ.', 'One who sleeps a lot at night loses the [opportunity to perform the] deeds that he cannot make up for during the daytime.', 'Ghurar al-Hikam, Sleep- §3', 'wisdom'),
  ('ما أنْقَضَ النَّوْمَ لِعَزائِمِ اليَوْمِ.', 'What a rescinder sleep is for the resolutions of the day!', 'Ghurar al-Hikam, Sleep- §4', 'wisdom'),
  ('اَلمُسْتَثْقِلُ النّائِمُ تُكَذِّبُهُ أحْلامُهُ.', 'One who is deep in sleep is belied by his dreams.', 'Ghurar al-Hikam, Sleep- §5', 'wisdom'),
  ('وَيْحَ النّائِمِ ما أخْسَرَهُ قَصُرَ عَمَلُهُ وقَلَّ أجْرُهُ.', 'Woe to the sleeper, how great is his loss! His actions fall short and his reward is little.', 'Ghurar al-Hikam, Sleep- §6', 'wisdom'),
  ('إذَا اسْتُنِبتَ فَاعْزِمْ.', 'When you are appointed as a deputy, then be resolute [in fulfilling your obligation].', 'Ghurar al-Hikam, Deputyship- §1', 'wisdom'),
  ('مَنْ نالَ اسْتَطالَ.', 'Whoever obtains [great wealth or power] becomes overbearing.', 'Ghurar al-Hikam, Obtainment- §1', 'wisdom'),
  ('اَلنِّيَّةُ الصَّالِحَةُ أحَدُ العَمَلَينِ.', 'Righteous intention is one of the two actions.', 'Ghurar al-Hikam, Intention- §1', 'wisdom'),
  ('أفْضَلُ الذَّخائِرِ حُسْنُ الضَّمائِرِ.', 'The best of provisions is having good inner consciences.', 'Ghurar al-Hikam, Intention- §2', 'wisdom'),
  ('أقْرَبُ النِّيّاتِ بِالنَّجاحِ أعْوَدُها بِالصَّلاحِ.', 'The closest intentions to success are those that are nearest to righteousness.', 'Ghurar al-Hikam, Intention- §3', 'wisdom'),
  ('أبْلَغُ ما تُسْتَدَرُّ بِهِ الرَّحْمَةُ أنْ تُضْمَرَ لِجَميعِ النّاسِ الرَّحْمَةُ.', 'The most effective thing in making mercy flow forth [and surround you] is having mercy in your heart for all the people.', 'Ghurar al-Hikam, Intention- §4', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ عِنْدَ إضْمارِ كُلِّ مُضْمِر، وقَوْلِ كُلِّ قائِل، وعَمَلِ كُلِّ عامِل.', 'Verily Allah, the Glorified, knows the hidden intention of every concealer, the speech of every speaker and the action of every doer.', 'Ghurar al-Hikam, Intention- §5', 'wisdom'),
  ('إنَّ تَخْليصَ النِّيَّةِ مِنَ الفَسادِ أشَدُّ مِنَ العامِلينَ مِنْ طُولِ الاِجْتِهادِ.', 'Verily making intentions sincere and free from corruption is more difficult for the doers [of good deeds] than a prolonged, difficult struggle.', 'Ghurar al-Hikam, Intention- §6', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ يُحِبُّ أنْ تَكُونَ نِيَّةُ الإنْسانِ لِلنّاسِ جَمِيلَةً، كَما يُحِبُّ أنْ تَكُونَ نِيَّتُهُ في طاعَتِهِ قَوِيَّةً غَيْرَ مَدْخُولَة.', 'Verily Allah, the Glorified, likes a person’s intention towards the people to be good just as He likes his intention in His obedience to be strong, not shaky.', 'Ghurar al-Hikam, Intention- §7', 'wisdom'),
  ('اَلأعْمالُ ثِمارُ النِّيّاتِ.', 'Actions are the fruits of intentions.', 'Ghurar al-Hikam, Intention- §8', 'wisdom'),
  ('اَلنِيَّةُ أساسُ العَمَلِ.', 'Intention is the basis of action.', 'Ghurar al-Hikam, Intention- §9', 'wisdom'),
  ('إحْسانُ النِّيـَّةِ يُوجِبُ المَثُوبَةَ.', 'Having a good intention brings about reward.', 'Ghurar al-Hikam, Intention- §10', 'wisdom'),
  ('مَن وَثِقَ بِاللّهِ غَنِيَ.', 'hoever relies upon Allah becomes free from need.', 'Ghurar al-Hikam, Reliance on Allah- §1', 'wisdom'),
  ('مَنْ وَثِقَ بِاللّهِ تَوَكَّلَ.', 'Whoever relies upon Allah puts his trust in Him.', 'Ghurar al-Hikam, Reliance on Allah- §2', 'wisdom'),
  ('مَنْ وَثِقَ بِاللّهِ صانَ يَقينَهُ.', 'Whoever relies upon Allah has preserved his certitude.', 'Ghurar al-Hikam, Reliance on Allah- §3', 'wisdom'),
  ('مَنْ وَثِقَ بِأنَّ ما قَدَرَ اللّهُ لَهُ لَنْ يَفُوتَهُ اسْتَراحَ قَلْبُهُ.', 'Whoever is certain that what Allah has decreed for him will never escape him, his heart becomes relaxed.', 'Ghurar al-Hikam, Reliance on Allah- §4', 'wisdom'),
  ('رُبَّ واثِق خَجِل.', 'Many a person who relies on something [or someone] gets ashamed.', 'Ghurar al-Hikam, Reliance on Allah- §5', 'wisdom'),
  ('الوِجْدانُ سُلْوانٌ.', 'Attainment [of one’s goal] is solace.', 'Ghurar al-Hikam, Attainment- §1', 'wisdom'),
  ('مَنْ كَتَمَ وَجَعاً أصابَهُ ثَلاثَةَ أيّام، وشَكى إلَى اللّهِ سُبْحانَهُ كانَ اللّهُ سُبْحانَهُ مُعافِيَهُ.', 'Whoever hides a pain that has afflicted him for three days and complains of it [only] to Allah, the Glorified, then Allah will be the one who restores his good health.', 'Ghurar al-Hikam, Pain- §1', 'wisdom'),
  ('أكْرِمْ وُدَّكَ، واحْفَظْ عَهْدَكَ.', 'Honour your friendship and keep your promise.', 'Ghurar al-Hikam, Affection and friendship- §1', 'relationships'),
  ('اَلتَّوَدُّدُ (التُّؤَدَةُ) يُمْنٌ.', 'Affection is an auspicious blessing.', 'Ghurar al-Hikam, Affection and friendship- §2', 'relationships'),
  ('إذا أحْبَبْتَ فَلا تُكْثِرُ.', 'When you love [something or someone] then do not be excessive [in your love].', 'Ghurar al-Hikam, Affection and friendship- §3', 'relationships'),
  ('إذا ثَبَتَ الوُدُّ وَجَبَ التَّرافُدُ والتَّعاضُدُ.', 'When friendship gets established then [mutual] co-operation and support becomes necessary.', 'Ghurar al-Hikam, Affection and friendship- §4', 'relationships'),
  ('بِالتَّوَدُّدِ تَكُونُ المَحَبَّةُ.', 'Through affection comes love.', 'Ghurar al-Hikam, Affection and friendship- §5', 'relationships'),
  ('أفْضَلُ النّاسِ مِنَّةً مَنْ بَدَأَ بِالمَوَدَّةِ.', 'The best person in granting favours is the one who begins by [showing] friendship.', 'Ghurar al-Hikam, Affection and friendship- §6', 'relationships'),
  ('أسْرَعُ المَوَدّاتِ اِنْقِطاعاً مَوَدّاتُ الأشْرارِ.', 'The quickest friendships to get cut off are the friendships of wicked people.', 'Ghurar al-Hikam, Affection and friendship- §7', 'relationships'),
  ('إنَّ المَوَدَّةَ يُعَبِّرُ عَنْهَا اللِّسانُ، وَعَنِ المَحَبَّةِ العَيْنانِ (العَيانُ).', 'Verily friendship is expressed by the tongue whereas love is expressed by the gaze (or the eyes).', 'Ghurar al-Hikam, Affection and friendship- §8', 'relationships'),
  ('اَلْمَوَدَّةُ رَحِمٌ.', 'Friendship is kinship.', 'Ghurar al-Hikam, Affection and friendship- §9', 'relationships'),
  ('اَلْمَوَدَّةُ نَسَبٌ.', 'Friendship is affinity.', 'Ghurar al-Hikam, Affection and friendship- §10', 'relationships'),
  ('اَلْوَرَعُ يُصْلِحُ الدّينَ، ويَصُونُ النَّفْسَ، ويَزينُ المُرُوءَةَ.', 'Piety reforms the faith, protects the soul and adorns magnanimity.', 'Ghurar al-Hikam, Piety- §1', 'wisdom'),
  ('اَلاِنْقِباضُ عَنِ المَحارِمِ مِنْ شِيَمِ العُقَلاءِ، وَسَجِيَّةُ الأكارِمِ.', 'Restraining oneself from the forbidden [actions] is from the traits of the intelligent and is the quality of the honourable.', 'Ghurar al-Hikam, Piety- §2', 'wisdom'),
  ('أفْضَلُ مِنْ طَلَبِ التَّوْبَةِ تَرْكُ الذَّنْبِ.', 'Abandoning sins is better than seeking repentance [after sinning].', 'Ghurar al-Hikam, Piety- §3', 'wisdom'),
  ('أمْلَكُ شَيْء اَلوَرَعُ.', 'The most authoritative thing is piety.', 'Ghurar al-Hikam, Piety- §4', 'wisdom'),
  ('أنْفَعُ شَيْء اَلوَرَعُ.', 'The most beneficial thing is piety.', 'Ghurar al-Hikam, Piety- §5', 'wisdom'),
  ('أحْسَنُ اللِّباسِ الوَرَعُ.', 'Piety is the best attire.', 'Ghurar al-Hikam, Piety- §6', 'wisdom'),
  ('اَلْوَرَعُ مَنْ نَزِهَتْ نَفْسُهُ وشَرُفَتْ خِلالُهُ.', 'The pious person is one whose soul is pure and whose attributes are noble.', 'Ghurar al-Hikam, Piety- §7', 'wisdom'),
  ('اَلْوَرَعُ الوُقُوفُ عِنْدَ الشُّبْهَةِ.', 'Piety is stopping when faced with doubt.', 'Ghurar al-Hikam, Piety- §8', 'wisdom'),
  ('اِحْذَرُوا مِنَ اللّهِ كُنْهَ ما حَذَّرَكُمْ مِنْ نَفْسِهِ وَاخْشَوْهُمْ خَشْيَةً تَحْجُزُكُمْ عَمّا يُسْخِطُهُ.', 'Be cautious of [your duty towards] Him just as He has warned you of Himself and fear Him with a fear that would prevent you from [doing] that which causes His wrath.', 'Ghurar al-Hikam, Piety- §9', 'wisdom'),
  ('إيّاكَ والوُقُوعَ فِي الشُّبَهاتِ، والوُلُوعَ بِالشَّهَواتِ، فَإنَّهُما يَقْتادانِكَ إلَى الوُقُوعِ فِي الْحَرامِ ورُكُوبِ كَثير مِنَ الآثامِ.', 'Beware of falling into doubts and being inclined towards lustful desires, for indeed these two lead you towards falling into the forbidden and committing many sins.', 'Ghurar al-Hikam, Piety- §10', 'wisdom'),
  ('إنَّ مُواساةَ الرِّفاقِ مِنْ كَرَمِ الأعْراقِ.', 'Verily supporting [one’s] companions financially is a sign of noble descent.', 'Ghurar al-Hikam, Financial support- §1', 'wisdom'),
  ('اَلْمُواساةُ أفْضَلُ الأعْمالِ.', 'Giving financial support [to a believer] is the best of actions.', 'Ghurar al-Hikam, Financial support- §2', 'wisdom'),
  ('ما حُفِظَتِ الأُخُوَّةُ بِمِثْلِ المُواساةِ.', 'Nothing preserves brotherhood like financial support [in times of need].', 'Ghurar al-Hikam, Financial support- §3', 'wisdom'),
  ('مَنْ صَدَّقَ الواشِيَ أفْسَدَ الصَّديقَ.', 'Whoever believes [the words of] a tattletale spoils his friendship.', 'Ghurar al-Hikam, Tattletale- §1', 'wisdom'),
  ('لَنْ تَتَّصِلَ بِالخالِقِ حَتّى تَنْقَطِعَ عَنِ الخَلْقِ.', 'You will never get connected to the Creator until you sever your ties with the creation.', 'Ghurar al-Hikam, Getting connected to Allah- §1', 'wisdom'),
  ('الوُصْلَةُ بِاللّهِ فِي الاِنْقِطاعِ عَنِ النّاسِ.', 'Connecting to Allah is in severing ties with the people.', 'Ghurar al-Hikam, Getting connected to Allah- §2', 'wisdom'),
  ('كُنْ لِمَنْ قَطَعَكَ واصِلاً، وَلِمَنْ سَأَلَكَ مُعْطِياً، ولِمَنْ سَكَتَ عَنْ مَسْأَلَتِكَ مُبْتَدِئاً.', 'Establish ties with the one who cuts you off, give the one who asks you, and initiate in giving to the one who does not ask from you.', 'Ghurar al-Hikam, Establishing ties and relations- §2', 'wisdom'),
  ('مَنْ وَصَلَكَ وهُوَ مُعْدِمٌ خَيْرٌ لَكَ مِمَّنْ جَفاكَ وهُوَ مُكْثِرٌ.', 'The one who establishes ties with you while he has nothing is better than the one who shuns you while he has plenty.', 'Ghurar al-Hikam, Establishing ties and relations- §3', 'wisdom'),
  ('مَنْ مَتَّ إلَيْكَ بِحُرْمَةِ الاْسْلامِ فَقَدْ مَتَّ بِأوْثَقِ الأسْبابِ.', 'Whoever establishes ties with you through the sanctity of Islam has associated [with you] through the firmest means.', 'Ghurar al-Hikam, Establishing ties and relations- §4', 'wisdom'),
  ('مُواصَلَةُ الأفاضِلِ تُوجِبُ السُّمُوَّ.', 'Being connected [and keeping ties] with the people of excellence leads to loftiness.', 'Ghurar al-Hikam, Establishing ties and relations- §5', 'wisdom'),
  ('واصِلُوا مَنْ تُواصِلُونَهُ فِي اللّهِ، واهْجُرُوا مَنْ تَهْجُرُونَهُ فِي اللّهِ سُبْحانَهُ.', 'Establish ties with the one whom you keep relations with for the sake of Allah, and sever ties with the one whom you disassociate with for the sake of Allah, the Glorified.', 'Ghurar al-Hikam, Establishing ties and relations- §6', 'wisdom'),
  ('وَصُولٌ مُعْدِمٌ خَيْرٌمِنْ جاف مُكْثِر.', 'The ties established [with you] by a pauper is better than the shunning of the affluent.', 'Ghurar al-Hikam, Establishing ties and relations- §7', 'wisdom'),
  ('وَصُولُ النّاسِ مَنْ وَصَلَ مَنْ قَطَعَهُ.', 'The one who consociates with the people is he who establishes ties with the one who cuts him off.', 'Ghurar al-Hikam, Establishing ties and relations- §8', 'wisdom'),
  ('لايَكُونَنَّ أخُوكَ عَلى قَطيعَتِكَ أقْوى مِنْكَ عَلى صِلَتِهِ.', 'Never let your brother be stronger in severing ties with you than you are in establishing ties with him.', 'Ghurar al-Hikam, Establishing ties and relations- §9', 'wisdom'),
  ('اَلتَّواضُعُ أفْضَلُ الشَّرَفَيْنِ.', 'umility is the more superior of the two honours.', 'Ghurar al-Hikam, Humility- §1', 'character'),
  ('اَلتَّواضُعُ مَعَ الرِّفْعَةِ كَالعَفْوِ مَعَ القُدْرَةِ.', 'Humility in spite of [having a] high rank is like forgiveness in spite of [possessing the] power [to punish].', 'Ghurar al-Hikam, Humility- §2', 'character'),
  ('اَلتَّواضُعُ رَأْسُ العَقْلِ، والتَّكَبُّرُ رَأسُ الجَهْلِ.', 'Humility is the cornerstone of intelligence and pride is the cornerstone of ignorance.', 'Ghurar al-Hikam, Humility- §3', 'character'),
  ('اِتَّضِعْ تَرْتَفِعْ.', 'Be humble and you with be elevated.', 'Ghurar al-Hikam, Humility- §4', 'character'),
  ('أعْظَمُ النّاسِ رِفْعَةً مَنْ وَضَعَ نَفْسَهُ.', 'The greatest of people in loftiness is one who humbles himself.', 'Ghurar al-Hikam, Humility- §5', 'character'),
  ('أشْرَفُ الخَلائِقِ التَّواضُعُ والحِلْمُ، ولينُ الجانِبِ.', 'The most honourable of attributes is humility, forbearance and affability.', 'Ghurar al-Hikam, Humility- §6', 'character'),
  ('َالتَّواضُعُ يَرْفَعُ، اَلتَّكَبُّرُ يَضَعُ.', 'Humility elevates, pride abases.', 'Ghurar al-Hikam, Humility- §7', 'character'),
  ('اَلتَّواضُعُ ثَمَرَةُ العِلْمِ.', 'Humility is the fruit of knowledge.', 'Ghurar al-Hikam, Humility- §8', 'character'),
  ('اَلتَّواضُعُ يَرْفَعُ الوَضيعَ.', 'Humility elevates the abased.', 'Ghurar al-Hikam, Humility- §9', 'character'),
  ('اَلتَّواضُعُ عُنْوانُ النُّبْلِ.', 'Humility is the symbol of nobility.', 'Ghurar al-Hikam, Humility- §10', 'character'),
  ('مِنْ ضيقِ العَطَنِ لُزُومُ الوَطَنِ.', 'It is from the restriction of means to remain in one’s homeland [and not travel].', 'Ghurar al-Hikam, Homeland- §1', 'wisdom'),
  ('اَلاِغْتِرابُ أحَدُ الشِّتاتَيْنِ.', 'Separation from one’s homeland is one of the two separations.', 'Ghurar al-Hikam, Homeland- §2', 'wisdom'),
  ('اِسْتَصْبِحُوا مِنْ شُعْلَةِ واعِظ مُتَّعِظ، وأقْبَلُوا نَصيحَةَ ناصِح مُتَيَقِّظ، وَقِفُوا عِنْدَ ما أفادَكُمْ مِنَ التَّعْليمِ.', 'Take light from the flame of the preacher who practices what he preaches, accept advice from the adviser who is vigilant, and act upon what he teaches you.', 'Ghurar al-Hikam, Admonition- §1', 'wisdom'),
  ('اَلا إنَّ أسْمَعَ الأسماعِ مَنْ وَعَي التَّذْكيرَ وقَبِلَهُ.', 'Indeed the most hearing ear is one that listens to admonition and heeds it.', 'Ghurar al-Hikam, Admonition- §2', 'wisdom'),
  ('أنْفَعُ المَواعِظِ ما رََدَعَ.', 'The most beneficial of admonitions is that which deters [someone from sin].', 'Ghurar al-Hikam, Admonition- §3', 'wisdom'),
  ('أبْلَغُ العِظاتِ اَلاِعْتِبارُ بِمَصارِعِ الأمْواتِ.', 'The most effective admonition is taking a lesson from the place where the dead lay.', 'Ghurar al-Hikam, Admonition- §4', 'wisdom'),
  ('أبْلَغُ العِظاتِ اَلنَّظَرُ إلى مَصارِعِ الأمْواتِ،وَ الاِعْتِبارُ بِمَصائِرِ الآباءِ وَالأُمَّهاتِ.', 'The most effective admonition is looking at the places where the dead lay, and taking a lesson from the outcome of one’s forefathers and foremothers.', 'Ghurar al-Hikam, Admonition- §5', 'wisdom'),
  ('أبْلَغُ ناصِح لَكَ الدُّنْيا، لَوِ انْتَصَحْتَ بِما تُريكَ مِنْ تَغايُرِ الحالاتِ، وَتُؤْذِنُكَ بِهِ مِنَ البَيْنِ والشَّتاتِ.', 'The most effective adviser for you is this world, if only you took a lesson from what it shows you of the changing circumstances and what it informs you of disunion and separation.', 'Ghurar al-Hikam, Admonition- §6', 'wisdom'),
  ('إنَّ في كُلِّ شَيْء مَوْعِظَةً وعِبْرَةً لِذَوِى اللُّبِ وَالاِعْتِبارِ.', 'Verily there is a lesson and an admonition in everything for the people of wisdom and understanding.', 'Ghurar al-Hikam, Admonition- §7', 'wisdom'),
  ('إنَّ أنْصَحَ النّاسِ أنْصَحُهُمْ لِنَفْسِهِ، وأطْوَعُهُمْ لِرَبِّهِ.', 'Verily the most sincere of people is one who admonishes himself and is most submissive to his Lord.', 'Ghurar al-Hikam, Admonition- §8', 'wisdom'),
  ('إنَّ الوَعْظَ الَّذي لايَمُجُّهُ سَمْعٌ، ولايَعْدِلُهُ نَفْعٌ، ما سَكَتَ عَنْهُ لِسانُ القَوْلِ، ونَطَقَ بِِهِ لِسانُ الفِعْلِ.', 'Verily the admonition that is neither discarded by the ears nor matched in benefit is that which is not expressed by the speaking tongue, rather it is exhibited by the tongue of action.', 'Ghurar al-Hikam, Admonition- §9', 'wisdom'),
  ('اَلاِتِّعاظُ اِعْتِبارٌ.', 'Accepting admonition means taking a lesson [and putting into action].', 'Ghurar al-Hikam, Admonition- §10', 'wisdom'),
  ('اَلتَّوْفِيقُ أشْرَفُ الحَظَّيْنِ.', 'God-given success is the more honourable of the two shares.', 'Ghurar al-Hikam, God-given success- §1', 'wisdom'),
  ('اَلتَّوفِيْقُ والخِذْلانُ يَتَجاذِبانِ النَّفْسَ فَأيُّهُما غَلَبَ كانَتْ في حَيِّزِهِ.', 'God-given success and God’s abandonment 1 each pulls the soul towards itself, so whichever [of the two] prevails, it enters its fold.', 'Ghurar al-Hikam, God-given success- §2', 'wisdom'),
  ('إنَّ اللّهَ سُبْحانَهُ إذا أرادَ بِعَبْد خَيْراً، وَفَّقَهُ لإنْفاذِ أجَلِهِ، في أحْسَنِ عَمَلِهِ ورَزَقَهُ مُبادَرَةَ مَهَلِهِ في طاعَتِهِ قَبْلَ الفَوْتِ.', 'Verily when Allah, the Glorified, wishes good for a servant, He grants him success in spending his lifetime doing the best deeds and blesses him with the ability to quickly use his available time to perform acts of worship, before [the coming of] his death.', 'Ghurar al-Hikam, God-given success- §3', 'wisdom'),
  ('اَلتَّوْفِيقُ عِنايَةٌ.', 'God-given success is [God’s special attention and] favour.', 'Ghurar al-Hikam, God-given success- §4', 'wisdom'),
  ('اَلتَّوْفِيقُ رَحْمَةٌ.', 'God-given success is a mercy.', 'Ghurar al-Hikam, God-given success- §5', 'wisdom'),
  ('اَلتَّوْفِيقُ إقْبالٌ.', 'God-given success is [a means of] advancement [towards Allah].', 'Ghurar al-Hikam, God-given success- §6', 'wisdom'),
  ('اَلتَّوْفِيقُ(الرِّفْقُ) مِفْتاحُ الرِّفْقِ.', 'God-given success (or kindness) is the key to sustenance.', 'Ghurar al-Hikam, God-given success- §7', 'wisdom'),
  ('اَلتَّوْفِيقُ قائِدُ الصَّلاحِ.', 'God-given success is the leader towards righteousness.', 'Ghurar al-Hikam, God-given success- §8', 'wisdom'),
  ('اَلتَّوْفِيقُ مِنْ جَذَباتِ الرَّبِّ.', 'God-given success is from the attractions [that pulls one] towards the Lord.', 'Ghurar al-Hikam, God-given success- §9', 'wisdom'),
  ('اَلتَّوْفِيقُ أوَّلُ النِّعْمَةِ.', 'God-given success is the beginning of [many] blessings.', 'Ghurar al-Hikam, God-given success- §10', 'wisdom'),
  ('كَثْرَةُ الوِفاقِ نِفاقٌ.', 'Excessive agreement is hypocrisy.', 'Ghurar al-Hikam, Agreement- §1', 'wisdom'),
  ('بِئْسَ الوَجْهُ الْوَقاحُ.', 'The worst countenance is [that of] the shameless.', 'Ghurar al-Hikam, Shamelessness and the shameless- §1', 'wisdom'),
  ('ما أوْقَحَ الجاهِلَ.', 'How shameless the ignorant one is!', 'Ghurar al-Hikam, Shamelessness and the shameless- §2', 'wisdom'),
  ('وَقاحَةُ الرَّجُلِ تَشينُهُ.', 'The shamelessness of a man disgraces him.', 'Ghurar al-Hikam, Shamelessness and the shameless- §3', 'wisdom'),
  ('إيّاكَ والْقِحَةَ، فَإنَّها تَحْدُوكَ عَلى رُكُوبِ القَبائِحِ، والتَّهَجُّمِ عَلَى السَّيِّئاتِ.', 'Beware of impudence, for indeed it drives you to embark on ugly acts and to rush towards evil deeds.', 'Ghurar al-Hikam, Impudence- §1', 'wisdom'),
  ('اَلقِحَةُ عُنْوانُ الشَّرِّ.', 'Impudence is the symbol of evil.', 'Ghurar al-Hikam, Impudence- §2', 'wisdom'),
  ('رَأْسُ كُلِّ شَرّ ألقِحَةُ.', 'The cornerstone of every evil is impudence.', 'Ghurar al-Hikam, Impudence- §3', 'wisdom'),
  ('وَقِّرُوا اللّهَ سُبْحانَهُ، واجْتَنِبُوا مَحارِمَهُ، وأحِبُّوا أحِبّائَهُ.', 'Revere Allah the Glorified, keep away from what He has forbidden and love those whom He loves.', 'Ghurar al-Hikam, Reverence- §1', 'wisdom'),
  ('وَقِّرُوا كِبارَكُمْ، يُوَقِّرْكُمْ صِغارُكُمْ.', 'Revere your elders and your youngsters will revere you.', 'Ghurar al-Hikam, Reverence- §2', 'wisdom'),
  ('عَلَيْكَ بِالتَّقِيَّةِ فَإنَّها شيمَةُ الأفاضِلِ.', 'Espouse precautionary dissimulation for indeed it is a trait of the praiseworthy.', 'Ghurar al-Hikam, Precautionary dissumilation- §1', 'wisdom'),
  ('لادينَ لِمَنْ لاتَقِيَّةَ لَهُ.', 'He who has no precautionary dissimulation has no religion.', 'Ghurar al-Hikam, Precautionary dissumilation- §2', 'wisdom'),
  ('اَلتَّقِيَّةُ دِيانَةٌ.', 'Precautionary dissimulation is religiosity.', 'Ghurar al-Hikam, Precautionary dissumilation- §3', 'wisdom'),
  ('اَلتَّقْوى حِصْنٌ حَصينٌ لِمَنْ لَجَأَ إلَيْهِ.', 'God-wariness is a fortified stronghold for the one who takes refuge in it.', 'Ghurar al-Hikam, God-wariness- §1', 'wisdom'),
  ('اَلتَّقْوى جَمّاعُ التَّنَزُّهِ والعَفافِ.', 'God-wariness is the accumulator of [all] purity and chastity.', 'Ghurar al-Hikam, God-wariness- §2', 'wisdom'),
  ('اَلتَّقْوى ثَمَرَةُ الدّينِ وأمارَةُ اليَقينِ.', 'God-wariness is the fruit of faith and the sign of certitude.', 'Ghurar al-Hikam, God-wariness- §3', 'wisdom'),
  ('اَلتَّقْوى ظاهِرُهُ شَرَفُ الدُّنْيا، وباطِنُهُ شَرَفُ الآخِرَةِ.', 'The exterior of God-wariness is honour in this world while its interior is honour in the Hereafter.', 'Ghurar al-Hikam, God-wariness- §4', 'wisdom'),
  ('اَلتَّقْوى آكَدُ سَبَب بَيْنَكَ وبيْنَ اللّهِ إنْ أخَذْتَ بِهِ وجُنَّـةٌ مِن ْ عَذاب أليم.', 'God-wariness is the strongest connection between yourself and Allah if you hold on to it, and it is a shield against the painful chastisement [of the Hereafter].', 'Ghurar al-Hikam, God-wariness- §5', 'wisdom'),
  ('اَلتَّقْوى لاعِوَضَ ولا خَلَفَ فيهِ.', 'God-wariness is such that there is no alternative or substitute for it.', 'Ghurar al-Hikam, God-wariness- §6', 'wisdom'),
  ('اَلتَّقْوى أنْ يَتَّقِيَ المَرْءُ كُلَّما يُؤْثِمُهُ.', 'God-wariness is for a person to be cautious of all [the things] that could lead him towards sin.', 'Ghurar al-Hikam, God-wariness- §7', 'wisdom'),
  ('اِتَّقِ تَفُزْ.', 'Be God-wary and you will succeed [in this world and the next].', 'Ghurar al-Hikam, God-wariness- §8', 'wisdom'),
  ('أشْعِرْ قَلْبَكَ التَّقْوى، وخالِفِ الهَوى تَغْلِبِ الشَّيْطانَ.', 'Fill your heart with God-wariness and oppose your vain desires, [by this] you will overcome Satan.', 'Ghurar al-Hikam, God-wariness- §9', 'wisdom'),
  ('اِتَّقِ اللّهَ بَعْضَ التُّقى وإنْ قَلَّ، واجْعَلْ بَيْنَكَ وبَيْنَهُ سِتْراً وإنْ رَقَّ.', 'Fear Allah with some God-wariness, even if it be little, and place between yourself and Him a veil [of shame], even if it be thin.', 'Ghurar al-Hikam, God-wariness- §10', 'wisdom'),
  ('اَلْمُتَّقي مَنِ اتَّقَى الذُّنُوبَ، والمُتَنَزِّهُ مَنْ تَنَزَّهَ عَنِ العُيُوبِ.', 'The God-wary is one who guards against sins, and the purified is one who purifies himself of faults.', 'Ghurar al-Hikam, The God-wary and God fearing people- §1', 'wisdom'),
  ('اَلْمُتَّقُونَ أنْفُسُهُمْ عَفِيفَةٌ، وحاجاتَهُمْ خَفِيْفَةٌ، وخَيْراتُهُمْ مَأمُولَةٌ، وَشُرُُورُهُمْ مَأمُونَةٌ.', 'The God-wary are those whose souls are chaste and whose needs are few; people hope for good from them and feel secure from their evil.', 'Ghurar al-Hikam, The God-wary and God fearing people- §2', 'wisdom'),
  ('اَلْمُتَّقُونَ أنْفُسُهُمْ قانِعَةٌ، وَشَهَواتُهُمْ مَيْتَةٌ، ووُجُوهُهُمْ مُسْتَبْشِرَةٌ، وَقُلُوبُهُمْ مَحْزُونَةٌ.', 'The God-wary are those whose souls are content, whose lustful desires are dead and whose faces are cheerful while their hearts are sad.', 'Ghurar al-Hikam, The God-wary and God fearing people- §4', 'wisdom'),
  ('اَلْمُتَّقُونَ أعْمالُهُمْ زاكِيَةٌ، وأعْيُنُهُمْ باكِيَةٌ، وقُلُوبُهُمْ وَجِلَةٌ.', 'The God-wary are those whose actions are pure, whose eyes are tearful and whose hearts are fearful.', 'Ghurar al-Hikam, The God-wary and God fearing people- §5', 'wisdom'),
  ('اَلمُتَّقي مَيْتَةٌ شَهْوَتُهُ، مَكْظُومٌ غَيْظُهُ، فِي الرَّخاءِ شَكُورٌ، وفِي المَكارِهِ صَبُورٌ.', 'The God-wary person is one whose lustful desire is dead, whose anger is suppressed, and who is thankful in times of comfort and patient in times of hardships.', 'Ghurar al-Hikam, The God-wary and God fearing people- §6', 'wisdom'),
  ('إنَّ الأتْقِياءَ كُلُّ سَخِىّ، مُتَعَفِّف مُحْسِن.', 'Verily the God-wary are all those [believers] who are generous, chaste and benevolent.', 'Ghurar al-Hikam, The God-wary and God fearing people- §7', 'wisdom'),
  ('إنَّ المُتَّقينَ ذَهَبُوا بِعاجِلِ الدُّنْيا والآخِرَةِ، شارَكُوا أهْلَ الدُّنْيا في دُنْياهُمْ، ولَمْ يُشارِكْهُمْ أهْلُ الدُّنْيا في آخِرَتِهِمْ.', 'Verily the God-wary have taken [and gained in both] the evanescent world and the Hereafter. They have shared with the people of this world in their worldly benefits, while the people of this world shall not share with them in their Hereafter.', 'Ghurar al-Hikam, The God-wary and God fearing people- §8', 'wisdom'),
  ('اَلْمُتَّقُونَ قُلُوبُهُمْ مَحْزُونَةٌ، وشُرُورُهُمْ مَأْمُونَةٌ.', 'The God-wary are those whose hearts are sad and from whose evil people are safe.', 'Ghurar al-Hikam, The God-wary and God fearing people- §9', 'wisdom'),
  ('اَلمُتَّقي قانِعٌ، مُتَنَزِّهٌ، مُتَعَفِّفٌ.', 'The God-wary person is content, free from sin and chaste.', 'Ghurar al-Hikam, The God-wary and God fearing people- §10', 'wisdom'),
  ('شيمَةُ الأتْقياءِ اِغْتِنامُ الْمُهْلَةِ، والتَّزَوُّدُ لِلرِّحْلَةِ.', 'The practice of the God-wary is taking advantage of respite and preparing provisions for the [final] journey.', 'Ghurar al-Hikam, The God-wary and God fearing people- §11', 'wisdom'),
  ('اَلتَّوَكُّلُ كِفايَةٌ شَريفَةٌ لِمَنِ اعْتَمَدَ عَلَيْهِ.', 'Trusting in Allah is an honourable sufficiency for the one who relies upon it.', 'Ghurar al-Hikam, Putting trust in Allah- §1', 'wisdom'),
  ('اَلتَّوَكُّلُ اَلتَبَّري مِنَ الحَوْلِ والقُوَّةِ وانْتِظارُ ما يَأتي بِهِ القَدَرُ.', 'Trusting in Allah means distancing oneself from [reliance upon one’s] strength and power, and waiting for what is brought by divine decree.', 'Ghurar al-Hikam, Putting trust in Allah- §2', 'wisdom'),
  ('إيّاكَ أنْ تَتَخَيَّرَ لِنَفْسِكَ، فَإنَّ أكْثَرَ النُّجْحِ فيما لايُحْتَسَبُ.', 'Beware of choosing [a path] for yourself [instead of putting your trust in Allah], for indeed most of the success lies in that which is not reckoned.', 'Ghurar al-Hikam, Putting trust in Allah- §3', 'wisdom'),
  ('أصْلُ قُوَّةِ القَلْبِ اَلتَّوَكُّلُ عَلَى اللّهِ.', 'The root of the heart’s strength is in putting [one’s] trust in Allah.', 'Ghurar al-Hikam, Putting trust in Allah- §4', 'wisdom'),
  ('إنَّ حُسْنَ التَّوَكُّلِ لَمِنْ صِدْقِ الإيقانِ.', 'Verily the perfection of trust in Allah stems from the verity of certitude.', 'Ghurar al-Hikam, Putting trust in Allah- §5', 'wisdom'),
  ('اَلتَّوَكُّلُ كِفايَةٌ.', 'Trusting in Allah is [a means of] sufficiency.', 'Ghurar al-Hikam, Putting trust in Allah- §6', 'wisdom'),
  ('اَلتَّوَكُّلُ بِضاعَةٌ.', 'Trusting in Allah is an asset.', 'Ghurar al-Hikam, Putting trust in Allah- §7', 'wisdom'),
  ('اَلتَّوَكُّلُ خَيْرُ عِماد.', 'Trusting in Allah is the best pillar [of support].', 'Ghurar al-Hikam, Putting trust in Allah- §8', 'wisdom'),
  ('اَلتَّوَكُّلُ حِصْنُ الحِكْمَةِ.', 'Trusting in Allah is the fortress of wisdom.', 'Ghurar al-Hikam, Putting trust in Allah- §9', 'wisdom'),
  ('اَلتَّوَكُّلُ أفْضَلُ عَمَل.', 'Trusting in Allah is the best action.', 'Ghurar al-Hikam, Putting trust in Allah- §10', 'wisdom'),
  ('اَلْوَلَدُ الصّالِحُ أجْمَلُ الذِّكْرَيْنِ.', 'A righteous child is the more beautiful of the two recollections.', 'Ghurar al-Hikam, The Child- §1', 'wisdom'),
  ('اَلْوَلَدُ أحَدُ العَدُوَّيْنِ.', 'A child is one of the two enemies.', 'Ghurar al-Hikam, The Child- §2', 'wisdom'),
  ('شَرُّ الأوْلادِ اَلْعاقُّ.', 'The worst of all children is the undutiful one.', 'Ghurar al-Hikam, The Child- §3', 'wisdom'),
  ('فَقْدُ الوَلَدِ مُحْرِقُ الكَبِدِ.', 'The loss of a child burns the heart.', 'Ghurar al-Hikam, The Child- §4', 'wisdom'),
  ('مَوْتُ الوَلَدِ صَدْعٌ فِي الكَبِدِ.', 'The death of a child is [like a] tear in the heart.', 'Ghurar al-Hikam, The Child- §5', 'wisdom'),
  ('وَلَدُ السُّوءِ يَهْدِمُ الشَّرَفَ، ويَشينُ السَّلَفَ.', 'An evil child destroys one’s honour and disgraces one’s ancestors.', 'Ghurar al-Hikam, The Child- §6', 'wisdom'),
  ('وَلَدُ السُّوءِ يَعُرُّ السَّلَفَ، ويُفْسِدُ الخَلَفَ.', 'An evil child dishonours one’s ancestors and corrupts one’s descendants.', 'Ghurar al-Hikam, The Child- §7', 'wisdom'),
  ('وَلَدٌ عَقُوقٌ مِحْنَةٌ وشُؤْمٌ.', 'The undutiful child is a tribulation and a misfortune.', 'Ghurar al-Hikam, The Child- §8', 'wisdom'),
  ('إنَّ أوْلِياءَ اللّهِ تَعالى كُلُّ مُسْتَقْرِب أجَلَهُ، مُكَذِّب أمَلَهُ، كَثير عَمَلُهُ، قَليل زَلَلُهُ.', 'Verily the friends of Allah, the Most High, include all those who consider their death to be near, belie their [false] hopes, and have many good deeds and only a few mistakes.', 'Ghurar al-Hikam, The Close Friends And Lovers Of Allah §1', 'wisdom'),
  ('إنَّ أوْلِياءَ اللّهِ لأكْثَرُ النّاسِ لَهُ ذِكْراً، وأدْوَمُهُمْ لَهُ شُكْراً، وأعْظَمُهُمْ عَلى بَلائِهِ صَبْراً.', 'Verily the friends of Allah are those who remember Him the most, are constantly grateful to Him and have greater patience in the face of His trials.', 'Ghurar al-Hikam, The Close Friends And Lovers Of Allah §2', 'wisdom'),
  ('إنَّ مِنْ أحَبِّ العِبادِ إلَى اللّهِ عَبْداً أعانَهُ عَلى نَفْسِهِ فَاسْتَشْعَرَ الحُزْنَ، وَتَجَلْبَبَ الخَوْفَ، فَزَهَرَ مِصْباحُ الهُدى في قَلْبِهِ،وَ أعَدَّ القِرى لِيَوْمِهِ النّازِلِ بِهِِ.', 'Verily the most beloved of servants in the sight of Allah is the servant whom He helps to reform his soul such that he feels sadness [on the inside] and dons the attire of fear [on the outside]; so the lamp of guidance is illuminated in his heart, and he has prepared [for himself] a hospitable reception for the day which he will come upon.', 'Ghurar al-Hikam, The Close Friends And Lovers Of Allah §3', 'wisdom'),
  ('اَلتَّواني فِي الدُّنْيا إضاعَةٌ، وفِي الآخِرَةِ حَسْرَةٌ.', 'Lethargy causes loss in this world and regret in the Hereafter.', 'Ghurar al-Hikam, Lethargy- §1', 'wisdom'),
  ('اَلتَّواني إضاعَةٌ.', 'Lethargy is wastage [of one’s lifetime].', 'Ghurar al-Hikam, Lethargy- §2', 'wisdom'),
  ('اَلتَّواني فَوْتٌ.', 'Lethargy is [a cause of] loss.', 'Ghurar al-Hikam, Lethargy- §3', 'wisdom'),
  ('اَلتَّواني سَجِيَّةُ النَّوْكى.', 'Lethargy is the trait of the foolish.', 'Ghurar al-Hikam, Lethargy- §4', 'wisdom'),
  ('بِالتَّواني يَكُونُ الفَوْتُ.', 'Loss comes about through lethargy.', 'Ghurar al-Hikam, Lethargy- §5', 'wisdom'),
  ('ضادُّوا التَّوانِيَ بِالعَزْمِ.', 'Counter lethargy with resolve.', 'Ghurar al-Hikam, Lethargy- §6', 'wisdom'),
  ('مَنْ أطاعَ التَّوانِيَ ضَيَّعَ الحُقُوقَ.', 'One who submits to lethargy forfeits his rights.', 'Ghurar al-Hikam, Lethargy- §7', 'wisdom'),
  ('مَنْ أَطاعَ التَّوانِيَ أحاطَتْ بِهِ النَّدامَةُ.', 'One who submits to lethargy is encompassed by regret.', 'Ghurar al-Hikam, Lethargy- §8', 'wisdom'),
  ('مِنَ التَّوانِي يَتَوَلَّدُ الكَسَلُ.', 'It is from lethargy that laziness originates.', 'Ghurar al-Hikam, Lethargy- §9', 'wisdom'),
  ('رُبَّ مَوْهِبَة خَيْرٌ مِنْهَا الفَجيعَةُ.', 'any a grant is such that misfortune is better than it.', 'Ghurar al-Hikam, The grant- §1', 'wisdom'),
  ('لَيْسَ الوَهْمُ كَالْفَهْمِ.', 'Delusion is not the same as comprehension.', 'Ghurar al-Hikam, Delusion- §1', 'wisdom'),
  ('مَنْ عَرَّضَ نَفْسَهُ لِلتُّهْمَةِ فَلا يَلُومَنَّ مََنْ أساءَ الظَّنَّ بِهِ.', 'hoever exposes himself to suspicion should not blame those who suspect him.', 'Ghurar al-Hikam, Suspicion- §1', 'wisdom'),
  ('أفْضَلُ الذُّخْرِ اَلهُدى.', 'The best reserve is true guidance.', 'Ghurar al-Hikam, True guidance from Allah- §1', 'wisdom'),
  ('بِالهُدى يَكْثُرُ الاِسْتِبْصارُ.', 'Through true guidance discernment increases.', 'Ghurar al-Hikam, True guidance from Allah- §2', 'wisdom'),
  ('ضَلَّ مَنِ اهْتَدى بِغَيْرِ هُدَى اللّهِ.', 'He who takes guidance from other than the guidance of Allah has gone astray.', 'Ghurar al-Hikam, True guidance from Allah- §3', 'wisdom'),
  ('طُوبى لِمَنْ بادَرَ الهُدى قَبْلَ أنْ تُغْلَقَ أبْوابُهُ.', 'Blessed is the one who hastens towards true guidance before its doors are closed.', 'Ghurar al-Hikam, True guidance from Allah- §4', 'wisdom'),
  ('طاعَةُ الهُدى تُنْجي.', 'Following true guidance leads to salvation.', 'Ghurar al-Hikam, True guidance from Allah- §5', 'wisdom'),
  ('فازَ مَنِ اسْتَصْبَحَ بِنُورِ الهُدى، وَخالَفَ دَواعِيَ الهَوى، وجَعَلَ الإيمانَ عُدَّةَ مَعادِهِ، والتَّقْوى ذُخْرَهُ وزادَهُ.', 'Successful is the one who gets illumination from the lamp of guidance, opposes the calls of [his] vain desire, makes faith the equipage for his Hereafter and [makes] God-wariness his reserve and provision.', 'Ghurar al-Hikam, True guidance from Allah- §6', 'wisdom'),
  ('كَيْفَ يَهْتَدِى الضَّليلُ مَعَ غَفْلَةِ الدَّليلِ؟!', 'How can the one who is astray be guided aright when the guide [he follows] is heedless?!', 'Ghurar al-Hikam, True guidance from Allah- §7', 'wisdom'),
  ('كَيْفَ يَهْدي غَيْرَهُ مَنْ يُضِلُّ نَفْسَهُ؟!', 'How can one who is himself astray guide others to the right?!', 'Ghurar al-Hikam, True guidance from Allah- §8', 'wisdom'),
  ('كَيْفَ يَسْتَطيعُ الهُدى مَنْ يَغْلِبُهُ الهَوى؟!', 'How is the one who is overcome by [his] vain desire able to get true guidance?!', 'Ghurar al-Hikam, True guidance from Allah- §9', 'wisdom'),
  ('لِيَكُنْ شِعارُكَ الهُدى.', 'Let your garment be true guidance.', 'Ghurar al-Hikam, True guidance from Allah- §10', 'wisdom'),
  ('اَلْهَدِيَّةُ تَجْلِبُ المَحَبَّةَ.', 'Gifts bring about affection.', 'Ghurar al-Hikam, Gifts- §1', 'wisdom'),
  ('مَا اسْتُعْطِفَ السُّلْطانُ، ولاَاسْتُسِلَّ سَخيمَةُ الغَضْبانِ، وَلاَ اسْتُميلَ المَهْجُورُ، ولاَ اسْتُنْجِحَتْ صِعابُ الأُمُورِ، ولاَ اسْتُدْفِعَتِ الشُّرُورُ بِمِثْلِ الهَدِيَّةِ.', 'Nothing gains the favour of the ruler, quells the rancour of an enraged person, attracts the deserter [to come back], makes difficult matters easy and keeps wickedness [and evil] at bay like the [giving of a] gift.', 'Ghurar al-Hikam, Gifts- §2', 'wisdom'),
  ('اِجْتَنِبِ الهَذَرَ، فَأيْسَرُ جنايَتِهِ المَلامَةُ.', 'Keep away from idle talk, for the least of its damage is blame.', 'Ghurar al-Hikam, Idle talk- §1', 'wisdom'),
  ('إيّاكَ وَالهَذَرَ، فَمَنْ كَثُرَ كَلامُهُ كَثُرَتْ آثامُهُ.', 'Beware of idle talk, for the one whose talk increases, his sins [also] increase.', 'Ghurar al-Hikam, Idle talk- §2', 'wisdom'),
  ('اَلْهَذَرُ مُقَرِّبٌ مِنَ الغِيَرِ.', 'Idle talk takes one closer to [unpleasant] changes [in circumstances].', 'Ghurar al-Hikam, Idle talk- §3', 'wisdom'),
  ('اَلْهَذَرُ يَأْتي عَلَى المُهْجَةِ.', 'Idle talk harms the soul.', 'Ghurar al-Hikam, Idle talk- §4', 'wisdom'),
  ('كَثْرَةُ الْهَذَرِ تُكْسِبُ العارَ.', 'Excessive idle talk earns disgrace.', 'Ghurar al-Hikam, Idle talk- §5', 'wisdom'),
  ('كَثْرَةُ الهَزْلِ آيَةُ الجَهْلِ.', 'Too much joking is a sign of ignorance.', 'Ghurar al-Hikam, Joking- §1', 'wisdom'),
  ('مَنْ كَثُرَ هَزْلُهُ اُسْتُجْهِلَ.', 'Whoever jokes too much is considered ignorant.', 'Ghurar al-Hikam, Joking- §2', 'wisdom'),
  ('مَنْ كَثُرَ هَزْلُهُ بَطَلَ جِدُّهُ.', 'Whoever jokes a lot, his seriousness becomes ineffective [and is considered just another of his jokes].', 'Ghurar al-Hikam, Joking- §3', 'wisdom'),
  ('مَنْ غَلَبَ عَلَيْهِ الهَزْلُ فَسَدَ عَقْلُهُ.', 'Whoever is overcome by jest, his intellect becomes corrupt.', 'Ghurar al-Hikam, Joking- §4', 'wisdom'),
  ('ثَلاثَةٌ مُهْلِكَةٌ: اَلجُرْأَةُ عَلَى السُّلْطانِ، وائْتِمانُ الخَوّانِ، وشُرْبُ السَّمِ لِلتَّجْرِبَةِ.', 'Three things cause ruin: boldness in front of the ruler, trusting a disloyal person and tasting poison as an experiment [to see how effective it is!].', 'Ghurar al-Hikam, The causes of downfall and ruin- §2', 'wisdom'),
  ('ثَلاثٌ هُنَّ المُحْرِقاتُ المُوبِقاتُ: فَقْرٌ بَعْدَ غِنىً، وذُلٌّ بَعْدَ عِزّ، وفَـقْدُ الأحِبَّةِ.', 'Three things break one’s spirit and cause downfall: poverty after wealth, humiliation after dignity and loss of loved ones.', 'Ghurar al-Hikam, The causes of downfall and ruin- §3', 'wisdom'),
  ('ثَلاثٌ يَهْدُونَ القُوى: فَقْدُ الأحِبَّةِ، والفَقْرُ فِي الغُرْبَةِ، ودَوامُ الشِّدَّةِ.', 'Three things weaken one’s spirit: loss of loved ones, poverty in a strange land and unending hardship.', 'Ghurar al-Hikam, The causes of downfall and ruin- §4', 'wisdom'),
  ('اَلْهَمّازُ مَذْمُومٌ مَجْرُوحٌ.', 'The scandal-monger is dispraised and reviled.', 'Ghurar al-Hikam, The scandal monger- §1', 'wisdom'),
  ('أبْعَدُ الهِمَمِ أقْرَبُها مِنَ الكَرَمِ.', 'The farthest endeavours are those that are closest to nobleness.', 'Ghurar al-Hikam, Endeavours- §1', 'wisdom'),
  ('بِقَدْرِ الهِمَمِ تَكُونُ الهُمُومُ.', 'Worries [and concerns] are [proportionate] to the extent of [one’s] endeavours.', 'Ghurar al-Hikam, Endeavours- §2', 'wisdom'),
  ('خَيْرُ الهِمَمِ أعْلاها.', 'The best endeavours are the loftiest of them.', 'Ghurar al-Hikam, Endeavours- §3', 'wisdom'),
  ('كُنْ بَعيدَ الهِمَمِ إذا طَلَبْتَ، كَريمَ الظَّفَرِ إذا غَلَبْتَ.', 'Be lofty in your endeavours when you seek something and honourable in victory when you overpower [your enemy].', 'Ghurar al-Hikam, Endeavours- §4', 'wisdom'),
  ('مَنْ كَبُرَ هِمَتُّهُ كَبُرَ اهْتِمامُهُ.', 'One whose endeavour is great, his care [and attention towards it] becomes great.', 'Ghurar al-Hikam, Endeavours- §5', 'wisdom'),
  ('مَنْ صَغُرَتْ هِمَّتُهُ بَطَلَتْ فَضيلَتُهُ.', 'One whose endeavour is insignificant, his merit is nullified.', 'Ghurar al-Hikam, Endeavours- §6', 'wisdom'),
  ('مَنْ شَرُفَتْ هِمَّتُهُ عَظُمَتْ قيمَتُهُ.', 'One whose endeavour is honourable, his value becomes great.', 'Ghurar al-Hikam, Endeavours- §7', 'wisdom'),
  ('مَنْ كَبـرَتْ هِمَّتُهُ عَزَّ مَرامُهُ.', 'One whose endeavour is great, his cause is worthy.', 'Ghurar al-Hikam, Endeavours- §8', 'wisdom'),
  ('اِقْصِرْ هِمَّتَكَ عَلى ما يَلْزِمُكَ، ولاتَخُضْ فيما لايَعْنيكَ.', 'Confine your endeavour to that which is necessary for you and do not enter into that which does not concern you.', 'Ghurar al-Hikam, Endeavours- §9', 'wisdom'),
  ('مَنْ رَقى دَرَجاتِ الهِمَمِ عَظَّمَتْهُ الأُمَمُ.', 'One who rises to the [higher] levels of endeavour [and determination] is glorified [and considered as great] by the nations.', 'Ghurar al-Hikam, Endeavours- §10', 'wisdom'),
  ('مَنْ تَهَوَّرَ نَدِمَ.', 'One who acts irresponsibly regrets.', 'Ghurar al-Hikam, Irresponsibility- §1', 'wisdom'),
  ('مَنْ رَكِبَ الأهْوالَ اِكْتَسَبَ الأمْوالَ.', 'Whoever embarks on the frightful [and risky] earns wealth.', 'Ghurar al-Hikam, The frightful- §1', 'wisdom'),
  ('مَنِ اسْتَهانَ بِالرِّجالِ قَلَّ.', 'Whoever treats people with disdain, [his status] diminishes.', 'Ghurar al-Hikam, Disdain- §1', 'wisdom'),
  ('اِغْلِبُوا أهْوائَـكُمْ، وهارِبُوها، فَإنَّها إنْ تُقَيِّدْكُمْ تُورِدْكُمْ مِنَ الهَلَكَةِ أبْعَدَ غايَة.', 'Overcome your vain desires and flee from them, for indeed if they capture you they will take you into the farthest depths of destruction.', 'Ghurar al-Hikam, Vain desire- §1', 'wisdom'),
  ('إيّاكُمْ وتَمَكُّنَ الهَوى مِنْكُمْ، فَإنَّ أوَّلَهُ فِتْنَةٌ، وآخِرَهُ مِحْنَةٌ.', 'Beware of allowing vain desire to gain control over you for indeed its beginning is temptation and its end is tribulation.', 'Ghurar al-Hikam, Vain desire- §2', 'wisdom'),
  ('اَلا وإنَّ أخْوَفَ ما أخافُ عَلَيْكُمْ اِتِّباعُ الهَوى، وطُولُ الأمَلِ.', 'Indeed, the thing I fear most for you is [the result of your] following vain desires and having lengthy aspirations.', 'Ghurar al-Hikam, Vain desire- §3', 'wisdom'),
  ('اَلْهَوى يُرْدي.', 'Vain desire destroys.', 'Ghurar al-Hikam, Vain desire- §4', 'wisdom'),
  ('اَلْهَوى صَبْوَةٌ.', 'Vain desires are passions of youth.', 'Ghurar al-Hikam, Vain desire- §5', 'wisdom'),
  ('اَلْهَوى عَدُّوُ العَقْلِ.', 'Vain desire is the enemy of reason.', 'Ghurar al-Hikam, Vain desire- §6', 'wisdom'),
  ('اَلْهَوى آفَةُ الألْبابِ.', 'Vain desire is the bane of the intellects.', 'Ghurar al-Hikam, Vain desire- §7', 'wisdom'),
  ('اَلْهَوى عَدُوٌّ مَتْبُوعٌ.', 'Vain desire is an obeyed enemy.', 'Ghurar al-Hikam, Vain desire- §8', 'wisdom'),
  ('إنَّكَ إنْ أطَعْتَ هَواكَ أصَمَّكَ وأعْماكَ وأفْسَدَ مُنْقَلَبَكَ وَأرْداكَ.', 'Verily if you follow your vain desire, it will make you deaf and blind, ruin your place of [final] return and destroy you.', 'Ghurar al-Hikam, Vain desire- §9', 'wisdom'),
  ('إنَّكُمْ إنْ أمَّرْتُمْ عَلَيْكُمُ الهَوى أصَمَّكُمْ، وأعْماكُمْ، وَأرْداكُمْ.', 'Verily if you allow vain desire rule over you, it will deafen you, blind you and destroy you.', 'Ghurar al-Hikam, Vain desire- §10', 'wisdom'),
  ('اَلْهَيْبَةُ خَيْبَةٌ.', 'Dread is [a cause of] failure.', 'Ghurar al-Hikam, Dread and awe- §1', 'wisdom'),
  ('اَلْهَيْبَةُ مَقْرُونَةٌ بِالخَيْبَةِ.', 'Dread is accompanied by failure.', 'Ghurar al-Hikam, Dread and awe- §2', 'wisdom'),
  ('آفَةُ الهَيْبَةِ المَزاحُ.', 'The bane of awe is jest.', 'Ghurar al-Hikam, Dread and awe- §3', 'wisdom'),
  ('قُرِنَتِ الهَيْبَةُ بِالخَيْبَةِ.', 'Dread has been paired with failure.', 'Ghurar al-Hikam, Dread and awe- §4', 'wisdom'),
  ('اَلْيَأسُ أحَدُ النُّجْحَيْنِ.', 'Loss of hope [in others] is one of the two successes.', 'Ghurar al-Hikam, Dread and awe- §1', 'wisdom'),
  ('إنَّ أكْرَمَ النّاسِ مَنِ اقْتَنَى الْيَأْسَ، ولَزِمَ القُنُوعَ والوَرَعَ، وبَرِيَ مِنَ الحِرْصِ والطَّمََعِ، فَإنَّ الطَّمَعَ والحِرْصَ اَلْفَقْرُ الحاضِرُ، وإنَّ الْيَأسَ والقَناعَةَ الغِنىَ الظّاهِرُ.', 'Verily the most honourable of all people is one who loses hope [in others], espouses contentment and piety and is devoid of greed and covetousness, for indeed covetousness and greed are a ready indigence and verily loss of hope [in others] and contentment are a manifest affluence.', 'Ghurar al-Hikam, Dread and awe- §3', 'wisdom'),
  ('اَلْيَأسُ حُرٌّ.', 'Loss of hope [in others] is freedom.', 'Ghurar al-Hikam, Dread and awe- §4', 'wisdom'),
  ('اَلْيَأسُ عِتْقٌ.', 'Loss of hope [in others] is liberty.', 'Ghurar al-Hikam, Dread and awe- §5', 'wisdom'),
  ('اَلْيَأسُ مَسْلاةٌ.', 'Loss of hope [in this world] is a solace.', 'Ghurar al-Hikam, Dread and awe- §6', 'wisdom'),
  ('اَلْيَأسُ غِناءٌ حاضِرٌ.', 'Loss of hope [in this world] is a ready affluence.', 'Ghurar al-Hikam, Dread and awe- §7', 'wisdom'),
  ('بَـرُّوا أيْتامَكُمْ، وواسَوْا فُقَرائَـكُمْ، وارْفُقُوا بِضُعَفائِكُمْ.', 'Be good to your orphans, help your poor folk and be kind to the weak amongst you.', 'Ghurar al-Hikam, Orphans §1', 'wisdom'),
  ('مَنْ ظَلَمَ يَتيماً عَقَّ أوْلادَهُ.', 'Whoever oppresses an orphan has severed his ties with his children.', 'Ghurar al-Hikam, Orphans §2', 'wisdom'),
  ('مَنْ رَعَى الأيْتامَ رُعِيَ في بَنيهِ.', 'Whoever takes care of the orphans, his children will be cared for.', 'Ghurar al-Hikam, Orphans §3', 'wisdom'),
  ('كافِلُ اليَتيمِ والمِسْكينِ عِنْدَ اللّهِ مِنَ المُكْرَمينَ.', 'The one who takes charge of caring for the orphans and the needy is considered [to be] among the honourable ones in the sight of Allah.', 'Ghurar al-Hikam, Orphans §4', 'wisdom'),
  ('كافِلُ اليَتيمِ اَثيْرٌ عِنْدَ اللّهِ.', 'One who takes charge of caring for the orphans is favoured in the sight of Allah.', 'Ghurar al-Hikam, Orphans §5', 'wisdom'),
  ('اَلتَّيَقُّظُ فِي الدّينِ نِعْمَةٌ عَلى مَنْ رُزِقَهُ.', 'Vigilance in religion is a blessing for the one whom it is bestowed upon.', 'Ghurar al-Hikam, Alertness And Vigilance §1', 'wisdom'),
  ('اَلْيَقْظَةُ نُورٌ، اَلْغَفْلَةُ غُرُورٌ.', 'Alertness is illumination, negligence is delusion.', 'Ghurar al-Hikam, Alertness And Vigilance §2', 'wisdom'),
  ('اَلْيَقْظَةُ اِسْتِبْصارٌ.', 'Alertness is perspicacity.', 'Ghurar al-Hikam, Alertness And Vigilance §3', 'wisdom'),
  ('قَدْ يُقِّظْتُمْ فَتَـيَقَّظُوا، وهُديتُمْ فَاهْتَدُوا.', 'Indeed you have been alerted so become vigilant, and you have been guided so follow the guidance.', 'Ghurar al-Hikam, Alertness And Vigilance §4', 'wisdom'),
  ('مَنْ لَمْ يَسْتَظْهِرْ بِاليَقْظَةِ لَمْ يَنْتَفِعْ بِالحَفَظَةِ.', 'One who does not take support through vigilance will not benefit from [the presence of] guards.', 'Ghurar al-Hikam, Alertness And Vigilance §5', 'wisdom'),
  ('اَلْيَقْظَةُ كَرَبٌ.', 'Alertness is [a cause of] grief.', 'Ghurar al-Hikam, Alertness And Vigilance §6', 'wisdom'),
  ('أفِقْ أَيُّهَا السّامِعُ مِنْ سَكْرَتِكَ، واسْتَيْقِظْ مِنْ غَفْلَتِكَ، وَاحْتَصِرْ(اِخْتَصِرْ) مِنْ عَجَلَتِكَ.', 'Recover, O listener, from your stupor, and wake up from your heedlessness, and curb (or cut short) your haste [towards sins].', 'Ghurar al-Hikam, Alertness And Vigilance §7', 'wisdom'),
  ('اَلا مُسْتَيْقِظٌ مِنْ غَفْلَتِهِ قَبْلَ نَفادِ مُدَّتِهِ.', 'Is there nobody who will wake up from his [slumber of] negligence before his time [on this earth] ends?', 'Ghurar al-Hikam, Alertness And Vigilance §8', 'wisdom'),
  ('أيْقِنْ (أتْقِنْ) تُفْلِحْ.', 'Attain certitude (or proficiency) and you will be successful.', 'Ghurar al-Hikam, Certitude- §1', 'wisdom'),
  ('أفْضَلُ الدّينِ اليَقينُ.', 'The best faith is certitude.', 'Ghurar al-Hikam, Certitude- §2', 'wisdom'),
  ('أصْلُ الصَّبْرِ حُسْنُ اليَقينِ بِاللّهِ.', 'The root of patience is [having] definite certainty about Allah.', 'Ghurar al-Hikam, Certitude- §3', 'wisdom'),
  ('أصْلُ الزُّهْدِ اَلْيَقينُ، وثَمَرَتُهُ السَّعادَةُ.', 'The root of indifference towards worldly pleasures is certitude, and its fruit is felicity.', 'Ghurar al-Hikam, Certitude- §4', 'wisdom'),
  ('اَلْيَقينُ عِبادَةٌ.', 'Certitude is worship.', 'Ghurar al-Hikam, Certitude- §5', 'wisdom'),
  ('اَلْيَقينُ نُورٌ.', 'Certitude is light.', 'Ghurar al-Hikam, Certitude- §6', 'wisdom'),
  ('اَلْيَقينُ عُنْوانُ الإيمانِ.', 'Certitude is the symbol of faith.', 'Ghurar al-Hikam, Certitude- §7', 'wisdom'),
  ('اَلْيَقينُ أفْضَلُ الزَّهادَةِ.', 'Certitude is the best [means of] indifference towards [the pleasures of] this world.', 'Ghurar al-Hikam, Certitude- §8', 'wisdom'),
  ('اَلْيَقينُ عِمادُ الإيمانِ.', 'Certitude is the pillar of faith.', 'Ghurar al-Hikam, Certitude- §9', 'wisdom'),
  ('اَلْيَقينُ جِلْبابُ الأكْياسِ.', 'Certitude is the gown of the sagacious.', 'Ghurar al-Hikam, Certitude- §10', 'wisdom'),
  ('الْبُخْلُ عَارٌ، وَالْجُبْنُ مَنْقَصَةٌ، وَالْفَقْرُ يُخْرِسُ الْفَطِنَ عَنْ حُجَّتِهِ', 'Miserliness is shame, cowardice is a defect, and poverty silences the sharp-minded from his case.', 'Nahj al-Balagha, Saying 3', 'character'),
  ('الْعِلْمُ وَرَاثَةٌ كَرِيمَةٌ، وَالْآدَابُ حُلَلٌ حِسَانٌ', 'Knowledge is a noble inheritance, and good manners are fine robes.', 'Nahj al-Balagha, Saying 5', 'wisdom'),
  ('الذُّلُّ قَدْ يَصُونُ مَالَ صَاحِبِهِ وَيُبَقِّيهِ لَهُ', 'Humiliation at times preserves one''s wealth and keeps it for him.', 'Nahj al-Balagha, Saying 8', 'detachment'),
  ('إِذَا قَدَرْتَ عَلَى عَدُوِّكَ فَاجْعَلِ الْعَفْوَ عَنْهُ شُكْراً لِلْقُدْرَةِ عَلَيْهِ', 'When you gain power over your adversary, pardon him as thanks for being able to overpower him.', 'Nahj al-Balagha, Saying 11', 'forgiveness'),
  ('أَعْجَزُ النَّاسِ مَنْ عَجَزَ عَنِ اكْتِسَابِ الْإِخْوَانِ', 'The most helpless is he who cannot gain a brother in faith; more helpless still is he who loses the one he finds.', 'Nahj al-Balagha, Saying 12', 'relationships'),
  ('لَا يَعْدَمُ الصَّبُورُ الظَّفَرَ وَإِنْ طَالَ بِهِ الزَّمَانُ', 'The patient never misses success, even if it takes a long time.', 'Nahj al-Balagha, Saying 17', 'patience'),
  ('الْفُرْصَةُ تَمُرُّ مَرَّ السَّحَابِ، فَانْتَهِزُوا فُرَصَ الْخَيْرِ', 'Opportunity passes like the cloud — so seize the opportunities for good.', 'Nahj al-Balagha, Saying 21', 'purpose'),
  ('لَا يُقِيمُ أَمْرَ اللَّهِ سُبْحَانَهُ إِلَّا مَنْ لَا يُصَانِعُ وَلَا يُضَارِعُ', 'Only one who neither flatters nor gives up can uphold God''s command.', 'Nahj al-Balagha, Saying 27', 'character'),
  ('مَنِ اتَّجَرَ بِغَيْرِ فِقْهٍ فَقَدِ ارْتَطَمَ فِي الرِّبَا', 'Whoever trades without understanding falls headlong into usury.', 'Nahj al-Balagha, Saying 31', 'wisdom'),
  ('مَنْ أَطَالَ الْأَمَلَ أَسَاءَ الْعَمَلَ', 'Whoever prolongs his desires ruins his actions.', 'Nahj al-Balagha, Saying 36', 'purpose'),
  ('الْمَرْءُ حَيْثُ وَضَعَ نَفْسَهُ', 'A person is [worth] wherever he places himself.', 'Nahj al-Balagha, Saying 38', 'self-mastery'),
  ('كُلُّ مُعَاجَلٍ يَسْأَلُ الْإِنَاظَرَةَ وَكُلُّ مُؤَجَّلٍ يَتَعَلَّلُ بِالتَّسْوِيفِ', 'Every person in a hurry wishes for delay, and every procrastinator makes excuses for postponing.', 'Nahj al-Balagha, Saying 41', 'purpose'),
  ('لَيْسَ لِعَاقِلٍ أَنْ يَكُونَ شَاخِصاً إِلَّا فِي ثَلَاثَةٍ: مَرَمَّةٍ لِمَعَاشٍ، أَوْ خُطْوَةٍ فِي مَعَادٍ، أَوْ لَذَّةٍ فِي غَيْرِ مَحَرَّمٍ', 'A wise person should not be away from home except for three reasons: provision of livelihood, a step toward the Hereafter, or lawful pleasure.', 'Nahj al-Balagha, Saying 45', 'wisdom'),
  ('قِيمَةُ كُلِّ امْرِئٍ مَا يُحْسِنُهُ', 'The worth of every person is what they do well.', 'Nahj al-Balagha, Saying 47', 'purpose'),
  ('لَا يَصْدُقُ الَّذِي يَطَّلِعُ عَلَى سِرِّكَ', 'One who reveals your secret to others is not truthful to you.', 'Nahj al-Balagha, Saying 49', 'relationships'),
  ('مَنِ اسْتَبَدَّ بِرَأْيِهِ هَلَكَ وَمَنْ شَاوَرَ الرِّجَالَ شَارَكَهَا فِي عُقُولِهَا', 'One who is self-opinionated is destroyed; one who consults men shares in their wisdom.', 'Nahj al-Balagha, Saying 51', 'wisdom'),
  ('لَا مَالَ أَعْوَدُ مِنَ الْعَقْلِ', 'No wealth is more profitable than the intellect.', 'Nahj al-Balagha, Saying 53', 'wisdom'),
  ('مَنْ نَصَبَ نَفْسَهُ لِلنَّاسِ إِمَاماً فَلْيَبْدَأْ بِتَعْلِيمِ نَفْسِهِ قَبْلَ تَعْلِيمِ غَيْرِهِ', 'One who sets himself up as a leader of people should teach himself before teaching others.', 'Nahj al-Balagha, Saying 57', 'leadership'),
  ('مَنْ جَرَى فِي عِنَانِ أَمَلِهِ عَثَرَ بِأَجَلِهِ', 'Whoever runs in the reins of his desires stumbles over his appointed time.', 'Nahj al-Balagha, Saying 64', 'mortality'),
  ('لَنْ يُهْلِكَ امْرَأً عَرَفَ قَدْرَهُ', 'No one is destroyed who knows his own worth.', 'Nahj al-Balagha, Saying 66', 'self-mastery'),
  ('مَنْ زَهِدَ فِي الدُّنْيَا اسْتَهَانَ بِالْمُصِيبَاتِ', 'Whoever is detached from the world treats calamities as trivial.', 'Nahj al-Balagha, Saying 68', 'detachment'),
  ('إِذَا تَمَّ الْعَقْلُ نَقَصَ الْكَلَامُ', 'When the intellect is perfected, speech grows less.', 'Nahj al-Balagha, Saying 71', 'wisdom'),
  ('رُبَّمَا كَانَ الدَّوَاءُ دَاءً وَالدَّاءُ دَوَاءً', 'Sometimes the cure is the disease and the disease is the cure.', 'Nahj al-Balagha, Saying 73', 'wisdom'),
  ('رُبَّمَا كَانَ الْيَأْسُ إِدْرَاكاً، إِذَا كَانَ الطَّمَعُ هَلَاكاً', 'Sometimes despair is attainment, when greed is destruction.', 'Nahj al-Balagha, Saying 74', 'hope'),
  ('أَجِلُّوا اللَّهَ أَنْ تَذْكُرُوهُ عِنْدَ كُلِّ خَسِيسَةٍ', 'Honour God by not mentioning Him except for worthy matters.', 'Nahj al-Balagha, Saying 79', 'faith'),
  ('الصَّبْرُ صِنْفَانِ: صَبْرٌ عَلَى مَا تَكْرَهُ، وَصَبْرٌ عَنْ مَا تُحِبُّ', 'Patience is of two kinds: patience with what you dislike, and patience away from what you desire.', 'Nahj al-Balagha, Saying 81', 'patience'),
  ('الصَّبْرُ مِنَ الْإِيمَانِ كَالرَّأْسِ مِنَ الْجَسَدِ', 'Patience is to faith what the head is to the body.', 'Nahj al-Balagha, Saying 82', 'patience'),
  ('أَشْجَعُ النَّاسِ مَنْ غَلَبَ هَوَاهُ', 'The bravest of people is one who conquers his desires.', 'Nahj al-Balagha, Saying 83', 'self-mastery'),
  ('التَّوَاضُعُ يُورِثُ الرِّفْعَةَ', 'Humility brings elevation.', 'Nahj al-Balagha, Saying 85', 'character'),
  ('عَجِبْتُ لِمَنْ يَقْنَطُ وَمَعَهُ الِاسْتِغْفَارُ', 'I wonder at one who despairs while still possessing the means of seeking forgiveness.', 'Nahj al-Balagha, Saying 87', 'forgiveness'),
  ('لَا فَقْرَ أَشَدُّ مِنَ الْجَهْلِ', 'There is no poverty worse than ignorance.', 'Nahj al-Balagha, Saying 88', 'wisdom'),
  ('مَنْ حَاسَبَ نَفْسَهُ رَبِحَ، وَمَنْ غَفَلَ عَنْهَا خَسِرَ', 'Whoever takes himself to account profits; whoever neglects himself loses.', 'Nahj al-Balagha, Saying 91', 'self-mastery'),
  ('الدَّهْرُ يُخْلِقُ الْأَبْدَانَ، وَيُجَدِّدُ الْآمَالَ، وَيُقَرِّبُ الْمَنِيَّةَ', 'Time wears away bodies, renews hopes, and brings death closer.', 'Nahj al-Balagha, Saying 96', 'mortality'),
  ('كُلُّ شَيْءٍ يَنْقُصُهُ الْإِنْفَاقُ إِلَّا الْعِلْمَ', 'Everything is diminished by spending except knowledge.', 'Nahj al-Balagha, Saying 100', 'wisdom'),
  ('مَنْ أَطَاعَ التَّوَانِيَ ضَيَّعَ الْحُقُوقَ', 'Whoever follows laziness squanders rights.', 'Nahj al-Balagha, Saying 108', 'purpose'),
  ('فَازَ مَنْ نَاضَلَ بِعِلْمٍ', 'Whoever strives with knowledge succeeds.', 'Nahj al-Balagha, Saying 113', 'wisdom'),
  ('إِضَاعَةُ الْفُرْصَةِ غُصَّةٌ', 'To miss an opportunity is a source of grief.', 'Nahj al-Balagha, Saying 118', 'purpose'),
  ('الْحِرَصُ رِقٌّ مُؤَبَّدٌ', 'Greed is perpetual slavery.', 'Nahj al-Balagha, Saying 120', 'detachment'),
  ('نَتِيجَةُ الْكَسَلِ النَّدَامَةُ', 'The fruit of laziness is regret.', 'Nahj al-Balagha, Saying 121', 'purpose'),
  ('اتَّقِ اللَّهَ بَعْضَ التُّقَى وَإِنْ قَلَّ', 'Fear God to some extent, however little.', 'Nahj al-Balagha, Saying 128', 'faith'),
  ('الدُّنْيَا دَارُ مَمَرٍّ لَا دَارُ مَقَرٍّ', 'This world is a place of passage, not a place of stay.', 'Nahj al-Balagha, Saying 133', 'detachment'),
  ('لَا يَكُونُ الصَّدِيقُ صَدِيقاً حَتَّى يَحْفَظَ أَخَاهُ فِي ثَلَاثٍ: فِي نَكْبَتِهِ، وَغَيْبَتِهِ، وَوَفَاتِهِ', 'A friend is not truly a friend until he safeguards his brother in three things: in his misfortune, in his absence, and after his death.', 'Nahj al-Balagha, Saying 134', 'relationships'),
  ('كَمْ مِنْ صَائِمٍ لَيْسَ لَهُ مِنْ صِيَامِهِ إِلَّا الْجُوعُ وَالظَّمَأُ', 'How many a fasting person gains nothing from their fast but hunger and thirst.', 'Nahj al-Balagha, Saying 136', 'faith'),
  ('إِنَّمَا الْمَرْءُ فِي الدُّنْيَا غَرَضٌ تَنْتَضِلُ فِيهِ الْمَنَايَا، وَنَهْبٌ تُبَادِرُهُ الْمَصَائِبُ', 'Truly man in this world is a target at which calamities shoot, and a prize which misfortunes race to claim.', 'Nahj al-Balagha, Saying 139', 'mortality'),
  ('الرَّأْيُ مَعَ الصَّوَابِ لَا مَعَ الشَّجَاعَةِ', 'Sound judgment lies with what is right, not with courage alone.', 'Nahj al-Balagha, Saying 143', 'wisdom'),
  ('مَنْ كَرُمَتْ عَلَيْهِ نَفْسُهُ هَانَتْ عَلَيْهِ شَهَوَاتُهُ', 'Whoever honours his soul, his desires become insignificant to him.', 'Nahj al-Balagha, Saying 147', 'self-mastery'),
  ('الْمَرْءُ مَخْبُوءٌ تَحْتَ لِسَانِهِ', 'A person lies hidden beneath his tongue.', 'Nahj al-Balagha, Saying 148', 'wisdom'),
  ('هَلَكَ امْرُؤٌ لَمْ يَعْرِفْ قَدْرَهُ', 'Ruined is the one who does not know his own worth.', 'Nahj al-Balagha, Saying 149', 'self-mastery'),
  ('خُذِ الْحِكْمَةَ أَنَّى كَانَتْ', 'Take wisdom from wherever it comes.', 'Nahj al-Balagha, Saying 150', 'wisdom'),
  ('لَا يَزَالُ الزُّبَيْرُ مِنَّا أَهْلَ الْبَيْتِ حَتَّى يَنْشَأَ ابْنُهُ عَبْدُ اللَّهِ', 'Seeking help from God is a duty upon every person in every circumstance.', 'Nahj al-Balagha, Saying 155', 'faith'),
  ('مَنْ طَلَبَ أَخَاً بِلَا عَيْبٍ بَقِيَ بِلَا أَخٍ', 'Whoever seeks a friend without any faults remains without a friend.', 'Nahj al-Balagha, Saying 160', 'relationships'),
  ('مَنْ أَكْثَرَ أَهْجَرَ', 'Whoever speaks too much, speaks nonsense.', 'Nahj al-Balagha, Saying 161', 'wisdom'),
  ('لَا طَاعَةَ لِمَخْلُوقٍ فِي مَعْصِيَةِ الْخَالِقِ', 'There is no obedience to any creature in disobedience to the Creator.', 'Nahj al-Balagha, Saying 163', 'faith'),
  ('تَرْكُ الذَّنْبِ أَهْوَنُ مِنْ طَلَبِ التَّوْبَةِ', 'Leaving a sin is easier than seeking repentance afterwards.', 'Nahj al-Balagha, Saying 170', 'forgiveness'),
  ('النَّاسُ أَعْدَاءُ مَا جَهِلُوا', 'People are enemies of what they do not know.', 'Nahj al-Balagha, Saying 172', 'wisdom'),
  ('الْعَقْلُ حِفْظُ التَّجَارِبِ', 'Intellect is the preservation of experiences.', 'Nahj al-Balagha, Saying 173', 'wisdom'),
  ('لَا عِلْمَ كَالتَّفَكُّرِ', 'No knowledge is like contemplation.', 'Nahj al-Balagha, Saying 174', 'wisdom'),
  ('لَا عِبَادَةَ كَالتَّفَكُّرِ فِي صَنْعَةِ اللَّهِ', 'No worship is like contemplating the work of God.', 'Nahj al-Balagha, Saying 175', 'faith'),
  ('الطَّمَعُ رِقٌّ مُؤَبَّدٌ', 'Greed is perpetual slavery.', 'Nahj al-Balagha, Saying 176', 'detachment'),
  ('مَنِ اعْتَدَلَتْ سَجِيَّتُهُ كَثُرَ مُحِبُّوهُ', 'Whoever is balanced in character, his admirers increase.', 'Nahj al-Balagha, Saying 188', 'character'),
  ('لَا دِينَ لِمَنْ لَا وَفَاءَ لَهُ', 'No religion for one who has no faithfulness.', 'Nahj al-Balagha, Saying 196', 'character'),
  ('كُونُوا دُعَاةً إِلَى الله بِغَيْرِ أَلْسِنَتِكُمْ', 'Be callers to God through other than your tongues — through your character and conduct.', 'Nahj al-Balagha, Saying 199', 'faith'),
  ('كُلُّ وِعَاءٍ يَضِيقُ بِمَا جُعِلَ فِيهِ إِلَّا وِعَاءَ الْعِلْمِ، فَإِنَّهُ يَتَّسِعُ', 'Every vessel grows narrower with what is placed in it — except the vessel of knowledge, which only expands.', 'Nahj al-Balagha, Saying 205', 'wisdom'),
  ('لَيْسَ مِنَ الْحَقِّ أَنْ تَكُونَ سِعَةُ الْبَطْنِ أَهَمَّ عِنْدَكَ مِنْ دَفْعِ الظُّلْمِ', 'It is not right that filling your belly should be more important to you than resisting injustice.', 'Nahj al-Balagha, Saying 211', 'justice'),
  ('أَمْلِكُوا أَنْفُسَكُمْ', 'Take control of your own selves.', 'Nahj al-Balagha, Saying 213', 'self-mastery'),
  ('الصِّدْقُ سَيْفٌ مِنْ سُيُوفِ اللَّهِ', 'Truthfulness is a sword from the swords of God.', 'Nahj al-Balagha, Saying 215', 'character'),
  ('مَنْ كَسَاهُ الْحَيَاءُ ثَوْبَهُ، لَمْ يَرَ النَّاسُ عَيْبَهُ', 'Whomever modesty clothes in its garment, people will not see his faults.', 'Nahj al-Balagha, Saying 223', 'character'),
  ('لَا ذُلَّ كَذُلِّ الطَّمَعِ', 'No humiliation is like the humiliation of greed.', 'Nahj al-Balagha, Saying 224', 'detachment'),
  ('لَا يَسْتَقِيمُ قَضَاءُ الْحَوَائِجِ إِلَّا بِثَلَاثَةٍ: بِاسْتِصْغَارِهَا لِتَعْظُمَ، وَبِاسْتِكْتَامِهَا لِتَظْهَرَ، وَبِتَعْجِيلِهَا لِتَهْنُؤَ', 'Fulfilling needs can only be done properly with three things: considering them small so they grow large, keeping them secret so they appear, and hastening them so they become pleasant.', 'Nahj al-Balagha, Saying 227', 'wisdom'),
  ('أَلَا إِنَّ اللِّسَانَ بَضْعَةٌ مِنَ الْإِنْسَانِ', 'Truly the tongue is a part of man.', 'Nahj al-Balagha, Saying 234', 'wisdom'),
  ('اللُّؤْمُ أَنْ لَا تَشْكُرَ النِّعْمَةَ', 'Meanness is failing to be grateful for a blessing.', 'Nahj al-Balagha, Saying 239', 'gratitude'),
  ('لَيْسَ لِلْعَاقِلِ أَنْ يَكُونَ فِي زَمَانِهِ هَاجِعاً', 'A wise person cannot afford to be heedless of the times in which he lives.', 'Nahj al-Balagha, Saying 248', 'wisdom'),
  ('الْغَرُورُ يَكُونُ مِنَ الدُّنْيَا وَالنَّاسِ وَالشَّيْطَانِ', 'Delusion comes from the world, from people, and from Satan.', 'Nahj al-Balagha, Saying 252', 'self-mastery'),
  ('الْبُعْدُ عَنِ الطَّمَعِ صِيَانَةٌ', 'Keeping away from greed is a protection.', 'Nahj al-Balagha, Saying 255', 'detachment'),
  ('كَفَاكَ أَدَباً لِنَفْسِكَ اجْتِنَابُ مَا تَكْرَهُهُ مِنْ غَيْرِكَ', 'It suffices as self-discipline to avoid for yourself what you dislike in others.', 'Nahj al-Balagha, Saying 260', 'character'),
  ('مَا أَضَلَّ الْعَقْلَ الْهَوَى', 'How desire misleads the intellect!', 'Nahj al-Balagha, Saying 265', 'self-mastery'),
  ('يَا ابْنَ آدَمَ، لَا تَحْمِلْ هَمَّ يَوْمِكَ الَّذِي لَمْ يَأْتِكَ عَلَى يَوْمِكَ الَّذِي قَدْ أَتَاكَ', 'O son of Adam, do not carry the worry of a day not yet come into the day already here — God will bring its provision when it arrives.', 'Nahj al-Balagha, Saying 267', 'patience'),
  ('أَحْبِبْ حَبِيبَكَ هَوْناً مَا، عَسَى أَنْ يَكُونَ بَغِيضَكَ يَوْماً مَا', 'Love your friend with moderation, for he may become your enemy; and hate your enemy with moderation, for he may become your friend.', 'Nahj al-Balagha, Saying 268', 'relationships'),
  ('لَا يَعِيبُ الرَّجُلَ أَنْ يَكُونَ مُقَصِّراً فِي الدُّنْيَا إِذَا كَانَ مُتَّسِعاً فِي دِينِهِ', 'It is no fault for a man to fall short in the world if he is generous in his religion.', 'Nahj al-Balagha, Saying 270', 'faith'),
  ('أَفْضَلُ الزُّهْدِ إِخْفَاءُ الزُّهْدِ', 'The best asceticism is concealing one''s asceticism.', 'Nahj al-Balagha, Saying 276', 'detachment'),
  ('صِحَّةُ الْجَسَدِ مِنْ قِلَّةِ الْحَسَدِ', 'Health of the body comes from freedom of envy.', 'Nahj al-Balagha, Saying 279', 'character'),
  ('أَشَدُّ الذُّنُوبِ مَا اسْتَهَانَ بِهِ صَاحِبُهُ', 'The gravest sins are those treated lightly by their owner.', 'Nahj al-Balagha, Saying 285', 'forgiveness'),
  ('ذِكْرُ الرِّجَالِ فِي مَجَالِسِهِمْ مَقَابِرُهُمْ', 'Mentioning men in their presence is their burial.', 'Nahj al-Balagha, Saying 289', 'wisdom'),
  ('لَا تَسْأَلُ عَمَّا لَا يَعْنِيكَ', 'Do not ask about what does not concern you.', 'Nahj al-Balagha, Saying 290', 'wisdom'),
  ('إِنَّمَا سُمِّيَ الْعَقْلُ عَقْلاً لِأَنَّهُ يَعْقِلُ صَاحِبَهُ عَنِ الشَّرِّ', 'The intellect is called intellect because it restrains its owner from evil.', 'Nahj al-Balagha, Saying 295', 'wisdom'),
  ('مَا أَكْثَرَ الْعِبَرَ، وَأَقَلَّ الِاعْتِبَارَ', 'How many are the lessons, and how few take heed.', 'Nahj al-Balagha, Saying 297', 'wisdom'),
  ('أَقِلُّوا الطَّلَبَ لِلدُّنْيَا تَرْبَحُوا', 'Reduce your pursuit of the world and you will profit.', 'Nahj al-Balagha, Saying 302', 'detachment'),
  ('رُبَّ مَفْتُونٍ بِحُسْنِ الْقَوْلِ فِيهِ', 'Many a person is deluded by the good things said about him.', 'Nahj al-Balagha, Saying 334', 'character'),
  ('مَنِ اتَّخَذَ أَخاً مِنْ غَيْرِ اخْتِبَارٍ أَلْجَأَهُ الاضْطِرَارُ إِلَى مُرَافَقَةِ الْأَشْرَارِ', 'Whoever takes a brother without testing him, necessity will drive him to the company of the wicked.', 'Nahj al-Balagha, Saying 338', 'relationships'),
  ('غَايَةُ الْعِلْمِ الِاعْتِبَارُ', 'The goal of knowledge is to take heed from it.', 'Nahj al-Balagha, Saying 342', 'wisdom'),
  ('غَايَةُ الزُّهْدِ الْقَنَاعَةُ', 'The goal of asceticism is contentment.', 'Nahj al-Balagha, Saying 343', 'detachment'),
  ('إِذَا كُنْتَ فِي إِدْبَارٍ فَاصْبِرْ حَتَّى يُقْبِلَ', 'When you are in retreat, be patient until prosperity returns.', 'Nahj al-Balagha, Saying 345', 'patience'),
  ('مَنْ صَبَرَ عَلَى الْمُصِيبَةِ اعْتَاضَ مِنْهَا بِمَنْفَعَةٍ', 'Whoever is patient with a calamity is compensated for it with benefit.', 'Nahj al-Balagha, Saying 348', 'patience'),
  ('طُوبَى لِمَنْ ذَكَرَ الْمَعَادَ وَعَمِلَ لِلْحِسَابِ وَقَنِعَ بِالْكَفَافِ', 'Blessed is one who remembers the Hereafter, works for the Reckoning, and is content with sufficiency.', 'Nahj al-Balagha, Saying 350', 'mortality'),
  ('كَثْرَةُ الصَّمْتِ تُهَيِّبُ', 'Frequent silence produces awe.', 'Nahj al-Balagha, Saying 356', 'character'),
  ('يَا كُمَيْلُ، مَا مِنْ حَرَكَةٍ إِلَّا وَأَنْتَ مُحْتَاجٌ فِيهَا إِلَى مَعْرِفَةٍ', 'O Kumayl, there is no movement without a need for knowledge.', 'Nahj al-Balagha, Saying 378', 'wisdom'),
  ('مَنْ أَطَاعَ الْمُنَى خَانَتْهُ', 'Whoever obeys wishful hopes, they will betray him.', 'Nahj al-Balagha, Saying 390', 'purpose'),
  ('جَاهِلٌ تَسْمَعُ مِنْهُ الْحِكْمَةَ خَيْرٌ مِنْ عَالِمٍ تَسْمَعُ مِنْهُ الْجَهْلَ', 'An ignorant person from whom you hear wisdom is better than a scholar from whom you hear ignorance.', 'Nahj al-Balagha, Saying 396', 'wisdom'),
  ('الرِّفْقُ يُيَسِّرُ الصِّعَابَ وَيُسَهِّلُ شَدِيدَ الْأَسْبَابِ', 'Gentleness makes difficulties easy and smooths harsh conditions.', 'Nahj al-Balagha, Saying 398', 'character'),
  ('مَنْ وَثِقَ بِاللَّهِ أَغْنَاهُ', 'Whoever trusts in God, God enriches him.', 'Nahj al-Balagha, Saying 399', 'faith'),
  ('أَعْقَلُ النَّاسِ أَعْلَمُهُمْ بِالنَّفْسِ', 'The most rational of people is the most knowledgeable of himself.', 'Nahj al-Balagha, Saying 403', 'self-mastery'),
  ('شَرُّ النَّاسِ مَنْ يَنْهَى عَنِ الذُّنُوبِ وَهُوَ يَفْعَلُهَا', 'The worst of people is one who forbids sins while committing them himself.', 'Nahj al-Balagha, Saying 410', 'character'),
  ('الْحِلْمُ غِطَاءٌ سَاتِرٌ، وَالْعَقْلُ حُسَامٌ قَاطِعٌ، فَاسْتُرْ خَلَلَ خُلُقِكَ بِحِلْمِكَ', 'Forbearance is a concealing veil and intellect is a cutting sword — cover the flaws of your character with your forbearance and fight your desires with your intellect.', 'Nahj al-Balagha, Saying 424', 'self-mastery'),
  ('مَنْ لَا يَنْفَعُكَ حُبُّهُ لَا يَضُرُّكَ بُغْضُهُ', 'Whoever''s love does not benefit you, his hatred does not harm you.', 'Nahj al-Balagha, Saying 434', 'relationships'),
  ('عَوِّدْ نَفْسَكَ الصَّبْرَ', 'Train yourself to patience.', 'Nahj al-Balagha, Saying 453', 'patience'),
  ('إِيَّاكَ أَنْ تَذْكُرَ مِنَ الْكَلَامِ مَا يَكُونُ مُضْحِكاً', 'Beware of speech that would cause laughter at you.', 'Nahj al-Balagha, Saying 467', 'wisdom'),
  ('أَعُوذُ بِاللَّهِ مِنْ حُرْمَانِ الصَّلَاةِ', 'I seek refuge in God from being deprived of prayer.', 'Nahj al-Balagha, Saying 475', 'faith'),
  ('مَنْ رَضِيَ بِفِعْلٍ فَهُوَ شَرِيكُ فَاعِلِهِ', 'Whoever is pleased with an action is a partner of the one who performed it.', 'Nahj al-Balagha, Saying 478', 'character')
